/* 博物館「名局選」の文 (2026-11-27). MUSEUM_MATCH_T[lang] = { ui: {…}, <game id>: { t: title, w/b: the two sides, ev: the occasion, d: date, pl: place, lead, c: { <ply>: ミュゼフクの解説 } } }
   c: the key is the number of moves played (0 = the start position, 1 = after the first move …). Edit this file, then node tools/museum-read-split.js
   (→ museum/match-i18n/<lang>.js; each language's file is filled with English for anything it lacks) and bump MATCH_I18N_V in atlas/museum.js. */
window.MUSEUM_MATCH_T = {
  "ja": {
    ui: {"lead":"名勝負を一手ずつ。ミュゼフクの解説を聞きながら、盤の上で名局をたどってみましょう。","all":"すべて","k_chess":"チェス","k_shogi":"将棋","k_go":"囲碁","k_xiangqi":"シャンチー","side_r":"紅","res_r":"紅の勝ち","back":"名局選にもどる","start":"最初","prev":"1手もどる","next":"1手進む","end":"最後","play":"自動で進める","pause":"止める","moves":"棋譜","move":"{n}手目","startpos":"開始局面","nextnote":"次の解説へ（{n}手目）","quiet":"この手の解説はありません。","guide":"ミュゼフク","keys":"← → で1手ずつ","result":"結果","r_event":"対局","r_date":"年","r_place":"場所","side_w":"白","side_b":"黒","side_s":"先手","side_g":"後手","side_B":"黒","side_W":"白","res_w":"白の勝ち","res_b":"黒の勝ち","res_d":"引き分け","res_s":"先手の勝ち","res_g":"後手の勝ち","credit":"棋譜は公に知られている記録です。解説は博物館のミュゼフクによるものです。"},
    "opera": { "t": "オペラ座の一局", "w": "ポール・モーフィー", "b": "ブラウンシュヴァイク公カール2世とイズアール伯爵", "ev": "オペラ座のボックス席での一局（相談指し）", "d": "1858年", "pl": "フランス（パリ）", "lead": "若きアメリカのチャンピオンが、オペラの上演中に貴族2人を相手に指した17手。駒を早く出して、迷わず捨てて、最後は少ない駒で決める。チェスの教科書にいちばんよく載る一局です。",
      c: {
        "0": "1858年のパリ。21歳のアメリカ人ポール・モーフィーは、ヨーロッパの強い選手をつぎつぎと破っていました。この夜、オペラ座のボックス席で、ブラウンシュヴァイク公とイズアール伯爵の2人が相談しながら黒を持ち、モーフィーに挑みます。モーフィーは舞台も見たかったので、早く終わらせたかったともいわれます。駒を早く出すこと、キングを安全にすること――チェスの基本がつまった17手です。",
        "1": "白はキングの前のポーンを2マス進めます。中央のd5・e5をにらみ、ビショップとクイーンの通り道も開けます。",
        "2": "黒も同じくe5。中央で向かい合い、白のポーンがこれ以上進むのを止めます。",
        "3": "ナイトがf3へ出て、e5のポーンをねらいます。駒を出しながら相手に「守らなきゃ」と思わせる、よい手です。",
        "4": "黒はd6でe5を守ります。フィリドール・ディフェンスと呼ばれる形です。しっかりしていますが、f8のビショップの道が少しせまくなります。",
        "5": "白はd4でもう1本のポーンを中央へ出し、e5にぶつけます。黒は取るか守るか決めなければなりません。",
        "6": "黒のビショップがg4へ。f3のナイトにからみ、うしろのd1のクイーンと一直線にしています。ナイトが動くとクイーンが取られるので、ナイトはe5を取りに行けません。",
        "7": "白はポーンでe5を取ります。黒がすぐにd6のポーンで取り返すと、クイーンを交換されたあと、ナイトがe5のポーンを取ってしまいます。だから黒は先にf3のナイトをどかしたいのです。",
        "8": "黒はビショップでナイトを取ります。これでe5を安全に取り返せるようになりました。でも、出したばかりのビショップをナイトと交換したことで、黒の駒の出足がおくれます。",
        "9": "クイーンで取り返します。白のクイーンは早くも盤の中央近くで働きはじめました。黒はまだ駒をほとんど出せていません。",
        "10": "黒はポーンで取り返し、駒の数は互角です。でも、出ている駒の数では白がリードしています。",
        "11": "ビショップがc4へ。f3のクイーンといっしょにf7をねらいます。f7はキングしか守っていない弱いマスで、ここを取られるとメイトです。",
        "12": "黒はナイトをf6に出してf列をふさぎます。これがないと、クイーンでf7を取ってメイトでした。ナイトを出しながら守る、正しい受けです。",
        "13": "クイーンがb3へ向きを変えて、f7とb7の2か所を同時にねらいます。2つのねらいを同時に持つ手は、相手が両方を守れないので強力です。",
        "14": "黒はクイーンをe7へ出してf7を守ります。b7は取られてもいい、という判断です。でもクイーンがf8のビショップの道をふさいでしまいました。",
        "15": "モーフィーはb7のポーンを取らずに、ナイトを出しました。ポーンを取るとクイーンが遠くへ行ってしまいます。駒の数より、駒を早く働かせることを選んだ、モーフィーらしい一手です。",
        "16": "黒はc6でd5やb5のマスをおさえ、クイーンをb6へ出す道も作ります。",
        "17": "ビショップがg5へ。f6のナイトをピンします。ナイトが動くと、うしろのe7のクイーンが取られてしまいます。これで黒の駒はますます動きにくくなりました。",
        "18": "黒はb5でc4のビショップを追い払おうとします。クイーン側に場所を作るねらいもありますが、白の駒が飛びこむすきもできてしまいました。",
        "19": "ナイトを捨ててb5のポーンを取ります！ ビショップが逃げるのではなく、攻めを止めないのがモーフィー流です。キングがまだ真ん中にいる黒には、とてもこわい手です。",
        "20": "黒はナイトを取ります。駒の数では黒がナイト1つ分リードしました。でも黒のキングはまだe8にいて、白の駒はどんどん集まってきます。",
        "21": "ビショップがb5でチェック！ 黒のキングはまだ真ん中に残ったままです。白はポーンを2本取って、黒のキングに直接せまります。",
        "22": "黒はナイトをd7に入れてチェックを防ぎます。でもこのナイトはピンされていて、動けば黒のキングがチェックされます。白はこのd7をねらっていきます。",
        "23": "白はクイーン側にキャスリング。キングが安全になり、同時にルークがd1に来てd7をにらみます。守りと攻めを1手で両方こなす、すばらしい手です。",
        "24": "黒もルークをd8に出してd7を守ります。黒はまだキャスリングできず、h8のルークとf8のビショップはまったく働いていません。",
        "25": "ルークを捨ててd7を取ります！ 2本のルークのうち1本を渡して、黒の守りの駒を減らすねらいです。",
        "26": "黒はルークで取り返します。これでd7のルークもピンされ、動けば黒のキングがb5のビショップにチェックされます。",
        "27": "もう1本のルークもd1へ。d7のルークをもう一度ねらいます。d7をねらう白の駒が、守る黒の駒より多くなりました。",
        "28": "黒のクイーンはe6へ。クイーンの交換を持ちかけ、b3のクイーンをどかそうとします。d7も守ろうという手ですが、もう間に合いません。",
        "29": "ビショップがd7を取ってチェック。黒の守りの駒を1つずつ取り除いていきます。",
        "30": "黒はナイトで取り返します。f6のナイトがいなくなったので、g5のビショップからd8までの斜めの道が通りました。この道が最後に効いてきます。",
        "31": "クイーンをb8に捨ててチェック！ この局でいちばん有名な手です。黒はナイトで取るしかなく、そのナイトがd7からいなくなるので、d列が空きます。",
        "32": "黒はナイトで取ります。これで黒にはd8を守る駒がいなくなりました。",
        "33": "ルークがd8へ。チェックメイト！ g5のビショップがd8を支え、黒のキングは自分の駒にかこまれて逃げられません。白はクイーンもルークもビショップも渡して、最後はルークとビショップの2つだけで決めました。駒を早く出し、キングを安全にし、相手のキングが真ん中にいるうちに一気に攻める――チェスの大切な考え方がつまった、いちばん有名な名局の1つです。"
      } },
    "reti1910": { "t": "レティのメイト", "w": "リヒャルト・レティ", "b": "サヴィエリ・タルタコワー", "ev": "気軽に指した一局（大会ではない）", "d": "1910年", "pl": "オーストリア（ウィーン）", "lead": "のちに大名人になる2人が、ウィーンで気軽に指した11手の一局。白はクイーンを捨て、2つの駒で同時にチェックする「両王手」で一気に決めます。このメイトの形は、白の名前から「レティのメイト」と呼ばれています。",
      c: {
        "0": "1910年のウィーン。白は20歳のリヒャルト・レティ、黒はサヴィエリ・タルタコワーです。2人ともこのあと世界のトップ選手になり、チェスの考え方を新しくしたことでも知られます。これは大会ではなく、少しのお金をかけた気軽な一局でした。短いけれど、「キングを早く安全にすること」の大切さがよくわかる名局です。",
        "1": "白はキングの前のポーンを2マス進めます。盤のまん中をとると、うしろの駒が出やすくなります。ビショップとクイーンの通り道も開きました。",
        "2": "黒はc6。すぐには中央に出ず、次にd5と出てe4のポーンにぶつけるための準備です。これはカロ・カン・ディフェンスと呼ばれる、守りの固い形です。",
        "3": "白はもう1本のポーンもd4へ。中央に2本のポーンが並び、白が場所を広くとりました。黒はこれをくずしに行きます。",
        "4": "予定どおりd5。e4のポーンに「取るよ」とぶつけます。白はこのポーンを守るか、先へ進めるか、交換するかを決めなければなりません。",
        "5": "白はナイトを出してe4を守ります。駒を出しながら守れるので、むだのない手です。",
        "6": "黒はe4のポーンを取ります。中央のポーンを交換して、白の中央を小さくするねらいです。",
        "7": "白はナイトで取り返します。ナイトが盤のまん中に出てきました。まん中のナイトは、たくさんのマスに目が届く強い駒です。",
        "8": "黒はナイトを出して、e4のナイトに向かい合います。ここではビショップをf5へ出す手がよく指されますが、黒はナイトの交換をさそいました。",
        "9": "クイーンが早くもd3へ出て、e4のナイトを守ります。ふつうクイーンは早く出しすぎないものですが、白には考えがありました。このクイーンが、黒のキングの前のd列にいることを覚えておきましょう。",
        "10": "黒はe5。ポーンを1本さし出して、ビショップやクイーンの通り道を開こうとします。中央で戦いを起こす、積極的な手です。",
        "11": "白はe5のポーンを取ります。もらえるものはもらっておく手ですが、これで黒のクイーンが動きやすくなりました。",
        "12": "チェック！ 黒のクイーンがa5から斜めにe1のキングをねらいます。e5のポーンを取り返すねらいも同時にある、一石二鳥の手です。白は駒を間に入れて防ぎます。",
        "13": "白はビショップをd2に置いてチェックを防ぎます。ビショップはクイーンに取られそうですが、クイーンがしっかり守っています。",
        "14": "黒はポーンを取り返して、駒の数は互角にもどりました。しかもこのクイーンは、e列でe4のナイトとそのうしろのキングを一直線に見ています。ナイトが動けばキングがチェックされるので、ナイトは動けません。黒はこのナイトを取れそうに見えます。",
        "15": "白はクイーン側にキャスリング。キングがe列からはなれ、ナイトが自由に動けるようになりました。同時にルークがd1へ来て、d1のルーク、d3のクイーン、黒のキングの横のd8が一列に並びます。ここが白のわなです。",
        "16": "黒はe4のナイトを取りました。駒を1つ得したように見えます。でも黒のキングはまだe8にいて、キャスリングもしていません。白の駒はd列に集まっていて、黒のキングのまわりはがら空きです。この一手が負けにつながる、勝負の分かれ目でした。",
        "17": "クイーンをd8に捨ててチェック！ いちばん強い駒を、ただで取らせます。黒のキングのそばには、このクイーンを取れる駒がキングしかいません。取らせることで、キングをd8という危ないマスへ引っぱり出すのがねらいです。",
        "18": "黒はキングで取るしかありません。ほかにチェックを防ぐ方法はありませんでした。キングはd8に引っぱり出され、そのうしろにはd1のルークが控えています。",
        "19": "ビショップがd2からg5へ動いてチェック。同時に、ビショップのうしろにいたd1のルークの道も開いて、ルークもd列でチェックしています。2つの駒で同時にチェックする「両王手」です。両王手は1つの駒を取っても、間に駒を入れても防げないので、キングが逃げるしかありません。",
        "20": "キングはc7へ逃げます。e8へ逃げても、ルークがd8へ来てメイトでした。どちらへ逃げても、白には決めの一手が用意されています。",
        "21": "ビショップがd8へ。斜めにc7のキングをチェックメイト！ d8のビショップはd1のルークが守っていて、キングは取れません。キングのまわりのb8・c8・b7・c6などは黒の自分の駒でふさがり、d6やd7はルークがにらんでいます。わずか11手、クイーンを捨てて小さな駒2つでしとめました。キャスリングをせずに駒を取りに行くと、キングがどれだけ危なくなるかを教えてくれる一局です。記録によっては、黒はこの1手前で投了したともいわれます。"
      } },
    "immortal": { "t": "不滅の一局", "w": "アドルフ・アンデルセン", "b": "ライオネル・キーゼリツキー", "ev": "1851年ロンドン大会の合間に指した非公式の一局", "d": "1851年", "pl": "イギリス（ロンドン）", "lead": "世界で初めての国際大会が開かれていたロンドンで、休けいの合間に指された一局。白はビショップ、ルーク2本、最後にはクイーンまで捨て、残った小さな駒3つでメイトします。黒はとちゅうで投了し、最後の数手は白が示した手順だともいわれます。",
      c: {
        "0": "1851年のロンドン。大会の合間に、ドイツのアンデルセン（白）とフランスで活やくしたキーゼリツキー（黒）が気軽に指しました。",
        "1": "白はキングの前のポーンを2マス進めます。",
        "2": "黒も同じく。",
        "3": "f4！ ポーンを1本さし出す「キングズ・ギャンビット」。黒のe5のポーンを中央からどかすのがねらいです。",
        "4": "黒はポーンを受け取ります。",
        "5": "ビショップが出て、黒のキングのそばのf7をにらみます。",
        "6": "チェック！ 白のf列のポーンがいなくなったので、h4からe1まで斜めに道が開いていました。",
        "7": "キングが1マスよけます。これで白はもうキャスリングできません。",
        "8": "黒もポーンをさし出します。b5でビショップを引きつけるねらいです。",
        "9": "白はポーンを取ります。",
        "10": "ナイトが出て、e4のポーンをねらいます。",
        "11": "白もナイトを出し、h4のクイーンを追い払います。",
        "12": "クイーンはh6へ下がります。",
        "13": "d3でe4のポーンを守り、c1のビショップの道も開きます。",
        "14": "ナイトがh5へ。次にg3へ跳んでチェックし、h1のルークもねらう作戦です。",
        "15": "白のナイトがh4へ。f5へ進んで黒のクイーンをおどかす準備です。",
        "16": "黒のクイーンはg5へ。h4のナイトをねらいます。",
        "17": "ナイトがf5へ。e4のポーンに守られた、いい場所です。g7のポーンもねらっています。",
        "18": "c6でb5のビショップを追い払おうとします。",
        "19": "白はビショップを助けず、g4でh5のナイトを追います。",
        "20": "ナイトはf6へもどります。",
        "21": "ルークがg1へ。g4のポーンを守ります。b5のビショップは取られてもいい、という大胆な手です。",
        "22": "黒はビショップを取りました。駒の数では黒が大きくリード。",
        "23": "h4のポーンで、黒のクイーンを追い回します。",
        "24": "クイーンはg6へ。",
        "25": "h5でもう一度クイーンを追います。",
        "26": "クイーンはg5へもどるしかありません。クイーンの動ける場所がどんどんせまくなっています。",
        "27": "白のクイーンがf3へ。次にビショップでf4を取ると、黒のクイーンが逃げられなくなるおそれがあります。",
        "28": "黒はナイトをg8へもどし、クイーンの逃げ道f6を作ります。",
        "29": "ビショップでf4のポーンを取り、クイーンを追います。",
        "30": "クイーンはf6へ逃げます。",
        "31": "ナイトが出ます。次はd5へ跳んでクイーンをねらう予定です。",
        "32": "ビショップが出て、g1のルークをねらいます。",
        "33": "ナイトがd5へ。f6のクイーンとc7のマスをねらいます。g1のルークは取られてもかまいません。",
        "34": "クイーンがb2のポーンを取り、a1のルークをねらいます。",
        "35": "ビショップがd6へ！ ルーク2本を両方とも取らせるつもりです。代わりに黒のキングをかこむ網を作ります。",
        "36": "黒はg1のルークを取りました。",
        "37": "e5！ このポーンが、b2のクイーンからg7への斜めの道をふさぎます。もう黒のクイーンはキングを助けに来られません。",
        "38": "黒はチェックしながら、もう1本のルークも取ります。",
        "39": "キングはe2へ。ポーン以外で白に残っているのは、クイーン、ナイト2つ、ビショップ1つだけです。",
        "40": "ナイトをa6へ出してc7のマスを守ります。黒はこのあたりで投了し、ここから先は白が示した手順だともいわれます。",
        "41": "ナイトがg7のポーンを取ってチェック。",
        "42": "キングはd8へ逃げます。",
        "43": "クイーンをf6に捨ててチェック！ 最後の大きな駒まで渡します。",
        "44": "黒はナイトで取るしかありません。",
        "45": "ビショップがe7へ。チェックメイト！ d5のナイトがe7とc7を、g7のナイトがe8を押さえています。白はビショップ1つとナイト2つだけで勝ちました。"
      } },
    "mimiaka": { "t": "耳赤の一局", "w": "本因坊秀策", "b": "井上幻庵因碩", "ev": "大坂での対局（3日がかり）", "d": "1846年", "pl": "日本（大坂）", "lead": "17歳の秀策（四段）が、当時の第一人者のひとり幻庵（八段）に挑んだ一局。中盤、秀策の127手目を見た幻庵の耳が赤くなったという話から「耳赤の一局」と呼ばれます。コミのない時代の、黒2目勝ちです。",
      c: {
        "0": "1846年、大坂。秀策が黒、幻庵が白です。この前の日には幻庵が2子を置かせて打ちましたが、途中で打ち掛けになり、この局は秀策が黒番、置き石なしで打ちました。",
        "1": "黒1は右上の小目（R16）。隅から3つめと4つめの線が交わる点で、隅の地をしっかり取りやすい場所です。",
        "2": "白2は左上の小目（D17）。おたがいに空いている隅から打っていきます。",
        "5": "黒1・3・5と、黒は3つの隅をみな小目で打ちました。秀策が好んだ打ち方で、のちの時代にも手本にされます。",
        "6": "白6は左辺のC14。黒の隅に近づく（カカる）のではなく、辺に構えました。少しめずらしい手です。",
        "7": "黒7（E4）で左下の隅を2つの石で囲みました。これをシマリといい、隅がぐっと堅くなります。",
        "8": "白8（R5）は右下の黒Q3に近づく手。ここから右下で大きな戦いが始まります。",
        "10": "白10（O4）は「大斜（たいしゃ）」と呼ばれる手。黒の石に斜めにかぶせ、変化がとても多い形です。幻庵が得意にしていました。",
        "11": "黒11（Q5）で、黒はむずかしい変化に入りました。大斜は相手がよく研究している形なので、黒は注意して進まなければなりません。",
        "24": "右下では黒と白の石が入りくみ、どちらも相手を切り離そうとしています。白24（N4）で黒の石は外へ出にくくなりました。",
        "25": "黒25（N3）。のちの研究では、ここは別の打ち方のほうがよかったと言われる手です。名人でも迷う、むずかしい場面でした。",
        "28": "白28（M3）、30（L2）と、白はすかさず黒のすきをつきます。黒の石は下辺でせまいところに閉じこめられそうです。",
        "31": "黒31（M4）はだいじな一手。このあとのコウ（取ったり取り返したりの争い）にそなえて、相手が答えなければならない手を用意しておきます。",
        "36": "白36（N2）。コウを始める前に、白はここを先に打っておきました。タイミングのよい手です。",
        "40": "白40（R1）で黒1子を取り、コウが始まりました。取られた側はすぐには取り返せないので、ほかの場所で相手が答える手（コウダテ）を打ちます。",
        "41": "黒41（O5）はコウダテ。少し損をしても、ここはこう打つしかない場面でした。",
        "53": "黒53（R10）は、なかなか思いつかないおもしろい工夫。右辺で白の形を崩しにいきます。",
        "60": "白60（S3）は大きな手。これで白は次の62（M1）も、黒に答えさせながら打てるようになりました。",
        "63": "黒63（O1）で、右下の長い戦いがひと段落。白は下辺に地を作り、黒は右辺に厚い壁を築きました。この時点では白がうまく打ったと見られます。",
        "67": "黒67（L17）。黒は右辺の壁を背にして、上辺に大きく構えます。",
        "72": "白72（P13）はすばらしい手。黒の壁の上に石を置き、黒の模様がふくらむのをおさえます。",
        "74": "ここから100手目あたりまで、幻庵は一手もゆるみなく打ち進めます。黒の攻めをうまくかわし、白の石はつながっていきます。",
        "83": "黒83（H3）。黒は下辺の白の地に入っていきます。白の地を少しでも減らすための手です。",
        "96": "白96（R14）から、右上の黒の隅のまわりで細かい戦いが続きます。白はここでも上手に生きる形を作ります。",
        "107": "黒107（P10）で白1子を取りました。右辺の黒は安心できる形になります。",
        "118": "白118（M19）で黒1子を取り、上辺の白も生きる形になりました。黒の上辺の模様は、思ったほど大きくなりません。",
        "126": "白126（J5）。下辺の白はどっしりと厚くなり、中央へも力をのばしてきました。見ていたプロの多くは、白がよいと考えていたといいます。",
        "127": "これが「耳赤の一手」、黒127（K11）です。中央のこの一石は、上の黒の模様を広げ、下の白の厚みを弱め、右の黒を助け、左へ白がのびるのも防ぐ。4つの方向に同時に効いていると言われます。",
        "128": "127手目が打たれたとき、そばで見ていたお医者さんが、幻庵の耳が赤くなったことに気づきました。碁にはくわしくなかったその人は「動揺したしるし。黒が勝つのでは」と言ったと伝えられています。",
        "131": "黒131（D10）。黒は左辺の白の構えにも手をつけ、盤の全体で白の地を減らしにかかります。",
        "147": "黒147（K10）。127の石が中央で働きはじめ、白の石の間を割って進みます。",
        "160": "白160（H8）。白は中央の石を守りながら、左下の黒にもねらいをつけます。勝負はまだ細かい。",
        "167": "黒167（C2）は正確な手。左下の隅で黒の石が安全になり、白のねらいは消えました。",
        "175": "黒175（G4）で白1子を取りました。下辺の白の地は、はじめに見えたほど大きくありません。",
        "199": "黒199（K7）。中央の戦いが落ち着き、ここからは境い目を決めていく「ヨセ」に入ります。1目、2目をあらそう細かい勝負です。",
        "212": "白212（D19）、216（F19）と、白は上辺の端で黒の石を取ります。ヨセでもおたがいに一歩も引きません。",
        "228": "白228（N12）で中央にコウができました。ここから80手あまり、M13とN13で取ったり取り返したりが続きます。",
        "236": "白236（T8）はコウダテの1つで黒1子を取りました。のちの研究では、ここでコウを終わらせておけば、もっと差がつまったという意見もあります。",
        "275": "黒275（T14）で白2子を取りました。コウの間に、おたがいに盤のあちこちで得をしたり損をしたりしています。",
        "299": "黒299（J16）で白4子をまとめて取りました。上辺は黒がしっかり守りきります。",
        "311": "黒311（M13）でコウを解消しました。長いコウの争いが、ようやく終わります。",
        "325": "325手で終局。数えてみると黒の2目勝ちでした。コミのない時代でも、名人級の幻庵を相手にした17歳の勝利は大きな評判になり、秀策の名は広く知られるようになります。"
      } },
    "evergreen": { "t": "常緑の一局", "w": "アドルフ・アンデルセン", "b": "ジャン・デュフレーヌ", "ev": "気軽に指した一局（大会ではない）", "d": "1852年", "pl": "ドイツ（ベルリンと思われる）", "lead": "「不滅の一局」のアンデルセンが、翌年に指したもう1つの名局。黒がメイトをねらってきたその瞬間、白は静かにルークを1つ動かし、そこからクイーンを捨てて両王手で決めます。いつまでも色あせないという意味で「常緑（エバーグリーン）」と呼ばれます。",
      c: {
        "0": "1852年に雑誌にのった一局です。白はアンデルセン、黒は友人のデュフレーヌ。場所はベルリンと考えられていますが、はっきりした記録はありません。",
        "1": "白はキングの前のポーンを2マス。",
        "2": "黒も同じく。",
        "3": "ナイトがe5のポーンをねらいます。",
        "4": "黒はナイトでe5を守ります。",
        "5": "ビショップが出て、黒のf7をにらみます。",
        "6": "黒もビショップを出します。",
        "7": "b4！ ポーンをさし出す「エヴァンズ・ギャンビット」。取らせているうちに中央を固めるのがねらいです。",
        "8": "黒はポーンを取ります。",
        "9": "c3でビショップを追い、次のd4の準備をします。",
        "10": "ビショップはa5へ下がります。",
        "11": "d4で中央に出ます。",
        "12": "黒はポーンを取ります。",
        "13": "白は取り返さずにキャスリング。ポーンよりも、キングの安全と駒の動きを先にします。",
        "14": "黒のポーンがd3まで進み、白の陣地に入りこみます。",
        "15": "クイーンがb3へ。c4のビショップといっしょにf7をねらいます。",
        "16": "黒はクイーンでf7を守ります。",
        "17": "e5でクイーンを追います。",
        "18": "クイーンはg6へ。",
        "19": "ルークがe1へ。e列に入ってe5のポーンを支えます。",
        "20": "黒はナイトを出して、キャスリングの準備をします。",
        "21": "ビショップがa3へ。斜めにe7のナイトをにらみます。このナイトが動くとf8までの道が通るので、黒はキング側にキャスリングしにくくなりました。",
        "22": "黒はポーンをさし出して、白の駒を引きつけます。",
        "23": "クイーンが取ります。",
        "24": "ルークがb8へ。b列でクイーンを追います。",
        "25": "クイーンはa4へ。",
        "26": "ビショップはb6へ下がります。",
        "27": "ナイトが出ます。白の駒がほとんどそろいました。",
        "28": "黒もビショップを出します。",
        "29": "ナイトがe4へ。次はf6をねらっています。",
        "30": "黒のクイーンがf5へ。e4のナイトをねらいます。",
        "31": "ビショップがd3のポーンを取り、e4のナイトを守ります。",
        "32": "クイーンがh5へ。f3のナイトをねらいます。",
        "33": "ナイトをf6に捨ててチェック！",
        "34": "黒はポーンで取ります。",
        "35": "ポーンで取り返して、e7のナイトをねらいます。e列ではe1のルークもe7をにらんでいます。",
        "36": "ルークがg8へ。g2をねらいます。h5のクイーンでf3を取れば、メイトがせまる形です。",
        "37": "ルークを静かにd1へ！ 自分のキングが危ないのに、守らずにd7のマスへ駒をそろえます。この一手が「常緑」と呼ばれるわけです。",
        "38": "黒はf3のナイトを取ります。次にg2で取ればメイトです。",
        "39": "でも白が先です。ルークでe7のナイトを取ってチェック！",
        "40": "黒はc6のナイトで取り返します。これでa4からd7までの斜めの道が空きました。",
        "41": "クイーンをd7に捨ててチェック！",
        "42": "キングで取るしかありません。",
        "43": "ビショップがf5へ動いてチェック。同時にd1のルークの道も開いて、両王手です。",
        "44": "キングはe8へ。c6へ逃げても、ビショップがd7でメイトでした。",
        "45": "ビショップがd7でチェック。",
        "46": "キングはf8へ。",
        "47": "a3のビショップがe7のナイトを取ってチェックメイト！ d7のビショップがe8を、f6のポーンがe7とg7を押さえています。"
      } },
    "lasker1912": { "t": "キングの大行進", "w": "エドワード・ラスカー", "b": "ジョージ・アラン・トーマス", "ev": "シティ・オブ・ロンドン・チェスクラブでの早指し（気軽な一局）", "d": "1912年", "pl": "イギリス（ロンドン）", "lead": "ロンドンのクラブで指された、持ち時間の短い気軽な一局。白はクイーンを捨てて、黒のキングを自分の陣地のいちばん奥、g8からg1まで追い立てます。序盤の手順は記録によって少しずつちがいますが、10手目の局面は同じです。",
      c: {
        "0": "1912年10月、ロンドンのシティ・オブ・ロンドン・チェスクラブ。白はドイツから来たばかりの若い技術者エドワード・ラスカー、黒はのちにイギリスのチャンピオンになるジョージ・アラン・トーマスです。持ち時間の短い、気軽な早指しでした。この一局は、黒のキングがg8から盤の反対の端のg1まで追い立てられる「キング狩り」として有名です。ラスカーはのちにアメリカへわたり、チェスの本を書いて広く知られました。",
        "1": "白はd4。クイーンの前のポーンから始めます。e5やc5のマスをおさえ、c1のビショップの道も開けます。",
        "2": "黒はe6。まずはしっかりした形をつくり、次にf5やd5へ進む準備をします。",
        "3": "ナイトがf3へ。e5のマスをおさえ、キング側の守りにもなる、いちばん自然な場所です。",
        "4": "黒はf5。e4のマスをおさえる、オランダ・ディフェンスに近い形です。ただ、キングの前のポーンが動くので、黒のキングのまわりは少し弱くなります。",
        "5": "もう1つのナイトもc3へ出ます。次にe4と進んで、f5のポーンにぶつける準備です。",
        "6": "黒もナイトをf6へ。e4のマスをさらにおさえ、キャスリングの準備もします。",
        "7": "ビショップがg5へ。f6のナイトをねらいます。このナイトは黒のキングを守る大事な駒なので、白は早めにどかしたいのです。",
        "8": "黒はビショップをe7へ出してナイトを守ります。キャスリングの準備も進みました。",
        "9": "白はビショップとナイトを交換します。黒のキングを守るナイトがいなくなりました。",
        "10": "黒はビショップで取り返します。このビショップがf6で、黒のキング側を守る役目を引きつぎます。",
        "11": "e4！ f5のポーンにぶつけて、中央を広げます。f列も開いて、白の駒が動きやすくなります。",
        "12": "黒はe4のポーンを取ります。取らないと、白がe5と進んで黒の駒を追い返してしまいます。",
        "13": "ナイトで取り返して、中央へ。このナイトはf6のビショップや、g5・d6のマスをにらんでいます。",
        "14": "黒はb6。ビショップをb7に出して、長い斜めの道からe4のナイトをねらう準備です。",
        "15": "ナイトがe5へ。中央の強いマスで、g4やf7もにらみます。白のナイト2つが、黒のキング側へ近づいてきました。",
        "16": "黒はキャスリング。キングはg8に入りました。でもf列のポーンがいないので、キングのまわりはすき間が多い状態です。",
        "17": "ビショップがd3へ。今はe4の自分のナイトがじゃまをしていますが、その先にはh7のポーンがあります。e4のナイトが動いた瞬間、このビショップがh7をにらむしかけです。",
        "18": "黒のビショップがb7へ。長い斜めの道からe4のナイトをねらい、白の駒を動きにくくします。",
        "19": "クイーンがh5へ。h7のポーンをねらいます。h7は黒のキングしか守っていません。白のクイーン、ビショップ、ナイトがすべて黒のキングのほうを向いています。",
        "20": "黒はクイーンをe7へ。f6のビショップを守り、c5へ出る道も作る手ですが、白のねらいに気づいていません。ここでh6やBxe5など、白のナイトを消す手を考えるべきでした。これが勝負の分かれ目です。",
        "21": "クイーンをh7に捨ててチェック！ いちばん強い駒を、ただで取らせます。ラスカーはここから先、キングを追いかけてメイトにする道筋を見ていました。",
        "22": "黒はキングで取るしかありません。キングがh7に引き出されました。",
        "23": "ナイトがf6のビショップを取ってチェック。同時にe4がどいたので、d3のビショップもh7のキングをにらみ、両王手です。両王手は防げないので、キングは逃げるしかありません。",
        "24": "キングはh6へ。h8へ下がると、もう1つのナイトがg6へ跳んでメイトでした。キングはどんどん前へ押し出されていきます。",
        "25": "もう1つのナイトがe5からg4へ跳んでチェック。g4のナイトはh6のキングをねらい、キングをさらに前へ追い立てます。",
        "26": "キングはg5へ。黒のキングは、自分の陣地をはなれて白の陣地へ近づいていきます。",
        "27": "h4のポーンでチェック！ ポーンもキング狩りに加わります。キングはさらに前へ進むしかありません。",
        "28": "キングはf4へ。もう盤の真ん中をこえ、白の陣地に入りかけています。",
        "29": "g3のポーンでまたチェック。ポーン2本が、キングの後ろへの道をふさいでいます。",
        "30": "キングはf3へ。白の駒のまっただ中です。",
        "31": "ビショップがd3からe2へ下がってチェック。キングはさらに奥へ追いこまれます。",
        "32": "キングはg2へ。白のキングのいるe1まで、もうすぐです。",
        "33": "ルークがh2でチェック。ルークもついに働きはじめました。",
        "34": "キングはとうとうg1へ。スタートのg8から、盤の反対の端の1段目まで来てしまいました。",
        "35": "白のキングがe1からd2へ。キングがどいたことで、a1のルークの前が開き、1段目を通ってg1の黒のキングをチェックします。これでチェックメイト！ クイーン側のキャスリングでもメイトでしたが、ラスカーはキングを動かしました。持ち時間の短い早指しで、クイーンを捨ててから14手かけて、キングを自分の陣地のいちばん奥まで追いこんだ、とても珍しい一局です。"
      } },
    "toketsu": { "t": "吐血の一局", "w": "赤星因徹", "b": "本因坊丈和", "ev": "老中・松平周防守の屋敷での対局（4日がかり）", "d": "1835年", "pl": "日本（江戸）", "lead": "碁打ちの最高位「名人碁所」の座をめぐる争いの中で打たれた一局。井上幻庵因碩は、弟子の赤星因徹を名人・丈和にぶつけました。4日にわたる熱戦の末に因徹は敗れ、盤の前で血を吐いたと伝わります。",
      c: {
        "0": "1835年。黒は赤星因徹（七段）、白は名人の本因坊丈和です。幻庵は「名人が七段に負けるなら、名人の資格はない」と言うつもりで、いちばんの弟子を送りこみました。",
        "1": "黒1は左下の小目（C4）。因徹は落ち着いた手から始めます。",
        "4": "4手目までで、4つの隅に石が1つずつ入りました。白は右下と左上、黒は左下と右上です。",
        "6": "白6（E3）は、早くも黒の左下の隅に近づく手。丈和は最初から積極的です。",
        "10": "白10（P4）で右下の隅を2つの石で固めました（シマリ）。",
        "12": "白12（D6）は、黒の左下の隅に上からかぶせる手。ここから左下で、この局のいちばん大きな戦いが始まります。",
        "13": "黒13（E4）は白の石にぴったりつける手。黒も負けずに戦いを受けて立ちます。",
        "20": "白20（C3）は、黒の隅の下に入る手。黒の隅の地をけずりながら、自分の石を生かしにいきます。",
        "28": "白28（C9）は、左辺へ大きく踏みこんだ手。広げすぎで無理だとも言われる、はげしい丈和らしい一手です。",
        "33": "黒33（C2）。これは井上家がひそかに研究していた、新しい変化だと伝わります。白の中央の石を攻めながら、左辺の白も取りこむねらいです。",
        "36": "白36（F3）。白は左下で黒を外から押さえながら、自分の石をつなごうとします。",
        "43": "黒43（E9）。左辺の白の石は苦しくなりました。ここまでは因徹がうまく打ち、リードを奪ったと見られています。",
        "45": "黒45（D11）。黒は左辺を上へのびて、白の石を左右から分けたまま、自分の石を強くします。",
        "50": "白50（C16）。白は左下をいったん離れ、左上の隅に向かいます。",
        "53": "黒53（G17）。黒は上辺に入り、白の左上を広げさせません。",
        "58": "白58（C14）。白は左上の隅から辺へと石を広げ、左辺の黒の石に近づきます。",
        "60": "白60（G4）で黒2子を取りました。左下の白の石にやっと少しゆとりができます。",
        "62": "白62（J17）。上辺でも白と黒が向かい合い、盤のあちこちに弱い石がある、むずかしい局面です。",
        "66": "白66（B14）。左上の隅のまわりで、白は自分の石を落ち着かせにいきます。",
        "68": "白68（B11）。ここからの白の数手と80手目は、のちに「丈和の妙手」として語り継がれます。あまりにすばらしいので「幽霊が教えた手」と言われたほどです。",
        "70": "白70（E12）。白は左辺の黒にすぐ答えず、先に別の急所に打ちました。あとで効いてくる仕掛けが残っているので、こう打てるのです。",
        "72": "白72（R13）。白は右辺に向かい、黒の右上を広げさせない構えです。",
        "76": "白76（O14）。白は右上と中央をつなぐように石を置き、黒の石を分断する準備をします。",
        "80": "白80（Q10）。石が3つ「く」の字に固まる、ふつうは悪い形とされる手です。ところがこの手が、黒の石を2つに分けて攻める足がかりになりました。「形は悪いが好手」の代表としてよく紹介されます。",
        "83": "黒83（R3）。黒は右下の白の隅に入っていきます。ここから右下で、取ったり取られたりの激しい戦いになります。",
        "91": "黒91（Q4）で白1子を取りました。右下の隅は黒にとって大事な場所です。",
        "98": "白98（M4）。白は下辺の黒の石を外から包むように打ち、黒にかんたんに生きさせません。",
        "106": "白106（S5）で黒1子を取りました。右下の隅は白が守りきり、黒の石は外へ逃げることになります。",
        "113": "黒113（K6）。下辺の黒の石は、中央へ顔を出して生きる道を探します。",
        "120": "白120（N9）。白はにげる黒の前をふさぎます。中央で黒と白のどちらの石が先に弱るかの勝負です。",
        "128": "白128（L11）。白は中央の黒をさらに上からおさえます。黒の石はなかなか安心できません。",
        "138": "白138（K8）で黒1子を取り、中央でコウが始まりました。K8とL8で、取っては取り返す争いが30手ほど続きます。",
        "152": "白152（E11）はコウダテ。コウの間、白は盤のあちこちで黒が答えなければならない手を打っていきます。",
        "170": "白170（P15）。中央のコウがひと段落し、白は右上へ。黒の大きな石がまだ完全には生きていないことをねらいます。",
        "178": "白178（J14）。白は上辺の中ほどに打ちこみ、黒の石を左右に分けにいきます。80手目からねらっていた分断の攻めが、ここで本格的になります。",
        "193": "黒193（J11）で白1子を取りました。黒も必死に石をつなぎ、生きる道を探します。",
        "201": "黒201（R14）で白1子を取り、右辺で新しいコウが始まりました。R14とR15で、また取り合いが続きます。",
        "206": "白206（M13）。コウの間にも、白は中央の黒の石をじわじわと苦しめていきます。",
        "222": "白222（L14）で黒1子を取りました。上辺の黒は2つに分かれたまま、両方を守るのはむずかしくなっています。",
        "230": "白230（C13）。白は左辺でも黒の弱いところを突きます。盤の上の白の石は、もうしっかりつながっています。",
        "237": "黒237（F12）、239（E13）と、黒は左上で白の石を取り返します。それでも、全体の差は縮まりません。",
        "246": "白246（L8）で、因徹は投了しました。石を片づけようとしたとき、因徹は盤の上に血を吐いたと伝わります。体はそれまでに病で弱っていたと思われ、因徹はそれからまもなく亡くなりました。丈和にとっては生涯最高の勝利と言われる一局です。"
      } },
    "deepblue1997": { "t": "ディープ・ブルーの勝利", "w": "ディープ・ブルー（IBMのコンピューター）", "b": "ガルリ・カスパロフ", "ev": "IBMのディープ・ブルーとの再戦（6局勝負）の第6局", "d": "1997年", "pl": "アメリカ（ニューヨーク）", "lead": "世界チャンピオンのカスパロフと、IBMが作ったチェス専用のコンピューター「ディープ・ブルー」の6局勝負。5局を終えて同点で迎えた最後の一局は、わずか19手で決まりました。コンピューターが、何局も指す正式な勝負で世界チャンピオンに初めて勝った日です。",
      c: {
        "0": "1997年5月11日、ニューヨーク。前の年の勝負ではカスパロフが勝っていました。今回は5局を終えて2.5対2.5の同点。白はディープ・ブルーです。",
        "1": "白はキングの前のポーンを2マス。",
        "2": "カスパロフはc6。カロ・カン・ディフェンスです。",
        "3": "白はもう1本のポーンも中央へ。",
        "4": "黒はd5でe4にぶつけます。",
        "5": "ナイトでe4を守ります。",
        "6": "黒はe4のポーンを取ります。",
        "7": "ナイトで取り返します。",
        "8": "黒はナイトをd7へ。次にもう1つのナイトをf6へ出す準備です。",
        "9": "ナイトがg5へ跳びます。f7やe6のマスをねらう、するどい作戦です。",
        "10": "黒はナイトをf6へ。",
        "11": "ビショップがd3へ。黒のキング側をにらみます。",
        "12": "黒はe6で守りを固めます。",
        "13": "もう1つのナイトもf3へ出ます。",
        "14": "黒はh6でg5のナイトを追い払おうとします。でもこの形では、白がナイトを捨てる手が知られていました。カスパロフらしくない選び方だといわれます。",
        "15": "ナイトをe6に捨てます！ ディープ・ブルーは、前もって覚えていた序盤の手順の中からこの手を指したといわれます。",
        "16": "黒はすぐには取らず、クイーンをe7へ。e列で、e6のナイトとうしろの白のキングを一直線にねらいます。",
        "17": "白はキャスリングしてキングを逃がします。",
        "18": "黒はナイトを取りました。駒の数では黒がリードです。",
        "19": "ビショップがg6でチェック。f7のポーンがいないので、斜めの道がキングまで通っています。",
        "20": "キングはd8へ。黒はもうキャスリングできず、キングが盤のまん中近くに残ってしまいました。",
        "21": "もう1つのビショップも出て、黒のキングのまわりのマスをねらいます。",
        "22": "黒はb5。クイーン側に場所を作って、キングの逃げ道とビショップの出口を作ろうとします。",
        "23": "a4でb5のポーンにぶつけます。",
        "24": "黒はビショップをb7へ。",
        "25": "ルークがe1へ。e列でe6のポーン、そしてその先のe7のクイーンをにらみます。",
        "26": "黒のナイトがd5へ。f4のビショップをねらいます。",
        "27": "ビショップはg3へ下がります。",
        "28": "黒のキングはc8へ。少しでも安全な場所へ動きます。",
        "29": "白はb5のポーンを取ります。",
        "30": "黒は取り返します。",
        "31": "クイーンがd3へ。b5のポーンをねらい、f5のマスにも目を向けています。",
        "32": "黒はビショップでb5を守ります。",
        "33": "ビショップをf5へ！ ただで取らせる手です。",
        "34": "黒はポーンで取ります。でもこれで、e列のポーンがいなくなりました。",
        "35": "ルークがe7のクイーンを取ります。白はナイト、ビショップ、ルークを渡しましたが、代わりにクイーンを取りました。",
        "36": "黒はビショップでルークを取り返します。",
        "37": "c4！ ポーンがb5とd5の両方にぶつかり、黒の守りがくずれはじめます。カスパロフはここで投了しました。キングの守りが薄く、白の攻めを止めきれないと考えたのでしょう。コンピューターが世界チャンピオンとの勝負に勝った瞬間です。"
      } },
    "seigen1933": { "t": "三々・星・天元の一局", "w": "呉清源", "b": "本因坊秀哉", "ev": "秀哉名人との記念対局（3か月あまり）", "d": "1933〜1934年", "pl": "日本（東京）", "lead": "19歳の呉清源（五段）が、名人・本因坊秀哉と打った一局。黒の呉清源は1手目に三々、3手目に星、5手目に天元という、それまでの常識をやぶる打ち方で世の中をおどろかせました。対局は何度も打ち掛けをはさんで3か月あまり続き、白の2目勝ちで終わりました。",
      c: {
        "0": "1933年。この年、呉清源は友人の木谷実とともに「新布石」と呼ばれる新しい打ち方を広めていました。名人・秀哉を相手に、それをどう見せるのかに注目が集まります。",
        "1": "黒1は右上の三々（R17）。隅から3つめの線どうしが交わる点で、隅の地を1手で確実に取れます。ただ、外への力は弱いので、当時は最初に打つ手とは考えられていませんでした。",
        "3": "黒3は左下の星（D4）。星は隅から4つめの線が交わる点で、三々とは反対に、外への広がりを重んじる手です。",
        "5": "黒5はなんと盤のまん中、天元（K10）。隅でも辺でもなく、まず中央に打つ。名人を相手に、新しい考え方を正面から示した一手です。",
        "6": "三々・星・天元。3つの黒石は、隅の地、外への広がり、中央の力と、それぞれちがう役目をもっています。白6（Q16）で、白は右上の黒の三々のすぐそばに打ちました。",
        "9": "黒9（P18）。黒は右上の隅を小さくまとめて、しっかり生きます。三々らしい、地にからい打ち方です。",
        "11": "黒11（K4）。天元の真下、下辺のまん中に打ちました。天元の石と協力して、下辺を大きく囲もうとしています。",
        "12": "白12（M3）。白はすぐに下辺へ入り、黒の大きな構えを作らせません。名人はあわてず、ひとつずつ黒の計画をくずしていきます。",
        "13": "黒13（D10）。今度は左辺のまん中。黒の石は盤の中ほどの高い位置にならび、全体で大きく構えています。",
        "14": "白14（E16）で左上の隅を2つの石で固めました（シマリ）。名人は黒の新しい打ち方にまどわされず、落ち着いて隅を守ります。",
        "21": "黒21（G10）。天元と左辺の石の間をつなぎ、中央に黒の勢力が広がります。",
        "28": "白28（D3）。白は左下の黒の星の下に入りこみ、隅の地を取ります。黒は外側を固めるかわりに、隅を白にゆずりました。",
        "30": "白30（Q12）。白は右辺に広げ、右上の黒の三々の外側にもふたをするようにして、黒の力を弱めます。",
        "37": "黒37（P15）で白1子を取りました。右上では白と黒がぶつかり、細かい取り合いが起きています。",
        "40": "白40（O10）。白は右辺から中央へ一歩出て、天元のまわりの黒の勢力に近づきます。",
        "44": "白44（H17）。白は上辺に打ち、黒の石が上へ広がるのをおさえます。",
        "45": "黒45（R7）。黒は右下の白の構えに手をつけます。右辺から右下にかけて、ここからしばらく戦いが続きます。",
        "59": "黒59（R4）。黒は右下の隅にも入りこみ、白の地をへらします。",
        "70": "白70（N6）。白は下辺から中央へ石をのばし、黒の右下の石と中央の石を分けにかかります。",
        "79": "黒79（L9）。天元の石を中心に、黒は中央をしっかり固めます。ここまでは五分五分の勝負と言えそうです。",
        "80": "白80（C6）。白は左下の隅から左辺へ進み、黒の左辺の石をねらいます。",
        "98": "白98（A11）で黒2子を取りました。左辺の端で白がうまく生き、黒の左辺は思ったより小さくなりました。",
        "101": "黒101（S14）。黒は右上にもどって、右辺の白の構えを小さくする手を打ちます。",
        "105": "黒105（K17）。上辺のまん中に打ち、白の上辺の石を攻めにかかります。",
        "117": "黒117（F17）。左上でも黒は白の隅のまわりに入り、上辺全体で戦いが起こります。",
        "124": "白124（K15）。白は上辺の石を中央へ逃がしながら、黒の石の間を割っていきます。",
        "135": "黒135（E9）で白2子を取りました。左辺では黒が少し取り返しました。",
        "138": "白138（N18）。白は上辺で地をかためます。盤全体を見ると、たいへん細かい形勢です。",
        "153": "黒153（K14）。中央の黒の石が、上と下をつなぐ太い道になっています。この黒の厚みを白がどう崩すかが勝負どころです。",
        "159": "黒159（F4）。黒は左下をしっかり守りました。次の白の一手が、この局でいちばん有名な手になります。",
        "160": "白160（H8）。黒の厚みのすき間にとびこむ、するどい一手です。いくつものねらいを同時にもち、ここから白は黒の中央に手をつけていきます。この手は秀哉ではなく弟子が見つけたのでは、といううわさも流れましたが、たしかなことはわかっていません。",
        "161": "黒161（J8）。黒はすぐに受けますが、白のねらいはひとつではありません。",
        "162": "白162（K12）。今度は中央の上側に回って、黒の石のつながりをおびやかします。",
        "172": "白172（F13）。白は中央から左上へ石をつなぎ、黒の中央の厚みは少しずつ地にならなくなっていきます。",
        "178": "白178（N9）。中央の右側でも白が黒の地に入っていきます。",
        "187": "黒187（M6）、189（L7）と、黒は白の石を取って応じます。それでも白は大事なところで先に手をまわしていました。",
        "198": "白198（E12）で黒1子を取りました。左上の白の石もつながり、白は全体で少しリードしています。",
        "203": "黒203（B3）。ここからはヨセ。盤の端の境い目を、1目ずつ決めていきます。",
        "224": "白224（T10）で黒1子を取りました。右辺の端でも、白は1目もゆずりません。",
        "233": "黒233（L13）で白2子を取りました。黒も最後まであきらめずに追い上げます。",
        "252": "252手で終局。白の2目勝ちでした。コミのない時代なので、先に打つ黒が少し有利でしたが、名人は最後まで乱れずに勝ちきりました。それでも、呉清源の三々・星・天元は大きな話題となり、新しい布石の時代を印象づけました。"
      } },
    "century1956": { "t": "世紀の一局", "w": "ドナルド・バーン", "b": "ボビー・フィッシャー", "ev": "第3回ローゼンウォルド杯（ローゼンウォルド記念大会）", "d": "1956年", "pl": "アメリカ（ニューヨーク）", "lead": "13歳のボビー・フィッシャーが、アメリカの強い名人ドナルド・バーンを破った一局。17手目、フィッシャーはクイーンをただで取らせ、その代わりに駒をつぎつぎと取り返して、最後は小さな駒たちで白のキングを追いつめます。フィッシャーはのちに世界チャンピオンになりました。",
      c: {
        "0": "1956年10月17日、ニューヨークの大会。黒を持つのは13歳のフィッシャー、白はアメリカのトップ選手の1人、バーンです。",
        "1": "白はナイトから始めます。",
        "4": "フィッシャーはg6。ビショップを長い斜めの道に置く準備です。",
        "8": "黒はキャスリング。キングを先に安全にします。",
        "10": "黒はd5。中央の取り合いが始まります。",
        "15": "白はe4で、中央にポーンを2本並べました。",
        "17": "ルークがd1へ、d4のポーンを支えます。白はまだキャスリングしていません。",
        "18": "ナイトがb6へ出て、c4のクイーンを追います。",
        "20": "ビショップがg4へ。f3のナイトにからみます。",
        "21": "白もビショップをg5へ。白のキングはまだ真ん中にいます。",
        "22": "ナイトをa4へ！ わざと取られそうな場所へ跳びます。c3のナイトをどかせば、e4のポーンの守りがなくなるからです。",
        "23": "白はナイトを取らず、クイーンをa3へ逃がします。",
        "26": "黒のナイトがe4のポーンを取りました。白の中央がくずれます。",
        "27": "白はビショップでe7のポーンを取り、黒のクイーンとf8のルークを同時にねらいます。",
        "28": "クイーンをb6へ！ f8のルークは取られてもいい、という手です。黒は、白のキングがまだ真ん中にいることを見ています。",
        "29": "白はルークを取らずに、ビショップを出しました。",
        "30": "ナイトがc3のポーンを取り、d1のルークをねらいます。",
        "31": "ビショップがc5へ。b6の黒のクイーンを攻撃します。",
        "32": "ルークがe列でチェック！",
        "33": "キングはf1へ。これで白はもうキャスリングできません。",
        "34": "ビショップをe6へ！ クイーンをただで取らせる、この一局でいちばん有名な手です。そのかわり、黒は白の駒をつぎつぎと取り返す計画を立てていました。",
        "35": "白は黒のクイーンを取りました。",
        "36": "ビショップがc4でチェック。ここから黒の反撃です。",
        "38": "ナイトがe2でチェック。",
        "40": "キングがf1へもどると、ナイトが動いてc4のビショップのチェック（あき王手）。ナイトはついでにd4のポーンを取ります。",
        "44": "ナイトがc3へもどって、またあき王手。今度はd1のルークをねらいます。チェックをくり返しながら駒を取っていくこの動きは「風車」と呼ばれます。",
        "46": "ビショップを取り返します。c3のナイトは、まだd1のルークをねらっています。",
        "50": "ナイトがd1のルークを取りました。これで黒は、渡したクイーン以上の駒を取り返し、はっきりリードしています。",
        "52": "ルークがa2のポーンも取ります。",
        "56": "ルークを交換します。駒が減るほど、多く持っている黒が有利です。",
        "57": "白のクイーンがチェック。",
        "58": "黒はビショップを間に入れます。",
        "64": "b5。黒のポーンが前へ進みはじめます。",
        "68": "キングがg7へ動いて、f8のビショップを自由にします。",
        "70": "ここから黒の駒が白のキングを追いつめます。ビショップでチェック。",
        "72": "ナイトがg3でチェック。",
        "74": "もう1つのビショップでチェック。",
        "76": "ビショップがb3でチェック。",
        "78": "ナイトがe2でチェック。",
        "80": "ナイトがc3でチェック。キングは追い回されます。",
        "82": "ルークがc2へ。チェックメイト！ ルーク、ビショップ2つ、ナイトの4つの駒が力を合わせました。13歳の少年が見せた、たくさんの駒の連携です。"
      } },
    "oshiro1849": { "t": "秀策、はじめての御城碁", "w": "本因坊秀策", "b": "安井算知（九世）", "ev": "御城碁（江戸城で年に一度行われる対局）", "d": "1849年", "pl": "日本（江戸）", "lead": "御城碁は、碁の家元の棋士たちが将軍の城で打つ、年に一度の晴れ舞台でした。20歳の秀策は、この年はじめて出場し、黒番で11目勝ち。ここから御城碁で19戦19勝という、負けなしの記録が始まります。",
      c: {
        "0": "1849年。秀策は前の年に本因坊家の跡継ぎと決まり、この年はじめて御城碁に出ました。御城碁は、実際には前もって別の場所で打っておき、お城では並べ直すことが多かったと言われます。",
        "1": "黒1は右上の小目（R16）。秀策はいつものように、落ち着いた小目から始めます。",
        "4": "白4（C15）は、左上の黒D17に近づく手。序盤から左上で戦いが始まります。",
        "5": "黒5（C11）は、近づいてきた白の石を下からはさむ手（ハサミ）。白に左辺で楽をさせません。",
        "12": "白12（C17）。左上の隅は白が取り、黒は外側に石を持ちました。おたがいに納得できる分かれです。",
        "13": "黒13（J17）。外側の黒の石を生かして、上辺に広げました。",
        "15": "黒15（C5）で、最後に残った左下の隅に入りました。これで4つの隅がすべてうまりました。",
        "16": "白16（E4）はすぐにその黒に近づき、左下でも戦いになります。",
        "19": "黒19（D2）。黒は左下の隅の地をしっかり確保します。秀策らしい、手堅い打ち方です。",
        "23": "黒23（E5）。白の石の間から外へ出て、黒は左下の石を強くします。",
        "29": "黒29（F11）。左辺の黒の石を補強しつつ、中央へも目を向けた手です。",
        "30": "白30（H4）。白は下辺に広げ、左下の黒に圧力をかけつつ自分の陣地を作ります。",
        "31": "黒31（O3）。黒は右下の白の隅に近づきます。",
        "33": "黒33（R3）。黒は白の隅の石にぴったりつけていきます。ここから黒は外側に、白は端の3線に沿って石をのばしていきます。",
        "43": "黒43（Q8）。右辺に、上から下までつながる黒の厚い壁ができました。白は隅と辺の地を取り、黒は外の力を得た形です。",
        "44": "白44（L17）。白は上辺の黒の間に入り、黒の陣地が大きくなりすぎないようにします。",
        "50": "白50（R18）。白は右上の黒の隅の下に入りこみ、隅の地をねらいます。",
        "51": "黒51（P13）。黒は右辺の壁を背にして、右辺から中央にかけて大きな陣地を構えます。",
        "52": "白52（D10）。白は左辺の黒の石の間に打ちこみます。左辺で黒と白の石がからみ合います。",
        "63": "黒63（B10）。黒は左辺の端に石を置き、白の石が根拠を作れないようにします。",
        "65": "黒65（G3）。黒は下辺の白の陣地にも入っていき、白の地を小さくします。",
        "73": "黒73（K17）。上辺の黒の石を固めて、白44の石を苦しくします。",
        "76": "白76（P11）。白は黒の右辺の陣地に飛びこみました。この石が生きるか死ぬかで、地の差が大きく変わります。",
        "77": "黒77（Q11）。黒は自分の壁の側から受けて、白を中央へ追い出します。地を守りながら攻める、秀策らしい落ち着いた応手です。",
        "80": "白80（N10）。白は中央へ逃げ出し、黒の追及をかわそうとします。",
        "85": "黒85（N12）。黒は攻めながら、上辺と右辺の自分の地を広げていきます。攻めることで得をする、うまい運び方です。",
        "91": "黒91（J7）。黒は下辺の白の上に石を置き、中央からも白の陣地をおさえます。",
        "100": "白100（S17）。白は右上の隅に手をつけ、黒の隅の地をへらそうとします。",
        "119": "黒119（R17）。黒は右上の隅をしっかり守り、白の手をしのぎました。",
        "122": "白122（G6）。白は左下の黒の石の外側に回り、中央の黒とのつながりを断とうとします。",
        "131": "黒131（M5）。黒は下辺の中ほどで白の陣地にくさびを打ちます。",
        "140": "白140（B4）。白は左下の黒の隅に手をつけます。ここから左の端で細かい取り合いが始まります。",
        "156": "白156（A8）で黒2子を取りました。左の端の争いは、おたがいに少しずつ取り合って落ち着きます。",
        "158": "白158（L10）。中央に白の石が残り、黒の中央の地をへらそうとします。",
        "162": "白162（O12）で黒1子を取りました。それでも右辺の黒の陣地は大きく残っています。",
        "172": "白172（K18）。ここからはヨセ。上辺の境い目を決めていきます。",
        "186": "白186（T16）。白は右上の端で黒の地をけずります。ヨセでもおたがいに大きいところから打っていきます。",
        "205": "黒205（Q18）。黒は上辺の右側をしっかり閉じて、地を確定させます。",
        "223": "黒223（P10）。右辺の黒の地と、中央へ逃げた白の石との境い目を決める手です。",
        "233": "黒233（Q9）で白1子を取りました。右辺の黒の地は、ほぼ守りきれました。",
        "239": "黒239（A6）で白1子を取り、左の端でコウになりました。最後まで1目ずつの争いが続きます。",
        "260": "白260（T6）で黒1子を取り、右下の端でもコウ。黒は263（T5）で取り返します。",
        "267": "267手で終局。黒の11目勝ちです。大きな冒険はせず、相手の石を攻めながら自然に地をふやしていく、秀策らしい勝ち方でした。これが御城碁19連勝の1局目です。"
      } },
    "shilin": { "t": "『事林広記』順手炮の局", "w": "紅（名は伝わらない）", "b": "黒（名は伝わらない）", "ev": "日用百科『事林広記』の「饒先順手取勝局」", "d": "13世紀", "pl": "中国（宋〜元）", "lead": "宋の終わりから元の初めのころ、陳元靚がまとめた日用百科『事林広記』にのっている棋譜です。今に残るシャンチーの全局の譜として、もっとも古いものの一つとされます。強い側が先手をゆずる「饒先」の手本の局で、わずか9手のうちに黒の馬が紅の車をつかまえます。",
      c: {
        "0": "今から700年以上前の、宋から元にかけての時代の棋譜です。百科事典『事林広記』の遊びの章にのっていて、今に残るシャンチーの全局の記録としては、もっとも古いものの一つとされます。対局者の名は伝わっていません。「饒先」とは、強い人が弱い人に先手をゆずることで、この局は先手をもらった紅がどう負けるかを見せる手本です。紅が下で、先に指します。",
        "1": "紅は右の炮をまん中の筋へ動かしました。「中炮（当頭炮）」とよばれ、黒の将の正面をにらむ、いちばん強い始め方の一つです。700年前から、もうこの形が指されていたことがわかります。",
        "2": "黒も炮をまん中へ動かして、正面から向き合いました。紅と同じ側の炮を動かす形を「順手炮」といいます。炮と炮でにらみ合う、昔から人気の作戦です。",
        "3": "紅は馬をはねて、まん中の兵を守りました。中の兵は黒の炮にねらわれているので、守りが必要です。同時に、馬が前に出る準備にもなります。",
        "4": "黒も馬をはねて、中の卒を守ります。おたがいに同じ形で、まずは足場をかためています。",
        "5": "紅は右の車を一つ横へ動かし、縦にまっすぐ走れる筋に出しました。車は盤でいちばん強い駒なので、早く働かせたいのです。",
        "6": "黒はもう一頭の馬を出しました。車を出すのは後回しにして、まず駒を前に出す作戦です。ただ、車が出おくれると、あとで攻めに使いにくくなります。",
        "7": "紅の車が一気に河をこえ、黒の陣地に入りました。黒の駒をおびやかすねらいですが、ほかの駒がまだ家にいるので、少しあわてた攻めです。左の馬や車を先に出す手もありました。",
        "8": "黒は3筋の卒を一つ進めました。馬の通り道をあけて、あとで前へ出られるようにする手です。紅の車が来るのを、むしろ待っています。",
        "9": "紅の車が卒を取り、その先の黒の馬をにらみました。駒を一つ得して、さらに馬をおびやかす、気持ちのいい手に見えます。ところが、車だけが前に出すぎていて、まわりに味方がいません。ひとりで敵陣に入った車は、ねらわれやすいのです。",
        "10": "黒の馬が前へとび出しました。紅の車からにげながら、紅の陣地へ近づく一石二鳥の手です。この馬が、この局の主役になります。",
        "11": "紅は車を一つ下げて、横から黒の馬をねらいました。車は遠くからでも駒を取れるので、馬は休めません。でもこの手も、自分の駒を育てる手ではありません。",
        "12": "黒の馬はさらに前へ進み、河をこえて紅の陣地に入りました。紅の車からにげるたびに、だんだん紅の帥に近づいていきます。",
        "13": "紅は兵を一つ進めて、自分の馬の通り道をあけました。次に馬を出して、黒の馬と取りかえようという考えです。ただ、この時間で黒はさらに先に進めます。",
        "14": "黒は象を上げて、紅の車をねらいました。守りの駒の象で、相手の車を追いはらう、むだのない手です。紅は車を動かさなければならず、黒はもう一手かせぎました。",
        "15": "紅の車が横へ動いて、また卒を取りました。駒は二つ得しましたが、これが負けにつながる手です。車が帥から遠くはなれ、守りにもどれなくなってしまいました。ここは車を守りにもどすなど、黒の馬にそなえる手が必要でした。",
        "16": "黒の馬がさらに深く入りこみ、紅の車をねらいました。それだけではありません。次に馬が進むと、紅の帥に王手がかかり、同時に紅の隅の車もねらえる位置です。馬一頭で、二つのねらいを同時につくりました。",
        "17": "紅は車で黒の馬を追いかけました。でも、馬はもう止まりません。紅の車がいなくなった帥のまわりは、からっぽです。",
        "18": "黒の馬が飛びこんで王手！しかもこの馬は、紅の隅の車もねらっています。紅が帥を逃がすと、次に車を取られてしまいます。たった9手ですが、ひとりで前に出すぎた車がどうなるか、駒をそろえて戦う大切さを教えてくれる局です。700年前の人たちも、同じ盤で同じことを考えていたのですね。"
      } },
    "qima13": { "t": "弃馬十三着（『橘中秘』）", "w": "紅（名は伝わらない）", "b": "黒（名は伝わらない）", "ev": "『橘中秘』巻上 第1局「順炮横車破直車弃馬」", "d": "1632年（刊行）", "pl": "中国（明）", "lead": "明の朱晋楨が1632年（崇禎5年）に出した棋書『橘中秘』の、いちばん最初にのっている局です。紅はわざと馬をただで取らせ、そのすきに攻めこんで、13手で詰ませます。「弃馬十三着（馬を捨てる13手）」の名で、400年近くたった今も親しまれています。",
      c: {
        "0": "明の時代の終わりごろ、1632年に出版された棋書『橘中秘』の第1局です。『橘中秘』は、のちの『梅花譜』とならんで、シャンチーの二大古典とよばれています。この局は実戦ではなく、作戦を教えるための手本です。対局者の名はありません。紅が下で先に指し、たった13手で勝負がつきます。",
        "1": "紅は右の炮をまん中へ動かしました。黒の将の正面をにらむ「中炮」です。『橘中秘』は、この中炮での攻め方をくわしく研究した本として知られています。",
        "2": "黒も同じ側の炮をまん中へ。「順手炮（順炮）」という、炮どうしが正面からぶつかる形です。どちらも相手の中の兵（卒）をねらっています。",
        "3": "紅は馬をはねて中の兵を守りました。黒の炮にねらわれている兵を守りながら、馬も働き始めます。",
        "4": "黒も馬で中の卒を守ります。ここまでは、おたがいに同じ形です。",
        "5": "紅は右の車を一歩だけ前へ。こうすると次に車が横へ走れるようになります。横に動く車を「横車」といい、すばやく左右へ回れるのが強みです。",
        "6": "黒は車を横へ一つ動かし、縦にまっすぐ進める「直車」にしました。横車と直車、ちがう使い方の車がにらみ合う「順炮横車対直車」の形です。",
        "7": "紅の横車が、盤の左側の筋へ大きく移動しました。この筋は黒の士のすぐわきで、相手の守りのうすいところです。ここから一気に攻めこむ準備です。",
        "8": "黒の直車が河をこえて、紅の陣地に深く入りました。黒も攻め合いで対抗するつもりです。ただ、自分の守りより攻めを急いだ手でもあります。",
        "9": "紅の車が黒の陣地の奥まで進みました。ここは象の通り道（象の目）をふさぐ場所で、黒の象が動けなくなります。士のとなりで、将にもぐっと近づきました。",
        "10": "黒はもう一頭の馬を盤のはしへ出しました。紅の車に横から入られないように、ということも考えた手です。",
        "11": "ここが「弃馬」の一手です。紅はもう一つの車を一歩上げました。そのせいで左はしの馬を守る駒がいなくなり、黒の炮にただで取られてしまいます。でも紅は、馬一頭とひきかえに、二つの車をすばやく攻めに使える時間を手に入れるのです。",
        "12": "黒の炮が紅の馬を取りました。駒を一つ得したように見えます。でも、この炮はもう自分の陣地の守りには使えません。ここでは取らずに士を上げて守りをかためる手が、よかったと言われています。",
        "13": "紅の炮が前へ進みました。まん中にいる黒の炮を「台」にして飛びこえ、その先の黒の馬をねらっています。炮は駒を一つとびこえて取る、ふしぎな駒です。",
        "14": "黒は馬を下げてにげました。ところがこの馬は、まん中の卒を守っていた大事な駒でした。にげたことで、まん中の守りに穴があいてしまいます。ほかの守り方もありましたが、これがいちばん悪い選択でした。",
        "15": "紅の炮がまん中の卒を取って王手！さっき黒の馬がいなくなったので、まん中はがら空きです。ここから紅の攻めが一気に進みます。",
        "16": "黒は士を上げて、将の前をふさぎました。王手を防ぐには、これしかない形です。",
        "17": "紅の二つ目の車も、同じ筋へやってきました。二つの車が縦に重なると、とても強い力になります。次は黒の陣地の奥へ攻めこむぞ、というねらいです。",
        "18": "黒の将は横へにげました。そのままだと、紅の二つの車にまっすぐねらわれてしまうからです。",
        "19": "紅は前の車で黒の士を取って王手！この車は士にすぐ取り返されますが、それも計算のうち。車を一つ捨てて、黒の将のまわりの守りをこわしてしまう、思い切った一手です。",
        "20": "黒は士で紅の車を取りました。駒の数では黒がずっと得をしています。でも、将のまわりはさらにすかすかになりました。",
        "21": "紅の残りの車が将のいる筋へ移って、また王手。黒の将はもう、まわりに守ってくれる駒がほとんどありません。",
        "22": "黒は炮を将の前に入れて、王手を防ぎました。駒を間にはさむ「合い駒」です。",
        "23": "紅の車がその炮を取って、また王手。車がどんどん黒の駒を取りながら、将を追いつめていきます。",
        "24": "黒の将はまん中へもどるしかありません。ほかの場所は、どこも紅の駒にねらわれています。",
        "25": "最後は紅の炮がまん中に並び、二つの炮が縦に重なって王手。前の炮が台になって、後ろの炮が将をねらう「重炮」です。黒の将はどこにもにげられず、紅の勝ちです。馬を一頭捨てただけで、紅はたった13手で勝ちました。駒の数よりも、時間（手番）と駒の働きが大切だということを、この局は400年前から教えてくれています。"
      } }
  },
  "en": {
    ui: {"lead":"Great games, one move at a time. Follow famous games on the board while Musowl explains each move.","all":"All","k_chess":"Chess","k_shogi":"Shogi","k_go":"Go","k_xiangqi":"Xiangqi","side_r":"Red","res_r":"Red won","back":"Back to Great Games","start":"Start","prev":"Back one move","next":"Forward one move","end":"End","play":"Play","pause":"Pause","moves":"Moves","move":"Move {n}","startpos":"Start","nextnote":"Next note (move {n})","quiet":"No note for this move.","guide":"Musowl","keys":"← → step through the moves","result":"Result","r_event":"Game","r_date":"Year","r_place":"Place","side_w":"White","side_b":"Black","side_s":"Sente","side_g":"Gote","side_B":"Black","side_W":"White","res_w":"White won","res_b":"Black won","res_d":"Draw","res_s":"Sente won","res_g":"Gote won","credit":"The moves are the public record of each game. The notes are by the museum’s Musowl."},
    "opera": { "t": "The Opera Game", "w": "Paul Morphy", "b": "Duke Karl II of Brunswick and Count Isouard", "ev": "Played in a box at the Paris Opera (the two allies consulting)", "d": "1858", "pl": "France (Paris)", "lead": "The young American champion against two noblemen, during a performance at the opera: seventeen moves. Bring the pieces out fast, give them up without a second thought, and finish with very few. No game appears in more chess books.",
      c: {
        "0": "Paris, 1858. Twenty-one-year-old American Paul Morphy had been beating Europe's strong players one after another. That evening, in a box at the opera, the Duke of Brunswick and Count Isouard took Black together and played him, talking over each move. It is said Morphy wanted to finish quickly so he could watch the stage. These seventeen moves are full of the basics: bring pieces out fast, keep your king safe.",
        "1": "White pushes the king's pawn two squares. It eyes d5 and e5 in the centre and opens paths for the bishop and queen.",
        "2": "Black also plays e5. The pawns face each other in the centre, and White's pawn cannot go further.",
        "3": "The knight comes to f3 and attacks the e5 pawn. A good move: it develops a piece and makes Black think about defending.",
        "4": "Black guards e5 with d6. This is called the Philidor Defence. It is solid, but it makes the path of the bishop on f8 a little narrow.",
        "5": "White plays d4, bringing another pawn to the centre to hit e5. Black must decide whether to take or defend.",
        "6": "Black's bishop goes to g4. It presses the knight on f3, which stands in line with White's queen on d1. If the knight moves, the queen can be taken, so the knight cannot go after e5.",
        "7": "White takes on e5 with the pawn. If Black took back at once with the d6 pawn, White would trade queens and then the knight would grab the e5 pawn. So Black first wants to get rid of the knight on f3.",
        "8": "Black takes the knight with the bishop. Now e5 can be won back safely. But giving up the bishop that had just come out for the knight leaves Black behind in development.",
        "9": "White takes back with the queen. White's queen is already working near the middle, while Black has hardly brought out any pieces.",
        "10": "Black takes back with a pawn, and the material is even. But White is ahead in pieces that are out and ready.",
        "11": "Bishop to c4. Together with the queen on f3 it aims at f7. Only the king guards f7, so it is a weak square; taking it would be mate.",
        "12": "Black brings the knight to f6 and blocks the f-file. Without this, queen takes f7 would be mate. Defending while developing is the right answer.",
        "13": "The queen swings to b3 and attacks f7 and b7 at the same time. A move with two threats is strong, because the opponent cannot defend both.",
        "14": "Black plays the queen to e7 to guard f7, letting b7 go. But the queen now blocks the bishop on f8.",
        "15": "Morphy does not take the pawn on b7; he develops a knight instead. Taking would send the queen far away. Choosing fast development over a pawn is typical of Morphy.",
        "16": "Black plays c6, covering d5 and b5 and opening a road for the queen to b6.",
        "17": "Bishop to g5 pins the knight on f6. If the knight moves, the queen on e7 behind it can be taken. Black's pieces find it harder and harder to move.",
        "18": "Black plays b5 to chase the bishop from c4. It also gains room on the queen's side, but it opens a gap for White's pieces to jump in.",
        "19": "The knight is given up to take on b5! Instead of retreating the bishop, Morphy keeps attacking. With Black's king still in the middle, this is very dangerous for Black.",
        "20": "Black takes the knight and is a knight ahead. But Black's king is still on e8, and White's pieces keep gathering.",
        "21": "Bishop to b5, check! Black's king is still stuck in the middle. White has two pawns for the knight and comes straight at the king.",
        "22": "Black blocks with the knight on d7. But this knight is pinned: if it moves, the black king is in check. White will now aim at d7.",
        "23": "White castles queenside. The king is safe, and at the same time the rook arrives on d1 to aim at d7. One move does both defence and attack: a superb move.",
        "24": "Black brings the rook to d8 to guard d7. Black still cannot castle, and the rook on h8 and bishop on f8 are doing nothing.",
        "25": "The rook is given up to take on d7! White hands over one rook to remove one of Black's defenders.",
        "26": "Black takes back with the rook. Now this rook on d7 is pinned too: if it moves, the bishop on b5 checks the black king.",
        "27": "The other rook comes to d1 and attacks d7 again. Now more white pieces attack d7 than black pieces defend it.",
        "28": "Black's queen goes to e6, offering a queen trade to push White's queen away from b3, and hoping to help d7. But it is too late.",
        "29": "The bishop takes on d7 with check. White removes Black's defenders one by one.",
        "30": "Black takes back with the knight. With the knight gone from f6, the diagonal from the bishop on g5 to d8 is open. That diagonal will matter at the very end.",
        "31": "The queen is given up on b8, with check! This is the most famous move of the game. Black must take with the knight, and when the knight leaves d7 the d-file opens.",
        "32": "Black takes with the knight. Now no black piece guards d8.",
        "33": "Rook to d8, checkmate! The bishop on g5 supports d8, and the black king is boxed in by its own pieces. White gave away queen, rook and bishop, and finished with just a rook and a bishop. Develop quickly, keep your king safe, and attack while the enemy king is stuck in the middle: this famous game shows all these important ideas."
      } },
    "reti1910": { "t": "Réti's Mate", "w": "Richard Réti", "b": "Savielly Tartakower", "ev": "A casual game (not a tournament)", "d": "1910", "pl": "Austria (Vienna)", "lead": "Two future grandmasters, a casual game in Vienna, eleven moves. White gives up the queen and finishes with a double check: two pieces checking at once. The mating pattern is named after White: Réti's Mate.",
      c: {
        "0": "Vienna, 1910. White is twenty-year-old Richard Réti; Black is Savielly Tartakower. Both went on to become top players and are known for bringing new ideas to chess. This was not a tournament game but a casual one, played for a small stake. It is short, but it shows clearly why you should get your king safe early.",
        "1": "White pushes the king's pawn two squares. Taking the middle of the board makes it easier for the pieces behind to come out. The bishop and queen now have open paths.",
        "2": "Black plays c6. Instead of going to the centre at once, Black gets ready for d5 to hit the pawn on e4. This solid opening is called the Caro-Kann Defence.",
        "3": "White puts the other pawn on d4 too. Two pawns stand side by side in the centre, and White has plenty of space. Black will try to break them up.",
        "4": "As planned, d5. The pawn challenges e4: \"I can take you.\" White must decide whether to guard it, push it or trade it.",
        "5": "White brings out a knight to guard e4. It develops a piece and defends at the same time, so no time is wasted.",
        "6": "Black takes the pawn on e4. By trading centre pawns, Black makes White's centre smaller.",
        "7": "White takes back with the knight, which now stands in the middle of the board. A central knight reaches many squares and is a strong piece.",
        "8": "Black brings out a knight to face the one on e4. Bishop to f5 is often played here, but Black invites a knight trade.",
        "9": "The queen comes out early to d3 to guard the knight on e4. Usually you should not bring the queen out too soon, but White has a plan. Remember that this queen stands on the d-file, in front of Black's king.",
        "10": "Black plays e5, offering a pawn to open lines for the bishop and queen. It is an active move that starts a fight in the centre.",
        "11": "White takes the pawn on e5. White accepts the gift, but this also gives Black's queen more room to move.",
        "12": "Check! Black's queen on a5 aims diagonally at the king on e1. At the same time it plans to win back the e5 pawn: two jobs in one move. White must block.",
        "13": "White blocks the check with the bishop on d2. The queen could take the bishop, but White's queen guards it well.",
        "14": "Black wins the pawn back, so material is equal again. And this queen looks straight down the e-file at the knight on e4 and the king behind it. If the knight moves, the king is in check, so the knight is stuck. Black seems about to win it.",
        "15": "White castles queenside. The king leaves the e-file, so the knight is free again. At the same time a rook comes to d1: the rook on d1, the queen on d3 and the square d8 next to Black's king are all on one line. This is White's trap.",
        "16": "Black takes the knight on e4 and seems to win a piece. But Black's king is still on e8 and has not castled. White's pieces are lined up on the d-file, and the black king is unprotected. This move, which loses the game, is the turning point.",
        "17": "Queen to d8, check! White gives away the strongest piece for nothing. The only black piece that can take it is the king. By letting it be taken, White drags the king onto the dangerous square d8.",
        "18": "Black must take with the king; there is no other way to stop the check. The king is pulled out to d8, with the rook on d1 waiting behind.",
        "19": "The bishop moves from d2 to g5 with check, and at the same time it opens the way for the rook on d1, which checks along the d-file too. Two pieces checking at once is a double check. You cannot stop it by taking one piece or by blocking, so the king must run.",
        "20": "The king runs to c7. If it went to e8 instead, the rook would come to d8 and mate. Wherever the king goes, White has a finishing move ready.",
        "21": "Bishop to d8: checkmate on the diagonal against the king on c7! The bishop is guarded by the rook on d1, so the king cannot take it. Squares like b8, c8, b7 and c6 are blocked by Black's own pieces, and the rook watches d6 and d7. In just eleven moves, White gave up the queen and won with two small pieces. The game shows how dangerous it is to grab material before castling. Some records say Black resigned one move earlier."
      } },
    "immortal": { "t": "The Immortal Game", "w": "Adolf Anderssen", "b": "Lionel Kieseritzky", "ev": "An informal game during a break in the London 1851 tournament", "d": "1851", "pl": "United Kingdom (London)", "lead": "London, during the first international chess tournament: a game played in a break. White gives up a bishop, both rooks and finally the queen, and mates with the three small pieces left. Black is said to have resigned before the end; the last few moves may be the finish White showed.",
      c: {
        "0": "London, 1851. During a break in the tournament, Anderssen of Germany (White) and Kieseritzky, a star of Paris (Black), played a friendly game.",
        "1": "White pushes the king's pawn two squares.",
        "2": "Black does the same.",
        "3": "f4! White offers a pawn: the King's Gambit. The idea is to pull Black's e5 pawn away from the centre.",
        "4": "Black takes the pawn.",
        "5": "The bishop comes out and eyes f7, next to Black's king.",
        "6": "Check! With White's f-pawn gone, there is an open diagonal from h4 to e1.",
        "7": "The king steps aside. Now White can never castle.",
        "8": "Black offers a pawn too, to lure the bishop to b5.",
        "9": "White takes it.",
        "10": "A knight comes out and attacks the e4 pawn.",
        "11": "White brings out a knight and chases the queen from h4.",
        "12": "The queen drops back to h6.",
        "13": "d3 guards e4 and opens the way for the bishop on c1.",
        "14": "Knight to h5. The plan is to jump to g3 with check and hit the rook on h1.",
        "15": "White's knight goes to h4, ready to jump to f5 and bother Black's queen.",
        "16": "Black's queen goes to g5 and attacks the knight on h4.",
        "17": "Knight to f5, a fine square guarded by the e4 pawn. It also eyes the pawn on g7.",
        "18": "c6 tries to chase away the bishop on b5.",
        "19": "White does not save the bishop. g4 chases the knight on h5 instead.",
        "20": "The knight goes back to f6.",
        "21": "Rook to g1, guarding the g4 pawn. White is happy to let the bishop on b5 go. A bold move!",
        "22": "Black takes the bishop and is a whole piece ahead.",
        "23": "The h-pawn starts chasing Black's queen.",
        "24": "The queen goes to g6.",
        "25": "h5 chases the queen again.",
        "26": "The queen can only go back to g5. It has fewer and fewer squares.",
        "27": "White's queen goes to f3. If the bishop then takes on f4, Black's queen may be trapped.",
        "28": "Black brings the knight home to g8, so the queen can escape to f6.",
        "29": "The bishop takes the f4 pawn and hits the queen.",
        "30": "The queen escapes to f6.",
        "31": "A knight comes out, planning to jump to d5 and hit the queen.",
        "32": "The bishop comes out and aims at the rook on g1.",
        "33": "Knight to d5, attacking the queen on f6 and the square c7. White doesn't mind losing the rook on g1.",
        "34": "The queen grabs the b2 pawn and attacks the rook on a1.",
        "35": "Bishop to d6! White lets both rooks go. In return, the pieces build a net around Black's king.",
        "36": "Black takes the rook on g1.",
        "37": "e5! This pawn blocks the diagonal from the queen on b2 to g7. Black's queen can no longer come back to help the king.",
        "38": "Black takes the other rook too, with check.",
        "39": "The king goes to e2. White has only the queen, two knights and one bishop left.",
        "40": "The knight goes to a6 to guard c7. Black is said to have resigned around here; the rest may be the finish White showed.",
        "41": "The knight takes on g7 with check.",
        "42": "The king runs to d8.",
        "43": "The queen is given up on f6, with check! The last big piece goes too.",
        "44": "Black must take with the knight.",
        "45": "Bishop to e7, checkmate! The knight on d5 covers e7 and c7, and the knight on g7 covers e8. White wins with just a bishop and two knights."
      } },
    "mimiaka": { "t": "The Ear-reddening Game", "w": "Honinbo Shusaku", "b": "Inoue Gennan Inseki", "ev": "A game in Osaka (played over three days)", "d": "1846", "pl": "Japan (Osaka)", "lead": "Seventeen-year-old Shusaku (4-dan) took on Gennan (8-dan), one of the strongest players of the day. When Shusaku played move 127, Gennan’s ears are said to have turned red — hence the name. There was no komi then; Black won by 2 points.",
      c: {
        "0": "Osaka, 1846. Shusaku has Black, Gennan White. The day before, they had begun a game with Shusaku taking two handicap stones, but it was stopped; this time Shusaku plays Black with no handicap.",
        "1": "Black 1 is on the 3-4 point at top right (R16). It sits low enough to secure the corner easily.",
        "2": "White 2 takes the 3-4 point at top left (D17). Both sides first share out the empty corners.",
        "5": "With 1, 3 and 5, Black has taken three corners, all on 3-4 points. Shusaku liked this way of starting, and later players studied it closely.",
        "6": "White 6 at C14 on the left side. Instead of approaching Black’s corner, White sets up on the side — a slightly unusual choice.",
        "7": "Black 7 (E4) closes the bottom-left corner with a second stone. This “enclosure” makes the corner very solid.",
        "8": "White 8 (R5) approaches Black’s Q3 corner. A big fight in the bottom right is about to start.",
        "10": "White 10 (O4) is the taisha, a move that caps Black’s stone diagonally from a distance. It leads to a huge number of variations, and it was Gennan’s favourite.",
        "11": "With 11 (Q5), Black enters a difficult line. Gennan knew the taisha well, so Black has to step carefully.",
        "24": "In the bottom right the stones are tangled, each side trying to cut the other apart. After White 24 (N4), Black’s stones find it hard to get out.",
        "25": "Black 25 (N3). Later study suggests Black had a better move here. Even for a master, this was a hard spot.",
        "28": "With 28 (M3) and 30 (L2), White at once strikes at Black’s weakness. Black’s stones risk being shut into a small space along the bottom.",
        "31": "Black 31 (M4) is important. It prepares for the coming ko — the back-and-forth capture fight — by creating places where White will have to answer.",
        "36": "White 36 (N2). Before starting the ko, White plays this forcing move first. Good timing.",
        "40": "White 40 (R1) captures a stone and the ko begins. The side whose stone was taken may not retake at once, so it first plays a threat elsewhere.",
        "41": "Black 41 (O5) is a ko threat. It costs a little, but here Black has no better choice.",
        "53": "Black 53 (R10) is an inventive idea that few would find. It goes after White’s shape on the right side.",
        "60": "White 60 (S3) is a big move. It also lets White play 62 (M1) next while forcing Black to answer.",
        "63": "After Black 63 (O1) the long bottom-right fight calms down. White has territory along the bottom, Black a thick wall on the right. White seems to have done well so far.",
        "67": "Black 67 (L17). With the wall on the right behind it, Black sets up a large framework along the top.",
        "72": "White 72 (P13) is a superb move. Placed just above Black’s wall, it stops Black’s framework from growing.",
        "74": "From here to about move 100, Gennan plays without a single slack move. He dodges Black’s attacks and keeps his stones connected.",
        "83": "Black 83 (H3) goes into White’s area at the bottom, trying to make it smaller.",
        "96": "From White 96 (R14), a sharp little fight runs around Black’s top-right corner. Again White finds a good shape.",
        "107": "Black 107 (P10) captures a white stone. Black’s group on the right is now safe.",
        "118": "White 118 (M19) captures a stone, and White’s group at the top lives too. Black’s top framework ends up smaller than hoped.",
        "126": "White 126 (J5). White is now thick along the bottom and reaching towards the centre. Most professionals watching are said to have thought White was ahead.",
        "127": "This is the famous ear-reddening move, Black 127 (K11). This one stone in the centre is said to work in four directions at once: it widens Black’s area above, weakens White’s thickness below, helps Black’s group on the right and blocks White from spreading to the left.",
        "128": "At this moment a doctor watching the game noticed that Gennan’s ears had turned red. He knew little about go, but he is said to have taken it as a sign that Gennan was shaken — and guessed that Black would win.",
        "131": "Black 131 (D10). Black now also reaches into White’s left side, trimming White’s territory all over the board.",
        "147": "Black 147 (K10). The stone of move 127 starts to pay off as Black pushes between White’s groups in the centre.",
        "160": "White 160 (H8). White defends the centre stones while eyeing Black’s group at bottom left. The game is still close.",
        "167": "Black 167 (C2) is accurate. Black’s stones in the bottom-left corner are now safe, and White’s threat is gone.",
        "175": "Black 175 (G4) captures a white stone. White’s bottom territory is not as large as it first looked.",
        "199": "Black 199 (K7). The centre fight settles, and the game moves into the endgame — fixing the borders between the areas, where every point counts.",
        "212": "With 212 (D19) and 216 (F19), White picks off black stones along the top edge. Neither side gives an inch in the endgame.",
        "228": "White 228 (N12) creates a ko in the centre. For more than 80 moves, the two sides take turns capturing at M13 and N13.",
        "236": "White 236 (T8), played during the ko, captures a stone. Some later analysts think that ending the ko here instead would have made the game even closer.",
        "275": "Black 275 (T14) captures two white stones. During the ko, each side gains here and loses there all over the board.",
        "299": "Black 299 (J16) captures four white stones at once. Black holds the top firmly.",
        "311": "Black 311 (M13) fills the ko. The long ko fight is finally over.",
        "325": "The game ends after 325 moves, and the count shows Black ahead by 2 points. Even without komi, a 17-year-old beating a player of Gennan’s class caused a sensation, and Shusaku’s name became widely known."
      } },
    "evergreen": { "t": "The Evergreen Game", "w": "Adolf Anderssen", "b": "Jean Dufresne", "ev": "A casual game (not a tournament)", "d": "1852", "pl": "Germany (probably Berlin)", "lead": "Anderssen, of the Immortal Game, played this other masterpiece a year later. Just as Black threatens mate, White quietly moves one rook, then gives up the queen and finishes with a double check. It is called \"evergreen\" because it never fades.",
      c: {
        "0": "A game published in a magazine in 1852. White is Anderssen; Black is his friend Dufresne. It is thought to have been played in Berlin, but no record says so for certain.",
        "1": "White pushes the king's pawn two squares.",
        "2": "Black does the same.",
        "3": "The knight attacks the e5 pawn.",
        "4": "Black guards e5 with a knight.",
        "5": "The bishop comes out and eyes Black's f7.",
        "6": "Black brings out a bishop too.",
        "7": "b4! A pawn offer called the Evans Gambit. While Black takes it, White builds up the centre.",
        "8": "Black takes the pawn.",
        "9": "c3 chases the bishop and gets ready for d4.",
        "10": "The bishop drops back to a5.",
        "11": "d4 claims the centre.",
        "12": "Black takes the pawn.",
        "13": "White does not take back but castles. The king's safety and active pieces come before pawns.",
        "14": "Black's pawn pushes on to d3, deep inside White's camp.",
        "15": "Queen to b3. Together with the bishop on c4 it aims at f7.",
        "16": "Black guards f7 with the queen.",
        "17": "e5 chases the queen.",
        "18": "The queen goes to g6.",
        "19": "Rook to e1, onto the e-file to back up the e5 pawn.",
        "20": "Black brings out a knight to get ready to castle.",
        "21": "Bishop to a3, aiming along the diagonal at the knight on e7. If that knight moves, the bishop will reach f8, so castling on the king's side gets hard for Black.",
        "22": "Black offers a pawn to pull White's pieces away.",
        "23": "The queen takes it.",
        "24": "Rook to b8, chasing the queen along the b-file.",
        "25": "The queen goes to a4.",
        "26": "The bishop drops back to b6.",
        "27": "A knight comes out. Almost all of White's pieces are in play.",
        "28": "Black develops the other bishop.",
        "29": "Knight to e4, eyeing f6 next.",
        "30": "Black's queen goes to f5 and attacks the knight on e4.",
        "31": "The bishop takes the pawn on d3 and guards the knight on e4.",
        "32": "Queen to h5, aiming at the knight on f3.",
        "33": "The knight is given up on f6, with check!",
        "34": "Black takes with a pawn.",
        "35": "White takes back with a pawn and hits the knight on e7. On the e-file the rook on e1 is watching e7 too.",
        "36": "Rook to g8, aiming at g2. If the queen on h5 takes on f3, mate is close.",
        "37": "A quiet rook move to d1! White's own king is in danger, but instead of defending, White lines up on d7. This is the move that made the game \"evergreen\".",
        "38": "Black takes the knight on f3. Taking on g2 next would be mate.",
        "39": "But White moves first. The rook takes the knight on e7, with check!",
        "40": "Black takes back with the knight from c6. Now the diagonal from a4 to d7 is open.",
        "41": "The queen is given up on d7, with check!",
        "42": "Black must take with the king.",
        "43": "The bishop moves to f5 with check, and it opens the d-file for the rook on d1 too: a double check.",
        "44": "The king goes to e8. On c6 the bishop would mate on d7.",
        "45": "Bishop to d7, check.",
        "46": "The king goes to f8.",
        "47": "The bishop from a3 takes the knight on e7: checkmate! The bishop on d7 covers e8, and the pawn on f6 covers e7 and g7."
      } },
    "lasker1912": { "t": "The King Hunt", "w": "Edward Lasker", "b": "George Alan Thomas", "ev": "A quick casual game at the City of London Chess Club", "d": "1912", "pl": "United Kingdom (London)", "lead": "A fast, casual game at a London club. White gives up the queen and chases Black's king all the way across the board, from g8 to g1. The opening moves are written in slightly different orders in different records, but the position after move 10 is the same.",
      c: {
        "0": "October 1912, the City of London Chess Club. White is Edward Lasker, a young engineer just arrived from Germany; Black is George Alan Thomas, later British champion. It was a fast, casual game. It is famous as a \"king hunt\": Black's king is chased from g8 all the way to g1 at the other end of the board. Lasker later moved to America and became well known for his chess books.",
        "1": "White starts with d4, the queen's pawn. It covers e5 and c5 and opens the way for the bishop on c1.",
        "2": "Black plays e6, building a solid position and preparing f5 or d5.",
        "3": "Knight to f3. It covers e5 and helps guard the king's side: the most natural square.",
        "4": "Black plays f5, controlling e4, like the Dutch Defence. But moving a pawn in front of the king makes Black's king a little weaker.",
        "5": "The other knight comes to c3, getting ready for e4 to hit the f5 pawn.",
        "6": "Black brings a knight to f6. It controls e4 even more and prepares to castle.",
        "7": "Bishop to g5, aiming at the knight on f6. That knight is an important defender of Black's king, so White wants to remove it early.",
        "8": "Black brings the bishop to e7 to guard the knight, and gets closer to castling.",
        "9": "White trades the bishop for the knight. The knight that guarded Black's king is gone.",
        "10": "Black takes back with the bishop. Now this bishop on f6 takes over the job of guarding the king's side.",
        "11": "e4! White hits the f5 pawn and gains space in the centre. Lines open, and White's pieces can move more freely.",
        "12": "Black takes the pawn on e4. If not, White would push e5 and drive Black's pieces back.",
        "13": "The knight takes back and sits in the centre, eyeing the bishop on f6 and the squares g5 and d6.",
        "14": "Black plays b6, preparing to bring the bishop to b7 to aim down the long diagonal at the knight on e4.",
        "15": "Knight to e5, a strong central square that also eyes g4 and f7. Both white knights are now close to Black's king's side.",
        "16": "Black castles. The king is on g8. But with the f-pawn gone, there are many gaps around the king.",
        "17": "Bishop to d3. For now its own knight on e4 is in the way, but behind it lies the pawn on h7. The moment the knight on e4 moves, this bishop will aim straight at h7.",
        "18": "Black's bishop goes to b7 and aims down the long diagonal at the knight on e4, making White's pieces less free.",
        "19": "Queen to h5, aiming at the pawn on h7, which only Black's king defends. White's queen, bishop and knights all point at Black's king.",
        "20": "Black puts the queen on e7. It guards the bishop on f6 and gets ready to go to c5, but Black misses White's idea. Moves like h6 or taking the knight on e5 were needed. This is the turning point.",
        "21": "The queen is given up on h7, with check! White hands over the strongest piece for nothing. Lasker saw the whole path of chasing the king to mate.",
        "22": "Black must take with the king. The king is pulled out to h7.",
        "23": "The knight takes the bishop on f6 with check. At the same time e4 is empty, so the bishop on d3 also checks the king on h7: a double check. It cannot be blocked, so the king must run.",
        "24": "The king goes to h6. On h8, the other knight would jump to g6 and mate. The king is pushed further and further forward.",
        "25": "The other knight jumps from e5 to g4 with check. It attacks the king on h6 and drives it further forward.",
        "26": "The king goes to g5, leaving its own camp and walking toward White's side.",
        "27": "Check with the h-pawn! Even the pawns join the hunt. The king has to keep moving forward.",
        "28": "The king goes to f4. It has crossed the middle of the board and is entering White's camp.",
        "29": "Check again with the g-pawn. Two pawns now block the way back for the king.",
        "30": "The king goes to f3, right in the middle of White's pieces.",
        "31": "The bishop drops back from d3 to e2 with check. The king is pushed even deeper.",
        "32": "The king goes to g2. White's own king on e1 is not far away.",
        "33": "Rook to h2, check. At last the rook joins in.",
        "34": "The king finally reaches g1. It started on g8 and has walked to the first row at the other end of the board.",
        "35": "White's king steps from e1 to d2. This opens the way for the rook on a1, which now checks the king on g1 along the first row: checkmate! Castling queenside would also have mated, but Lasker moved the king. In a quick game, after giving up the queen, White chased the king for fourteen moves into the deepest corner of White's own camp. A very rare game."
      } },
    "toketsu": { "t": "The Blood-vomiting Game", "w": "Akaboshi Intetsu", "b": "Honinbo Jowa", "ev": "Played at the residence of Lord Matsudaira of Suo (over four days)", "d": "1835", "pl": "Japan (Edo)", "lead": "A game born of the struggle for Meijin Godokoro, the highest post in Japanese go. Inoue Gennan Inseki sent his pupil Akaboshi Intetsu to face the Meijin, Jowa. After four days of hard fighting Intetsu lost, and he is said to have coughed up blood at the board.",
      c: {
        "0": "1835. Black is Akaboshi Intetsu (7-dan), White the Meijin, Honinbo Jowa. Gennan sent his best pupil, planning to argue that a Meijin who lost to a 7-dan did not deserve the title.",
        "1": "Black 1 on the 3-4 point at bottom left (C4). Intetsu starts calmly.",
        "4": "After four moves, each corner has one stone: White at bottom right and top left, Black at bottom left and top right.",
        "6": "White 6 (E3) already approaches Black’s bottom-left corner. Jowa is active from the start.",
        "10": "White 10 (P4) closes the bottom-right corner with a second stone (an enclosure).",
        "12": "White 12 (D6) presses down on Black’s bottom-left corner from above. The biggest fight of the game begins here.",
        "13": "Black 13 (E4) attaches directly to a white stone. Black accepts the fight.",
        "20": "White 20 (C3) slips under Black’s corner. It eats into Black’s corner territory while trying to make White’s own stones live.",
        "28": "White 28 (C9) reaches far along the left side. It is often called an over-extension — a fierce move typical of Jowa.",
        "33": "Black 33 (C2). This is said to be a new line that the Inoue house had studied in secret. It attacks White’s floating stones in the centre while swallowing White’s stones on the left side.",
        "36": "White 36 (F3). White tries to hold Black in from outside at bottom left while connecting its own stones.",
        "43": "Black 43 (E9). White’s stones on the left are in trouble. Up to here Intetsu has played well and is thought to have taken the lead.",
        "45": "Black 45 (D11) extends up the left side, keeping White’s stones apart while strengthening its own.",
        "50": "White 50 (C16). White leaves the bottom left for now and turns to the top-left corner.",
        "53": "Black 53 (G17). Black moves into the top side so that White cannot widen the top left.",
        "58": "White 58 (C14) spreads from the top-left corner along the side, drawing close to Black’s stones on the left.",
        "60": "White 60 (G4) captures two black stones. White’s group at bottom left finally gets a little breathing room.",
        "62": "White 62 (J17). The two sides now face off along the top too. There are weak stones all over the board — a difficult position.",
        "66": "White 66 (B14). Around the top-left corner, White works to settle its own stones.",
        "68": "White 68 (B11). The next few white moves, together with move 80, became famous as Jowa’s brilliant moves. They were so remarkable that people said ghosts had shown them to him.",
        "70": "White 70 (E12). Instead of answering Black on the left side directly, White plays another key point first. Hidden possibilities left behind make this possible.",
        "72": "White 72 (R13). White turns to the right side to stop Black’s top-right area from growing.",
        "76": "White 76 (O14). White links the right side to the centre and prepares to split Black’s stones.",
        "80": "White 80 (Q10) makes an “empty triangle”, a shape usually considered bad. Yet it became the base for splitting Black’s stones in two and attacking them. It is often shown as the classic example of a bad-looking but excellent move.",
        "83": "Black 83 (R3) goes into White’s bottom-right corner. A fierce fight of captures and recaptures follows there.",
        "91": "Black 91 (Q4) captures a white stone. The bottom-right corner matters a lot for Black.",
        "98": "White 98 (M4). White wraps around Black’s stones on the bottom side and does not let them live easily.",
        "106": "White 106 (S5) captures a black stone. White keeps the bottom-right corner, and Black’s stones must run outwards.",
        "113": "Black 113 (K6). Black’s stones on the bottom look for life by heading into the centre.",
        "120": "White 120 (N9) blocks the running black stones. In the centre it is now a race to see whose stones weaken first.",
        "128": "White 128 (L11) presses Black’s centre stones from above as well. Black still cannot relax.",
        "138": "White 138 (K8) captures a stone and a ko starts in the centre. For about 30 moves the two sides capture and recapture at K8 and L8.",
        "152": "White 152 (E11) is a ko threat. During the ko White keeps finding moves elsewhere that Black must answer.",
        "170": "White 170 (P15). The centre ko has settled, and White turns to the top right, aiming at a big black group that is not yet fully alive.",
        "178": "White 178 (J14) jumps into the middle of the top area to split Black’s stones left and right. The splitting attack prepared since move 80 now begins in earnest.",
        "193": "Black 193 (J11) captures a white stone. Black fights hard to connect and find life.",
        "201": "Black 201 (R14) captures a stone and a new ko begins on the right side, with captures going back and forth at R14 and R15.",
        "206": "White 206 (M13). Even during the ko, White slowly tightens the grip on Black’s centre stones.",
        "222": "White 222 (L14) captures a stone. Black’s stones at the top remain split in two, and saving both is getting hard.",
        "230": "White 230 (C13) hits Black’s weak spot on the left side as well. White’s stones are now solidly connected across the board.",
        "237": "With 237 (F12) and 239 (E13), Black captures back on the top left. Even so, the overall gap does not shrink.",
        "246": "After White 246 (L8), Intetsu resigned. As the stones were being cleared, he is said to have coughed up blood onto the board. He had probably been ill for some time, and he died not long afterwards. For Jowa, it is called the greatest win of his career."
      } },
    "deepblue1997": { "t": "Deep Blue Wins", "w": "Deep Blue (IBM computer)", "b": "Garry Kasparov", "ev": "Game 6 of the rematch with IBM's Deep Blue (a six-game match)", "d": "1997", "pl": "United States (New York)", "lead": "World champion Kasparov against Deep Blue, a chess computer built by IBM, in a six-game match. With the score level after five games, the last game was over in only 19 moves. It was the first time a computer beat the world champion in a full match of several games.",
      c: {
        "0": "New York, 11 May 1997. Kasparov had won their match the year before. This time the score is 2½–2½ after five games. Deep Blue has White.",
        "1": "White pushes the king's pawn two squares.",
        "2": "Kasparov plays c6: the Caro-Kann Defence.",
        "3": "White brings the other pawn to the centre.",
        "4": "Black plays d5, hitting e4.",
        "5": "The knight guards e4.",
        "6": "Black takes the pawn on e4.",
        "7": "The knight takes back.",
        "8": "Black puts a knight on d7, getting ready to bring the other knight to f6.",
        "9": "The knight jumps to g5, a sharp plan aiming at f7 and e6.",
        "10": "Black brings the knight to f6.",
        "11": "Bishop to d3, eyeing Black's king's side.",
        "12": "Black strengthens the defence with e6.",
        "13": "The other knight comes out to f3.",
        "14": "Black plays h6 to chase the knight on g5. But in this position a knight sacrifice for White was already known. People say it was an unusual choice for Kasparov.",
        "15": "The knight is given up on e6! Deep Blue is said to have played this move from the opening moves it had stored in advance.",
        "16": "Black doesn't take at once but plays the queen to e7. On the e-file it lines up on the knight on e6 and White's king behind it.",
        "17": "White castles and gets the king away.",
        "18": "Black takes the knight and is ahead in material.",
        "19": "Bishop to g6, check. With the f7 pawn gone, the diagonal reaches the king.",
        "20": "The king goes to d8. Black can no longer castle, and the king is stuck near the middle.",
        "21": "The other bishop comes out and eyes the squares around Black's king.",
        "22": "Black plays b5, making room on the queen's side for the king and the bishop.",
        "23": "a4 hits the pawn on b5.",
        "24": "Black brings the bishop to b7.",
        "25": "Rook to e1. On the e-file it eyes the e6 pawn, and the queen on e7 behind it.",
        "26": "Black's knight goes to d5 and attacks the bishop on f4.",
        "27": "The bishop drops back to g3.",
        "28": "Black's king goes to c8, a little safer.",
        "29": "White takes the pawn on b5.",
        "30": "Black takes back.",
        "31": "Queen to d3, eyeing the b5 pawn and the square f5.",
        "32": "Black guards b5 with the bishop.",
        "33": "Bishop to f5! It can be taken for free.",
        "34": "Black takes with a pawn. But now the pawn on the e-file is gone.",
        "35": "The rook takes the queen on e7. White has given a knight, a bishop and a rook, but has won the queen.",
        "36": "Black takes back the rook with the bishop.",
        "37": "c4! The pawn hits both b5 and d5, and Black's defence starts to fall apart. Kasparov resigned here, probably feeling his king was too open to stop White's attack. A computer had won a match against the world champion."
      } },
    "seigen1933": { "t": "The 3-3, Star Point and Tengen Game", "w": "Go Seigen", "b": "Honinbo Shusai", "ev": "Commemorative game with the Meijin (over three months)", "d": "1933–1934", "pl": "Japan (Tokyo)", "lead": "Nineteen-year-old Go Seigen (5-dan) played the Meijin, Honinbo Shusai. With Black he opened on the 3-3 point, then a star point, then the very centre (tengen) — breaking every rule of the day and astonishing the go world. With many adjournments the game lasted over three months, and White won by 2 points.",
      c: {
        "0": "1933. That year Go Seigen and his friend Kitani Minoru were spreading a new style of opening, the “Shinfuseki”. Everyone wanted to see how he would use it against the Meijin.",
        "1": "Black 1 is on the 3-3 point at top right (R17). It takes the corner in one move, but it has little influence outwards, so in those days nobody thought of it as an opening move.",
        "3": "Black 3 is on the star point at bottom left (D4). Unlike the 3-3 point, the star point cares more about spreading outwards.",
        "5": "Black 5 goes right to the centre of the board — tengen (K10). Not a corner, not a side, but the middle. Against the Meijin, Go Seigen put his new ideas on show head-on.",
        "6": "3-3, star point, tengen: the three black stones each have a different job — corner territory, outward reach and central power. With 6 (Q16), White plays right next to Black’s 3-3 stone.",
        "9": "Black 9 (P18). Black settles the top-right corner compactly and safely — a territory-first style that suits the 3-3 point.",
        "11": "Black 11 (K4) goes to the middle of the bottom side, right below tengen. Working with the tengen stone, Black aims for a big area along the bottom.",
        "12": "White 12 (M3) moves straight into the bottom side so that Black cannot build a big framework. The Meijin stays calm and takes Black’s plans apart one by one.",
        "13": "Black 13 (D10), now in the middle of the left side. Black’s stones stand high on the board, forming a wide framework together.",
        "14": "White 14 (E16) closes the top-left corner with a second stone (an enclosure). The Meijin is not thrown by Black’s new style and calmly secures the corner.",
        "21": "Black 21 (G10) links tengen with the left-side stone, and Black’s influence spreads across the centre.",
        "28": "White 28 (D3) slides under Black’s star-point stone at bottom left and takes the corner. Black lets White have it in exchange for strength outside.",
        "30": "White 30 (Q12) extends along the right side, also putting a lid over Black’s 3-3 corner and weakening its reach.",
        "37": "Black 37 (P15) captures a white stone. In the top right the two sides clash in a close fight.",
        "40": "White 40 (O10) steps out from the right side towards the centre, approaching Black’s influence around tengen.",
        "44": "White 44 (H17) takes a point on the top side to stop Black’s stones spreading upwards.",
        "45": "Black 45 (R7) starts work on White’s lower-right position. A long fight follows from the right side down to the bottom right.",
        "59": "Black 59 (R4) also gets into the bottom-right corner and reduces White’s territory.",
        "70": "White 70 (N6) pushes from the bottom side into the centre, aiming to separate Black’s bottom-right stones from the centre.",
        "79": "Black 79 (L9) firms up the centre around the tengen stone. So far the game looks fairly even.",
        "80": "White 80 (C6) moves from the bottom-left corner up the left side, targeting Black’s stones there.",
        "98": "White 98 (A11) captures two black stones. White lives neatly at the left edge, and Black’s left side turns out smaller than planned.",
        "101": "Black 101 (S14) returns to the top right to shrink White’s position on the right side.",
        "105": "Black 105 (K17) takes the middle of the top side and starts attacking White’s stones there.",
        "117": "Black 117 (F17) also goes into the area around White’s top-left corner, and the whole top side becomes a battlefield.",
        "124": "White 124 (K15) runs its top-side stones towards the centre, cutting between Black’s stones on the way.",
        "135": "Black 135 (E9) captures two white stones. Black wins something back on the left side.",
        "138": "White 138 (N18) secures territory on the top side. Over the whole board the position is very close.",
        "153": "Black 153 (K14). Black’s centre stones form a thick road linking top and bottom. How White can break into that thickness is the key question.",
        "159": "Black 159 (F4) defends the bottom left firmly. White’s next move is the most famous move of this game.",
        "160": "White 160 (H8) leaps into a gap in Black’s thickness — a sharp move with several aims at once, from which White starts breaking into Black’s centre. A rumour spread that a pupil, not Shusai, had found it, but this has never been proved.",
        "161": "Black 161 (J8) answers at once, but White has more than one aim.",
        "162": "White 162 (K12) switches to the upper side of the centre and threatens the links between Black’s stones.",
        "172": "White 172 (F13) links stones from the centre to the top left. Little by little, Black’s central thickness stops turning into territory.",
        "178": "White 178 (N9) gets into Black’s area on the right of the centre too.",
        "187": "With 187 (M6) and 189 (L7), Black captures white stones in reply. Even so, White has already got to the important points first.",
        "198": "White 198 (E12) captures a stone. White’s top-left stones are connected too, and White is slightly ahead overall.",
        "203": "Black 203 (B3). From here it is endgame: the borders along the edges are fixed point by point.",
        "224": "White 224 (T10) captures a stone. Even at the right edge, White does not give away a single point.",
        "233": "Black 233 (L13) captures two white stones. Black keeps chasing to the very end.",
        "252": "The game ends after 252 moves: White wins by 2 points. With no komi Black had the small advantage of moving first, but the Meijin held steady to the end. Even so, Go Seigen’s 3-3, star point and tengen became a sensation and announced a new age of openings."
      } },
    "century1956": { "t": "The Game of the Century", "w": "Donald Byrne", "b": "Bobby Fischer", "ev": "The third Rosenwald Trophy tournament (Rosenwald Memorial)", "d": "1956", "pl": "United States (New York)", "lead": "Thirteen-year-old Bobby Fischer beats Donald Byrne, one of America's strongest masters. On move 17 Fischer lets his queen be taken for nothing, then wins piece after piece back, and at the end his small pieces hunt down White's king. Fischer later became world champion.",
      c: {
        "0": "New York, 17 October 1956, a tournament game. Black is thirteen-year-old Fischer; White is Byrne, one of the top American players.",
        "1": "White starts with a knight.",
        "4": "Fischer plays g6, getting ready to put his bishop on the long diagonal.",
        "8": "Black castles, making the king safe first.",
        "10": "Black plays d5. The fight for the centre begins.",
        "15": "With e4, White has two pawns side by side in the centre.",
        "17": "Rook to d1, supporting the pawn on d4. White has still not castled.",
        "18": "The knight goes to b6 and chases the queen on c4.",
        "20": "Bishop to g4, putting pressure on the knight on f3.",
        "21": "White's bishop goes to g5. White's king is still in the middle.",
        "22": "Knight to a4! It jumps to a square where it can be taken. The idea: if the knight on c3 goes away, the e4 pawn loses its guard.",
        "23": "White doesn't take the knight and moves the queen to a3.",
        "26": "Black's knight takes the e4 pawn. White's centre is breaking down.",
        "27": "White's bishop takes the e7 pawn, attacking Black's queen and the rook on f8 at once.",
        "28": "Queen to b6! Black lets the rook on f8 go. Fischer is counting on White's king still being in the middle.",
        "29": "White doesn't take the rook but develops the bishop.",
        "30": "The knight takes the c3 pawn and attacks the rook on d1.",
        "31": "Bishop to c5, attacking Black's queen on b6.",
        "32": "Check from the rook on the e-file!",
        "33": "The king goes to f1. Now White can never castle.",
        "34": "Bishop to e6! The most famous move of the game: Black lets the queen be taken for nothing. In return, Black has a plan to win back piece after piece.",
        "35": "White takes Black's queen.",
        "36": "Bishop to c4, check. Black's counter-attack begins.",
        "38": "The knight checks from e2.",
        "40": "When the king goes back to f1, the knight moves and uncovers a check from the bishop on c4. On the way, the knight grabs the pawn on d4.",
        "44": "The knight returns to c3, another uncovered check, and now it attacks the rook on d1. Checking again and again while picking up pieces is called a \"windmill\".",
        "46": "Black takes back the bishop. The knight on c3 is still attacking the rook on d1.",
        "50": "The knight takes the rook on d1. Now Black has won back more than the queen and is clearly ahead.",
        "52": "The rook takes the a2 pawn as well.",
        "56": "Black trades rooks. The fewer pieces left, the better for the side with more.",
        "57": "White's queen gives a check.",
        "58": "Black blocks with the bishop.",
        "64": "b5. Black's pawn starts to march.",
        "68": "The king moves to g7 and frees the bishop on f8.",
        "70": "Now Black's pieces hunt the white king. Check with a bishop.",
        "72": "The knight checks on g3.",
        "74": "Check with the other bishop.",
        "76": "Bishop to b3, check.",
        "78": "The knight checks on e2.",
        "80": "The knight checks on c3. The king is chased around.",
        "82": "Rook to c2: checkmate! Rook, two bishops and knight all work together. A thirteen-year-old showed how many pieces can play as one team."
      } },
    "oshiro1849": { "t": "Shusaku’s First Castle Game", "w": "Honinbo Shusaku", "b": "Yasui Sanchi IX", "ev": "Castle Game (the yearly game at Edo Castle)", "d": "1849", "pl": "Japan (Edo)", "lead": "The Castle Games were the yearly showcase where players of the official go houses played at the shogun’s castle. Twenty-year-old Shusaku made his debut this year and won with Black by 11 points — the start of a perfect record of 19 wins in 19 Castle Games.",
      c: {
        "0": "1849. The year before, Shusaku had been named heir to the Honinbo house, and now he plays his first Castle Game. It is said that such games were often played beforehand elsewhere and only replayed at the castle.",
        "1": "Black 1 on the 3-4 point at top right (R16). As usual, Shusaku starts with a calm 3-4 point.",
        "4": "White 4 (C15) approaches Black’s D17 in the top left. A fight starts there early on.",
        "5": "Black 5 (C11) pincers the approaching white stone from below, so White cannot settle easily on the left side.",
        "12": "White 12 (C17). White takes the top-left corner and Black gets stones facing outwards — a fair trade for both.",
        "13": "Black 13 (J17) makes use of the outside stones by extending along the top.",
        "15": "Black 15 (C5) takes the last empty corner, at bottom left. All four corners are now occupied.",
        "16": "White 16 (E4) approaches that black stone at once, and a fight starts at bottom left too.",
        "19": "Black 19 (D2) firmly secures the bottom-left corner — a solid, Shusaku-like choice.",
        "23": "Black 23 (E5) comes out between White’s stones and strengthens Black’s group at bottom left.",
        "29": "Black 29 (F11) reinforces Black’s stones on the left while also looking towards the centre.",
        "30": "White 30 (H4) extends along the bottom, pressing Black’s bottom-left group while building White’s own area.",
        "31": "Black 31 (O3) approaches White’s bottom-right corner.",
        "33": "Black 33 (R3) attaches to White’s corner stone. From here Black builds on the outside while White crawls along the third line at the edge.",
        "43": "Black 43 (Q8). A thick black wall now runs down the right side. White has taken the corner and edge territory; Black has gained outside strength.",
        "44": "White 44 (L17) steps in between Black’s stones on the top side so Black’s area does not grow too large.",
        "50": "White 50 (R18) slips under Black’s top-right corner, aiming at the corner territory.",
        "51": "Black 51 (P13). With the wall behind it, Black frames a large area from the right side towards the centre.",
        "52": "White 52 (D10) jumps in between Black’s stones on the left side. Black and White stones become tangled there.",
        "63": "Black 63 (B10) plays at the left edge so that White’s stones cannot make a base there.",
        "65": "Black 65 (G3) also goes into White’s area on the bottom side, reducing White’s territory.",
        "73": "Black 73 (K17) firms up Black’s top-side stones and puts pressure on White’s stone of move 44.",
        "76": "White 76 (P11) jumps into Black’s right-side area. Whether this stone lives or dies will make a big difference to the score.",
        "77": "Black 77 (Q11) answers from the side of its wall, pushing White out towards the centre — calm defence that also attacks, typical of Shusaku.",
        "80": "White 80 (N10) runs into the centre, trying to escape Black’s pursuit.",
        "85": "Black 85 (N12) keeps attacking while expanding its own territory on the top and right. Gaining profit by attacking — skilful play.",
        "91": "Black 91 (J7) plays above White’s bottom stones, capping White’s area from the centre as well.",
        "100": "White 100 (S17) tries something in the top-right corner to reduce Black’s corner territory.",
        "119": "Black 119 (R17) defends the top-right corner firmly and holds off White’s attempt.",
        "122": "White 122 (G6) goes around the outside of Black’s bottom-left stones, trying to cut them off from Black’s centre.",
        "131": "Black 131 (M5) drives a wedge into White’s area in the middle of the bottom side.",
        "140": "White 140 (B4) tries something in Black’s bottom-left corner. A close capturing fight begins along the left edge.",
        "156": "White 156 (A8) captures two black stones. The fight on the left edge settles after both sides take a little.",
        "158": "White 158 (L10). White still has stones in the centre and tries to reduce Black’s central territory.",
        "162": "White 162 (O12) captures a black stone. Even so, Black’s right-side area remains large.",
        "172": "White 172 (K18). From here it is the endgame, starting with the border on the top side.",
        "186": "White 186 (T16) trims Black’s territory at the top-right edge. In the endgame, both sides play the biggest points first.",
        "205": "Black 205 (Q18) closes off the right part of the top side and fixes the territory there.",
        "223": "Black 223 (P10) fixes the border between Black’s right-side territory and the white stones that escaped into the centre.",
        "233": "Black 233 (Q9) captures a white stone. Black’s right-side territory is now almost entirely safe.",
        "239": "Black 239 (A6) captures a stone and a ko appears at the left edge. The fight over single points goes on to the very end.",
        "260": "White 260 (T6) captures a stone, making another ko at the bottom-right edge. Black takes back at 263 (T5).",
        "267": "The game ends after 267 moves: Black wins by 11 points. No wild adventures — Shusaku simply attacked and let his territory grow naturally, a very Shusaku-like win. It was the first of his 19 straight Castle Game victories."
      } },
    "shilin": { "t": "The Shilin Guangji game", "w": "Red (name not recorded)", "b": "Black (name not recorded)", "ev": "The everyday encyclopedia Shilin Guangji: “a game won after giving the first move, with same-side cannons”", "d": "13th century", "pl": "China (Song–Yuan)", "lead": "This record comes from the Shilin Guangji, an everyday encyclopedia compiled by Chen Yuanjing around the end of the Song dynasty and the start of the Yuan. It is said to be one of the oldest complete xiangqi game records that survive. It is a model game in which the stronger side lets the other move first, and in only nine moves Black’s horse traps Red’s chariot.",
      c: {
        "0": "This record is more than 700 years old, from the time between the Song and Yuan dynasties. It appears in the games chapter of the encyclopedia Shilin Guangji, and it is said to be one of the oldest complete xiangqi games we still have. The players’ names are not recorded. The title says the stronger player “gave the first move” to the weaker one, so this is a lesson showing how Red, who moves first, loses. Red is at the bottom and starts.",
        "1": "Red moves the right cannon to the middle file. This is the Central Cannon, aimed straight at Black’s general, and still one of the strongest openings today. It shows that this opening was already played 700 years ago.",
        "2": "Black answers with a cannon to the middle too, so the two cannons face each other. When both sides move the cannon on the same side, it is called Same Direction Cannons. Cannon against cannon has been a popular fight for centuries.",
        "3": "Red jumps a horse out to guard the middle soldier. That soldier is under attack from Black’s cannon, so it needs a defender. The horse is also getting ready to come forward.",
        "4": "Black does the same and guards the middle soldier with a horse. Both sides are building a firm base first.",
        "5": "Red moves the right chariot one step sideways onto an open file. The chariot is the strongest piece on the board, so it is good to get it working early.",
        "6": "Black brings out the other horse and leaves the chariots at home for now. The plan is to bring pieces forward first. But a chariot that comes out late can be hard to use in the attack later.",
        "7": "Red’s chariot rushes across the river into Black’s camp. It wants to threaten Black’s pieces, but Red’s other pieces are still at home, so this attack is a bit hasty. Bringing out the left horse or chariot first was also possible.",
        "8": "Black pushes the soldier on file 3 one step. This opens a path for the horse so it can jump forward later. Black is almost inviting Red’s chariot to come.",
        "9": "Red’s chariot takes a soldier and now eyes the black horse beyond it. Winning a piece and threatening another looks great. But the chariot has run far ahead with no friends around it. A chariot alone in the enemy camp is easy to chase.",
        "10": "Black’s horse jumps forward. It escapes from the chariot and moves toward Red’s camp at the same time — two jobs with one move. This horse will be the star of the game.",
        "11": "Red pulls the chariot back one step to attack the horse from the side. A chariot can capture from far away, so the horse cannot rest. Still, this move does not help Red develop any other piece.",
        "12": "Black’s horse goes further forward and crosses the river into Red’s camp. Each time it runs from the chariot, it gets closer to Red’s general.",
        "13": "Red pushes a soldier to open a path for Red’s own horse. The idea is to bring that horse out and trade it for Black’s horse. But this gives Black time to go even further.",
        "14": "Black lifts an elephant and attacks Red’s chariot. Using a defending piece to chase the enemy chariot away is very efficient. Red must move the chariot again, and Black gains another move.",
        "15": "Red’s chariot slides across and takes another soldier. Red is now two soldiers up, but this is the move that loses. The chariot is now far from its general and cannot come back to defend. Red needed a move to guard against the horse, such as bringing the chariot home.",
        "16": "Black’s horse jumps deeper and attacks Red’s chariot. And there is more: if the horse jumps once again, it will check Red’s general and at the same time attack the chariot in Red’s corner. One horse has made two threats at once.",
        "17": "Red chases the horse with the chariot. But the horse can no longer be stopped. Around Red’s general there is nobody left to help.",
        "18": "The horse leaps in with check! It also attacks the chariot in Red’s corner, so when the general steps away, the chariot will be lost. Only nine moves, but the game teaches what happens to a chariot that runs ahead alone, and why pieces should fight together. Players 700 years ago were thinking about the same things on the same board."
      } },
    "qima13": { "t": "The Thirteen-Move Horse Sacrifice (Juzhongmi)", "w": "Red (name not recorded)", "b": "Black (name not recorded)", "ev": "Juzhongmi, Volume 1, Game 1", "d": "1632 (published)", "pl": "China (Ming)", "lead": "This is the very first game in the Juzhongmi (“The Secret in the Tangerine”), a xiangqi book published by Zhu Jinzhen of the Ming dynasty in 1632. Red lets Black capture a horse for free, rushes in while Black is busy, and mates in thirteen moves. Under the name “The Thirteen-Move Horse Sacrifice” it is still loved almost 400 years later.",
      c: {
        "0": "This is Game 1 of the Juzhongmi, a book printed in 1632, near the end of the Ming dynasty. Together with the later Plum Blossom Manual, it is called one of the two great classics of xiangqi. This is not a real match but a model game written to teach a plan, so there are no players’ names. Red is at the bottom and moves first, and the game is over in just thirteen moves.",
        "1": "Red moves the right cannon to the middle. This is the Central Cannon, staring straight at Black’s general. The Juzhongmi is famous for studying how to attack with this opening.",
        "2": "Black also moves the cannon on the same side to the middle. This is Same Direction Cannons, where the cannons clash head-on. Each side is aiming at the other’s middle soldier.",
        "3": "Red jumps a horse out to guard the middle soldier. It protects the soldier the black cannon is aiming at, and the horse starts to work too.",
        "4": "Black also guards the middle soldier with a horse. So far both sides have the same shape.",
        "5": "Red moves the right chariot just one step forward. Now it can run sideways next move. A chariot that moves sideways like this is called a “horizontal chariot”, and it can quickly swing to either wing.",
        "6": "Black moves the chariot one step sideways so it can drive straight up the board. This is a “straight chariot”. Horizontal chariot against straight chariot — two different ways of using the chariot face off.",
        "7": "Red’s horizontal chariot swings over to a file on the left. That file runs right beside Black’s advisor, where Black’s defence is thin. Red is getting ready to break in from here.",
        "8": "Black’s straight chariot crosses the river and goes deep into Red’s camp. Black wants to fight back with an attack of its own. But it is a move that hurries to attack before defending.",
        "9": "Red’s chariot drives deep into Black’s camp. It stands on the elephant’s “eye”, the point an elephant must pass through, so Black’s elephant cannot move. Right next to the advisor, it is now very close to the general.",
        "10": "Black brings the other horse out to the edge. Part of the idea is to stop Red’s chariot from sliding in sideways.",
        "11": "Here is the horse sacrifice! Red lifts the other chariot one step. This leaves the horse in the left corner with no defender, so Black’s cannon can take it for free. But in return for one horse, Red gains time to bring both chariots into the attack quickly.",
        "12": "Black’s cannon takes Red’s horse. It looks like Black has won a piece. But this cannon is now far from home and cannot help defend. It is said that strengthening the defence by moving up an advisor, instead of capturing, was better here.",
        "13": "Red’s cannon moves forward. Using Black’s middle cannon as a “screen” to jump over, it now aims at Black’s horse beyond it. The cannon is a strange piece that captures by jumping over exactly one piece.",
        "14": "Black retreats the horse to escape. But that horse was the important piece guarding the middle soldier. By running away, it leaves a hole in Black’s centre. Black had other defences, but this was the worst choice.",
        "15": "Red’s cannon takes the middle soldier — check! With Black’s horse gone, the centre was wide open. From here Red’s attack rushes forward.",
        "16": "Black moves an advisor up to block in front of the general. This is the only good way to stop the check.",
        "17": "Red’s second chariot arrives on the same file. Two chariots lined up on one file are extremely strong. The plan is to break into the back of Black’s camp.",
        "18": "Black’s general steps to the side. Otherwise it would be stared at straight down the file by Red’s two chariots.",
        "19": "Red’s front chariot takes Black’s advisor — check! This chariot will be captured by the other advisor at once, but that is part of the plan. Red throws away a chariot to smash the guards around Black’s general. What a bold move!",
        "20": "Black takes the chariot with the advisor. In pieces, Black is now far ahead. But the general’s house is even emptier than before.",
        "21": "Red’s last chariot moves to the general’s file — check again. Black’s general has almost no pieces left to protect it.",
        "22": "Black puts a cannon in front of the general to block the check. Putting a piece in between like this is called interposing.",
        "23": "Red’s chariot takes that cannon — check again. The chariot keeps capturing Black’s pieces while chasing the general into a corner.",
        "24": "Black’s general can only go back to the middle. Every other point is covered by Red’s pieces.",
        "25": "Finally Red’s cannon lines up in the middle, two cannons on one file — check. The front cannon is the screen and the back cannon hits the general: a “double cannon” mate. Black’s general has nowhere to go, and Red wins. By giving up just one horse, Red won in thirteen moves. For 400 years this game has been teaching that time and active pieces can matter more than the number of pieces."
      } }
  },
  "zh": {
    ui: {"lead":"名局一步一步看。一边听 Musowl 讲解，一边在棋盘上重温经典对局吧。","all":"全部","k_chess":"国际象棋","k_shogi":"将棋","k_go":"围棋","k_xiangqi":"中国象棋","side_r":"红方","res_r":"红方胜","back":"返回名局选","start":"开头","prev":"后退一步","next":"前进一步","end":"最后","play":"自动播放","pause":"暂停","moves":"棋谱","move":"第{n}步","startpos":"开始局面","nextnote":"下一条讲解（第{n}步）","quiet":"这一步没有讲解。","guide":"Musowl","keys":"← → 一步一步看","result":"结果","r_event":"对局","r_date":"年份","r_place":"地点","side_w":"白方","side_b":"黑方","side_s":"先手","side_g":"后手","side_B":"黑方","side_W":"白方","res_w":"白方胜","res_b":"黑方胜","res_d":"和棋","res_s":"先手胜","res_g":"后手胜","credit":"棋谱是公开的对局记录。讲解由博物馆的 Musowl 撰写。"},
    "opera": { "t": "歌剧院之局", "w": "保罗·莫菲", "b": "不伦瑞克公爵卡尔二世与伊苏阿尔伯爵", "ev": "在歌剧院包厢里下的一盘棋（两人商量着下）", "d": "1858年", "pl": "法国（巴黎）", "lead": "年轻的美国冠军在歌剧演出时，对阵两位贵族，只下了17个回合。快速出子，毫不犹豫地弃子，最后只用很少的棋子取胜。这是国际象棋书里最常出现的一盘棋。",
      c: {
        "0": "1858年的巴黎。21岁的美国人保罗·莫菲接连击败了欧洲的强手。那天晚上，在歌剧院的包厢里，布伦瑞克公爵和伊苏阿尔伯爵两人一边商量一边执黑，向莫菲挑战。据说莫菲还想看舞台上的演出，所以想早点结束。这17个回合里装满了国际象棋的基本道理：快速出子，让王安全。",
        "1": "白方把王前的兵走两格。它盯住中央的d5和e5，也为象和后打开了路。",
        "2": "黑方也走e5。两个兵在中央面对面，白兵不能再往前走了。",
        "3": "马出到f3，攻击e5的兵。一边出子，一边让对方不得不防守，是好棋。",
        "4": "黑方走d6保护e5。这叫菲利多尔防御。很稳，但f8象的路变窄了一点。",
        "5": "白方走d4，又一个兵来到中央，冲击e5。黑方必须决定是吃还是守。",
        "6": "黑象到g4，牵制f3的马。马后面是d1的白后，马一走后就会被吃，所以马不能去吃e5。",
        "7": "白方用兵吃e5。如果黑方马上用d6兵吃回，白方会换后，然后马就能吃掉e5的兵。所以黑方想先除掉f3的马。",
        "8": "黑方用象吃马，这样就能安全地吃回e5了。但刚出动的象换掉了马，黑方的出子落后了。",
        "9": "白方用后吃回。白后已经在中央附近活跃起来，而黑方几乎还没有出子。",
        "10": "黑方用兵吃回，子力相等。但从出动的棋子数来看，白方领先。",
        "11": "象到c4，和f3的后一起瞄准f7。f7只有王在保护，是弱点；被吃掉就是将死。",
        "12": "黑方把马出到f6，挡住f线。没有这一步，后吃f7就是将死。一边出子一边防守，是正确的应对。",
        "13": "后转到b3，同时攻击f7和b7。同时有两个威胁的棋很强，因为对方没法两边都守住。",
        "14": "黑方把后走到e7保护f7，放弃了b7。但这样后挡住了f8象的路。",
        "15": "莫菲没有吃b7的兵，而是出马。吃兵会让后跑得太远。选择快速出子而不是多吃一个兵，正是莫菲的风格。",
        "16": "黑方走c6，控制d5和b5，也给后打开了去b6的路。",
        "17": "象到g5，牵制f6的马。马一走，后面e7的后就会被吃。黑方的棋子越来越难动了。",
        "18": "黑方走b5，想赶走c4的象。这也在后翼抢到了空间，但同时给白方的棋子留下了冲进来的空隙。",
        "19": "弃马吃b5的兵！莫菲没有让象逃走，而是继续进攻。黑王还在中间，这对黑方非常危险。",
        "20": "黑方吃掉马，多了一个马。但黑王还在e8，白方的棋子不断聚集过来。",
        "21": "象到b5将军！黑王还困在中间。白方用一个马换来两个兵，直接逼近黑王。",
        "22": "黑方用马在d7垫将。但这个马被牵制了，一动黑王就会被将军。白方接下来就瞄准d7。",
        "23": "白方长易位。王安全了，同时车来到d1瞄准d7。一步棋同时完成防守和进攻，非常出色。",
        "24": "黑方把车出到d8保护d7。黑方还不能易位，h8的车和f8的象完全没有发挥作用。",
        "25": "弃车吃d7！白方送出一个车，除掉黑方的一个防守棋子。",
        "26": "黑方用车吃回。现在d7的车也被牵制了，一动b5的象就会将军黑王。",
        "27": "另一个车也来到d1，再次攻击d7。现在攻击d7的白子比防守的黑子还多。",
        "28": "黑后到e6，提议换后，想把b3的白后赶走，也想帮忙保护d7。但已经来不及了。",
        "29": "象吃d7并将军。白方把黑方的防守棋子一个一个地除掉。",
        "30": "黑方用马吃回。f6的马离开了，从g5的象到d8的斜线通了。这条斜线在最后会起作用。",
        "31": "后弃在b8并将军！这是这盘棋最有名的一步。黑方只能用马吃，马一离开d7，d线就打开了。",
        "32": "黑方用马吃。现在已经没有黑子保护d8了。",
        "33": "车到d8，将死！g5的象支援d8，黑王被自己的棋子围住，无处可逃。白方送出了后、车和象，最后只用一个车和一个象结束了对局。快速出子、让王安全、趁对方的王还在中间一口气进攻——这盘最有名的名局包含了所有这些重要的道理。"
      } },
    "reti1910": { "t": "列蒂杀法", "w": "理查德·列蒂", "b": "萨维利·塔尔塔科维尔", "ev": "一盘随意下的棋（不是比赛）", "d": "1910年", "pl": "奥地利（维也纳）", "lead": "两位后来的大师在维也纳随意下的一盘棋，只有11个回合。白方弃掉后，用两个棋子同时将军的\"双将\"一举取胜。这种杀法以白方的名字命名，叫做\"列蒂杀法\"。",
      c: {
        "0": "1910年的维也纳。白方是20岁的理查德·列蒂，黑方是萨维利·塔尔塔科维尔。两人后来都成了世界顶尖棋手，也以给国际象棋带来新思路而闻名。这不是比赛，而是押了一点小钱的随意对局。虽然很短，却能清楚看出\"早点让王安全\"有多重要。",
        "1": "白方把王前的兵走两格。占住中央，后面的棋子就容易出动。象和后的路也打开了。",
        "2": "黑方走c6。不马上进中央，而是为下一步d5冲击e4的兵做准备。这种稳固的开局叫卡罗-康防御。",
        "3": "白方把另一个兵也走到d4。两个兵并排站在中央，白方占了很大空间。黑方要想办法拆掉它们。",
        "4": "按计划走d5，向e4的兵发出\"我能吃你\"的挑战。白方要决定是保护、前进还是交换。",
        "5": "白方出马保护e4。一边出子一边防守，一点也不浪费。",
        "6": "黑方吃掉e4的兵。交换中心兵，让白方的中心变小。",
        "7": "白方用马吃回来，马站到了棋盘中央。中央的马能照顾很多格子，是很强的棋子。",
        "8": "黑方出马，和e4的马面对面。这里常见的是象出到f5，但黑方选择邀请换马。",
        "9": "白后早早来到d3，保护e4的马。一般来说后不要出得太早，但白方另有打算。请记住，这个后站在d线上，正对着黑王前方。",
        "10": "黑方走e5，送出一个兵，为象和后打开通路。这是在中央挑起战斗的积极一步。",
        "11": "白方吃掉e5的兵。白方收下了礼物，但这也让黑后更容易活动。",
        "12": "将军！a5的黑后沿斜线瞄准e1的王，同时还打算吃回e5的兵，一步两用。白方必须挡住。",
        "13": "白方把象放在d2挡住将军。后可以吃这个象，但白后好好地保护着它。",
        "14": "黑方吃回了兵，子力又相等了。而且这个后沿e线正对着e4的马和后面的王。马一走开王就会被将军，所以马动不了。看起来黑方马上就能吃掉它。",
        "15": "白方长易位。王离开了e线，马又能自由行动了。同时车来到d1：d1的车、d3的后和黑王旁边的d8排成一条线。这就是白方的陷阱。",
        "16": "黑方吃掉e4的马，好像多得了一个子。但黑王还在e8，也没有易位。白方的棋子都排在d线上，黑王身边空荡荡的。这一步导致了失败，是胜负的分水岭。",
        "17": "后走到d8将军！把最强的棋子白白送掉。能吃它的黑子只有王。让对方吃，就是为了把王拉到d8这个危险的格子上。",
        "18": "黑方只能用王吃，没有别的办法挡将。王被拉到了d8，后面还有d1的车在等着。",
        "19": "象从d2走到g5将军，同时让开了后面d1车的路，车也沿d线将军。两个棋子同时将军叫\"双将\"。双将既不能靠吃掉一个子解除，也不能垫子挡住，王只能逃。",
        "20": "王逃到c7。如果逃到e8，车走到d8就是将死。不管王逃到哪里，白方都准备好了致命一击。",
        "21": "象走到d8，沿斜线将死c7的王！象由d1的车保护，王吃不了它。b8、c8、b7、c6等格子被黑方自己的棋子堵住，d6和d7被车控制。只用11个回合，白方弃后，用两个小子取胜。这盘棋告诉我们：不易位就去吃子，王会有多危险。也有记录说黑方在前一步就认输了。"
      } },
    "immortal": { "t": "不朽之局", "w": "阿道夫·安德森", "b": "莱昂内尔·基塞里茨基", "ev": "1851年伦敦大赛期间下的一盘非正式对局", "d": "1851年", "pl": "英国（伦敦）", "lead": "世界上第一次国际比赛在伦敦举行时，两人在休息时下了这盘棋。白方先后弃掉象、两个车，最后连后也弃掉，只用剩下的三个小子将死对方。据说黑方中途就认输了，最后几步可能是白方演示的走法。",
      c: {
        "0": "1851年的伦敦。比赛休息时，德国的安德森（白）和在巴黎很有名的基塞里茨基（黑）随意下了一盘。",
        "1": "白方把王前的兵走两格。",
        "2": "黑方也一样。",
        "3": "f4！白方送出一个兵，这叫\"王翼弃兵\"。目的是把黑方e5的兵引离中心。",
        "4": "黑方吃下这个兵。",
        "5": "象出动，瞄准黑王旁边的f7。",
        "6": "将军！白方f线的兵不在了，从h4到e1的斜线是空的。",
        "7": "王往旁边让一步。这样白方就再也不能王车易位了。",
        "8": "黑方也送出一个兵，想把象引到b5。",
        "9": "白方吃掉。",
        "10": "马出动，攻击e4的兵。",
        "11": "白方也出马，赶走h4的后。",
        "12": "后退到h6。",
        "13": "d3保护e4，也给c1的象让出了路。",
        "14": "马到h5。打算跳到g3将军，同时攻击h1的车。",
        "15": "白马到h4，准备跳到f5去威胁黑后。",
        "16": "黑后到g5，攻击h4的马。",
        "17": "马到f5，这是有e4兵保护的好位置。它还瞄着g7的兵。",
        "18": "c6想赶走b5的象。",
        "19": "白方不救象，而是用g4赶h5的马。",
        "20": "马退回f6。",
        "21": "车到g1，保护g4的兵。b5的象被吃也没关系，这是很大胆的一步。",
        "22": "黑方吃掉象，多了一整个子。",
        "23": "白方用h兵开始追赶黑后。",
        "24": "后到g6。",
        "25": "h5再次追后。",
        "26": "后只能回到g5。它能走的格子越来越少。",
        "27": "白后到f3。接下来象如果吃f4，黑后可能就被困住了。",
        "28": "黑方把马退回g8，给后留出f6这条退路。",
        "29": "象吃掉f4的兵，攻击黑后。",
        "30": "后逃到f6。",
        "31": "马出动，准备跳到d5攻击后。",
        "32": "象出动，瞄准g1的车。",
        "33": "马到d5，攻击f6的后和c7格。g1的车被吃也不在乎。",
        "34": "后吃掉b2的兵，攻击a1的车。",
        "35": "象到d6！白方让对方吃掉两个车，换来的是围住黑王的一张网。",
        "36": "黑方吃掉g1的车。",
        "37": "e5！这个兵挡住了从b2的后到g7的斜线。黑后再也回不来保护王了。",
        "38": "黑方一边将军，一边吃掉另一个车。",
        "39": "王到e2。白方的大子只剩下后、两个马和一个象。",
        "40": "马到a6保护c7。据说黑方在这附近认输了，后面的走法可能是白方演示的。",
        "41": "马吃g7并将军。",
        "42": "王逃到d8。",
        "43": "后弃在f6并将军！最后一个大子也送出去了。",
        "44": "黑方只能用马吃。",
        "45": "象到e7，将死！d5的马控制e7和c7，g7的马控制e8。白方只用一个象和两个马就赢了。"
      } },
    "mimiaka": { "t": "耳赤之局", "w": "本因坊秀策", "b": "井上幻庵因硕", "ev": "大坂对局（下了三天）", "d": "1846年", "pl": "日本（大坂）", "lead": "17岁的秀策（四段）挑战当时顶尖棋手之一幻庵（八段）。中盘秀策下出第127手时，据说幻庵的耳朵红了，因此称为“耳赤之局”。那时没有贴目，黑胜2目。",
      c: {
        "0": "1846年，大坂。秀策执黑，幻庵执白。前一天两人下过一盘让二子的棋，但中途打挂；这一盘秀策执黑，不放子。",
        "1": "黑1下在右上小目（R16），这个位置容易稳稳地占住角地。",
        "2": "白2下在左上小目（D17）。双方先分占空角。",
        "5": "黑1、3、5，三个角都下在小目。这是秀策喜欢的下法，后人也常以此为范本。",
        "6": "白6下在左边C14。不去挂黑角，而是在边上布局，稍显少见。",
        "7": "黑7（E4）在左下角再补一手，叫做“守角”，角就非常牢固了。",
        "8": "白8（R5）挂右下黑Q3。右下的大战由此开始。",
        "10": "白10（O4）就是“大斜”，从远处斜着罩住黑子，变化极多，是幻庵的拿手好戏。",
        "11": "黑11（Q5）进入了复杂的变化。大斜是对手研究得很深的定式，黑必须小心应对。",
        "24": "右下黑白交错，双方都想把对方切断。白24（N4）之后，黑子很难向外出头。",
        "25": "黑25（N3）。后来的研究认为这里有更好的下法。即使是高手也会犹豫的难处。",
        "28": "白28（M3）、30（L2），白立刻抓住黑的漏洞。黑子在下边快被封在狭窄的地方。",
        "31": "黑31（M4）很重要。为接下来的劫争（你提我提的争夺）做准备，预先制造对方必须应的劫材。",
        "36": "白36（N2）。开劫之前，白先在这里下一手，时机恰到好处。",
        "40": "白40（R1）提掉一子，劫争开始。被提的一方不能马上提回，要先到别处找劫材。",
        "41": "黑41（O5）是劫材。虽然有些亏，但此时只能这样下。",
        "53": "黑53（R10）是一般人想不到的妙想，去破坏右边白棋的棋形。",
        "60": "白60（S3）是大棋，而且让白接下来的62（M1）也能先手下到。",
        "63": "黑63（O1），右下的长期战斗告一段落。白在下边得到实地，黑在右边筑起厚势。目前看来白下得比较好。",
        "67": "黑67（L17）。黑背靠右边的厚势，在上边展开大模样。",
        "72": "白72（P13）是妙手。下在黑厚势的上方，阻止黑模样扩张。",
        "74": "从这里到第100手左右，幻庵下得一丝不苟，巧妙化解黑的攻击，白子连成一片。",
        "83": "黑83（H3）打入下边白空，想尽量减少白地。",
        "96": "从白96（R14）起，围绕右上黑角展开细致的战斗。白在这里也走出了好形。",
        "107": "黑107（P10）提掉白一子，右边黑棋安全了。",
        "118": "白118（M19）提黑一子，上边白棋也活了。黑上边的模样没有想象中那么大。",
        "126": "白126（J5）。下边白棋很厚，并向中央伸展。据说当时观战的职业棋手大多认为白棋好。",
        "127": "这就是著名的“耳赤之手”——黑127（K11）。据说中央这一子同时作用于四个方向：扩大上方黑模样、削弱下方白厚势、援助右边黑棋、阻止白向左扩展。",
        "128": "这时，在旁观战的一位医生注意到幻庵的耳朵红了。他不太懂棋，却说这是动摇的表现，黑棋大概会赢——这个故事流传至今。",
        "131": "黑131（D10）。黑也进入左边白的阵势，全盘削减白地。",
        "147": "黑147（K10）。第127手那颗子开始发挥作用，黑在中央把白棋分开。",
        "160": "白160（H8）。白一边守护中央的子，一边瞄着左下黑棋。胜负仍很细微。",
        "167": "黑167（C2）下得准确。左下角黑棋安全了，白的企图落空。",
        "175": "黑175（G4）提白一子。下边白地并没有起初看起来那么大。",
        "199": "黑199（K7）。中央战斗平息，进入划定边界的“官子”阶段，一目两目都要争。",
        "212": "白212（D19）、216（F19），白在上边边缘提掉黑子。官子阶段双方寸步不让。",
        "228": "白228（N12）在中央形成劫。此后80多手，双方在M13和N13反复提子。",
        "236": "白236（T8）是劫争中提一子的劫材。后来有研究认为，若在此结束劫争，差距会更小。",
        "275": "黑275（T14）提白两子。劫争中，双方在盘上各处有得有失。",
        "299": "黑299（J16）一举提掉白四子，上边黑守得稳稳的。",
        "311": "黑311（M13）消劫，漫长的劫争终于结束。",
        "325": "325手终局，数子结果黑胜2目。虽然是不贴目的时代，17岁少年战胜幻庵这样的顶尖高手仍轰动一时，秀策从此声名远扬。"
      } },
    "evergreen": { "t": "常青之局", "w": "阿道夫·安德森", "b": "让·杜弗雷纳", "ev": "一盘随意下的棋（不是比赛）", "d": "1852年", "pl": "德国（据认为是柏林）", "lead": "下出\"不朽之局\"的安德森，第二年又下出了这盘名局。就在黑方要将死白方的时候，白方安静地走了一步车，然后弃后，用双将结束对局。因为它永远不会褪色，所以叫做\"常青之局\"。",
      c: {
        "0": "这是1852年刊登在杂志上的一盘棋。白方是安德森，黑方是他的朋友杜弗雷纳。一般认为是在柏林下的，但没有确切的记录。",
        "1": "白方把王前的兵走两格。",
        "2": "黑方也一样。",
        "3": "马攻击e5的兵。",
        "4": "黑方用马保护e5。",
        "5": "象出动，瞄准黑方的f7。",
        "6": "黑方也出象。",
        "7": "b4！送出一个兵，这叫\"埃文斯弃兵\"。趁黑方吃兵的时候，白方巩固中心。",
        "8": "黑方吃兵。",
        "9": "c3赶象，为下一步d4做准备。",
        "10": "象退到a5。",
        "11": "d4占领中心。",
        "12": "黑方吃兵。",
        "13": "白方不吃回，而是王车易位。王的安全和棋子的活跃比兵更重要。",
        "14": "黑兵一直冲到d3，深入白方阵地。",
        "15": "后到b3，和c4的象一起瞄准f7。",
        "16": "黑方用后保护f7。",
        "17": "e5赶后。",
        "18": "后到g6。",
        "19": "车到e1，进入e线支援e5的兵。",
        "20": "黑方出马，准备王车易位。",
        "21": "象到a3，沿斜线盯住e7的马。这个马一走开，象就能控制f8，所以黑方很难短易位了。",
        "22": "黑方送出一个兵，想引开白方的棋子。",
        "23": "后吃掉。",
        "24": "车到b8，沿b线追后。",
        "25": "后到a4。",
        "26": "象退到b6。",
        "27": "马出动。白方的棋子几乎都出来了。",
        "28": "黑方也出另一个象。",
        "29": "马到e4，下一步瞄准f6。",
        "30": "黑后到f5，攻击e4的马。",
        "31": "象吃掉d3的兵，同时保护e4的马。",
        "32": "后到h5，瞄准f3的马。",
        "33": "马弃在f6并将军！",
        "34": "黑方用兵吃。",
        "35": "白方用兵吃回，攻击e7的马。e线上e1的车也盯着e7。",
        "36": "车到g8，瞄准g2。如果h5的后吃掉f3，将杀就近在眼前。",
        "37": "车安静地走到d1！自己的王有危险，白方却不防守，而是把棋子对准d7。正是这一步让这盘棋成了\"常青\"。",
        "38": "黑方吃掉f3的马。下一步吃g2就是将死。",
        "39": "但白方先走。车吃掉e7的马并将军！",
        "40": "黑方用c6的马吃回。这样从a4到d7的斜线就空出来了。",
        "41": "后弃在d7并将军！",
        "42": "只能用王吃。",
        "43": "象走到f5将军，同时让开了d1车的d线：双将。",
        "44": "王到e8。如果逃到c6，象到d7就是将死。",
        "45": "象到d7将军。",
        "46": "王到f8。",
        "47": "a3的象吃掉e7的马，将死！d7的象控制e8，f6的兵控制e7和g7。"
      } },
    "lasker1912": { "t": "猎王之局", "w": "爱德华·拉斯克", "b": "乔治·艾伦·托马斯", "ev": "在伦敦城国际象棋俱乐部下的一盘快棋（随意的对局）", "d": "1912年", "pl": "英国（伦敦）", "lead": "在伦敦一家俱乐部里下的一盘随意的快棋。白方弃后，把黑王从g8一路赶到g1，横穿整个棋盘。各种记录里开局的顺序稍有不同，但第10回合后的局面是一样的。",
      c: {
        "0": "1912年10月，伦敦城国际象棋俱乐部。白方是刚从德国来的年轻工程师爱德华·拉斯克，黑方是后来成为英国冠军的乔治·艾伦·托马斯。这是一盘时间很短、很随意的快棋。它以\"猎王\"闻名：黑王从g8一路被赶到棋盘另一端的g1。拉斯克后来去了美国，因写国际象棋书而广为人知。",
        "1": "白方先走d4，后前的兵。它控制e5和c5，也给c1的象让出了路。",
        "2": "黑方走e6，先摆出稳固的形状，准备下一步走f5或d5。",
        "3": "马到f3。它控制e5，也帮助保护王翼，是最自然的位置。",
        "4": "黑方走f5，控制e4格，接近荷兰防御。但王前的兵动了，黑王周围变得有点弱。",
        "5": "另一个马也到c3，准备走e4去冲击f5的兵。",
        "6": "黑方也把马出到f6，进一步控制e4，同时准备易位。",
        "7": "象到g5，瞄准f6的马。这个马是保护黑王的重要棋子，所以白方想早点除掉它。",
        "8": "黑方把象出到e7保护马，易位的准备也更进一步。",
        "9": "白方用象换掉马。保护黑王的马不见了。",
        "10": "黑方用象吃回。现在f6的象接过了保护王翼的任务。",
        "11": "e4！冲击f5的兵，扩大中心。线路打开，白方的棋子更容易活动。",
        "12": "黑方吃掉e4的兵。不吃的话，白方会走e5把黑方的棋子赶回去。",
        "13": "马吃回来站到中央，盯着f6的象以及g5、d6格。",
        "14": "黑方走b6，准备把象出到b7，从长斜线瞄准e4的马。",
        "15": "马到e5，这是中央的好格子，也盯着g4和f7。白方的两个马都靠近了黑方王翼。",
        "16": "黑方王车易位，王到了g8。但f线的兵不在了，王周围有很多空隙。",
        "17": "象到d3。现在被自己e4的马挡住，但再往前就是h7的兵。e4的马一动，这个象就会直指h7。",
        "18": "黑象到b7，从长斜线瞄准e4的马，让白方的棋子不太自由。",
        "19": "后到h5，瞄准h7的兵。h7只有黑王保护。白方的后、象和马全都对准了黑王。",
        "20": "黑方把后走到e7。它保护f6的象，也准备去c5，但黑方没发现白方的意图。这里应该走h6或吃掉e5的马。这是胜负的分水岭。",
        "21": "后弃在h7并将军！把最强的棋子白白送掉。拉斯克已经看清了一路追王直到将死的路线。",
        "22": "黑方只能用王吃。王被拉到了h7。",
        "23": "马吃掉f6的象并将军。同时e4空了出来，d3的象也将军h7的王：双将。双将挡不住，王只能逃。",
        "24": "王到h6。如果退到h8，另一个马跳到g6就是将死。王被越赶越往前。",
        "25": "另一个马从e5跳到g4将军。它攻击h6的王，把王继续往前赶。",
        "26": "王到g5，离开了自己的阵地，向白方那边走去。",
        "27": "用h兵将军！连兵也加入了猎王。王只能继续往前。",
        "28": "王到f4。它已经越过棋盘中线，正走进白方阵地。",
        "29": "再用g兵将军。两个兵挡住了王的退路。",
        "30": "王到f3，正好在白方棋子的包围中。",
        "31": "象从d3退到e2将军。王被赶得更深了。",
        "32": "王到g2。离白王所在的e1已经不远了。",
        "33": "车到h2将军。车终于也参战了。",
        "34": "王终于到了g1。它从g8出发，一直走到了棋盘另一端的第一横排。",
        "35": "白王从e1走到d2。王让开后，a1的车前面通了，沿第一横排将军g1的黑王：将死！长易位也能将死，但拉斯克选择了走王。在一盘快棋里，弃后之后用14个回合把王一直赶到白方阵地的最深处，这是非常罕见的一盘棋。"
      } },
    "toketsu": { "t": "吐血之局", "w": "赤星因彻", "b": "本因坊丈和", "ev": "于老中松平周防守府邸对局（下了四天）", "d": "1835年", "pl": "日本（江户）", "lead": "这是围绕棋界最高职位“名人棋所”之争而下的一局。井上幻庵因硕派弟子赤星因彻挑战名人丈和。经过四天激战，因彻落败，据说他在棋盘前吐了血。",
      c: {
        "0": "1835年。黑方赤星因彻（七段），白方名人本因坊丈和。幻庵派出最得意的弟子，打算一旦获胜就说：输给七段的人不配当名人。",
        "1": "黑1下在左下小目（C4），因彻从稳健的一手开始。",
        "4": "四手之后，四个角各有一子：白在右下和左上，黑在左下和右上。",
        "6": "白6（E3）早早地挂左下黑角。丈和一开始就很积极。",
        "10": "白10（P4）在右下角守角。",
        "12": "白12（D6）从上方压住左下黑角。本局最大的战斗由此展开。",
        "13": "黑13（E4）紧贴白子，黑也毫不示弱地应战。",
        "20": "白20（C3）钻到黑角下面，一边掏黑角的实地，一边设法让自己的棋子做活。",
        "28": "白28（C9）大步跨入左边，常被认为是过分之着，是丈和式的强硬一手。",
        "33": "黑33（C2）。据说这是井上家秘密研究的新变化，既攻击白中央浮棋，又吞掉左边白子。",
        "36": "白36（F3）。白在左下从外面压住黑，同时想把自己的子连起来。",
        "43": "黑43（E9）。左边白子陷入困境。到这里因彻下得很好，一般认为已经领先。",
        "45": "黑45（D11）沿左边向上伸展，保持分断白子，同时加强自己。",
        "50": "白50（C16）。白暂时离开左下，转向左上角。",
        "53": "黑53（G17）。黑进入上边，不让白扩大左上。",
        "58": "白58（C14）从左上角向边上展开，逼近左边黑子。",
        "60": "白60（G4）提黑两子，左下白棋终于稍微喘了口气。",
        "62": "白62（J17）。上边黑白也对峙起来，盘上到处都有弱棋，局面复杂。",
        "66": "白66（B14）。白在左上角一带安顿自己的棋子。",
        "68": "白68（B11）。从这里开始的几手白棋以及第80手，后来被传为“丈和的妙手”，精彩到被说成是“鬼魂教的棋”。",
        "70": "白70（E12）。白没有直接应左边黑棋，而是先下另一个要点。因为留有后续的手段，才能这样下。",
        "72": "白72（R13）。白转向右边，不让黑的右上扩大。",
        "76": "白76（O14）。白连接右边与中央，准备分断黑子。",
        "80": "白80（Q10）形成“空三角”，通常被认为是愚形。然而正是这一手，成为把黑棋分成两块进行攻击的据点。常被举为“形愚而实妙”的典型。",
        "83": "黑83（R3）打入右下白角，接着展开你提我提的激战。",
        "91": "黑91（Q4）提白一子，右下角对黑来说非常重要。",
        "98": "白98（M4）。白从外面包住下边黑子，不让黑轻易做活。",
        "106": "白106（S5）提黑一子。白守住了右下角，黑子只好向外逃。",
        "113": "黑113（K6）。下边黑子向中央出头，寻找活路。",
        "120": "白120（N9）挡住逃跑的黑子。中央变成谁先变弱的较量。",
        "128": "白128（L11）从上方继续压住中央黑子，黑始终无法安心。",
        "138": "白138（K8）提黑一子，中央开劫。双方在K8和L8反复提子，持续约30手。",
        "152": "白152（E11）是劫材。劫争期间，白不断在各处找到黑必须应的手。",
        "170": "白170（P15）。中央劫争告一段落，白转向右上，瞄准尚未完全活净的大块黑棋。",
        "178": "白178（J14）打入上边中部，要把黑子分成左右两块。从第80手开始酝酿的分断攻击，在这里正式展开。",
        "193": "黑193（J11）提白一子。黑也拼命连接，寻找活路。",
        "201": "黑201（R14）提白一子，右边又开新劫，双方在R14和R15反复争夺。",
        "206": "白206（M13）。劫争之中，白也一步步收紧对中央黑子的包围。",
        "222": "白222（L14）提黑一子。上边黑棋仍被分成两块，要两边兼顾越来越难。",
        "230": "白230（C13）在左边也冲击黑的弱点。盘上的白子已经牢牢连在一起了。",
        "237": "黑237（F12）、239（E13），黑在左上提回白子。尽管如此，全局差距并未缩小。",
        "246": "白246（L8）之后，因彻认输。据说收拾棋子时，他把血吐在了棋盘上。他的身体大概早已被疾病拖垮，不久便去世了。这一局被称为丈和一生最大的胜利。"
      } },
    "deepblue1997": { "t": "深蓝的胜利", "w": "深蓝（IBM的计算机）", "b": "加里·卡斯帕罗夫", "ev": "与IBM深蓝的再战（六局比赛）第6局", "d": "1997年", "pl": "美国（纽约）", "lead": "世界冠军卡斯帕罗夫，对阵IBM制造的国际象棋计算机\"深蓝\"，进行六局比赛。前五局打成平手，最后一局只下了19个回合就结束了。这是计算机第一次在多局的正式比赛中战胜世界冠军。",
      c: {
        "0": "1997年5月11日，纽约。前一年的比赛是卡斯帕罗夫赢了。这一次前五局后比分是2.5比2.5。深蓝执白。",
        "1": "白方把王前的兵走两格。",
        "2": "卡斯帕罗夫走c6，卡罗-康防御。",
        "3": "白方把另一个兵也走到中央。",
        "4": "黑方走d5，冲击e4。",
        "5": "马保护e4。",
        "6": "黑方吃掉e4的兵。",
        "7": "马吃回来。",
        "8": "黑方把马走到d7，准备再把另一个马出到f6。",
        "9": "马跳到g5，这是瞄准f7和e6的尖锐走法。",
        "10": "黑方把马出到f6。",
        "11": "象到d3，瞄准黑方王翼。",
        "12": "黑方走e6加强防守。",
        "13": "另一个马也出到f3。",
        "14": "黑方走h6，想赶走g5的马。但在这个局面里，白方弃马的走法早已为人所知。人们说这不像卡斯帕罗夫的选择。",
        "15": "马弃在e6！据说深蓝是从事先存好的开局走法里走出这一步的。",
        "16": "黑方没有马上吃，而是把后走到e7。在e线上，它对准了e6的马和后面的白王。",
        "17": "白方王车易位，让王离开。",
        "18": "黑方吃掉马，子力领先。",
        "19": "象到g6将军。f7的兵不在了，斜线一直通到王。",
        "20": "王到d8。黑方再也不能易位，王被困在中间附近。",
        "21": "另一个象也出动，瞄准黑王周围的格子。",
        "22": "黑方走b5，在后翼给王和象腾出地方。",
        "23": "a4冲击b5的兵。",
        "24": "黑方把象走到b7。",
        "25": "车到e1，在e线上瞄准e6的兵，以及后面e7的后。",
        "26": "黑马到d5，攻击f4的象。",
        "27": "象退到g3。",
        "28": "黑王到c8，稍微安全一点。",
        "29": "白方吃掉b5的兵。",
        "30": "黑方吃回。",
        "31": "后到d3，瞄准b5的兵，也盯着f5格。",
        "32": "黑方用象保护b5。",
        "33": "象到f5！可以被白吃。",
        "34": "黑方用兵吃。但这样e线上的兵就没了。",
        "35": "车吃掉e7的后。白方送出了马、象和车，但换来了对方的后。",
        "36": "黑方用象吃回车。",
        "37": "c4！这个兵同时冲击b5和d5，黑方的防线开始崩溃。卡斯帕罗夫在这里认输了，大概是认为王太暴露，挡不住白方的进攻。计算机在比赛中战胜了世界冠军。"
      } },
    "seigen1933": { "t": "三三·星·天元之局", "w": "吴清源", "b": "本因坊秀哉", "ev": "与秀哉名人的纪念对局（历时三个多月）", "d": "1933—1934年", "pl": "日本（东京）", "lead": "19岁的吴清源（五段）与名人本因坊秀哉对弈。执黑的吴清源第1手下三三、第3手下星、第5手下天元，打破当时的常识，震惊棋界。对局多次打挂，历时三个多月，最终白胜2目。",
      c: {
        "0": "1933年。这一年，吴清源与好友木谷实一起推广被称为“新布局”的新下法。人们都关注他会如何在名人面前施展。",
        "1": "黑1下在右上三三（R17）。一手就能确保角地，但向外的力量较弱，当时人们并不认为这是开局第一手该下的地方。",
        "3": "黑3下在左下星位（D4）。与三三相反，星位更重视向外发展。",
        "5": "黑5竟然下在棋盘正中央的天元（K10）。不是角也不是边，而是先占中央。面对名人，他正面展示了新的思路。",
        "6": "三三、星、天元：三颗黑子分别承担角地、向外发展和中央力量的不同任务。白6（Q16）紧挨着右上黑三三下子。",
        "9": "黑9（P18）。黑在右上角简洁地安定下来，是三三特有的重实地下法。",
        "11": "黑11（K4）下在天元正下方的下边中央，与天元配合，想围出下边的大模样。",
        "12": "白12（M3）立刻打入下边，不让黑形成大模样。名人沉着应对，一一化解黑的构想。",
        "13": "黑13（D10），这次下在左边中央。黑子都在棋盘较高的位置，整体形成大模样。",
        "14": "白14（E16）在左上角守角。名人没有被黑的新下法迷惑，沉着地守住角。",
        "21": "黑21（G10）连接天元与左边的子，黑势力在中央扩展。",
        "28": "白28（D3）钻到左下黑星位下面，取得角地。黑以外势为代价，把角让给了白。",
        "30": "白30（Q12）在右边展开，同时罩住右上黑三三的外侧，削弱黑的力量。",
        "37": "黑37（P15）提白一子。右上黑白相撞，发生细致的争夺。",
        "40": "白40（O10）从右边向中央迈出一步，逼近天元周围的黑势力。",
        "44": "白44（H17）下在上边，阻止黑子向上发展。",
        "45": "黑45（R7）开始侵入右下白阵。从右边到右下，接下来战斗持续了一段时间。",
        "59": "黑59（R4）也侵入右下角，削减白地。",
        "70": "白70（N6）从下边向中央延伸，企图分开黑右下与中央的子。",
        "79": "黑79（L9）以天元为中心巩固中央。到这里可说是势均力敌。",
        "80": "白80（C6）从左下角向左边推进，瞄准黑左边的子。",
        "98": "白98（A11）提黑两子。白在左边边缘巧妙做活，黑的左边比预想的小。",
        "101": "黑101（S14）回到右上，削减右边白阵。",
        "105": "黑105（K17）下在上边中央，开始攻击白在上边的子。",
        "117": "黑117（F17）在左上也侵入白角周围，整个上边都打了起来。",
        "124": "白124（K15）一边把上边白子向中央逃出，一边从黑子之间穿过。",
        "135": "黑135（E9）提白两子，在左边扳回一些。",
        "138": "白138（N18）在上边巩固实地。从全局看，形势非常细微。",
        "153": "黑153（K14）。中央黑子形成连接上下的粗壮通道。白如何突破这片厚势，是胜负的关键。",
        "159": "黑159（F4）稳守左下。白的下一手，成了本局最有名的一手。",
        "160": "白160（H8）跳进黑厚势的缝隙，是一步锐利的棋，同时带有多重目的，白由此开始侵蚀黑的中央。有传言说这手棋是秀哉的弟子发现的，但并无确证。",
        "161": "黑161（J8）立即应对，但白的目的不止一个。",
        "162": "白162（K12）转到中央上方，威胁黑子之间的连接。",
        "172": "白172（F13）把中央与左上的子连起来，黑中央的厚势渐渐无法转化为实地。",
        "178": "白178（N9）在中央右侧也侵入黑空。",
        "187": "黑187（M6）、189（L7）提掉白子应对。尽管如此，白已抢先占到了要点。",
        "198": "白198（E12）提黑一子。左上白子也连通了，白全局略为领先。",
        "203": "黑203（B3）。从这里进入官子，逐目确定边缘的边界。",
        "224": "白224（T10）提黑一子。在右边边缘，白也一目不让。",
        "233": "黑233（L13）提白两子，黑坚持追赶到最后。",
        "252": "252手终局，白胜2目。没有贴目的时代，先行的黑稍占便宜，但名人始终不乱，赢到了最后。尽管如此，吴清源的三三、星、天元引起轰动，宣告了新布局时代的到来。"
      } },
    "century1956": { "t": "世纪之局", "w": "唐纳德·伯恩", "b": "鲍比·费舍尔", "ev": "第三届罗森瓦尔德杯赛（罗森瓦尔德纪念赛）", "d": "1956年", "pl": "美国（纽约）", "lead": "13岁的鲍比·费舍尔战胜了美国强手唐纳德·伯恩。第17回合，费舍尔让对方白白吃掉自己的后，然后一个接一个地把棋子赢回来，最后用小子们围捕白王。费舍尔后来成为了世界冠军。",
      c: {
        "0": "1956年10月17日，纽约的一场比赛。执黑的是13岁的费舍尔，执白的是美国顶尖棋手之一伯恩。",
        "1": "白方先出马。",
        "4": "费舍尔走g6，准备把象放到长斜线上。",
        "8": "黑方王车易位，先让王安全。",
        "10": "黑方走d5，中心争夺开始了。",
        "15": "白方走e4，中心有了两个并排的兵。",
        "17": "车到d1，支援d4的兵。白方还没有王车易位。",
        "18": "马到b6，赶c4的后。",
        "20": "象到g4，牵制f3的马。",
        "21": "白方的象也到g5。白王还在中间。",
        "22": "马到a4！故意跳到会被吃的地方。想法是：c3的马一离开，e4的兵就没人保护了。",
        "23": "白方不吃马，把后移到a3。",
        "26": "黑马吃掉e4的兵，白方中心开始崩溃。",
        "27": "白象吃掉e7的兵，同时攻击黑后和f8的车。",
        "28": "后到b6！黑方让f8的车被吃也没关系。费舍尔看准了白王还在中间。",
        "29": "白方没有吃车，而是出象。",
        "30": "马吃掉c3的兵，攻击d1的车。",
        "31": "象到c5，攻击b6的黑后。",
        "32": "车在e线将军！",
        "33": "王到f1。这样白方再也不能易位了。",
        "34": "象到e6！这是这盘棋最有名的一步：让对方白白吃掉自己的后。作为交换，黑方计划一个接一个地把棋子赢回来。",
        "35": "白方吃掉黑后。",
        "36": "象到c4将军，黑方的反击开始了。",
        "38": "马在e2将军。",
        "40": "王回到f1时，马一走开，c4的象就形成了闪击将军。马顺便吃掉了d4的兵。",
        "44": "马回到c3，又是闪击将军，这次攻击d1的车。一边连续将军一边吃子，这叫\"风车\"。",
        "46": "黑方吃回象。c3的马还在攻击d1的车。",
        "50": "马吃掉d1的车。现在黑方赢回的已经比送出的后还多，明显领先。",
        "52": "车也吃掉a2的兵。",
        "56": "黑方兑车。棋子越少，子力多的一方越有利。",
        "57": "白后将军。",
        "58": "黑方用象垫将。",
        "64": "b5，黑兵开始前进。",
        "68": "王走到g7，让f8的象可以活动。",
        "70": "现在黑方的棋子开始围捕白王。用象将军。",
        "72": "马在g3将军。",
        "74": "用另一个象将军。",
        "76": "象到b3将军。",
        "78": "马在e2将军。",
        "80": "马在c3将军，白王被追来追去。",
        "82": "车到c2：将死！车、两个象和马齐心协力。一个13岁的少年，展示了这么多棋子如何像一个团队一样配合。"
      } },
    "oshiro1849": { "t": "秀策的第一局御城棋", "w": "本因坊秀策", "b": "安井算知（九世）", "ev": "御城棋（每年在江户城举行的对局）", "d": "1849年", "pl": "日本（江户）", "lead": "御城棋是各围棋家元的棋手每年在将军城中对弈的盛会。20岁的秀策这一年首次出场，执黑胜11目。由此开始了他在御城棋中19战全胜的不败纪录。",
      c: {
        "0": "1849年。秀策前一年被定为本因坊家的继承人，这一年首次出场御城棋。据说御城棋多是事先在别处下好，再到城中复盘重摆。",
        "1": "黑1下在右上小目（R16）。秀策一如往常，从稳健的小目开始。",
        "4": "白4（C15）挂左上黑D17，布局阶段左上就开始了战斗。",
        "5": "黑5（C11）从下方夹击挂过来的白子，不让白在左边轻松安定。",
        "12": "白12（C17）。左上角归白，黑得到外侧。双方都可接受的转换。",
        "13": "黑13（J17）利用外侧黑子，在上边展开。",
        "15": "黑15（C5）占据最后一个空角——左下角。四个角都有子了。",
        "16": "白16（E4）立刻逼近这颗黑子，左下也打了起来。",
        "19": "黑19（D2）牢牢确保左下角的实地，是秀策式的稳健下法。",
        "23": "黑23（E5）从白子之间出头，加强左下黑棋。",
        "29": "黑29（F11）补强左边黑子，同时着眼中央。",
        "30": "白30（H4）在下边展开，一边压迫左下黑棋，一边构筑自己的阵地。",
        "31": "黑31（O3）挂右下白角。",
        "33": "黑33（R3）紧贴白角的子。此后黑在外侧，白沿边上的三线伸展。",
        "43": "黑43（Q8）。右边形成了上下相连的黑色厚壁。白取得角和边的实地，黑获得外势。",
        "44": "白44（L17）打入上边黑子之间，不让黑阵地过大。",
        "50": "白50（R18）钻进右上黑角下方，瞄准角地。",
        "51": "黑51（P13）。黑背靠右边厚壁，从右边到中央构筑大阵地。",
        "52": "白52（D10）打入左边黑子之间，左边黑白纠缠在一起。",
        "63": "黑63（B10）在左边边缘落子，不让白子在这里建立根据地。",
        "65": "黑65（G3）也侵入下边白阵，削减白地。",
        "73": "黑73（K17）巩固上边黑子，让白44那颗子陷入困境。",
        "76": "白76（P11）打入黑右边阵地。这颗子是死是活，将大大影响地的多少。",
        "77": "黑77（Q11）从厚壁一侧应对，把白赶向中央。守地的同时进攻，是秀策式的沉稳应手。",
        "80": "白80（N10）向中央逃出，试图摆脱黑的追击。",
        "85": "黑85（N12）一边攻击，一边扩大上边和右边的实地。借攻得利，运筹巧妙。",
        "91": "黑91（J7）下在下边白子上方，从中央方向压住白阵。",
        "100": "白100（S17）在右上角动手，想削减黑的角地。",
        "119": "黑119（R17）稳守右上角，化解了白的手段。",
        "122": "白122（G6）绕到左下黑子外侧，企图切断它与中央黑子的联系。",
        "131": "黑131（M5）在下边中部楔入白阵。",
        "140": "白140（B4）在左下黑角动手，左边边缘开始了细致的提子争夺。",
        "156": "白156（A8）提黑两子。左边边缘的争夺在双方互有所得后平息。",
        "158": "白158（L10）。白在中央仍有子，试图削减黑中央的实地。",
        "162": "白162（O12）提黑一子。尽管如此，黑右边的阵地仍然很大。",
        "172": "白172（K18）。从这里进入官子，先确定上边的边界。",
        "186": "白186（T16）在右上边缘削减黑地。官子阶段，双方都先下最大的地方。",
        "205": "黑205（Q18）封住上边右侧，确定实地。",
        "223": "黑223（P10）确定右边黑地与逃向中央的白子之间的边界。",
        "233": "黑233（Q9）提白一子。黑右边的实地基本守住了。",
        "239": "黑239（A6）提白一子，左边边缘形成劫。一目一目的争夺一直持续到最后。",
        "260": "白260（T6）提黑一子，右下边缘也成劫。黑在263（T5）提回。",
        "267": "267手终局，黑胜11目。没有冒大险，而是边攻击边自然扩大实地，是秀策式的胜法。这是他御城棋19连胜的第一局。"
      } },
    "shilin": { "t": "《事林广记》顺手炮局", "w": "红方（姓名未流传）", "b": "黑方（姓名未流传）", "ev": "日用百科《事林广记》“饶先顺手取胜局”", "d": "13世纪", "pl": "中国（宋元之际）", "lead": "这是宋末元初陈元靓编写的日用百科《事林广记》中收录的棋谱，被认为是现存最古老的象棋全局谱之一。这是一盘强者让对方先走的“饶先”示范局，短短9个回合，黑马就捉住了红车。",
      c: {
        "0": "这是七百多年前、宋元之际的棋谱。它收在百科全书《事林广记》讲游戏的部分，被认为是现存最古老的象棋全局记录之一。对局双方的名字没有流传下来。“饶先”是强者把先手让给弱者，所以这盘棋是在示范先走的红方怎样输掉。红方在下方，先走。",
        "1": "红方把右边的炮移到中路。这叫“中炮（当头炮）”，正对着黑将，至今仍是最强的开局之一。可见七百年前人们就已经在下这种布局了。",
        "2": "黑方也把炮移到中路，正面对峙。双方都动同一侧的炮，叫做“顺手炮”。炮对炮的较量，自古以来就很受欢迎。",
        "3": "红方跳马保护中兵。中兵正被黑炮瞄着，需要有子保护。同时，这匹马也准备向前出动。",
        "4": "黑方也跳马保护中卒。双方摆出相同的阵形，先把根基打牢。",
        "5": "红方把右车横移一步，走到可以直冲的路线上。车是棋盘上最强的子，越早出动越好。",
        "6": "黑方又跳出一匹马，暂时不出车。先把子力向前展开是一种思路，但车出得太晚，之后就不容易参加进攻。",
        "7": "红车一下子过河，冲进黑方阵地。它想威胁黑子，可是红方其他子都还在家里，这样进攻有点急。也可以先出动左边的马或车。",
        "8": "黑方挺起3路卒，给马让出道路，以后马就能向前跳。黑方几乎是在等红车过来。",
        "9": "红车吃掉一个卒，同时瞄着后面的黑马。得了一子又捉马，看起来很痛快。可是这辆车冲得太远，身边没有帮手。孤车深入敌阵，很容易被追打。",
        "10": "黑马向前跳出，既躲开红车，又靠近红方阵地，一步棋做了两件事。这匹马就是本局的主角。",
        "11": "红车退一步，从侧面再捉黑马。车能远距离吃子，马一刻也不能停。不过这步棋同样没有让其他红子出动。",
        "12": "黑马继续前进，过河进入红方阵地。每躲一次红车，它就离红帅更近一步。",
        "13": "红方挺起一个兵，给自己的马让路。想法是接着出马，和黑马兑换。可是这就给了黑方继续前进的时间。",
        "14": "黑方飞象，攻击红车。用防守的象赶走对方的车，非常经济。红车只好再走，黑方又赚了一步。",
        "15": "红车横走，又吃掉一个卒。虽然多得了两个卒，但这正是输棋的一步。车离帅太远，再也回不来防守了。这里需要防备黑马，比如把车调回来。",
        "16": "黑马跳得更深，捉住红车。不止如此：马再跳一步，就能将军红帅，同时捉住红方角上的车。一匹马同时造成了两个威胁。",
        "17": "红车追捉黑马，可是马已经挡不住了。红帅身边已经没有任何保护。",
        "18": "黑马跳入将军！这匹马同时还捉着红方角上的车，红帅一躲，车就会被吃掉。虽然只有9个回合，但这盘棋告诉我们：孤车冒进会有什么下场，子力要互相配合才能作战。七百年前的人们，也在同样的棋盘上思考着同样的事情。"
      } },
    "qima13": { "t": "弃马十三着（《橘中秘》）", "w": "红方（姓名未流传）", "b": "黑方（姓名未流传）", "ev": "《橘中秘》卷上 第一局“顺炮横车破直车弃马”", "d": "1632年（刊行）", "pl": "中国（明）", "lead": "这是明代朱晋桢于1632年（崇祯五年）刊行的棋书《橘中秘》中最开头的一局。红方故意让黑方白吃一匹马，趁机杀入，13个回合就将死对方。“弃马十三着”这个名字，在将近400年后的今天依然广为人知。",
      c: {
        "0": "这是明朝末年、1632年出版的棋书《橘中秘》的第一局。《橘中秘》和后来的《梅花谱》并称为象棋两大古典名谱。这盘棋不是实战，而是用来讲解战术的示范局，所以没有对局者的名字。红方在下方先走，只用13个回合就分出胜负。",
        "1": "红方把右炮移到中路，正对黑将，这是“中炮”。《橘中秘》正是以深入研究中炮攻法而闻名的书。",
        "2": "黑方也把同一侧的炮移到中路，形成炮与炮正面碰撞的“顺手炮（顺炮）”。双方都瞄着对方的中兵（中卒）。",
        "3": "红方跳马保护中兵。既守住被黑炮瞄着的兵，马也开始发挥作用。",
        "4": "黑方也跳马保护中卒。到这里为止，双方阵形完全一样。",
        "5": "红方把右车向前走一步。这样下一步车就能横着走。能横向移动的车叫“横车”，好处是可以快速调到左右两边。",
        "6": "黑方把车横移一步，变成可以直着前进的“直车”。横车对直车，两种不同用法的车互相对峙，形成“顺炮横车对直车”。",
        "7": "红方的横车大幅移到左侧的路线上。这条路线紧挨着黑方的士，是对方防守薄弱的地方。红方准备从这里一举杀入。",
        "8": "黑方的直车过河，深深打入红方阵地。黑方也想以对攻来对抗。不过这是一步先急于进攻、而顾不上防守的棋。",
        "9": "红车一直冲到黑方阵地深处。这里正是象要经过的“象眼”，黑象被塞住无法行动。车紧贴着士，也离黑将非常近了。",
        "10": "黑方把另一匹马跳到边线。这也考虑到要防止红车从侧面横插进来。",
        "11": "这就是“弃马”的一步！红方把另一辆车抬起一步。这样一来，左角的马没有子保护，会被黑炮白白吃掉。但红方用一匹马，换来了让两辆车迅速投入进攻的时间。",
        "12": "黑炮吃掉红马，看起来赚了一子。可是这门炮已经无法回去保护自己的阵地。一般认为，这里不吃马、而是补士巩固防守更好。",
        "13": "红炮向前进。它把中路的黑炮当作“炮架”跳过去，瞄准后面的黑马。炮是一种隔一个子才能吃子的奇妙棋子。",
        "14": "黑方退马逃跑。可是这匹马本来是保护中卒的重要棋子。它一走，中路防守就出现了漏洞。黑方还有别的防法，但这是最差的选择。",
        "15": "红炮打掉中卒，将军！刚才黑马离开了，中路空空荡荡。红方的攻势从这里一下子展开。",
        "16": "黑方补士，挡在将的前面。要解除将军，这几乎是唯一的办法。",
        "17": "红方的第二辆车也来到同一条路线上。两辆车纵向连在一起，力量非常强大。下一步就要杀入黑方阵地深处。",
        "18": "黑将向旁边躲开。如果不动，就会被红方两辆车在同一条直线上瞄着。",
        "19": "红方用前车吃掉黑士，将军！这辆车马上会被另一个士吃掉，但这也在计算之中。弃掉一辆车，拆毁黑将身边的防守，真是大胆的一着。",
        "20": "黑方用士吃掉红车。论子力，黑方已经大大领先。可是将的周围变得更加空虚。",
        "21": "红方剩下的车移到将所在的路线上，再次将军。黑将身边几乎已经没有保护它的子了。",
        "22": "黑方把炮垫在将前，挡住将军。这种在中间放一个子的应法叫“垫将”。",
        "23": "红车吃掉这门炮，又将军。红车一边吃掉黑子，一边把黑将逼入绝境。",
        "24": "黑将只能回到中间。其他位置全都被红子控制着。",
        "25": "最后红炮来到中路，两门炮纵向重叠，将军。前面的炮当炮架，后面的炮瞄准黑将，这就是“重炮”杀。黑将无处可逃，红方获胜。只弃掉一匹马，红方就在13个回合内取胜。这盘棋四百年来一直告诉我们：比起子力多少，时间（先手）和子力的活跃更加重要。"
      } }
  },
  "zh-TW": {
    ui: {"lead":"名局一步一步看。一邊聽 Musowl 解說，一邊在棋盤上重溫經典對局吧。","all":"全部","k_chess":"西洋棋","k_shogi":"將棋","k_go":"圍棋","k_xiangqi":"中國象棋","side_r":"紅方","res_r":"紅方勝","back":"返回名局選","start":"開頭","prev":"後退一步","next":"前進一步","end":"最後","play":"自動播放","pause":"暫停","moves":"棋譜","move":"第{n}步","startpos":"開始局面","nextnote":"下一則解說（第{n}步）","quiet":"這一步沒有解說。","guide":"Musowl","keys":"← → 一步一步看","result":"結果","r_event":"對局","r_date":"年份","r_place":"地點","side_w":"白方","side_b":"黑方","side_s":"先手","side_g":"後手","side_B":"黑方","side_W":"白方","res_w":"白方勝","res_b":"黑方勝","res_d":"和局","res_s":"先手勝","res_g":"後手勝","credit":"棋譜是公開的對局紀錄。解說由博物館的 Musowl 撰寫。"},
    "opera": { "t": "歌劇院之局", "w": "保羅·莫菲", "b": "布倫瑞克公爵卡爾二世與伊蘇瓦爾伯爵", "ev": "在歌劇院包廂裡下的一盤棋（兩人商量著下）", "d": "1858年", "pl": "法國（巴黎）", "lead": "年輕的美國冠軍在歌劇演出時，對上兩位貴族，只下了17回合。快速出子，毫不猶豫地棄子，最後只用很少的棋子取勝。這是西洋棋書裡最常出現的一盤棋。",
      c: {
        "0": "1858年的巴黎。21歲的美國人保羅·莫菲接連擊敗了歐洲的強手。那天晚上，在歌劇院的包廂裡，布倫瑞克公爵和伊蘇阿爾伯爵兩人一邊商量一邊執黑，向莫菲挑戰。據說莫菲還想看舞台上的演出，所以想早點結束。這17回合裡裝滿了西洋棋的基本道理：快速出子，讓國王安全。",
        "1": "白方把國王前的士兵走兩格。它盯住中央的d5和e5，也為主教和皇后打開了路。",
        "2": "黑方也走e5。兩個士兵在中央面對面，白方士兵不能再往前走了。",
        "3": "騎士出到f3，攻擊e5的士兵。一邊出子，一邊讓對方不得不防守，是好棋。",
        "4": "黑方走d6保護e5。這叫菲利多爾防禦。很穩，但f8主教的路變窄了一點。",
        "5": "白方走d4，又一個士兵來到中央，衝擊e5。黑方必須決定是吃還是守。",
        "6": "黑方主教到g4，牽制f3的騎士。騎士後面是d1的白方皇后，騎士一走皇后就會被吃，所以騎士不能去吃e5。",
        "7": "白方用士兵吃e5。如果黑方馬上用d6士兵吃回，白方會換后，然後騎士就能吃掉e5的士兵。所以黑方想先除掉f3的騎士。",
        "8": "黑方用主教吃騎士，這樣就能安全地吃回e5了。但剛出動的主教換掉了騎士，黑方的出子落後了。",
        "9": "白方用皇后吃回。白方皇后已經在中央附近活躍起來，而黑方幾乎還沒有出子。",
        "10": "黑方用士兵吃回，子力相等。但從出動的棋子數來看，白方領先。",
        "11": "主教到c4，和f3的皇后一起瞄準f7。f7只有國王在保護，是弱點；被吃掉就是將死。",
        "12": "黑方把騎士出到f6，擋住f線。沒有這一步，皇后吃f7就是將死。一邊出子一邊防守，是正確的應對。",
        "13": "皇后轉到b3，同時攻擊f7和b7。同時有兩個威脅的棋很強，因為對方沒法兩邊都守住。",
        "14": "黑方把皇后走到e7保護f7，放棄了b7。但這樣皇后擋住了f8主教的路。",
        "15": "莫菲沒有吃b7的士兵，而是出騎士。吃兵會讓皇后跑得太遠。選擇快速出子而不是多吃一個兵，正是莫菲的風格。",
        "16": "黑方走c6，控制d5和b5，也給皇后打開了去b6的路。",
        "17": "主教到g5，牽制f6的騎士。騎士一走，後面e7的皇后就會被吃。黑方的棋子越來越難動了。",
        "18": "黑方走b5，想趕走c4的主教。這也在后翼搶到了空間，但同時給白方的棋子留下了衝進來的空隙。",
        "19": "棄騎士吃b5的士兵！莫菲沒有讓主教逃走，而是繼續進攻。黑方國王還在中間，這對黑方非常危險。",
        "20": "黑方吃掉騎士，多了一個騎士。但黑方國王還在e8，白方的棋子不斷聚集過來。",
        "21": "主教到b5將軍！黑方國王還困在中間。白方用一個騎士換來兩個士兵，直接逼近黑方國王。",
        "22": "黑方用騎士在d7擋住將軍。但這個騎士被牽制了，一動黑方國王就會被將軍。白方接下來就瞄準d7。",
        "23": "白方往后翼入堡。國王安全了，同時城堡來到d1瞄準d7。一步棋同時完成防守和進攻，非常出色。",
        "24": "黑方把城堡出到d8保護d7。黑方還不能入堡，h8的城堡和f8的主教完全沒有發揮作用。",
        "25": "棄城堡吃d7！白方送出一個城堡，除掉黑方的一個防守棋子。",
        "26": "黑方用城堡吃回。現在d7的城堡也被牽制了，一動b5的主教就會將軍黑方國王。",
        "27": "另一個城堡也來到d1，再次攻擊d7。現在攻擊d7的白子比防守的黑子還多。",
        "28": "黑方皇后到e6，提議換后，想把b3的白方皇后趕走，也想幫忙保護d7。但已經來不及了。",
        "29": "主教吃d7並將軍。白方把黑方的防守棋子一個一個地除掉。",
        "30": "黑方用騎士吃回。f6的騎士離開了，從g5的主教到d8的斜線通了。這條斜線在最後會起作用。",
        "31": "皇后棄在b8並將軍！這是這盤棋最有名的一步。黑方只能用騎士吃，騎士一離開d7，d線就打開了。",
        "32": "黑方用騎士吃。現在已經沒有黑子保護d8了。",
        "33": "城堡到d8，將死！g5的主教支援d8，黑方國王被自己的棋子圍住，無處可逃。白方送出了皇后、城堡和主教，最後只用一個城堡和一個主教結束了對局。快速出子、讓國王安全、趁對方國王還在中間一口氣進攻——這盤最有名的名局包含了所有這些重要的道理。"
      } },
    "reti1910": { "t": "列蒂殺法", "w": "理查·列蒂", "b": "薩維利·塔塔科維", "ev": "一盤輕鬆下的棋（不是比賽）", "d": "1910年", "pl": "奧地利（維也納）", "lead": "兩位後來的大師在維也納輕鬆下的一盤棋，只有11回合。白方棄掉皇后，用兩個棋子同時將軍的「雙將」一舉獲勝。這種殺法以白方的名字命名，叫做「列蒂殺法」。",
      c: {
        "0": "1910年的維也納。白方是20歲的理查·列蒂，黑方是薩維利·塔塔科維。兩人後來都成了世界頂尖棋手，也以為西洋棋帶來新想法而聞名。這不是比賽，而是押了一點小錢的輕鬆對局。雖然很短，卻能清楚看出「早點讓國王安全」有多重要。",
        "1": "白方把國王前的士兵走兩格。佔住中央，後面的棋子就容易出動。主教和皇后的路也打開了。",
        "2": "黑方走c6。不馬上進中央，而是為下一步d5衝擊e4的士兵做準備。這種穩固的開局叫卡羅-康防禦。",
        "3": "白方把另一個士兵也走到d4。兩個士兵並排站在中央，白方佔了很大空間。黑方要想辦法拆掉它們。",
        "4": "照計畫走d5，向e4的士兵發出「我能吃你」的挑戰。白方要決定是保護、前進還是交換。",
        "5": "白方出騎士保護e4。一邊出子一邊防守，一點也不浪費。",
        "6": "黑方吃掉e4的士兵。交換中央的士兵，讓白方的中央變小。",
        "7": "白方用騎士吃回來，騎士站到了棋盤中央。中央的騎士能照顧很多格子，是很強的棋子。",
        "8": "黑方出騎士，和e4的騎士面對面。這裡常見的是主教出到f5，但黑方選擇邀請換騎士。",
        "9": "白方皇后早早來到d3，保護e4的騎士。一般來說皇后不要出得太早，但白方另有打算。請記住，這個皇后站在d線上，正對著黑方國王前方。",
        "10": "黑方走e5，送出一個士兵，為主教和皇后打開通路。這是在中央挑起戰鬥的積極一步。",
        "11": "白方吃掉e5的士兵。白方收下了禮物，但這也讓黑方皇后更容易活動。",
        "12": "將軍！a5的黑方皇后沿斜線瞄準e1的國王，同時還打算吃回e5的士兵，一步兩用。白方必須擋住。",
        "13": "白方把主教放在d2擋住將軍。皇后可以吃這個主教，但白方皇后好好地保護著它。",
        "14": "黑方吃回了士兵，子力又相等了。而且這個皇后沿e線正對著e4的騎士和後面的國王。騎士一走開國王就會被將軍，所以騎士動不了。看起來黑方馬上就能吃掉它。",
        "15": "白方往后翼入堡。國王離開了e線，騎士又能自由行動了。同時城堡來到d1：d1的城堡、d3的皇后和黑方國王旁邊的d8排成一條線。這就是白方的陷阱。",
        "16": "黑方吃掉e4的騎士，好像多得了一子。但黑方國王還在e8，也沒有入堡。白方的棋子都排在d線上，黑方國王身邊空蕩蕩的。這一步導致了失敗，是勝負的分水嶺。",
        "17": "皇后走到d8將軍！把最強的棋子白白送掉。能吃它的黑子只有國王。讓對方吃，就是為了把國王拉到d8這個危險的格子上。",
        "18": "黑方只能用國王吃，沒有別的辦法擋住將軍。國王被拉到了d8，後面還有d1的城堡在等著。",
        "19": "主教從d2走到g5將軍，同時讓開了後面d1城堡的路，城堡也沿d線將軍。兩個棋子同時將軍叫「雙將」。雙將既不能靠吃掉一子解除，也不能用棋子擋住，國王只能逃。",
        "20": "國王逃到c7。如果逃到e8，城堡走到d8就是將死。不管國王逃到哪裡，白方都準備好了致命一擊。",
        "21": "主教走到d8，沿斜線將死c7的國王！主教由d1的城堡保護，國王吃不了它。b8、c8、b7、c6等格子被黑方自己的棋子堵住，d6和d7被城堡控制。只用11回合，白方棄后，用兩個小子取勝。這盤棋告訴我們：不入堡就去吃子，國王會有多危險。也有紀錄說黑方在前一步就認輸了。"
      } },
    "immortal": { "t": "不朽之局", "w": "阿道夫·安德森", "b": "萊昂內爾·基塞里茨基", "ev": "1851年倫敦大賽期間下的一盤非正式對局", "d": "1851年", "pl": "英國（倫敦）", "lead": "世界上第一次國際比賽在倫敦舉行時，兩人在休息時下了這盤棋。白方先後棄掉主教、兩個城堡，最後連皇后也棄掉，只用剩下的三個小子將死對方。據說黑方中途就認輸了，最後幾步可能是白方示範的走法。",
      c: {
        "0": "1851年的倫敦。比賽休息時，德國的安德森（白）和在巴黎很有名的基塞里茨基（黑）輕鬆下了一盤。",
        "1": "白方把國王前的士兵走兩格。",
        "2": "黑方也一樣。",
        "3": "f4！白方送出一個士兵，這叫「王翼棄兵」。目的是把黑方e5的士兵引離中央。",
        "4": "黑方吃下這個士兵。",
        "5": "主教出動，瞄準黑方國王旁邊的f7。",
        "6": "將軍！白方f線的士兵不在了，從h4到e1的斜線是空的。",
        "7": "國王往旁邊讓一步。這樣白方就再也不能入堡了。",
        "8": "黑方也送出一個士兵，想把主教引到b5。",
        "9": "白方吃掉。",
        "10": "騎士出動，攻擊e4的士兵。",
        "11": "白方也出騎士，趕走h4的皇后。",
        "12": "皇后退到h6。",
        "13": "d3保護e4，也給c1的主教讓出了路。",
        "14": "騎士到h5。打算跳到g3將軍，同時攻擊h1的城堡。",
        "15": "白方騎士到h4，準備跳到f5去威脅黑方皇后。",
        "16": "黑方皇后到g5，攻擊h4的騎士。",
        "17": "騎士到f5，這是有e4士兵保護的好位置。它還瞄著g7的士兵。",
        "18": "c6想趕走b5的主教。",
        "19": "白方不救主教，而是用g4趕h5的騎士。",
        "20": "騎士退回f6。",
        "21": "城堡到g1，保護g4的士兵。b5的主教被吃也沒關係，這是很大膽的一步。",
        "22": "黑方吃掉主教，多了一整個子。",
        "23": "白方用h線士兵開始追趕黑方皇后。",
        "24": "皇后到g6。",
        "25": "h5再次追皇后。",
        "26": "皇后只能回到g5。它能走的格子越來越少。",
        "27": "白方皇后到f3。接下來主教如果吃f4，黑方皇后可能就被困住了。",
        "28": "黑方把騎士退回g8，給皇后留出f6這條退路。",
        "29": "主教吃掉f4的士兵，攻擊黑方皇后。",
        "30": "皇后逃到f6。",
        "31": "騎士出動，準備跳到d5攻擊皇后。",
        "32": "主教出動，瞄準g1的城堡。",
        "33": "騎士到d5，攻擊f6的皇后和c7格。g1的城堡被吃也不在乎。",
        "34": "皇后吃掉b2的士兵，攻擊a1的城堡。",
        "35": "主教到d6！白方讓對方吃掉兩個城堡，換來的是圍住黑方國王的一張網。",
        "36": "黑方吃掉g1的城堡。",
        "37": "e5！這個士兵擋住了從b2的皇后到g7的斜線。黑方皇后再也回不來保護國王了。",
        "38": "黑方一邊將軍，一邊吃掉另一個城堡。",
        "39": "國王到e2。白方的大子只剩下皇后、兩個騎士和一個主教。",
        "40": "騎士到a6保護c7。據說黑方在這附近認輸了，後面的走法可能是白方示範的。",
        "41": "騎士吃g7並將軍。",
        "42": "國王逃到d8。",
        "43": "皇后棄在f6並將軍！最後一個大子也送出去了。",
        "44": "黑方只能用騎士吃。",
        "45": "主教到e7，將死！d5的騎士控制e7和c7，g7的騎士控制e8。白方只用一個主教和兩個騎士就贏了。"
      } },
    "mimiaka": { "t": "耳赤之局", "w": "本因坊秀策", "b": "井上幻庵因碩", "ev": "大坂對局（下了三天）", "d": "1846年", "pl": "日本（大坂）", "lead": "17歲的秀策（四段）挑戰當時頂尖棋士之一幻庵（八段）。中盤秀策下出第127手時，據說幻庵的耳朵紅了，因此稱為「耳赤之局」。那時沒有貼目，黑勝2目。",
      c: {
        "0": "1846年，大坂。秀策執黑，幻庵執白。前一天兩人下過一盤讓二子的棋，但中途打掛；這一盤秀策執黑，不放子。",
        "1": "黑1下在右上小目（R16），這個位置容易穩穩地占住角地。",
        "2": "白2下在左上小目（D17）。雙方先分占空角。",
        "5": "黑1、3、5，三個角都下在小目。這是秀策喜歡的下法，後人也常以此為範本。",
        "6": "白6下在左邊C14。不去掛黑角，而是在邊上布局，稍顯少見。",
        "7": "黑7（E4）在左下角再補一手，叫做「守角」，角就非常牢固了。",
        "8": "白8（R5）掛右下黑Q3。右下的大戰由此開始。",
        "10": "白10（O4）就是「大斜」，從遠處斜著罩住黑子，變化極多，是幻庵的拿手好戲。",
        "11": "黑11（Q5）進入了複雜的變化。大斜是對手研究得很深的定式，黑必須小心應對。",
        "24": "右下黑白交錯，雙方都想把對方切斷。白24（N4）之後，黑子很難向外出頭。",
        "25": "黑25（N3）。後來的研究認為這裡有更好的下法。即使是高手也會猶豫的難處。",
        "28": "白28（M3）、30（L2），白立刻抓住黑的漏洞。黑子在下邊快被封在狹窄的地方。",
        "31": "黑31（M4）很重要。為接下來的劫爭（你提我提的爭奪）做準備，預先製造對方必須應的劫材。",
        "36": "白36（N2）。開劫之前，白先在這裡下一手，時機恰到好處。",
        "40": "白40（R1）提掉一子，劫爭開始。被提的一方不能馬上提回，要先到別處找劫材。",
        "41": "黑41（O5）是劫材。雖然有些虧，但此時只能這樣下。",
        "53": "黑53（R10）是一般人想不到的妙想，去破壞右邊白棋的棋形。",
        "60": "白60（S3）是大棋，而且讓白接下來的62（M1）也能先手下到。",
        "63": "黑63（O1），右下的長期戰鬥告一段落。白在下邊得到實地，黑在右邊築起厚勢。目前看來白下得比較好。",
        "67": "黑67（L17）。黑背靠右邊的厚勢，在上邊展開大模樣。",
        "72": "白72（P13）是妙手。下在黑厚勢的上方，阻止黑模樣擴張。",
        "74": "從這裡到第100手左右，幻庵下得一絲不苟，巧妙化解黑的攻擊，白子連成一片。",
        "83": "黑83（H3）打入下邊白空，想盡量減少白地。",
        "96": "從白96（R14）起，圍繞右上黑角展開細緻的戰鬥。白在這裡也走出了好形。",
        "107": "黑107（P10）提掉白一子，右邊黑棋安全了。",
        "118": "白118（M19）提黑一子，上邊白棋也活了。黑上邊的模樣沒有想像中那麼大。",
        "126": "白126（J5）。下邊白棋很厚，並向中央伸展。據說當時觀戰的職業棋士大多認為白棋好。",
        "127": "這就是著名的「耳赤之手」——黑127（K11）。據說中央這一子同時作用於四個方向：擴大上方黑模樣、削弱下方白厚勢、援助右邊黑棋、阻止白向左擴展。",
        "128": "這時，在旁觀戰的一位醫生注意到幻庵的耳朵紅了。他不太懂棋，卻說這是動搖的表現，黑棋大概會贏——這個故事流傳至今。",
        "131": "黑131（D10）。黑也進入左邊白的陣勢，全盤削減白地。",
        "147": "黑147（K10）。第127手那顆子開始發揮作用，黑在中央把白棋分開。",
        "160": "白160（H8）。白一邊守護中央的子，一邊瞄著左下黑棋。勝負仍很細微。",
        "167": "黑167（C2）下得準確。左下角黑棋安全了，白的企圖落空。",
        "175": "黑175（G4）提白一子。下邊白地並沒有起初看起來那麼大。",
        "199": "黑199（K7）。中央戰鬥平息，進入劃定邊界的「官子」階段，一目兩目都要爭。",
        "212": "白212（D19）、216（F19），白在上邊邊緣提掉黑子。官子階段雙方寸步不讓。",
        "228": "白228（N12）在中央形成劫。此後80多手，雙方在M13和N13反覆提子。",
        "236": "白236（T8）是劫爭中提一子的劫材。後來有研究認為，若在此結束劫爭，差距會更小。",
        "275": "黑275（T14）提白兩子。劫爭中，雙方在盤上各處有得有失。",
        "299": "黑299（J16）一舉提掉白四子，上邊黑守得穩穩的。",
        "311": "黑311（M13）消劫，漫長的劫爭終於結束。",
        "325": "325手終局，數子結果黑勝2目。雖然是不貼目的時代，17歲少年戰勝幻庵這樣的頂尖高手仍轟動一時，秀策從此聲名遠揚。"
      } },
    "evergreen": { "t": "常青之局", "w": "阿道夫·安德森", "b": "尚·杜弗雷納", "ev": "一盤輕鬆下的棋（不是比賽）", "d": "1852年", "pl": "德國（一般認為是柏林）", "lead": "下出「不朽之局」的安德森，隔年又下出了這盤名局。就在黑方要將死白方的時候，白方安靜地走了一步城堡，然後棄后，用雙將結束對局。因為它永遠不會褪色，所以叫做「常青之局」。",
      c: {
        "0": "這是1852年刊登在雜誌上的一盤棋。白方是安德森，黑方是他的朋友杜弗雷納。一般認為是在柏林下的，但沒有確切的紀錄。",
        "1": "白方把國王前的士兵走兩格。",
        "2": "黑方也一樣。",
        "3": "騎士攻擊e5的士兵。",
        "4": "黑方用騎士保護e5。",
        "5": "主教出動，瞄準黑方的f7。",
        "6": "黑方也出主教。",
        "7": "b4！送出一個士兵，這叫「埃文斯棄兵」。趁黑方吃兵的時候，白方鞏固中央。",
        "8": "黑方吃兵。",
        "9": "c3趕主教，為下一步d4做準備。",
        "10": "主教退到a5。",
        "11": "d4佔領中央。",
        "12": "黑方吃兵。",
        "13": "白方不吃回，而是入堡。國王的安全和棋子的活躍比士兵更重要。",
        "14": "黑方士兵一直衝到d3，深入白方陣地。",
        "15": "皇后到b3，和c4的主教一起瞄準f7。",
        "16": "黑方用皇后保護f7。",
        "17": "e5趕皇后。",
        "18": "皇后到g6。",
        "19": "城堡到e1，進入e線支援e5的士兵。",
        "20": "黑方出騎士，準備入堡。",
        "21": "主教到a3，沿斜線盯住e7的騎士。這個騎士一走開，主教就能控制f8，所以黑方很難往王翼入堡了。",
        "22": "黑方送出一個士兵，想引開白方的棋子。",
        "23": "皇后吃掉。",
        "24": "城堡到b8，沿b線追皇后。",
        "25": "皇后到a4。",
        "26": "主教退到b6。",
        "27": "騎士出動。白方的棋子幾乎都出來了。",
        "28": "黑方也出另一個主教。",
        "29": "騎士到e4，下一步瞄準f6。",
        "30": "黑方皇后到f5，攻擊e4的騎士。",
        "31": "主教吃掉d3的士兵，同時保護e4的騎士。",
        "32": "皇后到h5，瞄準f3的騎士。",
        "33": "騎士棄在f6並將軍！",
        "34": "黑方用士兵吃。",
        "35": "白方用士兵吃回，攻擊e7的騎士。e線上e1的城堡也盯著e7。",
        "36": "城堡到g8，瞄準g2。如果h5的皇后吃掉f3，將殺就近在眼前。",
        "37": "城堡安靜地走到d1！自己的國王有危險，白方卻不防守，而是把棋子對準d7。正是這一步讓這盤棋成了「常青」。",
        "38": "黑方吃掉f3的騎士。下一步吃g2就是將死。",
        "39": "但白方先走。城堡吃掉e7的騎士並將軍！",
        "40": "黑方用c6的騎士吃回。這樣從a4到d7的斜線就空出來了。",
        "41": "皇后棄在d7並將軍！",
        "42": "只能用國王吃。",
        "43": "主教走到f5將軍，同時讓開了d1城堡的d線：雙將。",
        "44": "國王到e8。如果逃到c6，主教到d7就是將死。",
        "45": "主教到d7將軍。",
        "46": "國王到f8。",
        "47": "a3的主教吃掉e7的騎士，將死！d7的主教控制e8，f6的士兵控制e7和g7。"
      } },
    "lasker1912": { "t": "獵王之局", "w": "愛德華·拉斯克", "b": "喬治·艾倫·湯瑪斯", "ev": "在倫敦城西洋棋俱樂部下的一盤快棋（輕鬆的對局）", "d": "1912年", "pl": "英國（倫敦）", "lead": "在倫敦一家俱樂部裡下的一盤輕鬆的快棋。白方棄后，把黑方國王從g8一路趕到g1，橫越整個棋盤。各種紀錄裡開局的順序稍有不同，但第10回合後的局面是一樣的。",
      c: {
        "0": "1912年10月，倫敦城西洋棋俱樂部。白方是剛從德國來的年輕工程師愛德華·拉斯克，黑方是後來成為英國冠軍的喬治·艾倫·湯瑪斯。這是一盤時間很短、很輕鬆的快棋。它以「獵王」聞名：黑方國王從g8一路被趕到棋盤另一端的g1。拉斯克後來去了美國，因寫西洋棋書而廣為人知。",
        "1": "白方先走d4，皇后前的士兵。它控制e5和c5，也給c1的主教讓出了路。",
        "2": "黑方走e6，先擺出穩固的形狀，準備下一步走f5或d5。",
        "3": "騎士到f3。它控制e5，也幫忙保護王翼，是最自然的位置。",
        "4": "黑方走f5，控制e4格，接近荷蘭防禦。但國王前的士兵動了，黑方國王周圍變得有點弱。",
        "5": "另一個騎士也到c3，準備走e4去衝擊f5的士兵。",
        "6": "黑方也把騎士出到f6，進一步控制e4，同時準備入堡。",
        "7": "主教到g5，瞄準f6的騎士。這個騎士是保護黑方國王的重要棋子，所以白方想早點除掉它。",
        "8": "黑方把主教出到e7保護騎士，入堡的準備也更進一步。",
        "9": "白方用主教換掉騎士。保護黑方國王的騎士不見了。",
        "10": "黑方用主教吃回。現在f6的主教接過了保護王翼的任務。",
        "11": "e4！衝擊f5的士兵，擴大中央。線路打開，白方的棋子更容易活動。",
        "12": "黑方吃掉e4的士兵。不吃的話，白方會走e5把黑方的棋子趕回去。",
        "13": "騎士吃回來站到中央，盯著f6的主教以及g5、d6格。",
        "14": "黑方走b6，準備把主教出到b7，從長斜線瞄準e4的騎士。",
        "15": "騎士到e5，這是中央的好格子，也盯著g4和f7。白方的兩個騎士都靠近了黑方王翼。",
        "16": "黑方入堡，國王到了g8。但f線的士兵不在了，國王周圍有很多空隙。",
        "17": "主教到d3。現在被自己e4的騎士擋住，但再往前就是h7的士兵。e4的騎士一動，這個主教就會直指h7。",
        "18": "黑方主教到b7，從長斜線瞄準e4的騎士，讓白方的棋子不太自由。",
        "19": "皇后到h5，瞄準h7的士兵。h7只有黑方國王保護。白方的皇后、主教和騎士全都對準了黑方國王。",
        "20": "黑方把皇后走到e7。它保護f6的主教，也準備去c5，但黑方沒發現白方的意圖。這裡應該走h6或吃掉e5的騎士。這是勝負的分水嶺。",
        "21": "皇后棄在h7並將軍！把最強的棋子白白送掉。拉斯克已經看清了一路追趕國王直到將死的路線。",
        "22": "黑方只能用國王吃。國王被拉到了h7。",
        "23": "騎士吃掉f6的主教並將軍。同時e4空了出來，d3的主教也將軍h7的國王：雙將。雙將擋不住，國王只能逃。",
        "24": "國王到h6。如果退到h8，另一個騎士跳到g6就是將死。國王被越趕越往前。",
        "25": "另一個騎士從e5跳到g4將軍。它攻擊h6的國王，把國王繼續往前趕。",
        "26": "國王到g5，離開了自己的陣地，向白方那邊走去。",
        "27": "用h線士兵將軍！連士兵也加入了獵王。國王只能繼續往前。",
        "28": "國王到f4。它已經越過棋盤中線，正走進白方陣地。",
        "29": "再用g線士兵將軍。兩個士兵擋住了國王的退路。",
        "30": "國王到f3，正好在白方棋子的包圍中。",
        "31": "主教從d3退到e2將軍。國王被趕得更深了。",
        "32": "國王到g2。離白方國王所在的e1已經不遠了。",
        "33": "城堡到h2將軍。城堡終於也參戰了。",
        "34": "國王終於到了g1。它從g8出發，一直走到了棋盤另一端的第一橫排。",
        "35": "白方國王從e1走到d2。國王讓開後，a1的城堡前面通了，沿第一橫排將軍g1的黑方國王：將死！往后翼入堡也能將死，但拉斯克選擇了走國王。在一盤快棋裡，棄后之後用14回合把國王一直趕到白方陣地的最深處，這是非常罕見的一盤棋。"
      } },
    "toketsu": { "t": "吐血之局", "w": "赤星因徹", "b": "本因坊丈和", "ev": "於老中松平周防守府邸對局（下了四天）", "d": "1835年", "pl": "日本（江戶）", "lead": "這是圍繞棋界最高職位「名人碁所」之爭而下的一局。井上幻庵因碩派弟子赤星因徹挑戰名人丈和。經過四天激戰，因徹落敗，據說他在棋盤前吐了血。",
      c: {
        "0": "1835年。黑方赤星因徹（七段），白方名人本因坊丈和。幻庵派出最得意的弟子，打算一旦獲勝就說：輸給七段的人不配當名人。",
        "1": "黑1下在左下小目（C4），因徹從穩健的一手開始。",
        "4": "四手之後，四個角各有一子：白在右下和左上，黑在左下和右上。",
        "6": "白6（E3）早早地掛左下黑角。丈和一開始就很積極。",
        "10": "白10（P4）在右下角守角。",
        "12": "白12（D6）從上方壓住左下黑角。本局最大的戰鬥由此展開。",
        "13": "黑13（E4）緊貼白子，黑也毫不示弱地應戰。",
        "20": "白20（C3）鑽到黑角下面，一邊掏黑角的實地，一邊設法讓自己的棋子做活。",
        "28": "白28（C9）大步跨入左邊，常被認為是過分之著，是丈和式的強硬一手。",
        "33": "黑33（C2）。據說這是井上家秘密研究的新變化，既攻擊白中央浮棋，又吞掉左邊白子。",
        "36": "白36（F3）。白在左下從外面壓住黑，同時想把自己的子連起來。",
        "43": "黑43（E9）。左邊白子陷入困境。到這裡因徹下得很好，一般認為已經領先。",
        "45": "黑45（D11）沿左邊向上伸展，保持分斷白子，同時加強自己。",
        "50": "白50（C16）。白暫時離開左下，轉向左上角。",
        "53": "黑53（G17）。黑進入上邊，不讓白擴大左上。",
        "58": "白58（C14）從左上角向邊上展開，逼近左邊黑子。",
        "60": "白60（G4）提黑兩子，左下白棋終於稍微喘了口氣。",
        "62": "白62（J17）。上邊黑白也對峙起來，盤上到處都有弱棋，局面複雜。",
        "66": "白66（B14）。白在左上角一帶安頓自己的棋子。",
        "68": "白68（B11）。從這裡開始的幾手白棋以及第80手，後來被傳為「丈和的妙手」，精彩到被說成是「鬼魂教的棋」。",
        "70": "白70（E12）。白沒有直接應左邊黑棋，而是先下另一個要點。因為留有後續的手段，才能這樣下。",
        "72": "白72（R13）。白轉向右邊，不讓黑的右上擴大。",
        "76": "白76（O14）。白連接右邊與中央，準備分斷黑子。",
        "80": "白80（Q10）形成「空三角」，通常被認為是愚形。然而正是這一手，成為把黑棋分成兩塊進行攻擊的據點。常被舉為「形愚而實妙」的典型。",
        "83": "黑83（R3）打入右下白角，接著展開你提我提的激戰。",
        "91": "黑91（Q4）提白一子，右下角對黑來說非常重要。",
        "98": "白98（M4）。白從外面包住下邊黑子，不讓黑輕易做活。",
        "106": "白106（S5）提黑一子。白守住了右下角，黑子只好向外逃。",
        "113": "黑113（K6）。下邊黑子向中央出頭，尋找活路。",
        "120": "白120（N9）擋住逃跑的黑子。中央變成誰先變弱的較量。",
        "128": "白128（L11）從上方繼續壓住中央黑子，黑始終無法安心。",
        "138": "白138（K8）提黑一子，中央開劫。雙方在K8和L8反覆提子，持續約30手。",
        "152": "白152（E11）是劫材。劫爭期間，白不斷在各處找到黑必須應的手。",
        "170": "白170（P15）。中央劫爭告一段落，白轉向右上，瞄準尚未完全活淨的大塊黑棋。",
        "178": "白178（J14）打入上邊中部，要把黑子分成左右兩塊。從第80手開始醞釀的分斷攻擊，在這裡正式展開。",
        "193": "黑193（J11）提白一子。黑也拼命連接，尋找活路。",
        "201": "黑201（R14）提白一子，右邊又開新劫，雙方在R14和R15反覆爭奪。",
        "206": "白206（M13）。劫爭之中，白也一步步收緊對中央黑子的包圍。",
        "222": "白222（L14）提黑一子。上邊黑棋仍被分成兩塊，要兩邊兼顧越來越難。",
        "230": "白230（C13）在左邊也衝擊黑的弱點。盤上的白子已經牢牢連在一起了。",
        "237": "黑237（F12）、239（E13），黑在左上提回白子。儘管如此，全局差距並未縮小。",
        "246": "白246（L8）之後，因徹認輸。據說收拾棋子時，他把血吐在了棋盤上。他的身體大概早已被疾病拖垮，不久便去世了。這一局被稱為丈和一生最大的勝利。"
      } },
    "deepblue1997": { "t": "深藍的勝利", "w": "深藍（IBM的電腦）", "b": "加里·卡斯帕洛夫", "ev": "與IBM深藍的再戰（六局比賽）第6局", "d": "1997年", "pl": "美國（紐約）", "lead": "世界冠軍卡斯帕洛夫，對上IBM製造的西洋棋電腦「深藍」，進行六局比賽。前五局打成平手，最後一局只下了19回合就結束了。這是電腦第一次在多局的正式比賽中戰勝世界冠軍。",
      c: {
        "0": "1997年5月11日，紐約。前一年的比賽是卡斯帕洛夫贏了。這一次前五局後比分是2.5比2.5。深藍執白。",
        "1": "白方把國王前的士兵走兩格。",
        "2": "卡斯帕洛夫走c6，卡羅-康防禦。",
        "3": "白方把另一個士兵也走到中央。",
        "4": "黑方走d5，衝擊e4。",
        "5": "騎士保護e4。",
        "6": "黑方吃掉e4的士兵。",
        "7": "騎士吃回來。",
        "8": "黑方把騎士走到d7，準備再把另一個騎士出到f6。",
        "9": "騎士跳到g5，這是瞄準f7和e6的尖銳走法。",
        "10": "黑方把騎士出到f6。",
        "11": "主教到d3，瞄準黑方王翼。",
        "12": "黑方走e6加強防守。",
        "13": "另一個騎士也出到f3。",
        "14": "黑方走h6，想趕走g5的騎士。但在這個局面裡，白方棄騎士的走法早已為人所知。人們說這不像卡斯帕洛夫的選擇。",
        "15": "騎士棄在e6！據說深藍是從事先存好的開局走法裡走出這一步的。",
        "16": "黑方沒有馬上吃，而是把皇后走到e7。在e線上，它對準了e6的騎士和後面的白方國王。",
        "17": "白方入堡，讓國王離開。",
        "18": "黑方吃掉騎士，子力領先。",
        "19": "主教到g6將軍。f7的士兵不在了，斜線一直通到國王。",
        "20": "國王到d8。黑方再也不能入堡，國王被困在中間附近。",
        "21": "另一個主教也出動，瞄準黑方國王周圍的格子。",
        "22": "黑方走b5，在后翼給國王和主教騰出地方。",
        "23": "a4衝擊b5的士兵。",
        "24": "黑方把主教走到b7。",
        "25": "城堡到e1，在e線上瞄準e6的士兵，以及後面e7的皇后。",
        "26": "黑方騎士到d5，攻擊f4的主教。",
        "27": "主教退到g3。",
        "28": "黑方國王到c8，稍微安全一點。",
        "29": "白方吃掉b5的士兵。",
        "30": "黑方吃回。",
        "31": "皇后到d3，瞄準b5的士兵，也盯著f5格。",
        "32": "黑方用主教保護b5。",
        "33": "主教到f5！可以被白白吃掉。",
        "34": "黑方用士兵吃。但這樣e線上的士兵就沒了。",
        "35": "城堡吃掉e7的皇后。白方送出了騎士、主教和城堡，但換來了對方的皇后。",
        "36": "黑方用主教吃回城堡。",
        "37": "c4！這個士兵同時衝擊b5和d5，黑方的防線開始崩潰。卡斯帕洛夫在這裡認輸了，大概是認為國王太暴露，擋不住白方的進攻。電腦在比賽中戰勝了世界冠軍。"
      } },
    "seigen1933": { "t": "三三·星·天元之局", "w": "吳清源", "b": "本因坊秀哉", "ev": "與秀哉名人的紀念對局（歷時三個多月）", "d": "1933—1934年", "pl": "日本（東京）", "lead": "19歲的吳清源（五段）與名人本因坊秀哉對弈。執黑的吳清源第1手下三三、第3手下星、第5手下天元，打破當時的常識，震驚棋界。對局多次打掛，歷時三個多月，最終白勝2目。",
      c: {
        "0": "1933年。這一年，吳清源與好友木谷實一起推廣被稱為「新布石」的新下法。人們都關注他會如何在名人面前施展。",
        "1": "黑1下在右上三三（R17）。一手就能確保角地，但向外的力量較弱，當時人們並不認為這是開局第一手該下的地方。",
        "3": "黑3下在左下星位（D4）。與三三相反，星位更重視向外發展。",
        "5": "黑5竟然下在棋盤正中央的天元（K10）。不是角也不是邊，而是先占中央。面對名人，他正面展示了新的思路。",
        "6": "三三、星、天元：三顆黑子分別承擔角地、向外發展和中央力量的不同任務。白6（Q16）緊挨著右上黑三三下子。",
        "9": "黑9（P18）。黑在右上角簡潔地安定下來，是三三特有的重實地下法。",
        "11": "黑11（K4）下在天元正下方的下邊中央，與天元配合，想圍出下邊的大模樣。",
        "12": "白12（M3）立刻打入下邊，不讓黑形成大模樣。名人沉著應對，一一化解黑的構想。",
        "13": "黑13（D10），這次下在左邊中央。黑子都在棋盤較高的位置，整體形成大模樣。",
        "14": "白14（E16）在左上角守角。名人沒有被黑的新下法迷惑，沉著地守住角。",
        "21": "黑21（G10）連接天元與左邊的子，黑勢力在中央擴展。",
        "28": "白28（D3）鑽到左下黑星位下面，取得角地。黑以外勢為代價，把角讓給了白。",
        "30": "白30（Q12）在右邊展開，同時罩住右上黑三三的外側，削弱黑的力量。",
        "37": "黑37（P15）提白一子。右上黑白相撞，發生細緻的爭奪。",
        "40": "白40（O10）從右邊向中央邁出一步，逼近天元周圍的黑勢力。",
        "44": "白44（H17）下在上邊，阻止黑子向上發展。",
        "45": "黑45（R7）開始侵入右下白陣。從右邊到右下，接下來戰鬥持續了一段時間。",
        "59": "黑59（R4）也侵入右下角，削減白地。",
        "70": "白70（N6）從下邊向中央延伸，企圖分開黑右下與中央的子。",
        "79": "黑79（L9）以天元為中心鞏固中央。到這裡可說是勢均力敵。",
        "80": "白80（C6）從左下角向左邊推進，瞄準黑左邊的子。",
        "98": "白98（A11）提黑兩子。白在左邊邊緣巧妙做活，黑的左邊比預想的小。",
        "101": "黑101（S14）回到右上，削減右邊白陣。",
        "105": "黑105（K17）下在上邊中央，開始攻擊白在上邊的子。",
        "117": "黑117（F17）在左上也侵入白角周圍，整個上邊都打了起來。",
        "124": "白124（K15）一邊把上邊白子向中央逃出，一邊從黑子之間穿過。",
        "135": "黑135（E9）提白兩子，在左邊扳回一些。",
        "138": "白138（N18）在上邊鞏固實地。從全局看，形勢非常細微。",
        "153": "黑153（K14）。中央黑子形成連接上下的粗壯通道。白如何突破這片厚勢，是勝負的關鍵。",
        "159": "黑159（F4）穩守左下。白的下一手，成了本局最有名的一手。",
        "160": "白160（H8）跳進黑厚勢的縫隙，是一步銳利的棋，同時帶有多重目的，白由此開始侵蝕黑的中央。有傳言說這手棋是秀哉的弟子發現的，但並無確證。",
        "161": "黑161（J8）立即應對，但白的目的不止一個。",
        "162": "白162（K12）轉到中央上方，威脅黑子之間的連接。",
        "172": "白172（F13）把中央與左上的子連起來，黑中央的厚勢漸漸無法轉化為實地。",
        "178": "白178（N9）在中央右側也侵入黑空。",
        "187": "黑187（M6）、189（L7）提掉白子應對。儘管如此，白已搶先占到了要點。",
        "198": "白198（E12）提黑一子。左上白子也連通了，白全局略為領先。",
        "203": "黑203（B3）。從這裡進入官子，逐目確定邊緣的邊界。",
        "224": "白224（T10）提黑一子。在右邊邊緣，白也一目不讓。",
        "233": "黑233（L13）提白兩子，黑堅持追趕到最後。",
        "252": "252手終局，白勝2目。沒有貼目的時代，先行的黑稍占便宜，但名人始終不亂，贏到了最後。儘管如此，吳清源的三三、星、天元引起轟動，宣告了新布石時代的到來。"
      } },
    "century1956": { "t": "世紀之局", "w": "唐納德·伯恩", "b": "巴比·費雪", "ev": "第三屆羅森瓦爾德杯賽（羅森瓦爾德紀念賽）", "d": "1956年", "pl": "美國（紐約）", "lead": "13歲的巴比·費雪戰勝了美國強手唐納德·伯恩。第17回合，費雪讓對方白白吃掉自己的皇后，然後一個接一個地把棋子贏回來，最後用小子們圍捕白方國王。費雪後來成為了世界冠軍。",
      c: {
        "0": "1956年10月17日，紐約的一場比賽。執黑的是13歲的費雪，執白的是美國頂尖棋手之一伯恩。",
        "1": "白方先出騎士。",
        "4": "費雪走g6，準備把主教放到長斜線上。",
        "8": "黑方入堡，先讓國王安全。",
        "10": "黑方走d5，中央爭奪開始了。",
        "15": "白方走e4，中央有了兩個並排的士兵。",
        "17": "城堡到d1，支援d4的士兵。白方還沒有入堡。",
        "18": "騎士到b6，趕c4的皇后。",
        "20": "主教到g4，牽制f3的騎士。",
        "21": "白方的主教也到g5。白方國王還在中間。",
        "22": "騎士到a4！故意跳到會被吃的地方。想法是：c3的騎士一離開，e4的士兵就沒人保護了。",
        "23": "白方不吃騎士，把皇后移到a3。",
        "26": "黑方騎士吃掉e4的士兵，白方中央開始崩潰。",
        "27": "白方主教吃掉e7的士兵，同時攻擊黑方皇后和f8的城堡。",
        "28": "皇后到b6！黑方讓f8的城堡被吃也沒關係。費雪看準了白方國王還在中間。",
        "29": "白方沒有吃城堡，而是出主教。",
        "30": "騎士吃掉c3的士兵，攻擊d1的城堡。",
        "31": "主教到c5，攻擊b6的黑方皇后。",
        "32": "城堡在e線將軍！",
        "33": "國王到f1。這樣白方再也不能入堡了。",
        "34": "主教到e6！這是這盤棋最有名的一步：讓對方白白吃掉自己的皇后。作為交換，黑方計畫一個接一個地把棋子贏回來。",
        "35": "白方吃掉黑方皇后。",
        "36": "主教到c4將軍，黑方的反擊開始了。",
        "38": "騎士在e2將軍。",
        "40": "國王回到f1時，騎士一走開，c4的主教就形成了閃擊將軍。騎士順便吃掉了d4的士兵。",
        "44": "騎士回到c3，又是閃擊將軍，這次攻擊d1的城堡。一邊連續將軍一邊吃子，這叫「風車」。",
        "46": "黑方吃回主教。c3的騎士還在攻擊d1的城堡。",
        "50": "騎士吃掉d1的城堡。現在黑方贏回的已經比送出的皇后還多，明顯領先。",
        "52": "城堡也吃掉a2的士兵。",
        "56": "黑方兌換城堡。棋子越少，子力多的一方越有利。",
        "57": "白方皇后將軍。",
        "58": "黑方用主教擋住。",
        "64": "b5，黑方士兵開始前進。",
        "68": "國王走到g7，讓f8的主教可以活動。",
        "70": "現在黑方的棋子開始圍捕白方國王。用主教將軍。",
        "72": "騎士在g3將軍。",
        "74": "用另一個主教將軍。",
        "76": "主教到b3將軍。",
        "78": "騎士在e2將軍。",
        "80": "騎士在c3將軍，白方國王被追來追去。",
        "82": "城堡到c2：將死！城堡、兩個主教和騎士齊心協力。一個13歲的少年，展示了這麼多棋子如何像一個團隊一樣配合。"
      } },
    "oshiro1849": { "t": "秀策的第一局御城碁", "w": "本因坊秀策", "b": "安井算知（九世）", "ev": "御城碁（每年在江戶城舉行的對局）", "d": "1849年", "pl": "日本（江戶）", "lead": "御城碁是各圍棋家元的棋士每年在將軍城中對弈的盛會。20歲的秀策這一年首次出場，執黑勝11目。由此開始了他在御城碁中19戰全勝的不敗紀錄。",
      c: {
        "0": "1849年。秀策前一年被定為本因坊家的繼承人，這一年首次出場御城碁。據說御城碁多是事先在別處下好，再到城中覆盤重擺。",
        "1": "黑1下在右上小目（R16）。秀策一如往常，從穩健的小目開始。",
        "4": "白4（C15）掛左上黑D17，布局階段左上就開始了戰鬥。",
        "5": "黑5（C11）從下方夾擊掛過來的白子，不讓白在左邊輕鬆安定。",
        "12": "白12（C17）。左上角歸白，黑得到外側。雙方都可接受的轉換。",
        "13": "黑13（J17）利用外側黑子，在上邊展開。",
        "15": "黑15（C5）占據最後一個空角——左下角。四個角都有子了。",
        "16": "白16（E4）立刻逼近這顆黑子，左下也打了起來。",
        "19": "黑19（D2）牢牢確保左下角的實地，是秀策式的穩健下法。",
        "23": "黑23（E5）從白子之間出頭，加強左下黑棋。",
        "29": "黑29（F11）補強左邊黑子，同時著眼中央。",
        "30": "白30（H4）在下邊展開，一邊壓迫左下黑棋，一邊構築自己的陣地。",
        "31": "黑31（O3）掛右下白角。",
        "33": "黑33（R3）緊貼白角的子。此後黑在外側，白沿邊上的三線伸展。",
        "43": "黑43（Q8）。右邊形成了上下相連的黑色厚壁。白取得角和邊的實地，黑獲得外勢。",
        "44": "白44（L17）打入上邊黑子之間，不讓黑陣地過大。",
        "50": "白50（R18）鑽進右上黑角下方，瞄準角地。",
        "51": "黑51（P13）。黑背靠右邊厚壁，從右邊到中央構築大陣地。",
        "52": "白52（D10）打入左邊黑子之間，左邊黑白糾纏在一起。",
        "63": "黑63（B10）在左邊邊緣落子，不讓白子在這裡建立根據地。",
        "65": "黑65（G3）也侵入下邊白陣，削減白地。",
        "73": "黑73（K17）鞏固上邊黑子，讓白44那顆子陷入困境。",
        "76": "白76（P11）打入黑右邊陣地。這顆子是死是活，將大大影響地的多少。",
        "77": "黑77（Q11）從厚壁一側應對，把白趕向中央。守地的同時進攻，是秀策式的沉穩應手。",
        "80": "白80（N10）向中央逃出，試圖擺脫黑的追擊。",
        "85": "黑85（N12）一邊攻擊，一邊擴大上邊和右邊的實地。借攻得利，運籌巧妙。",
        "91": "黑91（J7）下在下邊白子上方，從中央方向壓住白陣。",
        "100": "白100（S17）在右上角動手，想削減黑的角地。",
        "119": "黑119（R17）穩守右上角，化解了白的手段。",
        "122": "白122（G6）繞到左下黑子外側，企圖切斷它與中央黑子的聯繫。",
        "131": "黑131（M5）在下邊中部楔入白陣。",
        "140": "白140（B4）在左下黑角動手，左邊邊緣開始了細緻的提子爭奪。",
        "156": "白156（A8）提黑兩子。左邊邊緣的爭奪在雙方互有所得後平息。",
        "158": "白158（L10）。白在中央仍有子，試圖削減黑中央的實地。",
        "162": "白162（O12）提黑一子。儘管如此，黑右邊的陣地仍然很大。",
        "172": "白172（K18）。從這裡進入官子，先確定上邊的邊界。",
        "186": "白186（T16）在右上邊緣削減黑地。官子階段，雙方都先下最大的地方。",
        "205": "黑205（Q18）封住上邊右側，確定實地。",
        "223": "黑223（P10）確定右邊黑地與逃向中央的白子之間的邊界。",
        "233": "黑233（Q9）提白一子。黑右邊的實地基本守住了。",
        "239": "黑239（A6）提白一子，左邊邊緣形成劫。一目一目的爭奪一直持續到最後。",
        "260": "白260（T6）提黑一子，右下邊緣也成劫。黑在263（T5）提回。",
        "267": "267手終局，黑勝11目。沒有冒大險，而是邊攻擊邊自然擴大實地，是秀策式的勝法。這是他御城碁19連勝的第一局。"
      } },
    "shilin": { "t": "《事林廣記》順手炮局", "w": "紅方（姓名未流傳）", "b": "黑方（姓名未流傳）", "ev": "日用百科《事林廣記》「饒先順手取勝局」", "d": "13世紀", "pl": "中國（宋元之際）", "lead": "這是宋末元初陳元靚編寫的日用百科《事林廣記》中收錄的棋譜，被認為是現存最古老的象棋全局譜之一。這是一盤強者讓對方先走的「饒先」示範局，短短9個回合，黑馬就捉住了紅車。",
      c: {
        "0": "這是七百多年前、宋元之際的棋譜。它收在百科全書《事林廣記》講遊戲的部分，被認為是現存最古老的象棋全局紀錄之一。對局雙方的名字沒有流傳下來。「饒先」是強者把先手讓給弱者，所以這盤棋是在示範先走的紅方怎樣輸掉。紅方在下方，先走。",
        "1": "紅方把右邊的炮移到中路。這叫「中炮（當頭炮）」，正對著黑將，至今仍是最強的開局之一。可見七百年前人們就已經在下這種佈局了。",
        "2": "黑方也把炮移到中路，正面對峙。雙方都動同一側的炮，叫做「順手炮」。炮對炮的較量，自古以來就很受歡迎。",
        "3": "紅方跳馬保護中兵。中兵正被黑炮瞄著，需要有子保護。同時，這匹馬也準備向前出動。",
        "4": "黑方也跳馬保護中卒。雙方擺出相同的陣形，先把根基打牢。",
        "5": "紅方把右車橫移一步，走到可以直衝的路線上。車是棋盤上最強的子，越早出動越好。",
        "6": "黑方又跳出一匹馬，暫時不出車。先把子力向前展開是一種思路，但車出得太晚，之後就不容易參加進攻。",
        "7": "紅車一下子過河，衝進黑方陣地。它想威脅黑子，可是紅方其他子都還在家裡，這樣進攻有點急。也可以先出動左邊的馬或車。",
        "8": "黑方挺起3路卒，給馬讓出道路，以後馬就能向前跳。黑方幾乎是在等紅車過來。",
        "9": "紅車吃掉一個卒，同時瞄著後面的黑馬。得了一子又捉馬，看起來很痛快。可是這輛車衝得太遠，身邊沒有幫手。孤車深入敵陣，很容易被追打。",
        "10": "黑馬向前跳出，既躲開紅車，又靠近紅方陣地，一步棋做了兩件事。這匹馬就是本局的主角。",
        "11": "紅車退一步，從側面再捉黑馬。車能遠距離吃子，馬一刻也不能停。不過這步棋同樣沒有讓其他紅子出動。",
        "12": "黑馬繼續前進，過河進入紅方陣地。每躲一次紅車，它就離紅帥更近一步。",
        "13": "紅方挺起一個兵，給自己的馬讓路。想法是接著出馬，和黑馬兌換。可是這就給了黑方繼續前進的時間。",
        "14": "黑方飛象，攻擊紅車。用防守的象趕走對方的車，非常經濟。紅車只好再走，黑方又賺了一步。",
        "15": "紅車橫走，又吃掉一個卒。雖然多得了兩個卒，但這正是輸棋的一步。車離帥太遠，再也回不來防守了。這裡需要防備黑馬，比如把車調回來。",
        "16": "黑馬跳得更深，捉住紅車。不只如此：馬再跳一步，就能將軍紅帥，同時捉住紅方角上的車。一匹馬同時造成了兩個威脅。",
        "17": "紅車追捉黑馬，可是馬已經擋不住了。紅帥身邊已經沒有任何保護。",
        "18": "黑馬跳入將軍！這匹馬同時還捉著紅方角上的車，紅帥一躲，車就會被吃掉。雖然只有9個回合，但這盤棋告訴我們：孤車冒進會有什麼下場，子力要互相配合才能作戰。七百年前的人們，也在同樣的棋盤上思考著同樣的事情。"
      } },
    "qima13": { "t": "棄馬十三著（《橘中秘》）", "w": "紅方（姓名未流傳）", "b": "黑方（姓名未流傳）", "ev": "《橘中秘》卷上 第一局「順炮橫車破直車棄馬」", "d": "1632年（刊行）", "pl": "中國（明）", "lead": "這是明代朱晉楨於1632年（崇禎五年）刊行的棋書《橘中秘》中最開頭的一局。紅方故意讓黑方白吃一匹馬，趁機殺入，13個回合就將死對方。「棄馬十三著」這個名字，在將近400年後的今天依然廣為人知。",
      c: {
        "0": "這是明朝末年、1632年出版的棋書《橘中秘》的第一局。《橘中秘》和後來的《梅花譜》並稱為象棋兩大古典名譜。這盤棋不是實戰，而是用來講解戰術的示範局，所以沒有對局者的名字。紅方在下方先走，只用13個回合就分出勝負。",
        "1": "紅方把右炮移到中路，正對黑將，這是「中炮」。《橘中秘》正是以深入研究中炮攻法而聞名的書。",
        "2": "黑方也把同一側的炮移到中路，形成炮與炮正面碰撞的「順手炮（順炮）」。雙方都瞄著對方的中兵（中卒）。",
        "3": "紅方跳馬保護中兵。既守住被黑炮瞄著的兵，馬也開始發揮作用。",
        "4": "黑方也跳馬保護中卒。到這裡為止，雙方陣形完全一樣。",
        "5": "紅方把右車向前走一步。這樣下一步車就能橫著走。能橫向移動的車叫「橫車」，好處是可以快速調到左右兩邊。",
        "6": "黑方把車橫移一步，變成可以直著前進的「直車」。橫車對直車，兩種不同用法的車互相對峙，形成「順炮橫車對直車」。",
        "7": "紅方的橫車大幅移到左側的路線上。這條路線緊挨著黑方的士，是對方防守薄弱的地方。紅方準備從這裡一舉殺入。",
        "8": "黑方的直車過河，深深打入紅方陣地。黑方也想以對攻來對抗。不過這是一步先急於進攻、而顧不上防守的棋。",
        "9": "紅車一直衝到黑方陣地深處。這裡正是象要經過的「象眼」，黑象被塞住無法行動。車緊貼著士，也離黑將非常近了。",
        "10": "黑方把另一匹馬跳到邊線。這也考慮到要防止紅車從側面橫插進來。",
        "11": "這就是「棄馬」的一步！紅方把另一輛車抬起一步。這樣一來，左角的馬沒有子保護，會被黑炮白白吃掉。但紅方用一匹馬，換來了讓兩輛車迅速投入進攻的時間。",
        "12": "黑炮吃掉紅馬，看起來賺了一子。可是這門炮已經無法回去保護自己的陣地。一般認為，這裡不吃馬、而是補士鞏固防守更好。",
        "13": "紅炮向前進。它把中路的黑炮當作「炮架」跳過去，瞄準後面的黑馬。炮是一種隔一個子才能吃子的奇妙棋子。",
        "14": "黑方退馬逃跑。可是這匹馬本來是保護中卒的重要棋子。它一走，中路防守就出現了漏洞。黑方還有別的防法，但這是最差的選擇。",
        "15": "紅炮打掉中卒，將軍！剛才黑馬離開了，中路空空蕩蕩。紅方的攻勢從這裡一下子展開。",
        "16": "黑方補士，擋在將的前面。要解除將軍，這幾乎是唯一的辦法。",
        "17": "紅方的第二輛車也來到同一條路線上。兩輛車縱向連在一起，力量非常強大。下一步就要殺入黑方陣地深處。",
        "18": "黑將向旁邊躲開。如果不動，就會被紅方兩輛車在同一條直線上瞄著。",
        "19": "紅方用前車吃掉黑士，將軍！這輛車馬上會被另一個士吃掉，但這也在計算之中。棄掉一輛車，拆毀黑將身邊的防守，真是大膽的一著。",
        "20": "黑方用士吃掉紅車。論子力，黑方已經大大領先。可是將的周圍變得更加空虛。",
        "21": "紅方剩下的車移到將所在的路線上，再次將軍。黑將身邊幾乎已經沒有保護它的子了。",
        "22": "黑方把炮墊在將前，擋住將軍。這種在中間放一個子的應法叫「墊將」。",
        "23": "紅車吃掉這門炮，又將軍。紅車一邊吃掉黑子，一邊把黑將逼入絕境。",
        "24": "黑將只能回到中間。其他位置全都被紅子控制著。",
        "25": "最後紅炮來到中路，兩門炮縱向重疊，將軍。前面的炮當炮架，後面的炮瞄準黑將，這就是「重炮」殺。黑將無處可逃，紅方獲勝。只棄掉一匹馬，紅方就在13個回合內取勝。這盤棋四百年來一直告訴我們：比起子力多少，時間（先手）和子力的活躍更加重要。"
      } }
  },
  "ko": {
    ui: {"lead":"명국을 한 수씩. Musowl의 해설을 들으며 보드 위에서 명국을 따라가 보세요.","all":"전체","k_chess":"체스","k_shogi":"쇼기","k_go":"바둑","k_xiangqi":"샹치","side_r":"홍","res_r":"홍 승","back":"명국선으로 돌아가기","start":"처음","prev":"한 수 뒤로","next":"한 수 앞으로","end":"마지막","play":"자동 재생","pause":"멈춤","moves":"기보","move":"{n}수째","startpos":"시작 국면","nextnote":"다음 해설로 ({n}수째)","quiet":"이 수에는 해설이 없습니다.","guide":"Musowl","keys":"← → 로 한 수씩","result":"결과","r_event":"대국","r_date":"연도","r_place":"장소","side_w":"백","side_b":"흑","side_s":"선수","side_g":"후수","side_B":"흑","side_W":"백","res_w":"백 승","res_b":"흑 승","res_d":"무승부","res_s":"선수 승","res_g":"후수 승","credit":"기보는 널리 알려진 공개 기록입니다. 해설은 박물관의 Musowl이 썼습니다."},
    "opera": { "t": "오페라 하우스 게임", "w": "폴 모피", "b": "브라운슈바이크 공작 카를 2세와 이주아르 백작", "ev": "오페라 극장의 박스석에서 둔 한 판 (두 사람이 상의하며 둠)", "d": "1858년", "pl": "프랑스 (파리)", "lead": "젊은 미국 챔피언이 오페라 공연 중에 귀족 두 사람을 상대로 둔 17수. 기물을 빨리 꺼내고, 망설임 없이 희생하고, 마지막에는 적은 기물로 끝냅니다. 체스 교과서에 가장 자주 실리는 한 판입니다.",
      c: {
        "0": "1858년 파리. 21살의 미국인 폴 모피는 유럽의 강한 선수들을 차례로 꺾고 있었습니다. 그날 밤 오페라 극장의 박스석에서 브라운슈바이크 공작과 이주아르 백작 두 사람이 상의하며 흑을 잡고 모피에게 도전했습니다. 모피는 무대도 보고 싶어서 빨리 끝내고 싶었다고도 합니다. 기물을 빨리 꺼내고 킹을 안전하게 하는 체스의 기본이 가득 담긴 17수입니다.",
        "1": "백은 킹 앞의 폰을 두 칸 전진합니다. 중앙의 d5와 e5를 노리고, 비숍과 퀸의 길도 엽니다.",
        "2": "흑도 e5. 폰끼리 중앙에서 마주 보아 백의 폰이 더 나아갈 수 없습니다.",
        "3": "나이트가 f3으로 나와 e5 폰을 노립니다. 기물을 꺼내면서 상대가 수비를 생각하게 만드는 좋은 수입니다.",
        "4": "흑은 d6으로 e5를 지킵니다. 필리도르 디펜스라고 부르는 모양입니다. 튼튼하지만 f8 비숍의 길이 조금 좁아집니다.",
        "5": "백은 d4로 다른 폰도 중앙에 내보내 e5에 부딪힙니다. 흑은 잡을지 지킬지 정해야 합니다.",
        "6": "흑의 비숍이 g4로. f3의 나이트를 압박하는데, 그 뒤에는 d1의 백 퀸이 있습니다. 나이트가 움직이면 퀸이 잡히니 나이트는 e5를 잡으러 갈 수 없습니다.",
        "7": "백은 폰으로 e5를 잡습니다. 흑이 바로 d6 폰으로 다시 잡으면, 백이 퀸을 교환한 뒤 나이트가 e5 폰을 잡아 버립니다. 그래서 흑은 먼저 f3의 나이트를 없애고 싶어 합니다.",
        "8": "흑은 비숍으로 나이트를 잡습니다. 이제 e5를 안전하게 되찾을 수 있습니다. 하지만 막 나온 비숍을 나이트와 바꾸면서 흑의 전개가 늦어집니다.",
        "9": "퀸으로 다시 잡습니다. 백의 퀸은 벌써 중앙 가까이에서 일하기 시작했고, 흑은 아직 기물을 거의 꺼내지 못했습니다.",
        "10": "흑은 폰으로 다시 잡아 기물 수는 같습니다. 하지만 나와 있는 기물 수로는 백이 앞섭니다.",
        "11": "비숍이 c4로. f3의 퀸과 함께 f7을 노립니다. f7은 킹만 지키는 약한 칸이라 잡히면 메이트입니다.",
        "12": "흑은 나이트를 f6으로 꺼내 f줄을 막습니다. 이것이 없으면 퀸이 f7을 잡아 메이트였습니다. 기물을 꺼내며 지키는 올바른 대응입니다.",
        "13": "퀸이 b3으로 방향을 바꿔 f7과 b7을 동시에 노립니다. 두 가지를 동시에 노리는 수는 상대가 둘 다 지킬 수 없어 강력합니다.",
        "14": "흑은 퀸을 e7로 옮겨 f7을 지키고 b7은 내줍니다. 그런데 퀸이 f8 비숍의 길을 막아 버렸습니다.",
        "15": "모피는 b7 폰을 잡지 않고 나이트를 꺼냈습니다. 폰을 잡으면 퀸이 멀리 가 버립니다. 폰보다 기물을 빨리 움직이는 것을 택한, 모피다운 수입니다.",
        "16": "흑은 c6으로 d5와 b5를 누르고, 퀸이 b6으로 나갈 길도 만듭니다.",
        "17": "비숍이 g5로 가서 f6 나이트를 핀합니다. 나이트가 움직이면 뒤에 있는 e7의 퀸이 잡힙니다. 흑의 기물은 점점 움직이기 어려워집니다.",
        "18": "흑은 b5로 c4의 비숍을 쫓으려 합니다. 퀸 쪽에 공간도 만들지만, 백의 기물이 뛰어들 틈도 생겼습니다.",
        "19": "나이트를 버리며 b5 폰을 잡습니다! 비숍을 피하는 대신 공격을 멈추지 않는 것이 모피의 방식입니다. 킹이 아직 가운데에 있는 흑에게는 매우 무서운 수입니다.",
        "20": "흑은 나이트를 잡아 나이트 하나를 앞섭니다. 하지만 흑 킹은 아직 e8에 있고, 백의 기물이 계속 모여듭니다.",
        "21": "비숍이 b5에서 체크! 흑 킹은 아직 가운데에 갇혀 있습니다. 백은 나이트 하나로 폰 두 개를 얻고 킹에게 곧장 다가갑니다.",
        "22": "흑은 나이트를 d7에 놓아 체크를 막습니다. 하지만 이 나이트는 핀되어 움직이면 흑 킹이 체크를 당합니다. 백은 이제 d7을 노립니다.",
        "23": "백은 퀸 쪽으로 캐슬링. 킹이 안전해지고, 동시에 룩이 d1로 와서 d7을 노립니다. 한 수로 수비와 공격을 모두 해내는 훌륭한 수입니다.",
        "24": "흑도 룩을 d8로 꺼내 d7을 지킵니다. 흑은 아직 캐슬링을 못 했고, h8의 룩과 f8의 비숍은 전혀 일하지 못하고 있습니다.",
        "25": "룩을 버리며 d7을 잡습니다! 룩 하나를 내주고 흑의 수비 기물을 하나 없앱니다.",
        "26": "흑은 룩으로 다시 잡습니다. 이제 d7의 룩도 핀되어, 움직이면 b5의 비숍이 흑 킹을 체크합니다.",
        "27": "다른 룩도 d1로 와서 d7을 다시 노립니다. 이제 d7을 공격하는 백 기물이 지키는 흑 기물보다 많아졌습니다.",
        "28": "흑의 퀸은 e6으로. 퀸 교환을 제안해 b3의 퀸을 쫓아내고 d7도 도우려 하지만, 이미 늦었습니다.",
        "29": "비숍이 d7을 잡으며 체크. 백은 흑의 수비 기물을 하나씩 없애 갑니다.",
        "30": "흑은 나이트로 다시 잡습니다. f6의 나이트가 사라져서 g5 비숍에서 d8까지 대각선이 열렸습니다. 이 길이 마지막에 큰 역할을 합니다.",
        "31": "퀸을 b8에 버리며 체크! 이 판에서 가장 유명한 수입니다. 흑은 나이트로 잡을 수밖에 없고, 나이트가 d7을 떠나면 d줄이 열립니다.",
        "32": "흑은 나이트로 잡습니다. 이제 d8을 지키는 흑 기물이 없습니다.",
        "33": "룩이 d8로. 체크메이트! g5의 비숍이 d8을 받치고, 흑 킹은 자기 기물에 둘러싸여 도망칠 수 없습니다. 백은 퀸, 룩, 비숍을 내주고 마지막엔 룩과 비숍 두 개만으로 끝냈습니다. 기물을 빨리 꺼내고, 킹을 안전하게 하고, 상대 킹이 가운데 있을 때 한꺼번에 공격한다—이 유명한 명국에는 그 중요한 생각이 모두 담겨 있습니다."
      } },
    "reti1910": { "t": "레티의 메이트", "w": "리하르트 레티", "b": "사비엘리 타르타코베르", "ev": "가볍게 둔 한 판 (대회가 아님)", "d": "1910년", "pl": "오스트리아 (빈)", "lead": "나중에 대가가 되는 두 사람이 빈에서 가볍게 둔 11수의 한 판. 백은 퀸을 버리고, 두 기물로 동시에 체크하는 \"더블 체크\"로 단숨에 끝냅니다. 이 메이트 모양은 백의 이름을 따서 \"레티의 메이트\"라고 불립니다.",
      c: {
        "0": "1910년 빈. 백은 20살의 리하르트 레티, 흑은 사비엘리 타르타코베르입니다. 두 사람 모두 이후 세계 정상급 선수가 되었고, 체스에 새로운 생각을 들여온 것으로도 유명합니다. 이것은 대회가 아니라 작은 돈을 건 가벼운 한 판이었습니다. 짧지만 \"킹을 일찍 안전하게 하는 것\"이 왜 중요한지 잘 보여 줍니다.",
        "1": "백은 킹 앞의 폰을 두 칸 전진합니다. 한가운데를 잡으면 뒤에 있는 기물이 나오기 쉬워집니다. 비숍과 퀸의 길도 열렸습니다.",
        "2": "흑은 c6. 바로 중앙으로 나가지 않고, 다음에 d5로 e4 폰에 부딪히기 위한 준비입니다. 이 탄탄한 오프닝을 카로칸 디펜스라고 합니다.",
        "3": "백은 다른 폰도 d4로. 두 폰이 중앙에 나란히 서서 백이 넓은 공간을 차지했습니다. 흑은 이것을 무너뜨리려 합니다.",
        "4": "계획대로 d5. e4 폰에 \"잡을 수 있어\"라고 부딪힙니다. 백은 지킬지, 전진할지, 교환할지 정해야 합니다.",
        "5": "백은 나이트를 꺼내 e4를 지킵니다. 기물을 꺼내면서 지키니 낭비가 없는 수입니다.",
        "6": "흑은 e4 폰을 잡습니다. 중앙 폰을 교환해서 백의 중앙을 작게 만들려는 생각입니다.",
        "7": "백은 나이트로 다시 잡고, 나이트가 판 한가운데에 섭니다. 중앙의 나이트는 많은 칸에 닿는 강한 기물입니다.",
        "8": "흑은 나이트를 꺼내 e4의 나이트와 마주 봅니다. 여기서는 비숍을 f5로 꺼내는 수가 자주 쓰이지만, 흑은 나이트 교환을 권했습니다.",
        "9": "퀸이 일찍 d3으로 나와 e4 나이트를 지킵니다. 보통은 퀸을 너무 일찍 꺼내지 않지만, 백에게는 계획이 있었습니다. 이 퀸이 흑 킹 앞의 d줄에 있다는 것을 기억해 두세요.",
        "10": "흑은 e5. 폰 하나를 내주며 비숍과 퀸의 길을 열려고 합니다. 중앙에서 싸움을 거는 적극적인 수입니다.",
        "11": "백은 e5 폰을 잡습니다. 주는 것을 받았지만, 그 덕분에 흑의 퀸이 움직이기 쉬워졌습니다.",
        "12": "체크! a5의 흑 퀸이 대각선으로 e1의 킹을 노립니다. 동시에 e5 폰을 되찾을 생각도 있는, 일석이조의 수입니다. 백은 막아야 합니다.",
        "13": "백은 비숍을 d2에 놓아 체크를 막습니다. 퀸이 비숍을 잡을 수도 있지만, 백의 퀸이 잘 지키고 있습니다.",
        "14": "흑은 폰을 되찾아 기물 수가 다시 같아졌습니다. 게다가 이 퀸은 e줄을 따라 e4의 나이트와 그 뒤의 킹을 일직선으로 보고 있습니다. 나이트가 움직이면 킹이 체크를 당하니, 나이트는 움직일 수 없습니다. 흑이 곧 그 나이트를 잡을 것처럼 보입니다.",
        "15": "백은 퀸 쪽으로 캐슬링. 킹이 e줄을 벗어나 나이트가 다시 자유로워졌습니다. 동시에 룩이 d1로 와서, d1의 룩, d3의 퀸, 흑 킹 옆의 d8이 한 줄로 늘어섭니다. 이것이 백의 함정입니다.",
        "16": "흑은 e4의 나이트를 잡아 기물 하나를 번 것처럼 보입니다. 하지만 흑 킹은 아직 e8에 있고 캐슬링도 하지 않았습니다. 백의 기물은 d줄에 모여 있고 흑 킹 주변은 텅 비었습니다. 패배로 이어진 이 수가 승부의 갈림길이었습니다.",
        "17": "퀸을 d8에 버리며 체크! 가장 강한 기물을 공짜로 내줍니다. 이 퀸을 잡을 수 있는 흑의 기물은 킹뿐입니다. 잡게 해서 킹을 d8이라는 위험한 칸으로 끌어내려는 것입니다.",
        "18": "흑은 킹으로 잡을 수밖에 없습니다. 체크를 막을 다른 방법이 없었습니다. 킹은 d8로 끌려 나왔고, 그 뒤에는 d1의 룩이 기다리고 있습니다.",
        "19": "비숍이 d2에서 g5로 가며 체크. 동시에 뒤에 있던 d1 룩의 길이 열려 룩도 d줄로 체크합니다. 두 기물로 동시에 체크하는 \"더블 체크\"입니다. 더블 체크는 한 기물을 잡아도, 사이에 기물을 넣어도 막을 수 없어 킹이 도망칠 수밖에 없습니다.",
        "20": "킹은 c7로 도망칩니다. e8로 갔다면 룩이 d8로 와서 메이트였습니다. 어디로 가도 백에게는 마무리 수가 준비되어 있습니다.",
        "21": "비숍이 d8로. 대각선으로 c7의 킹을 체크메이트! 비숍은 d1의 룩이 지키고 있어 킹이 잡을 수 없습니다. b8, c8, b7, c6 같은 칸은 흑 자신의 기물로 막혀 있고, d6과 d7은 룩이 노리고 있습니다. 단 11수 만에 백은 퀸을 버리고 작은 기물 두 개로 이겼습니다. 캐슬링하지 않고 기물을 잡으러 가면 킹이 얼마나 위험해지는지 알려 주는 한 판입니다. 기록에 따라서는 흑이 한 수 전에 기권했다고도 합니다."
      } },
    "immortal": { "t": "불멸의 게임", "w": "아돌프 안데르센", "b": "리오넬 키에세리츠키", "ev": "1851년 런던 대회 중 쉬는 시간에 둔 비공식 대국", "d": "1851년", "pl": "영국 (런던)", "lead": "세계 최초의 국제 대회가 열리던 런던에서, 쉬는 시간에 둔 한 판. 백은 비숍, 룩 두 개, 마지막에는 퀸까지 버리고 남은 작은 기물 세 개로 메이트합니다. 흑은 도중에 기권했고, 마지막 몇 수는 백이 보여 준 수순이라고도 합니다.",
      c: {
        "0": "1851년 런던. 대회 쉬는 시간에 독일의 안데르센(백)과 파리에서 활약한 키에세리츠키(흑)가 가볍게 두었습니다.",
        "1": "백은 킹 앞의 폰을 두 칸 전진.",
        "2": "흑도 똑같이.",
        "3": "f4! 폰 하나를 내주는 \"킹스 갬빗\"입니다. 흑의 e5 폰을 중앙에서 끌어내는 것이 목적입니다.",
        "4": "흑은 폰을 받습니다.",
        "5": "비숍이 나와 흑 킹 옆의 f7을 노립니다.",
        "6": "체크! 백의 f줄 폰이 없어져서 h4에서 e1까지 대각선 길이 열려 있었습니다.",
        "7": "킹이 한 칸 비킵니다. 이제 백은 캐슬링을 할 수 없습니다.",
        "8": "흑도 폰을 내줍니다. 비숍을 b5로 끌어내려는 생각입니다.",
        "9": "백은 폰을 잡습니다.",
        "10": "나이트가 나와 e4 폰을 노립니다.",
        "11": "백도 나이트를 꺼내 h4의 퀸을 쫓습니다.",
        "12": "퀸은 h6으로 물러납니다.",
        "13": "d3으로 e4 폰을 지키고, c1 비숍의 길도 엽니다.",
        "14": "나이트가 h5로. 다음에 g3으로 뛰어 체크하면서 h1 룩도 노리는 작전입니다.",
        "15": "백 나이트가 h4로. f5로 나가 흑의 퀸을 위협할 준비입니다.",
        "16": "흑의 퀸은 g5로 가서 h4 나이트를 노립니다.",
        "17": "나이트가 f5로. e4 폰이 지켜 주는 좋은 자리입니다. g7 폰도 노리고 있습니다.",
        "18": "c6으로 b5 비숍을 쫓아내려 합니다.",
        "19": "백은 비숍을 구하지 않고 g4로 h5 나이트를 쫓습니다.",
        "20": "나이트는 f6으로 돌아갑니다.",
        "21": "룩이 g1로 가서 g4 폰을 지킵니다. b5 비숍은 잡혀도 된다는 대담한 수입니다.",
        "22": "흑은 비숍을 잡았습니다. 기물 하나를 앞섰습니다.",
        "23": "h폰으로 흑의 퀸을 쫓기 시작합니다.",
        "24": "퀸은 g6으로.",
        "25": "h5로 다시 퀸을 쫓습니다.",
        "26": "퀸은 g5로 돌아갈 수밖에 없습니다. 갈 수 있는 칸이 점점 줄어듭니다.",
        "27": "백 퀸이 f3으로. 다음에 비숍이 f4를 잡으면 흑의 퀸이 갇힐 수도 있습니다.",
        "28": "흑은 나이트를 g8로 되돌려 퀸이 f6으로 도망칠 길을 만듭니다.",
        "29": "비숍이 f4 폰을 잡으며 퀸을 쫓습니다.",
        "30": "퀸은 f6으로 도망칩니다.",
        "31": "나이트가 나옵니다. d5로 뛰어 퀸을 노릴 예정입니다.",
        "32": "비숍이 나와 g1의 룩을 노립니다.",
        "33": "나이트가 d5로. f6의 퀸과 c7 칸을 노립니다. g1 룩은 잡혀도 상관없습니다.",
        "34": "퀸이 b2 폰을 잡고 a1 룩을 노립니다.",
        "35": "비숍이 d6으로! 룩 두 개를 모두 내줄 생각입니다. 대신 흑 킹을 둘러싸는 그물을 만듭니다.",
        "36": "흑은 g1의 룩을 잡았습니다.",
        "37": "e5! 이 폰이 b2의 퀸에서 g7로 가는 대각선을 막습니다. 흑의 퀸은 더 이상 킹을 도우러 올 수 없습니다.",
        "38": "흑은 체크하면서 다른 룩도 잡습니다.",
        "39": "킹은 e2로. 백에게 남은 큰 기물은 퀸, 나이트 둘, 비숍 하나뿐입니다.",
        "40": "나이트를 a6으로 꺼내 c7을 지킵니다. 흑은 이쯤에서 기권했고, 그 뒤는 백이 보여 준 수순이라고도 합니다.",
        "41": "나이트가 g7을 잡으며 체크.",
        "42": "킹은 d8로 도망칩니다.",
        "43": "퀸을 f6에 버리며 체크! 마지막 큰 기물까지 내줍니다.",
        "44": "흑은 나이트로 잡을 수밖에 없습니다.",
        "45": "비숍이 e7로. 체크메이트! d5의 나이트가 e7과 c7을, g7의 나이트가 e8을 막고 있습니다. 백은 비숍 하나와 나이트 둘만으로 이겼습니다."
      } },
    "mimiaka": { "t": "귀가 붉어진 대국", "w": "혼인보 슈사쿠", "b": "이노우에 겐난 인세키", "ev": "오사카에서의 대국 (사흘에 걸쳐)", "d": "1846년", "pl": "일본 (오사카)", "lead": "17세의 슈사쿠(4단)가 당대 최강자 중 한 명인 겐난(8단)에게 도전한 대국. 슈사쿠의 127수를 본 겐난의 귀가 붉어졌다는 이야기에서 이 이름이 붙었습니다. 덤이 없던 시대로, 흑이 2집 이겼습니다.",
      c: {
        "0": "1846년 오사카. 슈사쿠가 흑, 겐난이 백입니다. 전날에는 두 점 접바둑을 두다가 중단되었고, 이번 판은 슈사쿠가 흑으로 접지 않고 둡니다.",
        "1": "흑1은 우상귀 소목(R16). 귀의 집을 단단히 차지하기 쉬운 자리입니다.",
        "2": "백2는 좌상귀 소목(D17). 서로 빈 귀부터 차지합니다.",
        "5": "흑1·3·5로 세 귀를 모두 소목에 두었습니다. 슈사쿠가 즐겨 쓴 방식으로, 후대에도 본보기가 됩니다.",
        "6": "백6은 좌변 C14. 흑의 귀에 걸치지 않고 변에 자리를 잡았습니다. 조금 드문 수입니다.",
        "7": "흑7(E4)로 좌하귀를 두 돌로 굳혔습니다. 이것을 굳힘이라 하며, 귀가 아주 단단해집니다.",
        "8": "백8(R5)은 우하귀 흑Q3에 걸치는 수. 여기서 우하귀의 큰 싸움이 시작됩니다.",
        "10": "백10(O4)은 ‘대사(大斜)’라 불리는 수. 흑돌을 비스듬히 씌우는 형태로 변화가 아주 많습니다. 겐난이 즐겨 둔 수입니다.",
        "11": "흑11(Q5)로 어려운 변화에 들어갔습니다. 대사는 상대가 깊이 연구한 형태라 흑은 조심해야 합니다.",
        "24": "우하귀에서 흑백이 얽혀 서로 끊으려 합니다. 백24(N4)로 흑돌은 밖으로 나가기 어려워졌습니다.",
        "25": "흑25(N3). 후대의 연구에서는 여기서 다른 수가 더 좋았다고 합니다. 고수라도 헤맬 만한 어려운 장면이었습니다.",
        "28": "백28(M3), 30(L2)으로 백은 곧바로 흑의 약점을 찌릅니다. 흑돌은 하변의 좁은 곳에 갇힐 듯합니다.",
        "31": "흑31(M4)은 중요한 한 수. 곧 올 패(서로 따냈다 되따내는 싸움)에 대비해, 상대가 받아야 하는 곳을 미리 만들어 둡니다.",
        "36": "백36(N2). 패를 시작하기 전에 백은 여기를 먼저 둡니다. 시기가 좋은 수입니다.",
        "40": "백40(R1)으로 한 점을 따내 패가 시작됩니다. 따인 쪽은 바로 되따낼 수 없어서, 다른 곳에 팻감을 씁니다.",
        "41": "흑41(O5)은 팻감. 조금 손해지만 여기서는 이렇게 둘 수밖에 없었습니다.",
        "53": "흑53(R10)은 좀처럼 떠올리기 힘든 재미있는 착상. 우변에서 백의 모양을 흔듭니다.",
        "60": "백60(S3)은 큰 수. 덕분에 다음 62(M1)도 선수로 둘 수 있게 됐습니다.",
        "63": "흑63(O1)으로 우하귀의 긴 싸움이 일단락. 백은 하변에 집을, 흑은 우변에 두터운 벽을 얻었습니다. 지금까지는 백이 잘 둔 것으로 보입니다.",
        "67": "흑67(L17). 우변의 벽을 등지고 상변에 크게 진을 칩니다.",
        "72": "백72(P13)는 훌륭한 수. 흑의 벽 위에 돌을 놓아 흑의 모양이 커지는 것을 막습니다.",
        "74": "여기서 100수 무렵까지 겐난은 한 수도 느슨함 없이 둡니다. 흑의 공격을 잘 피하며 백돌을 이어 갑니다.",
        "83": "흑83(H3)으로 하변 백집에 들어갑니다. 백집을 조금이라도 줄이려는 수입니다.",
        "96": "백96(R14)부터 우상귀 흑 주변에서 섬세한 싸움이 이어집니다. 백은 여기서도 좋은 모양을 만듭니다.",
        "107": "흑107(P10)로 백 한 점을 따냈습니다. 우변 흑은 안심할 수 있는 모양이 됐습니다.",
        "118": "백118(M19)로 흑 한 점을 따내, 상변 백도 살았습니다. 흑의 상변 모양은 생각만큼 커지지 않습니다.",
        "126": "백126(J5). 하변 백은 두터워졌고 중앙으로도 힘을 뻗습니다. 지켜보던 전문가 대부분은 백이 좋다고 생각했다고 합니다.",
        "127": "이것이 유명한 ‘이적(耳赤)의 묘수’, 흑127(K11)입니다. 중앙의 이 한 점은 위의 흑 모양을 넓히고, 아래 백의 두터움을 약하게 하고, 오른쪽 흑을 돕고, 백이 왼쪽으로 뻗는 것도 막아 네 방향에 동시에 효과가 있다고 합니다.",
        "128": "이때 곁에서 보던 의사가 겐난의 귀가 붉어진 것을 알아챘습니다. 바둑을 잘 모르던 그는 “당황했다는 표시이니 흑이 이길 것”이라고 했다고 전해집니다.",
        "131": "흑131(D10). 흑은 좌변 백의 진영에도 손을 대며, 판 전체에서 백집을 줄여 갑니다.",
        "147": "흑147(K10). 127수의 돌이 중앙에서 힘을 발휘하기 시작해, 백돌 사이를 가르며 나아갑니다.",
        "160": "백160(H8). 백은 중앙의 돌을 지키며 좌하귀 흑도 노립니다. 승부는 아직 미세합니다.",
        "167": "흑167(C2)은 정확한 수. 좌하귀 흑이 안전해져 백의 노림은 사라졌습니다.",
        "175": "흑175(G4)로 백 한 점을 따냈습니다. 하변 백집은 처음 보였던 만큼 크지 않습니다.",
        "199": "흑199(K7). 중앙 싸움이 가라앉고, 경계를 정하는 끝내기로 들어갑니다. 한두 집을 다투는 세밀한 승부입니다.",
        "212": "백212(D19), 216(F19)으로 상변 끝에서 흑돌을 따냅니다. 끝내기에서도 서로 한 발도 물러서지 않습니다.",
        "228": "백228(N12)로 중앙에 패가 생겼습니다. 이후 80수 넘게 M13과 N13에서 따냈다 되따내기가 이어집니다.",
        "236": "백236(T8)은 패 도중 한 점을 따낸 수. 후대 연구에는 여기서 패를 끝냈다면 차이가 더 좁혀졌을 거라는 의견도 있습니다.",
        "275": "흑275(T14)로 백 두 점을 따냈습니다. 패를 하는 동안 서로 판 여기저기서 이득과 손해를 주고받습니다.",
        "299": "흑299(J16)로 백 넉 점을 한꺼번에 따냈습니다. 상변은 흑이 단단히 지켜 냅니다.",
        "311": "흑311(M13)로 패를 해소했습니다. 긴 패 싸움이 드디어 끝납니다.",
        "325": "325수로 종국. 계가해 보니 흑 2집 승이었습니다. 덤이 없던 시대라도, 17세가 겐난 같은 최고수를 이긴 일은 큰 화제가 되었고 슈사쿠의 이름이 널리 알려집니다."
      } },
    "evergreen": { "t": "에버그린 게임", "w": "아돌프 안데르센", "b": "장 뒤프렌", "ev": "가볍게 둔 한 판 (대회가 아님)", "d": "1852년", "pl": "독일 (베를린으로 추정)", "lead": "\"불멸의 게임\"의 안데르센이 이듬해에 둔 또 하나의 명국. 흑이 메이트를 노리는 바로 그 순간, 백은 조용히 룩 하나를 움직이고, 그다음 퀸을 버려 더블 체크로 끝냅니다. 언제까지나 빛바래지 않는다는 뜻에서 \"에버그린(상록)\"이라고 불립니다.",
      c: {
        "0": "1852년 잡지에 실린 한 판입니다. 백은 안데르센, 흑은 친구 뒤프렌. 베를린에서 두었다고 여겨지지만 확실한 기록은 없습니다.",
        "1": "백은 킹 앞의 폰을 두 칸.",
        "2": "흑도 똑같이.",
        "3": "나이트가 e5 폰을 노립니다.",
        "4": "흑은 나이트로 e5를 지킵니다.",
        "5": "비숍이 나와 흑의 f7을 노립니다.",
        "6": "흑도 비숍을 꺼냅니다.",
        "7": "b4! 폰을 내주는 \"에반스 갬빗\"입니다. 흑이 잡는 사이에 중앙을 굳히려는 생각입니다.",
        "8": "흑은 폰을 잡습니다.",
        "9": "c3으로 비숍을 쫓고 다음 d4를 준비합니다.",
        "10": "비숍은 a5로 물러납니다.",
        "11": "d4로 중앙에 나갑니다.",
        "12": "흑은 폰을 잡습니다.",
        "13": "백은 다시 잡지 않고 캐슬링. 폰보다 킹의 안전과 기물의 활동을 먼저 생각합니다.",
        "14": "흑의 폰이 d3까지 나아가 백 진영 깊숙이 들어갑니다.",
        "15": "퀸이 b3으로. c4 비숍과 함께 f7을 노립니다.",
        "16": "흑은 퀸으로 f7을 지킵니다.",
        "17": "e5로 퀸을 쫓습니다.",
        "18": "퀸은 g6으로.",
        "19": "룩이 e1로. e줄에 들어가 e5 폰을 받칩니다.",
        "20": "흑은 나이트를 꺼내 캐슬링을 준비합니다.",
        "21": "비숍이 a3으로. 대각선으로 e7의 나이트를 노립니다. 이 나이트가 움직이면 비숍이 f8까지 닿으므로, 흑은 킹 쪽 캐슬링이 어려워졌습니다.",
        "22": "흑은 폰을 내주며 백의 기물을 끌어냅니다.",
        "23": "퀸이 잡습니다.",
        "24": "룩이 b8로 가서 b줄로 퀸을 쫓습니다.",
        "25": "퀸은 a4로.",
        "26": "비숍은 b6으로 물러납니다.",
        "27": "나이트가 나옵니다. 백의 기물이 거의 다 나왔습니다.",
        "28": "흑도 다른 비숍을 꺼냅니다.",
        "29": "나이트가 e4로. 다음은 f6을 노립니다.",
        "30": "흑의 퀸이 f5로 가서 e4 나이트를 노립니다.",
        "31": "비숍이 d3 폰을 잡고 e4 나이트를 지킵니다.",
        "32": "퀸이 h5로. f3의 나이트를 노립니다.",
        "33": "나이트를 f6에 버리며 체크!",
        "34": "흑은 폰으로 잡습니다.",
        "35": "백은 폰으로 다시 잡고 e7의 나이트를 노립니다. e줄에서는 e1의 룩도 e7을 보고 있습니다.",
        "36": "룩이 g8로 가서 g2를 노립니다. h5의 퀸이 f3을 잡으면 메이트가 코앞입니다.",
        "37": "룩을 조용히 d1로! 자기 킹이 위험한데도 지키지 않고 d7 칸을 향해 기물을 모읍니다. 이 한 수가 \"에버그린\"이라 불리는 이유입니다.",
        "38": "흑은 f3의 나이트를 잡습니다. 다음에 g2를 잡으면 메이트입니다.",
        "39": "하지만 백이 먼저입니다. 룩이 e7의 나이트를 잡으며 체크!",
        "40": "흑은 c6의 나이트로 다시 잡습니다. 이로써 a4에서 d7까지 대각선이 비었습니다.",
        "41": "퀸을 d7에 버리며 체크!",
        "42": "킹으로 잡을 수밖에 없습니다.",
        "43": "비숍이 f5로 가며 체크. 동시에 d1 룩의 d줄도 열려 더블 체크입니다.",
        "44": "킹은 e8로. c6으로 가면 비숍이 d7에서 메이트였습니다.",
        "45": "비숍이 d7에서 체크.",
        "46": "킹은 f8로.",
        "47": "a3의 비숍이 e7의 나이트를 잡으며 체크메이트! d7의 비숍이 e8을, f6의 폰이 e7과 g7을 막고 있습니다."
      } },
    "lasker1912": { "t": "킹 사냥", "w": "에드워드 라스커", "b": "조지 앨런 토머스", "ev": "시티 오브 런던 체스 클럽에서 둔 속기 (가벼운 한 판)", "d": "1912년", "pl": "영국 (런던)", "lead": "런던의 한 클럽에서 둔 짧은 시간의 가벼운 한 판. 백은 퀸을 버리고 흑의 킹을 g8에서 g1까지, 판을 가로질러 몰아붙입니다. 기록마다 초반 수순이 조금씩 다르지만 10수째 국면은 같습니다.",
      c: {
        "0": "1912년 10월, 시티 오브 런던 체스 클럽. 백은 독일에서 막 건너온 젊은 기술자 에드워드 라스커, 흑은 나중에 영국 챔피언이 되는 조지 앨런 토머스입니다. 시간이 짧은 가벼운 속기였습니다. 이 판은 흑 킹이 g8에서 판 반대쪽 끝 g1까지 쫓겨 가는 \"킹 사냥\"으로 유명합니다. 라스커는 나중에 미국으로 건너가 체스 책으로 널리 알려졌습니다.",
        "1": "백은 d4. 퀸 앞의 폰으로 시작합니다. e5와 c5를 누르고 c1 비숍의 길도 엽니다.",
        "2": "흑은 e6. 먼저 튼튼한 모양을 만들고 다음에 f5나 d5로 나갈 준비를 합니다.",
        "3": "나이트가 f3으로. e5를 누르고 킹 쪽 수비도 돕는 가장 자연스러운 자리입니다.",
        "4": "흑은 f5. e4 칸을 누르는 더치 디펜스와 비슷한 모양입니다. 하지만 킹 앞의 폰이 움직여 흑 킹 주변이 조금 약해집니다.",
        "5": "다른 나이트도 c3으로. 다음에 e4로 나가 f5 폰에 부딪힐 준비입니다.",
        "6": "흑도 나이트를 f6으로. e4를 더 누르고 캐슬링도 준비합니다.",
        "7": "비숍이 g5로 가서 f6 나이트를 노립니다. 이 나이트는 흑 킹을 지키는 중요한 기물이라 백은 일찍 없애고 싶습니다.",
        "8": "흑은 비숍을 e7로 꺼내 나이트를 지키고 캐슬링 준비도 진행합니다.",
        "9": "백은 비숍과 나이트를 교환합니다. 흑 킹을 지키던 나이트가 사라졌습니다.",
        "10": "흑은 비숍으로 다시 잡습니다. 이제 f6의 비숍이 킹 쪽을 지키는 역할을 이어받습니다.",
        "11": "e4! f5 폰에 부딪혀 중앙을 넓힙니다. 길이 열려 백의 기물이 움직이기 쉬워집니다.",
        "12": "흑은 e4 폰을 잡습니다. 잡지 않으면 백이 e5로 나가 흑의 기물을 밀어냅니다.",
        "13": "나이트로 다시 잡아 중앙에 섭니다. f6의 비숍과 g5, d6 칸을 노립니다.",
        "14": "흑은 b6. 비숍을 b7로 꺼내 긴 대각선에서 e4 나이트를 노릴 준비입니다.",
        "15": "나이트가 e5로. 중앙의 강한 칸이며 g4와 f7도 노립니다. 백의 나이트 두 개가 흑의 킹 쪽으로 다가왔습니다.",
        "16": "흑은 캐슬링. 킹이 g8에 들어갔습니다. 하지만 f줄 폰이 없어서 킹 주변에 틈이 많습니다.",
        "17": "비숍이 d3으로. 지금은 e4의 자기 나이트가 막고 있지만, 그 너머에는 h7 폰이 있습니다. e4 나이트가 움직이는 순간 이 비숍이 h7을 노리는 장치입니다.",
        "18": "흑의 비숍이 b7로 가서 긴 대각선으로 e4 나이트를 노리며 백의 기물을 묶습니다.",
        "19": "퀸이 h5로 가서 h7 폰을 노립니다. h7은 흑 킹만 지키고 있습니다. 백의 퀸, 비숍, 나이트가 모두 흑 킹 쪽을 향하고 있습니다.",
        "20": "흑은 퀸을 e7로. f6 비숍을 지키고 c5로 나갈 길도 만들지만, 백의 노림을 눈치채지 못했습니다. 여기서는 h6이나 e5 나이트를 잡는 수가 필요했습니다. 이것이 승부의 갈림길입니다.",
        "21": "퀸을 h7에 버리며 체크! 가장 강한 기물을 공짜로 내줍니다. 라스커는 킹을 쫓아 메이트까지 가는 길을 내다보고 있었습니다.",
        "22": "흑은 킹으로 잡을 수밖에 없습니다. 킹이 h7로 끌려 나왔습니다.",
        "23": "나이트가 f6의 비숍을 잡으며 체크. 동시에 e4가 비어 d3 비숍도 h7의 킹을 체크하는 더블 체크입니다. 더블 체크는 막을 수 없어 킹이 도망칠 수밖에 없습니다.",
        "24": "킹은 h6으로. h8로 물러나면 다른 나이트가 g6으로 뛰어 메이트였습니다. 킹은 점점 앞으로 밀려납니다.",
        "25": "다른 나이트가 e5에서 g4로 뛰며 체크. h6의 킹을 노려 더 앞으로 몰아냅니다.",
        "26": "킹은 g5로. 자기 진영을 떠나 백 쪽으로 다가갑니다.",
        "27": "h폰으로 체크! 폰까지 킹 사냥에 가세합니다. 킹은 계속 앞으로 갈 수밖에 없습니다.",
        "28": "킹은 f4로. 이미 판의 한가운데를 넘어 백 진영으로 들어가고 있습니다.",
        "29": "g폰으로 또 체크. 폰 두 개가 킹의 퇴로를 막고 있습니다.",
        "30": "킹은 f3으로. 백 기물들의 한가운데입니다.",
        "31": "비숍이 d3에서 e2로 물러나며 체크. 킹은 더 깊숙이 몰립니다.",
        "32": "킹은 g2로. 백 킹이 있는 e1이 멀지 않습니다.",
        "33": "룩이 h2에서 체크. 마침내 룩도 일하기 시작했습니다.",
        "34": "킹은 드디어 g1로. 출발점 g8에서 판 반대쪽 끝의 첫 줄까지 와 버렸습니다.",
        "35": "백 킹이 e1에서 d2로. 킹이 비키자 a1 룩 앞이 열려 첫 줄을 따라 g1의 흑 킹을 체크합니다. 체크메이트! 퀸 쪽 캐슬링으로도 메이트였지만, 라스커는 킹을 움직였습니다. 짧은 속기에서 퀸을 버린 뒤 14수에 걸쳐 킹을 백 진영의 가장 깊은 곳까지 몰아넣은, 아주 드문 한 판입니다."
      } },
    "toketsu": { "t": "토혈의 대국", "w": "아카보시 인테쓰", "b": "혼인보 조와", "ev": "로주 마쓰다이라 스오노카미 저택에서의 대국 (나흘에 걸쳐)", "d": "1835년", "pl": "일본 (에도)", "lead": "바둑계 최고의 자리 ‘명인기소’를 둘러싼 다툼 속에서 둔 대국. 이노우에 겐난 인세키는 제자 아카보시 인테쓰를 명인 조와와 맞붙였습니다. 나흘간의 격전 끝에 인테쓰는 졌고, 바둑판 앞에서 피를 토했다고 전해집니다.",
      c: {
        "0": "1835년. 흑은 아카보시 인테쓰(7단), 백은 명인 혼인보 조와. 겐난은 “7단에게 지는 명인은 자격이 없다”고 주장할 생각으로 가장 뛰어난 제자를 보냈습니다.",
        "1": "흑1은 좌하귀 소목(C4). 인테쓰는 차분한 수로 시작합니다.",
        "4": "4수까지 네 귀에 돌이 하나씩 놓였습니다. 백은 우하·좌상, 흑은 좌하·우상입니다.",
        "6": "백6(E3)은 벌써 좌하귀 흑에 걸칩니다. 조와는 처음부터 적극적입니다.",
        "10": "백10(P4)으로 우하귀를 두 돌로 굳혔습니다(굳힘).",
        "12": "백12(D6)는 좌하귀 흑을 위에서 씌우는 수. 여기서 이 판의 가장 큰 싸움이 시작됩니다.",
        "13": "흑13(E4)은 백돌에 바짝 붙이는 수. 흑도 물러서지 않고 싸움을 받아들입니다.",
        "20": "백20(C3)은 흑 귀 밑으로 파고드는 수. 흑의 귀 집을 깎으면서 자기 돌을 살리려 합니다.",
        "28": "백28(C9)은 좌변으로 크게 뛰어든 수. 지나치게 벌렸다는 평도 있는, 조와다운 격렬한 한 수입니다.",
        "33": "흑33(C2). 이노우에 가문이 몰래 연구해 온 새로운 변화라고 전해집니다. 백의 중앙 돌을 공격하면서 좌변 백도 잡으려는 노림입니다.",
        "36": "백36(F3). 백은 좌하귀에서 흑을 밖에서 누르며 자기 돌을 이으려 합니다.",
        "43": "흑43(E9). 좌변 백돌이 괴로워졌습니다. 여기까지는 인테쓰가 잘 두어 앞서 나갔다고 봅니다.",
        "45": "흑45(D11)는 좌변을 따라 위로 뻗어, 백돌을 갈라놓은 채 자기 돌을 강하게 합니다.",
        "50": "백50(C16). 백은 좌하귀를 잠시 떠나 좌상귀로 향합니다.",
        "53": "흑53(G17). 흑은 상변에 들어가 백의 좌상귀가 넓어지지 못하게 합니다.",
        "58": "백58(C14)은 좌상귀에서 변으로 펼쳐 좌변 흑돌에 다가갑니다.",
        "60": "백60(G4)으로 흑 두 점을 따냈습니다. 좌하귀 백에 겨우 조금 여유가 생깁니다.",
        "62": "백62(J17). 상변에서도 흑백이 맞서, 판 곳곳에 약한 돌이 있는 어려운 국면입니다.",
        "66": "백66(B14). 좌상귀 주변에서 백은 자기 돌을 안정시키려 합니다.",
        "68": "백68(B11). 여기서부터의 백 몇 수와 80수는 훗날 ‘조와의 묘수’로 전해집니다. 너무 훌륭해서 ‘유령이 가르쳐 준 수’라는 말까지 나왔습니다.",
        "70": "백70(E12). 백은 좌변 흑에 바로 받지 않고 먼저 다른 급소에 둡니다. 나중에 효과를 낼 수단이 남아 있어서 가능한 수입니다.",
        "72": "백72(R13). 백은 우변으로 향해 흑의 우상귀가 넓어지지 않게 합니다.",
        "76": "백76(O14). 백은 우변과 중앙을 잇듯 돌을 놓아 흑을 가를 준비를 합니다.",
        "80": "백80(Q10)은 ‘빈삼각’을 만드는, 보통은 나쁜 모양으로 여겨지는 수. 그런데 이 수가 흑을 둘로 갈라 공격하는 발판이 되었습니다. ‘모양은 나빠도 좋은 수’의 대표로 자주 소개됩니다.",
        "83": "흑83(R3)으로 우하귀 백에 들어갑니다. 여기서 따내고 따이는 격렬한 싸움이 벌어집니다.",
        "91": "흑91(Q4)로 백 한 점을 따냈습니다. 우하귀는 흑에게 중요한 곳입니다.",
        "98": "백98(M4). 백은 하변 흑을 밖에서 감싸 쉽게 살지 못하게 합니다.",
        "106": "백106(S5)으로 흑 한 점을 따냈습니다. 우하귀는 백이 지켜 냈고, 흑돌은 밖으로 달아나야 합니다.",
        "113": "흑113(K6). 하변 흑돌은 중앙으로 머리를 내밀어 살길을 찾습니다.",
        "120": "백120(N9)으로 달아나는 흑의 앞을 막습니다. 중앙에서 누구의 돌이 먼저 약해지느냐의 승부입니다.",
        "128": "백128(L11)은 중앙 흑을 위에서도 누릅니다. 흑돌은 좀처럼 안심할 수 없습니다.",
        "138": "백138(K8)로 흑 한 점을 따내 중앙에서 패가 시작됩니다. K8과 L8에서 따냈다 되따내기가 30수쯤 이어집니다.",
        "152": "백152(E11)는 팻감. 패를 하는 동안 백은 판 곳곳에서 흑이 받아야 하는 수를 찾아냅니다.",
        "170": "백170(P15). 중앙의 패가 일단락되고 백은 우상으로. 아직 완전히 살지 못한 흑 대마를 노립니다.",
        "178": "백178(J14)은 상변 한가운데로 뛰어들어 흑을 좌우로 가릅니다. 80수부터 노리던 분단 공격이 여기서 본격화됩니다.",
        "193": "흑193(J11)으로 백 한 점을 따냈습니다. 흑도 필사적으로 돌을 이어 살길을 찾습니다.",
        "201": "흑201(R14)로 백 한 점을 따내 우변에서 새 패가 시작됩니다. R14와 R15에서 다시 따내기가 이어집니다.",
        "206": "백206(M13). 패를 하는 중에도 백은 중앙 흑을 조금씩 옥죕니다.",
        "222": "백222(L14)로 흑 한 점을 따냈습니다. 상변 흑은 둘로 갈린 채여서 양쪽을 다 지키기가 어려워졌습니다.",
        "230": "백230(C13)은 좌변에서도 흑의 약점을 찌릅니다. 판 위의 백돌은 이미 단단히 이어져 있습니다.",
        "237": "흑237(F12), 239(E13)로 좌상에서 백돌을 되따냅니다. 그래도 전체 차이는 줄어들지 않습니다.",
        "246": "백246(L8)에서 인테쓰는 돌을 던졌습니다. 돌을 정리하려던 순간 판 위에 피를 토했다고 전해집니다. 몸은 이미 병으로 약해져 있었던 것으로 보이며, 그는 얼마 뒤 세상을 떠났습니다. 조와에게는 생애 최고의 승리로 불리는 대국입니다."
      } },
    "deepblue1997": { "t": "딥 블루의 승리", "w": "딥 블루 (IBM의 컴퓨터)", "b": "가리 카스파로프", "ev": "IBM 딥 블루와의 재대결 (6국 승부) 제6국", "d": "1997년", "pl": "미국 (뉴욕)", "lead": "세계 챔피언 카스파로프와 IBM이 만든 체스 전용 컴퓨터 \"딥 블루\"의 6국 승부. 다섯 판을 마치고 동점으로 맞은 마지막 판은 겨우 19수 만에 끝났습니다. 컴퓨터가 여러 판을 두는 정식 승부에서 세계 챔피언을 처음으로 이긴 날입니다.",
      c: {
        "0": "1997년 5월 11일, 뉴욕. 전년도 승부에서는 카스파로프가 이겼습니다. 이번에는 다섯 판을 마치고 2.5 대 2.5 동점. 백은 딥 블루입니다.",
        "1": "백은 킹 앞의 폰을 두 칸.",
        "2": "카스파로프는 c6. 카로칸 디펜스입니다.",
        "3": "백은 다른 폰도 중앙으로.",
        "4": "흑은 d5로 e4에 부딪힙니다.",
        "5": "나이트로 e4를 지킵니다.",
        "6": "흑은 e4 폰을 잡습니다.",
        "7": "나이트로 다시 잡습니다.",
        "8": "흑은 나이트를 d7로. 다음에 다른 나이트를 f6으로 꺼낼 준비입니다.",
        "9": "나이트가 g5로 뜁니다. f7과 e6을 노리는 날카로운 작전입니다.",
        "10": "흑은 나이트를 f6으로.",
        "11": "비숍이 d3으로. 흑의 킹 쪽을 노립니다.",
        "12": "흑은 e6으로 수비를 굳힙니다.",
        "13": "다른 나이트도 f3으로 나옵니다.",
        "14": "흑은 h6으로 g5의 나이트를 쫓으려 합니다. 하지만 이 모양에서는 백이 나이트를 버리는 수가 이미 알려져 있었습니다. 카스파로프답지 않은 선택이었다고들 합니다.",
        "15": "나이트를 e6에 버립니다! 딥 블루는 미리 기억해 둔 초반 수순 가운데서 이 수를 두었다고 합니다.",
        "16": "흑은 바로 잡지 않고 퀸을 e7로. e줄에서 e6의 나이트와 그 뒤의 백 킹을 일직선으로 노립니다.",
        "17": "백은 캐슬링으로 킹을 피신시킵니다.",
        "18": "흑은 나이트를 잡았습니다. 기물 수로는 흑이 앞섭니다.",
        "19": "비숍이 g6에서 체크. f7 폰이 없어서 대각선이 킹까지 열려 있습니다.",
        "20": "킹은 d8로. 흑은 이제 캐슬링을 할 수 없고, 킹이 판 가운데 근처에 남았습니다.",
        "21": "다른 비숍도 나와 흑 킹 주변의 칸을 노립니다.",
        "22": "흑은 b5. 퀸 쪽에 킹과 비숍이 쓸 자리를 만들려고 합니다.",
        "23": "a4로 b5 폰에 부딪힙니다.",
        "24": "흑은 비숍을 b7로.",
        "25": "룩이 e1로. e줄에서 e6 폰과 그 너머 e7의 퀸을 노립니다.",
        "26": "흑의 나이트가 d5로 가서 f4의 비숍을 노립니다.",
        "27": "비숍은 g3으로 물러납니다.",
        "28": "흑의 킹은 c8로. 조금이라도 안전한 곳으로 갑니다.",
        "29": "백은 b5 폰을 잡습니다.",
        "30": "흑은 다시 잡습니다.",
        "31": "퀸이 d3으로. b5 폰을 노리고 f5 칸도 보고 있습니다.",
        "32": "흑은 비숍으로 b5를 지킵니다.",
        "33": "비숍을 f5로! 공짜로 잡히는 수입니다.",
        "34": "흑은 폰으로 잡습니다. 하지만 이로써 e줄의 폰이 사라졌습니다.",
        "35": "룩이 e7의 퀸을 잡습니다. 백은 나이트, 비숍, 룩을 내줬지만 대신 퀸을 잡았습니다.",
        "36": "흑은 비숍으로 룩을 다시 잡습니다.",
        "37": "c4! 폰이 b5와 d5 양쪽에 부딪히며 흑의 수비가 무너지기 시작합니다. 카스파로프는 여기서 기권했습니다. 킹의 수비가 얇아 백의 공격을 막을 수 없다고 본 것이겠지요. 컴퓨터가 세계 챔피언과의 승부에서 이긴 순간입니다."
      } },
    "seigen1933": { "t": "삼삼·화점·천원의 대국", "w": "오청원", "b": "혼인보 슈사이", "ev": "슈사이 명인과의 기념 대국 (석 달 남짓)", "d": "1933~1934년", "pl": "일본 (도쿄)", "lead": "19세의 오청원(5단)이 명인 혼인보 슈사이와 둔 대국. 흑을 쥔 오청원은 1수 삼삼, 3수 화점, 5수 천원이라는, 당시의 상식을 깨는 수로 세상을 놀라게 했습니다. 대국은 여러 차례 중단을 거쳐 석 달 넘게 이어졌고, 백이 2집 이겼습니다.",
      c: {
        "0": "1933년. 이해 오청원은 친구 기타니 미노루와 함께 ‘신포석’이라는 새로운 방식을 퍼뜨리고 있었습니다. 명인 앞에서 그것을 어떻게 보여 줄지 모두가 주목했습니다.",
        "1": "흑1은 우상귀 삼삼(R17). 한 수로 귀의 집을 확실히 얻지만 바깥으로의 힘이 약해서, 당시에는 첫 수로 둘 곳이라고 여기지 않았습니다.",
        "3": "흑3은 좌하귀 화점(D4). 삼삼과 반대로 바깥으로 넓히는 것을 중시하는 수입니다.",
        "5": "흑5는 놀랍게도 판 한가운데 천원(K10). 귀도 변도 아닌 중앙에 먼저 둡니다. 명인 앞에서 새 생각을 정면으로 보여 준 한 수입니다.",
        "6": "삼삼·화점·천원. 세 흑돌은 귀의 집, 바깥으로의 확장, 중앙의 힘이라는 서로 다른 역할을 맡습니다. 백6(Q16)은 우상귀 흑 삼삼 바로 옆에 두었습니다.",
        "9": "흑9(P18). 흑은 우상귀를 작게 정리해 확실히 삽니다. 삼삼다운, 집에 짠 방식입니다.",
        "11": "흑11(K4)은 천원 바로 아래, 하변 한가운데. 천원의 돌과 힘을 합쳐 하변을 크게 둘러싸려 합니다.",
        "12": "백12(M3)는 곧장 하변에 들어가 흑이 큰 진을 치지 못하게 합니다. 명인은 서두르지 않고 흑의 계획을 하나씩 무너뜨립니다.",
        "13": "흑13(D10). 이번에는 좌변 한가운데. 흑돌은 판의 높은 위치에 늘어서 전체로 크게 진을 칩니다.",
        "14": "백14(E16)로 좌상귀를 두 돌로 굳혔습니다(굳힘). 명인은 흑의 새 방식에 흔들리지 않고 차분히 귀를 지킵니다.",
        "21": "흑21(G10)은 천원과 좌변 돌 사이를 이어, 중앙에 흑의 세력이 퍼집니다.",
        "28": "백28(D3)은 좌하귀 흑 화점 아래로 파고들어 귀의 집을 가져갑니다. 흑은 바깥을 굳히는 대신 귀를 백에게 내주었습니다.",
        "30": "백30(Q12)은 우변으로 벌리며, 우상귀 흑 삼삼의 바깥에도 뚜껑을 덮어 흑의 힘을 약하게 합니다.",
        "37": "흑37(P15)로 백 한 점을 따냈습니다. 우상에서 흑백이 부딪쳐 세밀한 다툼이 일어납니다.",
        "40": "백40(O10)은 우변에서 중앙으로 한 발 나와 천원 주변의 흑 세력에 다가갑니다.",
        "44": "백44(H17)는 상변에 두어 흑돌이 위로 퍼지는 것을 막습니다.",
        "45": "흑45(R7)로 우하의 백 진영에 손을 댑니다. 우변에서 우하에 걸쳐 한동안 싸움이 이어집니다.",
        "59": "흑59(R4)는 우하귀에도 들어가 백집을 줄입니다.",
        "70": "백70(N6)은 하변에서 중앙으로 돌을 뻗어, 흑의 우하 돌과 중앙 돌을 가르려 합니다.",
        "79": "흑79(L9)는 천원을 중심으로 중앙을 단단히 굳힙니다. 여기까지는 팽팽한 승부라 할 만합니다.",
        "80": "백80(C6)은 좌하귀에서 좌변으로 나아가 흑의 좌변 돌을 노립니다.",
        "98": "백98(A11)로 흑 두 점을 따냈습니다. 백은 좌변 끝에서 깔끔하게 살았고, 흑의 좌변은 생각보다 작아졌습니다.",
        "101": "흑101(S14)은 우상으로 돌아가 우변 백 진영을 줄입니다.",
        "105": "흑105(K17)는 상변 한가운데에 두어 상변 백돌을 공격합니다.",
        "117": "흑117(F17)은 좌상에서도 백 귀 주변에 들어가, 상변 전체가 싸움터가 됩니다.",
        "124": "백124(K15)는 상변 백돌을 중앙으로 달아나게 하면서 흑돌 사이를 가릅니다.",
        "135": "흑135(E9)로 백 두 점을 따냈습니다. 좌변에서 흑이 조금 만회했습니다.",
        "138": "백138(N18)은 상변에서 집을 굳힙니다. 판 전체로 보면 아주 미세한 형세입니다.",
        "153": "흑153(K14). 중앙의 흑돌이 위아래를 잇는 굵은 길이 됐습니다. 이 흑의 두터움을 백이 어떻게 무너뜨리느냐가 승부처입니다.",
        "159": "흑159(F4)로 좌하를 단단히 지켰습니다. 다음 백의 한 수가 이 판에서 가장 유명한 수가 됩니다.",
        "160": "백160(H8)은 흑의 두터움 틈새로 뛰어드는 날카로운 한 수. 여러 노림을 동시에 지니며, 여기서부터 백은 흑의 중앙을 파고듭니다. 이 수는 슈사이가 아니라 제자가 찾았다는 소문도 돌았지만, 확실한 것은 알려져 있지 않습니다.",
        "161": "흑161(J8)이 곧바로 받지만, 백의 노림은 하나가 아닙니다.",
        "162": "백162(K12)는 이번엔 중앙 위쪽으로 돌아 흑돌의 연결을 위협합니다.",
        "172": "백172(F13)는 중앙에서 좌상으로 돌을 이어, 흑의 중앙 두터움이 조금씩 집이 되지 못하게 됩니다.",
        "178": "백178(N9)은 중앙 오른쪽에서도 흑의 집에 들어갑니다.",
        "187": "흑187(M6), 189(L7)로 백돌을 따내며 응수합니다. 그래도 백은 중요한 곳에 먼저 손을 써 두었습니다.",
        "198": "백198(E12)로 흑 한 점을 따냈습니다. 좌상의 백돌도 이어져, 백이 전체적으로 조금 앞섭니다.",
        "203": "흑203(B3). 여기서부터는 끝내기. 판 가장자리의 경계를 한 집씩 정해 갑니다.",
        "224": "백224(T10)로 흑 한 점을 따냈습니다. 우변 끝에서도 백은 한 집도 양보하지 않습니다.",
        "233": "흑233(L13)으로 백 두 점을 따냈습니다. 흑도 끝까지 포기하지 않고 추격합니다.",
        "252": "252수로 종국, 백 2집 승. 덤이 없던 시대라 먼저 두는 흑이 조금 유리했지만, 명인은 끝까지 흔들리지 않고 이겼습니다. 그래도 오청원의 삼삼·화점·천원은 큰 화제가 되어 새 포석의 시대를 알렸습니다."
      } },
    "century1956": { "t": "세기의 게임", "w": "도널드 번", "b": "보비 피셔", "ev": "제3회 로젠월드 트로피 대회 (로젠월드 기념 대회)", "d": "1956년", "pl": "미국 (뉴욕)", "lead": "13살의 보비 피셔가 미국의 강한 마스터 도널드 번을 이긴 한 판. 17수째에 피셔는 퀸을 공짜로 내주고, 대신 기물을 하나하나 되찾아 마지막에는 작은 기물들로 백의 킹을 몰아붙입니다. 피셔는 나중에 세계 챔피언이 되었습니다.",
      c: {
        "0": "1956년 10월 17일, 뉴욕의 대회. 흑은 13살의 피셔, 백은 미국 정상급 선수 중 한 명인 번입니다.",
        "1": "백은 나이트로 시작합니다.",
        "4": "피셔는 g6. 비숍을 긴 대각선에 놓을 준비입니다.",
        "8": "흑은 캐슬링. 킹을 먼저 안전하게 합니다.",
        "10": "흑은 d5. 중앙 다툼이 시작됩니다.",
        "15": "백은 e4로 중앙에 폰 두 개를 나란히 세웠습니다.",
        "17": "룩이 d1로 가서 d4 폰을 받칩니다. 백은 아직 캐슬링하지 않았습니다.",
        "18": "나이트가 b6으로 나가 c4의 퀸을 쫓습니다.",
        "20": "비숍이 g4로. f3의 나이트를 압박합니다.",
        "21": "백도 비숍을 g5로. 백의 킹은 아직 가운데에 있습니다.",
        "22": "나이트를 a4로! 일부러 잡힐 수 있는 곳으로 뜁니다. c3의 나이트를 치우면 e4 폰을 지키는 기물이 없어지기 때문입니다.",
        "23": "백은 나이트를 잡지 않고 퀸을 a3으로 피합니다.",
        "26": "흑의 나이트가 e4 폰을 잡았습니다. 백의 중앙이 무너집니다.",
        "27": "백 비숍이 e7 폰을 잡고, 흑의 퀸과 f8의 룩을 동시에 노립니다.",
        "28": "퀸을 b6으로! f8의 룩은 잡혀도 된다는 수입니다. 피셔는 백 킹이 아직 가운데에 있다는 점을 보고 있습니다.",
        "29": "백은 룩을 잡지 않고 비숍을 꺼냅니다.",
        "30": "나이트가 c3 폰을 잡고 d1의 룩을 노립니다.",
        "31": "비숍이 c5로 가서 b6의 흑 퀸을 공격합니다.",
        "32": "룩이 e줄에서 체크!",
        "33": "킹은 f1로. 이제 백은 캐슬링을 할 수 없습니다.",
        "34": "비숍을 e6으로! 퀸을 공짜로 내주는, 이 판에서 가장 유명한 수입니다. 그 대신 흑은 백의 기물을 하나하나 되찾을 계획이 있었습니다.",
        "35": "백은 흑의 퀸을 잡았습니다.",
        "36": "비숍이 c4에서 체크. 흑의 반격이 시작됩니다.",
        "38": "나이트가 e2에서 체크.",
        "40": "킹이 f1로 돌아가면 나이트가 움직여 c4 비숍의 체크(디스커버드 체크)가 됩니다. 나이트는 가는 김에 d4 폰을 잡습니다.",
        "44": "나이트가 c3으로 돌아와 다시 디스커버드 체크. 이번에는 d1의 룩을 노립니다. 체크를 되풀이하며 기물을 잡아 가는 이 움직임을 \"풍차\"라고 부릅니다.",
        "46": "비숍을 다시 잡습니다. c3의 나이트는 아직 d1의 룩을 노리고 있습니다.",
        "50": "나이트가 d1의 룩을 잡았습니다. 이제 흑은 내준 퀸보다 많이 되찾아 확실히 앞섭니다.",
        "52": "룩이 a2 폰도 잡습니다.",
        "56": "룩을 교환합니다. 기물이 줄수록 많이 가진 흑이 유리합니다.",
        "57": "백 퀸의 체크.",
        "58": "흑은 비숍을 사이에 놓습니다.",
        "64": "b5. 흑의 폰이 전진을 시작합니다.",
        "68": "킹이 g7로 움직여 f8의 비숍을 풀어 줍니다.",
        "70": "이제 흑의 기물들이 백 킹을 몰아붙입니다. 비숍으로 체크.",
        "72": "나이트가 g3에서 체크.",
        "74": "다른 비숍으로 체크.",
        "76": "비숍이 b3에서 체크.",
        "78": "나이트가 e2에서 체크.",
        "80": "나이트가 c3에서 체크. 킹이 쫓겨 다닙니다.",
        "82": "룩이 c2로. 체크메이트! 룩, 비숍 둘, 나이트, 네 기물이 힘을 합쳤습니다. 13살 소년이 보여 준 여러 기물의 협력입니다."
      } },
    "oshiro1849": { "t": "슈사쿠의 첫 어성기", "w": "혼인보 슈사쿠", "b": "야스이 산치(9세)", "ev": "어성기(에도성에서 해마다 열린 대국)", "d": "1849년", "pl": "일본 (에도)", "lead": "어성기는 바둑 가문의 기사들이 쇼군의 성에서 해마다 두던 영광의 무대였습니다. 20세의 슈사쿠는 이해 처음 출전해 흑으로 11집 승. 여기서 어성기 19전 19승이라는 무패 기록이 시작됩니다.",
      c: {
        "0": "1849년. 슈사쿠는 전해에 혼인보 가문의 후계자로 정해졌고, 이해 처음 어성기에 나갔습니다. 어성기는 실제로는 미리 다른 곳에서 두어 두고 성에서는 다시 늘어놓는 경우가 많았다고 합니다.",
        "1": "흑1은 우상귀 소목(R16). 슈사쿠는 늘 그렇듯 차분한 소목으로 시작합니다.",
        "4": "백4(C15)는 좌상귀 흑D17에 걸치는 수. 초반부터 좌상에서 싸움이 시작됩니다.",
        "5": "흑5(C11)는 걸쳐 온 백돌을 아래에서 협공하는 수. 백이 좌변에서 편하게 자리 잡지 못하게 합니다.",
        "12": "백12(C17). 좌상귀는 백이 갖고, 흑은 바깥쪽에 돌을 얻었습니다. 서로 납득할 만한 갈림입니다.",
        "13": "흑13(J17)은 바깥쪽 흑돌을 살려 상변으로 벌렸습니다.",
        "15": "흑15(C5)로 마지막 빈 귀인 좌하귀에 들어갔습니다. 이로써 네 귀가 모두 찼습니다.",
        "16": "백16(E4)은 곧바로 그 흑에 다가가, 좌하에서도 싸움이 됩니다.",
        "19": "흑19(D2)로 좌하귀 집을 단단히 확보합니다. 슈사쿠다운 견실한 수입니다.",
        "23": "흑23(E5)은 백돌 사이로 나와 좌하의 흑을 강하게 합니다.",
        "29": "흑29(F11)는 좌변 흑돌을 보강하면서 중앙도 바라보는 수입니다.",
        "30": "백30(H4)은 하변으로 벌려 좌하 흑을 압박하며 자기 진영을 만듭니다.",
        "31": "흑31(O3)은 우하귀 백에 걸칩니다.",
        "33": "흑33(R3)은 백 귀의 돌에 바짝 붙입니다. 여기서부터 흑은 바깥에, 백은 가장자리 3선을 따라 돌을 뻗어 갑니다.",
        "43": "흑43(Q8). 우변에 위아래로 이어지는 흑의 두꺼운 벽이 생겼습니다. 백은 귀와 변의 집을, 흑은 바깥의 힘을 얻었습니다.",
        "44": "백44(L17)는 상변 흑돌 사이에 들어가 흑 진영이 너무 커지지 않게 합니다.",
        "50": "백50(R18)은 우상귀 흑 아래로 파고들어 귀의 집을 노립니다.",
        "51": "흑51(P13). 흑은 우변의 벽을 등지고 우변에서 중앙에 걸쳐 큰 진영을 칩니다.",
        "52": "백52(D10)는 좌변 흑돌 사이로 뛰어듭니다. 좌변에서 흑백이 얽힙니다.",
        "63": "흑63(B10)은 좌변 끝에 두어 백돌이 근거를 만들지 못하게 합니다.",
        "65": "흑65(G3)는 하변 백 진영에도 들어가 백집을 줄입니다.",
        "73": "흑73(K17)은 상변 흑돌을 굳혀, 백44의 돌을 괴롭게 합니다.",
        "76": "백76(P11)은 흑의 우변 진영에 뛰어들었습니다. 이 돌의 사활에 따라 집 차이가 크게 달라집니다.",
        "77": "흑77(Q11)은 자기 벽 쪽에서 받아 백을 중앙으로 몰아냅니다. 집을 지키며 공격하는, 슈사쿠다운 차분한 응수입니다.",
        "80": "백80(N10)은 중앙으로 달아나 흑의 추격을 피하려 합니다.",
        "85": "흑85(N12)는 공격하면서 상변과 우변의 자기 집을 넓혀 갑니다. 공격으로 이득을 보는 능숙한 운영입니다.",
        "91": "흑91(J7)은 하변 백의 위에 두어 중앙에서도 백 진영을 누릅니다.",
        "100": "백100(S17)은 우상귀에 손을 대 흑의 귀 집을 줄이려 합니다.",
        "119": "흑119(R17)로 우상귀를 단단히 지켜 백의 수단을 막아 냈습니다.",
        "122": "백122(G6)는 좌하 흑돌의 바깥으로 돌아 중앙 흑과의 연결을 끊으려 합니다.",
        "131": "흑131(M5)은 하변 중간에서 백 진영에 쐐기를 박습니다.",
        "140": "백140(B4)은 좌하귀 흑에 손을 댑니다. 여기서 왼쪽 끝에서 세밀한 따내기 싸움이 시작됩니다.",
        "156": "백156(A8)으로 흑 두 점을 따냈습니다. 왼쪽 끝의 다툼은 서로 조금씩 따내고 진정됩니다.",
        "158": "백158(L10). 중앙에 백돌이 남아 흑의 중앙 집을 줄이려 합니다.",
        "162": "백162(O12)로 흑 한 점을 따냈습니다. 그래도 우변 흑 진영은 크게 남아 있습니다.",
        "172": "백172(K18). 여기서부터는 끝내기. 상변의 경계를 정해 갑니다.",
        "186": "백186(T16)은 우상 끝에서 흑집을 깎습니다. 끝내기에서도 서로 큰 곳부터 둡니다.",
        "205": "흑205(Q18)로 상변 오른쪽을 단단히 닫아 집을 확정합니다.",
        "223": "흑223(P10)은 우변 흑집과 중앙으로 달아난 백돌 사이의 경계를 정하는 수입니다.",
        "233": "흑233(Q9)으로 백 한 점을 따냈습니다. 우변 흑집은 거의 지켜 냈습니다.",
        "239": "흑239(A6)로 백 한 점을 따내 왼쪽 끝에서 패가 생겼습니다. 한 집 한 집의 다툼이 끝까지 이어집니다.",
        "260": "백260(T6)으로 흑 한 점을 따내 우하 끝에서도 패. 흑은 263(T5)으로 되따냅니다.",
        "267": "267수로 종국, 흑 11집 승. 큰 모험 없이, 상대 돌을 공격하며 자연스럽게 집을 늘리는 슈사쿠다운 승리였습니다. 이것이 어성기 19연승의 첫 판입니다."
      } },
    "shilin": { "t": "《사림광기》 순수포 대국", "w": "홍（이름이 전해지지 않음）", "b": "흑（이름이 전해지지 않음）", "ev": "일용 백과 《사림광기》의 「요선 순수포 승리국」", "d": "13세기", "pl": "중국（송~원）", "lead": "송나라 말부터 원나라 초 무렵 진원정이 엮은 일용 백과 《사림광기》에 실린 기보로, 지금까지 남아 있는 샹치 전국 기보 가운데 가장 오래된 것 중 하나로 여겨집니다. 강한 쪽이 선수를 양보하는 「요선」의 본보기 대국으로, 단 9수 만에 흑의 마가 홍의 차를 붙잡습니다.",
      c: {
        "0": "지금으로부터 700년도 더 전, 송나라에서 원나라로 넘어가던 시대의 기보입니다. 백과사전 《사림광기》의 놀이 부분에 실려 있으며, 지금 남아 있는 샹치 전국 기록 가운데 가장 오래된 것 중 하나로 여겨집니다. 두 사람의 이름은 전해지지 않습니다. 「요선」은 강한 사람이 약한 사람에게 선수를 양보한다는 뜻이라, 이 대국은 먼저 둔 홍이 어떻게 지는지를 보여 주는 본보기입니다. 홍이 아래쪽이고 먼저 둡니다.",
        "1": "홍은 오른쪽 포를 가운데 줄로 옮겼습니다. 「중포（당두포）」라고 하며, 흑의 장을 정면으로 노리는, 지금도 가장 강한 시작 가운데 하나입니다. 700년 전에도 이미 이 형태가 두어졌다는 것을 알 수 있습니다.",
        "2": "흑도 포를 가운데로 옮겨 정면으로 마주 봅니다. 양쪽이 같은 쪽의 포를 움직이는 형태를 「순수포」라고 합니다. 포와 포가 맞서는 싸움은 옛날부터 인기가 많았습니다.",
        "3": "홍은 마를 뛰어 가운데 병을 지켰습니다. 가운데 병은 흑의 포에게 노려지고 있어 지켜 줄 말이 필요합니다. 동시에 마가 앞으로 나갈 준비도 됩니다.",
        "4": "흑도 마를 뛰어 가운데 졸을 지킵니다. 서로 같은 모양으로 먼저 발판을 다지고 있습니다.",
        "5": "홍은 오른쪽 차를 옆으로 한 칸 옮겨 곧게 달릴 수 있는 줄로 내보냈습니다. 차는 판에서 가장 강한 말이라 일찍 움직이게 하고 싶은 것입니다.",
        "6": "흑은 마 하나를 더 꺼냈습니다. 차는 나중으로 미루고 먼저 말들을 앞으로 내보내는 작전입니다. 하지만 차가 늦게 나오면 나중에 공격에 쓰기 어려워집니다.",
        "7": "홍의 차가 단숨에 강을 건너 흑의 진영으로 들어갔습니다. 흑의 말들을 위협하려는 것이지만, 다른 말들이 아직 집에 있어서 조금 서두른 공격입니다. 왼쪽 마나 차를 먼저 꺼내는 수도 있었습니다.",
        "8": "흑은 3번 줄의 졸을 한 칸 전진했습니다. 마가 다닐 길을 열어 나중에 앞으로 나갈 수 있게 하는 수입니다. 홍의 차가 오기를 오히려 기다리고 있습니다.",
        "9": "홍의 차가 졸을 잡고, 그 뒤의 흑 마를 노립니다. 말 하나를 얻고 또 마를 위협하니 기분 좋은 수로 보입니다. 하지만 차 혼자 너무 앞으로 나와 주변에 도와줄 말이 없습니다. 혼자 적진에 들어간 차는 쫓기기 쉽습니다.",
        "10": "흑의 마가 앞으로 뛰어나왔습니다. 홍의 차를 피하면서 홍 진영에 가까워지는, 한 수로 두 가지를 하는 수입니다. 이 마가 이 대국의 주인공이 됩니다.",
        "11": "홍은 차를 한 칸 물려 옆에서 흑의 마를 노렸습니다. 차는 멀리서도 잡을 수 있어 마는 쉴 수가 없습니다. 하지만 이 수도 다른 말을 키우는 수는 아닙니다.",
        "12": "흑의 마는 더 앞으로 나아가 강을 건너 홍 진영에 들어갔습니다. 홍의 차를 피할 때마다 점점 홍의 장에 가까워집니다.",
        "13": "홍은 병을 하나 전진시켜 자기 마가 다닐 길을 열었습니다. 다음에 마를 꺼내 흑의 마와 바꾸려는 생각입니다. 하지만 그 사이에 흑은 더 앞으로 나갈 수 있습니다.",
        "14": "흑은 상을 올려 홍의 차를 노렸습니다. 수비하는 말인 상으로 상대의 차를 쫓아내는, 군더더기 없는 수입니다. 홍은 차를 또 움직여야 하고, 흑은 한 수를 더 벌었습니다.",
        "15": "홍의 차가 옆으로 움직여 또 졸을 잡았습니다. 말을 둘이나 얻었지만, 이것이 지는 원인이 되는 수입니다. 차가 장에게서 너무 멀어져 다시 지키러 돌아올 수 없게 되었습니다. 여기서는 차를 불러들이는 등 흑의 마에 대비하는 수가 필요했습니다.",
        "16": "흑의 마가 더 깊이 들어가 홍의 차를 노렸습니다. 그것만이 아닙니다. 마가 한 번 더 뛰면 홍의 장에게 장군을 부르면서 동시에 구석의 차도 노릴 수 있습니다. 마 하나로 두 가지 노림을 한꺼번에 만들었습니다.",
        "17": "홍은 차로 흑의 마를 쫓았습니다. 하지만 마는 이제 막을 수 없습니다. 차가 떠난 홍 장의 주변은 텅 비어 있습니다.",
        "18": "흑의 마가 뛰어들어 장군! 게다가 이 마는 홍의 구석에 있는 차도 노리고 있습니다. 홍이 수를 피하면 다음에 차를 잃게 됩니다. 단 9수이지만, 혼자 너무 앞서 나간 차가 어떻게 되는지, 말들이 함께 싸우는 것이 얼마나 중요한지 알려 주는 대국입니다. 700년 전 사람들도 같은 판 위에서 같은 생각을 했던 것이지요."
      } },
    "qima13": { "t": "기마십삼착（《귤중비》）", "w": "홍（이름이 전해지지 않음）", "b": "흑（이름이 전해지지 않음）", "ev": "《귤중비》 상권 제1국 「순포 횡차로 직차를 깨는 기마」", "d": "1632년（간행）", "pl": "중국（명）", "lead": "명나라 주진정이 1632년（숭정 5년）에 펴낸 기서 《귤중비》의 맨 첫 번째 대국입니다. 홍은 일부러 마를 공짜로 내주고, 그 틈에 쳐들어가 13수 만에 외통을 만듭니다. 「기마십삼착（마를 버리는 13수）」이라는 이름으로 400년 가까이 지난 지금도 사랑받고 있습니다.",
      c: {
        "0": "명나라 말, 1632년에 출판된 기서 《귤중비》의 제1국입니다. 《귤중비》는 뒤에 나온 《매화보》와 함께 샹치의 2대 고전으로 불립니다. 이 대국은 실전이 아니라 작전을 가르치기 위한 본보기라서 대국자의 이름이 없습니다. 홍이 아래에서 먼저 두며, 단 13수 만에 승부가 납니다.",
        "1": "홍은 오른쪽 포를 가운데로 옮겼습니다. 흑의 장을 정면으로 노리는 「중포」입니다. 《귤중비》는 바로 이 중포로 공격하는 방법을 자세히 연구한 책으로 유명합니다.",
        "2": "흑도 같은 쪽 포를 가운데로 옮겼습니다. 포와 포가 정면으로 부딪히는 「순수포（순포）」입니다. 양쪽 모두 상대의 가운데 병（졸）을 노리고 있습니다.",
        "3": "홍은 마를 뛰어 가운데 병을 지켰습니다. 흑의 포가 노리는 병을 지키면서 마도 일하기 시작합니다.",
        "4": "흑도 마로 가운데 졸을 지킵니다. 여기까지는 서로 같은 모양입니다.",
        "5": "홍은 오른쪽 차를 한 칸만 앞으로 냈습니다. 이렇게 하면 다음에 차가 옆으로 달릴 수 있습니다. 옆으로 움직이는 차를 「횡차」라고 하며, 좌우로 재빨리 돌아갈 수 있는 것이 장점입니다.",
        "6": "흑은 차를 옆으로 한 칸 옮겨 곧게 나아갈 수 있는 「직차」로 만들었습니다. 횡차와 직차, 서로 다른 방식의 차가 맞서는 「순포 횡차 대 직차」의 형태입니다.",
        "7": "홍의 횡차가 판의 왼쪽 줄로 크게 옮겨 갔습니다. 이 줄은 흑의 사 바로 옆으로, 상대 수비가 얇은 곳입니다. 여기서 단숨에 쳐들어갈 준비입니다.",
        "8": "흑의 직차가 강을 건너 홍 진영 깊이 들어왔습니다. 흑도 맞공격으로 맞서려는 생각입니다. 다만 수비보다 공격을 서두른 수이기도 합니다.",
        "9": "홍의 차가 흑 진영 깊숙이 들어갔습니다. 이곳은 상이 지나가야 하는 「상의 눈」을 막는 자리라 흑의 상이 움직일 수 없습니다. 사 바로 옆이라 장에게도 아주 가까워졌습니다.",
        "10": "흑은 다른 마를 판의 가장자리로 꺼냈습니다. 홍의 차가 옆으로 파고들지 못하게 하려는 생각도 담긴 수입니다.",
        "11": "여기가 「기마」의 한 수입니다! 홍은 다른 차를 한 칸 올렸습니다. 그 때문에 왼쪽 구석의 마를 지키는 말이 없어져 흑의 포에게 공짜로 잡히게 됩니다. 하지만 홍은 마 한 마리와 바꾸어 두 차를 재빨리 공격에 쓸 시간을 얻습니다.",
        "12": "흑의 포가 홍의 마를 잡았습니다. 말 하나를 번 것처럼 보입니다. 하지만 이 포는 이제 자기 진영을 지키러 돌아갈 수 없습니다. 여기서는 잡지 않고 사를 올려 수비를 굳히는 편이 좋았다고 합니다.",
        "13": "홍의 포가 앞으로 나왔습니다. 가운데에 있는 흑의 포를 「다리」 삼아 뛰어넘어, 그 너머의 흑 마를 노립니다. 포는 말 하나를 뛰어넘어야 잡을 수 있는 신기한 말입니다.",
        "14": "흑은 마를 물려 도망쳤습니다. 그런데 이 마는 가운데 졸을 지키던 중요한 말이었습니다. 도망친 탓에 가운데 수비에 구멍이 생겼습니다. 다른 수비 방법도 있었지만, 이것이 가장 나쁜 선택이었습니다.",
        "15": "홍의 포가 가운데 졸을 잡고 장군! 방금 흑의 마가 사라져서 가운데가 텅 비었습니다. 여기서부터 홍의 공격이 단숨에 진행됩니다.",
        "16": "흑은 사를 올려 장 앞을 막았습니다. 장군을 막으려면 이것밖에 없는 모양입니다.",
        "17": "홍의 두 번째 차도 같은 줄로 왔습니다. 두 차가 세로로 겹치면 아주 강한 힘이 됩니다. 다음에는 흑 진영 깊숙이 쳐들어가겠다는 노림입니다.",
        "18": "흑의 장은 옆으로 피했습니다. 그대로 있으면 홍의 두 차에게 한 줄로 노려지기 때문입니다.",
        "19": "홍은 앞의 차로 흑의 사를 잡고 장군! 이 차는 곧 다른 사에게 잡히지만, 그것도 계산 안에 있습니다. 차 하나를 버려 흑 장 주변의 수비를 부수는 과감한 한 수입니다.",
        "20": "흑은 사로 홍의 차를 잡았습니다. 말의 수로는 흑이 크게 앞서 있습니다. 하지만 장 주변은 더욱 텅 비었습니다.",
        "21": "홍의 남은 차가 장이 있는 줄로 옮겨 또 장군. 흑의 장 주변에는 지켜 줄 말이 거의 남아 있지 않습니다.",
        "22": "흑은 포를 장 앞에 넣어 장군을 막았습니다. 사이에 말을 끼워 넣는 「멍군」입니다.",
        "23": "홍의 차가 그 포를 잡고 또 장군. 차가 흑의 말을 계속 잡으면서 장을 몰아붙입니다.",
        "24": "흑의 장은 가운데로 돌아갈 수밖에 없습니다. 다른 자리는 모두 홍의 말이 노리고 있습니다.",
        "25": "마지막으로 홍의 포가 가운데에 서서 두 포가 세로로 겹치며 장군. 앞의 포가 다리가 되고 뒤의 포가 장을 노리는 「중포 외통」입니다. 흑의 장은 어디로도 피할 수 없어 홍의 승리입니다. 마 한 마리만 버리고 홍은 단 13수 만에 이겼습니다. 말의 수보다 시간（수순）과 말의 활약이 더 중요하다는 것을 이 대국은 400년 전부터 가르쳐 주고 있습니다."
      } }
  },
  "es": {
    ui: {"lead":"Grandes partidas, jugada a jugada. Sigue en el tablero partidas famosas mientras Musowl te explica cada movimiento.","all":"Todas","k_chess":"Ajedrez","k_shogi":"Shogi","k_go":"Go","k_xiangqi":"Xiangqi","side_r":"Rojas","res_r":"Ganan las rojas","back":"Volver a Grandes partidas","start":"Inicio","prev":"Retroceder una jugada","next":"Avanzar una jugada","end":"Final","play":"Reproducir","pause":"Pausa","moves":"Jugadas","move":"Jugada {n}","startpos":"Posición inicial","nextnote":"Siguiente comentario (jugada {n})","quiet":"Esta jugada no tiene comentario.","guide":"Musowl","keys":"← → para ir jugada a jugada","result":"Resultado","r_event":"Partida","r_date":"Año","r_place":"Lugar","side_w":"Blancas","side_b":"Negras","side_s":"Sente","side_g":"Gote","side_B":"Negras","side_W":"Blancas","res_w":"Ganan las blancas","res_b":"Ganan las negras","res_d":"Tablas","res_s":"Gana sente","res_g":"Gana gote","credit":"Las jugadas son el registro público de cada partida. Los comentarios son de Musowl, del museo."},
    "opera": { "t": "La partida de la Ópera", "w": "Paul Morphy", "b": "El duque Carlos II de Brunswick y el conde Isouard", "ev": "Jugada en un palco de la Ópera de París (los dos aliados jugaban en consulta)", "d": "1858", "pl": "Francia (París)", "lead": "El joven campeón estadounidense contra dos nobles, en plena función de ópera: diecisiete jugadas. Sacar las piezas rápido, entregarlas sin dudar y terminar con muy pocas. Ninguna partida aparece en más libros de ajedrez.",
      c: {
        "0": "París, 1858. El estadounidense Paul Morphy, de veintiún años, venía derrotando uno tras otro a los fuertes jugadores de Europa. Esa noche, en un palco de la ópera, el duque de Brunswick y el conde Isouard tomaron juntos las negras y lo desafiaron, consultando cada jugada. Se dice que Morphy quería terminar pronto para ver el escenario. Estas diecisiete jugadas están llenas de lo básico: sacar rápido las piezas y poner el rey a salvo.",
        "1": "Las blancas avanzan dos casillas el peón del rey. Vigila d5 y e5 en el centro y abre caminos al alfil y a la dama.",
        "2": "Las negras también juegan e5. Los peones se miran en el centro y el peón blanco ya no puede avanzar.",
        "3": "El caballo va a f3 y ataca el peón de e5. Buena jugada: desarrolla una pieza y obliga al rival a pensar en defenderse.",
        "4": "Las negras defienden e5 con d6. Es la Defensa Philidor. Es sólida, pero estrecha un poco el camino del alfil de f8.",
        "5": "Las blancas juegan d4: otro peón al centro, contra e5. Las negras deben decidir si capturan o defienden.",
        "6": "El alfil negro va a g4. Presiona al caballo de f3, que está en línea con la dama blanca de d1. Si el caballo se mueve, se pierde la dama, así que no puede ir por e5.",
        "7": "Las blancas toman en e5 con el peón. Si las negras recapturaran enseguida con el peón de d6, las blancas cambiarían damas y luego el caballo se comería el peón de e5. Por eso las negras quieren quitar primero el caballo de f3.",
        "8": "Las negras toman el caballo con el alfil. Ahora pueden recuperar e5 sin peligro. Pero entregar por el caballo el alfil que acababa de salir las deja atrasadas en desarrollo.",
        "9": "Las blancas recapturan con la dama, que ya trabaja cerca del centro, mientras las negras casi no han sacado piezas.",
        "10": "Las negras recapturan con un peón y el material está igualado. Pero en piezas desarrolladas, las blancas van por delante.",
        "11": "Alfil a c4. Junto con la dama de f3 apunta a f7. Solo el rey defiende f7, así que es una casilla débil: tomarla sería mate.",
        "12": "Las negras llevan el caballo a f6 y tapan la columna f. Sin esto, dama toma f7 sería mate. Defenderse desarrollando es la respuesta correcta.",
        "13": "La dama gira a b3 y ataca a la vez f7 y b7. Una jugada con dos amenazas es fuerte, porque el rival no puede defender ambas.",
        "14": "Las negras juegan la dama a e7 para defender f7 y dejan ir b7. Pero ahora la dama tapa al alfil de f8.",
        "15": "Morphy no toma el peón de b7: saca un caballo. Tomar mandaría la dama muy lejos. Elegir el desarrollo rápido antes que un peón es muy propio de Morphy.",
        "16": "Las negras juegan c6: controlan d5 y b5 y abren paso a la dama hacia b6.",
        "17": "Alfil a g5: clava el caballo de f6. Si el caballo se mueve, se puede tomar la dama de e7 detrás. A las negras cada vez les cuesta más mover sus piezas.",
        "18": "Las negras juegan b5 para echar al alfil de c4. También ganan espacio en el flanco de dama, pero abren un hueco para que entren las piezas blancas.",
        "19": "¡El caballo se entrega para tomar en b5! En vez de retirar el alfil, Morphy sigue atacando. Con el rey negro aún en el centro, esto es muy peligroso para las negras.",
        "20": "Las negras toman el caballo y tienen un caballo de más. Pero su rey sigue en e8, y las piezas blancas siguen llegando.",
        "21": "¡Alfil a b5, jaque! El rey negro sigue atrapado en el centro. Las blancas tienen dos peones por el caballo y van directas al rey.",
        "22": "Las negras tapan con el caballo en d7. Pero este caballo está clavado: si se mueve, el rey negro queda en jaque. Ahora las blancas apuntarán a d7.",
        "23": "Las blancas enrocan largo. El rey queda a salvo y, a la vez, la torre llega a d1 para apuntar a d7. Una sola jugada defiende y ataca: magnífica.",
        "24": "Las negras llevan la torre a d8 para defender d7. Todavía no pueden enrocar, y la torre de h8 y el alfil de f8 no hacen nada.",
        "25": "¡La torre se entrega para tomar en d7! Las blancas dan una torre para eliminar a uno de los defensores negros.",
        "26": "Las negras recapturan con la torre. Ahora esta torre de d7 también está clavada: si se mueve, el alfil de b5 da jaque al rey negro.",
        "27": "La otra torre llega a d1 y vuelve a atacar d7. Ahora hay más piezas blancas atacando d7 que piezas negras defendiéndola.",
        "28": "La dama negra va a e6: ofrece cambiar damas para alejar a la dama blanca de b3 y quiere ayudar a d7. Pero ya es tarde.",
        "29": "El alfil toma en d7 con jaque. Las blancas eliminan a los defensores negros uno por uno.",
        "30": "Las negras recapturan con el caballo. Sin el caballo en f6, la diagonal del alfil de g5 hasta d8 queda abierta. Esa diagonal será clave al final.",
        "31": "¡La dama se entrega en b8 con jaque! Es la jugada más famosa de la partida. Las negras tienen que tomar con el caballo, y al irse el caballo de d7 se abre la columna d.",
        "32": "Las negras toman con el caballo. Ya no queda ninguna pieza negra que defienda d8.",
        "33": "¡Torre a d8, jaque mate! El alfil de g5 apoya d8 y el rey negro queda encerrado por sus propias piezas. Las blancas entregaron dama, torre y alfil, y terminaron con solo una torre y un alfil. Desarrollar rápido, poner el rey a salvo y atacar mientras el rey rival está en el centro: esta famosa partida reúne todas esas ideas importantes."
      } },
    "reti1910": { "t": "El mate de Réti", "w": "Richard Réti", "b": "Savielly Tartakower", "ev": "Una partida amistosa (no de torneo)", "d": "1910", "pl": "Austria (Viena)", "lead": "Dos futuros grandes maestros, una partida amistosa en Viena, once jugadas. Las blancas entregan la dama y terminan con un jaque doble: dos piezas dando jaque a la vez. Este tipo de mate lleva el nombre de las blancas: el mate de Réti.",
      c: {
        "0": "Viena, 1910. Las blancas son de Richard Réti, de veinte años; las negras, de Savielly Tartakower. Los dos llegaron a estar entre los mejores del mundo y son famosos por traer ideas nuevas al ajedrez. No era una partida de torneo, sino una amistosa jugada por una pequeña apuesta. Es corta, pero muestra muy bien por qué hay que poner pronto al rey a salvo.",
        "1": "Las blancas avanzan dos casillas el peón del rey. Ocupar el centro hace que las piezas de atrás salgan con facilidad. El alfil y la dama ya tienen el camino abierto.",
        "2": "Las negras juegan c6. En vez de ir al centro enseguida, preparan d5 para atacar el peón de e4. Esta apertura tan sólida se llama Defensa Caro-Kann.",
        "3": "Las blancas ponen también el otro peón en d4. Dos peones juntos en el centro: las blancas tienen mucho espacio. Las negras intentarán romperlos.",
        "4": "Como estaba previsto, d5. El peón desafía a e4: \"puedo capturarte\". Las blancas deben decidir si lo defienden, lo avanzan o lo cambian.",
        "5": "Las blancas sacan un caballo para defender e4. Desarrollan una pieza y defienden a la vez, sin perder tiempo.",
        "6": "Las negras toman el peón de e4. Cambiando peones centrales, hacen más pequeño el centro blanco.",
        "7": "Las blancas recapturan con el caballo, que queda en el centro del tablero. Un caballo central llega a muchas casillas y es muy fuerte.",
        "8": "Las negras sacan un caballo frente al de e4. Aquí se suele jugar alfil a f5, pero las negras invitan a cambiar caballos.",
        "9": "La dama sale pronto a d3 para defender el caballo de e4. Normalmente no conviene sacar la dama tan rápido, pero las blancas tienen un plan. Recuerda que esta dama está en la columna d, frente al rey negro.",
        "10": "Las negras juegan e5 y ofrecen un peón para abrir caminos al alfil y a la dama. Es una jugada activa que provoca lucha en el centro.",
        "11": "Las blancas toman el peón de e5. Aceptan el regalo, pero así la dama negra tiene más libertad.",
        "12": "¡Jaque! La dama negra de a5 apunta en diagonal al rey de e1. Al mismo tiempo piensa recuperar el peón de e5: dos tareas con una jugada. Las blancas tienen que tapar.",
        "13": "Las blancas tapan el jaque con el alfil en d2. La dama podría tomar el alfil, pero la dama blanca lo protege bien.",
        "14": "Las negras recuperan el peón y el material vuelve a estar igualado. Además, esta dama mira por la columna e al caballo de e4 y al rey detrás. Si el caballo se mueve, el rey queda en jaque, así que el caballo no puede moverse. Parece que las negras lo van a ganar.",
        "15": "Las blancas enrocan largo. El rey sale de la columna e y el caballo vuelve a estar libre. A la vez llega una torre a d1: la torre de d1, la dama de d3 y la casilla d8, junto al rey negro, quedan en la misma línea. Esta es la trampa blanca.",
        "16": "Las negras toman el caballo de e4 y parecen ganar una pieza. Pero el rey negro sigue en e8 y no ha enrocado. Las piezas blancas están en la columna d y el rey negro está desprotegido. Esta jugada, que pierde la partida, es el momento decisivo.",
        "17": "¡Dama a d8, jaque! Las blancas regalan su pieza más fuerte. La única pieza negra que puede tomarla es el rey. Al dejar que la tome, las blancas arrastran al rey a la casilla peligrosa d8.",
        "18": "Las negras tienen que tomar con el rey; no hay otra forma de parar el jaque. El rey queda en d8, con la torre de d1 esperando detrás.",
        "19": "El alfil va de d2 a g5 con jaque y, a la vez, abre el camino de la torre de d1, que también da jaque por la columna d. Dos piezas dando jaque a la vez: un jaque doble. No se puede parar capturando una pieza ni tapando, así que el rey tiene que huir.",
        "20": "El rey huye a c7. Si fuera a e8, la torre vendría a d8 y daría mate. Vaya donde vaya, las blancas tienen preparado el golpe final.",
        "21": "¡Alfil a d8: jaque mate en diagonal al rey de c7! El alfil está protegido por la torre de d1, así que el rey no puede tomarlo. Casillas como b8, c8, b7 y c6 están ocupadas por piezas negras, y la torre vigila d6 y d7. En solo once jugadas, las blancas entregaron la dama y ganaron con dos piezas pequeñas. La partida enseña lo peligroso que es ir a por material antes de enrocar. Algunos registros dicen que las negras abandonaron una jugada antes."
      } },
    "immortal": { "t": "La Inmortal", "w": "Adolf Anderssen", "b": "Lionel Kieseritzky", "ev": "Partida informal durante una pausa del torneo de Londres 1851", "d": "1851", "pl": "Reino Unido (Londres)", "lead": "Londres, durante el primer torneo internacional de ajedrez: una partida jugada en un descanso. Las blancas entregan un alfil, las dos torres y al final la dama, y dan mate con las tres piezas menores que les quedan. Se dice que las negras abandonaron antes del final y que las últimas jugadas serían el remate que mostró el blanco.",
      c: {
        "0": "Londres, 1851. En una pausa del torneo, el alemán Anderssen (blancas) y Kieseritzky, figura de París (negras), jugaron una partida amistosa.",
        "1": "Las blancas avanzan dos casillas el peón del rey.",
        "2": "Las negras hacen lo mismo.",
        "3": "¡f4! Las blancas ofrecen un peón: es el Gambito de Rey. La idea es apartar del centro el peón negro de e5.",
        "4": "Las negras aceptan el peón.",
        "5": "El alfil sale y apunta a f7, junto al rey negro.",
        "6": "¡Jaque! Sin el peón f blanco, la diagonal de h4 a e1 está abierta.",
        "7": "El rey se aparta. Ahora las blancas ya no podrán enrocar.",
        "8": "Las negras también ofrecen un peón, para atraer al alfil a b5.",
        "9": "Las blancas lo toman.",
        "10": "Sale un caballo que ataca el peón de e4.",
        "11": "Las blancas sacan un caballo y echan a la dama de h4.",
        "12": "La dama se retira a h6.",
        "13": "d3 defiende e4 y abre paso al alfil de c1.",
        "14": "Caballo a h5. El plan es saltar a g3 con jaque y atacar la torre de h1.",
        "15": "El caballo blanco va a h4, listo para saltar a f5 y molestar a la dama negra.",
        "16": "La dama negra va a g5 y ataca al caballo de h4.",
        "17": "Caballo a f5, una buena casilla protegida por el peón de e4. También apunta al peón de g7.",
        "18": "c6 intenta echar al alfil de b5.",
        "19": "Las blancas no salvan el alfil: g4 persigue al caballo de h5.",
        "20": "El caballo vuelve a f6.",
        "21": "Torre a g1, defendiendo el peón de g4. Las blancas dejan ir el alfil de b5. ¡Qué valentía!",
        "22": "Las negras toman el alfil y tienen una pieza de más.",
        "23": "El peón h empieza a perseguir a la dama negra.",
        "24": "La dama va a g6.",
        "25": "h5 vuelve a perseguir a la dama.",
        "26": "La dama solo puede volver a g5. Cada vez tiene menos casillas.",
        "27": "La dama blanca va a f3. Si luego el alfil toma en f4, la dama negra podría quedar atrapada.",
        "28": "Las negras devuelven el caballo a g8 para que la dama pueda escapar a f6.",
        "29": "El alfil toma el peón de f4 y ataca a la dama.",
        "30": "La dama escapa a f6.",
        "31": "Sale un caballo con la idea de saltar a d5 y atacar a la dama.",
        "32": "El alfil sale y apunta a la torre de g1.",
        "33": "Caballo a d5, atacando la dama de f6 y la casilla c7. A las blancas no les importa perder la torre de g1.",
        "34": "La dama toma el peón de b2 y ataca la torre de a1.",
        "35": "¡Alfil a d6! Las blancas dejan ir las dos torres. A cambio, sus piezas tejen una red alrededor del rey negro.",
        "36": "Las negras toman la torre de g1.",
        "37": "¡e5! Este peón corta la diagonal de la dama de b2 hacia g7. La dama negra ya no puede volver a ayudar a su rey.",
        "38": "Las negras toman también la otra torre, con jaque.",
        "39": "El rey va a e2. A las blancas solo les quedan la dama, dos caballos y un alfil.",
        "40": "El caballo va a a6 para defender c7. Se dice que las negras abandonaron por aquí; lo que sigue sería el remate que mostró el blanco.",
        "41": "El caballo toma en g7 con jaque.",
        "42": "El rey huye a d8.",
        "43": "¡La dama se entrega en f6 con jaque! También se va la última pieza grande.",
        "44": "Las negras tienen que tomar con el caballo.",
        "45": "¡Alfil a e7, jaque mate! El caballo de d5 controla e7 y c7, y el de g7 controla e8. Las blancas ganan con solo un alfil y dos caballos."
      } },
    "mimiaka": { "t": "La partida de las orejas rojas", "w": "Hon’inbō Shūsaku", "b": "Inoue Gennan Inseki", "ev": "Partida en Osaka (jugada en tres días)", "d": "1846", "pl": "Japón (Osaka)", "lead": "Shūsaku, con 17 años y 4-dan, se enfrentó a Gennan (8-dan), uno de los mejores jugadores de su tiempo. Se cuenta que, al ver la jugada 127, a Gennan se le pusieron rojas las orejas. No había komi: las negras ganaron por 2 puntos.",
      c: {
        "0": "Osaka, 1846. Shūsaku lleva negras y Gennan blancas. El día anterior empezaron una partida con dos piedras de hándicap, pero se interrumpió; ahora Shūsaku juega con negras sin hándicap.",
        "1": "Negro 1 en el punto 3-4 de arriba a la derecha (R16): un lugar bajo que asegura bien la esquina.",
        "2": "Blanco 2 toma el 3-4 de arriba a la izquierda (D17). Primero se reparten las esquinas vacías.",
        "5": "Con 1, 3 y 5, las negras ocupan tres esquinas, todas en puntos 3-4. Era el comienzo favorito de Shūsaku y muchos lo estudiaron después.",
        "6": "Blanco 6 en C14, en el lado izquierdo. En vez de acercarse a la esquina negra, se coloca en el lado: algo poco habitual.",
        "7": "Negro 7 (E4) cierra la esquina inferior izquierda con una segunda piedra. Este «cierre» la hace muy sólida.",
        "8": "Blanco 8 (R5) se acerca a la esquina negra de Q3. Va a empezar una gran lucha abajo a la derecha.",
        "10": "Blanco 10 (O4) es el taisha: cubre la piedra negra en diagonal desde lejos. Tiene muchísimas variantes y era el favorito de Gennan.",
        "11": "Con 11 (Q5), las negras entran en una línea difícil. Gennan conocía muy bien el taisha, así que hay que ir con cuidado.",
        "24": "Abajo a la derecha las piedras se enredan; cada bando intenta cortar al otro. Tras Blanco 24 (N4), a las negras les cuesta salir.",
        "25": "Negro 25 (N3). Estudios posteriores indican que aquí había algo mejor. Incluso para un maestro era un momento difícil.",
        "28": "Con 28 (M3) y 30 (L2), las blancas atacan enseguida el punto débil. Las negras pueden quedar encerradas en poco espacio abajo.",
        "31": "Negro 31 (M4) es importante. Prepara el ko que viene —la lucha de capturar y recapturar— creando lugares donde las blancas tendrán que responder.",
        "36": "Blanco 36 (N2). Antes de empezar el ko, las blancas juegan aquí primero. Buen momento.",
        "40": "Blanco 40 (R1) captura una piedra y empieza el ko. Quien perdió la piedra no puede recapturar enseguida: primero juega una amenaza en otro sitio.",
        "41": "Negro 41 (O5) es una amenaza de ko. Cuesta algo, pero aquí no hay nada mejor.",
        "53": "Negro 53 (R10) es una idea ingeniosa que pocos encontrarían. Ataca la forma blanca del lado derecho.",
        "60": "Blanco 60 (S3) es una jugada grande. Además permite que 62 (M1) salga con iniciativa.",
        "63": "Con Negro 63 (O1) se calma la larga lucha de abajo a la derecha. Blanco tiene territorio abajo; Negro, un muro grueso a la derecha. Hasta aquí Blanco parece ir mejor.",
        "67": "Negro 67 (L17). Apoyado en el muro de la derecha, Negro prepara un gran marco arriba.",
        "72": "Blanco 72 (P13) es excelente. Colocado justo encima del muro negro, impide que el marco negro crezca.",
        "74": "Desde aquí hasta la jugada 100, más o menos, Gennan no comete ni un descuido. Esquiva los ataques y mantiene sus piedras unidas.",
        "83": "Negro 83 (H3) entra en la zona blanca de abajo para reducirla.",
        "96": "Desde Blanco 96 (R14) hay una lucha fina junto a la esquina negra de arriba a la derecha. Blanco vuelve a encontrar buena forma.",
        "107": "Negro 107 (P10) captura una piedra blanca. El grupo negro de la derecha ya está a salvo.",
        "118": "Blanco 118 (M19) captura una piedra y su grupo de arriba también vive. El marco negro de arriba queda más pequeño de lo esperado.",
        "126": "Blanco 126 (J5). Las blancas son fuertes abajo y se extienden hacia el centro. Se dice que casi todos los profesionales presentes creían que ganaba Blanco.",
        "127": "Esta es la famosa jugada de las orejas rojas, Negro 127 (K11). Se dice que esta piedra central trabaja en cuatro direcciones a la vez: amplía la zona negra de arriba, debilita la fuerza blanca de abajo, ayuda al grupo negro de la derecha y frena a Blanco hacia la izquierda.",
        "128": "En ese momento, un médico que miraba la partida notó que las orejas de Gennan se habían puesto rojas. Sabía poco de go, pero se cuenta que lo tomó como señal de nervios y predijo que ganarían las negras.",
        "131": "Negro 131 (D10). Las negras entran también en el lado izquierdo blanco y recortan territorio por todo el tablero.",
        "147": "Negro 147 (K10). La piedra de la jugada 127 empieza a rendir: Negro avanza entre los grupos blancos del centro.",
        "160": "Blanco 160 (H8). Defiende sus piedras del centro mientras apunta al grupo negro de abajo a la izquierda. La partida sigue reñida.",
        "167": "Negro 167 (C2) es preciso. Las piedras negras de la esquina inferior izquierda quedan a salvo y la amenaza blanca desaparece.",
        "175": "Negro 175 (G4) captura una piedra blanca. El territorio blanco de abajo no es tan grande como parecía.",
        "199": "Negro 199 (K7). La lucha del centro se calma y empieza el final: fijar las fronteras, donde cada punto cuenta.",
        "212": "Con 212 (D19) y 216 (F19), Blanco captura piedras negras en el borde superior. En el final nadie cede ni un punto.",
        "228": "Blanco 228 (N12) crea un ko en el centro. Durante más de 80 jugadas se captura y recaptura en M13 y N13.",
        "236": "Blanco 236 (T8), jugado durante el ko, captura una piedra. Algunos analistas creen que terminar el ko aquí habría dejado la partida aún más igualada.",
        "275": "Negro 275 (T14) captura dos piedras blancas. Durante el ko, ambos ganan aquí y pierden allá por todo el tablero.",
        "299": "Negro 299 (J16) captura cuatro piedras blancas de una vez. Las negras mantienen firme la parte de arriba.",
        "311": "Negro 311 (M13) cierra el ko. Por fin termina la larga lucha.",
        "325": "La partida termina en la jugada 325 y el recuento da 2 puntos de ventaja a Negro. Aun sin komi, que un joven de 17 años venciera a alguien como Gennan causó sensación, y el nombre de Shūsaku se hizo famoso."
      } },
    "evergreen": { "t": "La Siempreviva", "w": "Adolf Anderssen", "b": "Jean Dufresne", "ev": "Una partida amistosa (no de torneo)", "d": "1852", "pl": "Alemania (probablemente Berlín)", "lead": "Anderssen, el de la Inmortal, jugó esta otra joya un año después. Justo cuando las negras amenazan mate, las blancas mueven tranquilamente una torre, luego entregan la dama y terminan con un jaque doble. Se la llama \"siempreviva\" porque nunca se marchita.",
      c: {
        "0": "Una partida publicada en una revista en 1852. Las blancas son de Anderssen y las negras de su amigo Dufresne. Se cree que se jugó en Berlín, pero ningún registro lo confirma.",
        "1": "Las blancas avanzan dos casillas el peón del rey.",
        "2": "Las negras hacen lo mismo.",
        "3": "El caballo ataca el peón de e5.",
        "4": "Las negras defienden e5 con un caballo.",
        "5": "El alfil sale y apunta a f7.",
        "6": "Las negras sacan también un alfil.",
        "7": "¡b4! Una entrega de peón llamada Gambito Evans. Mientras las negras lo toman, las blancas refuerzan el centro.",
        "8": "Las negras toman el peón.",
        "9": "c3 persigue al alfil y prepara d4.",
        "10": "El alfil se retira a a5.",
        "11": "d4 ocupa el centro.",
        "12": "Las negras toman el peón.",
        "13": "Las blancas no recapturan: enrocan. La seguridad del rey y las piezas activas van antes que los peones.",
        "14": "El peón negro avanza hasta d3, metido en el campo blanco.",
        "15": "Dama a b3. Junto con el alfil de c4 apunta a f7.",
        "16": "Las negras defienden f7 con la dama.",
        "17": "e5 persigue a la dama.",
        "18": "La dama va a g6.",
        "19": "Torre a e1, a la columna e para apoyar el peón de e5.",
        "20": "Las negras sacan un caballo para preparar el enroque.",
        "21": "Alfil a a3, apuntando en diagonal al caballo de e7. Si ese caballo se mueve, el alfil llegará a f8, así que a las negras les cuesta enrocar corto.",
        "22": "Las negras ofrecen un peón para desviar las piezas blancas.",
        "23": "La dama lo toma.",
        "24": "Torre a b8, persiguiendo a la dama por la columna b.",
        "25": "La dama va a a4.",
        "26": "El alfil se retira a b6.",
        "27": "Sale un caballo. Casi todas las piezas blancas están en juego.",
        "28": "Las negras desarrollan el otro alfil.",
        "29": "Caballo a e4, mirando hacia f6.",
        "30": "La dama negra va a f5 y ataca al caballo de e4.",
        "31": "El alfil toma el peón de d3 y defiende el caballo de e4.",
        "32": "Dama a h5, apuntando al caballo de f3.",
        "33": "¡El caballo se entrega en f6 con jaque!",
        "34": "Las negras toman con un peón.",
        "35": "Las blancas recapturan con un peón y atacan al caballo de e7. En la columna e, la torre de e1 también mira a e7.",
        "36": "Torre a g8, apuntando a g2. Si la dama de h5 toma en f3, el mate está cerca.",
        "37": "¡Una tranquila jugada de torre a d1! El rey blanco está en peligro, pero en vez de defender, las blancas apuntan a d7. Esta es la jugada que hizo \"siempreviva\" a la partida.",
        "38": "Las negras toman el caballo de f3. Tomar en g2 a continuación sería mate.",
        "39": "Pero las blancas juegan antes. ¡La torre toma el caballo de e7 con jaque!",
        "40": "Las negras recapturan con el caballo de c6. Ahora la diagonal de a4 a d7 está abierta.",
        "41": "¡La dama se entrega en d7 con jaque!",
        "42": "Las negras tienen que tomar con el rey.",
        "43": "El alfil va a f5 con jaque y además abre la columna d para la torre de d1: jaque doble.",
        "44": "El rey va a e8. En c6, el alfil daría mate en d7.",
        "45": "Alfil a d7, jaque.",
        "46": "El rey va a f8.",
        "47": "¡El alfil de a3 toma el caballo de e7: jaque mate! El alfil de d7 controla e8, y el peón de f6 controla e7 y g7."
      } },
    "lasker1912": { "t": "La cacería del rey", "w": "Edward Lasker", "b": "George Alan Thomas", "ev": "Partida rápida amistosa en el City of London Chess Club", "d": "1912", "pl": "Reino Unido (Londres)", "lead": "Una partida rápida y amistosa en un club de Londres. Las blancas entregan la dama y persiguen al rey negro a través de todo el tablero, de g8 a g1. Las primeras jugadas aparecen en órdenes un poco distintos según el registro, pero la posición tras la jugada 10 es la misma.",
      c: {
        "0": "Octubre de 1912, City of London Chess Club. Las blancas son de Edward Lasker, un joven ingeniero recién llegado de Alemania; las negras, de George Alan Thomas, luego campeón británico. Fue una partida rápida y amistosa. Es famosa como \"cacería del rey\": el rey negro es perseguido desde g8 hasta g1, al otro lado del tablero. Lasker se fue después a Estados Unidos y se hizo conocido por sus libros de ajedrez.",
        "1": "Las blancas empiezan con d4, el peón de dama. Controla e5 y c5 y abre paso al alfil de c1.",
        "2": "Las negras juegan e6: primero una posición sólida, preparando f5 o d5.",
        "3": "Caballo a f3. Controla e5 y ayuda a defender el flanco de rey: la casilla más natural.",
        "4": "Las negras juegan f5 y controlan e4, como en la Defensa Holandesa. Pero mover un peón delante del rey lo debilita un poco.",
        "5": "El otro caballo va a c3, preparando e4 para atacar el peón de f5.",
        "6": "Las negras sacan un caballo a f6: controlan aún más e4 y preparan el enroque.",
        "7": "Alfil a g5, apuntando al caballo de f6. Ese caballo es un defensor importante del rey negro, así que las blancas quieren quitarlo pronto.",
        "8": "Las negras ponen el alfil en e7 para defender el caballo y se acercan al enroque.",
        "9": "Las blancas cambian el alfil por el caballo. Desaparece el caballo que protegía al rey negro.",
        "10": "Las negras recapturan con el alfil. Ahora este alfil de f6 se encarga de proteger el flanco de rey.",
        "11": "¡e4! Las blancas atacan el peón de f5 y ganan espacio en el centro. Se abren líneas y las piezas blancas se mueven mejor.",
        "12": "Las negras toman el peón de e4. Si no, las blancas jugarían e5 y empujarían a las piezas negras hacia atrás.",
        "13": "El caballo recaptura y se coloca en el centro, mirando al alfil de f6 y a las casillas g5 y d6.",
        "14": "Las negras juegan b6 para llevar el alfil a b7 y apuntar por la gran diagonal al caballo de e4.",
        "15": "Caballo a e5, una fuerte casilla central que también mira a g4 y f7. Los dos caballos blancos ya están cerca del flanco de rey negro.",
        "16": "Las negras enrocan. El rey está en g8. Pero sin el peón f, hay muchos huecos alrededor del rey.",
        "17": "Alfil a d3. Por ahora le estorba su propio caballo de e4, pero detrás está el peón de h7. En cuanto el caballo de e4 se mueva, este alfil apuntará directo a h7.",
        "18": "El alfil negro va a b7 y apunta por la gran diagonal al caballo de e4, quitando libertad a las piezas blancas.",
        "19": "Dama a h5, apuntando al peón de h7, que solo defiende el rey negro. Dama, alfil y caballos blancos apuntan todos al rey negro.",
        "20": "Las negras ponen la dama en e7. Protege el alfil de f6 y prepara ir a c5, pero no ven la idea blanca. Hacía falta h6 o tomar el caballo de e5. Este es el momento decisivo.",
        "21": "¡La dama se entrega en h7 con jaque! Las blancas regalan su pieza más fuerte. Lasker veía todo el camino para perseguir al rey hasta el mate.",
        "22": "Las negras tienen que tomar con el rey, que queda en h7.",
        "23": "El caballo toma el alfil de f6 con jaque. A la vez, e4 queda libre y el alfil de d3 también da jaque al rey de h7: jaque doble. No se puede tapar, así que el rey debe huir.",
        "24": "El rey va a h6. En h8, el otro caballo saltaría a g6 con mate. El rey es empujado cada vez más adelante.",
        "25": "El otro caballo salta de e5 a g4 con jaque, ataca al rey de h6 y lo empuja aún más.",
        "26": "El rey va a g5: abandona su campo y camina hacia el lado blanco.",
        "27": "¡Jaque con el peón h! Hasta los peones se unen a la cacería. El rey tiene que seguir avanzando.",
        "28": "El rey va a f4. Ya cruzó la mitad del tablero y entra en el campo blanco.",
        "29": "Otro jaque, con el peón g. Dos peones le cierran el camino de vuelta al rey.",
        "30": "El rey va a f3, en medio de las piezas blancas.",
        "31": "El alfil se retira de d3 a e2 con jaque. El rey es empujado todavía más adentro.",
        "32": "El rey va a g2. El rey blanco de e1 ya no está lejos.",
        "33": "Torre a h2, jaque. Por fin entra la torre.",
        "34": "El rey llega por fin a g1. Salió de g8 y llegó a la primera fila del otro lado del tablero.",
        "35": "El rey blanco pasa de e1 a d2. Así se abre el camino de la torre de a1, que da jaque al rey de g1 por la primera fila: ¡jaque mate! El enroque largo también daba mate, pero Lasker movió el rey. En una partida rápida, tras entregar la dama, las blancas persiguieron al rey durante catorce jugadas hasta el rincón más profundo de su propio campo. Una partida muy poco común."
      } },
    "toketsu": { "t": "La partida del vómito de sangre", "w": "Akaboshi Intetsu", "b": "Hon’inbō Jōwa", "ev": "Jugada en la residencia del señor Matsudaira de Suō (en cuatro días)", "d": "1835", "pl": "Japón (Edo)", "lead": "Una partida nacida de la lucha por el cargo de Meijin Godokoro, el más alto del go japonés. Inoue Gennan Inseki envió a su alumno Akaboshi Intetsu contra el Meijin Jōwa. Tras cuatro días de lucha, Intetsu perdió y, según se cuenta, escupió sangre ante el tablero.",
      c: {
        "0": "1835. Negras: Akaboshi Intetsu (7-dan); blancas: el Meijin Hon’inbō Jōwa. Gennan envió a su mejor alumno para poder decir que un Meijin que pierde ante un 7-dan no merece el título.",
        "1": "Negro 1 en el 3-4 de abajo a la izquierda (C4). Intetsu empieza con calma.",
        "4": "Tras cuatro jugadas hay una piedra en cada esquina: blancas abajo a la derecha y arriba a la izquierda; negras abajo a la izquierda y arriba a la derecha.",
        "6": "Blanco 6 (E3) ya se acerca a la esquina negra de abajo a la izquierda. Jōwa es activo desde el principio.",
        "10": "Blanco 10 (P4) cierra la esquina inferior derecha con una segunda piedra.",
        "12": "Blanco 12 (D6) presiona desde arriba la esquina negra de abajo a la izquierda. Aquí empieza la mayor lucha de la partida.",
        "13": "Negro 13 (E4) se pega a una piedra blanca. Las negras aceptan la pelea.",
        "20": "Blanco 20 (C3) se mete por debajo de la esquina negra: le quita territorio mientras intenta dar vida a sus piedras.",
        "28": "Blanco 28 (C9) se extiende mucho por el lado izquierdo. Suele considerarse excesivo: una jugada feroz, muy al estilo de Jōwa.",
        "33": "Negro 33 (C2). Se dice que es una línea nueva estudiada en secreto por la casa Inoue. Ataca las piedras blancas flotantes del centro y a la vez se traga las del lado izquierdo.",
        "36": "Blanco 36 (F3). Intenta encerrar a Negro desde fuera abajo a la izquierda mientras une sus piedras.",
        "43": "Negro 43 (E9). Las piedras blancas de la izquierda sufren. Hasta aquí Intetsu ha jugado bien y se considera que va por delante.",
        "45": "Negro 45 (D11) se extiende hacia arriba por el lado izquierdo, manteniendo separadas las piedras blancas y reforzándose.",
        "50": "Blanco 50 (C16). Deja por ahora la parte de abajo a la izquierda y va a la esquina superior izquierda.",
        "53": "Negro 53 (G17). Las negras entran en el lado superior para que Blanco no amplíe la esquina superior izquierda.",
        "58": "Blanco 58 (C14) se extiende desde la esquina superior izquierda por el lado y se acerca a las piedras negras de la izquierda.",
        "60": "Blanco 60 (G4) captura dos piedras negras. El grupo blanco de abajo a la izquierda respira un poco.",
        "62": "Blanco 62 (J17). También arriba se enfrentan. Hay piedras débiles por todo el tablero: una posición difícil.",
        "66": "Blanco 66 (B14). Junto a la esquina superior izquierda, Blanco asienta sus piedras.",
        "68": "Blanco 68 (B11). Las siguientes jugadas blancas, junto con la 80, se hicieron famosas como las jugadas geniales de Jōwa. Eran tan asombrosas que se decía que se las habían mostrado los fantasmas.",
        "70": "Blanco 70 (E12). En lugar de responder directamente a Negro en la izquierda, juega primero otro punto clave. Las posibilidades ocultas que quedan lo permiten.",
        "72": "Blanco 72 (R13). Se dirige al lado derecho para que la zona negra de arriba a la derecha no crezca.",
        "76": "Blanco 76 (O14). Enlaza el lado derecho con el centro y se prepara para dividir las piedras negras.",
        "80": "Blanco 80 (Q10) forma un «triángulo vacío», una figura que suele considerarse mala. Sin embargo, fue la base para partir en dos a las negras y atacarlas. Es el ejemplo clásico de jugada fea pero excelente.",
        "83": "Negro 83 (R3) entra en la esquina blanca de abajo a la derecha. Allí sigue una lucha feroz de capturas.",
        "91": "Negro 91 (Q4) captura una piedra blanca. La esquina de abajo a la derecha es importante para Negro.",
        "98": "Blanco 98 (M4). Rodea las piedras negras del lado inferior y no las deja vivir fácilmente.",
        "106": "Blanco 106 (S5) captura una piedra negra. Blanco conserva la esquina inferior derecha y las negras deben huir hacia fuera.",
        "113": "Negro 113 (K6). Las piedras negras de abajo buscan vida saliendo hacia el centro.",
        "120": "Blanco 120 (N9) cierra el paso a las piedras negras que huyen. En el centro, todo depende de quién se debilita primero.",
        "128": "Blanco 128 (L11) presiona también desde arriba las piedras negras del centro. Negro sigue sin poder relajarse.",
        "138": "Blanco 138 (K8) captura una piedra y empieza un ko en el centro. Durante unas 30 jugadas se captura y recaptura en K8 y L8.",
        "152": "Blanco 152 (E11) es una amenaza de ko. Durante el ko, Blanco encuentra jugadas por todas partes que Negro debe contestar.",
        "170": "Blanco 170 (P15). El ko del centro se ha calmado y Blanco va arriba a la derecha, apuntando a un gran grupo negro que aún no vive del todo.",
        "178": "Blanco 178 (J14) salta al centro de la zona superior para separar las piedras negras a izquierda y derecha. El ataque de división preparado desde la jugada 80 empieza de verdad.",
        "193": "Negro 193 (J11) captura una piedra blanca. Negro lucha por conectar y vivir.",
        "201": "Negro 201 (R14) captura una piedra y empieza un nuevo ko en el lado derecho, con capturas en R14 y R15.",
        "206": "Blanco 206 (M13). Incluso durante el ko, Blanco va apretando poco a poco a las piedras negras del centro.",
        "222": "Blanco 222 (L14) captura una piedra. Las negras de arriba siguen partidas en dos, y salvar ambas partes se complica.",
        "230": "Blanco 230 (C13) golpea también el punto débil negro del lado izquierdo. Las piedras blancas ya están bien unidas por todo el tablero.",
        "237": "Con 237 (F12) y 239 (E13), Negro recupera piedras arriba a la izquierda. Aun así, la diferencia total no se reduce.",
        "246": "Tras Blanco 246 (L8), Intetsu abandonó. Se cuenta que, al recoger las piedras, escupió sangre sobre el tablero. Probablemente llevaba tiempo enfermo, y murió poco después. Para Jōwa se considera la mayor victoria de su vida."
      } },
    "deepblue1997": { "t": "La victoria de Deep Blue", "w": "Deep Blue (computadora de IBM)", "b": "Garri Kaspárov", "ev": "Partida 6 de la revancha contra Deep Blue de IBM (match a seis partidas)", "d": "1997", "pl": "Estados Unidos (Nueva York)", "lead": "El campeón del mundo Kaspárov contra Deep Blue, una computadora de ajedrez construida por IBM, en un match a seis partidas. Con el marcador igualado tras cinco partidas, la última terminó en solo 19 jugadas. Fue la primera vez que una computadora venció al campeón del mundo en un match completo de varias partidas.",
      c: {
        "0": "Nueva York, 11 de mayo de 1997. Kaspárov había ganado el match del año anterior. Esta vez el marcador está 2½–2½ tras cinco partidas. Deep Blue lleva las blancas.",
        "1": "Las blancas avanzan dos casillas el peón del rey.",
        "2": "Kaspárov juega c6: la Defensa Caro-Kann.",
        "3": "Las blancas llevan el otro peón al centro.",
        "4": "Las negras juegan d5 contra e4.",
        "5": "El caballo defiende e4.",
        "6": "Las negras toman el peón de e4.",
        "7": "El caballo recaptura.",
        "8": "Las negras ponen un caballo en d7 para sacar después el otro a f6.",
        "9": "El caballo salta a g5: un plan agudo que apunta a f7 y e6.",
        "10": "Las negras sacan el caballo a f6.",
        "11": "Alfil a d3, mirando el flanco de rey negro.",
        "12": "Las negras refuerzan la defensa con e6.",
        "13": "El otro caballo sale a f3.",
        "14": "Las negras juegan h6 para echar al caballo de g5. Pero en esta posición ya se conocía un sacrificio de caballo para las blancas. Se dice que fue una elección rara en Kaspárov.",
        "15": "¡El caballo se entrega en e6! Se dice que Deep Blue sacó esta jugada de las aperturas que tenía guardadas de antemano.",
        "16": "Las negras no toman enseguida: juegan la dama a e7. En la columna e apunta al caballo de e6 y al rey blanco detrás.",
        "17": "Las blancas enrocan y ponen el rey a salvo.",
        "18": "Las negras toman el caballo y van por delante en material.",
        "19": "Alfil a g6, jaque. Sin el peón de f7, la diagonal llega hasta el rey.",
        "20": "El rey va a d8. Las negras ya no pueden enrocar y el rey queda cerca del centro.",
        "21": "El otro alfil sale y apunta a las casillas alrededor del rey negro.",
        "22": "Las negras juegan b5 para hacer sitio en el flanco de dama al rey y al alfil.",
        "23": "a4 ataca el peón de b5.",
        "24": "Las negras llevan el alfil a b7.",
        "25": "Torre a e1. En la columna e mira al peón de e6, y detrás, a la dama de e7.",
        "26": "El caballo negro va a d5 y ataca al alfil de f4.",
        "27": "El alfil se retira a g3.",
        "28": "El rey negro va a c8, algo más seguro.",
        "29": "Las blancas toman el peón de b5.",
        "30": "Las negras recapturan.",
        "31": "Dama a d3, mirando el peón de b5 y la casilla f5.",
        "32": "Las negras defienden b5 con el alfil.",
        "33": "¡Alfil a f5! Se puede tomar gratis.",
        "34": "Las negras toman con un peón. Pero así desaparece el peón de la columna e.",
        "35": "La torre toma la dama de e7. Las blancas han dado un caballo, un alfil y una torre, pero han ganado la dama.",
        "36": "Las negras recuperan la torre con el alfil.",
        "37": "¡c4! El peón ataca a la vez b5 y d5, y la defensa negra empieza a derrumbarse. Kaspárov abandonó aquí, seguramente porque veía a su rey demasiado expuesto para parar el ataque. Una computadora había ganado un match al campeón del mundo."
      } },
    "seigen1933": { "t": "La partida del 3-3, la hoshi y el tengen", "w": "Go Seigen", "b": "Hon’inbō Shūsai", "ev": "Partida conmemorativa con el Meijin (más de tres meses)", "d": "1933–1934", "pl": "Japón (Tokio)", "lead": "Go Seigen, con 19 años y 5-dan, jugó contra el Meijin Hon’inbō Shūsai. Con negras abrió en el 3-3, luego en un punto estrella y luego en el centro exacto (tengen), rompiendo las reglas de la época y asombrando a todos. Con muchas interrupciones duró más de tres meses; ganó Blanco por 2 puntos.",
      c: {
        "0": "1933. Ese año Go Seigen y su amigo Kitani Minoru difundían un nuevo estilo de apertura, el «Shinfuseki». Todos querían ver cómo lo usaría contra el Meijin.",
        "1": "Negro 1 en el 3-3 de arriba a la derecha (R17). Asegura la esquina en una jugada, pero tiene poca influencia hacia fuera; entonces nadie lo consideraba una buena primera jugada.",
        "3": "Negro 3 en el punto estrella de abajo a la izquierda (D4). Al contrario que el 3-3, prioriza la expansión hacia fuera.",
        "5": "Negro 5 va al centro exacto del tablero: el tengen (K10). Ni esquina ni lado, sino el medio. Ante el Meijin, Go Seigen mostró sus ideas nuevas sin rodeos.",
        "6": "3-3, estrella, tengen: cada piedra negra tiene su papel —territorio en la esquina, alcance exterior y fuerza central—. Con 6 (Q16), Blanco juega justo al lado del 3-3 negro.",
        "9": "Negro 9 (P18). Asienta la esquina superior derecha de forma compacta y segura: un estilo de territorio primero, propio del 3-3.",
        "11": "Negro 11 (K4) va al centro del lado inferior, justo debajo del tengen. Junto con esa piedra, busca una gran zona abajo.",
        "12": "Blanco 12 (M3) entra enseguida en el lado inferior para que Negro no construya un gran marco. El Meijin no se precipita y desmonta los planes negros uno a uno.",
        "13": "Negro 13 (D10), ahora en el centro del lado izquierdo. Las piedras negras están altas y juntas forman un marco amplio.",
        "14": "Blanco 14 (E16) cierra la esquina superior izquierda con una segunda piedra. El Meijin no se deja confundir por el estilo nuevo y asegura la esquina con calma.",
        "21": "Negro 21 (G10) une el tengen con la piedra del lado izquierdo, y la influencia negra se extiende por el centro.",
        "28": "Blanco 28 (D3) se mete bajo la piedra estrella negra de abajo a la izquierda y se queda la esquina. Negro la cede a cambio de fuerza exterior.",
        "30": "Blanco 30 (Q12) se extiende por el lado derecho y pone también una tapa sobre la esquina 3-3 negra, reduciendo su alcance.",
        "37": "Negro 37 (P15) captura una piedra blanca. Arriba a la derecha ambos chocan en una lucha cerrada.",
        "40": "Blanco 40 (O10) sale del lado derecho hacia el centro y se acerca a la influencia negra alrededor del tengen.",
        "44": "Blanco 44 (H17) ocupa un punto del lado superior para frenar la expansión negra hacia arriba.",
        "45": "Negro 45 (R7) empieza a trabajar en la posición blanca de abajo a la derecha. Sigue una larga lucha del lado derecho hacia esa esquina.",
        "59": "Negro 59 (R4) entra también en la esquina inferior derecha y reduce el territorio blanco.",
        "70": "Blanco 70 (N6) avanza del lado inferior al centro para separar las piedras negras de abajo a la derecha de las del centro.",
        "79": "Negro 79 (L9) refuerza el centro alrededor del tengen. Hasta aquí la partida parece bastante igualada.",
        "80": "Blanco 80 (C6) avanza desde la esquina inferior izquierda por el lado izquierdo, apuntando a las piedras negras de allí.",
        "98": "Blanco 98 (A11) captura dos piedras negras. Blanco vive con limpieza en el borde izquierdo, y el lado izquierdo negro queda menor de lo previsto.",
        "101": "Negro 101 (S14) vuelve arriba a la derecha para reducir la posición blanca del lado derecho.",
        "105": "Negro 105 (K17) ocupa el centro del lado superior y empieza a atacar las piedras blancas de allí.",
        "117": "Negro 117 (F17) entra también junto a la esquina blanca de arriba a la izquierda, y todo el lado superior se vuelve un campo de batalla.",
        "124": "Blanco 124 (K15) lleva sus piedras de arriba hacia el centro, cortando entre las negras por el camino.",
        "135": "Negro 135 (E9) captura dos piedras blancas. Negro recupera algo en el lado izquierdo.",
        "138": "Blanco 138 (N18) asegura territorio en el lado superior. En todo el tablero la posición está muy reñida.",
        "153": "Negro 153 (K14). Las piedras negras del centro forman un camino grueso que une arriba y abajo. La clave es cómo podrá Blanco romper ese grosor.",
        "159": "Negro 159 (F4) defiende con firmeza abajo a la izquierda. La siguiente jugada blanca es la más famosa de la partida.",
        "160": "Blanco 160 (H8) salta a un hueco del grosor negro: una jugada aguda con varios objetivos a la vez, desde la que Blanco empieza a entrar en el centro negro. Corrió el rumor de que la había encontrado un alumno y no Shūsai, pero nunca se ha demostrado.",
        "161": "Negro 161 (J8) responde enseguida, pero Blanco tiene más de un objetivo.",
        "162": "Blanco 162 (K12) pasa a la parte alta del centro y amenaza las conexiones negras.",
        "172": "Blanco 172 (F13) une piedras del centro con las de arriba a la izquierda. Poco a poco, el grosor central negro deja de convertirse en territorio.",
        "178": "Blanco 178 (N9) entra también en la zona negra a la derecha del centro.",
        "187": "Con 187 (M6) y 189 (L7), Negro captura piedras blancas. Aun así, Blanco ya ha llegado antes a los puntos importantes.",
        "198": "Blanco 198 (E12) captura una piedra. Las piedras blancas de arriba a la izquierda también quedan unidas, y Blanco va ligeramente por delante.",
        "203": "Negro 203 (B3). Desde aquí es el final: las fronteras de los bordes se fijan punto a punto.",
        "224": "Blanco 224 (T10) captura una piedra. Ni siquiera en el borde derecho cede Blanco un solo punto.",
        "233": "Negro 233 (L13) captura dos piedras blancas. Negro persigue hasta el final.",
        "252": "La partida termina en la jugada 252: Blanco gana por 2 puntos. Sin komi, Negro tenía la pequeña ventaja de salir primero, pero el Meijin se mantuvo firme hasta el final. Aun así, el 3-3, la estrella y el tengen de Go Seigen causaron sensación y anunciaron una nueva era de aperturas."
      } },
    "century1956": { "t": "La Partida del Siglo", "w": "Donald Byrne", "b": "Bobby Fischer", "ev": "Tercer torneo Trofeo Rosenwald (Memorial Rosenwald)", "d": "1956", "pl": "Estados Unidos (Nueva York)", "lead": "Bobby Fischer, con trece años, vence a Donald Byrne, uno de los maestros más fuertes de Estados Unidos. En la jugada 17 Fischer deja que le tomen la dama gratis, luego recupera pieza tras pieza y al final sus piezas pequeñas cazan al rey blanco. Fischer llegó a ser campeón del mundo.",
      c: {
        "0": "Nueva York, 17 de octubre de 1956, una partida de torneo. Las negras las lleva Fischer, de trece años; las blancas, Byrne, uno de los mejores jugadores estadounidenses.",
        "1": "Las blancas empiezan con un caballo.",
        "4": "Fischer juega g6 para poner el alfil en la gran diagonal.",
        "8": "Las negras enrocan: primero, el rey a salvo.",
        "10": "Las negras juegan d5. Empieza la lucha por el centro.",
        "15": "Con e4, las blancas tienen dos peones juntos en el centro.",
        "17": "Torre a d1, apoyando el peón de d4. Las blancas todavía no han enrocado.",
        "18": "El caballo va a b6 y persigue a la dama de c4.",
        "20": "Alfil a g4, presionando al caballo de f3.",
        "21": "El alfil blanco va a g5. El rey blanco sigue en el centro.",
        "22": "¡Caballo a a4! Salta a una casilla donde lo pueden tomar. La idea: si el caballo de c3 se va, el peón de e4 se queda sin defensa.",
        "23": "Las blancas no toman el caballo y llevan la dama a a3.",
        "26": "El caballo negro toma el peón de e4. El centro blanco se derrumba.",
        "27": "El alfil blanco toma el peón de e7 y ataca a la vez la dama negra y la torre de f8.",
        "28": "¡Dama a b6! Las negras dejan ir la torre de f8. Fischer cuenta con que el rey blanco sigue en el centro.",
        "29": "Las blancas no toman la torre: desarrollan el alfil.",
        "30": "El caballo toma el peón de c3 y ataca la torre de d1.",
        "31": "Alfil a c5, atacando la dama negra de b6.",
        "32": "¡Jaque de la torre por la columna e!",
        "33": "El rey va a f1. Ahora las blancas ya no podrán enrocar.",
        "34": "¡Alfil a e6! La jugada más famosa de la partida: las negras dejan que les tomen la dama gratis. A cambio, tienen un plan para recuperar pieza tras pieza.",
        "35": "Las blancas toman la dama negra.",
        "36": "Alfil a c4, jaque. Empieza el contraataque negro.",
        "38": "El caballo da jaque desde e2.",
        "40": "Cuando el rey vuelve a f1, el caballo se mueve y descubre un jaque del alfil de c4. De paso, el caballo se come el peón de d4.",
        "44": "El caballo vuelve a c3, otro jaque descubierto, y ahora ataca la torre de d1. Dar jaque una y otra vez mientras se ganan piezas se llama \"molino\".",
        "46": "Las negras recuperan el alfil. El caballo de c3 sigue atacando la torre de d1.",
        "50": "El caballo toma la torre de d1. Ahora las negras han recuperado más que la dama y van claramente por delante.",
        "52": "La torre toma también el peón de a2.",
        "56": "Las negras cambian torres. Cuantas menos piezas quedan, mejor para quien tiene más.",
        "57": "La dama blanca da jaque.",
        "58": "Las negras tapan con el alfil.",
        "64": "b5. El peón negro empieza a avanzar.",
        "68": "El rey va a g7 y libera el alfil de f8.",
        "70": "Ahora las piezas negras cazan al rey blanco. Jaque con un alfil.",
        "72": "El caballo da jaque en g3.",
        "74": "Jaque con el otro alfil.",
        "76": "Alfil a b3, jaque.",
        "78": "El caballo da jaque en e2.",
        "80": "El caballo da jaque en c3. El rey va de un lado a otro.",
        "82": "¡Torre a c2: jaque mate! Torre, dos alfiles y caballo trabajan juntos. Un chico de trece años mostró cómo muchas piezas pueden jugar como un equipo."
      } },
    "oshiro1849": { "t": "La primera partida del castillo de Shūsaku", "w": "Hon’inbō Shūsaku", "b": "Yasui Sanchi IX", "ev": "Partida del castillo (la partida anual en el castillo de Edo)", "d": "1849", "pl": "Japón (Edo)", "lead": "Las partidas del castillo eran la gran cita anual en la que los jugadores de las casas oficiales de go jugaban en el castillo del shōgun. Shūsaku, con 20 años, debutó ese año y ganó con negras por 11 puntos: el comienzo de un récord perfecto de 19 victorias en 19 partidas del castillo.",
      c: {
        "0": "1849. El año anterior Shūsaku fue nombrado heredero de la casa Hon’inbō, y ahora juega su primera partida del castillo. Se dice que estas partidas solían jugarse antes en otro lugar y en el castillo solo se reproducían.",
        "1": "Negro 1 en el 3-4 de arriba a la derecha (R16). Como siempre, Shūsaku empieza con un tranquilo 3-4.",
        "4": "Blanco 4 (C15) se acerca a la piedra negra de D17, arriba a la izquierda. Allí empieza pronto una lucha.",
        "5": "Negro 5 (C11) pinza desde abajo la piedra blanca que se acercó, para que Blanco no se asiente fácilmente en la izquierda.",
        "12": "Blanco 12 (C17). Blanco se queda la esquina superior izquierda y Negro obtiene piedras mirando hacia fuera: un reparto justo.",
        "13": "Negro 13 (J17) aprovecha las piedras exteriores y se extiende por arriba.",
        "15": "Negro 15 (C5) ocupa la última esquina libre, abajo a la izquierda. Ya están ocupadas las cuatro.",
        "16": "Blanco 16 (E4) se acerca enseguida a esa piedra negra, y también hay lucha abajo a la izquierda.",
        "19": "Negro 19 (D2) asegura con firmeza la esquina inferior izquierda: una elección sólida, muy de Shūsaku.",
        "23": "Negro 23 (E5) sale entre las piedras blancas y refuerza su grupo de abajo a la izquierda.",
        "29": "Negro 29 (F11) refuerza las piedras negras de la izquierda y a la vez mira hacia el centro.",
        "30": "Blanco 30 (H4) se extiende por abajo, presiona al grupo negro de la izquierda y construye su propia zona.",
        "31": "Negro 31 (O3) se acerca a la esquina blanca de abajo a la derecha.",
        "33": "Negro 33 (R3) se pega a la piedra blanca de la esquina. A partir de aquí Negro construye por fuera y Blanco avanza por la tercera línea del borde.",
        "43": "Negro 43 (Q8). Un grueso muro negro recorre ahora el lado derecho. Blanco tiene territorio en la esquina y el borde; Negro, fuerza exterior.",
        "44": "Blanco 44 (L17) entra entre las piedras negras del lado superior para que la zona negra no crezca demasiado.",
        "50": "Blanco 50 (R18) se mete bajo la esquina negra de arriba a la derecha, apuntando a su territorio.",
        "51": "Negro 51 (P13). Con el muro detrás, Negro prepara una gran zona del lado derecho hacia el centro.",
        "52": "Blanco 52 (D10) se mete entre las piedras negras del lado izquierdo. Allí las piedras se enredan.",
        "63": "Negro 63 (B10) juega en el borde izquierdo para que las piedras blancas no tengan base allí.",
        "65": "Negro 65 (G3) entra también en la zona blanca de abajo y reduce el territorio blanco.",
        "73": "Negro 73 (K17) refuerza sus piedras de arriba y presiona la piedra blanca de la jugada 44.",
        "76": "Blanco 76 (P11) salta dentro de la zona negra del lado derecho. Que esta piedra viva o muera cambiará mucho la cuenta.",
        "77": "Negro 77 (Q11) responde desde el lado de su muro y empuja a Blanco hacia el centro: defensa tranquila que también ataca, muy de Shūsaku.",
        "80": "Blanco 80 (N10) huye hacia el centro para escapar de la persecución negra.",
        "85": "Negro 85 (N12) sigue atacando mientras amplía su territorio de arriba y de la derecha. Ganar atacando: juego hábil.",
        "91": "Negro 91 (J7) juega encima de las piedras blancas de abajo y tapa también desde el centro la zona blanca.",
        "100": "Blanco 100 (S17) intenta algo en la esquina superior derecha para reducir el territorio negro.",
        "119": "Negro 119 (R17) defiende con firmeza la esquina superior derecha y frena el intento blanco.",
        "122": "Blanco 122 (G6) rodea por fuera las piedras negras de abajo a la izquierda para cortarlas del centro negro.",
        "131": "Negro 131 (M5) mete una cuña en la zona blanca, en medio del lado inferior.",
        "140": "Blanco 140 (B4) intenta algo en la esquina negra de abajo a la izquierda. Empieza una lucha cerrada de capturas en el borde izquierdo.",
        "156": "Blanco 156 (A8) captura dos piedras negras. La lucha del borde izquierdo se calma tras pequeñas ganancias de ambos.",
        "158": "Blanco 158 (L10). Blanco todavía tiene piedras en el centro y trata de reducir el territorio central negro.",
        "162": "Blanco 162 (O12) captura una piedra negra. Aun así, la zona negra de la derecha sigue siendo grande.",
        "172": "Blanco 172 (K18). Desde aquí es el final, empezando por la frontera del lado superior.",
        "186": "Blanco 186 (T16) recorta territorio negro en el borde superior derecho. En el final, ambos juegan primero lo más grande.",
        "205": "Negro 205 (Q18) cierra la parte derecha del lado superior y fija allí su territorio.",
        "223": "Negro 223 (P10) fija la frontera entre el territorio negro de la derecha y las piedras blancas que escaparon al centro.",
        "233": "Negro 233 (Q9) captura una piedra blanca. El territorio negro de la derecha está ya casi a salvo.",
        "239": "Negro 239 (A6) captura una piedra y aparece un ko en el borde izquierdo. La lucha punto a punto sigue hasta el final.",
        "260": "Blanco 260 (T6) captura una piedra y forma otro ko en el borde inferior derecho. Negro recaptura en 263 (T5).",
        "267": "La partida termina en la jugada 267: Negro gana por 11 puntos. Sin aventuras: Shūsaku atacó y dejó crecer su territorio con naturalidad, una victoria muy suya. Fue la primera de sus 19 victorias seguidas en el castillo."
      } },
    "shilin": { "t": "La partida del Shilin Guangji", "w": "Rojas (nombre no conservado)", "b": "Negras (nombre no conservado)", "ev": "Enciclopedia cotidiana Shilin Guangji: «partida ganada cediendo la salida, con cañones del mismo lado»", "d": "Siglo XIII", "pl": "China (Song–Yuan)", "lead": "Este registro procede del Shilin Guangji, una enciclopedia de la vida diaria reunida por Chen Yuanjing entre el final de la dinastía Song y el comienzo de la Yuan. Se considera uno de los registros completos de xiangqi más antiguos que se conservan. Es una partida modelo en la que el bando más fuerte cede la salida, y en solo nueve jugadas el caballo negro atrapa al carro rojo.",
      c: {
        "0": "Este registro tiene más de 700 años, de la época entre las dinastías Song y Yuan. Aparece en el capítulo de juegos de la enciclopedia Shilin Guangji y se considera una de las partidas completas de xiangqi más antiguas que conservamos. No se conocen los nombres de los jugadores. El título dice que el jugador fuerte «cedió la salida» al más débil, así que es una lección que muestra cómo pierde Rojas, que juega primero. Rojas está abajo y empieza.",
        "1": "Rojas lleva el cañón derecho a la columna central. Es el Cañón Central, que apunta directo al general negro, y sigue siendo una de las aperturas más fuertes. Vemos que ya se jugaba hace 700 años.",
        "2": "Negras también lleva un cañón al centro, y los dos cañones quedan frente a frente. Cuando ambos mueven el cañón del mismo lado se llama «cañones en la misma dirección». El duelo de cañones es popular desde hace siglos.",
        "3": "Rojas saca un caballo para proteger al soldado central. Ese soldado está atacado por el cañón negro y necesita un defensor. Además, el caballo se prepara para avanzar.",
        "4": "Negras hace lo mismo y protege su soldado central con un caballo. Los dos bandos primero construyen una base firme.",
        "5": "Rojas mueve el carro derecho un paso de lado, a una columna abierta. El carro es la pieza más fuerte del tablero, así que conviene ponerlo a trabajar pronto.",
        "6": "Negras saca el otro caballo y deja los carros en casa por ahora. La idea es adelantar piezas primero. Pero un carro que sale tarde puede costar usarlo en el ataque después.",
        "7": "El carro rojo cruza el río de golpe y entra en el campo negro. Quiere amenazar piezas negras, pero las demás piezas rojas siguen en casa, así que el ataque es algo apresurado. También podía sacar antes el caballo o el carro izquierdos.",
        "8": "Negras avanza un paso el soldado de la columna 3. Así abre camino al caballo para que pueda saltar adelante más tarde. Casi invita al carro rojo a venir.",
        "9": "El carro rojo captura un soldado y ahora apunta al caballo negro que está detrás. Ganar una pieza y amenazar otra parece estupendo. Pero el carro se ha adelantado mucho y no tiene amigos cerca. Un carro solo en campo enemigo es fácil de perseguir.",
        "10": "El caballo negro salta adelante. Escapa del carro y a la vez se acerca al campo rojo: dos tareas con una jugada. Este caballo será el protagonista de la partida.",
        "11": "Rojas retira el carro un paso para atacar al caballo desde el lado. El carro captura desde lejos, así que el caballo no puede descansar. Aun así, esta jugada no ayuda a desarrollar otras piezas rojas.",
        "12": "El caballo negro sigue avanzando y cruza el río hacia el campo rojo. Cada vez que huye del carro, queda más cerca del general rojo.",
        "13": "Rojas avanza un soldado para abrir paso a su propio caballo. La idea es sacarlo y cambiarlo por el caballo negro. Pero eso da tiempo a Negras para ir aún más lejos.",
        "14": "Negras sube un elefante y ataca al carro rojo. Usar una pieza defensiva para echar al carro enemigo es muy eficaz. Rojas debe mover otra vez el carro, y Negras gana otro tiempo.",
        "15": "El carro rojo se desliza de lado y captura otro soldado. Rojas tiene ya dos soldados de ventaja, pero esta es la jugada que pierde. El carro queda muy lejos de su general y no puede volver a defender. Rojas necesitaba protegerse del caballo, por ejemplo trayendo el carro a casa.",
        "16": "El caballo negro se mete más a fondo y ataca al carro rojo. Y hay más: si salta otra vez, dará jaque al general rojo y al mismo tiempo atacará al carro de la esquina roja. Un solo caballo ha creado dos amenazas a la vez.",
        "17": "Rojas persigue al caballo con el carro. Pero ya no se puede detener. Alrededor del general rojo no queda nadie para ayudar.",
        "18": "¡El caballo salta con jaque! También ataca al carro de la esquina roja, así que cuando el general se aparte, el carro se perderá. Solo nueve jugadas, pero la partida enseña qué le pasa a un carro que avanza solo y por qué las piezas deben luchar juntas. Hace 700 años los jugadores pensaban en lo mismo sobre el mismo tablero."
      } },
    "qima13": { "t": "El sacrificio de caballo en trece jugadas (Juzhongmi)", "w": "Rojas (nombre no conservado)", "b": "Negras (nombre no conservado)", "ev": "Juzhongmi, volumen 1, partida 1", "d": "1632 (publicación)", "pl": "China (Ming)", "lead": "Es la primerísima partida del Juzhongmi («El secreto de la mandarina»), libro de xiangqi publicado por Zhu Jinzhen, de la dinastía Ming, en 1632. Rojas deja que Negras le capture un caballo gratis, entra al ataque mientras tanto y da mate en trece jugadas. Con el nombre de «sacrificio de caballo en trece jugadas» sigue siendo querida casi 400 años después.",
      c: {
        "0": "Es la partida 1 del Juzhongmi, libro impreso en 1632, cerca del final de la dinastía Ming. Junto con el posterior Manual de la flor del ciruelo, se le llama uno de los dos grandes clásicos del xiangqi. No es una partida real sino un modelo para enseñar un plan, por eso no hay nombres de jugadores. Rojas está abajo y empieza, y la partida termina en solo trece jugadas.",
        "1": "Rojas lleva el cañón derecho al centro. Es el Cañón Central, que mira directo al general negro. El Juzhongmi es famoso por estudiar cómo atacar con esta apertura.",
        "2": "Negras también lleva al centro el cañón del mismo lado. Son los «cañones en la misma dirección», que chocan de frente. Cada bando apunta al soldado central del otro.",
        "3": "Rojas saca un caballo para proteger el soldado central. Defiende al soldado que apunta el cañón negro, y el caballo empieza a trabajar.",
        "4": "Negras también protege el soldado central con un caballo. Hasta aquí los dos tienen la misma forma.",
        "5": "Rojas adelanta el carro derecho un solo paso. Así, en la próxima jugada, podrá correr de lado. Un carro que se mueve de lado así se llama «carro horizontal», y puede pasar rápido a cualquier flanco.",
        "6": "Negras mueve el carro un paso de lado para poder subir recto por el tablero. Es un «carro recto». Carro horizontal contra carro recto: dos maneras distintas de usar el carro, frente a frente.",
        "7": "El carro horizontal rojo se pasa a una columna de la izquierda. Esa columna corre junto al consejero negro, donde la defensa es débil. Rojas se prepara para entrar por aquí.",
        "8": "El carro recto negro cruza el río y se mete hondo en el campo rojo. Negras quiere responder con su propio ataque. Pero es una jugada que se apura a atacar antes de defender.",
        "9": "El carro rojo entra hasta el fondo del campo negro. Se coloca en el «ojo» del elefante, el punto por el que el elefante debe pasar, así que el elefante negro no puede moverse. Pegado al consejero, ya está muy cerca del general.",
        "10": "Negras saca el otro caballo hacia el borde. Parte de la idea es impedir que el carro rojo se cuele de lado.",
        "11": "¡Aquí está el sacrificio del caballo! Rojas sube el otro carro un paso. Eso deja al caballo de la esquina izquierda sin defensor, y el cañón negro puede tomarlo gratis. Pero a cambio de un caballo, Rojas gana tiempo para meter rápido los dos carros en el ataque.",
        "12": "El cañón negro captura el caballo rojo. Parece que Negras ganó una pieza. Pero ese cañón queda lejos de casa y no puede ayudar a defender. Se dice que aquí era mejor reforzar la defensa subiendo un consejero en lugar de capturar.",
        "13": "El cañón rojo avanza. Usa el cañón central negro como «pantalla» para saltar y ahora apunta al caballo negro que está detrás. El cañón es una pieza curiosa que captura saltando exactamente una pieza.",
        "14": "Negras retira el caballo para escapar. Pero ese caballo era la pieza importante que protegía el soldado central. Al huir deja un hueco en el centro. Negras tenía otras defensas, pero esta fue la peor elección.",
        "15": "¡El cañón rojo toma el soldado central y da jaque! Sin el caballo negro, el centro estaba abierto. Desde aquí el ataque rojo avanza a toda prisa.",
        "16": "Negras sube un consejero para tapar el frente del general. Es la única buena forma de parar el jaque.",
        "17": "El segundo carro rojo llega a la misma columna. Dos carros alineados en una columna son tremendamente fuertes. El plan es entrar al fondo del campo negro.",
        "18": "El general negro se aparta hacia un lado. Si no, quedaría mirado de frente por los dos carros rojos en la misma columna.",
        "19": "¡El carro rojo de delante toma al consejero negro y da jaque! El otro consejero lo capturará enseguida, pero eso es parte del plan. Rojas entrega un carro para destrozar a los guardias del general negro. ¡Qué jugada tan valiente!",
        "20": "Negras toma el carro con el consejero. En piezas, Negras va muy por delante. Pero la casa del general está aún más vacía.",
        "21": "El último carro rojo pasa a la columna del general: otra vez jaque. Al general negro casi no le quedan piezas que lo protejan.",
        "22": "Negras pone un cañón delante del general para tapar el jaque. Poner una pieza en medio así se llama interponer.",
        "23": "El carro rojo toma ese cañón: jaque otra vez. El carro sigue capturando piezas negras mientras acorrala al general.",
        "24": "El general negro solo puede volver al centro. Todos los demás puntos están controlados por piezas rojas.",
        "25": "Por fin el cañón rojo se coloca en el centro, dos cañones en una columna: jaque. El cañón de delante hace de pantalla y el de atrás golpea al general: un mate de «cañón doble». El general negro no tiene adónde ir y Rojas gana. Entregando solo un caballo, Rojas ganó en trece jugadas. Durante 400 años, esta partida ha enseñado que el tiempo y la actividad de las piezas pueden valer más que su número."
      } }
  },
  "fr": {
    ui: {"lead":"Les grandes parties, coup par coup. Suivez sur l’échiquier des parties célèbres pendant que Musowl explique chaque coup.","all":"Toutes","k_chess":"Échecs","k_shogi":"Shogi","k_go":"Go","k_xiangqi":"Xiangqi","side_r":"Rouges","res_r":"Victoire des Rouges","back":"Retour aux grandes parties","start":"Début","prev":"Reculer d’un coup","next":"Avancer d’un coup","end":"Fin","play":"Lecture","pause":"Pause","moves":"Coups","move":"Coup {n}","startpos":"Position de départ","nextnote":"Commentaire suivant (coup {n})","quiet":"Pas de commentaire pour ce coup.","guide":"Musowl","keys":"← → pour avancer coup par coup","result":"Résultat","r_event":"Partie","r_date":"Année","r_place":"Lieu","side_w":"Blancs","side_b":"Noirs","side_s":"Sente","side_g":"Gote","side_B":"Noir","side_W":"Blanc","res_w":"Victoire des Blancs","res_b":"Victoire des Noirs","res_d":"Nulle","res_s":"Victoire de Sente","res_g":"Victoire de Gote","credit":"Les coups sont le relevé public de chaque partie. Les commentaires sont de Musowl, du musée."},
    "opera": { "t": "La partie de l’Opéra", "w": "Paul Morphy", "b": "Le duc Charles II de Brunswick et le comte Isouard", "ev": "Jouée dans une loge de l’Opéra de Paris (les deux alliés jouant en consultation)", "d": "1858", "pl": "France (Paris)", "lead": "Le jeune champion américain face à deux nobles, pendant une représentation à l’Opéra : dix-sept coups. Sortir ses pièces vite, les sacrifier sans hésiter et finir avec très peu. Aucune partie n’apparaît dans plus de livres d’échecs.",
      c: {
        "0": "Paris, 1858. L’Américain Paul Morphy, vingt et un ans, battait l’un après l’autre les meilleurs joueurs d’Europe. Ce soir-là, dans une loge de l’Opéra, le duc de Brunswick et le comte Isouard prennent ensemble les Noirs et le défient, en se concertant à chaque coup. On dit que Morphy voulait finir vite pour regarder la scène. Ces dix-sept coups sont remplis des bases : sortir vite ses pièces et mettre son roi à l’abri.",
        "1": "Les Blancs avancent de deux cases le pion du roi. Il surveille d5 et e5 au centre et ouvre la route au fou et à la dame.",
        "2": "Les Noirs jouent aussi e5. Les pions se font face au centre, et le pion blanc ne peut plus avancer.",
        "3": "Le cavalier va en f3 et attaque le pion e5. Bon coup : il développe une pièce et oblige l’adversaire à penser à défendre.",
        "4": "Les Noirs protègent e5 avec d6. C’est la défense Philidor. Solide, mais elle gêne un peu le fou f8.",
        "5": "Les Blancs jouent d4 : un autre pion au centre, contre e5. Les Noirs doivent choisir entre prendre et défendre.",
        "6": "Le fou noir va en g4. Il presse le cavalier f3, aligné avec la dame blanche en d1. Si le cavalier bouge, la dame tombe : il ne peut donc pas aller chercher e5.",
        "7": "Les Blancs prennent en e5 avec le pion. Si les Noirs reprenaient tout de suite avec le pion d6, les Blancs échangeraient les dames puis le cavalier mangerait le pion e5. Les Noirs veulent donc d’abord éliminer le cavalier f3.",
        "8": "Les Noirs prennent le cavalier avec le fou. Ils peuvent maintenant reprendre e5 sans risque. Mais donner contre le cavalier le fou qui venait de sortir les met en retard de développement.",
        "9": "Les Blancs reprennent avec la dame, qui travaille déjà près du centre, alors que les Noirs n’ont presque rien sorti.",
        "10": "Les Noirs reprennent avec un pion : le matériel est égal. Mais en pièces développées, les Blancs sont devant.",
        "11": "Fou en c4. Avec la dame f3, il vise f7. Seul le roi protège f7, c’est une case faible : la prendre serait mat.",
        "12": "Les Noirs placent le cavalier en f6 et bouchent la colonne f. Sans cela, dame prend f7 serait mat. Se défendre en développant est la bonne réponse.",
        "13": "La dame pivote en b3 et attaque en même temps f7 et b7. Un coup à deux menaces est fort, car l’adversaire ne peut pas parer les deux.",
        "14": "Les Noirs jouent la dame en e7 pour protéger f7 et laissent b7. Mais la dame bouche maintenant le fou f8.",
        "15": "Morphy ne prend pas le pion b7 : il sort un cavalier. Prendre enverrait la dame très loin. Préférer le développement rapide à un pion, c’est tout Morphy.",
        "16": "Les Noirs jouent c6 : ils contrôlent d5 et b5 et ouvrent à la dame la route de b6.",
        "17": "Fou en g5 : il cloue le cavalier f6. Si le cavalier bouge, la dame e7 derrière peut être prise. Les pièces noires ont de plus en plus de mal à bouger.",
        "18": "Les Noirs jouent b5 pour chasser le fou c4. Ils gagnent aussi de l’espace à l’aile dame, mais ouvrent une brèche aux pièces blanches.",
        "19": "Le cavalier se sacrifie pour prendre en b5 ! Au lieu de reculer le fou, Morphy continue d’attaquer. Avec le roi noir encore au centre, c’est très dangereux pour les Noirs.",
        "20": "Les Noirs prennent le cavalier et ont un cavalier de plus. Mais leur roi est toujours en e8, et les pièces blanches continuent d’arriver.",
        "21": "Fou en b5, échec ! Le roi noir est toujours coincé au centre. Les Blancs ont deux pions pour le cavalier et foncent sur le roi.",
        "22": "Les Noirs interposent le cavalier en d7. Mais ce cavalier est cloué : s’il bouge, le roi noir est en échec. Les Blancs vont viser d7.",
        "23": "Les Blancs roquent du côté de la dame. Le roi est à l’abri, et en même temps la tour arrive en d1 pour viser d7. Un seul coup défend et attaque : superbe.",
        "24": "Les Noirs mettent la tour en d8 pour défendre d7. Ils ne peuvent toujours pas roquer, et la tour h8 et le fou f8 ne font rien.",
        "25": "La tour se sacrifie pour prendre en d7 ! Les Blancs donnent une tour pour éliminer un défenseur noir.",
        "26": "Les Noirs reprennent avec la tour. Cette tour d7 est maintenant clouée aussi : si elle bouge, le fou b5 fait échec au roi noir.",
        "27": "L’autre tour vient en d1 et attaque encore d7. Il y a maintenant plus de pièces blanches qui attaquent d7 que de pièces noires qui la défendent.",
        "28": "La dame noire va en e6 : elle propose l’échange des dames pour chasser la dame b3 et veut aider d7. Mais c’est trop tard.",
        "29": "Le fou prend en d7 avec échec. Les Blancs éliminent les défenseurs noirs un par un.",
        "30": "Les Noirs reprennent avec le cavalier. Le cavalier ayant quitté f6, la diagonale du fou g5 jusqu’à d8 est ouverte. Cette diagonale comptera tout à la fin.",
        "31": "La dame se sacrifie en b8, avec échec ! C’est le coup le plus célèbre de la partie. Les Noirs doivent prendre avec le cavalier, et quand le cavalier quitte d7, la colonne d s’ouvre.",
        "32": "Les Noirs prennent avec le cavalier. Plus aucune pièce noire ne protège d8.",
        "33": "Tour en d8, échec et mat ! Le fou g5 soutient d8, et le roi noir est enfermé par ses propres pièces. Les Blancs ont donné dame, tour et fou, et ont fini avec une tour et un fou seulement. Développer vite, mettre son roi à l’abri et attaquer tant que le roi adverse est au centre : cette partie célèbre réunit toutes ces idées importantes."
      } },
    "reti1910": { "t": "Le mat de Réti", "w": "Richard Réti", "b": "Savielly Tartakower", "ev": "Une partie amicale (pas un tournoi)", "d": "1910", "pl": "Autriche (Vienne)", "lead": "Deux futurs grands maîtres, une partie amicale à Vienne, onze coups. Les Blancs donnent leur dame et finissent par un échec double : deux pièces qui font échec en même temps. Ce mat porte le nom des Blancs : le mat de Réti.",
      c: {
        "0": "Vienne, 1910. Les Blancs sont à Richard Réti, vingt ans ; les Noirs à Savielly Tartakower. Tous deux deviendront parmi les meilleurs joueurs du monde, connus pour avoir apporté des idées nouvelles aux échecs. Ce n’était pas une partie de tournoi, mais une partie amicale avec une petite mise. Elle est courte, mais montre bien pourquoi il faut vite mettre son roi à l’abri.",
        "1": "Les Blancs avancent de deux cases le pion du roi. Occuper le centre aide les pièces de derrière à sortir. Le fou et la dame ont maintenant le chemin libre.",
        "2": "Les Noirs jouent c6. Au lieu d’aller tout de suite au centre, ils préparent d5 pour attaquer le pion e4. Cette ouverture solide s’appelle la défense Caro-Kann.",
        "3": "Les Blancs placent aussi l’autre pion en d4. Deux pions côte à côte au centre : les Blancs ont beaucoup d’espace. Les Noirs vont essayer de les casser.",
        "4": "Comme prévu, d5. Le pion défie e4 : « je peux te prendre ». Les Blancs doivent choisir : le protéger, l’avancer ou l’échanger.",
        "5": "Les Blancs sortent un cavalier pour défendre e4. Ils développent une pièce et défendent en même temps, sans perdre de temps.",
        "6": "Les Noirs prennent le pion e4. En échangeant les pions du centre, ils réduisent le centre blanc.",
        "7": "Les Blancs reprennent avec le cavalier, qui se retrouve au milieu de l’échiquier. Un cavalier central touche beaucoup de cases et devient très fort.",
        "8": "Les Noirs sortent un cavalier face à celui d’e4. Ici, on joue souvent le fou en f5, mais les Noirs proposent l’échange des cavaliers.",
        "9": "La dame sort tôt en d3 pour défendre le cavalier e4. D’habitude, on évite de sortir la dame trop vite, mais les Blancs ont une idée. Retiens que cette dame est sur la colonne d, devant le roi noir.",
        "10": "Les Noirs jouent e5 et offrent un pion pour ouvrir des lignes au fou et à la dame. C’est un coup actif qui lance la lutte au centre.",
        "11": "Les Blancs prennent le pion e5. Ils acceptent le cadeau, mais la dame noire gagne ainsi de la liberté.",
        "12": "Échec ! La dame noire en a5 vise en diagonale le roi en e1. En même temps, elle compte reprendre le pion e5 : deux tâches en un coup. Les Blancs doivent parer.",
        "13": "Les Blancs parent l’échec avec le fou en d2. La dame pourrait prendre le fou, mais la dame blanche le protège bien.",
        "14": "Les Noirs reprennent le pion : le matériel est de nouveau égal. Et cette dame regarde, sur la colonne e, le cavalier e4 et le roi derrière lui. Si le cavalier bouge, le roi est en échec : le cavalier est cloué. Les Noirs semblent sur le point de le gagner.",
        "15": "Les Blancs roquent du côté de la dame. Le roi quitte la colonne e, et le cavalier est libéré. En même temps, une tour arrive en d1 : la tour d1, la dame d3 et la case d8, à côté du roi noir, sont alignées. Voilà le piège blanc.",
        "16": "Les Noirs prennent le cavalier e4 et semblent gagner une pièce. Mais le roi noir est toujours en e8 et n’a pas roqué. Les pièces blanches sont alignées sur la colonne d, et le roi noir est sans protection. Ce coup, qui perd la partie, est le tournant.",
        "17": "Dame en d8, échec ! Les Blancs donnent leur pièce la plus forte pour rien. La seule pièce noire qui peut la prendre est le roi. En la laissant prendre, les Blancs attirent le roi sur la case dangereuse d8.",
        "18": "Les Noirs doivent prendre avec le roi ; il n’y a pas d’autre façon de parer l’échec. Le roi est attiré en d8, avec la tour d1 qui attend derrière.",
        "19": "Le fou va de d2 en g5 avec échec et, en même temps, libère le chemin de la tour d1, qui fait aussi échec sur la colonne d. Deux pièces qui font échec ensemble : un échec double. On ne peut le parer ni en prenant une pièce ni en s’interposant ; le roi doit fuir.",
        "20": "Le roi fuit en c7. En e8, la tour viendrait en d8 et ferait mat. Où que le roi aille, les Blancs ont le coup final tout prêt.",
        "21": "Fou en d8 : échec et mat en diagonale sur le roi en c7 ! Le fou est protégé par la tour d1, donc le roi ne peut pas le prendre. Des cases comme b8, c8, b7 et c6 sont occupées par les propres pièces noires, et la tour surveille d6 et d7. En onze coups seulement, les Blancs ont donné la dame et gagné avec deux petites pièces. Cette partie montre combien il est dangereux de prendre du matériel avant de roquer. Certains récits disent que les Noirs ont abandonné un coup plus tôt."
      } },
    "immortal": { "t": "L’Immortelle", "w": "Adolf Anderssen", "b": "Lionel Kieseritzky", "ev": "Partie libre jouée pendant une pause du tournoi de Londres 1851", "d": "1851", "pl": "Royaume-Uni (Londres)", "lead": "Londres, pendant le premier tournoi international d’échecs : une partie jouée lors d’une pause. Les Blancs donnent un fou, les deux tours et enfin la dame, puis matent avec les trois pièces mineures restantes. On dit que les Noirs ont abandonné avant la fin, et que les derniers coups seraient la conclusion montrée par les Blancs.",
      c: {
        "0": "Londres, 1851. Pendant une pause du tournoi, l’Allemand Anderssen (Blancs) et Kieseritzky, vedette de Paris (Noirs), jouent une partie amicale.",
        "1": "Les Blancs avancent de deux cases le pion du roi.",
        "2": "Les Noirs font de même.",
        "3": "f4 ! Les Blancs offrent un pion : c’est le gambit du roi. L’idée est d’écarter du centre le pion noir e5.",
        "4": "Les Noirs acceptent le pion.",
        "5": "Le fou sort et vise f7, à côté du roi noir.",
        "6": "Échec ! Sans le pion f blanc, la diagonale de h4 à e1 est ouverte.",
        "7": "Le roi s’écarte. Les Blancs ne pourront plus jamais roquer.",
        "8": "Les Noirs offrent aussi un pion, pour attirer le fou en b5.",
        "9": "Les Blancs le prennent.",
        "10": "Un cavalier sort et attaque le pion e4.",
        "11": "Les Blancs sortent un cavalier et chassent la dame de h4.",
        "12": "La dame recule en h6.",
        "13": "d3 protège e4 et ouvre la route au fou c1.",
        "14": "Cavalier en h5. Le plan : sauter en g3 avec échec et attaquer la tour h1.",
        "15": "Le cavalier blanc va en h4, prêt à sauter en f5 pour gêner la dame noire.",
        "16": "La dame noire va en g5 et attaque le cavalier h4.",
        "17": "Cavalier en f5, une belle case protégée par le pion e4. Il vise aussi le pion g7.",
        "18": "c6 essaie de chasser le fou b5.",
        "19": "Les Blancs ne sauvent pas le fou : g4 chasse plutôt le cavalier h5.",
        "20": "Le cavalier revient en f6.",
        "21": "Tour en g1, qui protège le pion g4. Les Blancs laissent partir le fou b5. Quel culot !",
        "22": "Les Noirs prennent le fou et ont une pièce de plus.",
        "23": "Le pion h se met à pourchasser la dame noire.",
        "24": "La dame va en g6.",
        "25": "h5 chasse encore la dame.",
        "26": "La dame ne peut que revenir en g5. Elle a de moins en moins de cases.",
        "27": "La dame blanche va en f3. Si le fou prend ensuite en f4, la dame noire risque d’être prise au piège.",
        "28": "Les Noirs ramènent le cavalier en g8 pour que la dame puisse fuir en f6.",
        "29": "Le fou prend le pion f4 et attaque la dame.",
        "30": "La dame s’enfuit en f6.",
        "31": "Un cavalier sort, avec l’idée de sauter en d5 pour attaquer la dame.",
        "32": "Le fou sort et vise la tour g1.",
        "33": "Cavalier en d5, qui attaque la dame f6 et la case c7. Les Blancs se moquent de perdre la tour g1.",
        "34": "La dame prend le pion b2 et attaque la tour a1.",
        "35": "Fou en d6 ! Les Blancs laissent filer les deux tours. En échange, leurs pièces tissent un filet autour du roi noir.",
        "36": "Les Noirs prennent la tour g1.",
        "37": "e5 ! Ce pion coupe la diagonale de la dame b2 vers g7. La dame noire ne peut plus revenir aider son roi.",
        "38": "Les Noirs prennent aussi l’autre tour, avec échec.",
        "39": "Le roi va en e2. Il ne reste aux Blancs que la dame, deux cavaliers et un fou.",
        "40": "Le cavalier va en a6 pour garder c7. On dit que les Noirs ont abandonné vers ici ; la suite serait la conclusion montrée par les Blancs.",
        "41": "Le cavalier prend en g7 avec échec.",
        "42": "Le roi fuit en d8.",
        "43": "La dame se sacrifie en f6, avec échec ! La dernière grosse pièce part aussi.",
        "44": "Les Noirs doivent prendre avec le cavalier.",
        "45": "Fou en e7, échec et mat ! Le cavalier d5 tient e7 et c7, celui de g7 tient e8. Les Blancs gagnent avec un fou et deux cavaliers seulement."
      } },
    "mimiaka": { "t": "La partie des oreilles rouges", "w": "Hon’inbō Shūsaku", "b": "Inoue Gennan Inseki", "ev": "Partie jouée à Osaka (sur trois jours)", "d": "1846", "pl": "Japon (Osaka)", "lead": "À 17 ans, Shūsaku (4e dan) affronte Gennan (8e dan), l’un des plus forts joueurs de l’époque. On raconte qu’au coup 127, les oreilles de Gennan sont devenues rouges. Il n’y avait pas de komi : Noir gagne de 2 points.",
      c: {
        "0": "Osaka, 1846. Shūsaku a Noir, Gennan Blanc. La veille, ils avaient commencé une partie avec deux pierres de handicap, interrompue ; cette fois Shūsaku joue Noir sans handicap.",
        "1": "Noir 1 sur le point 3-4 en haut à droite (R16) : un point bas qui tient bien le coin.",
        "2": "Blanc 2 prend le 3-4 en haut à gauche (D17). On commence par se partager les coins vides.",
        "5": "Avec 1, 3 et 5, Noir occupe trois coins, tous sur des points 3-4. C’était le début préféré de Shūsaku, très étudié ensuite.",
        "6": "Blanc 6 en C14, sur le bord gauche. Au lieu d’approcher le coin noir, il s’installe sur le bord : un choix un peu inhabituel.",
        "7": "Noir 7 (E4) ferme le coin inférieur gauche avec une deuxième pierre. Cette « fermeture » rend le coin très solide.",
        "8": "Blanc 8 (R5) approche le coin noir de Q3. Un grand combat va commencer en bas à droite.",
        "10": "Blanc 10 (O4) est le taisha : il coiffe la pierre noire en diagonale, à distance. Il mène à d’innombrables variantes, et c’était le coup préféré de Gennan.",
        "11": "Avec 11 (Q5), Noir entre dans une suite difficile. Gennan connaissait bien le taisha : il faut avancer prudemment.",
        "24": "En bas à droite, les pierres s’emmêlent et chacun essaie de couper l’autre. Après Blanc 24 (N4), les pierres noires ont du mal à sortir.",
        "25": "Noir 25 (N3). Les études ultérieures indiquent qu’il y avait mieux ici. Même pour un maître, la position était difficile.",
        "28": "Avec 28 (M3) et 30 (L2), Blanc frappe aussitôt la faiblesse noire. Les pierres noires risquent d’être enfermées dans un petit espace en bas.",
        "31": "Noir 31 (M4) est important. Il prépare le ko à venir — la lutte de prise et reprise — en créant des menaces auxquelles Blanc devra répondre.",
        "36": "Blanc 36 (N2). Avant d’ouvrir le ko, Blanc joue d’abord ici. Bon timing.",
        "40": "Blanc 40 (R1) prend une pierre et le ko commence. Celui qui a perdu la pierre ne peut pas reprendre tout de suite : il joue d’abord une menace ailleurs.",
        "41": "Noir 41 (O5) est une menace de ko. Elle coûte un peu, mais il n’y a rien de mieux ici.",
        "53": "Noir 53 (R10) est une idée ingénieuse que peu trouveraient. Il s’en prend à la forme blanche sur le bord droit.",
        "60": "Blanc 60 (S3) est un grand coup. Il permet aussi de jouer 62 (M1) en gardant l’initiative.",
        "63": "Avec Noir 63 (O1), le long combat en bas à droite se calme. Blanc a du territoire en bas, Noir un mur épais à droite. Pour l’instant, Blanc semble mieux.",
        "67": "Noir 67 (L17). Adossé à son mur de droite, Noir prépare un grand moyo en haut.",
        "72": "Blanc 72 (P13) est superbe. Posé juste au-dessus du mur noir, il empêche le moyo noir de grandir.",
        "74": "D’ici au coup 100 environ, Gennan ne relâche jamais. Il esquive les attaques noires et garde ses pierres reliées.",
        "83": "Noir 83 (H3) entre dans la zone blanche du bas pour la réduire.",
        "96": "À partir de Blanc 96 (R14), un combat serré se joue autour du coin noir en haut à droite. Blanc trouve encore une bonne forme.",
        "107": "Noir 107 (P10) prend une pierre blanche. Le groupe noir de droite est maintenant en sécurité.",
        "118": "Blanc 118 (M19) prend une pierre, et son groupe du haut vit aussi. Le moyo noir du haut reste plus petit que prévu.",
        "126": "Blanc 126 (J5). Blanc est épais en bas et pousse vers le centre. On dit que la plupart des professionnels présents pensaient que Blanc menait.",
        "127": "Voici le célèbre coup des oreilles rouges, Noir 127 (K11). Cette pierre centrale agirait dans quatre directions à la fois : elle agrandit la zone noire du haut, affaiblit l’épaisseur blanche du bas, aide le groupe noir de droite et empêche Blanc de s’étendre à gauche.",
        "128": "À cet instant, un médecin qui regardait remarqua que les oreilles de Gennan étaient devenues rouges. Il connaissait peu le go, mais il y aurait vu un signe de trouble et prédit la victoire de Noir.",
        "131": "Noir 131 (D10). Noir s’attaque aussi au bord gauche blanc et réduit le territoire blanc partout.",
        "147": "Noir 147 (K10). La pierre du coup 127 commence à servir : Noir avance entre les groupes blancs au centre.",
        "160": "Blanc 160 (H8). Il protège ses pierres du centre tout en visant le groupe noir en bas à gauche. La partie reste serrée.",
        "167": "Noir 167 (C2) est précis. Les pierres noires du coin inférieur gauche sont sauves, et la menace blanche disparaît.",
        "175": "Noir 175 (G4) prend une pierre blanche. Le territoire blanc du bas n’est pas aussi grand qu’il le semblait.",
        "199": "Noir 199 (K7). Le combat du centre se calme, et l’on passe au yose : on fixe les frontières, et chaque point compte.",
        "212": "Avec 212 (D19) et 216 (F19), Blanc prend des pierres noires sur le bord du haut. Dans le yose, personne ne cède un pouce.",
        "228": "Blanc 228 (N12) crée un ko au centre. Pendant plus de 80 coups, on prend et reprend en M13 et N13.",
        "236": "Blanc 236 (T8), joué pendant le ko, prend une pierre. Certains analystes pensent que finir le ko ici aurait rendu la partie encore plus serrée.",
        "275": "Noir 275 (T14) prend deux pierres blanches. Pendant le ko, chacun gagne ici et perd là, partout sur le plateau.",
        "299": "Noir 299 (J16) prend quatre pierres blanches d’un coup. Noir tient solidement le haut.",
        "311": "Noir 311 (M13) comble le ko. La longue lutte de ko est enfin terminée.",
        "325": "La partie s’achève au coup 325, et le décompte donne Noir gagnant de 2 points. Même sans komi, la victoire d’un garçon de 17 ans sur un joueur comme Gennan fit sensation, et le nom de Shūsaku devint célèbre."
      } },
    "evergreen": { "t": "L’Éternelle", "w": "Adolf Anderssen", "b": "Jean Dufresne", "ev": "Une partie amicale (pas un tournoi)", "d": "1852", "pl": "Allemagne (probablement Berlin)", "lead": "Anderssen, l’auteur de l’Immortelle, joua cet autre chef-d’œuvre un an plus tard. Au moment où les Noirs menacent de mater, les Blancs déplacent calmement une tour, puis donnent la dame et concluent par un échec double. On l’appelle « toujours verte » (Evergreen) parce qu’elle ne se fane jamais.",
      c: {
        "0": "Une partie publiée dans une revue en 1852. Les Blancs sont à Anderssen, les Noirs à son ami Dufresne. On pense qu’elle fut jouée à Berlin, mais aucun document ne le confirme.",
        "1": "Les Blancs avancent de deux cases le pion du roi.",
        "2": "Les Noirs font de même.",
        "3": "Le cavalier attaque le pion e5.",
        "4": "Les Noirs protègent e5 avec un cavalier.",
        "5": "Le fou sort et vise f7.",
        "6": "Les Noirs sortent aussi un fou.",
        "7": "b4 ! Un pion offert : le gambit Evans. Pendant que les Noirs le prennent, les Blancs renforcent le centre.",
        "8": "Les Noirs prennent le pion.",
        "9": "c3 chasse le fou et prépare d4.",
        "10": "Le fou recule en a5.",
        "11": "d4 occupe le centre.",
        "12": "Les Noirs prennent le pion.",
        "13": "Les Blancs ne reprennent pas : ils roquent. La sécurité du roi et l’activité des pièces passent avant les pions.",
        "14": "Le pion noir file jusqu’en d3, au cœur du camp blanc.",
        "15": "Dame en b3. Avec le fou c4, elle vise f7.",
        "16": "Les Noirs protègent f7 avec la dame.",
        "17": "e5 chasse la dame.",
        "18": "La dame va en g6.",
        "19": "Tour en e1, sur la colonne e, pour soutenir le pion e5.",
        "20": "Les Noirs sortent un cavalier pour préparer le roque.",
        "21": "Fou en a3, qui vise en diagonale le cavalier e7. Si ce cavalier bouge, le fou atteindra f8 : les Noirs auront du mal à roquer du côté du roi.",
        "22": "Les Noirs offrent un pion pour détourner les pièces blanches.",
        "23": "La dame le prend.",
        "24": "Tour en b8, qui chasse la dame sur la colonne b.",
        "25": "La dame va en a4.",
        "26": "Le fou recule en b6.",
        "27": "Un cavalier sort. Presque toutes les pièces blanches sont en jeu.",
        "28": "Les Noirs développent l’autre fou.",
        "29": "Cavalier en e4, qui regarde vers f6.",
        "30": "La dame noire va en f5 et attaque le cavalier e4.",
        "31": "Le fou prend le pion d3 et protège le cavalier e4.",
        "32": "Dame en h5, qui vise le cavalier f3.",
        "33": "Le cavalier se sacrifie en f6, avec échec !",
        "34": "Les Noirs prennent avec un pion.",
        "35": "Les Blancs reprennent avec un pion et attaquent le cavalier e7. Sur la colonne e, la tour e1 vise aussi e7.",
        "36": "Tour en g8, qui vise g2. Si la dame h5 prend en f3, le mat est tout proche.",
        "37": "Un calme coup de tour en d1 ! Le roi blanc est en danger, mais au lieu de défendre, les Blancs visent d7. C’est ce coup qui a rendu la partie « éternelle ».",
        "38": "Les Noirs prennent le cavalier f3. Prendre ensuite en g2 serait mat.",
        "39": "Mais les Blancs jouent d’abord. La tour prend le cavalier e7, avec échec !",
        "40": "Les Noirs reprennent avec le cavalier c6. La diagonale de a4 à d7 s’ouvre.",
        "41": "La dame se sacrifie en d7, avec échec !",
        "42": "Les Noirs doivent prendre avec le roi.",
        "43": "Le fou va en f5 avec échec et libère la colonne d pour la tour d1 : échec double.",
        "44": "Le roi va en e8. En c6, le fou materait en d7.",
        "45": "Fou en d7, échec.",
        "46": "Le roi va en f8.",
        "47": "Le fou a3 prend le cavalier e7 : échec et mat ! Le fou d7 tient e8, et le pion f6 tient e7 et g7."
      } },
    "lasker1912": { "t": "La chasse au roi", "w": "Edward Lasker", "b": "George Alan Thomas", "ev": "Partie rapide et amicale au City of London Chess Club", "d": "1912", "pl": "Royaume-Uni (Londres)", "lead": "Une partie rapide et amicale dans un club de Londres. Les Blancs donnent la dame et chassent le roi noir à travers tout l’échiquier, de g8 à g1. Les premiers coups sont notés dans un ordre un peu différent selon les sources, mais la position après le 10e coup est la même.",
      c: {
        "0": "Octobre 1912, City of London Chess Club. Les Blancs sont à Edward Lasker, un jeune ingénieur tout juste arrivé d’Allemagne ; les Noirs à George Alan Thomas, futur champion de Grande-Bretagne. C’était une partie rapide et amicale. Elle est célèbre comme « chasse au roi » : le roi noir est poursuivi de g8 jusqu’à g1, à l’autre bout de l’échiquier. Lasker partit ensuite en Amérique et devint connu pour ses livres d’échecs.",
        "1": "Les Blancs commencent par d4, le pion de la dame. Il contrôle e5 et c5 et ouvre la route au fou c1.",
        "2": "Les Noirs jouent e6 : d’abord une position solide, en préparant f5 ou d5.",
        "3": "Cavalier en f3. Il contrôle e5 et aide à défendre l’aile roi : la case la plus naturelle.",
        "4": "Les Noirs jouent f5 et contrôlent e4, comme dans la défense hollandaise. Mais bouger un pion devant le roi l’affaiblit un peu.",
        "5": "L’autre cavalier va en c3, en préparant e4 pour attaquer le pion f5.",
        "6": "Les Noirs sortent un cavalier en f6 : ils contrôlent encore plus e4 et préparent le roque.",
        "7": "Fou en g5, qui vise le cavalier f6. Ce cavalier est un défenseur important du roi noir ; les Blancs veulent donc l’éliminer tôt.",
        "8": "Les Noirs placent le fou en e7 pour protéger le cavalier et se rapprochent du roque.",
        "9": "Les Blancs échangent le fou contre le cavalier. Le cavalier qui protégeait le roi noir disparaît.",
        "10": "Les Noirs reprennent avec le fou. Ce fou f6 prend maintenant le relais pour garder l’aile roi.",
        "11": "e4 ! Les Blancs attaquent le pion f5 et gagnent de l’espace au centre. Des lignes s’ouvrent et les pièces blanches bougent mieux.",
        "12": "Les Noirs prennent le pion e4. Sinon, les Blancs joueraient e5 et repousseraient les pièces noires.",
        "13": "Le cavalier reprend et s’installe au centre, en regardant le fou f6 et les cases g5 et d6.",
        "14": "Les Noirs jouent b6 pour amener le fou en b7 et viser sur la grande diagonale le cavalier e4.",
        "15": "Cavalier en e5, une forte case centrale qui regarde aussi g4 et f7. Les deux cavaliers blancs sont maintenant près de l’aile roi noire.",
        "16": "Les Noirs roquent. Le roi est en g8. Mais sans le pion f, il y a beaucoup de trous autour du roi.",
        "17": "Fou en d3. Pour l’instant son propre cavalier e4 le gêne, mais derrière se trouve le pion h7. Dès que le cavalier e4 bougera, ce fou visera droit sur h7.",
        "18": "Le fou noir va en b7 et vise sur la grande diagonale le cavalier e4, ce qui gêne les pièces blanches.",
        "19": "Dame en h5, qui vise le pion h7, défendu seulement par le roi noir. Dame, fou et cavaliers blancs pointent tous vers le roi noir.",
        "20": "Les Noirs placent la dame en e7. Elle protège le fou f6 et prépare d’aller en c5, mais les Noirs ne voient pas l’idée blanche. Il fallait jouer h6 ou prendre le cavalier e5. C’est le tournant.",
        "21": "La dame se sacrifie en h7, avec échec ! Les Blancs donnent leur pièce la plus forte pour rien. Lasker voyait tout le chemin pour chasser le roi jusqu’au mat.",
        "22": "Les Noirs doivent prendre avec le roi, qui se retrouve en h7.",
        "23": "Le cavalier prend le fou f6 avec échec. En même temps, e4 se libère et le fou d3 fait aussi échec au roi h7 : échec double. On ne peut pas l’intercepter, le roi doit fuir.",
        "24": "Le roi va en h6. En h8, l’autre cavalier sauterait en g6 avec mat. Le roi est poussé toujours plus en avant.",
        "25": "L’autre cavalier saute de e5 en g4 avec échec, attaque le roi h6 et le pousse encore plus loin.",
        "26": "Le roi va en g5 : il quitte son camp et marche vers le côté blanc.",
        "27": "Échec avec le pion h ! Même les pions participent à la chasse. Le roi doit continuer d’avancer.",
        "28": "Le roi va en f4. Il a dépassé le milieu de l’échiquier et entre dans le camp blanc.",
        "29": "Encore échec, avec le pion g. Deux pions bloquent le chemin du retour du roi.",
        "30": "Le roi va en f3, au milieu des pièces blanches.",
        "31": "Le fou recule de d3 en e2 avec échec. Le roi est poussé encore plus loin.",
        "32": "Le roi va en g2. Le roi blanc en e1 n’est plus très loin.",
        "33": "Tour en h2, échec. La tour entre enfin en jeu.",
        "34": "Le roi arrive enfin en g1. Parti de g8, il a atteint la première rangée à l’autre bout de l’échiquier.",
        "35": "Le roi blanc passe de e1 en d2. Cela libère la tour a1, qui fait échec au roi g1 sur la première rangée : échec et mat ! Le grand roque matait aussi, mais Lasker a joué le roi. Dans une partie rapide, après avoir donné la dame, les Blancs ont chassé le roi pendant quatorze coups jusqu’au fond de leur propre camp. Une partie très rare."
      } },
    "toketsu": { "t": "La partie du sang craché", "w": "Akaboshi Intetsu", "b": "Hon’inbō Jōwa", "ev": "Jouée chez le seigneur Matsudaira de Suō (sur quatre jours)", "d": "1835", "pl": "Japon (Edo)", "lead": "Une partie née de la lutte pour le poste de Meijin Godokoro, le plus haut du go japonais. Inoue Gennan Inseki envoya son élève Akaboshi Intetsu affronter le Meijin Jōwa. Après quatre jours de combat, Intetsu perdit et aurait craché du sang devant le goban.",
      c: {
        "0": "1835. Noir : Akaboshi Intetsu (7e dan) ; Blanc : le Meijin Hon’inbō Jōwa. Gennan envoya son meilleur élève pour pouvoir dire qu’un Meijin battu par un 7e dan ne mérite pas son titre.",
        "1": "Noir 1 sur le 3-4 en bas à gauche (C4). Intetsu commence calmement.",
        "4": "Après quatre coups, chaque coin a sa pierre : Blanc en bas à droite et en haut à gauche, Noir en bas à gauche et en haut à droite.",
        "6": "Blanc 6 (E3) approche déjà le coin noir en bas à gauche. Jōwa est actif dès le départ.",
        "10": "Blanc 10 (P4) ferme le coin inférieur droit avec une deuxième pierre.",
        "12": "Blanc 12 (D6) appuie d’en haut sur le coin noir en bas à gauche. Le plus grand combat de la partie commence ici.",
        "13": "Noir 13 (E4) s’accole à une pierre blanche. Noir accepte le combat.",
        "20": "Blanc 20 (C3) se glisse sous le coin noir : il ronge le territoire du coin tout en cherchant à faire vivre ses pierres.",
        "28": "Blanc 28 (C9) s’étend loin sur le bord gauche. On le juge souvent excessif : un coup féroce, bien dans le style de Jōwa.",
        "33": "Noir 33 (C2). Ce serait une suite nouvelle, étudiée en secret par la maison Inoue. Elle attaque les pierres blanches flottantes du centre tout en avalant celles du bord gauche.",
        "36": "Blanc 36 (F3). Il tente d’enfermer Noir de l’extérieur en bas à gauche tout en reliant ses pierres.",
        "43": "Noir 43 (E9). Les pierres blanches de gauche souffrent. Jusqu’ici Intetsu a bien joué et passe pour avoir pris l’avantage.",
        "45": "Noir 45 (D11) s’étend vers le haut sur le bord gauche, garde les pierres blanches séparées et se renforce.",
        "50": "Blanc 50 (C16). Il quitte pour l’instant le bas à gauche et se tourne vers le coin supérieur gauche.",
        "53": "Noir 53 (G17). Noir entre sur le bord du haut pour empêcher Blanc d’agrandir le coin supérieur gauche.",
        "58": "Blanc 58 (C14) s’étend du coin supérieur gauche le long du bord et s’approche des pierres noires de gauche.",
        "60": "Blanc 60 (G4) prend deux pierres noires. Le groupe blanc en bas à gauche respire enfin un peu.",
        "62": "Blanc 62 (J17). Les deux camps se font face en haut aussi. Il y a des pierres faibles partout : une position difficile.",
        "66": "Blanc 66 (B14). Près du coin supérieur gauche, Blanc stabilise ses pierres.",
        "68": "Blanc 68 (B11). Les coups blancs qui suivent, avec le coup 80, sont devenus célèbres comme les coups géniaux de Jōwa. Ils étaient si remarquables qu’on disait que des fantômes les lui avaient soufflés.",
        "70": "Blanc 70 (E12). Au lieu de répondre directement à Noir à gauche, il joue d’abord un autre point clé. Des ressources cachées le lui permettent.",
        "72": "Blanc 72 (R13). Il se tourne vers le bord droit pour empêcher la zone noire en haut à droite de grandir.",
        "76": "Blanc 76 (O14). Il relie le bord droit au centre et se prépare à couper les pierres noires.",
        "80": "Blanc 80 (Q10) forme un « triangle vide », une forme d’ordinaire jugée mauvaise. Pourtant, ce coup sert de base pour couper Noir en deux et l’attaquer. C’est l’exemple classique du coup laid mais excellent.",
        "83": "Noir 83 (R3) entre dans le coin blanc en bas à droite. Un combat acharné de prises s’y engage.",
        "91": "Noir 91 (Q4) prend une pierre blanche. Le coin inférieur droit compte beaucoup pour Noir.",
        "98": "Blanc 98 (M4). Il enveloppe les pierres noires du bas et ne les laisse pas vivre facilement.",
        "106": "Blanc 106 (S5) prend une pierre noire. Blanc garde le coin inférieur droit, et les pierres noires doivent fuir vers l’extérieur.",
        "113": "Noir 113 (K6). Les pierres noires du bas cherchent la vie en sortant vers le centre.",
        "120": "Blanc 120 (N9) barre la route aux pierres noires en fuite. Au centre, c’est à qui faiblira le premier.",
        "128": "Blanc 128 (L11) presse aussi d’en haut les pierres noires du centre. Noir ne peut toujours pas souffler.",
        "138": "Blanc 138 (K8) prend une pierre et un ko commence au centre. Pendant une trentaine de coups, on prend et reprend en K8 et L8.",
        "152": "Blanc 152 (E11) est une menace de ko. Pendant le ko, Blanc trouve partout des coups auxquels Noir doit répondre.",
        "170": "Blanc 170 (P15). Le ko du centre s’est calmé ; Blanc passe en haut à droite et vise un grand groupe noir pas encore tout à fait vivant.",
        "178": "Blanc 178 (J14) saute au milieu de la zone du haut pour séparer les pierres noires à gauche et à droite. L’attaque de coupure préparée depuis le coup 80 commence pour de bon.",
        "193": "Noir 193 (J11) prend une pierre blanche. Noir se bat pour se relier et vivre.",
        "201": "Noir 201 (R14) prend une pierre et un nouveau ko commence sur le bord droit, avec des prises en R14 et R15.",
        "206": "Blanc 206 (M13). Même pendant le ko, Blanc resserre peu à peu l’étau sur les pierres noires du centre.",
        "222": "Blanc 222 (L14) prend une pierre. Les pierres noires du haut restent coupées en deux, et sauver les deux devient difficile.",
        "230": "Blanc 230 (C13) frappe aussi le point faible noir sur le bord gauche. Les pierres blanches sont désormais bien reliées sur tout le plateau.",
        "237": "Avec 237 (F12) et 239 (E13), Noir reprend des pierres en haut à gauche. Malgré tout, l’écart global ne diminue pas.",
        "246": "Après Blanc 246 (L8), Intetsu abandonna. On raconte qu’en rangeant les pierres il cracha du sang sur le goban. Il était sans doute malade depuis un moment, et il mourut peu après. Pour Jōwa, c’est la plus grande victoire de sa carrière."
      } },
    "deepblue1997": { "t": "La victoire de Deep Blue", "w": "Deep Blue (ordinateur d’IBM)", "b": "Garry Kasparov", "ev": "6e partie de la revanche contre Deep Blue d’IBM (match en six parties)", "d": "1997", "pl": "États-Unis (New York)", "lead": "Le champion du monde Kasparov face à Deep Blue, un ordinateur d’échecs construit par IBM, dans un match en six parties. À égalité après cinq parties, la dernière s’est terminée en 19 coups seulement. Pour la première fois, un ordinateur battait le champion du monde dans un vrai match de plusieurs parties.",
      c: {
        "0": "New York, 11 mai 1997. Kasparov avait gagné leur match l’année précédente. Cette fois, le score est de 2½–2½ après cinq parties. Deep Blue a les Blancs.",
        "1": "Les Blancs avancent de deux cases le pion du roi.",
        "2": "Kasparov joue c6 : la défense Caro-Kann.",
        "3": "Les Blancs placent l’autre pion au centre.",
        "4": "Les Noirs jouent d5 contre e4.",
        "5": "Le cavalier défend e4.",
        "6": "Les Noirs prennent le pion e4.",
        "7": "Le cavalier reprend.",
        "8": "Les Noirs placent un cavalier en d7 pour sortir ensuite l’autre en f6.",
        "9": "Le cavalier saute en g5 : un plan tranchant qui vise f7 et e6.",
        "10": "Les Noirs sortent le cavalier en f6.",
        "11": "Fou en d3, qui regarde l’aile roi noire.",
        "12": "Les Noirs renforcent la défense avec e6.",
        "13": "L’autre cavalier sort en f3.",
        "14": "Les Noirs jouent h6 pour chasser le cavalier g5. Mais dans cette position, un sacrifice de cavalier pour les Blancs était déjà connu. On dit que c’était un choix étonnant pour Kasparov.",
        "15": "Le cavalier se sacrifie en e6 ! Deep Blue aurait joué ce coup tiré des ouvertures qu’il avait en mémoire.",
        "16": "Les Noirs ne prennent pas tout de suite : la dame va en e7. Sur la colonne e, elle vise le cavalier e6 et le roi blanc derrière.",
        "17": "Les Blancs roquent et mettent leur roi à l’abri.",
        "18": "Les Noirs prennent le cavalier et ont plus de matériel.",
        "19": "Fou en g6, échec. Sans le pion f7, la diagonale va jusqu’au roi.",
        "20": "Le roi va en d8. Les Noirs ne peuvent plus roquer et le roi reste près du centre.",
        "21": "L’autre fou sort et vise les cases autour du roi noir.",
        "22": "Les Noirs jouent b5 pour faire de la place à l’aile dame pour le roi et le fou.",
        "23": "a4 attaque le pion b5.",
        "24": "Les Noirs placent le fou en b7.",
        "25": "Tour en e1. Sur la colonne e, elle vise le pion e6, et derrière lui la dame e7.",
        "26": "Le cavalier noir va en d5 et attaque le fou f4.",
        "27": "Le fou recule en g3.",
        "28": "Le roi noir va en c8, un peu plus à l’abri.",
        "29": "Les Blancs prennent le pion b5.",
        "30": "Les Noirs reprennent.",
        "31": "Dame en d3, qui regarde le pion b5 et la case f5.",
        "32": "Les Noirs protègent b5 avec le fou.",
        "33": "Fou en f5 ! On peut le prendre gratuitement.",
        "34": "Les Noirs prennent avec un pion. Mais le pion de la colonne e a disparu.",
        "35": "La tour prend la dame e7. Les Blancs ont donné un cavalier, un fou et une tour, mais ont gagné la dame.",
        "36": "Les Noirs reprennent la tour avec le fou.",
        "37": "c4 ! Le pion attaque à la fois b5 et d5, et la défense noire commence à s’effondrer. Kasparov abandonne ici, sans doute parce que son roi était trop exposé pour arrêter l’attaque. Un ordinateur venait de gagner un match contre le champion du monde."
      } },
    "seigen1933": { "t": "La partie 3-3, hoshi et tengen", "w": "Go Seigen", "b": "Hon’inbō Shūsai", "ev": "Partie commémorative avec le Meijin (plus de trois mois)", "d": "1933–1934", "pl": "Japon (Tokyo)", "lead": "À 19 ans, Go Seigen (5e dan) affronte le Meijin Hon’inbō Shūsai. Avec Noir, il ouvre sur le 3-3, puis un hoshi, puis le centre même (tengen) : contraire à tous les usages, ce début stupéfia le monde du go. Avec de nombreuses suspensions, la partie dura plus de trois mois ; Blanc gagna de 2 points.",
      c: {
        "0": "1933. Cette année-là, Go Seigen et son ami Kitani Minoru répandaient un nouveau style d’ouverture, le « Shinfuseki ». Tout le monde voulait voir comment il l’emploierait contre le Meijin.",
        "1": "Noir 1 sur le 3-3 en haut à droite (R17). Il prend le coin en un coup, mais rayonne peu vers l’extérieur ; à l’époque, personne n’en faisait un premier coup.",
        "3": "Noir 3 sur le hoshi en bas à gauche (D4). À l’inverse du 3-3, il privilégie l’ouverture vers l’extérieur.",
        "5": "Noir 5 va au centre même du goban : le tengen (K10). Ni coin ni bord, mais le milieu. Face au Meijin, Go Seigen affiche ses idées nouvelles sans détour.",
        "6": "3-3, hoshi, tengen : chaque pierre noire a son rôle — territoire de coin, rayonnement extérieur, force centrale. Avec 6 (Q16), Blanc joue juste à côté du 3-3 noir.",
        "9": "Noir 9 (P18). Il stabilise le coin supérieur droit de façon compacte et sûre : un style axé sur le territoire, typique du 3-3.",
        "11": "Noir 11 (K4) va au milieu du bord inférieur, juste sous le tengen. Avec cette pierre, il vise une grande zone en bas.",
        "12": "Blanc 12 (M3) entre aussitôt sur le bord inférieur pour empêcher un grand moyo noir. Le Meijin garde son calme et défait les plans noirs un à un.",
        "13": "Noir 13 (D10), cette fois au milieu du bord gauche. Les pierres noires sont hautes et forment ensemble un vaste moyo.",
        "14": "Blanc 14 (E16) ferme le coin supérieur gauche avec une deuxième pierre. Le Meijin ne se laisse pas troubler par le style nouveau et garde calmement le coin.",
        "21": "Noir 21 (G10) relie le tengen à la pierre du bord gauche, et l’influence noire s’étend au centre.",
        "28": "Blanc 28 (D3) se glisse sous le hoshi noir en bas à gauche et prend le coin. Noir le cède en échange de force à l’extérieur.",
        "30": "Blanc 30 (Q12) s’étend sur le bord droit et pose aussi un couvercle sur le coin 3-3 noir, réduisant sa portée.",
        "37": "Noir 37 (P15) prend une pierre blanche. En haut à droite, les deux camps se heurtent de près.",
        "40": "Blanc 40 (O10) sort du bord droit vers le centre et s’approche de l’influence noire autour du tengen.",
        "44": "Blanc 44 (H17) prend un point sur le bord du haut pour freiner l’expansion noire vers le haut.",
        "45": "Noir 45 (R7) s’attaque à la position blanche en bas à droite. Un long combat suit, du bord droit vers ce coin.",
        "59": "Noir 59 (R4) entre aussi dans le coin inférieur droit et réduit le territoire blanc.",
        "70": "Blanc 70 (N6) pousse du bas vers le centre pour séparer les pierres noires du bas à droite de celles du centre.",
        "79": "Noir 79 (L9) consolide le centre autour du tengen. Jusqu’ici la partie semble assez équilibrée.",
        "80": "Blanc 80 (C6) remonte du coin inférieur gauche le long du bord gauche et vise les pierres noires qui s’y trouvent.",
        "98": "Blanc 98 (A11) prend deux pierres noires. Blanc vit proprement au bord gauche, et le côté gauche noir est plus petit que prévu.",
        "101": "Noir 101 (S14) revient en haut à droite pour réduire la position blanche sur le bord droit.",
        "105": "Noir 105 (K17) prend le milieu du bord du haut et commence à attaquer les pierres blanches qui s’y trouvent.",
        "117": "Noir 117 (F17) entre aussi près du coin blanc en haut à gauche, et tout le bord du haut devient un champ de bataille.",
        "124": "Blanc 124 (K15) fait fuir ses pierres du haut vers le centre en coupant entre les pierres noires.",
        "135": "Noir 135 (E9) prend deux pierres blanches. Noir regagne un peu sur le bord gauche.",
        "138": "Blanc 138 (N18) consolide du territoire sur le bord du haut. Sur l’ensemble du plateau, la position est très serrée.",
        "153": "Noir 153 (K14). Les pierres noires du centre forment une route épaisse reliant le haut et le bas. Toute la question est de savoir comment Blanc va entamer cette épaisseur.",
        "159": "Noir 159 (F4) défend solidement le bas à gauche. Le coup blanc suivant est le plus célèbre de la partie.",
        "160": "Blanc 160 (H8) saute dans une brèche de l’épaisseur noire : un coup acéré aux multiples objectifs, à partir duquel Blanc entame le centre noir. La rumeur a couru qu’un élève, et non Shūsai, l’aurait trouvé, mais rien n’a jamais été prouvé.",
        "161": "Noir 161 (J8) répond aussitôt, mais Blanc a plus d’un objectif.",
        "162": "Blanc 162 (K12) passe au-dessus du centre et menace les liaisons noires.",
        "172": "Blanc 172 (F13) relie des pierres du centre au haut à gauche. Peu à peu, l’épaisseur centrale noire ne se transforme plus en territoire.",
        "178": "Blanc 178 (N9) entre aussi dans la zone noire à droite du centre.",
        "187": "Avec 187 (M6) et 189 (L7), Noir répond en prenant des pierres blanches. Malgré tout, Blanc a déjà joué les points importants.",
        "198": "Blanc 198 (E12) prend une pierre. Les pierres blanches du haut à gauche sont reliées aussi, et Blanc mène légèrement.",
        "203": "Noir 203 (B3). On entre dans le yose : les frontières le long des bords se fixent point par point.",
        "224": "Blanc 224 (T10) prend une pierre. Même au bord droit, Blanc ne cède pas un point.",
        "233": "Noir 233 (L13) prend deux pierres blanches. Noir poursuit jusqu’au bout.",
        "252": "La partie s’achève au coup 252 : Blanc gagne de 2 points. Sans komi, Noir avait le petit avantage de jouer en premier, mais le Meijin ne flancha jamais. Pourtant, le 3-3, le hoshi et le tengen de Go Seigen firent sensation et ouvrirent une nouvelle ère des ouvertures."
      } },
    "century1956": { "t": "La partie du siècle", "w": "Donald Byrne", "b": "Bobby Fischer", "ev": "Troisième tournoi du trophée Rosenwald (Mémorial Rosenwald)", "d": "1956", "pl": "États-Unis (New York)", "lead": "Bobby Fischer, treize ans, bat Donald Byrne, l’un des plus forts maîtres américains. Au 17e coup, Fischer laisse prendre sa dame pour rien, puis récupère pièce après pièce, et à la fin ses petites pièces traquent le roi blanc. Fischer devint plus tard champion du monde.",
      c: {
        "0": "New York, 17 octobre 1956, une partie de tournoi. Les Noirs sont à Fischer, treize ans ; les Blancs à Byrne, l’un des meilleurs joueurs américains.",
        "1": "Les Blancs commencent par un cavalier.",
        "4": "Fischer joue g6 pour placer son fou sur la grande diagonale.",
        "8": "Les Noirs roquent : d’abord mettre le roi à l’abri.",
        "10": "Les Noirs jouent d5. La lutte pour le centre commence.",
        "15": "Avec e4, les Blancs ont deux pions côte à côte au centre.",
        "17": "Tour en d1, qui soutient le pion d4. Les Blancs n’ont toujours pas roqué.",
        "18": "Le cavalier va en b6 et chasse la dame c4.",
        "20": "Fou en g4, qui met la pression sur le cavalier f3.",
        "21": "Le fou blanc va en g5. Le roi blanc est toujours au centre.",
        "22": "Cavalier en a4 ! Il saute sur une case où il peut être pris. L’idée : si le cavalier c3 s’en va, le pion e4 perd son défenseur.",
        "23": "Les Blancs ne prennent pas le cavalier et mettent la dame en a3.",
        "26": "Le cavalier noir prend le pion e4. Le centre blanc s’écroule.",
        "27": "Le fou blanc prend le pion e7 et attaque à la fois la dame noire et la tour f8.",
        "28": "Dame en b6 ! Les Noirs laissent la tour f8. Fischer compte sur le fait que le roi blanc est encore au centre.",
        "29": "Les Blancs ne prennent pas la tour et développent le fou.",
        "30": "Le cavalier prend le pion c3 et attaque la tour d1.",
        "31": "Fou en c5, qui attaque la dame noire en b6.",
        "32": "Échec de la tour sur la colonne e !",
        "33": "Le roi va en f1. Les Blancs ne pourront plus jamais roquer.",
        "34": "Fou en e6 ! Le coup le plus célèbre de la partie : les Noirs laissent prendre leur dame pour rien. En échange, ils ont un plan pour récupérer pièce après pièce.",
        "35": "Les Blancs prennent la dame noire.",
        "36": "Fou en c4, échec. La contre-attaque noire commence.",
        "38": "Le cavalier fait échec en e2.",
        "40": "Quand le roi revient en f1, le cavalier bouge et démasque un échec du fou c4. Au passage, le cavalier mange le pion d4.",
        "44": "Le cavalier revient en c3, nouvel échec à la découverte, et attaque maintenant la tour d1. Donner échec encore et encore en ramassant des pièces, c’est le « moulin ».",
        "46": "Les Noirs reprennent le fou. Le cavalier c3 attaque toujours la tour d1.",
        "50": "Le cavalier prend la tour d1. Les Noirs ont maintenant récupéré plus que la dame et sont nettement devant.",
        "52": "La tour prend aussi le pion a2.",
        "56": "Les Noirs échangent les tours. Moins il reste de pièces, mieux c’est pour celui qui en a le plus.",
        "57": "La dame blanche fait échec.",
        "58": "Les Noirs interposent le fou.",
        "64": "b5. Le pion noir se met en marche.",
        "68": "Le roi va en g7 et libère le fou f8.",
        "70": "Les pièces noires traquent maintenant le roi blanc. Échec avec un fou.",
        "72": "Le cavalier fait échec en g3.",
        "74": "Échec avec l’autre fou.",
        "76": "Fou en b3, échec.",
        "78": "Le cavalier fait échec en e2.",
        "80": "Le cavalier fait échec en c3. Le roi est pourchassé.",
        "82": "Tour en c2 : échec et mat ! Tour, deux fous et cavalier travaillent ensemble. Un garçon de treize ans a montré comment beaucoup de pièces peuvent jouer en équipe."
      } },
    "oshiro1849": { "t": "La première partie du château de Shūsaku", "w": "Hon’inbō Shūsaku", "b": "Yasui Sanchi IX", "ev": "Partie du château (la partie annuelle au château d’Edo)", "d": "1849", "pl": "Japon (Edo)", "lead": "Les parties du château étaient le grand rendez-vous annuel où les joueurs des maisons officielles de go jouaient au château du shōgun. À 20 ans, Shūsaku y fit ses débuts et gagna avec Noir de 11 points : le début d’un sans-faute de 19 victoires en 19 parties.",
      c: {
        "0": "1849. L’année précédente, Shūsaku avait été désigné héritier de la maison Hon’inbō ; il joue ici sa première partie du château. On dit que ces parties étaient souvent jouées à l’avance ailleurs, puis seulement rejouées au château.",
        "1": "Noir 1 sur le 3-4 en haut à droite (R16). Comme d’habitude, Shūsaku commence par un 3-4 tranquille.",
        "4": "Blanc 4 (C15) approche la pierre noire de D17 en haut à gauche. Un combat y commence tôt.",
        "5": "Noir 5 (C11) pince par en dessous la pierre blanche qui approche, pour que Blanc ne s’installe pas facilement à gauche.",
        "12": "Blanc 12 (C17). Blanc prend le coin supérieur gauche, Noir obtient des pierres tournées vers l’extérieur : un partage équitable.",
        "13": "Noir 13 (J17) tire parti des pierres extérieures et s’étend sur le haut.",
        "15": "Noir 15 (C5) occupe le dernier coin libre, en bas à gauche. Les quatre coins sont pris.",
        "16": "Blanc 16 (E4) approche aussitôt cette pierre noire, et un combat s’engage aussi en bas à gauche.",
        "19": "Noir 19 (D2) assure solidement le coin inférieur gauche : un choix sûr, bien dans le style de Shūsaku.",
        "23": "Noir 23 (E5) sort entre les pierres blanches et renforce son groupe en bas à gauche.",
        "29": "Noir 29 (F11) renforce les pierres noires de gauche tout en regardant vers le centre.",
        "30": "Blanc 30 (H4) s’étend sur le bas, presse le groupe noir de gauche et bâtit sa propre zone.",
        "31": "Noir 31 (O3) approche le coin blanc en bas à droite.",
        "33": "Noir 33 (R3) s’accole à la pierre blanche du coin. Dès lors, Noir bâtit à l’extérieur et Blanc rampe sur la troisième ligne du bord.",
        "43": "Noir 43 (Q8). Un épais mur noir descend maintenant le bord droit. Blanc a pris le territoire du coin et du bord ; Noir a gagné de la force extérieure.",
        "44": "Blanc 44 (L17) s’installe entre les pierres noires du haut pour que la zone noire ne devienne pas trop grande.",
        "50": "Blanc 50 (R18) se glisse sous le coin noir en haut à droite et vise son territoire.",
        "51": "Noir 51 (P13). Adossé au mur, Noir prépare une grande zone du bord droit vers le centre.",
        "52": "Blanc 52 (D10) s’insère entre les pierres noires du bord gauche. Les pierres s’y emmêlent.",
        "63": "Noir 63 (B10) joue au bord gauche pour que les pierres blanches n’y trouvent pas de base.",
        "65": "Noir 65 (G3) entre aussi dans la zone blanche du bas et réduit le territoire blanc.",
        "73": "Noir 73 (K17) consolide ses pierres du haut et met la pierre blanche du coup 44 sous pression.",
        "76": "Blanc 76 (P11) saute dans la zone noire du bord droit. Que cette pierre vive ou meure changera beaucoup le score.",
        "77": "Noir 77 (Q11) répond du côté de son mur et repousse Blanc vers le centre : une défense calme qui attaque aussi, typique de Shūsaku.",
        "80": "Blanc 80 (N10) s’échappe vers le centre pour fuir la poursuite noire.",
        "85": "Noir 85 (N12) continue d’attaquer tout en agrandissant son territoire en haut et à droite. Gagner en attaquant : du beau travail.",
        "91": "Noir 91 (J7) joue au-dessus des pierres blanches du bas et coiffe la zone blanche depuis le centre.",
        "100": "Blanc 100 (S17) tente quelque chose dans le coin supérieur droit pour réduire le territoire noir.",
        "119": "Noir 119 (R17) défend fermement le coin supérieur droit et repousse la tentative blanche.",
        "122": "Blanc 122 (G6) contourne les pierres noires du bas à gauche pour les couper du centre noir.",
        "131": "Noir 131 (M5) enfonce un coin dans la zone blanche, au milieu du bord inférieur.",
        "140": "Blanc 140 (B4) tente quelque chose dans le coin noir en bas à gauche. Un combat serré de prises commence au bord gauche.",
        "156": "Blanc 156 (A8) prend deux pierres noires. Le combat du bord gauche se calme après de petits gains de part et d’autre.",
        "158": "Blanc 158 (L10). Blanc a encore des pierres au centre et cherche à réduire le territoire central noir.",
        "162": "Blanc 162 (O12) prend une pierre noire. Malgré tout, la zone noire de droite reste grande.",
        "172": "Blanc 172 (K18). On entre dans le yose, en commençant par la frontière du haut.",
        "186": "Blanc 186 (T16) rogne le territoire noir au bord en haut à droite. Dans le yose, chacun joue d’abord les plus gros points.",
        "205": "Noir 205 (Q18) ferme la partie droite du haut et y fixe son territoire.",
        "223": "Noir 223 (P10) fixe la frontière entre le territoire noir de droite et les pierres blanches réfugiées au centre.",
        "233": "Noir 233 (Q9) prend une pierre blanche. Le territoire noir de droite est presque entièrement sauf.",
        "239": "Noir 239 (A6) prend une pierre et un ko apparaît au bord gauche. La lutte point par point continue jusqu’au bout.",
        "260": "Blanc 260 (T6) prend une pierre et crée un autre ko au bord en bas à droite. Noir reprend en 263 (T5).",
        "267": "La partie s’achève au coup 267 : Noir gagne de 11 points. Pas d’aventure : Shūsaku a attaqué et laissé son territoire grandir naturellement, une victoire bien à son image. C’était la première de ses 19 victoires d’affilée au château."
      } },
    "shilin": { "t": "La partie du Shilin Guangji", "w": "Rouges (nom non conservé)", "b": "Noirs (nom non conservé)", "ev": "Encyclopédie de la vie quotidienne Shilin Guangji : « partie gagnée en cédant le trait, canons du même côté »", "d": "XIIIe siècle", "pl": "Chine (Song–Yuan)", "lead": "Ce relevé vient du Shilin Guangji, une encyclopédie de la vie quotidienne réunie par Chen Yuanjing entre la fin de la dynastie Song et le début des Yuan. On le considère comme l’un des plus anciens relevés complets de xiangqi conservés. C’est une partie modèle où le joueur le plus fort laisse l’autre commencer, et en neuf coups seulement le cheval noir piège le char rouge.",
      c: {
        "0": "Ce relevé a plus de 700 ans ; il date de l’époque entre les Song et les Yuan. Il figure dans le chapitre des jeux de l’encyclopédie Shilin Guangji, et on le considère comme l’une des plus anciennes parties complètes de xiangqi encore connues. Le nom des joueurs n’a pas été conservé. Le titre dit que le plus fort a « cédé le trait » au plus faible : c’est donc une leçon qui montre comment Rouge, qui commence, finit par perdre. Rouge est en bas et joue en premier.",
        "1": "Rouge place le canon de droite sur la colonne centrale. C’est le Canon central, braqué sur le général noir, et c’est encore aujourd’hui l’une des ouvertures les plus fortes. On voit qu’on la jouait déjà il y a 700 ans.",
        "2": "Noir répond aussi par un canon au centre : les deux canons se font face. Quand les deux camps jouent le canon du même côté, on parle de « canons dans le même sens ». Le duel de canons plaît depuis des siècles.",
        "3": "Rouge sort un cheval pour protéger le soldat central. Ce soldat est visé par le canon noir et a besoin d’un défenseur. Le cheval se prépare aussi à avancer.",
        "4": "Noir fait de même et protège son soldat central avec un cheval. Les deux camps bâtissent d’abord une base solide.",
        "5": "Rouge déplace le char de droite d’un pas sur le côté, vers une colonne ouverte. Le char est la pièce la plus forte, il vaut mieux le faire travailler tôt.",
        "6": "Noir sort l’autre cheval et laisse les chars à la maison pour l’instant. L’idée est d’avancer d’abord les pièces. Mais un char sorti tard est parfois difficile à utiliser ensuite dans l’attaque.",
        "7": "Le char rouge traverse d’un coup la rivière et entre dans le camp noir. Il veut menacer des pièces noires, mais les autres pièces rouges sont encore chez elles : l’attaque est un peu précipitée. Sortir d’abord le cheval ou le char de gauche était aussi possible.",
        "8": "Noir avance d’un pas le soldat de la colonne 3. Il ouvre ainsi un chemin au cheval, qui pourra sauter en avant plus tard. Noir invite presque le char rouge à venir.",
        "9": "Le char rouge prend un soldat et vise maintenant le cheval noir derrière. Gagner une pièce et en menacer une autre semble excellent. Mais le char est parti très loin, sans aucun ami autour. Un char seul dans le camp adverse se fait facilement chasser.",
        "10": "Le cheval noir saute en avant. Il fuit le char et se rapproche du camp rouge en même temps : deux tâches en un coup. Ce cheval sera la vedette de la partie.",
        "11": "Rouge recule le char d’un pas pour attaquer le cheval par le côté. Le char prend de loin, le cheval ne peut pas se reposer. Mais ce coup n’aide toujours pas à développer les autres pièces rouges.",
        "12": "Le cheval noir avance encore et traverse la rivière dans le camp rouge. Chaque fois qu’il fuit le char, il se rapproche du général rouge.",
        "13": "Rouge avance un soldat pour ouvrir le chemin de son propre cheval. L’idée est de le sortir pour l’échanger contre le cheval noir. Mais cela laisse à Noir le temps d’aller encore plus loin.",
        "14": "Noir lève un éléphant et attaque le char rouge. Chasser le char adverse avec une pièce de défense, c’est très efficace. Rouge doit encore bouger son char, et Noir gagne un temps de plus.",
        "15": "Le char rouge glisse de côté et prend un autre soldat. Rouge a deux soldats de plus, mais c’est le coup perdant. Le char est maintenant loin de son général et ne peut plus revenir défendre. Il fallait parer le cheval, par exemple en ramenant le char.",
        "16": "Le cheval noir s’enfonce et attaque le char rouge. Et ce n’est pas tout : s’il saute encore une fois, il fera échec au général rouge tout en attaquant le char du coin rouge. Un seul cheval a créé deux menaces à la fois.",
        "17": "Rouge poursuit le cheval avec son char. Mais on ne peut plus l’arrêter. Autour du général rouge, il n’y a plus personne pour aider.",
        "18": "Le cheval bondit avec échec ! Il attaque aussi le char du coin rouge : quand le général s’écarte, le char est perdu. Neuf coups seulement, mais la partie montre ce qui arrive à un char qui part seul en avant, et pourquoi les pièces doivent se battre ensemble. Il y a 700 ans, les joueurs réfléchissaient déjà aux mêmes choses sur le même plateau."
      } },
    "qima13": { "t": "Le sacrifice du cheval en treize coups (Juzhongmi)", "w": "Rouges (nom non conservé)", "b": "Noirs (nom non conservé)", "ev": "Juzhongmi, livre 1, partie 1", "d": "1632 (publication)", "pl": "Chine (Ming)", "lead": "C’est la toute première partie du Juzhongmi (« Le secret de la mandarine »), un livre de xiangqi publié en 1632 par Zhu Jinzhen, sous la dynastie Ming. Rouge laisse Noir prendre un cheval gratuitement, s’engouffre pendant ce temps et mate en treize coups. Sous le nom de « sacrifice du cheval en treize coups », elle est encore appréciée près de 400 ans plus tard.",
      c: {
        "0": "C’est la partie 1 du Juzhongmi, un livre imprimé en 1632, vers la fin de la dynastie Ming. Avec le Manuel de la fleur de prunier, plus tardif, on l’appelle l’un des deux grands classiques du xiangqi. Ce n’est pas une vraie partie mais un modèle écrit pour enseigner un plan, d’où l’absence de noms. Rouge est en bas et commence, et tout est fini en treize coups.",
        "1": "Rouge place le canon de droite au centre. C’est le Canon central, qui fixe le général noir. Le Juzhongmi est célèbre pour avoir étudié comment attaquer avec cette ouverture.",
        "2": "Noir place aussi au centre le canon du même côté. Ce sont les « canons dans le même sens », qui se heurtent de face. Chaque camp vise le soldat central adverse.",
        "3": "Rouge sort un cheval pour protéger le soldat central. Il défend le soldat visé par le canon noir, et le cheval commence à travailler.",
        "4": "Noir protège lui aussi son soldat central avec un cheval. Jusqu’ici, les deux camps ont la même forme.",
        "5": "Rouge avance le char de droite d’un seul pas. Au coup suivant, il pourra filer sur le côté. Un char qui se déplace ainsi latéralement s’appelle un « char horizontal » : il peut vite passer d’une aile à l’autre.",
        "6": "Noir déplace son char d’un pas de côté pour pouvoir monter tout droit. C’est un « char droit ». Char horizontal contre char droit : deux façons d’utiliser le char se font face.",
        "7": "Le char horizontal rouge file vers une colonne à gauche. Cette colonne longe le conseiller noir, là où la défense est faible. Rouge se prépare à percer par là.",
        "8": "Le char droit noir traverse la rivière et s’enfonce dans le camp rouge. Noir veut répondre par sa propre attaque. Mais ce coup se presse d’attaquer avant de défendre.",
        "9": "Le char rouge plonge au fond du camp noir. Il se pose sur « l’œil » de l’éléphant, le point où l’éléphant doit passer, si bien que l’éléphant noir ne peut plus bouger. Collé au conseiller, il est maintenant tout près du général.",
        "10": "Noir sort l’autre cheval vers le bord. L’idée est aussi d’empêcher le char rouge de se glisser par le côté.",
        "11": "Voici le sacrifice du cheval ! Rouge lève l’autre char d’un pas. Le cheval du coin gauche n’a alors plus de défenseur, et le canon noir peut le prendre gratuitement. Mais en échange d’un cheval, Rouge gagne le temps de jeter vite ses deux chars dans l’attaque.",
        "12": "Le canon noir prend le cheval rouge. Noir semble avoir gagné une pièce. Mais ce canon est loin de chez lui et ne peut plus défendre. On dit qu’il valait mieux renforcer la défense en levant un conseiller au lieu de prendre.",
        "13": "Le canon rouge avance. En utilisant le canon central noir comme « écran » à sauter, il vise le cheval noir derrière. Le canon est une pièce étrange qui prend en sautant exactement une pièce.",
        "14": "Noir recule son cheval pour fuir. Mais ce cheval était la pièce importante qui gardait le soldat central. En fuyant, il ouvre un trou au centre. Noir avait d’autres défenses, mais c’était le pire choix.",
        "15": "Le canon rouge prend le soldat central — échec ! Sans le cheval noir, le centre était grand ouvert. À partir d’ici, l’attaque rouge déferle.",
        "16": "Noir lève un conseiller pour boucher le devant du général. C’est la seule bonne façon de parer l’échec.",
        "17": "Le second char rouge arrive sur la même colonne. Deux chars alignés sur une colonne, c’est extrêmement fort. Le plan est de percer jusqu’au fond du camp noir.",
        "18": "Le général noir s’écarte sur le côté. Sinon, il serait fixé par les deux chars rouges alignés.",
        "19": "Le char rouge de devant prend le conseiller noir — échec ! L’autre conseiller va le prendre aussitôt, mais cela fait partie du plan. Rouge sacrifie un char pour briser la garde du général noir. Quel coup audacieux !",
        "20": "Noir prend le char avec le conseiller. En matériel, Noir est très en avance. Mais la maison du général est encore plus vide.",
        "21": "Le dernier char rouge passe sur la colonne du général — encore échec. Le général noir n’a presque plus de pièces pour le protéger.",
        "22": "Noir place un canon devant le général pour parer l’échec. Mettre une pièce entre les deux, c’est s’interposer.",
        "23": "Le char rouge prend ce canon — encore échec. Le char continue de prendre des pièces noires tout en acculant le général.",
        "24": "Le général noir ne peut que revenir au centre. Tous les autres points sont tenus par des pièces rouges.",
        "25": "Enfin, le canon rouge se place au centre : deux canons sur une colonne — échec. Le canon de devant sert d’écran et celui de derrière frappe le général : c’est le mat du « double canon ». Le général noir n’a plus de case et Rouge gagne. En donnant seulement un cheval, Rouge a gagné en treize coups. Depuis 400 ans, cette partie enseigne que le temps et l’activité des pièces peuvent compter plus que leur nombre."
      } }
  },
  "pt": {
    ui: {"lead":"Grandes partidas, lance a lance. Acompanhe no tabuleiro partidas famosas enquanto Musowl explica cada lance.","all":"Todas","k_chess":"Xadrez","k_shogi":"Shogi","k_go":"Go","k_xiangqi":"Xiangqi","side_r":"Vermelhas","res_r":"Vitória das vermelhas","back":"Voltar às Grandes partidas","start":"Início","prev":"Voltar um lance","next":"Avançar um lance","end":"Fim","play":"Reproduzir","pause":"Pausar","moves":"Lances","move":"Lance {n}","startpos":"Posição inicial","nextnote":"Próximo comentário (lance {n})","quiet":"Este lance não tem comentário.","guide":"Musowl","keys":"← → para ir lance a lance","result":"Resultado","r_event":"Partida","r_date":"Ano","r_place":"Local","side_w":"Brancas","side_b":"Pretas","side_s":"Sente","side_g":"Gote","side_B":"Pretas","side_W":"Brancas","res_w":"Vitória das brancas","res_b":"Vitória das pretas","res_d":"Empate","res_s":"Vitória de sente","res_g":"Vitória de gote","credit":"Os lances são o registro público de cada partida. Os comentários são de Musowl, do museu."},
    "opera": { "t": "A Partida da Ópera", "w": "Paul Morphy", "b": "O duque Carlos II de Brunswick e o conde Isouard", "ev": "Jogada num camarote da Ópera de Paris (os dois aliados jogando em consulta)", "d": "1858", "pl": "França (Paris)", "lead": "O jovem campeão americano contra dois nobres, durante uma apresentação na ópera: dezessete lances. Desenvolver as peças depressa, entregá-las sem hesitar e terminar com pouquíssimas. Nenhuma partida aparece em mais livros de xadrez.",
      c: {
        "0": "Paris, 1858. O americano Paul Morphy, de vinte e um anos, vinha derrotando um após outro os fortes jogadores da Europa. Naquela noite, num camarote da ópera, o duque de Brunswick e o conde Isouard pegaram juntos as pretas e o desafiaram, conversando a cada lance. Diz-se que Morphy queria terminar logo para assistir ao palco. Esses dezessete lances estão cheios do básico: desenvolver as peças depressa e pôr o rei em segurança.",
        "1": "As brancas avançam duas casas o peão do rei. Ele vigia d5 e e5 no centro e abre caminho ao bispo e à dama.",
        "2": "As pretas também jogam e5. Os peões se encaram no centro, e o peão branco não pode mais avançar.",
        "3": "O cavalo vai a f3 e ataca o peão de e5. Bom lance: desenvolve uma peça e faz o adversário pensar em defender.",
        "4": "As pretas defendem e5 com d6. É a Defesa Philidor. Sólida, mas estreita um pouco o caminho do bispo de f8.",
        "5": "As brancas jogam d4: outro peão no centro, contra e5. As pretas precisam decidir entre capturar e defender.",
        "6": "O bispo preto vai a g4. Pressiona o cavalo de f3, alinhado com a dama branca em d1. Se o cavalo sair, a dama cai, então ele não pode ir atrás de e5.",
        "7": "As brancas capturam em e5 com o peão. Se as pretas recapturassem logo com o peão de d6, as brancas trocariam as damas e depois o cavalo pegaria o peão de e5. Por isso as pretas querem primeiro tirar o cavalo de f3.",
        "8": "As pretas capturam o cavalo com o bispo. Agora podem recuperar e5 com segurança. Mas entregar pelo cavalo o bispo que tinha acabado de sair deixa as pretas atrasadas no desenvolvimento.",
        "9": "As brancas recapturam com a dama, que já trabalha perto do centro, enquanto as pretas quase não desenvolveram peças.",
        "10": "As pretas recapturam com um peão e o material fica igual. Mas em peças desenvolvidas, as brancas estão à frente.",
        "11": "Bispo em c4. Junto com a dama de f3, mira f7. Só o rei protege f7, então é uma casa fraca: capturá-la seria mate.",
        "12": "As pretas levam o cavalo a f6 e fecham a coluna f. Sem isso, dama captura f7 seria mate. Defender desenvolvendo é a resposta certa.",
        "13": "A dama gira para b3 e ataca f7 e b7 ao mesmo tempo. Um lance com duas ameaças é forte, porque o adversário não consegue defender as duas.",
        "14": "As pretas levam a dama a e7 para defender f7 e deixam b7. Mas agora a dama bloqueia o bispo de f8.",
        "15": "Morphy não captura o peão de b7: desenvolve um cavalo. Capturar mandaria a dama para longe. Preferir o desenvolvimento rápido a um peão é bem típico de Morphy.",
        "16": "As pretas jogam c6: controlam d5 e b5 e abrem caminho para a dama ir a b6.",
        "17": "Bispo em g5: crava o cavalo de f6. Se o cavalo sair, a dama de e7 atrás pode ser capturada. As peças pretas ficam cada vez mais presas.",
        "18": "As pretas jogam b5 para expulsar o bispo de c4. Também ganham espaço na ala da dama, mas abrem uma brecha para as peças brancas entrarem.",
        "19": "O cavalo é entregue para capturar em b5! Em vez de recuar o bispo, Morphy continua atacando. Com o rei preto ainda no centro, isso é muito perigoso para as pretas.",
        "20": "As pretas capturam o cavalo e ficam com um cavalo a mais. Mas o rei preto continua em e8, e as peças brancas continuam chegando.",
        "21": "Bispo em b5, xeque! O rei preto continua preso no centro. As brancas têm dois peões pelo cavalo e vão direto ao rei.",
        "22": "As pretas bloqueiam com o cavalo em d7. Mas esse cavalo está cravado: se sair, o rei preto fica em xeque. Agora as brancas vão mirar d7.",
        "23": "As brancas fazem o roque grande. O rei fica seguro e, ao mesmo tempo, a torre chega a d1 para mirar d7. Um só lance defende e ataca: excelente.",
        "24": "As pretas levam a torre a d8 para defender d7. Ainda não podem rocar, e a torre de h8 e o bispo de f8 não fazem nada.",
        "25": "A torre é entregue para capturar em d7! As brancas dão uma torre para eliminar um defensor preto.",
        "26": "As pretas recapturam com a torre. Agora essa torre de d7 também está cravada: se sair, o bispo de b5 dá xeque no rei preto.",
        "27": "A outra torre vem a d1 e ataca d7 de novo. Agora há mais peças brancas atacando d7 do que pretas defendendo.",
        "28": "A dama preta vai a e6: oferece a troca de damas para afastar a dama de b3 e quer ajudar d7. Mas já é tarde.",
        "29": "O bispo captura em d7 com xeque. As brancas eliminam os defensores pretos um a um.",
        "30": "As pretas recapturam com o cavalo. Sem o cavalo em f6, a diagonal do bispo de g5 até d8 fica aberta. Essa diagonal fará diferença no final.",
        "31": "A dama é entregue em b8, com xeque! É o lance mais famoso da partida. As pretas têm de capturar com o cavalo, e quando ele sai de d7, a coluna d se abre.",
        "32": "As pretas capturam com o cavalo. Agora nenhuma peça preta protege d8.",
        "33": "Torre em d8, xeque-mate! O bispo de g5 apoia d8, e o rei preto fica preso pelas próprias peças. As brancas entregaram dama, torre e bispo e terminaram só com uma torre e um bispo. Desenvolver rápido, pôr o rei em segurança e atacar enquanto o rei adversário está no centro: esta partida famosa reúne todas essas ideias importantes."
      } },
    "reti1910": { "t": "O Mate de Réti", "w": "Richard Réti", "b": "Savielly Tartakower", "ev": "Uma partida amistosa (não de torneio)", "d": "1910", "pl": "Áustria (Viena)", "lead": "Dois futuros grandes mestres, uma partida amistosa em Viena, onze lances. As brancas entregam a dama e terminam com um xeque duplo: duas peças dando xeque ao mesmo tempo. Esse mate leva o nome das brancas: o Mate de Réti.",
      c: {
        "0": "Viena, 1910. As brancas são de Richard Réti, de vinte anos; as pretas, de Savielly Tartakower. Os dois ficaram entre os melhores do mundo e são famosos por trazer ideias novas ao xadrez. Não era uma partida de torneio, mas uma amistosa por uma pequena aposta. É curta, mas mostra bem por que é preciso pôr o rei em segurança cedo.",
        "1": "As brancas avançam duas casas o peão do rei. Ocupar o centro ajuda as peças de trás a sair. O bispo e a dama já têm caminho aberto.",
        "2": "As pretas jogam c6. Em vez de ir logo ao centro, preparam d5 para atacar o peão de e4. Essa abertura sólida se chama Defesa Caro-Kann.",
        "3": "As brancas também põem o outro peão em d4. Dois peões lado a lado no centro: as brancas têm muito espaço. As pretas vão tentar desmanchá-los.",
        "4": "Como planejado, d5. O peão desafia e4: \"posso te capturar\". As brancas precisam decidir se defendem, avançam ou trocam.",
        "5": "As brancas desenvolvem um cavalo para defender e4. Desenvolvem uma peça e defendem ao mesmo tempo, sem perder tempo.",
        "6": "As pretas capturam o peão de e4. Trocando peões centrais, diminuem o centro branco.",
        "7": "As brancas recapturam com o cavalo, que fica no meio do tabuleiro. Um cavalo central alcança muitas casas e é muito forte.",
        "8": "As pretas desenvolvem um cavalo de frente para o de e4. Aqui costuma-se jogar bispo em f5, mas as pretas convidam à troca de cavalos.",
        "9": "A dama sai cedo para d3 para defender o cavalo de e4. Normalmente não se tira a dama tão cedo, mas as brancas têm um plano. Lembre que essa dama está na coluna d, em frente ao rei preto.",
        "10": "As pretas jogam e5 e oferecem um peão para abrir caminho ao bispo e à dama. É um lance ativo que começa a luta no centro.",
        "11": "As brancas capturam o peão de e5. Aceitam o presente, mas assim a dama preta ganha liberdade.",
        "12": "Xeque! A dama preta em a5 mira na diagonal o rei em e1. Ao mesmo tempo quer recuperar o peão de e5: duas tarefas num lance. As brancas precisam bloquear.",
        "13": "As brancas bloqueiam o xeque com o bispo em d2. A dama poderia capturar o bispo, mas a dama branca o protege bem.",
        "14": "As pretas recuperam o peão e o material volta a ficar igual. Além disso, essa dama olha pela coluna e para o cavalo de e4 e o rei atrás dele. Se o cavalo se mexer, o rei fica em xeque, então o cavalo está preso. Parece que as pretas vão ganhá-lo.",
        "15": "As brancas fazem o roque grande. O rei sai da coluna e, e o cavalo fica livre de novo. Ao mesmo tempo uma torre chega a d1: a torre de d1, a dama de d3 e a casa d8, ao lado do rei preto, ficam na mesma linha. Essa é a armadilha branca.",
        "16": "As pretas capturam o cavalo de e4 e parecem ganhar uma peça. Mas o rei preto ainda está em e8 e não rocou. As peças brancas estão na coluna d, e o rei preto está desprotegido. Esse lance, que perde a partida, é o momento decisivo.",
        "17": "Dama em d8, xeque! As brancas dão de graça sua peça mais forte. A única peça preta que pode capturá-la é o rei. Deixando capturar, as brancas puxam o rei para a casa perigosa d8.",
        "18": "As pretas são obrigadas a capturar com o rei; não há outro jeito de parar o xeque. O rei fica em d8, com a torre de d1 esperando atrás.",
        "19": "O bispo vai de d2 para g5 com xeque e, ao mesmo tempo, abre o caminho da torre de d1, que também dá xeque pela coluna d. Duas peças dando xeque juntas: um xeque duplo. Não dá para parar capturando uma peça nem bloqueando, então o rei tem que fugir.",
        "20": "O rei foge para c7. Se fosse para e8, a torre viria a d8 e daria mate. Para onde o rei for, as brancas têm o golpe final pronto.",
        "21": "Bispo em d8: xeque-mate na diagonal contra o rei em c7! O bispo está protegido pela torre de d1, então o rei não pode capturá-lo. Casas como b8, c8, b7 e c6 estão ocupadas pelas próprias peças pretas, e a torre vigia d6 e d7. Em apenas onze lances, as brancas entregaram a dama e venceram com duas peças pequenas. A partida mostra como é perigoso ir atrás de material antes de rocar. Alguns registros dizem que as pretas abandonaram um lance antes."
      } },
    "immortal": { "t": "A Imortal", "w": "Adolf Anderssen", "b": "Lionel Kieseritzky", "ev": "Partida informal num intervalo do torneio de Londres 1851", "d": "1851", "pl": "Reino Unido (Londres)", "lead": "Londres, durante o primeiro torneio internacional de xadrez: uma partida jogada num intervalo. As brancas entregam um bispo, as duas torres e por fim a dama, e dão mate com as três peças menores que restam. Diz-se que as pretas abandonaram antes do fim e que os últimos lances seriam o final mostrado pelas brancas.",
      c: {
        "0": "Londres, 1851. Num intervalo do torneio, o alemão Anderssen (brancas) e Kieseritzky, estrela de Paris (pretas), jogaram uma partida amistosa.",
        "1": "As brancas avançam duas casas o peão do rei.",
        "2": "As pretas fazem o mesmo.",
        "3": "f4! As brancas oferecem um peão: é o Gambito do Rei. A ideia é tirar do centro o peão preto de e5.",
        "4": "As pretas aceitam o peão.",
        "5": "O bispo sai e mira f7, ao lado do rei preto.",
        "6": "Xeque! Sem o peão f branco, a diagonal de h4 a e1 está aberta.",
        "7": "O rei se afasta. Agora as brancas nunca mais poderão rocar.",
        "8": "As pretas também oferecem um peão, para atrair o bispo a b5.",
        "9": "As brancas capturam.",
        "10": "Sai um cavalo que ataca o peão de e4.",
        "11": "As brancas desenvolvem um cavalo e expulsam a dama de h4.",
        "12": "A dama recua para h6.",
        "13": "d3 protege e4 e abre caminho para o bispo de c1.",
        "14": "Cavalo em h5. O plano é saltar para g3 com xeque e atacar a torre de h1.",
        "15": "O cavalo branco vai a h4, pronto para saltar a f5 e incomodar a dama preta.",
        "16": "A dama preta vai a g5 e ataca o cavalo de h4.",
        "17": "Cavalo em f5, uma boa casa protegida pelo peão de e4. Ele também mira o peão de g7.",
        "18": "c6 tenta expulsar o bispo de b5.",
        "19": "As brancas não salvam o bispo: g4 persegue o cavalo de h5.",
        "20": "O cavalo volta para f6.",
        "21": "Torre em g1, protegendo o peão de g4. As brancas deixam o bispo de b5 ir embora. Que ousadia!",
        "22": "As pretas capturam o bispo e ficam com uma peça a mais.",
        "23": "O peão h começa a perseguir a dama preta.",
        "24": "A dama vai a g6.",
        "25": "h5 persegue a dama de novo.",
        "26": "A dama só pode voltar a g5. Ela tem cada vez menos casas.",
        "27": "A dama branca vai a f3. Se o bispo depois capturar em f4, a dama preta pode ficar presa.",
        "28": "As pretas levam o cavalo de volta a g8 para a dama poder fugir para f6.",
        "29": "O bispo captura o peão de f4 e ataca a dama.",
        "30": "A dama foge para f6.",
        "31": "Sai um cavalo, com a ideia de saltar a d5 e atacar a dama.",
        "32": "O bispo sai e mira a torre de g1.",
        "33": "Cavalo em d5, atacando a dama de f6 e a casa c7. As brancas não se importam em perder a torre de g1.",
        "34": "A dama captura o peão de b2 e ataca a torre de a1.",
        "35": "Bispo em d6! As brancas deixam as duas torres irem embora. Em troca, suas peças fecham uma rede em volta do rei preto.",
        "36": "As pretas capturam a torre de g1.",
        "37": "e5! Esse peão corta a diagonal da dama de b2 até g7. A dama preta não pode mais voltar para ajudar o rei.",
        "38": "As pretas capturam também a outra torre, com xeque.",
        "39": "O rei vai a e2. As brancas só têm a dama, dois cavalos e um bispo.",
        "40": "O cavalo vai a a6 para proteger c7. Diz-se que as pretas abandonaram por aqui; o resto seria o final mostrado pelas brancas.",
        "41": "O cavalo captura em g7 com xeque.",
        "42": "O rei foge para d8.",
        "43": "A dama é entregue em f6, com xeque! A última peça grande também se vai.",
        "44": "As pretas têm de capturar com o cavalo.",
        "45": "Bispo em e7, xeque-mate! O cavalo de d5 controla e7 e c7, e o de g7 controla e8. As brancas vencem só com um bispo e dois cavalos."
      } },
    "mimiaka": { "t": "A partida das orelhas vermelhas", "w": "Hon’inbō Shūsaku", "b": "Inoue Gennan Inseki", "ev": "Partida em Osaka (jogada em três dias)", "d": "1846", "pl": "Japão (Osaka)", "lead": "Aos 17 anos, Shūsaku (4-dan) enfrentou Gennan (8-dan), um dos mais fortes jogadores da época. Conta-se que, no lance 127, as orelhas de Gennan ficaram vermelhas. Não havia komi: as pretas venceram por 2 pontos.",
      c: {
        "0": "Osaka, 1846. Shūsaku joga de pretas, Gennan de brancas. No dia anterior começaram uma partida com duas pedras de handicap, mas ela foi interrompida; agora Shūsaku joga de pretas sem handicap.",
        "1": "Preto 1 no ponto 3-4 do canto superior direito (R16): um lugar baixo que garante bem o canto.",
        "2": "Branco 2 ocupa o 3-4 do canto superior esquerdo (D17). Primeiro dividem-se os cantos vazios.",
        "5": "Com 1, 3 e 5, as pretas ocupam três cantos, todos em pontos 3-4. Era a abertura favorita de Shūsaku, muito estudada depois.",
        "6": "Branco 6 em C14, no lado esquerdo. Em vez de se aproximar do canto preto, posiciona-se no lado: escolha pouco comum.",
        "7": "Preto 7 (E4) fecha o canto inferior esquerdo com uma segunda pedra. Esse «fechamento» deixa o canto bem sólido.",
        "8": "Branco 8 (R5) aproxima-se do canto preto de Q3. Vai começar uma grande luta no canto inferior direito.",
        "10": "Branco 10 (O4) é o taisha: cobre a pedra preta na diagonal, de longe. Tem muitíssimas variantes e era o lance favorito de Gennan.",
        "11": "Com 11 (Q5), as pretas entram numa linha difícil. Gennan conhecia bem o taisha, por isso é preciso cuidado.",
        "24": "No canto inferior direito as pedras se misturam; cada lado tenta cortar o outro. Após Branco 24 (N4), as pretas têm dificuldade para sair.",
        "25": "Preto 25 (N3). Estudos posteriores indicam que havia algo melhor aqui. Mesmo para um mestre, era um momento difícil.",
        "28": "Com 28 (M3) e 30 (L2), as brancas atacam logo o ponto fraco. As pretas podem ficar presas num espaço pequeno embaixo.",
        "31": "Preto 31 (M4) é importante. Prepara o ko que vem — a luta de capturar e recapturar — criando ameaças que as brancas terão de responder.",
        "36": "Branco 36 (N2). Antes de abrir o ko, as brancas jogam aqui primeiro. Bom momento.",
        "40": "Branco 40 (R1) captura uma pedra e começa o ko. Quem perdeu a pedra não pode recapturar logo: primeiro faz uma ameaça em outro lugar.",
        "41": "Preto 41 (O5) é uma ameaça de ko. Custa um pouco, mas aqui não há nada melhor.",
        "53": "Preto 53 (R10) é uma ideia engenhosa que poucos encontrariam. Ataca a forma branca no lado direito.",
        "60": "Branco 60 (S3) é um lance grande. Também permite jogar 62 (M1) mantendo a iniciativa.",
        "63": "Com Preto 63 (O1), a longa luta no canto inferior direito se acalma. Branco tem território embaixo; Preto, uma parede grossa à direita. Até aqui Branco parece melhor.",
        "67": "Preto 67 (L17). Apoiado na parede da direita, Preto prepara uma grande estrutura em cima.",
        "72": "Branco 72 (P13) é excelente. Colocado logo acima da parede preta, impede que a estrutura preta cresça.",
        "74": "Daqui até perto do lance 100, Gennan não relaxa nem uma vez. Evita os ataques pretos e mantém suas pedras ligadas.",
        "83": "Preto 83 (H3) entra na área branca de baixo para reduzi-la.",
        "96": "A partir de Branco 96 (R14), há uma luta fina perto do canto preto superior direito. Branco volta a encontrar boa forma.",
        "107": "Preto 107 (P10) captura uma pedra branca. O grupo preto da direita fica seguro.",
        "118": "Branco 118 (M19) captura uma pedra e seu grupo de cima também vive. A estrutura preta de cima fica menor que o esperado.",
        "126": "Branco 126 (J5). As brancas estão fortes embaixo e avançam para o centro. Diz-se que quase todos os profissionais presentes achavam que Branco estava na frente.",
        "127": "Este é o famoso lance das orelhas vermelhas, Preto 127 (K11). Diz-se que esta pedra central atua em quatro direções: amplia a área preta de cima, enfraquece a força branca de baixo, ajuda o grupo preto da direita e impede Branco de avançar para a esquerda.",
        "128": "Nesse momento, um médico que assistia notou que as orelhas de Gennan tinham ficado vermelhas. Ele pouco sabia de go, mas teria visto nisso um sinal de abalo e previsto a vitória das pretas.",
        "131": "Preto 131 (D10). As pretas também entram no lado esquerdo branco e reduzem o território em todo o tabuleiro.",
        "147": "Preto 147 (K10). A pedra do lance 127 começa a render: Preto avança entre os grupos brancos no centro.",
        "160": "Branco 160 (H8). Defende as pedras do centro e mira o grupo preto do canto inferior esquerdo. A partida continua apertada.",
        "167": "Preto 167 (C2) é preciso. As pedras pretas do canto inferior esquerdo ficam seguras e a ameaça branca desaparece.",
        "175": "Preto 175 (G4) captura uma pedra branca. O território branco de baixo não é tão grande quanto parecia.",
        "199": "Preto 199 (K7). A luta do centro se acalma e começa o final: fixar as fronteiras, onde cada ponto conta.",
        "212": "Com 212 (D19) e 216 (F19), Branco captura pedras pretas na borda de cima. No final ninguém cede nada.",
        "228": "Branco 228 (N12) cria um ko no centro. Por mais de 80 lances, captura-se e recaptura-se em M13 e N13.",
        "236": "Branco 236 (T8), jogado durante o ko, captura uma pedra. Alguns analistas acham que terminar o ko aqui deixaria a partida ainda mais apertada.",
        "275": "Preto 275 (T14) captura duas pedras brancas. Durante o ko, cada lado ganha aqui e perde ali por todo o tabuleiro.",
        "299": "Preto 299 (J16) captura quatro pedras brancas de uma vez. As pretas seguram firme a parte de cima.",
        "311": "Preto 311 (M13) fecha o ko. A longa luta finalmente termina.",
        "325": "A partida termina no lance 325 e a contagem dá vitória às pretas por 2 pontos. Mesmo sem komi, um jovem de 17 anos vencer alguém como Gennan causou sensação, e o nome de Shūsaku ficou famoso."
      } },
    "evergreen": { "t": "A Sempre-Viva", "w": "Adolf Anderssen", "b": "Jean Dufresne", "ev": "Uma partida amistosa (não de torneio)", "d": "1852", "pl": "Alemanha (provavelmente Berlim)", "lead": "Anderssen, o da Imortal, jogou esta outra obra-prima um ano depois. Bem quando as pretas ameaçam mate, as brancas movem com calma uma torre, depois entregam a dama e terminam com um xeque duplo. É chamada de \"sempre-viva\" porque nunca perde o brilho.",
      c: {
        "0": "Uma partida publicada numa revista em 1852. As brancas são de Anderssen e as pretas do seu amigo Dufresne. Acredita-se que foi jogada em Berlim, mas nenhum registro confirma.",
        "1": "As brancas avançam duas casas o peão do rei.",
        "2": "As pretas fazem o mesmo.",
        "3": "O cavalo ataca o peão de e5.",
        "4": "As pretas defendem e5 com um cavalo.",
        "5": "O bispo sai e mira f7.",
        "6": "As pretas também desenvolvem um bispo.",
        "7": "b4! Uma oferta de peão chamada Gambito Evans. Enquanto as pretas capturam, as brancas reforçam o centro.",
        "8": "As pretas capturam o peão.",
        "9": "c3 persegue o bispo e prepara d4.",
        "10": "O bispo recua para a5.",
        "11": "d4 ocupa o centro.",
        "12": "As pretas capturam o peão.",
        "13": "As brancas não recapturam: fazem o roque. A segurança do rei e as peças ativas vêm antes dos peões.",
        "14": "O peão preto avança até d3, dentro do campo branco.",
        "15": "Dama em b3. Junto com o bispo de c4, mira f7.",
        "16": "As pretas defendem f7 com a dama.",
        "17": "e5 persegue a dama.",
        "18": "A dama vai a g6.",
        "19": "Torre em e1, na coluna e, para apoiar o peão de e5.",
        "20": "As pretas desenvolvem um cavalo para preparar o roque.",
        "21": "Bispo em a3, mirando na diagonal o cavalo de e7. Se esse cavalo sair, o bispo alcança f8, então fica difícil para as pretas fazer o roque pequeno.",
        "22": "As pretas oferecem um peão para desviar as peças brancas.",
        "23": "A dama captura.",
        "24": "Torre em b8, perseguindo a dama pela coluna b.",
        "25": "A dama vai a a4.",
        "26": "O bispo recua para b6.",
        "27": "Sai um cavalo. Quase todas as peças brancas estão em jogo.",
        "28": "As pretas desenvolvem o outro bispo.",
        "29": "Cavalo em e4, de olho em f6.",
        "30": "A dama preta vai a f5 e ataca o cavalo de e4.",
        "31": "O bispo captura o peão de d3 e protege o cavalo de e4.",
        "32": "Dama em h5, mirando o cavalo de f3.",
        "33": "O cavalo é entregue em f6, com xeque!",
        "34": "As pretas capturam com um peão.",
        "35": "As brancas recapturam com um peão e atacam o cavalo de e7. Na coluna e, a torre de e1 também mira e7.",
        "36": "Torre em g8, mirando g2. Se a dama de h5 capturar em f3, o mate fica perto.",
        "37": "Um lance tranquilo de torre para d1! O rei branco está em perigo, mas em vez de defender, as brancas miram d7. Foi esse lance que tornou a partida \"sempre-viva\".",
        "38": "As pretas capturam o cavalo de f3. Capturar em g2 em seguida seria mate.",
        "39": "Mas as brancas jogam antes. A torre captura o cavalo de e7, com xeque!",
        "40": "As pretas recapturam com o cavalo de c6. Agora a diagonal de a4 a d7 está aberta.",
        "41": "A dama é entregue em d7, com xeque!",
        "42": "As pretas têm de capturar com o rei.",
        "43": "O bispo vai a f5 com xeque e abre a coluna d para a torre de d1: xeque duplo.",
        "44": "O rei vai a e8. Em c6, o bispo daria mate em d7.",
        "45": "Bispo em d7, xeque.",
        "46": "O rei vai a f8.",
        "47": "O bispo de a3 captura o cavalo de e7: xeque-mate! O bispo de d7 controla e8, e o peão de f6 controla e7 e g7."
      } },
    "lasker1912": { "t": "A Caça ao Rei", "w": "Edward Lasker", "b": "George Alan Thomas", "ev": "Partida rápida e amistosa no City of London Chess Club", "d": "1912", "pl": "Reino Unido (Londres)", "lead": "Uma partida rápida e amistosa num clube de Londres. As brancas entregam a dama e perseguem o rei preto pelo tabuleiro inteiro, de g8 a g1. Os primeiros lances aparecem em ordens um pouco diferentes conforme o registro, mas a posição depois do lance 10 é a mesma.",
      c: {
        "0": "Outubro de 1912, City of London Chess Club. As brancas são de Edward Lasker, um jovem engenheiro recém-chegado da Alemanha; as pretas, de George Alan Thomas, depois campeão britânico. Foi uma partida rápida e amistosa. Ela é famosa como \"caça ao rei\": o rei preto é perseguido de g8 até g1, do outro lado do tabuleiro. Lasker depois foi para os Estados Unidos e ficou conhecido por seus livros de xadrez.",
        "1": "As brancas começam com d4, o peão da dama. Controla e5 e c5 e abre caminho ao bispo de c1.",
        "2": "As pretas jogam e6: primeiro uma posição sólida, preparando f5 ou d5.",
        "3": "Cavalo em f3. Controla e5 e ajuda a defender a ala do rei: a casa mais natural.",
        "4": "As pretas jogam f5 e controlam e4, como na Defesa Holandesa. Mas mexer um peão na frente do rei o enfraquece um pouco.",
        "5": "O outro cavalo vai a c3, preparando e4 para atacar o peão de f5.",
        "6": "As pretas desenvolvem um cavalo em f6: controlam ainda mais e4 e preparam o roque.",
        "7": "Bispo em g5, mirando o cavalo de f6. Esse cavalo é um defensor importante do rei preto, por isso as brancas querem tirá-lo cedo.",
        "8": "As pretas põem o bispo em e7 para proteger o cavalo e se aproximam do roque.",
        "9": "As brancas trocam o bispo pelo cavalo. Some o cavalo que protegia o rei preto.",
        "10": "As pretas recapturam com o bispo. Agora esse bispo de f6 assume a tarefa de guardar a ala do rei.",
        "11": "e4! As brancas atacam o peão de f5 e ganham espaço no centro. Linhas se abrem e as peças brancas se movem melhor.",
        "12": "As pretas capturam o peão de e4. Senão, as brancas jogariam e5 e empurrariam as peças pretas para trás.",
        "13": "O cavalo recaptura e fica no centro, de olho no bispo de f6 e nas casas g5 e d6.",
        "14": "As pretas jogam b6 para levar o bispo a b7 e mirar pela grande diagonal o cavalo de e4.",
        "15": "Cavalo em e5, uma forte casa central que também mira g4 e f7. Os dois cavalos brancos já estão perto da ala do rei preto.",
        "16": "As pretas fazem o roque. O rei está em g8. Mas sem o peão f, há muitos buracos em volta do rei.",
        "17": "Bispo em d3. Por enquanto o próprio cavalo de e4 atrapalha, mas atrás dele está o peão de h7. Assim que o cavalo de e4 se mexer, esse bispo vai mirar direto em h7.",
        "18": "O bispo preto vai a b7 e mira pela grande diagonal o cavalo de e4, tirando liberdade das peças brancas.",
        "19": "Dama em h5, mirando o peão de h7, que só o rei preto defende. Dama, bispo e cavalos brancos apontam todos para o rei preto.",
        "20": "As pretas põem a dama em e7. Ela protege o bispo de f6 e prepara ir a c5, mas as pretas não veem a ideia branca. Era preciso jogar h6 ou capturar o cavalo de e5. Este é o momento decisivo.",
        "21": "A dama é entregue em h7, com xeque! As brancas dão de graça sua peça mais forte. Lasker via todo o caminho para perseguir o rei até o mate.",
        "22": "As pretas têm de capturar com o rei, que fica em h7.",
        "23": "O cavalo captura o bispo de f6 com xeque. Ao mesmo tempo e4 fica livre, e o bispo de d3 também dá xeque no rei em h7: xeque duplo. Não dá para bloquear, então o rei tem de fugir.",
        "24": "O rei vai a h6. Em h8, o outro cavalo saltaria para g6 com mate. O rei é empurrado cada vez mais para a frente.",
        "25": "O outro cavalo salta de e5 para g4 com xeque, ataca o rei em h6 e o empurra ainda mais.",
        "26": "O rei vai a g5: deixa o próprio campo e caminha para o lado branco.",
        "27": "Xeque com o peão h! Até os peões entram na caçada. O rei tem de continuar avançando.",
        "28": "O rei vai a f4. Já passou do meio do tabuleiro e está entrando no campo branco.",
        "29": "Outro xeque, com o peão g. Dois peões fecham o caminho de volta do rei.",
        "30": "O rei vai a f3, no meio das peças brancas.",
        "31": "O bispo recua de d3 para e2 com xeque. O rei é empurrado ainda mais para dentro.",
        "32": "O rei vai a g2. O rei branco em e1 já não está longe.",
        "33": "Torre em h2, xeque. Finalmente a torre entra no jogo.",
        "34": "O rei enfim chega a g1. Saiu de g8 e chegou à primeira fileira do outro lado do tabuleiro.",
        "35": "O rei branco vai de e1 para d2. Isso abre o caminho da torre de a1, que dá xeque no rei em g1 pela primeira fileira: xeque-mate! O roque grande também dava mate, mas Lasker moveu o rei. Numa partida rápida, depois de entregar a dama, as brancas perseguiram o rei por catorze lances até o canto mais fundo do próprio campo. Uma partida muito rara."
      } },
    "toketsu": { "t": "A partida do sangue", "w": "Akaboshi Intetsu", "b": "Hon’inbō Jōwa", "ev": "Jogada na residência do senhor Matsudaira de Suō (em quatro dias)", "d": "1835", "pl": "Japão (Edo)", "lead": "Uma partida nascida da disputa pelo cargo de Meijin Godokoro, o mais alto do go japonês. Inoue Gennan Inseki enviou seu aluno Akaboshi Intetsu contra o Meijin Jōwa. Após quatro dias de luta, Intetsu perdeu e, conta-se, tossiu sangue diante do tabuleiro.",
      c: {
        "0": "1835. Pretas: Akaboshi Intetsu (7-dan); brancas: o Meijin Hon’inbō Jōwa. Gennan enviou seu melhor aluno para poder dizer que um Meijin que perde para um 7-dan não merece o título.",
        "1": "Preto 1 no 3-4 do canto inferior esquerdo (C4). Intetsu começa com calma.",
        "4": "Após quatro lances, cada canto tem uma pedra: brancas embaixo à direita e em cima à esquerda; pretas embaixo à esquerda e em cima à direita.",
        "6": "Branco 6 (E3) já se aproxima do canto preto inferior esquerdo. Jōwa é ativo desde o início.",
        "10": "Branco 10 (P4) fecha o canto inferior direito com uma segunda pedra.",
        "12": "Branco 12 (D6) pressiona de cima o canto preto inferior esquerdo. Aqui começa a maior luta da partida.",
        "13": "Preto 13 (E4) encosta numa pedra branca. As pretas aceitam a luta.",
        "20": "Branco 20 (C3) entra por baixo do canto preto: tira território do canto enquanto tenta dar vida às suas pedras.",
        "28": "Branco 28 (C9) estende-se longe pelo lado esquerdo. Costuma ser visto como exagerado: um lance feroz, bem ao estilo de Jōwa.",
        "33": "Preto 33 (C2). Diz-se que é uma linha nova estudada em segredo pela casa Inoue. Ataca as pedras brancas soltas do centro e engole as do lado esquerdo.",
        "36": "Branco 36 (F3). Tenta prender Preto por fora no canto inferior esquerdo enquanto liga suas pedras.",
        "43": "Preto 43 (E9). As pedras brancas da esquerda sofrem. Até aqui Intetsu jogou bem e considera-se que está na frente.",
        "45": "Preto 45 (D11) estende-se para cima pelo lado esquerdo, mantendo as brancas separadas e se fortalecendo.",
        "50": "Branco 50 (C16). Deixa por ora o canto inferior esquerdo e vai para o canto superior esquerdo.",
        "53": "Preto 53 (G17). As pretas entram no lado de cima para que Branco não amplie o canto superior esquerdo.",
        "58": "Branco 58 (C14) estende-se do canto superior esquerdo pelo lado e aproxima-se das pedras pretas da esquerda.",
        "60": "Branco 60 (G4) captura duas pedras pretas. O grupo branco do canto inferior esquerdo respira um pouco.",
        "62": "Branco 62 (J17). Também em cima os dois lados se enfrentam. Há pedras fracas por todo o tabuleiro: posição difícil.",
        "66": "Branco 66 (B14). Perto do canto superior esquerdo, Branco estabiliza suas pedras.",
        "68": "Branco 68 (B11). Os lances brancos seguintes, junto com o 80, ficaram famosos como os lances geniais de Jōwa. Eram tão notáveis que se dizia que fantasmas os tinham mostrado a ele.",
        "70": "Branco 70 (E12). Em vez de responder diretamente a Preto na esquerda, joga primeiro outro ponto-chave. Possibilidades escondidas permitem isso.",
        "72": "Branco 72 (R13). Vai para o lado direito para que a área preta de cima à direita não cresça.",
        "76": "Branco 76 (O14). Liga o lado direito ao centro e prepara-se para dividir as pedras pretas.",
        "80": "Branco 80 (Q10) forma um «triângulo vazio», figura normalmente considerada ruim. Porém, foi a base para dividir as pretas em duas e atacá-las. É o exemplo clássico de lance feio, mas excelente.",
        "83": "Preto 83 (R3) entra no canto branco inferior direito. Segue ali uma luta feroz de capturas.",
        "91": "Preto 91 (Q4) captura uma pedra branca. O canto inferior direito é importante para Preto.",
        "98": "Branco 98 (M4). Envolve as pedras pretas de baixo e não as deixa viver facilmente.",
        "106": "Branco 106 (S5) captura uma pedra preta. Branco mantém o canto inferior direito, e as pretas precisam fugir para fora.",
        "113": "Preto 113 (K6). As pedras pretas de baixo procuram vida saindo para o centro.",
        "120": "Branco 120 (N9) bloqueia as pedras pretas em fuga. No centro, tudo depende de quem enfraquece primeiro.",
        "128": "Branco 128 (L11) pressiona também de cima as pedras pretas do centro. Preto ainda não pode relaxar.",
        "138": "Branco 138 (K8) captura uma pedra e começa um ko no centro. Por uns 30 lances, captura-se e recaptura-se em K8 e L8.",
        "152": "Branco 152 (E11) é uma ameaça de ko. Durante o ko, Branco encontra por toda parte lances que Preto precisa responder.",
        "170": "Branco 170 (P15). O ko do centro acalmou e Branco vai para cima à direita, mirando um grande grupo preto que ainda não está totalmente vivo.",
        "178": "Branco 178 (J14) salta para o meio da área de cima para separar as pedras pretas à esquerda e à direita. O ataque de divisão preparado desde o lance 80 começa de verdade.",
        "193": "Preto 193 (J11) captura uma pedra branca. Preto luta para se ligar e viver.",
        "201": "Preto 201 (R14) captura uma pedra e começa um novo ko no lado direito, com capturas em R14 e R15.",
        "206": "Branco 206 (M13). Mesmo durante o ko, Branco aperta pouco a pouco as pedras pretas do centro.",
        "222": "Branco 222 (L14) captura uma pedra. As pretas de cima continuam divididas em duas, e salvar ambas fica difícil.",
        "230": "Branco 230 (C13) ataca também o ponto fraco preto no lado esquerdo. As pedras brancas já estão bem ligadas por todo o tabuleiro.",
        "237": "Com 237 (F12) e 239 (E13), Preto recupera pedras em cima à esquerda. Mesmo assim, a diferença total não diminui.",
        "246": "Após Branco 246 (L8), Intetsu abandonou. Conta-se que, ao recolher as pedras, ele tossiu sangue sobre o tabuleiro. Provavelmente já estava doente havia algum tempo, e morreu pouco depois. Para Jōwa, é tida como a maior vitória de sua vida."
      } },
    "deepblue1997": { "t": "A Vitória de Deep Blue", "w": "Deep Blue (computador da IBM)", "b": "Garry Kasparov", "ev": "Partida 6 da revanche contra o Deep Blue da IBM (match de seis partidas)", "d": "1997", "pl": "Estados Unidos (Nova York)", "lead": "O campeão mundial Kasparov contra Deep Blue, um computador de xadrez construído pela IBM, num match de seis partidas. Com o placar empatado depois de cinco partidas, a última terminou em apenas 19 lances. Foi a primeira vez que um computador venceu o campeão mundial num match completo de várias partidas.",
      c: {
        "0": "Nova York, 11 de maio de 1997. Kasparov tinha vencido o match do ano anterior. Desta vez o placar está 2½–2½ depois de cinco partidas. Deep Blue joga de brancas.",
        "1": "As brancas avançam duas casas o peão do rei.",
        "2": "Kasparov joga c6: a Defesa Caro-Kann.",
        "3": "As brancas levam o outro peão ao centro.",
        "4": "As pretas jogam d5 contra e4.",
        "5": "O cavalo defende e4.",
        "6": "As pretas capturam o peão de e4.",
        "7": "O cavalo recaptura.",
        "8": "As pretas põem um cavalo em d7 para depois levar o outro a f6.",
        "9": "O cavalo salta para g5: um plano agudo que mira f7 e e6.",
        "10": "As pretas levam o cavalo a f6.",
        "11": "Bispo em d3, de olho na ala do rei preto.",
        "12": "As pretas reforçam a defesa com e6.",
        "13": "O outro cavalo sai para f3.",
        "14": "As pretas jogam h6 para expulsar o cavalo de g5. Mas nessa posição já se conhecia um sacrifício de cavalo para as brancas. Dizem que foi uma escolha estranha para Kasparov.",
        "15": "O cavalo é entregue em e6! Diz-se que o Deep Blue tirou esse lance das aberturas que tinha guardado antes.",
        "16": "As pretas não capturam logo: levam a dama a e7. Na coluna e ela mira o cavalo de e6 e o rei branco atrás.",
        "17": "As brancas fazem o roque e põem o rei a salvo.",
        "18": "As pretas capturam o cavalo e ficam à frente em material.",
        "19": "Bispo em g6, xeque. Sem o peão de f7, a diagonal chega até o rei.",
        "20": "O rei vai a d8. As pretas não podem mais rocar e o rei fica perto do centro.",
        "21": "O outro bispo sai e mira as casas em volta do rei preto.",
        "22": "As pretas jogam b5 para abrir espaço na ala da dama para o rei e o bispo.",
        "23": "a4 ataca o peão de b5.",
        "24": "As pretas levam o bispo a b7.",
        "25": "Torre em e1. Na coluna e ela mira o peão de e6 e, atrás dele, a dama de e7.",
        "26": "O cavalo preto vai a d5 e ataca o bispo de f4.",
        "27": "O bispo recua para g3.",
        "28": "O rei preto vai a c8, um pouco mais seguro.",
        "29": "As brancas capturam o peão de b5.",
        "30": "As pretas recapturam.",
        "31": "Dama em d3, de olho no peão de b5 e na casa f5.",
        "32": "As pretas protegem b5 com o bispo.",
        "33": "Bispo em f5! Pode ser capturado de graça.",
        "34": "As pretas capturam com um peão. Mas assim some o peão da coluna e.",
        "35": "A torre captura a dama de e7. As brancas deram um cavalo, um bispo e uma torre, mas ganharam a dama.",
        "36": "As pretas recuperam a torre com o bispo.",
        "37": "c4! O peão ataca b5 e d5 ao mesmo tempo, e a defesa preta começa a desmoronar. Kasparov abandonou aqui, provavelmente achando que seu rei estava exposto demais para parar o ataque. Um computador tinha vencido um match contra o campeão mundial."
      } },
    "seigen1933": { "t": "A partida do 3-3, hoshi e tengen", "w": "Go Seigen", "b": "Hon’inbō Shūsai", "ev": "Partida comemorativa com o Meijin (mais de três meses)", "d": "1933–1934", "pl": "Japão (Tóquio)", "lead": "Aos 19 anos, Go Seigen (5-dan) enfrentou o Meijin Hon’inbō Shūsai. De pretas, abriu no 3-3, depois num ponto estrela e depois no centro exato (tengen), quebrando as regras da época e espantando todos. Com muitas interrupções, durou mais de três meses; Branco venceu por 2 pontos.",
      c: {
        "0": "1933. Naquele ano, Go Seigen e seu amigo Kitani Minoru difundiam um novo estilo de abertura, o «Shinfuseki». Todos queriam ver como ele o usaria contra o Meijin.",
        "1": "Preto 1 no 3-3 do canto superior direito (R17). Garante o canto num só lance, mas tem pouca influência para fora; na época ninguém o via como primeiro lance.",
        "3": "Preto 3 no ponto estrela do canto inferior esquerdo (D4). Ao contrário do 3-3, privilegia a expansão para fora.",
        "5": "Preto 5 vai ao centro exato do tabuleiro: o tengen (K10). Nem canto nem lado, mas o meio. Diante do Meijin, Go Seigen mostrou suas ideias novas de frente.",
        "6": "3-3, estrela, tengen: cada pedra preta tem seu papel — território no canto, alcance para fora e força central. Com 6 (Q16), Branco joga bem ao lado do 3-3 preto.",
        "9": "Preto 9 (P18). Estabiliza o canto superior direito de forma compacta e segura: estilo de território primeiro, típico do 3-3.",
        "11": "Preto 11 (K4) vai ao meio do lado inferior, logo abaixo do tengen. Junto com essa pedra, busca uma grande área embaixo.",
        "12": "Branco 12 (M3) entra logo no lado inferior para que Preto não construa uma grande estrutura. O Meijin não se apressa e desmonta os planos pretos um a um.",
        "13": "Preto 13 (D10), agora no meio do lado esquerdo. As pretas estão altas e juntas formam uma ampla estrutura.",
        "14": "Branco 14 (E16) fecha o canto superior esquerdo com uma segunda pedra. O Meijin não se deixa perturbar pelo estilo novo e garante o canto com calma.",
        "21": "Preto 21 (G10) liga o tengen à pedra do lado esquerdo, e a influência preta se espalha pelo centro.",
        "28": "Branco 28 (D3) entra por baixo da pedra estrela preta no canto inferior esquerdo e fica com o canto. Preto o cede em troca de força externa.",
        "30": "Branco 30 (Q12) estende-se pelo lado direito e põe também uma tampa sobre o canto 3-3 preto, reduzindo seu alcance.",
        "37": "Preto 37 (P15) captura uma pedra branca. Em cima à direita, os dois lados se chocam numa luta apertada.",
        "40": "Branco 40 (O10) sai do lado direito para o centro e aproxima-se da influência preta em torno do tengen.",
        "44": "Branco 44 (H17) ocupa um ponto no lado de cima para frear a expansão preta para cima.",
        "45": "Preto 45 (R7) começa a mexer na posição branca do canto inferior direito. Segue uma longa luta do lado direito até esse canto.",
        "59": "Preto 59 (R4) entra também no canto inferior direito e reduz o território branco.",
        "70": "Branco 70 (N6) avança do lado inferior para o centro para separar as pedras pretas de baixo à direita das do centro.",
        "79": "Preto 79 (L9) reforça o centro em torno do tengen. Até aqui a partida parece bem equilibrada.",
        "80": "Branco 80 (C6) sobe do canto inferior esquerdo pelo lado esquerdo, mirando as pedras pretas dali.",
        "98": "Branco 98 (A11) captura duas pedras pretas. Branco vive com elegância na borda esquerda, e o lado esquerdo preto fica menor que o previsto.",
        "101": "Preto 101 (S14) volta para cima à direita para reduzir a posição branca no lado direito.",
        "105": "Preto 105 (K17) ocupa o meio do lado de cima e começa a atacar as pedras brancas dali.",
        "117": "Preto 117 (F17) entra também perto do canto branco de cima à esquerda, e todo o lado de cima vira campo de batalha.",
        "124": "Branco 124 (K15) leva suas pedras de cima para o centro, cortando entre as pretas no caminho.",
        "135": "Preto 135 (E9) captura duas pedras brancas. Preto recupera um pouco no lado esquerdo.",
        "138": "Branco 138 (N18) garante território no lado de cima. No tabuleiro todo, a posição está muito apertada.",
        "153": "Preto 153 (K14). As pedras pretas do centro formam um caminho grosso ligando cima e baixo. A questão é como Branco vai romper essa espessura.",
        "159": "Preto 159 (F4) defende firme o canto inferior esquerdo. O próximo lance branco é o mais famoso da partida.",
        "160": "Branco 160 (H8) salta para uma brecha na espessura preta: um lance afiado com vários objetivos, a partir do qual Branco começa a entrar no centro preto. Correu o boato de que um aluno, e não Shūsai, o encontrou, mas isso nunca foi provado.",
        "161": "Preto 161 (J8) responde logo, mas Branco tem mais de um objetivo.",
        "162": "Branco 162 (K12) passa para a parte de cima do centro e ameaça as ligações pretas.",
        "172": "Branco 172 (F13) liga pedras do centro com as de cima à esquerda. Pouco a pouco, a espessura central preta deixa de virar território.",
        "178": "Branco 178 (N9) entra também na área preta à direita do centro.",
        "187": "Com 187 (M6) e 189 (L7), Preto responde capturando pedras brancas. Mesmo assim, Branco já chegou antes aos pontos importantes.",
        "198": "Branco 198 (E12) captura uma pedra. As pedras brancas de cima à esquerda ficam ligadas, e Branco está um pouco à frente.",
        "203": "Preto 203 (B3). Daqui em diante é o final: as fronteiras das bordas se fixam ponto a ponto.",
        "224": "Branco 224 (T10) captura uma pedra. Nem na borda direita Branco cede um ponto.",
        "233": "Preto 233 (L13) captura duas pedras brancas. Preto persegue até o fim.",
        "252": "A partida termina no lance 252: Branco vence por 2 pontos. Sem komi, Preto tinha a pequena vantagem de jogar primeiro, mas o Meijin ficou firme até o fim. Mesmo assim, o 3-3, a estrela e o tengen de Go Seigen causaram sensação e anunciaram uma nova era de aberturas."
      } },
    "century1956": { "t": "A Partida do Século", "w": "Donald Byrne", "b": "Bobby Fischer", "ev": "Terceiro torneio Troféu Rosenwald (Memorial Rosenwald)", "d": "1956", "pl": "Estados Unidos (Nova York)", "lead": "Bobby Fischer, com treze anos, vence Donald Byrne, um dos mestres mais fortes dos Estados Unidos. No lance 17 Fischer deixa sua dama ser capturada de graça, depois recupera peça por peça e, no final, suas peças pequenas caçam o rei branco. Fischer mais tarde se tornou campeão mundial.",
      c: {
        "0": "Nova York, 17 de outubro de 1956, uma partida de torneio. As pretas são de Fischer, com treze anos; as brancas de Byrne, um dos melhores jogadores americanos.",
        "1": "As brancas começam com um cavalo.",
        "4": "Fischer joga g6 para pôr o bispo na grande diagonal.",
        "8": "As pretas fazem o roque: primeiro, o rei em segurança.",
        "10": "As pretas jogam d5. Começa a luta pelo centro.",
        "15": "Com e4, as brancas têm dois peões lado a lado no centro.",
        "17": "Torre em d1, apoiando o peão de d4. As brancas ainda não fizeram o roque.",
        "18": "O cavalo vai a b6 e persegue a dama de c4.",
        "20": "Bispo em g4, pressionando o cavalo de f3.",
        "21": "O bispo branco vai a g5. O rei branco continua no centro.",
        "22": "Cavalo em a4! Ele salta para uma casa onde pode ser capturado. A ideia: se o cavalo de c3 sair, o peão de e4 fica sem defesa.",
        "23": "As brancas não capturam o cavalo e levam a dama a a3.",
        "26": "O cavalo preto captura o peão de e4. O centro branco desmorona.",
        "27": "O bispo branco captura o peão de e7 e ataca ao mesmo tempo a dama preta e a torre de f8.",
        "28": "Dama em b6! As pretas deixam a torre de f8 ir. Fischer conta com o rei branco ainda no centro.",
        "29": "As brancas não capturam a torre e desenvolvem o bispo.",
        "30": "O cavalo captura o peão de c3 e ataca a torre de d1.",
        "31": "Bispo em c5, atacando a dama preta em b6.",
        "32": "Xeque da torre pela coluna e!",
        "33": "O rei vai a f1. Agora as brancas nunca mais poderão rocar.",
        "34": "Bispo em e6! O lance mais famoso da partida: as pretas deixam a dama ser capturada de graça. Em troca, têm um plano para recuperar peça por peça.",
        "35": "As brancas capturam a dama preta.",
        "36": "Bispo em c4, xeque. Começa o contra-ataque preto.",
        "38": "O cavalo dá xeque em e2.",
        "40": "Quando o rei volta a f1, o cavalo se move e descobre um xeque do bispo de c4. No caminho, o cavalo pega o peão de d4.",
        "44": "O cavalo volta a c3, outro xeque descoberto, e agora ataca a torre de d1. Dar xeque de novo e de novo enquanto ganha peças se chama \"moinho\".",
        "46": "As pretas recuperam o bispo. O cavalo de c3 continua atacando a torre de d1.",
        "50": "O cavalo captura a torre de d1. Agora as pretas recuperaram mais do que a dama e estão claramente à frente.",
        "52": "A torre captura também o peão de a2.",
        "56": "As pretas trocam as torres. Quanto menos peças restam, melhor para quem tem mais.",
        "57": "A dama branca dá xeque.",
        "58": "As pretas bloqueiam com o bispo.",
        "64": "b5. O peão preto começa a avançar.",
        "68": "O rei vai a g7 e libera o bispo de f8.",
        "70": "Agora as peças pretas caçam o rei branco. Xeque com um bispo.",
        "72": "O cavalo dá xeque em g3.",
        "74": "Xeque com o outro bispo.",
        "76": "Bispo em b3, xeque.",
        "78": "O cavalo dá xeque em e2.",
        "80": "O cavalo dá xeque em c3. O rei é perseguido de um lado para o outro.",
        "82": "Torre em c2: xeque-mate! Torre, dois bispos e cavalo trabalham juntos. Um menino de treze anos mostrou como muitas peças podem jogar como um time."
      } },
    "oshiro1849": { "t": "A primeira partida do castelo de Shūsaku", "w": "Hon’inbō Shūsaku", "b": "Yasui Sanchi IX", "ev": "Partida do castelo (a partida anual no castelo de Edo)", "d": "1849", "pl": "Japão (Edo)", "lead": "As partidas do castelo eram o grande evento anual em que os jogadores das casas oficiais de go jogavam no castelo do xógum. Aos 20 anos, Shūsaku estreou nesse ano e venceu de pretas por 11 pontos: o início de um recorde perfeito de 19 vitórias em 19 partidas.",
      c: {
        "0": "1849. No ano anterior, Shūsaku fora nomeado herdeiro da casa Hon’inbō, e agora joga sua primeira partida do castelo. Diz-se que essas partidas costumavam ser jogadas antes em outro lugar e apenas reproduzidas no castelo.",
        "1": "Preto 1 no 3-4 do canto superior direito (R16). Como sempre, Shūsaku começa com um tranquilo 3-4.",
        "4": "Branco 4 (C15) aproxima-se da pedra preta de D17, em cima à esquerda. Ali começa cedo uma luta.",
        "5": "Preto 5 (C11) faz uma pinça por baixo na pedra branca que se aproximou, para que Branco não se instale fácil na esquerda.",
        "12": "Branco 12 (C17). Branco fica com o canto superior esquerdo e Preto ganha pedras voltadas para fora: uma troca justa.",
        "13": "Preto 13 (J17) aproveita as pedras externas e se estende por cima.",
        "15": "Preto 15 (C5) ocupa o último canto livre, embaixo à esquerda. Os quatro estão ocupados.",
        "16": "Branco 16 (E4) aproxima-se logo dessa pedra preta, e há luta também embaixo à esquerda.",
        "19": "Preto 19 (D2) garante com firmeza o canto inferior esquerdo: escolha sólida, bem ao estilo de Shūsaku.",
        "23": "Preto 23 (E5) sai entre as pedras brancas e reforça seu grupo embaixo à esquerda.",
        "29": "Preto 29 (F11) reforça as pedras pretas da esquerda e ao mesmo tempo olha para o centro.",
        "30": "Branco 30 (H4) estende-se por baixo, pressiona o grupo preto da esquerda e constrói sua área.",
        "31": "Preto 31 (O3) aproxima-se do canto branco embaixo à direita.",
        "33": "Preto 33 (R3) encosta na pedra branca do canto. Daqui em diante Preto constrói por fora e Branco avança pela terceira linha da borda.",
        "43": "Preto 43 (Q8). Uma grossa parede preta percorre agora o lado direito. Branco ficou com território no canto e na borda; Preto, com força externa.",
        "44": "Branco 44 (L17) entra entre as pedras pretas do lado de cima para que a área preta não cresça demais.",
        "50": "Branco 50 (R18) entra por baixo do canto preto de cima à direita, mirando o território.",
        "51": "Preto 51 (P13). Com a parede atrás, Preto prepara uma grande área do lado direito ao centro.",
        "52": "Branco 52 (D10) entra entre as pedras pretas do lado esquerdo. Ali as pedras se embaralham.",
        "63": "Preto 63 (B10) joga na borda esquerda para que as pedras brancas não tenham base ali.",
        "65": "Preto 65 (G3) entra também na área branca de baixo e reduz o território branco.",
        "73": "Preto 73 (K17) reforça suas pedras de cima e pressiona a pedra branca do lance 44.",
        "76": "Branco 76 (P11) salta para dentro da área preta do lado direito. Se essa pedra vive ou morre muda muito a contagem.",
        "77": "Preto 77 (Q11) responde do lado da sua parede e empurra Branco para o centro: defesa calma que também ataca, típica de Shūsaku.",
        "80": "Branco 80 (N10) foge para o centro tentando escapar da perseguição preta.",
        "85": "Preto 85 (N12) continua atacando enquanto amplia seu território em cima e à direita. Ganhar atacando: jogo habilidoso.",
        "91": "Preto 91 (J7) joga acima das pedras brancas de baixo e tampa também do centro a área branca.",
        "100": "Branco 100 (S17) tenta algo no canto superior direito para reduzir o território preto.",
        "119": "Preto 119 (R17) defende firme o canto superior direito e segura a tentativa branca.",
        "122": "Branco 122 (G6) contorna por fora as pedras pretas de baixo à esquerda para cortá-las do centro preto.",
        "131": "Preto 131 (M5) crava uma cunha na área branca, no meio do lado inferior.",
        "140": "Branco 140 (B4) tenta algo no canto preto embaixo à esquerda. Começa uma luta apertada de capturas na borda esquerda.",
        "156": "Branco 156 (A8) captura duas pedras pretas. A luta na borda esquerda se acalma após pequenos ganhos dos dois lados.",
        "158": "Branco 158 (L10). Branco ainda tem pedras no centro e tenta reduzir o território central preto.",
        "162": "Branco 162 (O12) captura uma pedra preta. Mesmo assim, a área preta da direita continua grande.",
        "172": "Branco 172 (K18). Daqui em diante é o final, começando pela fronteira do lado de cima.",
        "186": "Branco 186 (T16) corta território preto na borda superior direita. No final, ambos jogam primeiro os maiores pontos.",
        "205": "Preto 205 (Q18) fecha a parte direita do lado de cima e fixa ali o território.",
        "223": "Preto 223 (P10) fixa a fronteira entre o território preto da direita e as pedras brancas que fugiram para o centro.",
        "233": "Preto 233 (Q9) captura uma pedra branca. O território preto da direita está quase todo seguro.",
        "239": "Preto 239 (A6) captura uma pedra e surge um ko na borda esquerda. A luta ponto a ponto segue até o fim.",
        "260": "Branco 260 (T6) captura uma pedra e forma outro ko na borda inferior direita. Preto recaptura em 263 (T5).",
        "267": "A partida termina no lance 267: Preto vence por 11 pontos. Sem aventuras: Shūsaku atacou e deixou seu território crescer naturalmente, uma vitória bem dele. Foi a primeira de suas 19 vitórias seguidas no castelo."
      } },
    "shilin": { "t": "A partida do Shilin Guangji", "w": "Vermelhas (nome não registrado)", "b": "Pretas (nome não registrado)", "ev": "Enciclopédia do dia a dia Shilin Guangji: «partida vencida cedendo a saída, com canhões do mesmo lado»", "d": "Século XIII", "pl": "China (Song–Yuan)", "lead": "Este registro vem do Shilin Guangji, uma enciclopédia do dia a dia reunida por Chen Yuanjing entre o fim da dinastia Song e o início da Yuan. É considerado um dos registros completos de xiangqi mais antigos que existem. É uma partida-modelo em que o lado mais forte deixa o outro começar, e em apenas nove lances o cavalo preto prende a carruagem vermelha.",
      c: {
        "0": "Este registro tem mais de 700 anos, da época entre as dinastias Song e Yuan. Ele está no capítulo de jogos da enciclopédia Shilin Guangji e é considerado uma das partidas completas de xiangqi mais antigas que ainda temos. Os nomes dos jogadores não foram registrados. O título diz que o jogador forte «cedeu a saída» ao mais fraco, então é uma lição que mostra como as Vermelhas, que jogam primeiro, perdem. As Vermelhas estão embaixo e começam.",
        "1": "As Vermelhas levam o canhão direito para a coluna central. É o Canhão Central, mirando direto o general preto, e ainda hoje uma das aberturas mais fortes. Vemos que ela já era jogada há 700 anos.",
        "2": "As Pretas também levam um canhão ao centro, e os dois canhões ficam frente a frente. Quando os dois lados movem o canhão do mesmo lado, chama-se «canhões na mesma direção». O duelo de canhões é popular há séculos.",
        "3": "As Vermelhas tiram um cavalo para proteger o soldado central. Esse soldado está atacado pelo canhão preto e precisa de defesa. O cavalo também se prepara para avançar.",
        "4": "As Pretas fazem o mesmo e protegem o soldado central com um cavalo. Os dois lados primeiro constroem uma base firme.",
        "5": "As Vermelhas movem a carruagem direita um passo para o lado, para uma coluna aberta. A carruagem é a peça mais forte do tabuleiro, então é bom colocá-la para trabalhar cedo.",
        "6": "As Pretas tiram o outro cavalo e deixam as carruagens em casa por enquanto. A ideia é avançar as peças primeiro. Mas uma carruagem que sai tarde pode ser difícil de usar no ataque depois.",
        "7": "A carruagem vermelha cruza o rio de uma vez e entra no campo preto. Quer ameaçar peças pretas, mas as outras peças vermelhas ainda estão em casa, então o ataque é um pouco apressado. Também era possível tirar antes o cavalo ou a carruagem da esquerda.",
        "8": "As Pretas avançam um passo o soldado da coluna 3. Isso abre caminho para o cavalo saltar à frente mais tarde. As Pretas quase convidam a carruagem vermelha a vir.",
        "9": "A carruagem vermelha captura um soldado e agora mira o cavalo preto atrás dele. Ganhar uma peça e ameaçar outra parece ótimo. Mas a carruagem avançou demais e não tem amigos por perto. Uma carruagem sozinha no campo inimigo é fácil de perseguir.",
        "10": "O cavalo preto salta à frente. Foge da carruagem e ao mesmo tempo se aproxima do campo vermelho: duas tarefas num lance. Este cavalo será o protagonista da partida.",
        "11": "As Vermelhas recuam a carruagem um passo para atacar o cavalo pelo lado. A carruagem captura de longe, então o cavalo não pode descansar. Ainda assim, esse lance não ajuda a desenvolver outras peças vermelhas.",
        "12": "O cavalo preto avança mais e cruza o rio para o campo vermelho. Cada vez que foge da carruagem, chega mais perto do general vermelho.",
        "13": "As Vermelhas avançam um soldado para abrir caminho ao próprio cavalo. A ideia é tirá-lo e trocá-lo pelo cavalo preto. Mas isso dá tempo às Pretas para ir ainda mais longe.",
        "14": "As Pretas sobem um elefante e atacam a carruagem vermelha. Usar uma peça de defesa para expulsar a carruagem inimiga é muito eficiente. As Vermelhas precisam mover a carruagem de novo, e as Pretas ganham mais um tempo.",
        "15": "A carruagem vermelha desliza de lado e captura outro soldado. As Vermelhas têm dois soldados a mais, mas este é o lance que perde. A carruagem fica longe do seu general e não consegue voltar para defender. Era preciso se proteger do cavalo, por exemplo trazendo a carruagem de volta.",
        "16": "O cavalo preto entra mais fundo e ataca a carruagem vermelha. E tem mais: se saltar outra vez, dará xeque ao general vermelho e ao mesmo tempo atacará a carruagem do canto vermelho. Um só cavalo criou duas ameaças de uma vez.",
        "17": "As Vermelhas perseguem o cavalo com a carruagem. Mas ele já não pode ser parado. Ao redor do general vermelho não sobrou ninguém para ajudar.",
        "18": "O cavalo salta com xeque! Ele também ataca a carruagem do canto vermelho, então quando o general sair, a carruagem será perdida. Só nove lances, mas a partida ensina o que acontece com uma carruagem que avança sozinha e por que as peças devem lutar juntas. Há 700 anos os jogadores já pensavam nas mesmas coisas, no mesmo tabuleiro."
      } },
    "qima13": { "t": "O sacrifício do cavalo em treze lances (Juzhongmi)", "w": "Vermelhas (nome não registrado)", "b": "Pretas (nome não registrado)", "ev": "Juzhongmi, volume 1, partida 1", "d": "1632 (publicação)", "pl": "China (Ming)", "lead": "É a primeiríssima partida do Juzhongmi («O segredo da tangerina»), livro de xiangqi publicado por Zhu Jinzhen, da dinastia Ming, em 1632. As Vermelhas deixam as Pretas capturarem um cavalo de graça, entram no ataque enquanto isso e dão mate em treze lances. Com o nome de «sacrifício do cavalo em treze lances», ainda é querida quase 400 anos depois.",
      c: {
        "0": "É a partida 1 do Juzhongmi, livro impresso em 1632, perto do fim da dinastia Ming. Junto com o posterior Manual da Flor de Ameixeira, é chamado de um dos dois grandes clássicos do xiangqi. Não é uma partida real, mas um modelo escrito para ensinar um plano, por isso não há nomes de jogadores. As Vermelhas estão embaixo e começam, e tudo acaba em apenas treze lances.",
        "1": "As Vermelhas levam o canhão direito ao centro. É o Canhão Central, encarando o general preto. O Juzhongmi é famoso por estudar como atacar com essa abertura.",
        "2": "As Pretas também levam ao centro o canhão do mesmo lado. São os «canhões na mesma direção», que se chocam de frente. Cada lado mira o soldado central do outro.",
        "3": "As Vermelhas tiram um cavalo para proteger o soldado central. Ele defende o soldado mirado pelo canhão preto, e o cavalo começa a trabalhar.",
        "4": "As Pretas também protegem o soldado central com um cavalo. Até aqui os dois lados têm a mesma forma.",
        "5": "As Vermelhas avançam a carruagem direita só um passo. Assim, no próximo lance, ela poderá correr de lado. Uma carruagem que se move de lado assim chama-se «carruagem horizontal», e pode ir rápido para qualquer ala.",
        "6": "As Pretas movem a carruagem um passo para o lado para poder subir reto pelo tabuleiro. É uma «carruagem reta». Carruagem horizontal contra carruagem reta: dois jeitos diferentes de usar a carruagem, frente a frente.",
        "7": "A carruagem horizontal vermelha vai para uma coluna à esquerda. Essa coluna passa ao lado do conselheiro preto, onde a defesa é fraca. As Vermelhas se preparam para entrar por ali.",
        "8": "A carruagem reta preta cruza o rio e entra fundo no campo vermelho. As Pretas querem responder com seu próprio ataque. Mas é um lance que se apressa em atacar antes de defender.",
        "9": "A carruagem vermelha entra até o fundo do campo preto. Ela para no «olho» do elefante, o ponto por onde o elefante precisa passar, então o elefante preto não pode se mover. Grudada no conselheiro, já está bem perto do general.",
        "10": "As Pretas tiram o outro cavalo para a borda. Parte da ideia é impedir que a carruagem vermelha entre pelo lado.",
        "11": "Aqui está o sacrifício do cavalo! As Vermelhas sobem a outra carruagem um passo. Isso deixa o cavalo do canto esquerdo sem defensor, e o canhão preto pode capturá-lo de graça. Mas, em troca de um cavalo, as Vermelhas ganham tempo para colocar rápido as duas carruagens no ataque.",
        "12": "O canhão preto captura o cavalo vermelho. Parece que as Pretas ganharam uma peça. Mas esse canhão fica longe de casa e não pode ajudar na defesa. Diz-se que aqui era melhor reforçar a defesa subindo um conselheiro em vez de capturar.",
        "13": "O canhão vermelho avança. Usando o canhão central preto como «anteparo» para saltar, ele agora mira o cavalo preto atrás. O canhão é uma peça curiosa que captura saltando exatamente uma peça.",
        "14": "As Pretas recuam o cavalo para fugir. Mas esse cavalo era a peça importante que protegia o soldado central. Ao fugir, ele abre um buraco no centro. As Pretas tinham outras defesas, mas esta foi a pior escolha.",
        "15": "O canhão vermelho toma o soldado central — xeque! Sem o cavalo preto, o centro estava escancarado. Daqui em diante o ataque vermelho avança depressa.",
        "16": "As Pretas sobem um conselheiro para tapar a frente do general. É a única boa maneira de parar o xeque.",
        "17": "A segunda carruagem vermelha chega à mesma coluna. Duas carruagens alinhadas numa coluna são fortíssimas. O plano é invadir o fundo do campo preto.",
        "18": "O general preto sai para o lado. Senão ficaria encarado de frente pelas duas carruagens vermelhas na mesma coluna.",
        "19": "A carruagem vermelha da frente toma o conselheiro preto — xeque! O outro conselheiro a capturará na hora, mas isso faz parte do plano. As Vermelhas entregam uma carruagem para destruir os guardas do general preto. Que lance corajoso!",
        "20": "As Pretas tomam a carruagem com o conselheiro. Em peças, as Pretas estão muito à frente. Mas a casa do general ficou ainda mais vazia.",
        "21": "A última carruagem vermelha vai para a coluna do general — xeque de novo. O general preto quase não tem mais peças para protegê-lo.",
        "22": "As Pretas colocam um canhão na frente do general para tapar o xeque. Pôr uma peça no meio assim chama-se interpor.",
        "23": "A carruagem vermelha toma esse canhão — xeque outra vez. Ela continua capturando peças pretas enquanto encurrala o general.",
        "24": "O general preto só pode voltar ao centro. Todos os outros pontos estão controlados por peças vermelhas.",
        "25": "Por fim o canhão vermelho se coloca no centro, dois canhões numa coluna — xeque. O canhão da frente serve de anteparo e o de trás atinge o general: um mate de «canhão duplo». O general preto não tem para onde ir, e as Vermelhas vencem. Entregando só um cavalo, as Vermelhas venceram em treze lances. Há 400 anos esta partida ensina que o tempo e a atividade das peças podem valer mais do que a quantidade delas."
      } }
  },
  "de": {
    ui: {"lead":"Berühmte Partien, Zug für Zug. Verfolge große Partien auf dem Brett, während Musowl jeden Zug erklärt.","all":"Alle","k_chess":"Schach","k_shogi":"Shogi","k_go":"Go","k_xiangqi":"Xiangqi","side_r":"Rot","res_r":"Rot gewinnt","back":"Zurück zu den großen Partien","start":"Anfang","prev":"Einen Zug zurück","next":"Einen Zug vor","end":"Ende","play":"Abspielen","pause":"Anhalten","moves":"Züge","move":"Zug {n}","startpos":"Ausgangsstellung","nextnote":"Nächste Erklärung (Zug {n})","quiet":"Zu diesem Zug gibt es keine Erklärung.","guide":"Musowl","keys":"← → Zug für Zug","result":"Ergebnis","r_event":"Partie","r_date":"Jahr","r_place":"Ort","side_w":"Weiß","side_b":"Schwarz","side_s":"Sente","side_g":"Gote","side_B":"Schwarz","side_W":"Weiß","res_w":"Weiß gewinnt","res_b":"Schwarz gewinnt","res_d":"Remis","res_s":"Sente gewinnt","res_g":"Gote gewinnt","credit":"Die Züge sind die öffentlich bekannte Aufzeichnung jeder Partie. Die Erklärungen stammen von Musowl aus dem Museum."},
    "opera": { "t": "Die Opernpartie", "w": "Paul Morphy", "b": "Herzog Karl II. von Braunschweig und Graf Isouard", "ev": "Gespielt in einer Loge der Pariser Oper (die beiden Verbündeten berieten sich)", "d": "1858", "pl": "Frankreich (Paris)", "lead": "Der junge amerikanische Meister gegen zwei Adlige, mitten in einer Opernaufführung: siebzehn Züge. Die Figuren schnell entwickeln, sie ohne Zögern opfern und mit ganz wenigen gewinnen. Keine Partie steht in mehr Schachbüchern.",
      c: {
        "0": "Paris, 1858. Der einundzwanzigjährige Amerikaner Paul Morphy besiegte einen starken Spieler Europas nach dem anderen. An diesem Abend nahmen in einer Loge der Oper der Herzog von Braunschweig und Graf Isouard gemeinsam Schwarz und forderten ihn heraus, wobei sie jeden Zug berieten. Man sagt, Morphy wollte schnell fertig werden, um die Bühne zu sehen. Diese siebzehn Züge stecken voller Grundlagen: Figuren schnell entwickeln und den König in Sicherheit bringen.",
        "1": "Weiß zieht den Königsbauern zwei Felder vor. Er beobachtet d5 und e5 im Zentrum und öffnet Läufer und Dame den Weg.",
        "2": "Schwarz spielt ebenfalls e5. Die Bauern stehen sich im Zentrum gegenüber, und der weiße Bauer kann nicht weiter.",
        "3": "Der Springer geht nach f3 und greift den Bauern e5 an. Ein guter Zug: Er entwickelt eine Figur und zwingt den Gegner, an Verteidigung zu denken.",
        "4": "Schwarz deckt e5 mit d6. Das ist die Philidor-Verteidigung. Solide, aber der Läufer f8 hat es etwas enger.",
        "5": "Weiß spielt d4: ein weiterer Bauer ins Zentrum, gegen e5. Schwarz muss sich entscheiden, ob es schlägt oder deckt.",
        "6": "Der schwarze Läufer geht nach g4. Er drückt auf den Springer f3, der mit der weißen Dame d1 auf einer Linie steht. Zieht der Springer, fällt die Dame – also kann er nicht nach e5.",
        "7": "Weiß schlägt mit dem Bauern auf e5. Nähme Schwarz sofort mit dem d6-Bauern zurück, würde Weiß die Damen tauschen und dann mit dem Springer den Bauern e5 schnappen. Deshalb will Schwarz zuerst den Springer f3 loswerden.",
        "8": "Schwarz schlägt den Springer mit dem Läufer. Jetzt kann es e5 sicher zurückgewinnen. Doch den gerade entwickelten Läufer gegen den Springer zu geben, bringt Schwarz in Entwicklungsrückstand.",
        "9": "Weiß schlägt mit der Dame zurück, die schon nahe der Mitte arbeitet, während Schwarz kaum Figuren entwickelt hat.",
        "10": "Schwarz schlägt mit einem Bauern zurück, das Material ist gleich. Aber bei den entwickelten Figuren liegt Weiß vorn.",
        "11": "Läufer nach c4. Zusammen mit der Dame f3 zielt er auf f7. Nur der König deckt f7, ein schwaches Feld: Es zu schlagen wäre Matt.",
        "12": "Schwarz stellt den Springer nach f6 und sperrt die f-Linie. Ohne diesen Zug wäre Dame schlägt f7 matt. Verteidigen und dabei entwickeln ist die richtige Antwort.",
        "13": "Die Dame schwenkt nach b3 und greift f7 und b7 zugleich an. Ein Zug mit zwei Drohungen ist stark, weil der Gegner nicht beide abwehren kann.",
        "14": "Schwarz stellt die Dame nach e7, deckt f7 und gibt b7 auf. Doch nun versperrt die Dame dem Läufer f8 den Weg.",
        "15": "Morphy nimmt den Bauern b7 nicht, sondern entwickelt einen Springer. Nach dem Schlagen stünde die Dame weit weg. Schnelle Entwicklung statt Bauerngewinn – typisch Morphy.",
        "16": "Schwarz spielt c6: Es kontrolliert d5 und b5 und öffnet der Dame den Weg nach b6.",
        "17": "Läufer nach g5 fesselt den Springer f6. Zieht der Springer, kann die Dame e7 dahinter geschlagen werden. Die schwarzen Figuren können sich immer schwerer bewegen.",
        "18": "Schwarz spielt b5, um den Läufer c4 zu vertreiben. Es gewinnt Raum am Damenflügel, öffnet aber eine Lücke für die weißen Figuren.",
        "19": "Der Springer opfert sich und schlägt auf b5! Statt den Läufer zurückzuziehen, greift Morphy weiter an. Mit dem schwarzen König noch in der Mitte ist das sehr gefährlich für Schwarz.",
        "20": "Schwarz schlägt den Springer und hat einen Springer mehr. Doch der König steht noch auf e8, und die weißen Figuren rücken weiter heran.",
        "21": "Läufer nach b5, Schach! Der schwarze König steckt immer noch in der Mitte. Weiß hat zwei Bauern für den Springer und stürmt direkt auf den König zu.",
        "22": "Schwarz stellt den Springer nach d7. Doch dieser Springer ist gefesselt: Zieht er, steht der schwarze König im Schach. Jetzt zielt Weiß auf d7.",
        "23": "Weiß rochiert lang. Der König ist sicher, und zugleich kommt der Turm nach d1 und zielt auf d7. Ein Zug, der verteidigt und angreift: großartig.",
        "24": "Schwarz stellt den Turm nach d8, um d7 zu decken. Schwarz kann immer noch nicht rochieren, und Turm h8 und Läufer f8 tun nichts.",
        "25": "Der Turm opfert sich und schlägt auf d7! Weiß gibt einen Turm, um einen schwarzen Verteidiger zu beseitigen.",
        "26": "Schwarz schlägt mit dem Turm zurück. Jetzt ist auch dieser Turm auf d7 gefesselt: Zieht er, gibt der Läufer b5 dem schwarzen König Schach.",
        "27": "Der andere Turm kommt nach d1 und greift d7 erneut an. Nun greifen mehr weiße Figuren d7 an, als schwarze es verteidigen.",
        "28": "Die schwarze Dame geht nach e6 und bietet den Damentausch an, um die Dame b3 zu vertreiben und d7 zu helfen. Doch es ist zu spät.",
        "29": "Der Läufer schlägt mit Schach auf d7. Weiß beseitigt die schwarzen Verteidiger einen nach dem anderen.",
        "30": "Schwarz schlägt mit dem Springer zurück. Da der Springer f6 verlassen hat, ist die Diagonale vom Läufer g5 bis d8 frei. Diese Diagonale wird ganz am Ende wichtig.",
        "31": "Die Dame opfert sich mit Schach auf b8! Das ist der berühmteste Zug der Partie. Schwarz muss mit dem Springer schlagen, und wenn er d7 verlässt, öffnet sich die d-Linie.",
        "32": "Schwarz schlägt mit dem Springer. Nun deckt keine schwarze Figur mehr d8.",
        "33": "Turm nach d8, Schachmatt! Der Läufer g5 stützt d8, und der schwarze König ist von seinen eigenen Figuren eingesperrt. Weiß gab Dame, Turm und Läufer her und gewann am Ende mit nur einem Turm und einem Läufer. Schnell entwickeln, den König in Sicherheit bringen und angreifen, solange der gegnerische König in der Mitte steht: Diese berühmte Partie vereint all diese wichtigen Ideen."
      } },
    "reti1910": { "t": "Rétis Matt", "w": "Richard Réti", "b": "Savielly Tartakower", "ev": "Eine freie Partie (kein Turnier)", "d": "1910", "pl": "Österreich (Wien)", "lead": "Zwei spätere Großmeister, eine freie Partie in Wien, elf Züge. Weiß gibt die Dame her und beendet die Partie mit einem Doppelschach: zwei Figuren geben gleichzeitig Schach. Dieses Mattbild ist nach Weiß benannt: Rétis Matt.",
      c: {
        "0": "Wien, 1910. Weiß ist der zwanzigjährige Richard Réti, Schwarz Savielly Tartakower. Beide wurden später Weltklassespieler und sind dafür bekannt, dem Schach neue Ideen gebracht zu haben. Es war keine Turnierpartie, sondern eine freie Partie um einen kleinen Einsatz. Sie ist kurz, zeigt aber deutlich, warum man den König früh in Sicherheit bringen sollte.",
        "1": "Weiß zieht den Königsbauern zwei Felder vor. Wer die Mitte besetzt, kann die Figuren dahinter leichter entwickeln. Läufer und Dame haben jetzt freie Bahn.",
        "2": "Schwarz spielt c6. Statt sofort ins Zentrum zu gehen, bereitet Schwarz d5 vor, um den Bauern e4 anzugreifen. Diese solide Eröffnung heißt Caro-Kann-Verteidigung.",
        "3": "Weiß stellt auch den anderen Bauern nach d4. Zwei Bauern nebeneinander im Zentrum: Weiß hat viel Raum. Schwarz wird versuchen, sie aufzubrechen.",
        "4": "Wie geplant d5. Der Bauer fordert e4 heraus: „Ich kann dich schlagen.“ Weiß muss entscheiden, ob es deckt, vorrückt oder tauscht.",
        "5": "Weiß entwickelt einen Springer und deckt e4. Figur entwickeln und verteidigen in einem Zug – keine Zeit verloren.",
        "6": "Schwarz schlägt den Bauern e4. Durch den Tausch der Zentrumsbauern wird das weiße Zentrum kleiner.",
        "7": "Weiß schlägt mit dem Springer zurück, der nun mitten auf dem Brett steht. Ein Springer im Zentrum erreicht viele Felder und ist sehr stark.",
        "8": "Schwarz entwickelt einen Springer gegenüber dem auf e4. Hier wird oft der Läufer nach f5 gespielt, aber Schwarz bietet den Springertausch an.",
        "9": "Die Dame kommt früh nach d3 und deckt den Springer e4. Normalerweise holt man die Dame nicht so früh heraus, doch Weiß hat einen Plan. Merk dir: Diese Dame steht auf der d-Linie, vor dem schwarzen König.",
        "10": "Schwarz spielt e5 und bietet einen Bauern an, um Linien für Läufer und Dame zu öffnen. Ein aktiver Zug, der den Kampf im Zentrum eröffnet.",
        "11": "Weiß schlägt den Bauern e5. Weiß nimmt das Geschenk an, doch dadurch bekommt die schwarze Dame mehr Freiheit.",
        "12": "Schach! Die schwarze Dame auf a5 zielt schräg auf den König e1. Zugleich will sie den Bauern e5 zurückgewinnen: zwei Aufgaben in einem Zug. Weiß muss dazwischenziehen.",
        "13": "Weiß stellt den Läufer nach d2. Die Dame könnte den Läufer schlagen, aber die weiße Dame deckt ihn gut.",
        "14": "Schwarz holt den Bauern zurück, das Material ist wieder gleich. Und diese Dame blickt auf der e-Linie auf den Springer e4 und den König dahinter. Zieht der Springer, steht der König im Schach – der Springer ist gefesselt. Schwarz scheint ihn gleich zu gewinnen.",
        "15": "Weiß rochiert lang. Der König verlässt die e-Linie, und der Springer ist wieder frei. Gleichzeitig kommt ein Turm nach d1: Turm d1, Dame d3 und das Feld d8 neben dem schwarzen König stehen auf einer Linie. Das ist die weiße Falle.",
        "16": "Schwarz schlägt den Springer e4 und scheint eine Figur zu gewinnen. Aber der schwarze König steht noch auf e8 und hat nicht rochiert. Die weißen Figuren stehen auf der d-Linie, und der schwarze König ist schutzlos. Dieser Zug, der die Partie verliert, ist der Wendepunkt.",
        "17": "Dame nach d8, Schach! Weiß verschenkt seine stärkste Figur. Die einzige schwarze Figur, die sie schlagen kann, ist der König. So lockt Weiß den König auf das gefährliche Feld d8.",
        "18": "Schwarz muss mit dem König schlagen; anders lässt sich das Schach nicht abwehren. Der König steht auf d8, und dahinter wartet der Turm d1.",
        "19": "Der Läufer zieht mit Schach von d2 nach g5 und öffnet zugleich den Weg für den Turm d1, der auf der d-Linie ebenfalls Schach gibt. Zwei Figuren geben gleichzeitig Schach: ein Doppelschach. Man kann es weder durch Schlagen einer Figur noch durch Dazwischenziehen abwehren – der König muss fliehen.",
        "20": "Der König flieht nach c7. Auf e8 käme der Turm nach d8 und setzte matt. Wohin der König auch geht, Weiß hat den Schlusszug bereit.",
        "21": "Läufer nach d8: Schachmatt auf der Diagonale gegen den König c7! Der Läufer ist vom Turm d1 gedeckt, der König kann ihn nicht schlagen. Felder wie b8, c8, b7 und c6 sind von schwarzen Figuren besetzt, und der Turm überwacht d6 und d7. In nur elf Zügen gab Weiß die Dame her und gewann mit zwei kleinen Figuren. Die Partie zeigt, wie gefährlich es ist, Material zu schnappen, bevor man rochiert hat. Manche Quellen sagen, Schwarz habe einen Zug früher aufgegeben."
      } },
    "immortal": { "t": "Die Unsterbliche Partie", "w": "Adolf Anderssen", "b": "Lionel Kieseritzky", "ev": "Freie Partie in einer Pause des Turniers London 1851", "d": "1851", "pl": "Vereinigtes Königreich (London)", "lead": "London, während des ersten internationalen Schachturniers: eine Partie in einer Pause. Weiß gibt einen Läufer, beide Türme und zuletzt die Dame her und setzt mit den drei übrigen Leichtfiguren matt. Schwarz soll vor dem Ende aufgegeben haben; die letzten Züge wären dann der Schluss, den Weiß zeigte.",
      c: {
        "0": "London, 1851. In einer Turnierpause spielen der Deutsche Anderssen (Weiß) und Kieseritzky, ein Star aus Paris (Schwarz), eine freie Partie.",
        "1": "Weiß zieht den Königsbauern zwei Felder vor.",
        "2": "Schwarz macht dasselbe.",
        "3": "f4! Weiß bietet einen Bauern an: das Königsgambit. Der schwarze Bauer e5 soll aus dem Zentrum gelockt werden.",
        "4": "Schwarz nimmt den Bauern.",
        "5": "Der Läufer kommt heraus und zielt auf f7 neben dem schwarzen König.",
        "6": "Schach! Ohne den weißen f-Bauern ist die Diagonale von h4 nach e1 offen.",
        "7": "Der König tritt zur Seite. Jetzt kann Weiß nie mehr rochieren.",
        "8": "Auch Schwarz bietet einen Bauern an, um den Läufer nach b5 zu locken.",
        "9": "Weiß nimmt.",
        "10": "Ein Springer kommt heraus und greift den Bauern e4 an.",
        "11": "Weiß entwickelt einen Springer und vertreibt die Dame von h4.",
        "12": "Die Dame zieht sich nach h6 zurück.",
        "13": "d3 deckt e4 und öffnet dem Läufer c1 den Weg.",
        "14": "Springer nach h5. Der Plan: nach g3 springen, Schach geben und den Turm h1 angreifen.",
        "15": "Der weiße Springer geht nach h4, bereit, nach f5 zu springen und die schwarze Dame zu stören.",
        "16": "Die schwarze Dame geht nach g5 und greift den Springer h4 an.",
        "17": "Springer nach f5, ein schönes Feld, vom Bauern e4 gedeckt. Er zielt auch auf den Bauern g7.",
        "18": "c6 versucht, den Läufer b5 zu vertreiben.",
        "19": "Weiß rettet den Läufer nicht, sondern jagt mit g4 den Springer h5.",
        "20": "Der Springer geht zurück nach f6.",
        "21": "Turm nach g1, er deckt den Bauern g4. Den Läufer b5 lässt Weiß einfach stehen. Wie mutig!",
        "22": "Schwarz schlägt den Läufer und hat eine ganze Figur mehr.",
        "23": "Der h-Bauer beginnt, die schwarze Dame zu jagen.",
        "24": "Die Dame geht nach g6.",
        "25": "h5 jagt die Dame wieder.",
        "26": "Die Dame kann nur zurück nach g5. Sie hat immer weniger Felder.",
        "27": "Die weiße Dame geht nach f3. Schlägt danach der Läufer auf f4, könnte die schwarze Dame gefangen sein.",
        "28": "Schwarz bringt den Springer zurück nach g8, damit die Dame nach f6 fliehen kann.",
        "29": "Der Läufer schlägt den Bauern f4 und greift die Dame an.",
        "30": "Die Dame flieht nach f6.",
        "31": "Ein Springer kommt heraus und will nach d5 springen, um die Dame anzugreifen.",
        "32": "Der Läufer kommt heraus und zielt auf den Turm g1.",
        "33": "Springer nach d5, er greift die Dame f6 und das Feld c7 an. Den Turm g1 gibt Weiß gern her.",
        "34": "Die Dame schlägt den Bauern b2 und greift den Turm a1 an.",
        "35": "Läufer nach d6! Weiß lässt beide Türme stehen. Dafür bauen die Figuren ein Netz um den schwarzen König.",
        "36": "Schwarz schlägt den Turm g1.",
        "37": "e5! Dieser Bauer sperrt die Diagonale der Dame b2 nach g7. Die schwarze Dame kann dem König nicht mehr helfen.",
        "38": "Schwarz schlägt mit Schach auch den anderen Turm.",
        "39": "Der König geht nach e2. Weiß hat nur noch die Dame, zwei Springer und einen Läufer.",
        "40": "Der Springer geht nach a6 und deckt c7. Schwarz soll etwa hier aufgegeben haben; der Rest wäre der Schluss, den Weiß zeigte.",
        "41": "Der Springer schlägt auf g7 mit Schach.",
        "42": "Der König flieht nach d8.",
        "43": "Die Dame opfert sich mit Schach auf f6! Auch die letzte große Figur geht.",
        "44": "Schwarz muss mit dem Springer schlagen.",
        "45": "Läufer nach e7, Schachmatt! Der Springer d5 hält e7 und c7, der Springer g7 hält e8. Weiß gewinnt nur mit einem Läufer und zwei Springern."
      } },
    "mimiaka": { "t": "Die Partie der roten Ohren", "w": "Hon’inbō Shūsaku", "b": "Inoue Gennan Inseki", "ev": "Partie in Osaka (an drei Tagen gespielt)", "d": "1846", "pl": "Japan (Osaka)", "lead": "Der 17-jährige Shūsaku (4. Dan) spielte gegen Gennan (8. Dan), einen der stärksten Spieler seiner Zeit. Bei Zug 127 sollen Gennans Ohren rot geworden sein – daher der Name. Komi gab es noch nicht: Schwarz gewann mit 2 Punkten.",
      c: {
        "0": "Osaka, 1846. Shūsaku hat Schwarz, Gennan Weiß. Am Vortag hatten sie mit zwei Vorgabesteinen begonnen, die Partie aber abgebrochen; jetzt spielt Shūsaku Schwarz ohne Vorgabe.",
        "1": "Schwarz 1 auf dem 3-4-Punkt oben rechts (R16) – tief genug, um die Ecke leicht zu sichern.",
        "2": "Weiß 2 nimmt den 3-4-Punkt oben links (D17). Zuerst werden die leeren Ecken verteilt.",
        "5": "Mit 1, 3 und 5 hat Schwarz drei Ecken besetzt, alle auf 3-4-Punkten. So eröffnete Shūsaku gern, und spätere Spieler lernten davon.",
        "6": "Weiß 6 auf C14 an der linken Seite. Statt Schwarz’ Ecke anzugreifen, stellt sich Weiß an der Seite auf – etwas ungewöhnlich.",
        "7": "Schwarz 7 (E4) schließt die Ecke unten links mit einem zweiten Stein ab. Diese „Eckeinschließung“ macht sie sehr fest.",
        "8": "Weiß 8 (R5) nähert sich der schwarzen Ecke bei Q3. Unten rechts beginnt gleich ein großer Kampf.",
        "10": "Weiß 10 (O4) ist der Taisha: Er deckt den schwarzen Stein schräg aus der Ferne ab. Es gibt unzählige Varianten, und es war Gennans Lieblingszug.",
        "11": "Mit 11 (Q5) wählt Schwarz eine schwierige Fortsetzung. Gennan kannte den Taisha genau, also muss Schwarz vorsichtig sein.",
        "24": "Unten rechts verknäueln sich die Steine; jede Seite will die andere trennen. Nach Weiß 24 (N4) kommen die schwarzen Steine schwer heraus.",
        "25": "Schwarz 25 (N3). Spätere Analysen meinen, hier gab es einen besseren Zug. Selbst für einen Meister war das schwer.",
        "28": "Mit 28 (M3) und 30 (L2) greift Weiß sofort die Schwäche an. Die schwarzen Steine drohen unten auf engem Raum eingeschlossen zu werden.",
        "31": "Schwarz 31 (M4) ist wichtig. Er bereitet das kommende Ko vor – das Hin und Her des Schlagens – und schafft Drohungen, auf die Weiß antworten muss.",
        "36": "Weiß 36 (N2). Bevor das Ko beginnt, spielt Weiß zuerst hier. Gut getimt.",
        "40": "Weiß 40 (R1) schlägt einen Stein, und das Ko beginnt. Wer den Stein verloren hat, darf nicht sofort zurückschlagen und droht zuerst woanders.",
        "41": "Schwarz 41 (O5) ist eine Ko-Drohung. Sie kostet etwas, aber es gibt hier nichts Besseres.",
        "53": "Schwarz 53 (R10) ist ein findiger Einfall, auf den kaum jemand käme. Er greift die weiße Form am rechten Rand an.",
        "60": "Weiß 60 (S3) ist ein großer Zug. Danach kann Weiß auch 62 (M1) mit Vorhand spielen.",
        "63": "Nach Schwarz 63 (O1) beruhigt sich der lange Kampf unten rechts. Weiß hat Gebiet am unteren Rand, Schwarz eine dicke Mauer rechts. Bisher scheint Weiß besser zu stehen.",
        "67": "Schwarz 67 (L17). Mit der Mauer rechts im Rücken baut Schwarz oben ein großes Gerüst.",
        "72": "Weiß 72 (P13) ist ein hervorragender Zug. Direkt über der schwarzen Mauer verhindert er, dass das schwarze Gerüst wächst.",
        "74": "Von hier bis etwa Zug 100 spielt Gennan ohne jede Nachlässigkeit. Er weicht den Angriffen aus und hält seine Steine verbunden.",
        "83": "Schwarz 83 (H3) dringt unten ins weiße Gebiet ein, um es zu verkleinern.",
        "96": "Ab Weiß 96 (R14) gibt es einen feinen Kampf an der schwarzen Ecke oben rechts. Auch hier findet Weiß eine gute Form.",
        "107": "Schwarz 107 (P10) schlägt einen weißen Stein. Die schwarze Gruppe rechts ist jetzt sicher.",
        "118": "Weiß 118 (M19) schlägt einen Stein, und auch die weiße Gruppe oben lebt. Das schwarze Gerüst oben bleibt kleiner als erhofft.",
        "126": "Weiß 126 (J5). Weiß ist unten dick und reicht in die Mitte. Die meisten zuschauenden Profis sollen geglaubt haben, dass Weiß vorne liegt.",
        "127": "Das ist der berühmte Zug der roten Ohren, Schwarz 127 (K11). Dieser eine Stein in der Mitte soll in vier Richtungen zugleich wirken: Er vergrößert das schwarze Gebiet oben, schwächt die weiße Dicke unten, hilft der schwarzen Gruppe rechts und hindert Weiß, sich nach links auszubreiten.",
        "128": "In diesem Moment bemerkte ein zuschauender Arzt, dass Gennans Ohren rot geworden waren. Er verstand wenig vom Go, soll es aber als Zeichen der Unruhe gedeutet und den Sieg von Schwarz vorhergesagt haben.",
        "131": "Schwarz 131 (D10). Schwarz greift nun auch die linke weiße Seite an und verkleinert das weiße Gebiet überall.",
        "147": "Schwarz 147 (K10). Der Stein von Zug 127 beginnt zu wirken: Schwarz schiebt sich in der Mitte zwischen die weißen Gruppen.",
        "160": "Weiß 160 (H8). Weiß schützt die Steine in der Mitte und zielt zugleich auf die schwarze Gruppe unten links. Die Partie bleibt eng.",
        "167": "Schwarz 167 (C2) ist genau. Die schwarzen Steine in der Ecke unten links sind sicher, die weiße Drohung ist weg.",
        "175": "Schwarz 175 (G4) schlägt einen weißen Stein. Das weiße Gebiet unten ist nicht so groß, wie es anfangs aussah.",
        "199": "Schwarz 199 (K7). Der Kampf in der Mitte beruhigt sich; jetzt beginnt das Endspiel, in dem die Grenzen festgelegt werden und jeder Punkt zählt.",
        "212": "Mit 212 (D19) und 216 (F19) schlägt Weiß schwarze Steine am oberen Rand. Im Endspiel gibt keiner nach.",
        "228": "Weiß 228 (N12) erzeugt ein Ko in der Mitte. Über 80 Züge lang wird auf M13 und N13 abwechselnd geschlagen.",
        "236": "Weiß 236 (T8), während des Ko gespielt, schlägt einen Stein. Manche Analysten meinen, das Ko hier zu beenden hätte die Partie noch enger gemacht.",
        "275": "Schwarz 275 (T14) schlägt zwei weiße Steine. Während des Ko gewinnt und verliert jede Seite überall auf dem Brett etwas.",
        "299": "Schwarz 299 (J16) schlägt vier weiße Steine auf einmal. Schwarz hält den oberen Rand fest.",
        "311": "Schwarz 311 (M13) löst das Ko auf. Der lange Ko-Kampf ist endlich vorbei.",
        "325": "Nach 325 Zügen ist die Partie zu Ende; Schwarz liegt mit 2 Punkten vorn. Auch ohne Komi war der Sieg eines 17-Jährigen über einen Spieler wie Gennan eine Sensation, und Shūsakus Name wurde bekannt."
      } },
    "evergreen": { "t": "Die Immergrüne Partie", "w": "Adolf Anderssen", "b": "Jean Dufresne", "ev": "Eine freie Partie (kein Turnier)", "d": "1852", "pl": "Deutschland (vermutlich Berlin)", "lead": "Anderssen, der Sieger der Unsterblichen, spielte ein Jahr später dieses zweite Meisterwerk. Gerade als Schwarz Matt droht, zieht Weiß ruhig einen Turm, gibt dann die Dame her und gewinnt mit einem Doppelschach. „Immergrün“ heißt sie, weil sie nie verblasst.",
      c: {
        "0": "Eine Partie, die 1852 in einer Zeitschrift erschien. Weiß ist Anderssen, Schwarz sein Freund Dufresne. Man nimmt an, dass sie in Berlin gespielt wurde, aber kein Dokument belegt das sicher.",
        "1": "Weiß zieht den Königsbauern zwei Felder vor.",
        "2": "Schwarz macht dasselbe.",
        "3": "Der Springer greift den Bauern e5 an.",
        "4": "Schwarz deckt e5 mit einem Springer.",
        "5": "Der Läufer kommt heraus und zielt auf f7.",
        "6": "Auch Schwarz entwickelt einen Läufer.",
        "7": "b4! Ein Bauernangebot namens Evans-Gambit. Während Schwarz schlägt, baut Weiß das Zentrum auf.",
        "8": "Schwarz nimmt den Bauern.",
        "9": "c3 jagt den Läufer und bereitet d4 vor.",
        "10": "Der Läufer zieht sich nach a5 zurück.",
        "11": "d4 besetzt das Zentrum.",
        "12": "Schwarz schlägt den Bauern.",
        "13": "Weiß schlägt nicht zurück, sondern rochiert. Königssicherheit und aktive Figuren gehen vor Bauern.",
        "14": "Der schwarze Bauer läuft bis d3, mitten ins weiße Lager.",
        "15": "Dame nach b3. Zusammen mit dem Läufer c4 zielt sie auf f7.",
        "16": "Schwarz deckt f7 mit der Dame.",
        "17": "e5 jagt die Dame.",
        "18": "Die Dame geht nach g6.",
        "19": "Turm nach e1, auf die e-Linie, um den Bauern e5 zu stützen.",
        "20": "Schwarz entwickelt einen Springer, um die Rochade vorzubereiten.",
        "21": "Läufer nach a3, er zielt auf der Diagonale auf den Springer e7. Zieht dieser Springer, erreicht der Läufer f8 – die kurze Rochade wird für Schwarz schwierig.",
        "22": "Schwarz bietet einen Bauern an, um weiße Figuren abzulenken.",
        "23": "Die Dame nimmt ihn.",
        "24": "Turm nach b8, er jagt die Dame auf der b-Linie.",
        "25": "Die Dame geht nach a4.",
        "26": "Der Läufer zieht sich nach b6 zurück.",
        "27": "Ein Springer kommt heraus. Fast alle weißen Figuren sind im Spiel.",
        "28": "Schwarz entwickelt den anderen Läufer.",
        "29": "Springer nach e4, mit Blick auf f6.",
        "30": "Die schwarze Dame geht nach f5 und greift den Springer e4 an.",
        "31": "Der Läufer schlägt den Bauern d3 und deckt den Springer e4.",
        "32": "Dame nach h5, sie zielt auf den Springer f3.",
        "33": "Der Springer opfert sich mit Schach auf f6!",
        "34": "Schwarz schlägt mit einem Bauern.",
        "35": "Weiß schlägt mit einem Bauern zurück und greift den Springer e7 an. Auf der e-Linie blickt auch der Turm e1 auf e7.",
        "36": "Turm nach g8, er zielt auf g2. Schlägt die Dame h5 auf f3, ist das Matt nah.",
        "37": "Ein ruhiger Turmzug nach d1! Der weiße König ist in Gefahr, doch statt zu verteidigen, richtet Weiß alles auf d7. Dieser Zug machte die Partie „immergrün“.",
        "38": "Schwarz schlägt den Springer f3. Danach auf g2 zu schlagen wäre Matt.",
        "39": "Aber Weiß ist zuerst dran. Der Turm schlägt den Springer e7 mit Schach!",
        "40": "Schwarz schlägt mit dem Springer c6 zurück. Nun ist die Diagonale von a4 nach d7 frei.",
        "41": "Die Dame opfert sich mit Schach auf d7!",
        "42": "Schwarz muss mit dem König schlagen.",
        "43": "Der Läufer zieht mit Schach nach f5 und öffnet zugleich die d-Linie für den Turm d1: Doppelschach.",
        "44": "Der König geht nach e8. Auf c6 würde der Läufer auf d7 mattsetzen.",
        "45": "Läufer nach d7, Schach.",
        "46": "Der König geht nach f8.",
        "47": "Der Läufer a3 schlägt den Springer e7: Schachmatt! Der Läufer d7 hält e8, und der Bauer f6 hält e7 und g7."
      } },
    "lasker1912": { "t": "Die Königsjagd", "w": "Edward Lasker", "b": "George Alan Thomas", "ev": "Eine schnelle, freie Partie im City of London Chess Club", "d": "1912", "pl": "Vereinigtes Königreich (London)", "lead": "Eine schnelle, freie Partie in einem Londoner Klub. Weiß gibt die Dame her und jagt den schwarzen König über das ganze Brett, von g8 bis g1. Die Eröffnungszüge stehen in den Quellen in leicht unterschiedlicher Reihenfolge, doch die Stellung nach dem 10. Zug ist dieselbe.",
      c: {
        "0": "Oktober 1912, City of London Chess Club. Weiß ist Edward Lasker, ein junger Ingenieur, gerade aus Deutschland gekommen; Schwarz ist George Alan Thomas, später britischer Meister. Es war eine schnelle, freie Partie. Berühmt ist sie als „Königsjagd“: Der schwarze König wird von g8 bis nach g1 am anderen Ende des Bretts gejagt. Lasker ging später nach Amerika und wurde durch seine Schachbücher bekannt.",
        "1": "Weiß beginnt mit d4, dem Damenbauern. Er kontrolliert e5 und c5 und öffnet dem Läufer c1 den Weg.",
        "2": "Schwarz spielt e6: zuerst eine solide Stellung, mit f5 oder d5 im Sinn.",
        "3": "Springer nach f3. Er kontrolliert e5 und hilft, den Königsflügel zu schützen – das natürlichste Feld.",
        "4": "Schwarz spielt f5 und kontrolliert e4, ähnlich wie in der Holländischen Verteidigung. Aber ein Bauernzug vor dem König schwächt ihn etwas.",
        "5": "Der andere Springer geht nach c3 und bereitet e4 vor, um den Bauern f5 anzugreifen.",
        "6": "Schwarz entwickelt einen Springer nach f6: Er kontrolliert e4 noch mehr und bereitet die Rochade vor.",
        "7": "Läufer nach g5, er zielt auf den Springer f6. Dieser Springer ist ein wichtiger Verteidiger des schwarzen Königs, also will Weiß ihn früh beseitigen.",
        "8": "Schwarz stellt den Läufer nach e7, deckt den Springer und kommt der Rochade näher.",
        "9": "Weiß tauscht den Läufer gegen den Springer. Der Springer, der den schwarzen König schützte, ist weg.",
        "10": "Schwarz schlägt mit dem Läufer zurück. Dieser Läufer auf f6 übernimmt jetzt den Schutz des Königsflügels.",
        "11": "e4! Weiß greift den Bauern f5 an und gewinnt Raum im Zentrum. Linien öffnen sich, die weißen Figuren werden beweglicher.",
        "12": "Schwarz schlägt den Bauern e4. Sonst würde Weiß e5 spielen und die schwarzen Figuren zurückdrängen.",
        "13": "Der Springer schlägt zurück und steht im Zentrum, mit Blick auf den Läufer f6 und die Felder g5 und d6.",
        "14": "Schwarz spielt b6, um den Läufer nach b7 zu bringen und über die lange Diagonale auf den Springer e4 zu zielen.",
        "15": "Springer nach e5, ein starkes Zentrumsfeld, das auch g4 und f7 im Blick hat. Beide weißen Springer stehen jetzt nahe am schwarzen Königsflügel.",
        "16": "Schwarz rochiert. Der König steht auf g8. Aber ohne f-Bauern gibt es viele Lücken um den König.",
        "17": "Läufer nach d3. Noch steht ihm der eigene Springer e4 im Weg, doch dahinter liegt der Bauer h7. Sobald der Springer e4 zieht, zielt dieser Läufer direkt auf h7.",
        "18": "Der schwarze Läufer geht nach b7 und zielt über die lange Diagonale auf den Springer e4, was die weißen Figuren einschränkt.",
        "19": "Dame nach h5, sie zielt auf den Bauern h7, den nur der schwarze König deckt. Dame, Läufer und Springer von Weiß zeigen alle auf den schwarzen König.",
        "20": "Schwarz stellt die Dame nach e7. Sie deckt den Läufer f6 und will nach c5, aber Schwarz übersieht die weiße Idee. Nötig waren h6 oder das Schlagen des Springers e5. Das ist der Wendepunkt.",
        "21": "Die Dame opfert sich mit Schach auf h7! Weiß verschenkt seine stärkste Figur. Lasker sah den ganzen Weg, den König bis ins Matt zu jagen.",
        "22": "Schwarz muss mit dem König schlagen, der nun auf h7 steht.",
        "23": "Der Springer schlägt den Läufer f6 mit Schach. Gleichzeitig wird e4 frei, und der Läufer d3 gibt dem König auf h7 ebenfalls Schach: Doppelschach. Es lässt sich nicht verstellen, der König muss fliehen.",
        "24": "Der König geht nach h6. Auf h8 spränge der andere Springer mit Matt nach g6. Der König wird immer weiter nach vorn getrieben.",
        "25": "Der andere Springer springt mit Schach von e5 nach g4, greift den König h6 an und treibt ihn weiter.",
        "26": "Der König geht nach g5: Er verlässt sein Lager und wandert zur weißen Seite.",
        "27": "Schach mit dem h-Bauern! Sogar die Bauern machen bei der Jagd mit. Der König muss weiter nach vorn.",
        "28": "Der König geht nach f4. Er hat die Brettmitte überquert und betritt das weiße Lager.",
        "29": "Wieder Schach, mit dem g-Bauern. Zwei Bauern versperren dem König den Rückweg.",
        "30": "Der König geht nach f3, mitten zwischen die weißen Figuren.",
        "31": "Der Läufer zieht sich mit Schach von d3 nach e2 zurück. Der König wird noch tiefer getrieben.",
        "32": "Der König geht nach g2. Der weiße König auf e1 ist nicht mehr weit.",
        "33": "Turm nach h2, Schach. Endlich greift auch der Turm ein.",
        "34": "Der König erreicht schließlich g1. Von g8 aus ist er bis zur ersten Reihe am anderen Ende des Bretts gewandert.",
        "35": "Der weiße König zieht von e1 nach d2. Damit wird der Turm a1 frei und gibt dem König g1 auf der ersten Reihe Schach: Schachmatt! Auch die lange Rochade hätte mattgesetzt, doch Lasker zog den König. In einer schnellen Partie jagte Weiß nach dem Damenopfer den König vierzehn Züge lang bis in die tiefste Ecke des eigenen Lagers. Eine sehr seltene Partie."
      } },
    "toketsu": { "t": "Die Blutspucker-Partie", "w": "Akaboshi Intetsu", "b": "Hon’inbō Jōwa", "ev": "Gespielt im Haus des Fürsten Matsudaira von Suō (an vier Tagen)", "d": "1835", "pl": "Japan (Edo)", "lead": "Eine Partie aus dem Streit um das Amt des Meijin Godokoro, das höchste im japanischen Go. Inoue Gennan Inseki schickte seinen Schüler Akaboshi Intetsu gegen den Meijin Jōwa. Nach vier Tagen harten Kampfes verlor Intetsu und soll am Brett Blut gespuckt haben.",
      c: {
        "0": "1835. Schwarz: Akaboshi Intetsu (7. Dan), Weiß: der Meijin Hon’inbō Jōwa. Gennan schickte seinen besten Schüler – ein Meijin, der gegen einen 7. Dan verliert, verdiene den Titel nicht, wollte er sagen.",
        "1": "Schwarz 1 auf dem 3-4-Punkt unten links (C4). Intetsu beginnt ruhig.",
        "4": "Nach vier Zügen liegt in jeder Ecke ein Stein: Weiß unten rechts und oben links, Schwarz unten links und oben rechts.",
        "6": "Weiß 6 (E3) nähert sich schon der schwarzen Ecke unten links. Jōwa spielt von Anfang an aktiv.",
        "10": "Weiß 10 (P4) schließt die Ecke unten rechts mit einem zweiten Stein ab.",
        "12": "Weiß 12 (D6) drückt von oben auf die schwarze Ecke unten links. Hier beginnt der größte Kampf der Partie.",
        "13": "Schwarz 13 (E4) legt sich direkt an einen weißen Stein. Schwarz nimmt den Kampf an.",
        "20": "Weiß 20 (C3) schlüpft unter die schwarze Ecke: Er nimmt Eckgebiet weg und versucht zugleich, die eigenen Steine leben zu lassen.",
        "28": "Weiß 28 (C9) greift weit an der linken Seite aus. Oft gilt er als Überdehnung – ein wilder Zug, typisch für Jōwa.",
        "33": "Schwarz 33 (C2). Das soll eine neue Variante sein, die das Haus Inoue heimlich studiert hatte. Sie greift die schwebenden weißen Steine in der Mitte an und schluckt zugleich die weißen Steine links.",
        "36": "Weiß 36 (F3). Weiß will Schwarz unten links von außen einschließen und zugleich die eigenen Steine verbinden.",
        "43": "Schwarz 43 (E9). Die weißen Steine links sind in Not. Bis hierher hat Intetsu gut gespielt und gilt als in Führung.",
        "45": "Schwarz 45 (D11) zieht an der linken Seite nach oben, hält die weißen Steine getrennt und stärkt sich selbst.",
        "50": "Weiß 50 (C16). Weiß verlässt vorerst unten links und wendet sich der Ecke oben links zu.",
        "53": "Schwarz 53 (G17). Schwarz geht an den oberen Rand, damit Weiß die Ecke oben links nicht vergrößern kann.",
        "58": "Weiß 58 (C14) dehnt sich von der Ecke oben links die Seite entlang aus und rückt an die schwarzen Steine links heran.",
        "60": "Weiß 60 (G4) schlägt zwei schwarze Steine. Die weiße Gruppe unten links bekommt endlich etwas Luft.",
        "62": "Weiß 62 (J17). Auch oben stehen sich beide gegenüber. Überall gibt es schwache Steine – eine schwierige Stellung.",
        "66": "Weiß 66 (B14). An der Ecke oben links bringt Weiß seine Steine in Sicherheit.",
        "68": "Weiß 68 (B11). Die folgenden weißen Züge und Zug 80 wurden als Jōwas Glanzzüge berühmt. Sie waren so erstaunlich, dass man sagte, Geister hätten sie ihm gezeigt.",
        "70": "Weiß 70 (E12). Statt Schwarz links direkt zu antworten, spielt Weiß zuerst einen anderen Schlüsselpunkt. Versteckte Möglichkeiten machen das möglich.",
        "72": "Weiß 72 (R13). Weiß wendet sich der rechten Seite zu, damit das schwarze Gebiet oben rechts nicht wächst.",
        "76": "Weiß 76 (O14). Weiß verbindet die rechte Seite mit der Mitte und bereitet die Trennung der schwarzen Steine vor.",
        "80": "Weiß 80 (Q10) bildet ein „leeres Dreieck“, eine Form, die meist als schlecht gilt. Doch genau dieser Zug wurde zur Basis, Schwarz zu teilen und anzugreifen – das klassische Beispiel für einen hässlichen, aber starken Zug.",
        "83": "Schwarz 83 (R3) dringt in die weiße Ecke unten rechts ein. Dort folgt ein heftiger Kampf mit Schlagen und Zurückschlagen.",
        "91": "Schwarz 91 (Q4) schlägt einen weißen Stein. Die Ecke unten rechts ist für Schwarz wichtig.",
        "98": "Weiß 98 (M4). Weiß umschließt die schwarzen Steine unten und lässt sie nicht leicht leben.",
        "106": "Weiß 106 (S5) schlägt einen schwarzen Stein. Weiß behält die Ecke unten rechts, und die schwarzen Steine müssen nach außen fliehen.",
        "113": "Schwarz 113 (K6). Die schwarzen Steine unten suchen ihr Leben, indem sie in die Mitte laufen.",
        "120": "Weiß 120 (N9) versperrt den fliehenden schwarzen Steinen den Weg. In der Mitte geht es darum, wessen Steine zuerst schwach werden.",
        "128": "Weiß 128 (L11) drückt die schwarzen Steine in der Mitte auch von oben. Schwarz kann noch nicht durchatmen.",
        "138": "Weiß 138 (K8) schlägt einen Stein, und in der Mitte beginnt ein Ko. Rund 30 Züge lang wird auf K8 und L8 hin und her geschlagen.",
        "152": "Weiß 152 (E11) ist eine Ko-Drohung. Während des Ko findet Weiß überall Züge, auf die Schwarz antworten muss.",
        "170": "Weiß 170 (P15). Das Ko in der Mitte ist vorbei; Weiß geht nach oben rechts und zielt auf eine große schwarze Gruppe, die noch nicht ganz lebt.",
        "178": "Weiß 178 (J14) springt mitten in den oberen Bereich, um die schwarzen Steine links und rechts zu trennen. Der seit Zug 80 vorbereitete Trennungsangriff beginnt jetzt richtig.",
        "193": "Schwarz 193 (J11) schlägt einen weißen Stein. Schwarz kämpft verbissen um Verbindung und Leben.",
        "201": "Schwarz 201 (R14) schlägt einen Stein, und an der rechten Seite beginnt ein neues Ko mit Schlagen auf R14 und R15.",
        "206": "Weiß 206 (M13). Auch während des Ko zieht Weiß die Schlinge um die schwarzen Steine in der Mitte langsam zu.",
        "222": "Weiß 222 (L14) schlägt einen Stein. Die schwarzen Steine oben bleiben geteilt, und beide zu retten wird schwer.",
        "230": "Weiß 230 (C13) trifft auch die schwarze Schwäche am linken Rand. Die weißen Steine sind jetzt überall fest verbunden.",
        "237": "Mit 237 (F12) und 239 (E13) schlägt Schwarz oben links zurück. Trotzdem schrumpft der Abstand insgesamt nicht.",
        "246": "Nach Weiß 246 (L8) gab Intetsu auf. Als die Steine abgeräumt wurden, soll er Blut auf das Brett gespuckt haben. Vermutlich war er schon länger krank; er starb kurz darauf. Für Jōwa gilt die Partie als größter Sieg seines Lebens."
      } },
    "deepblue1997": { "t": "Der Sieg von Deep Blue", "w": "Deep Blue (Computer von IBM)", "b": "Garri Kasparow", "ev": "6. Partie des Revanchekampfs gegen IBMs Deep Blue (Wettkampf über sechs Partien)", "d": "1997", "pl": "USA (New York)", "lead": "Weltmeister Kasparow gegen Deep Blue, einen von IBM gebauten Schachcomputer, in einem Wettkampf über sechs Partien. Nach fünf Partien stand es unentschieden, und die letzte war nach nur 19 Zügen vorbei. Zum ersten Mal gewann ein Computer einen ganzen Wettkampf über mehrere Partien gegen den Weltmeister.",
      c: {
        "0": "New York, 11. Mai 1997. Ein Jahr zuvor hatte Kasparow den Wettkampf gewonnen. Diesmal steht es nach fünf Partien 2½:2½. Deep Blue hat Weiß.",
        "1": "Weiß zieht den Königsbauern zwei Felder vor.",
        "2": "Kasparow spielt c6: die Caro-Kann-Verteidigung.",
        "3": "Weiß bringt den anderen Bauern ins Zentrum.",
        "4": "Schwarz spielt d5 gegen e4.",
        "5": "Der Springer deckt e4.",
        "6": "Schwarz schlägt den Bauern e4.",
        "7": "Der Springer schlägt zurück.",
        "8": "Schwarz stellt einen Springer nach d7, um danach den anderen nach f6 zu bringen.",
        "9": "Der Springer springt nach g5: ein scharfer Plan gegen f7 und e6.",
        "10": "Schwarz bringt den Springer nach f6.",
        "11": "Läufer nach d3, mit Blick auf den schwarzen Königsflügel.",
        "12": "Schwarz festigt die Verteidigung mit e6.",
        "13": "Der andere Springer kommt nach f3.",
        "14": "Schwarz spielt h6, um den Springer g5 zu vertreiben. Doch in dieser Stellung war ein Springeropfer für Weiß schon bekannt. Man sagt, es sei eine ungewöhnliche Wahl für Kasparow gewesen.",
        "15": "Der Springer opfert sich auf e6! Deep Blue soll diesen Zug aus den vorher gespeicherten Eröffnungszügen gespielt haben.",
        "16": "Schwarz schlägt nicht sofort, sondern stellt die Dame nach e7. Auf der e-Linie zielt sie auf den Springer e6 und den weißen König dahinter.",
        "17": "Weiß rochiert und bringt den König in Sicherheit.",
        "18": "Schwarz schlägt den Springer und hat mehr Material.",
        "19": "Läufer nach g6, Schach. Ohne den Bauern f7 reicht die Diagonale bis zum König.",
        "20": "Der König geht nach d8. Schwarz kann nicht mehr rochieren, und der König bleibt nahe der Mitte.",
        "21": "Der andere Läufer kommt heraus und zielt auf die Felder um den schwarzen König.",
        "22": "Schwarz spielt b5, um am Damenflügel Platz für König und Läufer zu schaffen.",
        "23": "a4 greift den Bauern b5 an.",
        "24": "Schwarz stellt den Läufer nach b7.",
        "25": "Turm nach e1. Auf der e-Linie zielt er auf den Bauern e6 und dahinter auf die Dame e7.",
        "26": "Der schwarze Springer geht nach d5 und greift den Läufer f4 an.",
        "27": "Der Läufer zieht sich nach g3 zurück.",
        "28": "Der schwarze König geht nach c8, etwas sicherer.",
        "29": "Weiß schlägt den Bauern b5.",
        "30": "Schwarz schlägt zurück.",
        "31": "Dame nach d3, mit Blick auf den Bauern b5 und das Feld f5.",
        "32": "Schwarz deckt b5 mit dem Läufer.",
        "33": "Läufer nach f5! Er kann umsonst geschlagen werden.",
        "34": "Schwarz schlägt mit einem Bauern. Doch damit ist der Bauer auf der e-Linie weg.",
        "35": "Der Turm schlägt die Dame e7. Weiß hat Springer, Läufer und Turm gegeben, aber die Dame gewonnen.",
        "36": "Schwarz schlägt den Turm mit dem Läufer zurück.",
        "37": "c4! Der Bauer greift b5 und d5 zugleich an, und die schwarze Verteidigung beginnt zu zerfallen. Kasparow gab hier auf, wohl weil sein König zu offen stand, um den Angriff aufzuhalten. Ein Computer hatte einen Wettkampf gegen den Weltmeister gewonnen."
      } },
    "seigen1933": { "t": "Die 3-3-, Hoshi- und Tengen-Partie", "w": "Go Seigen", "b": "Hon’inbō Shūsai", "ev": "Gedenkpartie gegen den Meijin (über drei Monate)", "d": "1933–1934", "pl": "Japan (Tokio)", "lead": "Der 19-jährige Go Seigen (5. Dan) spielte gegen den Meijin Hon’inbō Shūsai. Mit Schwarz eröffnete er auf dem 3-3-Punkt, dann auf einem Sternpunkt, dann genau in der Mitte (Tengen) – gegen alle Regeln der Zeit, zum Staunen der Go-Welt. Mit vielen Unterbrechungen dauerte die Partie über drei Monate; Weiß gewann mit 2 Punkten.",
      c: {
        "0": "1933. In diesem Jahr verbreiteten Go Seigen und sein Freund Kitani Minoru einen neuen Eröffnungsstil, das „Shinfuseki“. Alle wollten sehen, wie er ihn gegen den Meijin einsetzen würde.",
        "1": "Schwarz 1 auf dem 3-3-Punkt oben rechts (R17). Er sichert die Ecke mit einem Zug, wirkt aber kaum nach außen; damals galt er nicht als Eröffnungszug.",
        "3": "Schwarz 3 auf dem Sternpunkt unten links (D4). Anders als der 3-3-Punkt setzt er auf Ausdehnung nach außen.",
        "5": "Schwarz 5 geht genau in die Brettmitte – Tengen (K10). Keine Ecke, keine Seite, sondern die Mitte. Gegen den Meijin zeigte Go Seigen seine neuen Ideen ganz offen.",
        "6": "3-3, Sternpunkt, Tengen: Jeder schwarze Stein hat eine andere Aufgabe – Eckgebiet, Wirkung nach außen, Kraft in der Mitte. Mit 6 (Q16) spielt Weiß direkt neben den schwarzen 3-3-Stein.",
        "9": "Schwarz 9 (P18). Schwarz sichert die Ecke oben rechts kompakt und fest – ein gebietsorientierter Stil, passend zum 3-3-Punkt.",
        "11": "Schwarz 11 (K4) geht in die Mitte des unteren Rands, genau unter Tengen. Zusammen mit diesem Stein zielt Schwarz auf ein großes Gebiet unten.",
        "12": "Weiß 12 (M3) geht sofort an den unteren Rand, damit Schwarz kein großes Gerüst baut. Der Meijin bleibt ruhig und nimmt die schwarzen Pläne einen nach dem anderen auseinander.",
        "13": "Schwarz 13 (D10), jetzt in der Mitte des linken Rands. Die schwarzen Steine stehen hoch und bilden gemeinsam ein weites Gerüst.",
        "14": "Weiß 14 (E16) schließt die Ecke oben links mit einem zweiten Stein ab. Der Meijin lässt sich vom neuen Stil nicht beirren und sichert ruhig die Ecke.",
        "21": "Schwarz 21 (G10) verbindet Tengen mit dem Stein links, und der schwarze Einfluss breitet sich in der Mitte aus.",
        "28": "Weiß 28 (D3) schlüpft unter den schwarzen Sternpunktstein unten links und nimmt die Ecke. Schwarz überlässt sie Weiß für Stärke nach außen.",
        "30": "Weiß 30 (Q12) dehnt sich am rechten Rand aus und setzt zugleich einen Deckel auf die schwarze 3-3-Ecke.",
        "37": "Schwarz 37 (P15) schlägt einen weißen Stein. Oben rechts prallen beide Seiten in einem engen Kampf aufeinander.",
        "40": "Weiß 40 (O10) tritt von der rechten Seite in Richtung Mitte und nähert sich dem schwarzen Einfluss um Tengen.",
        "44": "Weiß 44 (H17) besetzt einen Punkt am oberen Rand und bremst die Ausbreitung von Schwarz nach oben.",
        "45": "Schwarz 45 (R7) nimmt die weiße Stellung unten rechts in Angriff. Es folgt ein langer Kampf von der rechten Seite bis in diese Ecke.",
        "59": "Schwarz 59 (R4) dringt auch in die Ecke unten rechts ein und verkleinert das weiße Gebiet.",
        "70": "Weiß 70 (N6) schiebt sich vom unteren Rand in die Mitte, um die schwarzen Steine unten rechts von der Mitte zu trennen.",
        "79": "Schwarz 79 (L9) festigt die Mitte rund um den Tengen-Stein. Bisher wirkt die Partie recht ausgeglichen.",
        "80": "Weiß 80 (C6) zieht von der Ecke unten links die linke Seite hinauf und zielt auf die schwarzen Steine dort.",
        "98": "Weiß 98 (A11) schlägt zwei schwarze Steine. Weiß lebt sauber am linken Rand, und die linke schwarze Seite fällt kleiner aus als geplant.",
        "101": "Schwarz 101 (S14) kehrt nach oben rechts zurück, um die weiße Stellung am rechten Rand zu verkleinern.",
        "105": "Schwarz 105 (K17) besetzt die Mitte des oberen Rands und beginnt, die weißen Steine dort anzugreifen.",
        "117": "Schwarz 117 (F17) dringt auch nahe der weißen Ecke oben links ein; der ganze obere Rand wird zum Schlachtfeld.",
        "124": "Weiß 124 (K15) führt die oberen Steine in die Mitte und schneidet dabei zwischen die schwarzen Steine.",
        "135": "Schwarz 135 (E9) schlägt zwei weiße Steine. Schwarz holt links etwas zurück.",
        "138": "Weiß 138 (N18) sichert Gebiet am oberen Rand. Über das ganze Brett gesehen ist die Stellung sehr knapp.",
        "153": "Schwarz 153 (K14). Die schwarzen Steine in der Mitte bilden eine dicke Straße von oben nach unten. Entscheidend ist, wie Weiß diese Dicke aufbrechen kann.",
        "159": "Schwarz 159 (F4) verteidigt unten links solide. Der nächste weiße Zug ist der berühmteste der Partie.",
        "160": "Weiß 160 (H8) springt in eine Lücke der schwarzen Dicke – ein scharfer Zug mit mehreren Zielen, mit dem Weiß beginnt, in die schwarze Mitte einzudringen. Es ging das Gerücht, ein Schüler und nicht Shūsai habe ihn gefunden, doch bewiesen wurde das nie.",
        "161": "Schwarz 161 (J8) antwortet sofort, aber Weiß hat mehr als ein Ziel.",
        "162": "Weiß 162 (K12) wechselt in den oberen Teil der Mitte und bedroht die schwarzen Verbindungen.",
        "172": "Weiß 172 (F13) verbindet Steine aus der Mitte mit oben links. Nach und nach wird die schwarze Dicke in der Mitte nicht mehr zu Gebiet.",
        "178": "Weiß 178 (N9) dringt auch rechts der Mitte ins schwarze Gebiet ein.",
        "187": "Mit 187 (M6) und 189 (L7) schlägt Schwarz weiße Steine. Trotzdem hat Weiß die wichtigen Punkte schon vorher besetzt.",
        "198": "Weiß 198 (E12) schlägt einen Stein. Auch die weißen Steine oben links sind verbunden; Weiß liegt insgesamt leicht vorn.",
        "203": "Schwarz 203 (B3). Ab hier ist Endspiel: Die Grenzen an den Rändern werden Punkt für Punkt festgelegt.",
        "224": "Weiß 224 (T10) schlägt einen Stein. Selbst am rechten Rand gibt Weiß keinen Punkt ab.",
        "233": "Schwarz 233 (L13) schlägt zwei weiße Steine. Schwarz jagt bis zum Schluss hinterher.",
        "252": "Nach 252 Zügen ist Schluss: Weiß gewinnt mit 2 Punkten. Ohne Komi hatte Schwarz den kleinen Vorteil des ersten Zuges, doch der Meijin blieb bis zum Ende standhaft. Trotzdem sorgten Go Seigens 3-3, Sternpunkt und Tengen für Aufsehen und kündigten ein neues Zeitalter der Eröffnungen an."
      } },
    "century1956": { "t": "Die Partie des Jahrhunderts", "w": "Donald Byrne", "b": "Bobby Fischer", "ev": "Drittes Rosenwald-Trophy-Turnier (Rosenwald-Gedenkturnier)", "d": "1956", "pl": "USA (New York)", "lead": "Der dreizehnjährige Bobby Fischer schlägt Donald Byrne, einen der stärksten Meister der USA. Im 17. Zug lässt Fischer seine Dame umsonst schlagen, holt dann Figur um Figur zurück, und am Ende jagen seine kleinen Figuren den weißen König. Fischer wurde später Weltmeister.",
      c: {
        "0": "New York, 17. Oktober 1956, eine Turnierpartie. Schwarz spielt der dreizehnjährige Fischer, Weiß Byrne, einer der besten Spieler der USA.",
        "1": "Weiß beginnt mit einem Springer.",
        "4": "Fischer spielt g6, um den Läufer auf die lange Diagonale zu stellen.",
        "8": "Schwarz rochiert: zuerst den König in Sicherheit bringen.",
        "10": "Schwarz spielt d5. Der Kampf ums Zentrum beginnt.",
        "15": "Mit e4 hat Weiß zwei Bauern nebeneinander im Zentrum.",
        "17": "Turm nach d1, er stützt den Bauern d4. Weiß hat immer noch nicht rochiert.",
        "18": "Der Springer geht nach b6 und jagt die Dame c4.",
        "20": "Läufer nach g4, er setzt den Springer f3 unter Druck.",
        "21": "Der weiße Läufer geht nach g5. Der weiße König steht noch in der Mitte.",
        "22": "Springer nach a4! Er springt auf ein Feld, wo er geschlagen werden kann. Die Idee: Verschwindet der Springer c3, verliert der Bauer e4 seinen Schutz.",
        "23": "Weiß schlägt den Springer nicht und stellt die Dame nach a3.",
        "26": "Der schwarze Springer schlägt den Bauern e4. Das weiße Zentrum bricht zusammen.",
        "27": "Der weiße Läufer schlägt den Bauern e7 und greift zugleich die schwarze Dame und den Turm f8 an.",
        "28": "Dame nach b6! Schwarz lässt den Turm f8 stehen. Fischer setzt darauf, dass der weiße König noch in der Mitte steht.",
        "29": "Weiß nimmt den Turm nicht, sondern entwickelt den Läufer.",
        "30": "Der Springer schlägt den Bauern c3 und greift den Turm d1 an.",
        "31": "Läufer nach c5, er greift die schwarze Dame auf b6 an.",
        "32": "Schach vom Turm auf der e-Linie!",
        "33": "Der König geht nach f1. Jetzt kann Weiß nie mehr rochieren.",
        "34": "Läufer nach e6! Der berühmteste Zug der Partie: Schwarz lässt die Dame umsonst schlagen. Dafür hat Schwarz einen Plan, Figur um Figur zurückzuholen.",
        "35": "Weiß schlägt die schwarze Dame.",
        "36": "Läufer nach c4, Schach. Der schwarze Gegenangriff beginnt.",
        "38": "Der Springer gibt Schach auf e2.",
        "40": "Geht der König zurück nach f1, zieht der Springer und deckt ein Schach des Läufers c4 auf. Nebenbei schnappt sich der Springer den Bauern d4.",
        "44": "Der Springer kehrt nach c3 zurück, wieder ein Abzugsschach, und greift jetzt den Turm d1 an. Immer wieder Schach geben und dabei Figuren einsammeln nennt man „Zwickmühle“.",
        "46": "Schwarz schlägt den Läufer zurück. Der Springer c3 greift noch immer den Turm d1 an.",
        "50": "Der Springer schlägt den Turm d1. Jetzt hat Schwarz mehr als die Dame zurückgewonnen und steht klar besser.",
        "52": "Der Turm schlägt auch den Bauern a2.",
        "56": "Schwarz tauscht die Türme. Je weniger Figuren übrig sind, desto besser für den, der mehr hat.",
        "57": "Die weiße Dame gibt Schach.",
        "58": "Schwarz stellt den Läufer dazwischen.",
        "64": "b5. Der schwarze Bauer marschiert los.",
        "68": "Der König geht nach g7 und befreit den Läufer f8.",
        "70": "Jetzt jagen die schwarzen Figuren den weißen König. Schach mit einem Läufer.",
        "72": "Der Springer gibt Schach auf g3.",
        "74": "Schach mit dem anderen Läufer.",
        "76": "Läufer nach b3, Schach.",
        "78": "Der Springer gibt Schach auf e2.",
        "80": "Der Springer gibt Schach auf c3. Der König wird hin und her gejagt.",
        "82": "Turm nach c2: Schachmatt! Turm, zwei Läufer und Springer arbeiten zusammen. Ein Dreizehnjähriger zeigte, wie viele Figuren als ein Team spielen können."
      } },
    "oshiro1849": { "t": "Shūsakus erste Schlosspartie", "w": "Hon’inbō Shūsaku", "b": "Yasui Sanchi IX", "ev": "Schlosspartie (die jährliche Partie im Schloss Edo)", "d": "1849", "pl": "Japan (Edo)", "lead": "Die Schlosspartien waren der jährliche Höhepunkt, bei dem die Spieler der offiziellen Go-Häuser im Schloss des Shōguns spielten. Der 20-jährige Shūsaku trat in diesem Jahr erstmals an und gewann mit Schwarz um 11 Punkte – der Beginn einer makellosen Serie von 19 Siegen in 19 Schlosspartien.",
      c: {
        "0": "1849. Im Vorjahr war Shūsaku zum Erben des Hauses Hon’inbō bestimmt worden; nun spielt er seine erste Schlosspartie. Solche Partien sollen oft vorher anderswo gespielt und im Schloss nur nachgelegt worden sein.",
        "1": "Schwarz 1 auf dem 3-4-Punkt oben rechts (R16). Wie gewohnt beginnt Shūsaku ruhig mit einem 3-4-Punkt.",
        "4": "Weiß 4 (C15) nähert sich dem schwarzen Stein auf D17 oben links. Dort beginnt früh ein Kampf.",
        "5": "Schwarz 5 (C11) zwickt den anrückenden weißen Stein von unten, damit Weiß sich links nicht leicht festsetzt.",
        "12": "Weiß 12 (C17). Weiß nimmt die Ecke oben links, Schwarz bekommt nach außen gerichtete Steine – ein fairer Tausch.",
        "13": "Schwarz 13 (J17) nutzt die äußeren Steine und dehnt sich oben aus.",
        "15": "Schwarz 15 (C5) besetzt die letzte freie Ecke unten links. Alle vier Ecken sind jetzt belegt.",
        "16": "Weiß 16 (E4) nähert sich sofort diesem schwarzen Stein, und auch unten links wird gekämpft.",
        "19": "Schwarz 19 (D2) sichert die Ecke unten links fest – solide, ganz im Stil Shūsakus.",
        "23": "Schwarz 23 (E5) kommt zwischen den weißen Steinen heraus und stärkt die Gruppe unten links.",
        "29": "Schwarz 29 (F11) verstärkt die schwarzen Steine links und blickt zugleich zur Mitte.",
        "30": "Weiß 30 (H4) dehnt sich unten aus, setzt die schwarze Gruppe links unter Druck und baut eigenes Gebiet.",
        "31": "Schwarz 31 (O3) nähert sich der weißen Ecke unten rechts.",
        "33": "Schwarz 33 (R3) legt sich an den weißen Eckstein. Von hier baut Schwarz außen, während Weiß auf der dritten Linie am Rand entlangkriecht.",
        "43": "Schwarz 43 (Q8). Eine dicke schwarze Mauer zieht sich nun die rechte Seite hinab. Weiß hat Gebiet in Ecke und Rand, Schwarz Stärke nach außen.",
        "44": "Weiß 44 (L17) setzt sich zwischen die schwarzen Steine oben, damit das schwarze Gebiet nicht zu groß wird.",
        "50": "Weiß 50 (R18) schlüpft unter die schwarze Ecke oben rechts und zielt auf das Eckgebiet.",
        "51": "Schwarz 51 (P13). Mit der Mauer im Rücken rahmt Schwarz ein großes Gebiet von rechts zur Mitte ein.",
        "52": "Weiß 52 (D10) springt zwischen die schwarzen Steine an der linken Seite. Dort verknäueln sich die Steine.",
        "63": "Schwarz 63 (B10) spielt am linken Rand, damit die weißen Steine dort keine Basis bilden.",
        "65": "Schwarz 65 (G3) dringt auch unten ins weiße Gebiet ein und verkleinert es.",
        "73": "Schwarz 73 (K17) festigt die schwarzen Steine oben und setzt den weißen Stein von Zug 44 unter Druck.",
        "76": "Weiß 76 (P11) springt ins schwarze Gebiet an der rechten Seite. Ob dieser Stein lebt oder stirbt, entscheidet viel.",
        "77": "Schwarz 77 (Q11) antwortet von der Mauerseite und drängt Weiß zur Mitte – ruhige Verteidigung, die zugleich angreift, typisch Shūsaku.",
        "80": "Weiß 80 (N10) flieht in die Mitte, um der schwarzen Verfolgung zu entkommen.",
        "85": "Schwarz 85 (N12) greift weiter an und vergrößert dabei das eigene Gebiet oben und rechts. Durch Angriff Gewinn machen – geschickt.",
        "91": "Schwarz 91 (J7) spielt über den weißen Steinen unten und deckelt das weiße Gebiet auch von der Mitte her.",
        "100": "Weiß 100 (S17) versucht etwas in der Ecke oben rechts, um das schwarze Eckgebiet zu verkleinern.",
        "119": "Schwarz 119 (R17) verteidigt die Ecke oben rechts fest und wehrt den weißen Versuch ab.",
        "122": "Weiß 122 (G6) geht außen um die schwarzen Steine unten links herum, um sie von der schwarzen Mitte abzuschneiden.",
        "131": "Schwarz 131 (M5) treibt einen Keil ins weiße Gebiet in der Mitte des unteren Rands.",
        "140": "Weiß 140 (B4) versucht etwas in der schwarzen Ecke unten links. Am linken Rand beginnt ein enger Schlagabtausch.",
        "156": "Weiß 156 (A8) schlägt zwei schwarze Steine. Der Kampf am linken Rand beruhigt sich, nachdem beide etwas genommen haben.",
        "158": "Weiß 158 (L10). Weiß hat noch Steine in der Mitte und versucht, das schwarze Gebiet dort zu verkleinern.",
        "162": "Weiß 162 (O12) schlägt einen schwarzen Stein. Trotzdem bleibt das schwarze Gebiet rechts groß.",
        "172": "Weiß 172 (K18). Ab hier ist Endspiel, zuerst wird die Grenze am oberen Rand festgelegt.",
        "186": "Weiß 186 (T16) knabbert am schwarzen Gebiet am Rand oben rechts. Im Endspiel spielen beide zuerst die größten Punkte.",
        "205": "Schwarz 205 (Q18) schließt den rechten Teil des oberen Rands und legt das Gebiet dort fest.",
        "223": "Schwarz 223 (P10) legt die Grenze zwischen dem schwarzen Gebiet rechts und den in die Mitte geflohenen weißen Steinen fest.",
        "233": "Schwarz 233 (Q9) schlägt einen weißen Stein. Das schwarze Gebiet rechts ist nun fast vollständig sicher.",
        "239": "Schwarz 239 (A6) schlägt einen Stein, und am linken Rand entsteht ein Ko. Der Kampf um einzelne Punkte geht bis zum Schluss.",
        "260": "Weiß 260 (T6) schlägt einen Stein, und am Rand unten rechts entsteht ein weiteres Ko. Schwarz schlägt mit 263 (T5) zurück.",
        "267": "Nach 267 Zügen ist Schluss: Schwarz gewinnt mit 11 Punkten. Keine Abenteuer – Shūsaku griff an und ließ sein Gebiet ganz natürlich wachsen, ein typischer Shūsaku-Sieg. Es war der erste seiner 19 Siege in Folge bei den Schlosspartien."
      } },
    "shilin": { "t": "Die Partie aus dem Shilin Guangji", "w": "Rot (Name nicht überliefert)", "b": "Schwarz (Name nicht überliefert)", "ev": "Alltagsenzyklopädie Shilin Guangji: „Sieg nach Überlassen des ersten Zugs, Kanonen auf derselben Seite“", "d": "13. Jahrhundert", "pl": "China (Song–Yuan)", "lead": "Diese Aufzeichnung stammt aus dem Shilin Guangji, einer Alltagsenzyklopädie, die Chen Yuanjing am Ende der Song- und zu Beginn der Yuan-Zeit zusammenstellte. Sie gilt als eine der ältesten erhaltenen vollständigen Xiangqi-Partien. Es ist eine Musterpartie, in der die stärkere Seite der anderen den ersten Zug überlässt – und in nur neun Zügen fängt das schwarze Pferd den roten Wagen.",
      c: {
        "0": "Diese Aufzeichnung ist über 700 Jahre alt und stammt aus der Zeit zwischen Song- und Yuan-Dynastie. Sie steht im Spiele-Kapitel der Enzyklopädie Shilin Guangji und gilt als eine der ältesten vollständigen Xiangqi-Partien, die wir noch haben. Die Namen der Spieler sind nicht überliefert. Der Titel sagt, dass der Stärkere dem Schwächeren „den ersten Zug überließ“ – es ist also eine Lehrpartie, die zeigt, wie Rot, das beginnt, verliert. Rot steht unten und zieht zuerst.",
        "1": "Rot stellt die rechte Kanone auf die Mittellinie. Das ist die Mittelkanone, die direkt auf den schwarzen General zielt – bis heute eine der stärksten Eröffnungen. Man sieht: Schon vor 700 Jahren wurde sie gespielt.",
        "2": "Schwarz antwortet ebenfalls mit einer Kanone in die Mitte, die beiden Kanonen stehen sich gegenüber. Ziehen beide die Kanone auf derselben Seite, heißt das „gleichgerichtete Kanonen“. Das Kanonenduell ist seit Jahrhunderten beliebt.",
        "3": "Rot zieht ein Pferd heraus, um den mittleren Soldaten zu decken. Dieser Soldat wird von der schwarzen Kanone bedroht und braucht einen Beschützer. Zugleich macht sich das Pferd bereit, nach vorn zu kommen.",
        "4": "Schwarz macht dasselbe und deckt den mittleren Soldaten mit einem Pferd. Beide Seiten bauen zuerst eine feste Grundlage.",
        "5": "Rot zieht den rechten Wagen einen Schritt zur Seite auf eine offene Linie. Der Wagen ist die stärkste Figur – er soll früh arbeiten.",
        "6": "Schwarz bringt das zweite Pferd heraus und lässt die Wagen vorerst zu Hause. Der Plan: erst Figuren nach vorn bringen. Aber ein Wagen, der spät herauskommt, lässt sich später schwer im Angriff einsetzen.",
        "7": "Der rote Wagen stürmt über den Fluss ins schwarze Lager. Er will schwarze Figuren bedrohen, doch die anderen roten Figuren stehen noch zu Hause – der Angriff ist etwas überhastet. Erst das linke Pferd oder den linken Wagen zu entwickeln, wäre auch möglich gewesen.",
        "8": "Schwarz rückt den Soldaten auf Linie 3 einen Schritt vor. So öffnet es dem Pferd einen Weg, um später nach vorn zu springen. Schwarz lädt den roten Wagen fast ein zu kommen.",
        "9": "Der rote Wagen schlägt einen Soldaten und zielt nun auf das schwarze Pferd dahinter. Eine Figur gewinnen und die nächste bedrohen – das sieht toll aus. Aber der Wagen ist weit vorgeprescht und hat keine Freunde in der Nähe. Ein Wagen allein im feindlichen Lager lässt sich leicht jagen.",
        "10": "Das schwarze Pferd springt nach vorn. Es flieht vor dem Wagen und nähert sich zugleich dem roten Lager – zwei Aufgaben mit einem Zug. Dieses Pferd wird der Star der Partie.",
        "11": "Rot zieht den Wagen einen Schritt zurück, um das Pferd von der Seite anzugreifen. Der Wagen schlägt auch aus der Ferne, also kann das Pferd nicht ausruhen. Trotzdem entwickelt dieser Zug keine andere rote Figur.",
        "12": "Das schwarze Pferd zieht weiter vor und überquert den Fluss ins rote Lager. Jedes Mal, wenn es vor dem Wagen flieht, kommt es dem roten General näher.",
        "13": "Rot rückt einen Soldaten vor, um dem eigenen Pferd den Weg zu öffnen. Die Idee: das Pferd herausbringen und gegen das schwarze tauschen. Doch das gibt Schwarz Zeit, noch weiter vorzudringen.",
        "14": "Schwarz hebt einen Elefanten und greift den roten Wagen an. Mit einer Verteidigungsfigur den feindlichen Wagen zu vertreiben, ist sehr sparsam. Rot muss den Wagen wieder ziehen, und Schwarz gewinnt noch ein Tempo.",
        "15": "Der rote Wagen gleitet zur Seite und schlägt einen weiteren Soldaten. Rot hat nun zwei Soldaten mehr – doch das ist der Verlustzug. Der Wagen ist weit weg von seinem General und kann nicht mehr zur Verteidigung zurück. Rot hätte sich gegen das Pferd schützen müssen, etwa indem es den Wagen heimholt.",
        "16": "Das schwarze Pferd dringt tiefer ein und greift den roten Wagen an. Und mehr noch: Springt es noch einmal, gibt es dem roten General Schach und greift zugleich den Wagen in Rots Ecke an. Ein einziges Pferd hat zwei Drohungen auf einmal geschaffen.",
        "17": "Rot jagt das Pferd mit dem Wagen. Doch es lässt sich nicht mehr aufhalten. Um den roten General herum ist niemand mehr, der helfen kann.",
        "18": "Das Pferd springt hinein – Schach! Es greift auch den Wagen in Rots Ecke an; weicht der General aus, geht der Wagen verloren. Nur neun Züge, doch die Partie zeigt, was mit einem Wagen passiert, der allein vorstürmt, und warum Figuren zusammen kämpfen müssen. Schon vor 700 Jahren dachten Spieler auf demselben Brett über dieselben Dinge nach."
      } },
    "qima13": { "t": "Das Pferdeopfer in dreizehn Zügen (Juzhongmi)", "w": "Rot (Name nicht überliefert)", "b": "Schwarz (Name nicht überliefert)", "ev": "Juzhongmi, Band 1, Partie 1", "d": "1632 (erschienen)", "pl": "China (Ming)", "lead": "Dies ist die allererste Partie im Juzhongmi („Das Geheimnis in der Mandarine“), einem Xiangqi-Buch, das Zhu Jinzhen in der Ming-Zeit 1632 herausgab. Rot lässt Schwarz ein Pferd umsonst schlagen, stürmt währenddessen hinein und setzt in dreizehn Zügen matt. Als „Pferdeopfer in dreizehn Zügen“ ist sie fast 400 Jahre später noch immer beliebt.",
      c: {
        "0": "Das ist Partie 1 des Juzhongmi, eines Buchs, das 1632 gegen Ende der Ming-Dynastie gedruckt wurde. Zusammen mit dem späteren Pflaumenblüten-Handbuch gilt es als einer der zwei großen Klassiker des Xiangqi. Es ist keine echte Wettkampfpartie, sondern ein Lehrbeispiel für einen Plan – deshalb gibt es keine Spielernamen. Rot steht unten und beginnt, und nach nur dreizehn Zügen ist alles vorbei.",
        "1": "Rot stellt die rechte Kanone in die Mitte. Das ist die Mittelkanone, die den schwarzen General fixiert. Das Juzhongmi ist berühmt dafür, den Angriff mit dieser Eröffnung genau untersucht zu haben.",
        "2": "Schwarz stellt die Kanone auf derselben Seite ebenfalls in die Mitte. Das sind „gleichgerichtete Kanonen“, die frontal aufeinanderprallen. Jede Seite zielt auf den mittleren Soldaten der anderen.",
        "3": "Rot zieht ein Pferd heraus, um den mittleren Soldaten zu decken. Es schützt den Soldaten, auf den die schwarze Kanone zielt, und das Pferd beginnt zu arbeiten.",
        "4": "Auch Schwarz deckt den mittleren Soldaten mit einem Pferd. Bis hierhin haben beide Seiten dieselbe Form.",
        "5": "Rot zieht den rechten Wagen nur einen Schritt vor. So kann er im nächsten Zug seitwärts fahren. Einen Wagen, der so seitwärts zieht, nennt man „Querwagen“ – er kann schnell auf jeden Flügel wechseln.",
        "6": "Schwarz zieht den Wagen einen Schritt zur Seite, damit er gerade das Brett hinauffahren kann. Das ist ein „gerader Wagen“. Querwagen gegen geraden Wagen – zwei Arten, den Wagen einzusetzen, stehen sich gegenüber.",
        "7": "Der rote Querwagen schwenkt auf eine Linie links. Diese Linie verläuft direkt neben dem schwarzen Berater, wo die Verteidigung dünn ist. Rot bereitet den Einbruch vor.",
        "8": "Der gerade schwarze Wagen überquert den Fluss und dringt tief ins rote Lager ein. Schwarz will mit einem eigenen Angriff antworten. Aber dieser Zug greift eilig an, bevor er verteidigt.",
        "9": "Der rote Wagen fährt tief ins schwarze Lager. Er steht auf dem „Auge“ des Elefanten, dem Punkt, über den der Elefant ziehen muss – so kann sich der schwarze Elefant nicht bewegen. Direkt neben dem Berater ist er dem General jetzt sehr nahe.",
        "10": "Schwarz bringt das zweite Pferd an den Rand. Teil der Idee ist, den roten Wagen am seitlichen Eindringen zu hindern.",
        "11": "Hier ist das Pferdeopfer! Rot hebt den anderen Wagen einen Schritt an. Dadurch hat das Pferd in der linken Ecke keinen Beschützer mehr, und die schwarze Kanone kann es umsonst schlagen. Aber für ein Pferd gewinnt Rot Zeit, beide Wagen schnell in den Angriff zu bringen.",
        "12": "Die schwarze Kanone schlägt das rote Pferd. Es sieht aus, als hätte Schwarz eine Figur gewonnen. Doch diese Kanone ist jetzt weit weg und kann nicht verteidigen. Es heißt, hier wäre es besser gewesen, statt zu schlagen einen Berater hochzuziehen und die Verteidigung zu stärken.",
        "13": "Die rote Kanone zieht vor. Mit der schwarzen Mittelkanone als „Schirm“ zum Überspringen zielt sie nun auf das schwarze Pferd dahinter. Die Kanone ist eine seltsame Figur, die schlägt, indem sie genau eine Figur überspringt.",
        "14": "Schwarz zieht das Pferd zurück, um zu fliehen. Aber dieses Pferd war die wichtige Figur, die den mittleren Soldaten deckte. Durch die Flucht entsteht ein Loch im Zentrum. Schwarz hatte andere Verteidigungen, doch dies war die schlechteste Wahl.",
        "15": "Die rote Kanone schlägt den mittleren Soldaten – Schach! Ohne das schwarze Pferd war die Mitte weit offen. Von hier an rollt der rote Angriff.",
        "16": "Schwarz hebt einen Berater an, um vor dem General zu blocken. Das ist die einzige gute Art, das Schach abzuwehren.",
        "17": "Der zweite rote Wagen kommt auf dieselbe Linie. Zwei Wagen hintereinander auf einer Linie sind extrem stark. Der Plan: tief ins schwarze Lager einbrechen.",
        "18": "Der schwarze General weicht zur Seite aus. Sonst würde er von beiden roten Wagen auf derselben Linie fixiert.",
        "19": "Der vordere rote Wagen schlägt den schwarzen Berater – Schach! Der andere Berater schlägt ihn sofort, aber das gehört zum Plan. Rot gibt einen Wagen her, um die Wächter des schwarzen Generals zu zerschlagen. Was für ein mutiger Zug!",
        "20": "Schwarz schlägt den Wagen mit dem Berater. An Material liegt Schwarz weit vorn. Doch das Haus des Generals ist noch leerer geworden.",
        "21": "Der letzte rote Wagen zieht auf die Linie des Generals – wieder Schach. Der schwarze General hat kaum noch Figuren, die ihn schützen.",
        "22": "Schwarz stellt eine Kanone vor den General, um das Schach zu blocken. Eine Figur dazwischenzustellen heißt dazwischenziehen.",
        "23": "Der rote Wagen schlägt diese Kanone – wieder Schach. Der Wagen schlägt weiter schwarze Figuren und treibt den General in die Enge.",
        "24": "Der schwarze General kann nur in die Mitte zurück. Alle anderen Punkte sind von roten Figuren besetzt oder bedroht.",
        "25": "Schließlich stellt sich die rote Kanone in die Mitte: zwei Kanonen auf einer Linie – Schach. Die vordere Kanone ist der Schirm, die hintere trifft den General: ein „Doppelkanonen“-Matt. Der schwarze General kann nirgends hin, und Rot gewinnt. Mit nur einem geopferten Pferd gewann Rot in dreizehn Zügen. Seit 400 Jahren lehrt diese Partie, dass Zeit und aktive Figuren mehr zählen können als die Zahl der Figuren."
      } }
  },
  "ru": {
    ui: {"lead":"Великие партии — ход за ходом. Следите за знаменитыми партиями на доске, а Musowl объяснит каждый ход.","all":"Все","k_chess":"Шахматы","k_shogi":"Сёги","k_go":"Го","k_xiangqi":"Сянци","side_r":"Красные","res_r":"Победа красных","back":"Назад к великим партиям","start":"В начало","prev":"На ход назад","next":"На ход вперёд","end":"В конец","play":"Воспроизвести","pause":"Пауза","moves":"Ходы","move":"Ход {n}","startpos":"Начальная позиция","nextnote":"Следующий комментарий (ход {n})","quiet":"К этому ходу нет комментария.","guide":"Musowl","keys":"← → — по одному ходу","result":"Результат","r_event":"Партия","r_date":"Год","r_place":"Место","side_w":"Белые","side_b":"Чёрные","side_s":"Сэнтэ","side_g":"Готэ","side_B":"Чёрные","side_W":"Белые","res_w":"Победа белых","res_b":"Победа чёрных","res_d":"Ничья","res_s":"Победа сэнтэ","res_g":"Победа готэ","credit":"Ходы — это общеизвестная запись каждой партии. Комментарии написал Musowl из музея."},
    "opera": { "t": "Партия в опере", "w": "Пол Морфи", "b": "Герцог Карл II Брауншвейгский и граф Изуар", "ev": "Сыграна в ложе Парижской оперы (двое союзников советовались друг с другом)", "d": "1858", "pl": "Франция (Париж)", "lead": "Молодой американский чемпион против двух аристократов прямо во время оперного спектакля: семнадцать ходов. Быстро вывести фигуры, без колебаний жертвовать ими и закончить совсем малыми силами. Ни одна партия не встречается в шахматных книгах чаще.",
      c: {
        "0": "Париж, 1858 год. Двадцатиоднолетний американец Пол Морфи побеждал одного сильного европейского шахматиста за другим. В тот вечер в ложе оперы герцог Брауншвейгский и граф Изуар вместе взяли чёрные и бросили ему вызов, советуясь над каждым ходом. Говорят, Морфи хотел закончить поскорее, чтобы смотреть на сцену. Эти семнадцать ходов полны основ: быстро выводить фигуры и прятать короля в безопасность.",
        "1": "Белые двигают королевскую пешку на два поля. Она смотрит на d5 и e5 в центре и открывает дорогу слону и ферзю.",
        "2": "Чёрные тоже играют e5. Пешки стоят друг против друга в центре, и белая пешка дальше не пройдёт.",
        "3": "Конь выходит на f3 и нападает на пешку e5. Хороший ход: он развивает фигуру и заставляет соперника думать о защите.",
        "4": "Чёрные защищают e5 ходом d6. Это защита Филидора. Надёжно, но слону f8 становится тесновато.",
        "5": "Белые играют d4 — ещё одна пешка в центр, против e5. Чёрным надо решить: брать или защищать.",
        "6": "Чёрный слон идёт на g4. Он давит на коня f3, стоящего на одной линии с белым ферзём d1. Если конь уйдёт, ферзь пропадёт, поэтому конь не может идти за e5.",
        "7": "Белые берут на e5 пешкой. Если бы чёрные сразу взяли обратно пешкой d6, белые разменяли бы ферзей, а потом конь забрал бы пешку e5. Поэтому чёрные сначала хотят избавиться от коня f3.",
        "8": "Чёрные берут коня слоном. Теперь можно спокойно отыграть e5. Но отдав только что выведенного слона за коня, чёрные отстают в развитии.",
        "9": "Белые берут обратно ферзём, который уже работает близко к центру, а чёрные почти не вывели фигур.",
        "10": "Чёрные берут пешкой, материал равный. Но по развитым фигурам белые впереди.",
        "11": "Слон на c4. Вместе с ферзём f3 он целится в f7. Это поле защищает только король, оно слабое: взятие на f7 было бы матом.",
        "12": "Чёрные ставят коня на f6 и закрывают линию f. Без этого ферзь брал бы на f7 с матом. Защищаться, развивая фигуры, — правильный ответ.",
        "13": "Ферзь переходит на b3 и атакует сразу f7 и b7. Ход с двумя угрозами силён: соперник не успеет защитить обе.",
        "14": "Чёрные ставят ферзя на e7, защищая f7, и отдают b7. Но теперь ферзь загораживает слона f8.",
        "15": "Морфи не берёт пешку b7, а выводит коня. После взятия ферзь оказался бы далеко. Выбрать быстрое развитие вместо пешки — в этом весь Морфи.",
        "16": "Чёрные играют c6: контролируют d5 и b5 и открывают ферзю путь на b6.",
        "17": "Слон на g5 связывает коня f6. Если конь уйдёт, ферзь e7 за ним будет взят. Чёрным фигурам всё труднее двигаться.",
        "18": "Чёрные играют b5, чтобы прогнать слона c4. Они получают место на ферзевом фланге, но открывают брешь для белых фигур.",
        "19": "Конь жертвуется и берёт на b5! Вместо отступления слоном Морфи продолжает атаку. Пока чёрный король в центре, это очень опасно для чёрных.",
        "20": "Чёрные берут коня и имеют лишнего коня. Но их король всё ещё на e8, а белые фигуры продолжают подтягиваться.",
        "21": "Слон на b5 — шах! Чёрный король застрял в центре. У белых две пешки за коня, и они идут прямо на короля.",
        "22": "Чёрные закрываются конём на d7. Но этот конь связан: если он уйдёт, чёрный король окажется под шахом. Теперь белые целятся в d7.",
        "23": "Белые делают длинную рокировку. Король в безопасности, а ладья одновременно встаёт на d1 и целится в d7. Один ход и защищает, и атакует — превосходно.",
        "24": "Чёрные ставят ладью на d8, защищая d7. Рокировать они всё ещё не могут, а ладья h8 и слон f8 бездействуют.",
        "25": "Ладья жертвуется и берёт на d7! Белые отдают ладью, чтобы убрать одного из защитников.",
        "26": "Чёрные берут обратно ладьёй. Теперь и эта ладья на d7 связана: если она уйдёт, слон b5 объявит шах чёрному королю.",
        "27": "Вторая ладья приходит на d1 и снова атакует d7. Теперь белых фигур, нападающих на d7, больше, чем чёрных защитников.",
        "28": "Чёрный ферзь идёт на e6, предлагая размен ферзей, чтобы прогнать белого ферзя с b3 и помочь d7. Но уже поздно.",
        "29": "Слон берёт на d7 с шахом. Белые убирают защитников чёрных одного за другим.",
        "30": "Чёрные берут обратно конём. Конь ушёл с f6, и диагональ от слона g5 до d8 открыта. Эта диагональ пригодится в самом конце.",
        "31": "Ферзь жертвуется на b8 с шахом! Это самый знаменитый ход партии. Чёрные должны брать конём, а когда конь уходит с d7, линия d открывается.",
        "32": "Чёрные берут конём. Теперь ни одна чёрная фигура не защищает d8.",
        "33": "Ладья на d8 — мат! Слон g5 поддерживает d8, а чёрный король зажат собственными фигурами. Белые отдали ферзя, ладью и слона и закончили всего ладьёй и слоном. Быстро развиваться, прятать короля и атаковать, пока король соперника в центре, — эта знаменитая партия собрала все эти важные идеи."
      } },
    "reti1910": { "t": "Мат Рети", "w": "Рихард Рети", "b": "Савелий Тартаковер", "ev": "Лёгкая партия (не турнир)", "d": "1910", "pl": "Австрия (Вена)", "lead": "Два будущих великих мастера, лёгкая партия в Вене, одиннадцать ходов. Белые отдают ферзя и заканчивают двойным шахом: две фигуры шахуют одновременно. Этот мат назван по имени белых — мат Рети.",
      c: {
        "0": "Вена, 1910 год. Белыми играет двадцатилетний Рихард Рети, чёрными — Савелий Тартаковер. Оба стали одними из сильнейших в мире и известны тем, что принесли в шахматы новые идеи. Это была не турнирная, а лёгкая партия на небольшую ставку. Она короткая, но ясно показывает, почему короля нужно рано прятать в безопасное место.",
        "1": "Белые двигают королевскую пешку на два поля. Заняв центр, легче выводить фигуры, стоящие сзади. Слону и ферзю открыта дорога.",
        "2": "Чёрные играют c6. Вместо того чтобы сразу идти в центр, они готовят d5 и нападение на пешку e4. Это надёжное начало называется защитой Каро-Канн.",
        "3": "Белые ставят и вторую пешку на d4. Две пешки рядом в центре — у белых много пространства. Чёрные постараются их разбить.",
        "4": "Как и задумано, d5. Пешка бросает вызов e4: «могу тебя взять». Белым надо решить: защищать, продвигать или меняться.",
        "5": "Белые выводят коня и защищают e4. Фигура выведена и защищает одновременно — время не потеряно.",
        "6": "Чёрные берут пешку e4. Размен центральных пешек уменьшает центр белых.",
        "7": "Белые берут обратно конём, и он встаёт в центр доски. Конь в центре достаёт много полей и очень силён.",
        "8": "Чёрные выводят коня напротив коня e4. Здесь часто играют слоном на f5, но чёрные предлагают размен коней.",
        "9": "Ферзь рано выходит на d3, защищая коня e4. Обычно ферзя так рано не выводят, но у белых есть план. Запомни: этот ферзь стоит на линии d, напротив чёрного короля.",
        "10": "Чёрные играют e5 и отдают пешку, чтобы открыть линии слону и ферзю. Активный ход, начинающий борьбу в центре.",
        "11": "Белые берут пешку e5. Подарок принят, но теперь у чёрного ферзя больше свободы.",
        "12": "Шах! Чёрный ферзь с a5 по диагонали целится в короля e1. Заодно он хочет вернуть пешку e5 — две задачи одним ходом. Белым нужно закрыться.",
        "13": "Белые закрываются слоном на d2. Ферзь мог бы взять слона, но белый ферзь надёжно его защищает.",
        "14": "Чёрные вернули пешку, материал снова равный. И этот ферзь смотрит по линии e на коня e4 и короля за ним. Если конь уйдёт, король окажется под шахом, — конь связан. Кажется, чёрные вот-вот его выиграют.",
        "15": "Белые делают длинную рокировку. Король уходит с линии e, и конь снова свободен. Одновременно ладья встаёт на d1: ладья d1, ферзь d3 и поле d8 рядом с чёрным королём оказываются на одной линии. Это ловушка белых.",
        "16": "Чёрные берут коня e4 и вроде бы выигрывают фигуру. Но чёрный король всё ещё на e8 и не рокировал. Белые фигуры выстроились по линии d, а чёрный король без защиты. Этот проигрывающий ход — поворотный момент партии.",
        "17": "Ферзь на d8, шах! Белые отдают самую сильную фигуру даром. Взять её может только король. Позволив её взять, белые вытаскивают короля на опасное поле d8.",
        "18": "Чёрные вынуждены брать королём — других способов уйти от шаха нет. Король стоит на d8, а за ним ждёт ладья d1.",
        "19": "Слон идёт с d2 на g5 с шахом и одновременно открывает путь ладье d1, которая тоже шахует по линии d. Две фигуры шахуют сразу — двойной шах. От него не спастись ни взятием одной фигуры, ни закрытием: король должен бежать.",
        "20": "Король бежит на c7. На e8 ладья пришла бы на d8 с матом. Куда бы ни пошёл король, у белых готов последний удар.",
        "21": "Слон на d8 — мат по диагонали королю на c7! Слона защищает ладья d1, так что король не может его взять. Поля b8, c8, b7 и c6 заняты собственными фигурами чёрных, а ладья держит d6 и d7. Всего за одиннадцать ходов белые отдали ферзя и победили двумя лёгкими фигурами. Партия показывает, как опасно хватать материал, не сделав рокировку. По некоторым записям, чёрные сдались на ход раньше."
      } },
    "immortal": { "t": "Бессмертная партия", "w": "Адольф Андерсен", "b": "Лионель Кизерицкий", "ev": "Лёгкая партия в перерыве Лондонского турнира 1851 года", "d": "1851", "pl": "Великобритания (Лондон)", "lead": "Лондон, первый международный шахматный турнир: партия, сыгранная в перерыве. Белые отдают слона, обе ладьи и под конец ферзя, а мат ставят тремя оставшимися лёгкими фигурами. Говорят, что чёрные сдались раньше, и последние ходы — это финал, который показал белый.",
      c: {
        "0": "Лондон, 1851 год. В перерыве турнира немец Андерсен (белые) и Кизерицкий, звезда Парижа (чёрные), сыграли лёгкую партию.",
        "1": "Белые двигают королевскую пешку на два поля.",
        "2": "Чёрные отвечают так же.",
        "3": "f4! Белые предлагают пешку — это королевский гамбит. Задача — увести чёрную пешку e5 из центра.",
        "4": "Чёрные берут пешку.",
        "5": "Слон выходит и смотрит на f7 рядом с чёрным королём.",
        "6": "Шах! Без белой пешки f диагональ от h4 до e1 открыта.",
        "7": "Король отходит в сторону. Теперь белые уже никогда не смогут рокировать.",
        "8": "Чёрные тоже отдают пешку, чтобы заманить слона на b5.",
        "9": "Белые берут.",
        "10": "Выходит конь и нападает на пешку e4.",
        "11": "Белые выводят коня и прогоняют ферзя с h4.",
        "12": "Ферзь отступает на h6.",
        "13": "d3 защищает e4 и открывает путь слону c1.",
        "14": "Конь на h5. План — прыгнуть на g3 с шахом и напасть на ладью h1.",
        "15": "Белый конь идёт на h4, чтобы прыгнуть на f5 и потревожить чёрного ферзя.",
        "16": "Чёрный ферзь идёт на g5 и нападает на коня h4.",
        "17": "Конь на f5 — хорошее поле под защитой пешки e4. Он также смотрит на пешку g7.",
        "18": "c6 пытается прогнать слона b5.",
        "19": "Белые не спасают слона: g4 гонит коня h5.",
        "20": "Конь возвращается на f6.",
        "21": "Ладья на g1 защищает пешку g4. Слона b5 белые просто оставляют. Смело!",
        "22": "Чёрные берут слона и имеют лишнюю фигуру.",
        "23": "Пешка h начинает гонять чёрного ферзя.",
        "24": "Ферзь идёт на g6.",
        "25": "h5 снова гонит ферзя.",
        "26": "Ферзю остаётся только вернуться на g5. Полей у него всё меньше.",
        "27": "Белый ферзь идёт на f3. Если затем слон возьмёт на f4, чёрный ферзь может попасть в ловушку.",
        "28": "Чёрные возвращают коня на g8, чтобы ферзь мог уйти на f6.",
        "29": "Слон берёт пешку f4 и нападает на ферзя.",
        "30": "Ферзь убегает на f6.",
        "31": "Выходит конь, чтобы прыгнуть на d5 и напасть на ферзя.",
        "32": "Слон выходит и целится в ладью g1.",
        "33": "Конь на d5 нападает на ферзя f6 и поле c7. Ладью g1 белым не жалко.",
        "34": "Ферзь берёт пешку b2 и нападает на ладью a1.",
        "35": "Слон на d6! Белые отдают обе ладьи. Взамен их фигуры плетут сеть вокруг чёрного короля.",
        "36": "Чёрные берут ладью g1.",
        "37": "e5! Эта пешка перекрывает диагональ ферзя b2 к g7. Чёрный ферзь больше не может помочь своему королю.",
        "38": "Чёрные с шахом берут и вторую ладью.",
        "39": "Король идёт на e2. У белых остались только ферзь, два коня и слон.",
        "40": "Конь идёт на a6, защищая c7. Говорят, примерно здесь чёрные сдались, а остальное — финал, показанный белыми.",
        "41": "Конь берёт на g7 с шахом.",
        "42": "Король бежит на d8.",
        "43": "Ферзь жертвуется на f6 с шахом! Уходит и последняя тяжёлая фигура.",
        "44": "Чёрные вынуждены брать конём.",
        "45": "Слон на e7 — мат! Конь d5 держит e7 и c7, конь g7 держит e8. Белые выигрывают одним слоном и двумя конями."
      } },
    "mimiaka": { "t": "Партия покрасневших ушей", "w": "Хонинбо Сюсаку", "b": "Иноуэ Геннан Инсэки", "ev": "Партия в Осаке (игралась три дня)", "d": "1846", "pl": "Япония (Осака)", "lead": "17-летний Сюсаку (4 дан) играл с Геннаном (8 дан), одним из сильнейших мастеров того времени. Говорят, что после 127-го хода у Геннана покраснели уши. Коми тогда не было: чёрные выиграли 2 очка.",
      c: {
        "0": "Осака, 1846 год. Сюсаку играет чёрными, Геннан — белыми. Накануне они начали партию с форой в два камня, но прервали её; теперь Сюсаку играет чёрными без форы.",
        "1": "Чёрные 1 — на пункте 3-4 в правом верхнем углу (R16). Отсюда легко забрать угол.",
        "2": "Белые 2 — пункт 3-4 в левом верхнем углу (D17). Сначала соперники делят пустые углы.",
        "5": "Ходами 1, 3 и 5 чёрные заняли три угла, все на пунктах 3-4. Сюсаку любил такое начало, и потом его долго изучали.",
        "6": "Белые 6 на C14 у левого края. Вместо подхода к чёрному углу белые занимают сторону — довольно редкий выбор.",
        "7": "Чёрные 7 (E4) закрывают левый нижний угол вторым камнем. Такое «закрытие» делает угол очень прочным.",
        "8": "Белые 8 (R5) подходят к чёрному углу Q3. Справа внизу начинается большая борьба.",
        "10": "Белые 10 (O4) — тайся: камень накрывает чёрный по диагонали издалека. У этой формы огромное число вариантов, и Геннан её очень любил.",
        "11": "Ходом 11 (Q5) чёрные вступают в сложный вариант. Геннан хорошо знал тайся, так что нужно действовать осторожно.",
        "24": "Справа внизу камни переплелись, каждая сторона пытается разрезать другую. После белых 24 (N4) чёрным трудно выбраться наружу.",
        "25": "Чёрные 25 (N3). Позднейший разбор показывает, что здесь был ход получше. Даже мастеру было трудно.",
        "28": "Ходами 28 (M3) и 30 (L2) белые сразу бьют по слабости. Чёрные камни могут оказаться запертыми на узком участке внизу.",
        "31": "Чёрные 31 (M4) — важный ход. Он готовит будущее ко (борьбу «взял — забрал обратно»), создавая угрозы, на которые белым придётся отвечать.",
        "36": "Белые 36 (N2). Перед началом ко белые сначала играют здесь. Хороший выбор момента.",
        "40": "Белые 40 (R1) снимают камень, и начинается ко. Сторона, потерявшая камень, не может сразу взять обратно и сначала делает угрозу в другом месте.",
        "41": "Чёрные 41 (O5) — угроза в ко. Это немного стоит, но лучше здесь ничего нет.",
        "53": "Чёрные 53 (R10) — изобретательная идея, до которой додумался бы не каждый. Ход бьёт по форме белых справа.",
        "60": "Белые 60 (S3) — крупный ход. После него и 62 (M1) белые сыграют с темпом.",
        "63": "После чёрных 63 (O1) долгая борьба справа внизу затихает. У белых территория внизу, у чёрных — толстая стена справа. Пока белые, похоже, сыграли лучше.",
        "67": "Чёрные 67 (L17). Опираясь на стену справа, чёрные строят большую сферу влияния вверху.",
        "72": "Белые 72 (P13) — превосходный ход. Камень над чёрной стеной не даёт чёрной сфере расти.",
        "74": "Отсюда примерно до 100-го хода Геннан не делает ни одного слабого хода. Он уходит от атак и держит камни связанными.",
        "83": "Чёрные 83 (H3) вторгаются в зону белых внизу, чтобы уменьшить её.",
        "96": "С белых 96 (R14) идёт тонкая борьба у чёрного угла справа вверху. Белые и здесь находят хорошую форму.",
        "107": "Чёрные 107 (P10) снимают белый камень. Чёрная группа справа теперь в безопасности.",
        "118": "Белые 118 (M19) снимают камень, и их группа вверху тоже живёт. Чёрная сфера вверху вышла меньше, чем хотелось.",
        "126": "Белые 126 (J5). Внизу белые толстые и тянутся к центру. Говорят, большинство наблюдавших профессионалов считали, что белые впереди.",
        "127": "Вот знаменитый ход «покрасневших ушей» — чёрные 127 (K11). Говорят, этот камень в центре работает сразу в четырёх направлениях: расширяет чёрную зону сверху, ослабляет толщину белых снизу, помогает чёрной группе справа и мешает белым расти влево.",
        "128": "В этот момент врач, наблюдавший за партией, заметил, что уши Геннана покраснели. Он мало понимал в го, но, как рассказывают, счёл это знаком волнения и предсказал победу чёрных.",
        "131": "Чёрные 131 (D10). Теперь чёрные вторгаются и на левую сторону белых, сокращая их территорию по всей доске.",
        "147": "Чёрные 147 (K10). Камень 127-го хода начинает работать: чёрные продвигаются между белыми группами в центре.",
        "160": "Белые 160 (H8). Белые защищают центральные камни и нацеливаются на чёрную группу слева внизу. Борьба всё ещё равная.",
        "167": "Чёрные 167 (C2) — точный ход. Чёрные камни в левом нижнем углу в безопасности, угроза белых исчезла.",
        "175": "Чёрные 175 (G4) снимают белый камень. Территория белых внизу не так велика, как казалась сначала.",
        "199": "Чёрные 199 (K7). Борьба в центре утихает, начинается ёсэ — уточнение границ, где важно каждое очко.",
        "212": "Ходами 212 (D19) и 216 (F19) белые снимают чёрные камни у верхнего края. В ёсэ никто не уступает.",
        "228": "Белые 228 (N12) создают ко в центре. Больше 80 ходов камни снимают по очереди на M13 и N13.",
        "236": "Белые 236 (T8), сыгранные во время ко, снимают камень. Некоторые аналитики считают, что, закончив ко здесь, белые сократили бы разрыв.",
        "275": "Чёрные 275 (T14) снимают два белых камня. Во время ко каждая сторона то выигрывает, то теряет в разных местах доски.",
        "299": "Чёрные 299 (J16) снимают сразу четыре белых камня. Верх надёжно остаётся за чёрными.",
        "311": "Чёрные 311 (M13) закрывают ко. Долгая борьба наконец окончена.",
        "325": "Партия заканчивается на 325-м ходу, подсчёт даёт чёрным перевес в 2 очка. Даже без коми победа 17-летнего над таким мастером, как Геннан, стала сенсацией, и имя Сюсаку прогремело."
      } },
    "evergreen": { "t": "Вечнозелёная партия", "w": "Адольф Андерсен", "b": "Жан Дюфрен", "ev": "Лёгкая партия (не турнир)", "d": "1852", "pl": "Германия (предположительно Берлин)", "lead": "Андерсен, автор «Бессмертной», через год сыграл ещё один шедевр. Как раз когда чёрные грозят матом, белые спокойно переводят ладью, затем отдают ферзя и заканчивают двойным шахом. Её называют «вечнозелёной», потому что она никогда не увянет.",
      c: {
        "0": "Партия, опубликованная в журнале в 1852 году. Белыми играл Андерсен, чёрными — его друг Дюфрен. Считается, что её сыграли в Берлине, но точной записи об этом нет.",
        "1": "Белые двигают королевскую пешку на два поля.",
        "2": "Чёрные отвечают так же.",
        "3": "Конь нападает на пешку e5.",
        "4": "Чёрные защищают e5 конём.",
        "5": "Слон выходит и смотрит на f7.",
        "6": "Чёрные тоже выводят слона.",
        "7": "b4! Жертва пешки — гамбит Эванса. Пока чёрные берут, белые укрепляют центр.",
        "8": "Чёрные берут пешку.",
        "9": "c3 гонит слона и готовит d4.",
        "10": "Слон отходит на a5.",
        "11": "d4 — белые занимают центр.",
        "12": "Чёрные берут пешку.",
        "13": "Белые не берут обратно, а рокируют. Безопасность короля и активность фигур важнее пешек.",
        "14": "Чёрная пешка доходит до d3, глубоко в лагерь белых.",
        "15": "Ферзь на b3. Вместе со слоном c4 он целится в f7.",
        "16": "Чёрные защищают f7 ферзём.",
        "17": "e5 гонит ферзя.",
        "18": "Ферзь уходит на g6.",
        "19": "Ладья на e1, на линию e, чтобы поддержать пешку e5.",
        "20": "Чёрные выводят коня, готовя рокировку.",
        "21": "Слон на a3 смотрит по диагонали на коня e7. Если конь уйдёт, слон достанет до f8, поэтому короткая рокировка чёрным теперь трудна.",
        "22": "Чёрные отдают пешку, чтобы отвлечь белые фигуры.",
        "23": "Ферзь берёт её.",
        "24": "Ладья на b8 гонит ферзя по линии b.",
        "25": "Ферзь уходит на a4.",
        "26": "Слон отступает на b6.",
        "27": "Выходит конь. Почти все белые фигуры в игре.",
        "28": "Чёрные выводят второго слона.",
        "29": "Конь на e4, с прицелом на f6.",
        "30": "Чёрный ферзь идёт на f5 и нападает на коня e4.",
        "31": "Слон берёт пешку d3 и защищает коня e4.",
        "32": "Ферзь на h5 целится в коня f3.",
        "33": "Конь жертвуется на f6 с шахом!",
        "34": "Чёрные берут пешкой.",
        "35": "Белые берут обратно пешкой и нападают на коня e7. По линии e на e7 смотрит и ладья e1.",
        "36": "Ладья на g8 целится в g2. Если ферзь с h5 возьмёт на f3, мат совсем близко.",
        "37": "Спокойный ход ладьёй на d1! Белый король в опасности, но вместо защиты белые нацеливаются на d7. Именно этот ход сделал партию «вечнозелёной».",
        "38": "Чёрные берут коня f3. Следующим ходом взятие на g2 было бы матом.",
        "39": "Но ход белых. Ладья берёт коня e7 с шахом!",
        "40": "Чёрные берут конём с c6. Теперь диагональ от a4 до d7 открыта.",
        "41": "Ферзь жертвуется на d7 с шахом!",
        "42": "Чёрные вынуждены брать королём.",
        "43": "Слон идёт на f5 с шахом и открывает линию d для ладьи d1 — двойной шах.",
        "44": "Король уходит на e8. На c6 слон дал бы мат на d7.",
        "45": "Слон на d7, шах.",
        "46": "Король уходит на f8.",
        "47": "Слон с a3 берёт коня e7 — мат! Слон d7 держит e8, а пешка f6 держит e7 и g7."
      } },
    "lasker1912": { "t": "Охота на короля", "w": "Эдвард Ласкер", "b": "Джордж Алан Томас", "ev": "Быстрая лёгкая партия в Шахматном клубе лондонского Сити", "d": "1912", "pl": "Великобритания (Лондон)", "lead": "Быстрая лёгкая партия в лондонском клубе. Белые отдают ферзя и гонят чёрного короля через всю доску — с g8 до g1. В разных записях первые ходы идут в немного разном порядке, но позиция после 10-го хода одна и та же.",
      c: {
        "0": "Октябрь 1912 года, Шахматный клуб лондонского Сити. Белыми играет Эдвард Ласкер, молодой инженер, только что приехавший из Германии, чёрными — Джордж Алан Томас, будущий чемпион Великобритании. Это была быстрая лёгкая партия. Она знаменита как «охота на короля»: чёрного короля гонят с g8 до самого g1 на другом краю доски. Позже Ласкер уехал в Америку и прославился своими шахматными книгами.",
        "1": "Белые начинают с d4 — ферзевой пешки. Она контролирует e5 и c5 и открывает путь слону c1.",
        "2": "Чёрные играют e6: сначала прочная позиция, с прицелом на f5 или d5.",
        "3": "Конь на f3. Он контролирует e5 и помогает защищать королевский фланг — самое естественное поле.",
        "4": "Чёрные играют f5 и контролируют e4, как в голландской защите. Но ход пешкой перед королём немного его ослабляет.",
        "5": "Второй конь идёт на c3, готовя e4 против пешки f5.",
        "6": "Чёрные выводят коня на f6: ещё сильнее держат e4 и готовят рокировку.",
        "7": "Слон на g5 целится в коня f6. Этот конь — важный защитник чёрного короля, и белые хотят убрать его пораньше.",
        "8": "Чёрные ставят слона на e7, защищая коня и приближаясь к рокировке.",
        "9": "Белые меняют слона на коня. Конь, защищавший чёрного короля, исчез.",
        "10": "Чёрные берут обратно слоном. Теперь слон f6 берёт на себя защиту королевского фланга.",
        "11": "e4! Белые бьют в пешку f5 и захватывают пространство в центре. Линии открываются, белые фигуры становятся подвижнее.",
        "12": "Чёрные берут пешку e4. Иначе белые сыграли бы e5 и оттеснили чёрные фигуры.",
        "13": "Конь берёт обратно и встаёт в центр, глядя на слона f6 и поля g5 и d6.",
        "14": "Чёрные играют b6, чтобы поставить слона на b7 и целиться по длинной диагонали в коня e4.",
        "15": "Конь на e5 — сильное поле в центре, откуда видны g4 и f7. Оба белых коня уже близко к королевскому флангу чёрных.",
        "16": "Чёрные рокируют. Король на g8. Но без пешки f вокруг короля много дыр.",
        "17": "Слон на d3. Пока ему мешает свой конь e4, но за ним стоит пешка h7. Как только конь e4 уйдёт, слон будет бить прямо в h7.",
        "18": "Чёрный слон идёт на b7 и целится по длинной диагонали в коня e4, сковывая белые фигуры.",
        "19": "Ферзь на h5 целится в пешку h7, которую защищает только чёрный король. Ферзь, слон и кони белых — все направлены на чёрного короля.",
        "20": "Чёрные ставят ферзя на e7. Он защищает слона f6 и готовит выход на c5, но чёрные не видят замысла белых. Нужно было играть h6 или брать коня e5. Это поворотный момент.",
        "21": "Ферзь жертвуется на h7 с шахом! Белые отдают самую сильную фигуру даром. Ласкер видел весь путь погони за королём до мата.",
        "22": "Чёрные вынуждены брать королём, и он оказывается на h7.",
        "23": "Конь берёт слона f6 с шахом. Одновременно освобождается e4, и слон d3 тоже шахует короля на h7 — двойной шах. Закрыться нельзя, король должен бежать.",
        "24": "Король идёт на h6. На h8 второй конь прыгнул бы на g6 с матом. Короля выталкивают всё дальше вперёд.",
        "25": "Второй конь прыгает с e5 на g4 с шахом, нападает на короля h6 и гонит его дальше.",
        "26": "Король идёт на g5: он покидает свой лагерь и идёт к белым.",
        "27": "Шах пешкой h! Даже пешки участвуют в охоте. Королю приходится идти вперёд.",
        "28": "Король идёт на f4. Он пересёк середину доски и входит в лагерь белых.",
        "29": "Снова шах — пешкой g. Две пешки закрывают королю путь назад.",
        "30": "Король идёт на f3, в самую гущу белых фигур.",
        "31": "Слон отходит с d3 на e2 с шахом. Короля загоняют ещё глубже.",
        "32": "Король идёт на g2. Белый король на e1 уже недалеко.",
        "33": "Ладья на h2 — шах. Наконец вступает и ладья.",
        "34": "Король наконец доходит до g1. Начав на g8, он дошёл до первой горизонтали на другом краю доски.",
        "35": "Белый король идёт с e1 на d2. Это открывает ладью a1, и она шахует короля g1 по первой горизонтали — мат! Длинная рокировка тоже давала мат, но Ласкер пошёл королём. В быстрой партии, отдав ферзя, белые четырнадцать ходов гнали короля в самый дальний угол своего лагеря. Очень редкая партия."
      } },
    "toketsu": { "t": "Партия с кровью", "w": "Акабоси Интэцу", "b": "Хонинбо Дзёва", "ev": "Сыграна в усадьбе князя Мацудайры Суо (четыре дня)", "d": "1835", "pl": "Япония (Эдо)", "lead": "Партия, рождённая борьбой за пост мэйдзин-годокоро — высший в японском го. Иноуэ Геннан Инсэки выставил своего ученика Акабоси Интэцу против мэйдзина Дзёвы. После четырёх дней борьбы Интэцу проиграл и, по преданию, закашлялся кровью у доски.",
      c: {
        "0": "1835 год. Чёрные — Акабоси Интэцу (7 дан), белые — мэйдзин Хонинбо Дзёва. Геннан выставил лучшего ученика, чтобы заявить: мэйдзин, проигравший седьмому дану, недостоин звания.",
        "1": "Чёрные 1 — пункт 3-4 слева внизу (C4). Интэцу начинает спокойно.",
        "4": "После четырёх ходов в каждом углу по камню: белые справа внизу и слева вверху, чёрные слева внизу и справа вверху.",
        "6": "Белые 6 (E3) уже подходят к чёрному углу слева внизу. Дзёва активен с самого начала.",
        "10": "Белые 10 (P4) закрывают правый нижний угол вторым камнем.",
        "12": "Белые 12 (D6) давят сверху на чёрный угол слева внизу. Здесь начинается главная битва партии.",
        "13": "Чёрные 13 (E4) приставляются вплотную к белому камню. Чёрные принимают бой.",
        "20": "Белые 20 (C3) подлезают под чёрный угол: отбирают угловую территорию и пытаются дать жизнь своим камням.",
        "28": "Белые 28 (C9) далеко продвигаются вдоль левого края. Ход часто считают чрезмерным — яростный, в стиле Дзёвы.",
        "33": "Чёрные 33 (C2). По преданию, это новый вариант, тайно изученный в доме Иноуэ. Он атакует висящие белые камни в центре и одновременно поглощает белые камни слева.",
        "36": "Белые 36 (F3). Белые пытаются запереть чёрных снаружи слева внизу и связать свои камни.",
        "43": "Чёрные 43 (E9). Белым камням слева тяжело. До этого момента Интэцу играл хорошо и, считается, вышел вперёд.",
        "45": "Чёрные 45 (D11) тянутся вверх по левой стороне, держа белые камни разделёнными и укрепляя свои.",
        "50": "Белые 50 (C16). Белые пока оставляют низ слева и переходят к левому верхнему углу.",
        "53": "Чёрные 53 (G17). Чёрные входят на верхнюю сторону, не давая белым расширить левый верхний угол.",
        "58": "Белые 58 (C14) расширяются из левого верхнего угла вдоль края и приближаются к чёрным камням слева.",
        "60": "Белые 60 (G4) снимают два чёрных камня. Белая группа слева внизу наконец получает немного воздуха.",
        "62": "Белые 62 (J17). Противостояние и наверху. По всей доске слабые камни — трудная позиция.",
        "66": "Белые 66 (B14). У левого верхнего угла белые укрепляют свои камни.",
        "68": "Белые 68 (B11). Следующие ходы белых и 80-й ход прославились как блестящие ходы Дзёвы. Они были так удивительны, что говорили, будто их подсказали призраки.",
        "70": "Белые 70 (E12). Вместо прямого ответа чёрным слева белые сначала занимают другой ключевой пункт. Это возможно благодаря скрытым ресурсам.",
        "72": "Белые 72 (R13). Белые переходят на правую сторону, чтобы зона чёрных справа вверху не росла.",
        "76": "Белые 76 (O14). Белые связывают правую сторону с центром и готовятся разрезать чёрные камни.",
        "80": "Белые 80 (Q10) образуют «пустой треугольник» — форму, которую обычно считают плохой. Но именно этот ход стал опорой, чтобы разрезать чёрных надвое и атаковать. Классический пример некрасивого, но сильного хода.",
        "83": "Чёрные 83 (R3) вторгаются в белый угол справа внизу. Там начинается жаркая борьба со взятиями.",
        "91": "Чёрные 91 (Q4) снимают белый камень. Правый нижний угол очень важен для чёрных.",
        "98": "Белые 98 (M4). Белые окружают чёрные камни внизу и не дают им легко ожить.",
        "106": "Белые 106 (S5) снимают чёрный камень. Правый нижний угол остаётся за белыми, чёрным камням приходится убегать наружу.",
        "113": "Чёрные 113 (K6). Чёрные камни внизу ищут жизнь, выходя в центр.",
        "120": "Белые 120 (N9) преграждают путь убегающим чёрным камням. В центре решается, чьи камни ослабнут первыми.",
        "128": "Белые 128 (L11) давят на чёрные камни в центре и сверху. Чёрным всё ещё нельзя расслабиться.",
        "138": "Белые 138 (K8) снимают камень, и в центре начинается ко. Около 30 ходов камни снимают по очереди на K8 и L8.",
        "152": "Белые 152 (E11) — угроза в ко. Во время ко белые повсюду находят ходы, на которые чёрным приходится отвечать.",
        "170": "Белые 170 (P15). Ко в центре завершилось, белые переходят направо вверх, целясь в большую чёрную группу, которая ещё не вполне жива.",
        "178": "Белые 178 (J14) прыгают в середину верхней зоны, разделяя чёрные камни слева и справа. Атака на разрезание, готовившаяся с 80-го хода, начинается всерьёз.",
        "193": "Чёрные 193 (J11) снимают белый камень. Чёрные отчаянно борются за связь и жизнь.",
        "201": "Чёрные 201 (R14) снимают камень, и на правой стороне начинается новое ко со взятиями на R14 и R15.",
        "206": "Белые 206 (M13). Даже во время ко белые постепенно сжимают кольцо вокруг чёрных камней в центре.",
        "222": "Белые 222 (L14) снимают камень. Чёрные камни наверху по-прежнему разделены, и спасти обе части всё труднее.",
        "230": "Белые 230 (C13) бьют и по слабости чёрных на левой стороне. Белые камни теперь надёжно связаны по всей доске.",
        "237": "Ходами 237 (F12) и 239 (E13) чёрные отыгрывают камни слева вверху. Но общий разрыв не уменьшается.",
        "246": "После белых 246 (L8) Интэцу сдался. Говорят, когда убирали камни, он закашлялся кровью прямо на доску. Видимо, он уже давно болел и вскоре умер. Для Дзёвы эту партию называют величайшей победой в жизни."
      } },
    "deepblue1997": { "t": "Победа Deep Blue", "w": "Deep Blue (компьютер IBM)", "b": "Гарри Каспаров", "ev": "6-я партия матча-реванша с Deep Blue от IBM (матч из шести партий)", "d": "1997", "pl": "США (Нью-Йорк)", "lead": "Чемпион мира Каспаров против Deep Blue — шахматного компьютера, построенного IBM, в матче из шести партий. После пяти партий счёт был равным, а последняя закончилась всего за 19 ходов. Впервые компьютер выиграл у чемпиона мира полноценный матч из нескольких партий.",
      c: {
        "0": "Нью-Йорк, 11 мая 1997 года. Годом раньше их матч выиграл Каспаров. На этот раз после пяти партий счёт 2½:2½. Deep Blue играет белыми.",
        "1": "Белые двигают королевскую пешку на два поля.",
        "2": "Каспаров играет c6 — защита Каро-Канн.",
        "3": "Белые ставят в центр вторую пешку.",
        "4": "Чёрные играют d5 против e4.",
        "5": "Конь защищает e4.",
        "6": "Чёрные берут пешку e4.",
        "7": "Конь берёт обратно.",
        "8": "Чёрные ставят коня на d7, чтобы потом вывести второго на f6.",
        "9": "Конь прыгает на g5 — острый план с прицелом на f7 и e6.",
        "10": "Чёрные выводят коня на f6.",
        "11": "Слон на d3 смотрит на королевский фланг чёрных.",
        "12": "Чёрные укрепляют оборону ходом e6.",
        "13": "Второй конь выходит на f3.",
        "14": "Чёрные играют h6, чтобы прогнать коня g5. Но в этой позиции жертва коня за белых была уже известна. Говорят, это был необычный выбор для Каспарова.",
        "15": "Конь жертвуется на e6! Говорят, Deep Blue сыграл этот ход из заранее заложенных дебютных вариантов.",
        "16": "Чёрные не берут сразу, а ставят ферзя на e7. По линии e он смотрит на коня e6 и белого короля за ним.",
        "17": "Белые рокируют и уводят короля.",
        "18": "Чёрные берут коня и имеют лишний материал.",
        "19": "Слон на g6 — шах. Без пешки f7 диагональ доходит до короля.",
        "20": "Король уходит на d8. Чёрные больше не могут рокировать, и король остаётся рядом с центром.",
        "21": "Второй слон выходит и смотрит на поля вокруг чёрного короля.",
        "22": "Чёрные играют b5, освобождая место на ферзевом фланге для короля и слона.",
        "23": "a4 бьёт в пешку b5.",
        "24": "Чёрные ставят слона на b7.",
        "25": "Ладья на e1. По линии e она смотрит на пешку e6, а за ней — на ферзя e7.",
        "26": "Чёрный конь идёт на d5 и нападает на слона f4.",
        "27": "Слон отходит на g3.",
        "28": "Чёрный король уходит на c8, чуть безопаснее.",
        "29": "Белые берут пешку b5.",
        "30": "Чёрные берут обратно.",
        "31": "Ферзь на d3 смотрит на пешку b5 и поле f5.",
        "32": "Чёрные защищают b5 слоном.",
        "33": "Слон на f5! Его можно взять даром.",
        "34": "Чёрные берут пешкой. Но теперь пешки на линии e больше нет.",
        "35": "Ладья берёт ферзя e7. Белые отдали коня, слона и ладью, но выиграли ферзя.",
        "36": "Чёрные отыгрывают ладью слоном.",
        "37": "c4! Пешка бьёт сразу по b5 и d5, и оборона чёрных начинает рушиться. Здесь Каспаров сдался — видимо, считая, что его король слишком открыт, чтобы отбить атаку. Компьютер выиграл матч у чемпиона мира."
      } },
    "seigen1933": { "t": "Партия «сан-сан, звезда, тэнгэн»", "w": "Го Сэйгэн", "b": "Хонинбо Сюсай", "ev": "Памятная партия с мэйдзином (более трёх месяцев)", "d": "1933–1934", "pl": "Япония (Токио)", "lead": "19-летний Го Сэйгэн (5 дан) играл с мэйдзином Хонинбо Сюсаем. Чёрными он пошёл в сан-сан, затем на звезду, затем в самый центр (тэнгэн), нарушив все правила того времени и поразив мир го. С многими перерывами партия шла больше трёх месяцев; белые выиграли 2 очка.",
      c: {
        "0": "1933 год. В этом году Го Сэйгэн и его друг Китани Минору продвигали новый стиль дебюта — «синфусэки». Всем хотелось увидеть, как он применит его против мэйдзина.",
        "1": "Чёрные 1 — сан-сан справа вверху (R17). Один ход забирает угол, но мало влияет наружу, поэтому тогда его не считали первым ходом партии.",
        "3": "Чёрные 3 — звезда слева внизу (D4). В отличие от сан-сан, она нацелена на развитие наружу.",
        "5": "Чёрные 5 — прямо в центр доски, тэнгэн (K10). Не угол, не сторона, а середина. Против мэйдзина Го Сэйгэн открыто показал свои новые идеи.",
        "6": "Сан-сан, звезда, тэнгэн: у каждого чёрного камня своя роль — угловая территория, влияние наружу и сила в центре. Ходом 6 (Q16) белые играют вплотную к чёрному сан-сан.",
        "9": "Чёрные 9 (P18). Чёрные компактно и надёжно устраиваются в правом верхнем углу — стиль «сначала территория», типичный для сан-сан.",
        "11": "Чёрные 11 (K4) — середина нижней стороны, прямо под тэнгэном. Вместе с ним чёрные метят в большую зону внизу.",
        "12": "Белые 12 (M3) сразу входят на нижнюю сторону, не давая чёрным построить большую сферу. Мэйдзин спокойно разрушает планы чёрных один за другим.",
        "13": "Чёрные 13 (D10), теперь в середине левой стороны. Чёрные камни стоят высоко и вместе образуют широкую сферу.",
        "14": "Белые 14 (E16) закрывают левый верхний угол вторым камнем. Мэйдзин не смущён новым стилем и спокойно укрепляет угол.",
        "21": "Чёрные 21 (G10) связывают тэнгэн с камнем на левой стороне, и влияние чёрных растекается по центру.",
        "28": "Белые 28 (D3) подлезают под чёрную звезду слева внизу и забирают угол. Чёрные уступают его в обмен на внешнюю силу.",
        "30": "Белые 30 (Q12) расширяются по правой стороне и заодно «накрывают» чёрный сан-сан, ослабляя его влияние.",
        "37": "Чёрные 37 (P15) снимают белый камень. Справа вверху стороны сталкиваются в плотной борьбе.",
        "40": "Белые 40 (O10) выходят с правой стороны к центру, приближаясь к влиянию чёрных вокруг тэнгэна.",
        "44": "Белые 44 (H17) занимают пункт на верхней стороне, сдерживая рост чёрных вверх.",
        "45": "Чёрные 45 (R7) берутся за позицию белых справа внизу. Начинается долгая борьба от правой стороны до этого угла.",
        "59": "Чёрные 59 (R4) проникают и в правый нижний угол, уменьшая территорию белых.",
        "70": "Белые 70 (N6) продвигаются снизу в центр, чтобы отделить чёрные камни справа внизу от центральных.",
        "79": "Чёрные 79 (L9) укрепляют центр вокруг тэнгэна. Пока партия выглядит довольно равной.",
        "80": "Белые 80 (C6) поднимаются из левого нижнего угла вдоль левой стороны, целясь в чёрные камни там.",
        "98": "Белые 98 (A11) снимают два чёрных камня. Белые аккуратно живут у левого края, и левая сторона чёрных выходит меньше задуманного.",
        "101": "Чёрные 101 (S14) возвращаются направо вверх, чтобы уменьшить позицию белых на правой стороне.",
        "105": "Чёрные 105 (K17) занимают середину верхней стороны и начинают атаку на белые камни там.",
        "117": "Чёрные 117 (F17) входят и в район белого угла слева вверху — вся верхняя сторона становится полем боя.",
        "124": "Белые 124 (K15) выводят верхние камни к центру, по пути разрезая чёрные камни.",
        "135": "Чёрные 135 (E9) снимают два белых камня. Чёрные кое-что отыгрывают слева.",
        "138": "Белые 138 (N18) закрепляют территорию наверху. По всей доске позиция очень близкая.",
        "153": "Чёрные 153 (K14). Чёрные камни в центре образуют толстую дорогу, связывающую верх и низ. Главный вопрос — как белые смогут её разрушить.",
        "159": "Чёрные 159 (F4) надёжно защищают низ слева. Следующий ход белых — самый знаменитый в партии.",
        "160": "Белые 160 (H8) прыгают в брешь чёрной толщины — острый ход сразу с несколькими целями, с которого белые начинают вторжение в чёрный центр. Ходили слухи, что его нашёл ученик, а не Сюсай, но это так и не доказано.",
        "161": "Чёрные 161 (J8) сразу отвечают, но у белых не одна цель.",
        "162": "Белые 162 (K12) переходят в верхнюю часть центра и угрожают связям чёрных.",
        "172": "Белые 172 (F13) связывают камни центра с левым верхом. Понемногу толщина чёрных в центре перестаёт превращаться в территорию.",
        "178": "Белые 178 (N9) вторгаются и в зону чёрных справа от центра.",
        "187": "Ходами 187 (M6) и 189 (L7) чёрные снимают белые камни. Но белые уже успели занять важные пункты.",
        "198": "Белые 198 (E12) снимают камень. Белые камни слева вверху тоже связаны, и в целом белые немного впереди.",
        "203": "Чёрные 203 (B3). Дальше — ёсэ: границы у краёв уточняются по одному очку.",
        "224": "Белые 224 (T10) снимают камень. Даже у правого края белые не уступают ни очка.",
        "233": "Чёрные 233 (L13) снимают два белых камня. Чёрные догоняют до самого конца.",
        "252": "Партия заканчивается на 252-м ходу: белые выигрывают 2 очка. Без коми у чёрных было небольшое преимущество первого хода, но мэйдзин выстоял до конца. И всё же сан-сан, звезда и тэнгэн Го Сэйгэна произвели сенсацию и открыли новую эпоху дебютов."
      } },
    "century1956": { "t": "Партия века", "w": "Дональд Бирн", "b": "Бобби Фишер", "ev": "Третий турнир на приз Розенвальда (Мемориал Розенвальда)", "d": "1956", "pl": "США (Нью-Йорк)", "lead": "Тринадцатилетний Бобби Фишер побеждает Дональда Бирна, одного из сильнейших мастеров США. На 17-м ходу Фишер даёт забрать своего ферзя даром, затем отыгрывает фигуру за фигурой, а в конце его лёгкие фигуры загоняют белого короля. Позже Фишер стал чемпионом мира.",
      c: {
        "0": "Нью-Йорк, 17 октября 1956 года, турнирная партия. Чёрными играет тринадцатилетний Фишер, белыми — Бирн, один из лучших шахматистов США.",
        "1": "Белые начинают ходом коня.",
        "4": "Фишер играет g6, чтобы поставить слона на длинную диагональ.",
        "8": "Чёрные рокируют: сначала король в безопасности.",
        "10": "Чёрные играют d5. Начинается борьба за центр.",
        "15": "Ходом e4 белые ставят в центре две пешки рядом.",
        "17": "Ладья на d1 поддерживает пешку d4. Белые всё ещё не рокировали.",
        "18": "Конь идёт на b6 и гонит ферзя c4.",
        "20": "Слон на g4 давит на коня f3.",
        "21": "Белый слон идёт на g5. Белый король всё ещё в центре.",
        "22": "Конь на a4! Он прыгает туда, где его можно взять. Идея: если конь c3 уйдёт, пешка e4 останется без защиты.",
        "23": "Белые не берут коня и уводят ферзя на a3.",
        "26": "Чёрный конь берёт пешку e4. Белый центр рушится.",
        "27": "Белый слон берёт пешку e7 и нападает сразу на чёрного ферзя и ладью f8.",
        "28": "Ферзь на b6! Чёрные отдают ладью f8. Фишер рассчитывает на то, что белый король всё ещё в центре.",
        "29": "Белые не берут ладью, а выводят слона.",
        "30": "Конь берёт пешку c3 и нападает на ладью d1.",
        "31": "Слон на c5 нападает на чёрного ферзя b6.",
        "32": "Шах ладьёй по линии e!",
        "33": "Король идёт на f1. Теперь белые уже никогда не смогут рокировать.",
        "34": "Слон на e6! Самый знаменитый ход партии: чёрные отдают ферзя даром. Взамен у них есть план отыгрывать фигуру за фигурой.",
        "35": "Белые берут чёрного ферзя.",
        "36": "Слон на c4 — шах. Начинается контратака чёрных.",
        "38": "Конь даёт шах с e2.",
        "40": "Когда король возвращается на f1, конь уходит и открывает шах слона c4. По пути конь забирает пешку d4.",
        "44": "Конь возвращается на c3 — снова вскрытый шах, и теперь он нападает на ладью d1. Шахи один за другим со сбором фигур называют «мельницей».",
        "46": "Чёрные забирают слона. Конь c3 всё ещё нападает на ладью d1.",
        "50": "Конь берёт ладью d1. Теперь чёрные отыграли больше, чем ферзя, и явно впереди.",
        "52": "Ладья забирает и пешку a2.",
        "56": "Чёрные меняют ладьи. Чем меньше фигур, тем лучше тому, у кого их больше.",
        "57": "Белый ферзь даёт шах.",
        "58": "Чёрные закрываются слоном.",
        "64": "b5. Чёрная пешка пускается в путь.",
        "68": "Король идёт на g7 и освобождает слона f8.",
        "70": "Теперь чёрные фигуры охотятся на белого короля. Шах слоном.",
        "72": "Конь даёт шах на g3.",
        "74": "Шах вторым слоном.",
        "76": "Слон на b3 — шах.",
        "78": "Конь даёт шах на e2.",
        "80": "Конь даёт шах на c3. Короля гоняют туда-сюда.",
        "82": "Ладья на c2 — мат! Ладья, два слона и конь действуют вместе. Тринадцатилетний мальчик показал, как много фигур могут играть одной командой."
      } },
    "oshiro1849": { "t": "Первая замковая партия Сюсаку", "w": "Хонинбо Сюсаку", "b": "Ясуи Санти IX", "ev": "Замковая партия (ежегодная игра в замке Эдо)", "d": "1849", "pl": "Япония (Эдо)", "lead": "Замковые партии были ежегодным торжественным событием: мастера официальных домов го играли в замке сёгуна. 20-летний Сюсаку впервые выступил в этом году и выиграл чёрными 11 очков — так началась безупречная серия: 19 побед в 19 замковых партиях.",
      c: {
        "0": "1849 год. Годом раньше Сюсаку был назван наследником дома Хонинбо и теперь играет первую замковую партию. Говорят, такие партии часто играли заранее в другом месте, а в замке лишь повторяли.",
        "1": "Чёрные 1 — пункт 3-4 справа вверху (R16). Как обычно, Сюсаку начинает со спокойного 3-4.",
        "4": "Белые 4 (C15) подходят к чёрному камню D17 слева вверху. Там рано начинается борьба.",
        "5": "Чёрные 5 (C11) зажимают подошедший белый камень снизу, чтобы белые не устроились легко слева.",
        "12": "Белые 12 (C17). Левый верхний угол достаётся белым, у чёрных — камни, смотрящие наружу. Честный размен.",
        "13": "Чёрные 13 (J17) используют внешние камни и расширяются по верху.",
        "15": "Чёрные 15 (C5) занимают последний свободный угол — слева внизу. Все четыре угла заняты.",
        "16": "Белые 16 (E4) тут же подходят к этому чёрному камню, и борьба начинается и слева внизу.",
        "19": "Чёрные 19 (D2) надёжно закрепляют левый нижний угол — основательно, в духе Сюсаку.",
        "23": "Чёрные 23 (E5) выходят между белыми камнями и усиливают свою группу слева внизу.",
        "29": "Чёрные 29 (F11) укрепляют камни слева и одновременно смотрят в центр.",
        "30": "Белые 30 (H4) расширяются по низу, давят на чёрную группу слева и строят свою зону.",
        "31": "Чёрные 31 (O3) подходят к белому углу справа внизу.",
        "33": "Чёрные 33 (R3) приставляются к белому угловому камню. Дальше чёрные строят снаружи, а белые ползут по третьей линии вдоль края.",
        "43": "Чёрные 43 (Q8). По правой стороне теперь тянется толстая чёрная стена. У белых — территория в углу и на краю, у чёрных — внешняя сила.",
        "44": "Белые 44 (L17) входят между чёрными камнями наверху, чтобы зона чёрных не стала слишком большой.",
        "50": "Белые 50 (R18) подлезают под чёрный угол справа вверху, нацеливаясь на угловую территорию.",
        "51": "Чёрные 51 (P13). Опираясь на стену, чёрные намечают большую зону от правой стороны к центру.",
        "52": "Белые 52 (D10) вторгаются между чёрными камнями слева. Там камни переплетаются.",
        "63": "Чёрные 63 (B10) играют у левого края, чтобы белые камни не получили там базы.",
        "65": "Чёрные 65 (G3) входят и в зону белых внизу, уменьшая их территорию.",
        "73": "Чёрные 73 (K17) укрепляют свои камни наверху и давят на белый камень 44-го хода.",
        "76": "Белые 76 (P11) прыгают в зону чёрных справа. Выживет этот камень или нет — сильно повлияет на счёт.",
        "77": "Чёрные 77 (Q11) отвечают со стороны своей стены и выталкивают белых к центру — спокойная защита с атакой, в стиле Сюсаку.",
        "80": "Белые 80 (N10) убегают в центр, уходя от преследования чёрных.",
        "85": "Чёрные 85 (N12) продолжают атаку, расширяя свою территорию сверху и справа. Выгода через атаку — искусная игра.",
        "91": "Чёрные 91 (J7) играют над белыми камнями внизу, накрывая зону белых и со стороны центра.",
        "100": "Белые 100 (S17) пробуют что-то в правом верхнем углу, чтобы уменьшить чёрную территорию.",
        "119": "Чёрные 119 (R17) надёжно защищают правый верхний угол и отражают попытку белых.",
        "122": "Белые 122 (G6) обходят снаружи чёрные камни слева внизу, пытаясь отрезать их от центра.",
        "131": "Чёрные 131 (M5) вбивают клин в зону белых в середине нижней стороны.",
        "140": "Белые 140 (B4) пробуют что-то в чёрном углу слева внизу. У левого края начинается плотная борьба со взятиями.",
        "156": "Белые 156 (A8) снимают два чёрных камня. Борьба у левого края затихает: обе стороны понемногу взяли своё.",
        "158": "Белые 158 (L10). У белых ещё есть камни в центре, и они пытаются сократить центральную территорию чёрных.",
        "162": "Белые 162 (O12) снимают чёрный камень. И всё же зона чёрных справа остаётся большой.",
        "172": "Белые 172 (K18). Дальше ёсэ — начинают с границы на верхней стороне.",
        "186": "Белые 186 (T16) подрезают территорию чёрных у правого верхнего края. В ёсэ обе стороны сначала играют самые крупные пункты.",
        "205": "Чёрные 205 (Q18) закрывают правую часть верхней стороны и закрепляют там территорию.",
        "223": "Чёрные 223 (P10) уточняют границу между чёрной территорией справа и белыми камнями, ушедшими в центр.",
        "233": "Чёрные 233 (Q9) снимают белый камень. Территория чёрных справа почти полностью в безопасности.",
        "239": "Чёрные 239 (A6) снимают камень, и у левого края возникает ко. Борьба за каждое очко идёт до самого конца.",
        "260": "Белые 260 (T6) снимают камень, и у правого нижнего края возникает ещё одно ко. Чёрные забирают обратно ходом 263 (T5).",
        "267": "Партия заканчивается на 267-м ходу: чёрные выигрывают 11 очков. Без авантюр — Сюсаку атаковал и естественно наращивал территорию, победа в его духе. Это первая из 19 подряд побед в замковых партиях."
      } },
    "shilin": { "t": "Партия из «Шилинь гуанцзи»", "w": "Красные (имя не сохранилось)", "b": "Чёрные (имя не сохранилось)", "ev": "Бытовая энциклопедия «Шилинь гуанцзи»: «победа после уступленного первого хода, пушки с одной стороны»", "d": "XIII век", "pl": "Китай (Сун — Юань)", "lead": "Эта запись взята из «Шилинь гуанцзи» — бытовой энциклопедии, которую Чэнь Юаньцзин составил на рубеже династий Сун и Юань. Её считают одной из самых старых сохранившихся полных партий в сянци. Это образцовая партия, где сильный игрок уступает слабому первый ход, — и всего за девять ходов чёрный конь ловит красную колесницу.",
      c: {
        "0": "Этой записи больше 700 лет: она из эпохи между династиями Сун и Юань. Она помещена в главе об играх энциклопедии «Шилинь гуанцзи» и считается одной из самых старых полных партий в сянци, дошедших до нас. Имена игроков не сохранились. В названии сказано, что сильный «уступил первый ход» слабому, так что это урок: он показывает, как проигрывают красные, которые ходят первыми. Красные внизу и начинают.",
        "1": "Красные ставят правую пушку на центральную вертикаль. Это «центральная пушка», нацеленная прямо на чёрного генерала, — и сегодня одно из самых сильных начал. Видно, что так играли уже 700 лет назад.",
        "2": "Чёрные тоже ставят пушку в центр, и две пушки смотрят друг на друга. Когда обе стороны двигают пушку с одной и той же стороны, это называют «пушки в одну сторону». Дуэль пушек любят уже много веков.",
        "3": "Красные выводят коня, чтобы защитить центрального солдата. Этого солдата атакует чёрная пушка, ему нужен защитник. Заодно конь готовится выйти вперёд.",
        "4": "Чёрные делают то же самое и защищают центрального солдата конём. Обе стороны сначала строят прочную опору.",
        "5": "Красные сдвигают правую колесницу на шаг вбок, на открытую вертикаль. Колесница — самая сильная фигура, её полезно рано пустить в дело.",
        "6": "Чёрные выводят второго коня, а колесницы пока оставляют дома. План — сначала продвинуть фигуры. Но колесницу, которая вышла поздно, потом бывает трудно включить в атаку.",
        "7": "Красная колесница сразу перебегает реку и врывается в лагерь чёрных. Она хочет угрожать чёрным фигурам, но остальные красные фигуры ещё дома, так что атака немного поспешная. Можно было сначала вывести левого коня или левую колесницу.",
        "8": "Чёрные продвигают солдата на 3-й вертикали на шаг. Так они открывают коню дорогу, чтобы позже прыгнуть вперёд. Чёрные почти приглашают красную колесницу прийти.",
        "9": "Красная колесница берёт солдата и теперь целится в чёрного коня за ним. Выиграть фигуру и угрожать другой — выглядит отлично. Но колесница забежала далеко, и рядом нет друзей. Одинокую колесницу в чужом лагере легко гонять.",
        "10": "Чёрный конь прыгает вперёд. Он уходит от колесницы и одновременно приближается к лагерю красных — две задачи одним ходом. Этот конь станет героем партии.",
        "11": "Красные отводят колесницу на шаг, чтобы напасть на коня сбоку. Колесница бьёт издалека, так что коню некогда отдыхать. Но и этот ход не помогает развить другие красные фигуры.",
        "12": "Чёрный конь идёт дальше и переходит реку в лагерь красных. Каждый раз, убегая от колесницы, он оказывается ближе к красному генералу.",
        "13": "Красные продвигают солдата, чтобы открыть дорогу своему коню. Идея — вывести его и разменять на чёрного коня. Но это даёт чёрным время пройти ещё дальше.",
        "14": "Чёрные поднимают слона и нападают на красную колесницу. Прогнать вражескую колесницу защитной фигурой — очень экономно. Красным снова приходится двигать колесницу, а чёрные выигрывают ещё темп.",
        "15": "Красная колесница скользит вбок и берёт ещё одного солдата. У красных уже на два солдата больше, но именно этот ход проигрывает. Колесница теперь далеко от своего генерала и не может вернуться на защиту. Нужно было защититься от коня, например вернуть колесницу домой.",
        "16": "Чёрный конь проникает глубже и нападает на красную колесницу. И это не всё: если он прыгнет ещё раз, то объявит шах красному генералу и одновременно нападёт на колесницу в углу. Один конь создал сразу две угрозы.",
        "17": "Красные гонятся за конём колесницей. Но его уже не остановить. Вокруг красного генерала не осталось никого, кто мог бы помочь.",
        "18": "Конь прыгает с шахом! Он же нападает на колесницу в углу красных, так что когда генерал отойдёт, колесница пропадёт. Всего девять ходов, но партия учит, что бывает с колесницей, убежавшей вперёд в одиночку, и почему фигуры должны сражаться вместе. 700 лет назад игроки думали о том же самом на той же доске."
      } },
    "qima13": { "t": "Жертва коня в тринадцать ходов («Цзюйчжунми»)", "w": "Красные (имя не сохранилось)", "b": "Чёрные (имя не сохранилось)", "ev": "«Цзюйчжунми», том 1, партия 1", "d": "1632 (издание)", "pl": "Китай (Мин)", "lead": "Это самая первая партия книги «Цзюйчжунми» («Тайна в мандарине»), которую Чжу Цзиньчжэнь издал в эпоху Мин, в 1632 году. Красные позволяют чёрным даром взять коня, тем временем врываются в атаку и ставят мат за тринадцать ходов. Под названием «жертва коня в тринадцать ходов» её любят и почти 400 лет спустя.",
      c: {
        "0": "Это партия 1 из книги «Цзюйчжунми», напечатанной в 1632 году, ближе к концу династии Мин. Вместе с более поздним «Сливовым трактатом» её называют одной из двух великих классических книг сянци. Это не настоящая партия, а образец, написанный, чтобы научить плану, поэтому имён игроков нет. Красные внизу и начинают, и всё заканчивается всего за тринадцать ходов.",
        "1": "Красные ставят правую пушку в центр. Это «центральная пушка», которая смотрит прямо на чёрного генерала. Книга «Цзюйчжунми» знаменита тем, что подробно изучила атаку этим началом.",
        "2": "Чёрные тоже ставят в центр пушку с той же стороны. Это «пушки в одну сторону», которые сталкиваются лоб в лоб. Каждая сторона целится в центрального солдата соперника.",
        "3": "Красные выводят коня, чтобы защитить центрального солдата. Он прикрывает солдата, на которого нацелена чёрная пушка, и конь начинает работать.",
        "4": "Чёрные тоже защищают центрального солдата конём. Пока у обеих сторон одинаковое построение.",
        "5": "Красные продвигают правую колесницу всего на один шаг. Теперь следующим ходом она сможет бежать вбок. Колесницу, которая так ходит вбок, называют «горизонтальной»: она быстро переходит на любой фланг.",
        "6": "Чёрные сдвигают колесницу на шаг вбок, чтобы она могла ехать прямо вверх по доске. Это «прямая колесница». Горизонтальная против прямой — два разных способа использовать колесницу.",
        "7": "Красная горизонтальная колесница переходит на вертикаль слева. Эта вертикаль проходит прямо рядом с чёрным советником, где защита слабая. Красные готовятся прорваться отсюда.",
        "8": "Чёрная прямая колесница переходит реку и глубоко входит в лагерь красных. Чёрные хотят ответить своей атакой. Но это ход, который спешит нападать, не успев защититься.",
        "9": "Красная колесница врывается в глубину лагеря чёрных. Она встаёт на «глаз» слона — точку, через которую слон должен пройти, — и чёрный слон не может двигаться. Рядом с советником она уже очень близко к генералу.",
        "10": "Чёрные выводят второго коня к краю. Отчасти чтобы не дать красной колеснице проскользнуть сбоку.",
        "11": "Вот и жертва коня! Красные поднимают вторую колесницу на шаг. Конь в левом углу остаётся без защиты, и чёрная пушка может взять его даром. Но за одного коня красные выигрывают время, чтобы быстро бросить в атаку обе колесницы.",
        "12": "Чёрная пушка берёт красного коня. Кажется, чёрные выиграли фигуру. Но эта пушка теперь далеко от дома и не может помочь в защите. Говорят, здесь лучше было не брать, а поднять советника и укрепить оборону.",
        "13": "Красная пушка идёт вперёд. Используя центральную чёрную пушку как «лафет» для прыжка, она нацеливается на чёрного коня за ней. Пушка — странная фигура: она бьёт, перепрыгивая ровно через одну фигуру.",
        "14": "Чёрные отводят коня, спасая его. Но этот конь был важной фигурой, защищавшей центрального солдата. Убежав, он оставил дыру в центре. У чёрных были и другие защиты, но эта — худший выбор.",
        "15": "Красная пушка берёт центрального солдата — шах! Без чёрного коня центр был распахнут. Отсюда атака красных несётся вперёд.",
        "16": "Чёрные поднимают советника, закрывая генерала спереди. Это единственный хороший способ защититься от шаха.",
        "17": "Вторая красная колесница приходит на ту же вертикаль. Две колесницы друг за другом на одной линии — огромная сила. План — прорваться в самую глубину лагеря чёрных.",
        "18": "Чёрный генерал отходит в сторону. Иначе на него в упор смотрели бы обе красные колесницы.",
        "19": "Передняя красная колесница берёт чёрного советника — шах! Другой советник сразу её возьмёт, но это часть плана. Красные отдают колесницу, чтобы разбить охрану чёрного генерала. Какой смелый ход!",
        "20": "Чёрные берут колесницу советником. По материалу чёрные далеко впереди. Но дом генерала опустел ещё сильнее.",
        "21": "Последняя красная колесница переходит на вертикаль генерала — снова шах. У чёрного генерала почти не осталось защитников.",
        "22": "Чёрные ставят пушку перед генералом, закрываясь от шаха. Поставить фигуру посередине — это перекрыть шах.",
        "23": "Красная колесница берёт эту пушку — снова шах. Колесница продолжает брать чёрные фигуры, загоняя генерала в угол.",
        "24": "Чёрному генералу остаётся только вернуться в центр. Все остальные точки под контролем красных.",
        "25": "Наконец красная пушка встаёт в центр: две пушки на одной линии — шах. Передняя пушка служит лафетом, а задняя бьёт генерала: это мат «двойной пушкой». Чёрному генералу некуда идти, красные побеждают. Отдав всего одного коня, красные выиграли за тринадцать ходов. Уже 400 лет эта партия учит, что время и активность фигур могут значить больше, чем их количество."
      } }
  },
  "tr": {
    ui: {"lead":"Büyük oyunlar, hamle hamle. Musowl her hamleyi anlatırken ünlü oyunları tahtada takip edin.","all":"Tümü","k_chess":"Satranç","k_shogi":"Shogi","k_go":"Go","k_xiangqi":"Xiangqi","side_r":"Kırmızı","res_r":"Kırmızı kazandı","back":"Büyük oyunlara dön","start":"Baş","prev":"Bir hamle geri","next":"Bir hamle ileri","end":"Son","play":"Oynat","pause":"Duraklat","moves":"Hamleler","move":"{n}. hamle","startpos":"Başlangıç konumu","nextnote":"Sonraki açıklama ({n}. hamle)","quiet":"Bu hamle için açıklama yok.","guide":"Musowl","keys":"← → ile hamle hamle","result":"Sonuç","r_event":"Oyun","r_date":"Yıl","r_place":"Yer","side_w":"Beyaz","side_b":"Siyah","side_s":"Sente","side_g":"Gote","side_B":"Siyah","side_W":"Beyaz","res_w":"Beyaz kazandı","res_b":"Siyah kazandı","res_d":"Berabere","res_s":"Sente kazandı","res_g":"Gote kazandı","credit":"Hamleler, her oyunun herkesçe bilinen kaydıdır. Açıklamalar müzenin Musowl’u tarafından yazıldı."},
    "opera": { "t": "Opera Oyunu", "w": "Paul Morphy", "b": "Brunswick Dükü II. Karl ve Kont Isouard", "ev": "Paris Operası’ndaki bir locada oynandı (iki müttefik birlikte danışarak oynadı)", "d": "1858", "pl": "Fransa (Paris)", "lead": "Genç Amerikalı şampiyon, bir opera gösterisi sırasında iki soyluya karşı: on yedi hamle. Taşları hızla çıkar, hiç tereddüt etmeden feda et ve çok az taşla bitir. Satranç kitaplarında bundan daha sık yer alan bir oyun yoktur.",
      c: {
        "0": "Paris, 1858. Yirmi bir yaşındaki Amerikalı Paul Morphy, Avrupa’nın güçlü oyuncularını birer birer yeniyordu. O akşam operadaki bir locada Brunswick Dükü ile Kont Isouard siyahı birlikte alıp ona meydan okudu ve her hamleyi birlikte düşündü. Morphy’nin sahneyi izleyebilmek için oyunu çabuk bitirmek istediği söylenir. Bu on yedi hamle temellerle dolu: taşları hızla çıkar, şahı güvene al.",
        "1": "Beyaz şah piyonunu iki kare ilerletir. Merkezdeki d5 ve e5’e bakar, fil ile vezirin yolunu açar.",
        "2": "Siyah da e5 oynar. Piyonlar merkezde karşı karşıya; beyaz piyon daha ileri gidemez.",
        "3": "At f3’e çıkıp e5 piyonuna saldırır. İyi bir hamle: hem taş geliştirir hem rakibi savunmayı düşünmeye zorlar.",
        "4": "Siyah d6 ile e5’i korur. Buna Philidor Savunması denir. Sağlamdır ama f8’deki filin yolu biraz daralır.",
        "5": "Beyaz d4 oynar: merkeze bir piyon daha, e5’e karşı. Siyah almakla korumak arasında seçim yapmalı.",
        "6": "Siyah fil g4’e gider. f3’teki ata baskı yapar; atın arkasında d1’de beyaz vezir var. At oynarsa vezir gider, bu yüzden at e5’i almaya gidemez.",
        "7": "Beyaz piyonla e5’te alır. Siyah hemen d6 piyonuyla geri alsaydı, Beyaz vezirleri değişir, sonra at e5 piyonunu kapardı. Bu yüzden Siyah önce f3’teki atı ortadan kaldırmak ister.",
        "8": "Siyah atı filiyle alır. Artık e5’i güvenle geri alabilir. Ama yeni çıkan fili ata vermek Siyah’ı gelişimde geri bırakır.",
        "9": "Beyaz veziriyle geri alır. Beyaz vezir şimdiden merkezin yakınında çalışıyor, Siyah ise neredeyse hiç taş çıkarmadı.",
        "10": "Siyah piyonla geri alır, malzeme eşit. Ama çıkmış taş sayısında Beyaz önde.",
        "11": "Fil c4’e. f3’teki vezirle birlikte f7’ye nişan alır. f7’yi yalnızca şah korur, zayıf bir karedir: alınırsa mat olur.",
        "12": "Siyah atı f6’ya çıkarıp f hattını kapatır. Bu olmasa vezir f7’yi alıp mat ederdi. Taş geliştirerek savunmak doğru cevaptır.",
        "13": "Vezir b3’e döner ve aynı anda f7 ile b7’ye saldırır. İki tehditli hamle güçlüdür, çünkü rakip ikisini birden koruyamaz.",
        "14": "Siyah veziri e7’ye getirip f7’yi korur, b7’yi bırakır. Ama vezir şimdi f8’deki filin önünü kapatıyor.",
        "15": "Morphy b7 piyonunu almaz, at çıkarır. Alsaydı vezir çok uzağa giderdi. Bir piyon yerine hızlı gelişimi seçmek tam Morphy’ye yakışır.",
        "16": "Siyah c6 oynar: d5 ve b5’i tutar, vezire b6’ya giden yolu açar.",
        "17": "Fil g5’e gidip f6’daki atı çiviler. At oynarsa arkasındaki e7 veziri alınır. Siyah taşların hareketi giderek zorlaşıyor.",
        "18": "Siyah c4’teki fili kovmak için b5 oynar. Vezir kanadında yer kazanır ama beyaz taşların gireceği bir boşluk da açar.",
        "19": "At feda edilip b5’te alır! Fili geri çekmek yerine Morphy saldırmaya devam eder. Siyah şah hâlâ ortadayken bu, Siyah için çok tehlikelidir.",
        "20": "Siyah atı alır ve bir at önde. Ama şahı hâlâ e8’de, beyaz taşlar da gelmeye devam ediyor.",
        "21": "Fil b5’te şah! Siyah şah hâlâ ortada sıkışık. Beyaz’ın at karşılığı iki piyonu var ve doğrudan şaha yürüyor.",
        "22": "Siyah d7’ye atı koyarak şahı keser. Ama bu at çivili: oynarsa siyah şah, şah altında kalır. Beyaz artık d7’ye nişan alacak.",
        "23": "Beyaz uzun rok yapar. Şah güvende ve aynı anda kale d1’e gelip d7’ye bakar. Tek hamleyle hem savunma hem saldırı: harika.",
        "24": "Siyah d7’yi korumak için kaleyi d8’e getirir. Hâlâ rok yapamıyor; h8’deki kale ve f8’deki fil hiçbir iş yapmıyor.",
        "25": "Kale feda edilip d7’de alır! Beyaz bir kale vererek bir siyah savunucuyu ortadan kaldırır.",
        "26": "Siyah kaleyle geri alır. Şimdi d7’deki bu kale de çivili: oynarsa b5’teki fil siyah şaha şah çeker.",
        "27": "Öbür kale d1’e gelip d7’ye yeniden saldırır. Artık d7’ye saldıran beyaz taşlar, onu koruyan siyah taşlardan fazla.",
        "28": "Siyah vezir e6’ya gider; b3’teki veziri uzaklaştırmak için vezir değişimi teklif eder ve d7’ye yardım etmek ister. Ama artık çok geç.",
        "29": "Fil d7’de alarak şah çeker. Beyaz siyahın savunucularını birer birer temizliyor.",
        "30": "Siyah atla geri alır. f6’daki at gidince g5’teki filden d8’e uzanan çapraz açıldı. Bu çapraz en sonda işe yarayacak.",
        "31": "Vezir b8’de şah çekerek feda edilir! Oyunun en ünlü hamlesi. Siyah atla almak zorunda; at d7’den ayrılınca d hattı açılır.",
        "32": "Siyah atla alır. Artık d8’i koruyan hiçbir siyah taş yok.",
        "33": "Kale d8’e, mat! g5’teki fil d8’i destekler; siyah şah kendi taşlarıyla çevrili, kaçamaz. Beyaz vezir, kale ve fil verdi ve sonunda yalnızca bir kale ve bir fille bitirdi. Hızlı geliş, şahı güvene al ve rakip şah ortadayken saldır: bu ünlü oyun tüm bu önemli fikirleri bir araya getirir."
      } },
    "reti1910": { "t": "Réti Matı", "w": "Richard Réti", "b": "Savielly Tartakower", "ev": "Serbest bir oyun (turnuva değil)", "d": "1910", "pl": "Avusturya (Viyana)", "lead": "İleride büyük usta olacak iki oyuncu, Viyana’da serbest bir oyun, on bir hamle. Beyaz vezirini verir ve çifte şahla bitirir: iki taş aynı anda şah çeker. Bu mat şekline Beyaz’ın adı verilmiştir: Réti Matı.",
      c: {
        "0": "Viyana, 1910. Beyazda yirmi yaşındaki Richard Réti, siyahta Savielly Tartakower var. İkisi de sonradan dünyanın en iyileri arasına girdi ve satranca yeni fikirler getirmeleriyle tanınır. Bu bir turnuva oyunu değil, küçük bir bahisle oynanan serbest bir oyundu. Kısa ama şahı erkenden güvene almanın neden önemli olduğunu çok iyi gösterir.",
        "1": "Beyaz şah piyonunu iki kare ilerletir. Merkezi tutmak, arkadaki taşların kolay çıkmasını sağlar. Fil ile vezirin yolu da açıldı.",
        "2": "Siyah c6 oynar. Hemen merkeze gitmek yerine d5 ile e4 piyonuna saldırmaya hazırlanır. Bu sağlam açılışa Caro-Kann Savunması denir.",
        "3": "Beyaz öbür piyonu da d4’e koyar. Merkezde yan yana iki piyon: Beyaz’ın geniş alanı var. Siyah bunları dağıtmaya çalışacak.",
        "4": "Planlandığı gibi d5. Piyon e4’e meydan okur: “Seni alabilirim.” Beyaz korumak, ilerletmek ya da değişmek arasında seçim yapmalı.",
        "5": "Beyaz e4’ü korumak için bir at çıkarır. Hem taş geliştirir hem savunur; hiç zaman kaybı yok.",
        "6": "Siyah e4’teki piyonu alır. Merkez piyonlarını değişerek Beyaz’ın merkezini küçültür.",
        "7": "Beyaz atla geri alır ve at tahtanın ortasına yerleşir. Merkezdeki at birçok kareye ulaşır ve çok güçlüdür.",
        "8": "Siyah e4’teki ata karşı bir at çıkarır. Burada genelde fil f5’e oynanır ama Siyah at değişimine davet eder.",
        "9": "Vezir erkenden d3’e çıkıp e4’teki atı korur. Normalde vezir bu kadar erken çıkarılmaz ama Beyaz’ın bir planı var. Bu vezirin d hattında, siyah şahın karşısında durduğunu unutma.",
        "10": "Siyah e5 oynar ve fil ile vezire yol açmak için bir piyon verir. Merkezde kavga başlatan aktif bir hamle.",
        "11": "Beyaz e5’teki piyonu alır. Hediyeyi kabul eder ama böylece siyah vezir daha rahat hareket eder.",
        "12": "Şah! a5’teki siyah vezir çaprazdan e1’deki şaha nişan alır. Aynı anda e5 piyonunu geri almayı da planlar: tek hamlede iki iş. Beyaz araya taş koymalı.",
        "13": "Beyaz fili d2’ye koyarak şahı keser. Vezir fili alabilirdi ama beyaz vezir onu iyi koruyor.",
        "14": "Siyah piyonu geri aldı, malzeme yine eşit. Üstelik bu vezir e hattı boyunca e4’teki ata ve arkasındaki şaha bakıyor. At oynarsa şah, şah altında kalır; yani at çivili. Siyah onu kazanacakmış gibi görünüyor.",
        "15": "Beyaz uzun rok yapar. Şah e hattından çıkar ve at yeniden serbest kalır. Aynı anda d1’e bir kale gelir: d1’deki kale, d3’teki vezir ve siyah şahın yanındaki d8 aynı hatta dizilir. İşte Beyaz’ın tuzağı.",
        "16": "Siyah e4’teki atı alır ve bir taş kazanmış gibi görünür. Ama siyah şah hâlâ e8’de ve rok yapmadı. Beyaz taşlar d hattında dizili, siyah şah ise korumasız. Oyunu kaybettiren bu hamle, oyunun dönüm noktasıdır.",
        "17": "Vezir d8’e, şah! Beyaz en güçlü taşını bedavaya verir. Onu alabilecek tek siyah taş şahtır. Aldırarak Beyaz, şahı tehlikeli d8 karesine çeker.",
        "18": "Siyah şahla almak zorunda; şahtan kurtulmanın başka yolu yok. Şah d8’de, arkasında da d1’deki kale bekliyor.",
        "19": "Fil d2’den g5’e şah çekerek gider ve aynı anda d1’deki kalenin yolunu açar; kale de d hattından şah çeker. İki taşın aynı anda şah çekmesine çifte şah denir. Bir taşı alarak da araya taş koyarak da durdurulamaz; şah kaçmak zorundadır.",
        "20": "Şah c7’ye kaçar. e8’e gitseydi kale d8’e gelip mat ederdi. Şah nereye giderse gitsin Beyaz’ın son vuruşu hazır.",
        "21": "Fil d8’e: c7’deki şaha çaprazdan mat! Fili d1’deki kale koruduğu için şah onu alamaz. b8, c8, b7 ve c6 gibi kareler siyahın kendi taşlarıyla dolu; kale de d6 ve d7’yi tutuyor. Yalnızca on bir hamlede Beyaz veziri verdi ve iki küçük taşla kazandı. Bu oyun, rok yapmadan malzeme peşine düşmenin ne kadar tehlikeli olduğunu öğretir. Bazı kayıtlara göre Siyah bir hamle önce terk etmiştir."
      } },
    "immortal": { "t": "Ölümsüz Oyun", "w": "Adolf Anderssen", "b": "Lionel Kieseritzky", "ev": "1851 Londra turnuvasının arasında oynanan resmî olmayan bir oyun", "d": "1851", "pl": "Birleşik Krallık (Londra)", "lead": "Londra’da ilk uluslararası satranç turnuvası sırasında, bir arada oynanan oyun. Beyaz bir fil, iki kale ve sonunda veziri verir; kalan üç küçük taşla mat eder. Siyahın sondan önce terk ettiği, son birkaç hamlenin Beyaz’ın gösterdiği bitiriş olduğu da söylenir.",
      c: {
        "0": "Londra, 1851. Turnuva arasında Alman Anderssen (beyaz) ile Paris’in yıldızı Kieseritzky (siyah) dostça bir oyun oynadı.",
        "1": "Beyaz şah piyonunu iki kare ilerletir.",
        "2": "Siyah da aynısını yapar.",
        "3": "f4! Beyaz bir piyon sunar: Şah Gambiti. Amaç siyahın e5 piyonunu merkezden uzaklaştırmak.",
        "4": "Siyah piyonu alır.",
        "5": "Fil çıkar ve siyah şahın yanındaki f7’ye bakar.",
        "6": "Şah! Beyazın f piyonu gidince h4’ten e1’e çapraz yol açıldı.",
        "7": "Şah bir kare kenara çekilir. Artık Beyaz hiç rok yapamaz.",
        "8": "Siyah da bir piyon sunar; fili b5’e çekmek ister.",
        "9": "Beyaz alır.",
        "10": "Bir at çıkar ve e4 piyonuna saldırır.",
        "11": "Beyaz da at çıkarıp h4’teki veziri kovalar.",
        "12": "Vezir h6’ya çekilir.",
        "13": "d3, e4’ü korur ve c1’deki filin yolunu açar.",
        "14": "At h5’e. Plan: g3’e sıçrayıp şah çekmek ve h1’deki kaleye saldırmak.",
        "15": "Beyaz at h4’e gider; f5’e sıçrayıp siyah veziri rahatsız etmeye hazırlanır.",
        "16": "Siyah vezir g5’e gider ve h4’teki ata saldırır.",
        "17": "At f5’e; e4 piyonunun koruduğu güzel bir kare. g7 piyonuna da bakıyor.",
        "18": "c6, b5’teki fili kovmaya çalışır.",
        "19": "Beyaz fili kurtarmaz; g4 ile h5’teki atı kovalar.",
        "20": "At f6’ya döner.",
        "21": "Kale g1’e, g4 piyonunu korur. b5’teki fil alınsa da olur. Çok cesur bir hamle!",
        "22": "Siyah fili alır ve bir taş öne geçer.",
        "23": "h piyonu siyah veziri kovalamaya başlar.",
        "24": "Vezir g6’ya.",
        "25": "h5 veziri yine kovalar.",
        "26": "Vezir yalnızca g5’e dönebilir. Gidebileceği kareler azalıyor.",
        "27": "Beyaz vezir f3’e. Sonra fil f4’te alırsa siyah vezir kapana kısılabilir.",
        "28": "Siyah atı g8’e geri götürür ki vezir f6’ya kaçabilsin.",
        "29": "Fil f4 piyonunu alır ve vezire saldırır.",
        "30": "Vezir f6’ya kaçar.",
        "31": "Bir at çıkar; d5’e sıçrayıp vezire saldırmayı planlar.",
        "32": "Fil çıkar ve g1’deki kaleye nişan alır.",
        "33": "At d5’e; f6’daki vezire ve c7 karesine saldırır. g1’deki kale gitse de umursamaz.",
        "34": "Vezir b2 piyonunu alır ve a1’deki kaleye saldırır.",
        "35": "Fil d6’ya! Beyaz iki kaleyi de bırakır. Karşılığında taşları siyah şahın çevresine ağ örer.",
        "36": "Siyah g1’deki kaleyi alır.",
        "37": "e5! Bu piyon, b2’deki vezirin g7’ye giden çaprazını kapatır. Siyah vezir artık şahına yardım edemez.",
        "38": "Siyah şah çekerek öbür kaleyi de alır.",
        "39": "Şah e2’ye. Beyazın elinde yalnızca vezir, iki at ve bir fil kaldı.",
        "40": "At a6’ya çıkıp c7’yi korur. Siyahın bu civarda terk ettiği, sonrasının Beyaz’ın gösterdiği bitiriş olduğu söylenir.",
        "41": "At g7’de alarak şah çeker.",
        "42": "Şah d8’e kaçar.",
        "43": "Vezir f6’da şah çekerek feda edilir! Son büyük taş da gider.",
        "44": "Siyah atla almak zorunda.",
        "45": "Fil e7’ye, mat! d5’teki at e7 ve c7’yi, g7’deki at e8’i tutar. Beyaz yalnızca bir fil ve iki atla kazanır."
      } },
    "mimiaka": { "t": "Kızaran Kulaklar Oyunu", "w": "Hon’inbō Shūsaku", "b": "Inoue Gennan Inseki", "ev": "Osaka’da oynanan oyun (üç günde)", "d": "1846", "pl": "Japonya (Osaka)", "lead": "17 yaşındaki Shūsaku (4. dan), dönemin en güçlü oyuncularından Gennan’la (8. dan) oynadı. 127. hamlede Gennan’ın kulaklarının kızardığı anlatılır; adı buradan gelir. O zaman komi yoktu: Siyah 2 puanla kazandı.",
      c: {
        "0": "Osaka, 1846. Shūsaku Siyah, Gennan Beyaz. Bir gün önce iki taş handikapla başlayan oyun yarıda kalmıştı; bu kez Shūsaku handikapsız Siyah oynuyor.",
        "1": "Siyah 1, sağ üst köşede 3-4 noktasına (R16). Köşeyi kolayca güvenceye alan alçak bir nokta.",
        "2": "Beyaz 2, sol üst köşede 3-4 noktası (D17). Önce boş köşeler paylaşılır.",
        "5": "1, 3 ve 5 ile Siyah üç köşeyi de 3-4 noktalarında aldı. Shūsaku’nun sevdiği bu açılış sonradan çok incelendi.",
        "6": "Beyaz 6, sol kenarda C14. Siyahın köşesine yaklaşmak yerine kenara yerleşiyor; biraz alışılmadık bir seçim.",
        "7": "Siyah 7 (E4), sol alt köşeyi ikinci bir taşla kapatıyor. Bu “kapama” köşeyi çok sağlam yapar.",
        "8": "Beyaz 8 (R5), Siyahın Q3 köşesine yaklaşıyor. Sağ altta büyük bir mücadele başlamak üzere.",
        "10": "Beyaz 10 (O4) taisha’dır: Siyah taşı uzaktan çapraz örter. Çok sayıda varyantı vardır ve Gennan’ın en sevdiği hamleydi.",
        "11": "11 (Q5) ile Siyah zor bir yola giriyor. Gennan taisha’yı çok iyi biliyordu; dikkatli olmak gerek.",
        "24": "Sağ altta taşlar birbirine girdi; iki taraf da diğerini kesmeye çalışıyor. Beyaz 24’ten (N4) sonra Siyah taşlar dışarı zor çıkıyor.",
        "25": "Siyah 25 (N3). Sonraki incelemelere göre burada daha iyi bir hamle vardı. Bir usta için bile zor bir andı.",
        "28": "28 (M3) ve 30 (L2) ile Beyaz hemen zayıflığa vuruyor. Siyah taşlar alt kenarda dar bir yere kapanabilir.",
        "31": "Siyah 31 (M4) önemli. Yaklaşan ko’ya —karşılıklı alıp geri alma mücadelesine— hazırlanıp Beyazın cevap vermesi gereken tehditler yaratıyor.",
        "36": "Beyaz 36 (N2). Ko’yu başlatmadan önce Beyaz önce buraya oynuyor. İyi zamanlama.",
        "40": "Beyaz 40 (R1) bir taş alıyor ve ko başlıyor. Taşını kaybeden taraf hemen geri alamaz; önce başka yerde bir tehdit oynar.",
        "41": "Siyah 41 (O5) bir ko tehdidi. Biraz kaybettiriyor ama burada daha iyisi yok.",
        "53": "Siyah 53 (R10), pek az kişinin bulacağı yaratıcı bir fikir. Sağ kenardaki Beyaz şekle saldırıyor.",
        "60": "Beyaz 60 (S3) büyük bir hamle. Ardından 62’yi (M1) de inisiyatifle oynayabiliyor.",
        "63": "Siyah 63 (O1) ile sağ alttaki uzun mücadele duruluyor. Beyazın altta bölgesi, Siyahın sağda kalın bir duvarı var. Şimdilik Beyaz daha iyi görünüyor.",
        "67": "Siyah 67 (L17). Sağdaki duvara dayanarak üst kenarda geniş bir çerçeve kuruyor.",
        "72": "Beyaz 72 (P13) harika bir hamle. Siyah duvarın hemen üstünde, Siyah çerçevenin büyümesini engelliyor.",
        "74": "Buradan yaklaşık 100. hamleye kadar Gennan hiç gevşemiyor. Saldırılardan kaçıyor ve taşlarını bağlı tutuyor.",
        "83": "Siyah 83 (H3), alttaki Beyaz bölgeye girip onu küçültmeye çalışıyor.",
        "96": "Beyaz 96’dan (R14) itibaren sağ üstteki Siyah köşe çevresinde ince bir mücadele var. Beyaz yine iyi bir şekil buluyor.",
        "107": "Siyah 107 (P10) bir Beyaz taşı alıyor. Sağdaki Siyah grup artık güvende.",
        "118": "Beyaz 118 (M19) bir taş alıyor ve üstteki grubu da yaşıyor. Siyahın üstteki çerçevesi beklenenden küçük kalıyor.",
        "126": "Beyaz 126 (J5). Beyaz altta kalın ve merkeze uzanıyor. İzleyen profesyonellerin çoğunun Beyazı önde gördüğü söylenir.",
        "127": "İşte ünlü “kızaran kulaklar” hamlesi, Siyah 127 (K11). Merkezdeki bu tek taşın dört yöne birden çalıştığı söylenir: üstteki Siyah alanı genişletir, alttaki Beyaz kalınlığı zayıflatır, sağdaki Siyah gruba yardım eder ve Beyazın sola yayılmasını engeller.",
        "128": "O anda oyunu izleyen bir doktor, Gennan’ın kulaklarının kızardığını fark etti. Go’dan pek anlamazdı ama bunu bir sarsılma işareti sayıp Siyahın kazanacağını söylediği anlatılır.",
        "131": "Siyah 131 (D10). Siyah sol kenardaki Beyaz düzene de giriyor ve her yerde Beyaz bölgeyi azaltıyor.",
        "147": "Siyah 147 (K10). 127. hamledeki taş işe yaramaya başlıyor; Siyah merkezde Beyaz grupların arasından ilerliyor.",
        "160": "Beyaz 160 (H8). Merkezdeki taşlarını korurken sol alttaki Siyah grubu da hedefliyor. Oyun hâlâ çok yakın.",
        "167": "Siyah 167 (C2) isabetli. Sol alt köşedeki Siyah taşlar güvende, Beyazın tehdidi ortadan kalktı.",
        "175": "Siyah 175 (G4) bir Beyaz taş alıyor. Alttaki Beyaz bölge ilk göründüğü kadar büyük değil.",
        "199": "Siyah 199 (K7). Merkezdeki savaş duruluyor ve oyun sınırların çizildiği, her puanın önemli olduğu bitiş aşamasına giriyor.",
        "212": "212 (D19) ve 216 (F19) ile Beyaz üst kenarda Siyah taşlar alıyor. Bitişte kimse geri adım atmıyor.",
        "228": "Beyaz 228 (N12) merkezde bir ko yaratıyor. 80’den fazla hamle boyunca M13 ve N13’te sırayla taş alınıyor.",
        "236": "Ko sırasında oynanan Beyaz 236 (T8) bir taş alıyor. Bazı analistlere göre ko’yu burada bitirmek oyunu daha da yakın yapardı.",
        "275": "Siyah 275 (T14) iki Beyaz taş alıyor. Ko boyunca iki taraf da tahtanın her yerinde kazanıp kaybediyor.",
        "299": "Siyah 299 (J16) bir anda dört Beyaz taş alıyor. Siyah üst kenarı sağlam tutuyor.",
        "311": "Siyah 311 (M13) ko’yu kapatıyor. Uzun ko mücadelesi sonunda bitti.",
        "325": "Oyun 325 hamlede bitiyor ve sayımda Siyah 2 puan önde. Komi olmasa da 17 yaşındaki birinin Gennan gibi bir ustayı yenmesi büyük ses getirdi ve Shūsaku’nun adı duyuldu."
      } },
    "evergreen": { "t": "Her Daim Yeşil Oyun", "w": "Adolf Anderssen", "b": "Jean Dufresne", "ev": "Dostça bir oyun (turnuva değil)", "d": "1852", "pl": "Almanya (muhtemelen Berlin)", "lead": "Ölümsüz Oyun’un sahibi Anderssen, bir yıl sonra bu ikinci başyapıtı oynadı. Siyah mat tehdidi kurduğu anda Beyaz sakince bir kaleyi oynatır, sonra veziri verip çifte şahla bitirir. Hiç solmadığı için “her daim yeşil” (Evergreen) denir.",
      c: {
        "0": "1852’de bir dergide yayımlanan oyun. Beyaz Anderssen, siyah arkadaşı Dufresne. Berlin’de oynandığı düşünülür ama bunu kesin gösteren bir kayıt yoktur.",
        "1": "Beyaz şah piyonunu iki kare ilerletir.",
        "2": "Siyah da aynısını yapar.",
        "3": "At e5 piyonuna saldırır.",
        "4": "Siyah e5’i bir atla korur.",
        "5": "Fil çıkar ve f7’ye bakar.",
        "6": "Siyah da bir fil çıkarır.",
        "7": "b4! Evans Gambiti denen bir piyon teklifi. Siyah alırken Beyaz merkezi sağlamlaştırır.",
        "8": "Siyah piyonu alır.",
        "9": "c3 fili kovalar ve d4’e hazırlanır.",
        "10": "Fil a5’e çekilir.",
        "11": "d4 merkezi alır.",
        "12": "Siyah piyonu alır.",
        "13": "Beyaz geri almaz, rok yapar. Şahın güvenliği ve taşların hareketi piyondan önce gelir.",
        "14": "Siyah piyon d3’e kadar ilerler, Beyaz’ın kampının içine girer.",
        "15": "Vezir b3’e. c4’teki fille birlikte f7’ye nişan alır.",
        "16": "Siyah f7’yi veziriyle korur.",
        "17": "e5 veziri kovalar.",
        "18": "Vezir g6’ya.",
        "19": "Kale e1’e; e hattına girip e5 piyonunu destekler.",
        "20": "Siyah rok için bir at çıkarır.",
        "21": "Fil a3’e, çaprazdan e7’deki ata bakar. Bu at oynarsa fil f8’e ulaşır; bu yüzden Siyah’ın kısa rok yapması zorlaşır.",
        "22": "Siyah Beyaz’ın taşlarını uzaklaştırmak için bir piyon sunar.",
        "23": "Vezir alır.",
        "24": "Kale b8’e, b hattında veziri kovalar.",
        "25": "Vezir a4’e.",
        "26": "Fil b6’ya çekilir.",
        "27": "Bir at çıkar. Beyazın neredeyse tüm taşları oyunda.",
        "28": "Siyah öbür fili çıkarır.",
        "29": "At e4’e, gözü f6’da.",
        "30": "Siyah vezir f5’e gidip e4’teki ata saldırır.",
        "31": "Fil d3 piyonunu alır ve e4’teki atı korur.",
        "32": "Vezir h5’e, f3’teki ata nişan alır.",
        "33": "At f6’da şah çekerek feda edilir!",
        "34": "Siyah piyonla alır.",
        "35": "Beyaz piyonla geri alır ve e7’deki ata saldırır. e hattında e1’deki kale de e7’ye bakıyor.",
        "36": "Kale g8’e, g2’ye nişan alır. h5’teki vezir f3’te alırsa mat çok yakın.",
        "37": "Kale sakince d1’e! Beyaz şah tehlikede ama Beyaz savunmak yerine d7’ye yönelir. Oyunu “her daim yeşil” yapan hamle budur.",
        "38": "Siyah f3’teki atı alır. Sonra g2’de almak mat olurdu.",
        "39": "Ama sıra Beyaz’da. Kale e7’deki atı şah çekerek alır!",
        "40": "Siyah c6’daki atla geri alır. Artık a4’ten d7’ye çapraz açık.",
        "41": "Vezir d7’de şah çekerek feda edilir!",
        "42": "Siyah şahla almak zorunda.",
        "43": "Fil şah çekerek f5’e gider ve d1’deki kalenin d hattını açar: çifte şah.",
        "44": "Şah e8’e. c6’ya gitseydi fil d7’de mat ederdi.",
        "45": "Fil d7’de şah.",
        "46": "Şah f8’e.",
        "47": "a3’teki fil e7’deki atı alır: mat! d7’deki fil e8’i, f6’daki piyon e7 ve g7’yi tutar."
      } },
    "lasker1912": { "t": "Şah Avı", "w": "Edward Lasker", "b": "George Alan Thomas", "ev": "City of London Satranç Kulübü’nde hızlı, dostça bir oyun", "d": "1912", "pl": "Birleşik Krallık (Londra)", "lead": "Londra’daki bir kulüpte hızlı ve dostça bir oyun. Beyaz veziri verir ve siyah şahı tahtanın bir ucundan öbür ucuna, g8’den g1’e kadar kovalar. Açılış hamlelerinin sırası kayıtlarda biraz farklıdır ama 10. hamleden sonraki konum aynıdır.",
      c: {
        "0": "Ekim 1912, City of London Satranç Kulübü. Beyazda Almanya’dan yeni gelmiş genç bir mühendis olan Edward Lasker, siyahta sonradan İngiltere şampiyonu olan George Alan Thomas var. Hızlı ve dostça bir oyundu. “Şah avı” olarak ünlüdür: Siyah şah g8’den tahtanın öbür ucundaki g1’e kadar kovalanır. Lasker sonra Amerika’ya gitti ve satranç kitaplarıyla tanındı.",
        "1": "Beyaz vezir piyonu d4 ile başlar. e5 ve c5’i tutar, c1’deki filin yolunu açar.",
        "2": "Siyah e6 oynar: önce sağlam bir dizilim, sonra f5 ya da d5.",
        "3": "At f3’e. e5’i tutar ve şah kanadının savunmasına yardım eder: en doğal kare.",
        "4": "Siyah f5 oynayıp e4’ü tutar; Hollanda Savunması’na benzer. Ama şahın önündeki piyonu oynatmak şahı biraz zayıflatır.",
        "5": "Öbür at c3’e gelir; f5 piyonuna vurmak için e4’e hazırlanır.",
        "6": "Siyah atı f6’ya çıkarır: e4’ü daha da tutar ve roka hazırlanır.",
        "7": "Fil g5’e, f6’daki ata nişan alır. Bu at siyah şahın önemli bir savunucusudur, Beyaz onu erkenden kaldırmak ister.",
        "8": "Siyah fili e7’ye koyup atı korur ve roka yaklaşır.",
        "9": "Beyaz fili atla değişir. Siyah şahı koruyan at gitti.",
        "10": "Siyah filiyle geri alır. Artık şah kanadını koruma işi f6’daki file kaldı.",
        "11": "e4! Beyaz f5 piyonuna vurur ve merkezde alan kazanır. Hatlar açılır, beyaz taşlar daha rahat oynar.",
        "12": "Siyah e4’teki piyonu alır. Almasa Beyaz e5 oynayıp siyah taşları geri iterdi.",
        "13": "At geri alıp merkeze yerleşir; f6’daki file ve g5, d6 karelerine bakar.",
        "14": "Siyah b6 oynar; fili b7’ye getirip uzun çaprazdan e4’teki ata nişan almak ister.",
        "15": "At e5’e: merkezde güçlü bir kare, g4 ve f7’ye de bakıyor. İki beyaz at artık siyahın şah kanadına yakın.",
        "16": "Siyah rok yapar. Şah g8’de. Ama f piyonu olmadığı için şahın çevresinde çok boşluk var.",
        "17": "Fil d3’e. Şimdilik e4’teki kendi atı önünü kesiyor ama arkasında h7 piyonu var. e4’teki at oynadığı anda bu fil doğrudan h7’ye bakacak.",
        "18": "Siyah fil b7’ye gidip uzun çaprazdan e4’teki ata nişan alır ve beyaz taşları kısıtlar.",
        "19": "Vezir h5’e, yalnızca siyah şahın koruduğu h7 piyonuna nişan alır. Beyazın veziri, fili ve atları hepsi siyah şaha dönmüş durumda.",
        "20": "Siyah veziri e7’ye koyar. f6’daki fili korur ve c5’e gitmeye hazırlanır ama Beyaz’ın fikrini görmez. h6 ya da e5’teki atı almak gerekiyordu. İşte dönüm noktası.",
        "21": "Vezir h7’de şah çekerek feda edilir! Beyaz en güçlü taşını bedavaya verir. Lasker şahı mata kadar kovalamanın tüm yolunu görmüştü.",
        "22": "Siyah şahla almak zorunda; şah h7’ye çekildi.",
        "23": "At f6’daki fili alarak şah çeker. Aynı anda e4 boşalır ve d3’teki fil de h7’deki şaha şah çeker: çifte şah. Araya taş konamaz, şah kaçmalı.",
        "24": "Şah h6’ya. h8’e gitseydi öbür at g6’ya sıçrayıp mat ederdi. Şah giderek öne itiliyor.",
        "25": "Öbür at e5’ten g4’e şah çekerek sıçrar, h6’daki şaha saldırıp onu daha da ileri iter.",
        "26": "Şah g5’e: kendi kampını bırakıp Beyaz tarafına yürüyor.",
        "27": "h piyonuyla şah! Piyonlar bile ava katılıyor. Şah ilerlemeye devam etmek zorunda.",
        "28": "Şah f4’e. Tahtanın ortasını geçti ve Beyaz’ın kampına giriyor.",
        "29": "Yine şah, bu kez g piyonuyla. İki piyon şahın dönüş yolunu kapatıyor.",
        "30": "Şah f3’e, beyaz taşların tam ortasına.",
        "31": "Fil d3’ten e2’ye çekilip şah çeker. Şah daha da içeri itilir.",
        "32": "Şah g2’ye. e1’deki beyaz şah artık uzak değil.",
        "33": "Kale h2’de şah. Sonunda kale de oyuna giriyor.",
        "34": "Şah sonunda g1’e varır. g8’den çıkıp tahtanın öbür ucundaki birinci sıraya geldi.",
        "35": "Beyaz şah e1’den d2’ye gider. Böylece a1’deki kalenin yolu açılır ve kale birinci sıradan g1’deki şaha şah çeker: mat! Uzun rok da mat ederdi ama Lasker şahı oynadı. Hızlı bir oyunda veziri verdikten sonra Beyaz, şahı on dört hamle boyunca kendi kampının en derin köşesine kadar kovaladı. Çok nadir bir oyun."
      } },
    "toketsu": { "t": "Kan Kusma Oyunu", "w": "Akaboshi Intetsu", "b": "Hon’inbō Jōwa", "ev": "Suō beyi Matsudaira’nın konağında oynandı (dört gün)", "d": "1835", "pl": "Japonya (Edo)", "lead": "Japon go’sunun en yüksek makamı Meijin Godokoro için verilen mücadeleden doğan bir oyun. Inoue Gennan Inseki, öğrencisi Akaboshi Intetsu’yu Meijin Jōwa’nın karşısına çıkardı. Dört günlük çetin savaşın sonunda Intetsu kaybetti ve tahtanın başında kan kustuğu anlatılır.",
      c: {
        "0": "1835. Siyah: Akaboshi Intetsu (7. dan); Beyaz: Meijin Hon’inbō Jōwa. Gennan en iyi öğrencisini gönderdi; 7. dana yenilen bir Meijin’in unvanı hak etmediğini söyleyecekti.",
        "1": "Siyah 1, sol altta 3-4 noktası (C4). Intetsu sakin başlıyor.",
        "4": "Dört hamleden sonra her köşede bir taş var: Beyaz sağ alt ve sol üstte, Siyah sol alt ve sağ üstte.",
        "6": "Beyaz 6 (E3) şimdiden sol alttaki Siyah köşeye yaklaşıyor. Jōwa baştan aktif.",
        "10": "Beyaz 10 (P4) sağ alt köşeyi ikinci bir taşla kapatıyor.",
        "12": "Beyaz 12 (D6), sol alttaki Siyah köşeye yukarıdan bastırıyor. Oyunun en büyük savaşı burada başlıyor.",
        "13": "Siyah 13 (E4) bir Beyaz taşa doğrudan yapışıyor. Siyah savaşı kabul ediyor.",
        "20": "Beyaz 20 (C3) Siyah köşenin altına giriyor: köşe bölgesini azaltırken kendi taşlarını yaşatmaya çalışıyor.",
        "28": "Beyaz 28 (C9) sol kenarda çok ileri uzanıyor. Sıklıkla aşırı genişleme sayılır; Jōwa’ya özgü sert bir hamle.",
        "33": "Siyah 33 (C2). Inoue okulunun gizlice çalıştığı yeni bir varyant olduğu söylenir. Merkezdeki dayanaksız Beyaz taşlara saldırırken soldaki Beyaz taşları da yutmayı hedefler.",
        "36": "Beyaz 36 (F3). Sol altta Siyahı dışarıdan kapatırken kendi taşlarını bağlamaya çalışıyor.",
        "43": "Siyah 43 (E9). Soldaki Beyaz taşlar zor durumda. Buraya kadar Intetsu iyi oynadı ve öne geçtiği kabul edilir.",
        "45": "Siyah 45 (D11) sol kenarda yukarı uzanıyor; Beyaz taşları ayrı tutarken kendini güçlendiriyor.",
        "50": "Beyaz 50 (C16). Sol altı şimdilik bırakıp sol üst köşeye dönüyor.",
        "53": "Siyah 53 (G17). Siyah üst kenara girerek Beyazın sol üst köşeyi genişletmesini engelliyor.",
        "58": "Beyaz 58 (C14) sol üst köşeden kenar boyunca yayılıp soldaki Siyah taşlara yaklaşıyor.",
        "60": "Beyaz 60 (G4) iki Siyah taş alıyor. Sol alttaki Beyaz grup nihayet biraz nefes alıyor.",
        "62": "Beyaz 62 (J17). Üstte de iki taraf karşı karşıya. Tahtanın her yerinde zayıf taşlar var; zor bir pozisyon.",
        "66": "Beyaz 66 (B14). Sol üst köşe çevresinde Beyaz taşlarını sağlamlaştırıyor.",
        "68": "Beyaz 68 (B11). Bunu izleyen birkaç Beyaz hamle ve 80. hamle, Jōwa’nın parlak hamleleri olarak ün kazandı. O kadar şaşırtıcıydılar ki onları hayaletlerin gösterdiği söylendi.",
        "70": "Beyaz 70 (E12). Soldaki Siyaha doğrudan cevap vermek yerine önce başka bir kilit noktaya oynuyor. Gizli olanaklar buna izin veriyor.",
        "72": "Beyaz 72 (R13). Sağ kenara yönelip sağ üstteki Siyah alanın büyümesini engelliyor.",
        "76": "Beyaz 76 (O14). Sağ kenarı merkeze bağlayıp Siyah taşları bölmeye hazırlanıyor.",
        "80": "Beyaz 80 (Q10) genelde kötü sayılan “boş üçgen” şeklini yapıyor. Oysa bu hamle Siyahı ikiye bölüp saldırmanın dayanağı oldu. Çirkin görünen ama mükemmel hamlenin klasik örneğidir.",
        "83": "Siyah 83 (R3) sağ alttaki Beyaz köşeye giriyor. Orada sert bir alma-verme savaşı başlıyor.",
        "91": "Siyah 91 (Q4) bir Beyaz taş alıyor. Sağ alt köşe Siyah için çok önemli.",
        "98": "Beyaz 98 (M4). Alttaki Siyah taşları dıştan sarıp kolayca yaşamalarına izin vermiyor.",
        "106": "Beyaz 106 (S5) bir Siyah taş alıyor. Sağ alt köşe Beyazda kalıyor; Siyah taşlar dışarı kaçmak zorunda.",
        "113": "Siyah 113 (K6). Alttaki Siyah taşlar merkeze çıkarak yaşam arıyor.",
        "120": "Beyaz 120 (N9) kaçan Siyah taşların yolunu kesiyor. Merkezde kimin taşlarının önce zayıflayacağı belirleniyor.",
        "128": "Beyaz 128 (L11) merkezdeki Siyah taşlara yukarıdan da bastırıyor. Siyah hâlâ rahatlayamıyor.",
        "138": "Beyaz 138 (K8) bir taş alıyor ve merkezde ko başlıyor. Yaklaşık 30 hamle boyunca K8 ve L8’de sırayla taş alınıyor.",
        "152": "Beyaz 152 (E11) bir ko tehdidi. Ko boyunca Beyaz her yerde Siyahın cevap vermesi gereken hamleler buluyor.",
        "170": "Beyaz 170 (P15). Merkezdeki ko duruldu; Beyaz sağ üste geçip henüz tam yaşamayan büyük bir Siyah grubu hedefliyor.",
        "178": "Beyaz 178 (J14) üst bölgenin ortasına atlayıp Siyah taşları sol ve sağ olarak ayırıyor. 80. hamleden beri hazırlanan bölme saldırısı asıl şimdi başlıyor.",
        "193": "Siyah 193 (J11) bir Beyaz taş alıyor. Siyah bağlanmak ve yaşamak için çabalıyor.",
        "201": "Siyah 201 (R14) bir taş alıyor ve sağ kenarda R14 ile R15’te yeni bir ko başlıyor.",
        "206": "Beyaz 206 (M13). Ko sırasında bile Beyaz merkezdeki Siyah taşları yavaş yavaş sıkıştırıyor.",
        "222": "Beyaz 222 (L14) bir taş alıyor. Üstteki Siyah taşlar ikiye bölünmüş durumda; ikisini de kurtarmak zorlaşıyor.",
        "230": "Beyaz 230 (C13) sol kenardaki Siyah zayıflığa da vuruyor. Beyaz taşlar artık tahtanın her yerinde sağlam bağlı.",
        "237": "237 (F12) ve 239 (E13) ile Siyah sol üstte taş geri alıyor. Yine de genel fark kapanmıyor.",
        "246": "Beyaz 246’dan (L8) sonra Intetsu pes etti. Taşlar toplanırken tahtaya kan kustuğu anlatılır. Muhtemelen bir süredir hastaydı ve kısa süre sonra öldü. Jōwa için kariyerinin en büyük zaferi sayılır."
      } },
    "deepblue1997": { "t": "Deep Blue’nun Zaferi", "w": "Deep Blue (IBM bilgisayarı)", "b": "Garri Kasparov", "ev": "IBM’in Deep Blue’suyla rövanş maçının 6. oyunu (altı oyunluk maç)", "d": "1997", "pl": "ABD (New York)", "lead": "Dünya şampiyonu Kasparov, IBM’in yaptığı satranç bilgisayarı Deep Blue’ya karşı altı oyunluk bir maçta. Beş oyundan sonra skor eşitti; son oyun yalnızca 19 hamlede bitti. Bir bilgisayar ilk kez birkaç oyunluk tam bir maçta dünya şampiyonunu yendi.",
      c: {
        "0": "New York, 11 Mayıs 1997. Bir önceki yılın maçını Kasparov kazanmıştı. Bu kez beş oyundan sonra skor 2½–2½. Beyaz Deep Blue.",
        "1": "Beyaz şah piyonunu iki kare ilerletir.",
        "2": "Kasparov c6 oynar: Caro-Kann Savunması.",
        "3": "Beyaz öbür piyonu da merkeze getirir.",
        "4": "Siyah d5 ile e4’e vurur.",
        "5": "At e4’ü korur.",
        "6": "Siyah e4’teki piyonu alır.",
        "7": "At geri alır.",
        "8": "Siyah atı d7’ye koyar; sonra öbür atı f6’ya çıkaracak.",
        "9": "At g5’e sıçrar: f7 ve e6’ya nişan alan keskin bir plan.",
        "10": "Siyah atı f6’ya çıkarır.",
        "11": "Fil d3’e, siyahın şah kanadına bakar.",
        "12": "Siyah e6 ile savunmayı güçlendirir.",
        "13": "Öbür at da f3’e çıkar.",
        "14": "Siyah g5’teki atı kovmak için h6 oynar. Ama bu konumda Beyaz için bir at fedası zaten biliniyordu. Kasparov için alışılmadık bir seçim olduğu söylenir.",
        "15": "At e6’da feda edilir! Deep Blue’nun bu hamleyi önceden kaydedilmiş açılış hamlelerinden oynadığı söylenir.",
        "16": "Siyah hemen almaz, veziri e7’ye getirir. e hattında e6’daki ata ve arkasındaki beyaz şaha nişan alır.",
        "17": "Beyaz rok yapıp şahı güvene alır.",
        "18": "Siyah atı alır ve malzemede öne geçer.",
        "19": "Fil g6’da şah. f7 piyonu olmadığı için çapraz şaha kadar açık.",
        "20": "Şah d8’e. Siyah artık rok yapamaz ve şah merkeze yakın kalır.",
        "21": "Öbür fil de çıkar ve siyah şahın çevresindeki karelere bakar.",
        "22": "Siyah b5 oynar; vezir kanadında şah ve fil için yer açmak ister.",
        "23": "a4, b5 piyonuna vurur.",
        "24": "Siyah fili b7’ye getirir.",
        "25": "Kale e1’e. e hattında e6 piyonuna, onun arkasında da e7’deki vezire bakar.",
        "26": "Siyah at d5’e gidip f4’teki file saldırır.",
        "27": "Fil g3’e çekilir.",
        "28": "Siyah şah c8’e, biraz daha güvenli.",
        "29": "Beyaz b5 piyonunu alır.",
        "30": "Siyah geri alır.",
        "31": "Vezir d3’e; b5 piyonuna ve f5 karesine bakar.",
        "32": "Siyah b5’i filiyle korur.",
        "33": "Fil f5’e! Bedavaya alınabilir.",
        "34": "Siyah piyonla alır. Ama böylece e hattındaki piyon gider.",
        "35": "Kale e7’deki veziri alır. Beyaz at, fil ve kale verdi ama veziri kazandı.",
        "36": "Siyah kaleyi filiyle geri alır.",
        "37": "c4! Piyon aynı anda b5 ve d5’e vurur ve Siyah’ın savunması çökmeye başlar. Kasparov burada terk etti; muhtemelen şahının saldırıyı durduramayacak kadar açık olduğunu düşündü. Bir bilgisayar dünya şampiyonuna karşı bir maç kazanmıştı."
      } },
    "seigen1933": { "t": "3-3, Yıldız ve Tengen Oyunu", "w": "Go Seigen", "b": "Hon’inbō Shūsai", "ev": "Meijin ile anma oyunu (üç aydan uzun)", "d": "1933–1934", "pl": "Japonya (Tokyo)", "lead": "19 yaşındaki Go Seigen (5. dan), Meijin Hon’inbō Shūsai ile oynadı. Siyahla önce 3-3 noktasına, sonra bir yıldız noktasına, sonra tam merkeze (tengen) oynayarak dönemin bütün kurallarını yıktı ve go dünyasını şaşırttı. Birçok aranın ardından oyun üç aydan uzun sürdü; Beyaz 2 puanla kazandı.",
      c: {
        "0": "1933. O yıl Go Seigen ve arkadaşı Kitani Minoru “Shinfuseki” adlı yeni bir açılış tarzını yayıyordu. Herkes bunu Meijin’e karşı nasıl kullanacağını merak ediyordu.",
        "1": "Siyah 1, sağ üstte 3-3 noktası (R17). Köşeyi tek hamlede alır ama dışarıya etkisi azdır; o zamanlar kimse bunu ilk hamle saymazdı.",
        "3": "Siyah 3, sol altta yıldız noktası (D4). 3-3’ün aksine dışa yayılmayı öne çıkarır.",
        "5": "Siyah 5 tahtanın tam ortasına, tengen’e (K10). Ne köşe ne kenar, doğrudan merkez. Go Seigen yeni fikirlerini Meijin’e açıkça gösterdi.",
        "6": "3-3, yıldız, tengen: her Siyah taşın ayrı görevi var — köşe bölgesi, dışa etki ve merkez gücü. Beyaz 6 (Q16) ile Siyahın 3-3 taşının hemen yanına oynuyor.",
        "9": "Siyah 9 (P18). Sağ üst köşeyi derli toplu ve güvenle yerleştiriyor; 3-3’e yakışan, önce bölge tarzı.",
        "11": "Siyah 11 (K4), tengen’in hemen altında alt kenarın ortasına. O taşla birlikte altta büyük bir alan hedefliyor.",
        "12": "Beyaz 12 (M3) hemen alt kenara girerek Siyahın büyük bir çerçeve kurmasını engelliyor. Meijin telaşsızca Siyahın planlarını tek tek bozuyor.",
        "13": "Siyah 13 (D10), bu kez sol kenarın ortasında. Siyah taşlar yüksekte duruyor ve birlikte geniş bir çerçeve kuruyor.",
        "14": "Beyaz 14 (E16) sol üst köşeyi ikinci bir taşla kapatıyor. Meijin yeni tarzdan etkilenmeden köşeyi sakince sağlamlaştırıyor.",
        "21": "Siyah 21 (G10) tengen’i soldaki taşa bağlıyor; Siyahın etkisi merkeze yayılıyor.",
        "28": "Beyaz 28 (D3) sol alttaki Siyah yıldız taşının altına girip köşeyi alıyor. Siyah, dış güç karşılığında köşeyi veriyor.",
        "30": "Beyaz 30 (Q12) sağ kenarda açılıyor ve Siyahın 3-3 köşesinin üstüne de kapak koyarak etkisini azaltıyor.",
        "37": "Siyah 37 (P15) bir Beyaz taş alıyor. Sağ üstte iki taraf yakın bir mücadelede çarpışıyor.",
        "40": "Beyaz 40 (O10) sağ kenardan merkeze doğru bir adım atıp tengen çevresindeki Siyah etkiye yaklaşıyor.",
        "44": "Beyaz 44 (H17) üst kenarda bir nokta alarak Siyahın yukarı yayılmasını durduruyor.",
        "45": "Siyah 45 (R7), sağ alttaki Beyaz düzene el atıyor. Sağ kenardan bu köşeye uzanan uzun bir savaş başlıyor.",
        "59": "Siyah 59 (R4) sağ alt köşeye de girip Beyaz bölgeyi küçültüyor.",
        "70": "Beyaz 70 (N6) alttan merkeze ilerleyip sağ alttaki Siyah taşları merkezdekilerden ayırmaya çalışıyor.",
        "79": "Siyah 79 (L9) tengen çevresinde merkezi sağlamlaştırıyor. Şimdiye kadar oyun oldukça dengeli görünüyor.",
        "80": "Beyaz 80 (C6) sol alt köşeden sol kenar boyunca ilerleyip oradaki Siyah taşları hedefliyor.",
        "98": "Beyaz 98 (A11) iki Siyah taş alıyor. Sol kenarda temizce yaşıyor; Siyahın sol tarafı planlanandan küçük kalıyor.",
        "101": "Siyah 101 (S14) sağ üste dönüp sağ kenardaki Beyaz düzeni küçültüyor.",
        "105": "Siyah 105 (K17) üst kenarın ortasını alıp oradaki Beyaz taşlara saldırmaya başlıyor.",
        "117": "Siyah 117 (F17) sol üstteki Beyaz köşenin çevresine de giriyor; bütün üst kenar savaş alanına dönüyor.",
        "124": "Beyaz 124 (K15) üstteki taşlarını merkeze kaçırırken Siyah taşların arasını kesiyor.",
        "135": "Siyah 135 (E9) iki Beyaz taş alıyor. Sol kenarda biraz geri kazanıyor.",
        "138": "Beyaz 138 (N18) üst kenarda bölgesini sağlamlaştırıyor. Bütün tahtaya bakınca durum çok yakın.",
        "153": "Siyah 153 (K14). Merkezdeki Siyah taşlar üstü ve altı bağlayan kalın bir yol oluşturuyor. Asıl soru, Beyazın bu kalınlığı nasıl kıracağı.",
        "159": "Siyah 159 (F4) sol altı sağlamca savunuyor. Beyazın sıradaki hamlesi oyunun en ünlü hamlesi.",
        "160": "Beyaz 160 (H8), Siyah kalınlığındaki bir boşluğa atlıyor: aynı anda birkaç amacı olan keskin bir hamle; Beyaz buradan Siyah merkeze girmeye başlıyor. Bu hamleyi Shūsai’nin değil bir öğrencisinin bulduğu söylentisi yayıldı, ama hiç kanıtlanmadı.",
        "161": "Siyah 161 (J8) hemen cevap veriyor ama Beyazın birden fazla hedefi var.",
        "162": "Beyaz 162 (K12) merkezin üst tarafına geçip Siyah taşların bağlantılarını tehdit ediyor.",
        "172": "Beyaz 172 (F13) merkezdeki taşları sol üste bağlıyor. Yavaş yavaş Siyahın merkezdeki kalınlığı bölgeye dönüşemez oluyor.",
        "178": "Beyaz 178 (N9) merkezin sağında da Siyah alana giriyor.",
        "187": "187 (M6) ve 189 (L7) ile Siyah Beyaz taşlar alarak karşılık veriyor. Yine de Beyaz önemli noktalara daha önce yetişmişti.",
        "198": "Beyaz 198 (E12) bir taş alıyor. Sol üstteki Beyaz taşlar da bağlandı; Beyaz genel olarak biraz önde.",
        "203": "Siyah 203 (B3). Buradan sonrası bitiş: kenarlardaki sınırlar puan puan belirleniyor.",
        "224": "Beyaz 224 (T10) bir taş alıyor. Sağ kenarda bile tek puan vermiyor.",
        "233": "Siyah 233 (L13) iki Beyaz taş alıyor. Siyah sonuna kadar kovalıyor.",
        "252": "Oyun 252 hamlede bitiyor: Beyaz 2 puanla kazanıyor. Komi olmadığından ilk oynayan Siyahın küçük bir avantajı vardı ama Meijin sonuna kadar sarsılmadı. Yine de Go Seigen’in 3-3, yıldız ve tengen’i büyük ses getirdi ve açılışlarda yeni bir çağı müjdeledi."
      } },
    "century1956": { "t": "Yüzyılın Oyunu", "w": "Donald Byrne", "b": "Bobby Fischer", "ev": "Üçüncü Rosenwald Kupası turnuvası (Rosenwald Anma Turnuvası)", "d": "1956", "pl": "ABD (New York)", "lead": "On üç yaşındaki Bobby Fischer, ABD’nin en güçlü ustalarından Donald Byrne’ı yener. 17. hamlede Fischer vezirini bedavaya aldırır, sonra taşları birer birer geri kazanır ve sonunda küçük taşlarıyla beyaz şahı kıstırır. Fischer sonradan dünya şampiyonu oldu.",
      c: {
        "0": "New York, 17 Ekim 1956, bir turnuva oyunu. Siyahta on üç yaşındaki Fischer, beyazda ABD’nin en iyi oyuncularından Byrne var.",
        "1": "Beyaz bir atla başlar.",
        "4": "Fischer g6 oynar; fili uzun çapraza yerleştirmeye hazırlanır.",
        "8": "Siyah rok yapar: önce şah güvende.",
        "10": "Siyah d5 oynar. Merkez kavgası başlar.",
        "15": "Beyaz e4 ile merkezde yan yana iki piyon kurar.",
        "17": "Kale d1’e, d4 piyonunu destekler. Beyaz hâlâ rok yapmadı.",
        "18": "At b6’ya gider ve c4’teki veziri kovalar.",
        "20": "Fil g4’e, f3’teki ata baskı yapar.",
        "21": "Beyaz fil g5’e gider. Beyaz şah hâlâ ortada.",
        "22": "At a4’e! Alınabileceği bir kareye sıçrar. Fikir şu: c3’teki at giderse e4 piyonu korumasız kalır.",
        "23": "Beyaz atı almaz, veziri a3’e götürür.",
        "26": "Siyah at e4 piyonunu alır. Beyazın merkezi çöküyor.",
        "27": "Beyaz fil e7 piyonunu alır ve aynı anda siyah vezire ve f8’deki kaleye saldırır.",
        "28": "Vezir b6’ya! Siyah f8’deki kaleyi bırakır. Fischer, beyaz şahın hâlâ ortada olmasına güvenir.",
        "29": "Beyaz kaleyi almaz, fili çıkarır.",
        "30": "At c3 piyonunu alır ve d1’deki kaleye saldırır.",
        "31": "Fil c5’e, b6’daki siyah vezire saldırır.",
        "32": "e hattından kaleyle şah!",
        "33": "Şah f1’e. Artık Beyaz hiç rok yapamaz.",
        "34": "Fil e6’ya! Oyunun en ünlü hamlesi: Siyah vezirini bedavaya aldırır. Karşılığında taşları birer birer geri kazanma planı vardır.",
        "35": "Beyaz siyah veziri alır.",
        "36": "Fil c4’te şah. Siyahın karşı saldırısı başlar.",
        "38": "At e2’den şah çeker.",
        "40": "Şah f1’e dönünce at oynar ve c4’teki filin şahını açar. At yolda d4 piyonunu da kapar.",
        "44": "At c3’e döner; yine açarak şah, şimdi d1’deki kaleye saldırır. Taş toplarken üst üste şah çekmeye “değirmen” denir.",
        "46": "Siyah fili geri alır. c3’teki at hâlâ d1’deki kaleye saldırıyor.",
        "50": "At d1’deki kaleyi alır. Artık Siyah verdiği vezirden fazlasını geri kazandı ve açıkça önde.",
        "52": "Kale a2 piyonunu da alır.",
        "56": "Siyah kaleleri değişir. Taş azaldıkça fazlası olan taraf daha avantajlı.",
        "57": "Beyaz vezir şah çeker.",
        "58": "Siyah araya fili koyar.",
        "64": "b5. Siyah piyon yürümeye başlar.",
        "68": "Şah g7’ye gider ve f8’deki fili serbest bırakır.",
        "70": "Artık siyah taşlar beyaz şahı avlıyor. Fille şah.",
        "72": "At g3’te şah.",
        "74": "Öbür fille şah.",
        "76": "Fil b3’te şah.",
        "78": "At e2’de şah.",
        "80": "At c3’te şah. Şah oradan oraya kovalanıyor.",
        "82": "Kale c2’ye: mat! Kale, iki fil ve at birlikte çalışır. On üç yaşında bir çocuk, birçok taşın nasıl tek bir takım gibi oynayabileceğini gösterdi."
      } },
    "oshiro1849": { "t": "Shūsaku’nun İlk Şato Oyunu", "w": "Hon’inbō Shūsaku", "b": "Yasui Sanchi IX", "ev": "Şato oyunu (Edo Şatosu’nda yılda bir oynanan oyun)", "d": "1849", "pl": "Japonya (Edo)", "lead": "Şato oyunları, resmî go okullarının oyuncularının şogunun şatosunda oynadığı yıllık gösteriydi. 20 yaşındaki Shūsaku o yıl ilk kez katıldı ve Siyahla 11 puan farkla kazandı; 19 şato oyununda 19 galibiyetlik kusursuz serisi böyle başladı.",
      c: {
        "0": "1849. Bir yıl önce Shūsaku, Hon’inbō okulunun varisi ilan edilmişti; şimdi ilk şato oyununu oynuyor. Bu oyunların çoğunlukla önceden başka yerde oynanıp şatoda yalnızca yeniden dizildiği söylenir.",
        "1": "Siyah 1, sağ üstte 3-4 noktası (R16). Shūsaku her zamanki gibi sakin bir 3-4 ile başlıyor.",
        "4": "Beyaz 4 (C15) sol üstteki Siyah D17’ye yaklaşıyor. Orada erkenden bir mücadele başlıyor.",
        "5": "Siyah 5 (C11) yaklaşan Beyaz taşı alttan kıskaca alıyor; Beyaz solda kolayca yerleşemesin.",
        "12": "Beyaz 12 (C17). Sol üst köşe Beyazın, Siyah ise dışa bakan taşlar aldı: iki taraf için adil bir takas.",
        "13": "Siyah 13 (J17) dıştaki taşlardan yararlanıp üst kenarda açılıyor.",
        "15": "Siyah 15 (C5) son boş köşeyi, sol altı alıyor. Dört köşe de doldu.",
        "16": "Beyaz 16 (E4) hemen o Siyah taşa yaklaşıyor; sol altta da mücadele başlıyor.",
        "19": "Siyah 19 (D2) sol alt köşeyi sağlamca güvenceye alıyor; Shūsaku’ya özgü sağlam bir seçim.",
        "23": "Siyah 23 (E5) Beyaz taşların arasından çıkıp sol alttaki grubunu güçlendiriyor.",
        "29": "Siyah 29 (F11) soldaki taşlarını güçlendirirken merkeze de bakıyor.",
        "30": "Beyaz 30 (H4) alt kenarda açılıp soldaki Siyah gruba baskı yaparken kendi alanını kuruyor.",
        "31": "Siyah 31 (O3) sağ alttaki Beyaz köşeye yaklaşıyor.",
        "33": "Siyah 33 (R3) köşedeki Beyaz taşa yapışıyor. Bundan sonra Siyah dışta kuruyor, Beyaz kenarda üçüncü sıra boyunca ilerliyor.",
        "43": "Siyah 43 (Q8). Sağ kenar boyunca kalın bir Siyah duvar uzanıyor. Beyaz köşe ve kenar bölgesini, Siyah dış gücü aldı.",
        "44": "Beyaz 44 (L17) üst kenarda Siyah taşların arasına girip Siyah alanın fazla büyümesini önlüyor.",
        "50": "Beyaz 50 (R18) sağ üstteki Siyah köşenin altına girip köşe bölgesini hedefliyor.",
        "51": "Siyah 51 (P13). Duvarı arkasına alan Siyah, sağ kenardan merkeze geniş bir alan çiziyor.",
        "52": "Beyaz 52 (D10) sol kenardaki Siyah taşların arasına giriyor. Orada taşlar birbirine giriyor.",
        "63": "Siyah 63 (B10) sol kenarda oynayarak Beyaz taşların orada üs kurmasını engelliyor.",
        "65": "Siyah 65 (G3) alttaki Beyaz alana da girip Beyaz bölgeyi küçültüyor.",
        "73": "Siyah 73 (K17) üstteki taşlarını sağlamlaştırıp 44. hamledeki Beyaz taşa baskı yapıyor.",
        "76": "Beyaz 76 (P11) Siyahın sağ kenar alanına atlıyor. Bu taşın yaşayıp ölmesi skoru çok değiştirecek.",
        "77": "Siyah 77 (Q11) duvar tarafından karşılık verip Beyazı merkeze itiyor; saldıran sakin bir savunma, tam Shūsaku tarzı.",
        "80": "Beyaz 80 (N10) Siyahın takibinden kurtulmak için merkeze kaçıyor.",
        "85": "Siyah 85 (N12) saldırmayı sürdürürken üstte ve sağda bölgesini genişletiyor. Saldırarak kazanç: ustaca bir oyun.",
        "91": "Siyah 91 (J7) alttaki Beyaz taşların üstüne oynayıp Beyaz alanı merkezden de kapatıyor.",
        "100": "Beyaz 100 (S17) sağ üst köşede Siyah bölgeyi azaltmak için bir girişimde bulunuyor.",
        "119": "Siyah 119 (R17) sağ üst köşeyi sıkıca savunup Beyazın girişimini püskürtüyor.",
        "122": "Beyaz 122 (G6) sol alttaki Siyah taşların dışından dolaşıp onları merkezdeki Siyahtan kesmeye çalışıyor.",
        "131": "Siyah 131 (M5) alt kenarın ortasında Beyaz alana bir kama sokuyor.",
        "140": "Beyaz 140 (B4) sol alttaki Siyah köşede bir şey deniyor. Sol kenarda yakın bir taş alma mücadelesi başlıyor.",
        "156": "Beyaz 156 (A8) iki Siyah taş alıyor. Sol kenardaki mücadele iki tarafın da biraz kazanmasıyla duruluyor.",
        "158": "Beyaz 158 (L10). Beyazın merkezde hâlâ taşları var ve Siyahın merkez bölgesini azaltmaya çalışıyor.",
        "162": "Beyaz 162 (O12) bir Siyah taş alıyor. Yine de sağdaki Siyah alan büyük kalıyor.",
        "172": "Beyaz 172 (K18). Buradan sonrası bitiş; önce üst kenardaki sınır belirleniyor.",
        "186": "Beyaz 186 (T16) sağ üst kenarda Siyah bölgeyi kırpıyor. Bitişte iki taraf da önce en büyük noktaları oynuyor.",
        "205": "Siyah 205 (Q18) üst kenarın sağ kısmını kapatıp oradaki bölgesini kesinleştiriyor.",
        "223": "Siyah 223 (P10), sağdaki Siyah bölge ile merkeze kaçan Beyaz taşlar arasındaki sınırı belirliyor.",
        "233": "Siyah 233 (Q9) bir Beyaz taş alıyor. Sağdaki Siyah bölge artık neredeyse tamamen güvende.",
        "239": "Siyah 239 (A6) bir taş alıyor ve sol kenarda bir ko çıkıyor. Puan puan mücadele sonuna kadar sürüyor.",
        "260": "Beyaz 260 (T6) bir taş alıyor ve sağ alt kenarda bir ko daha oluşuyor. Siyah 263 (T5) ile geri alıyor.",
        "267": "Oyun 267 hamlede bitiyor: Siyah 11 puanla kazanıyor. Macera yok; Shūsaku saldırarak bölgesini doğal biçimde büyüttü, tam ona yakışan bir zafer. Şato oyunlarındaki 19 ardışık galibiyetinin ilkiydi."
      } },
    "shilin": { "t": "Shilin Guangji oyunu", "w": "Kırmızı (adı bilinmiyor)", "b": "Siyah (adı bilinmiyor)", "ev": "Gündelik ansiklopedi Shilin Guangji: “ilk hamleyi verip aynı taraf toplarla kazanılan oyun”", "d": "13. yüzyıl", "pl": "Çin (Song–Yuan)", "lead": "Bu kayıt, Chen Yuanjing’in Song hanedanının sonu ile Yuan’ın başı arasında derlediği gündelik ansiklopedi Shilin Guangji’den gelir. Günümüze kalan en eski tam xiangqi oyunlarından biri olduğu söylenir. Güçlü tarafın ilk hamleyi diğerine bıraktığı örnek bir oyundur ve yalnızca dokuz hamlede siyah at kırmızı arabayı yakalar.",
      c: {
        "0": "Bu kayıt 700 yıldan eski; Song ile Yuan hanedanları arasındaki döneme ait. Shilin Guangji ansiklopedisinin oyunlar bölümünde yer alır ve elimizdeki en eski tam xiangqi oyunlarından biri olduğu söylenir. Oyuncuların adları bilinmiyor. Başlık, güçlü oyuncunun ilk hamleyi zayıf olana “verdiğini” söyler; yani bu, önce oynayan Kırmızı’nın nasıl kaybettiğini gösteren bir derstir. Kırmızı altta ve ilk o oynar.",
        "1": "Kırmızı sağdaki topu orta hatta getirir. Buna Orta Top denir; doğrudan siyah generale nişan alır ve bugün de en güçlü açılışlardan biridir. 700 yıl önce de oynandığını görüyoruz.",
        "2": "Siyah da bir topu ortaya getirir ve iki top karşı karşıya gelir. İki taraf da aynı taraftaki topu oynarsa buna “aynı yönde toplar” denir. Top topa düello yüzyıllardır sevilir.",
        "3": "Kırmızı ortadaki askeri korumak için bir at çıkarır. Bu asker siyah topun hedefinde ve bir koruyucuya ihtiyacı var. At aynı zamanda ileri çıkmaya da hazırlanıyor.",
        "4": "Siyah da aynısını yapar ve orta askerini atla korur. İki taraf da önce sağlam bir zemin kuruyor.",
        "5": "Kırmızı sağ arabayı bir adım yana, açık bir hatta kaydırır. Araba tahtadaki en güçlü taştır, erken çalıştırmak iyidir.",
        "6": "Siyah diğer atı da çıkarır ve arabaları şimdilik evde bırakır. Plan önce taşları ileri getirmek. Ama geç çıkan bir arabayı sonra saldırıda kullanmak zor olabilir.",
        "7": "Kırmızı araba bir anda nehri geçip siyahın kampına girer. Siyah taşları tehdit etmek istiyor ama diğer kırmızı taşlar hâlâ evde; bu saldırı biraz aceleci. Önce soldaki atı ya da arabayı çıkarmak da mümkündü.",
        "8": "Siyah 3. hattaki askeri bir adım ilerletir. Böylece ata yol açar, at sonra ileri sıçrayabilir. Siyah neredeyse kırmızı arabayı gelmeye davet ediyor.",
        "9": "Kırmızı araba bir askeri alır ve şimdi arkasındaki siyah atı hedefler. Bir taş kazanıp bir başkasını tehdit etmek harika görünür. Ama araba çok ileri gitmiş, yanında hiç arkadaşı yok. Düşman kampında yalnız kalan bir araba kolayca kovalanır.",
        "10": "Siyah at ileri sıçrar. Hem arabadan kaçar hem de kırmızının kampına yaklaşır: tek hamlede iki iş. Bu at oyunun yıldızı olacak.",
        "11": "Kırmızı arabayı bir adım geri çeker ve atı yandan tehdit eder. Araba uzaktan da alabildiği için at dinlenemez. Yine de bu hamle diğer kırmızı taşları geliştirmiyor.",
        "12": "Siyah at daha da ilerler ve nehri geçip kırmızının kampına girer. Arabadan her kaçışında kırmızı generale biraz daha yaklaşır.",
        "13": "Kırmızı kendi atına yol açmak için bir askeri ilerletir. Fikir, atı çıkarıp siyah atla değiştirmek. Ama bu, Siyah’a daha da ilerlemek için zaman verir.",
        "14": "Siyah bir fili kaldırır ve kırmızı arabaya saldırır. Bir savunma taşıyla düşman arabasını kovalamak çok verimlidir. Kırmızı arabayı yine oynamak zorunda ve Siyah bir tempo daha kazanır.",
        "15": "Kırmızı araba yana kayar ve bir asker daha alır. Kırmızı artık iki asker önde ama kaybettiren hamle bu. Araba generalinden çok uzakta ve savunmaya geri dönemez. Kırmızı’nın atına karşı önlem alması, örneğin arabayı eve getirmesi gerekiyordu.",
        "16": "Siyah at daha derine girer ve kırmızı arabaya saldırır. Dahası var: bir kez daha sıçrarsa kırmızı generale şah çekecek ve aynı anda köşedeki arabaya saldıracak. Tek bir at aynı anda iki tehdit yarattı.",
        "17": "Kırmızı atı arabayla kovalar. Ama artık durdurulamaz. Kırmızı generalin çevresinde yardım edecek kimse kalmadı.",
        "18": "At şahla içeri sıçrar! Köşedeki kırmızı arabaya da saldırır; general kaçınca araba kaybedilir. Yalnızca dokuz hamle, ama oyun tek başına öne fırlayan bir arabaya ne olduğunu ve taşların neden birlikte savaşması gerektiğini öğretir. 700 yıl önceki oyuncular da aynı tahtada aynı şeyleri düşünüyordu."
      } },
    "qima13": { "t": "On üç hamlede at fedası (Juzhongmi)", "w": "Kırmızı (adı bilinmiyor)", "b": "Siyah (adı bilinmiyor)", "ev": "Juzhongmi, 1. cilt, 1. oyun", "d": "1632 (yayın)", "pl": "Çin (Ming)", "lead": "Bu, Ming hanedanından Zhu Jinzhen’in 1632’de yayımladığı xiangqi kitabı Juzhongmi’nin (“Mandalinadaki Sır”) ilk oyunudur. Kırmızı, Siyah’ın bir atı bedavaya almasına izin verir, bu sırada saldırıya geçer ve on üç hamlede mat eder. “On üç hamlede at fedası” adıyla neredeyse 400 yıl sonra bile seviliyor.",
      c: {
        "0": "Bu, Ming hanedanının sonlarına doğru, 1632’de basılan Juzhongmi kitabının 1. oyunudur. Daha sonraki Erik Çiçeği El Kitabı ile birlikte xiangqi’nin iki büyük klasiğinden biri sayılır. Gerçek bir maç değil, bir planı öğretmek için yazılmış örnek bir oyundur; bu yüzden oyuncu adları yoktur. Kırmızı altta ve önce oynar; her şey yalnızca on üç hamlede biter.",
        "1": "Kırmızı sağdaki topu ortaya getirir. Bu, siyah generale doğrudan bakan Orta Top’tur. Juzhongmi, bu açılışla nasıl saldırılacağını incelemesiyle ünlüdür.",
        "2": "Siyah da aynı taraftaki topu ortaya getirir. Bunlar, karşı karşıya çarpışan “aynı yönde toplar”dır. İki taraf da diğerinin orta askerini hedefliyor.",
        "3": "Kırmızı orta askeri korumak için bir at çıkarır. Siyah topun hedeflediği askeri korur ve at da çalışmaya başlar.",
        "4": "Siyah da orta askerini bir atla korur. Buraya kadar iki tarafın dizilişi aynı.",
        "5": "Kırmızı sağ arabayı yalnızca bir adım ileri sürer. Böylece sonraki hamlede yana koşabilir. Böyle yana giden arabaya “yatay araba” denir; her iki kanada da hızla geçebilir.",
        "6": "Siyah arabasını bir adım yana alır, böylece tahtada dümdüz ilerleyebilir. Bu bir “düz araba”dır. Yatay arabaya karşı düz araba: arabayı kullanmanın iki farklı yolu karşı karşıya.",
        "7": "Kırmızı yatay araba soldaki bir hatta geçer. Bu hat siyah danışmanın hemen yanından geçer; savunmanın zayıf olduğu yerdir. Kırmızı buradan içeri dalmaya hazırlanıyor.",
        "8": "Siyahın düz arabası nehri geçip kırmızının kampına derinden girer. Siyah kendi saldırısıyla karşılık vermek istiyor. Ama bu, savunmadan önce saldırmaya acele eden bir hamle.",
        "9": "Kırmızı araba siyahın kampının derinliklerine dalar. Filin geçmesi gereken “göz” noktasına oturur, böylece siyah fil hareket edemez. Danışmanın hemen yanında, artık generale çok yakın.",
        "10": "Siyah diğer atı kenara çıkarır. Amaçlardan biri, kırmızı arabanın yandan sızmasını engellemek.",
        "11": "İşte at fedası! Kırmızı diğer arabayı bir adım kaldırır. Bu, sol köşedeki atı korumasız bırakır ve siyah top onu bedavaya alabilir. Ama bir at karşılığında Kırmızı, iki arabayı da hızla saldırıya sokacak zamanı kazanır.",
        "12": "Siyah top kırmızı atı alır. Siyah bir taş kazanmış gibi görünür. Ama bu top artık evinden uzakta ve savunmaya yardım edemez. Burada almak yerine bir danışmanı kaldırıp savunmayı güçlendirmenin daha iyi olduğu söylenir.",
        "13": "Kırmızı top ilerler. Ortadaki siyah topu atlanacak bir “perde” olarak kullanıp arkadaki siyah atı hedefler. Top, tam olarak bir taşın üzerinden atlayarak alan ilginç bir taştır.",
        "14": "Siyah kaçmak için atı geri çeker. Ama bu at orta askeri koruyan önemli taştı. Kaçınca merkezde bir delik açılır. Siyahın başka savunmaları da vardı ama bu en kötü seçimdi.",
        "15": "Kırmızı top orta askeri alır — şah! Siyah at gidince merkez ardına kadar açıktı. Buradan itibaren kırmızının saldırısı hızla ilerler.",
        "16": "Siyah generalin önünü kapatmak için bir danışmanı kaldırır. Şahı durdurmanın tek iyi yolu bu.",
        "17": "İkinci kırmızı araba da aynı hatta gelir. Bir hatta art arda dizilmiş iki araba son derece güçlüdür. Plan, siyahın kampının en derinine girmek.",
        "18": "Siyah general yana kaçar. Yoksa aynı hattaki iki kırmızı araba ona doğrudan bakacaktı.",
        "19": "Öndeki kırmızı araba siyah danışmanı alır — şah! Diğer danışman onu hemen alacak ama bu da planın parçası. Kırmızı, siyah generalin muhafızlarını dağıtmak için bir arabayı feda eder. Ne cesur bir hamle!",
        "20": "Siyah arabayı danışmanla alır. Taş sayısında Siyah çok önde. Ama generalin evi daha da boşaldı.",
        "21": "Son kırmızı araba generalin hattına geçer — yine şah. Siyah generali koruyacak neredeyse hiç taş kalmadı.",
        "22": "Siyah şahı kapatmak için generalin önüne bir top koyar. Araya böyle bir taş koymaya araya girmek denir.",
        "23": "Kırmızı araba o topu alır — yine şah. Araba siyah taşları almaya devam ederken generali köşeye sıkıştırır.",
        "24": "Siyah general yalnızca ortaya dönebilir. Diğer bütün noktalar kırmızı taşların kontrolünde.",
        "25": "Sonunda kırmızı top ortaya gelir; bir hatta iki top — şah. Öndeki top perde olur, arkadaki top generali vurur: bu bir “çift top” matıdır. Siyah generalin gidecek yeri yok ve Kırmızı kazanır. Yalnızca bir at vererek Kırmızı on üç hamlede kazandı. 400 yıldır bu oyun, zamanın ve taşların etkinliğinin taş sayısından daha önemli olabileceğini öğretiyor."
      } }
  },
  "id": {
    ui: {"lead":"Partai-partai hebat, langkah demi langkah. Ikuti partai terkenal di papan sambil mendengarkan penjelasan Musowl untuk setiap langkah.","all":"Semua","k_chess":"Catur","k_shogi":"Shogi","k_go":"Go","k_xiangqi":"Xiangqi","side_r":"Merah","res_r":"Merah menang","back":"Kembali ke Partai Hebat","start":"Awal","prev":"Mundur satu langkah","next":"Maju satu langkah","end":"Akhir","play":"Putar otomatis","pause":"Jeda","moves":"Langkah","move":"Langkah ke-{n}","startpos":"Posisi awal","nextnote":"Penjelasan berikutnya (langkah ke-{n})","quiet":"Tidak ada penjelasan untuk langkah ini.","guide":"Musowl","keys":"← → untuk maju atau mundur","result":"Hasil","r_event":"Partai","r_date":"Tahun","r_place":"Tempat","side_w":"Putih","side_b":"Hitam","side_s":"Sente","side_g":"Gote","side_B":"Hitam","side_W":"Putih","res_w":"Putih menang","res_b":"Hitam menang","res_d":"Remis","res_s":"Sente menang","res_g":"Gote menang","credit":"Langkah-langkahnya adalah catatan umum dari setiap partai. Penjelasannya ditulis oleh Musowl dari museum."},
    "opera": { "t": "Partai Opera", "w": "Paul Morphy", "b": "Adipati Karl II dari Brunswick dan Count Isouard", "ev": "Dimainkan di sebuah balkon pribadi Gedung Opera Paris (kedua sekutu bermain sambil berunding)", "d": "1858", "pl": "Prancis (Paris)", "lead": "Juara muda dari Amerika melawan dua bangsawan, di tengah pertunjukan opera: tujuh belas langkah. Keluarkan buah catur dengan cepat, korbankan tanpa ragu, dan akhiri hanya dengan sedikit buah. Tidak ada partai yang lebih sering muncul di buku-buku catur.",
      c: {
        "0": "Paris, 1858. Paul Morphy, orang Amerika berusia dua puluh satu tahun, sedang mengalahkan pemain-pemain kuat Eropa satu per satu. Malam itu, di balkon gedung opera, Adipati Brunswick dan Count Isouard bersama-sama memegang Hitam dan menantangnya sambil berunding setiap langkah. Konon Morphy ingin cepat selesai supaya bisa menonton panggung. Tujuh belas langkah ini penuh dasar-dasar: keluarkan buah dengan cepat dan amankan raja.",
        "1": "Putih memajukan pion raja dua petak. Pion ini mengawasi d5 dan e5 di tengah serta membuka jalan gajah dan menteri.",
        "2": "Hitam juga bermain e5. Pion-pion berhadapan di tengah, dan pion Putih tidak bisa maju lagi.",
        "3": "Kuda ke f3 dan menyerang pion e5. Langkah bagus: mengembangkan buah sekaligus membuat lawan berpikir untuk bertahan.",
        "4": "Hitam menjaga e5 dengan d6. Ini disebut Pertahanan Philidor. Kokoh, tetapi jalan gajah f8 jadi agak sempit.",
        "5": "Putih bermain d4: satu pion lagi ke tengah, menghadapi e5. Hitam harus memilih antara memakan atau menjaga.",
        "6": "Gajah Hitam ke g4. Ia menekan kuda f3, yang segaris dengan menteri Putih di d1. Jika kuda bergerak, menteri hilang, jadi kuda tidak bisa mengejar e5.",
        "7": "Putih memakan di e5 dengan pion. Jika Hitam langsung memakan kembali dengan pion d6, Putih akan menukar menteri lalu kuda menyambar pion e5. Karena itu Hitam ingin menyingkirkan kuda f3 lebih dulu.",
        "8": "Hitam memakan kuda dengan gajah. Kini e5 bisa direbut kembali dengan aman. Tetapi menukar gajah yang baru keluar dengan kuda membuat perkembangan Hitam tertinggal.",
        "9": "Putih memakan kembali dengan menteri, yang sudah bekerja dekat tengah, sementara Hitam hampir belum mengeluarkan buah.",
        "10": "Hitam memakan kembali dengan pion, materi seimbang. Tetapi dalam buah yang sudah keluar, Putih unggul.",
        "11": "Gajah ke c4. Bersama menteri f3, ia membidik f7. Hanya raja yang menjaga f7, jadi petak itu lemah: memakannya berarti skakmat.",
        "12": "Hitam menaruh kuda di f6 dan menutup lajur f. Tanpa ini, menteri memakan f7 adalah skakmat. Bertahan sambil mengembangkan buah adalah jawaban yang benar.",
        "13": "Menteri berbelok ke b3 dan menyerang f7 dan b7 sekaligus. Langkah dengan dua ancaman itu kuat, karena lawan tidak bisa menjaga keduanya.",
        "14": "Hitam memindahkan menteri ke e7 untuk menjaga f7 dan merelakan b7. Tetapi kini menteri menghalangi gajah f8.",
        "15": "Morphy tidak memakan pion b7; ia mengeluarkan kuda. Memakan akan membuat menteri pergi jauh. Memilih perkembangan cepat daripada satu pion sangat khas Morphy.",
        "16": "Hitam bermain c6: menguasai d5 dan b5 serta membuka jalan menteri ke b6.",
        "17": "Gajah ke g5 menyematkan kuda f6. Jika kuda bergerak, menteri e7 di belakangnya bisa dimakan. Buah Hitam makin sulit bergerak.",
        "18": "Hitam bermain b5 untuk mengusir gajah c4. Ia mendapat ruang di sisi menteri, tetapi juga membuka celah bagi buah Putih untuk masuk.",
        "19": "Kuda dikorbankan untuk memakan di b5! Bukannya memundurkan gajah, Morphy terus menyerang. Dengan raja Hitam masih di tengah, ini sangat berbahaya bagi Hitam.",
        "20": "Hitam memakan kuda dan unggul satu kuda. Tetapi rajanya masih di e8, dan buah Putih terus berdatangan.",
        "21": "Gajah ke b5, skak! Raja Hitam masih terjebak di tengah. Putih punya dua pion untuk kuda dan langsung menuju raja.",
        "22": "Hitam menutup dengan kuda di d7. Tetapi kuda ini tersemat: jika bergerak, raja Hitam terkena skak. Kini Putih akan membidik d7.",
        "23": "Putih melakukan rokade panjang. Raja aman, dan sekaligus benteng tiba di d1 untuk membidik d7. Satu langkah untuk bertahan dan menyerang: luar biasa.",
        "24": "Hitam menaruh benteng di d8 untuk menjaga d7. Hitam masih belum bisa rokade, dan benteng h8 serta gajah f8 tidak berbuat apa-apa.",
        "25": "Benteng dikorbankan untuk memakan di d7! Putih memberi satu benteng untuk menyingkirkan satu pembela Hitam.",
        "26": "Hitam memakan kembali dengan benteng. Kini benteng di d7 juga tersemat: jika bergerak, gajah b5 memberi skak kepada raja Hitam.",
        "27": "Benteng lainnya datang ke d1 dan menyerang d7 lagi. Kini lebih banyak buah Putih yang menyerang d7 daripada buah Hitam yang menjaganya.",
        "28": "Menteri Hitam ke e6, menawarkan tukar menteri untuk mengusir menteri b3 dan ingin membantu d7. Tetapi sudah terlambat.",
        "29": "Gajah memakan di d7 sambil skak. Putih menyingkirkan pembela Hitam satu per satu.",
        "30": "Hitam memakan kembali dengan kuda. Karena kuda meninggalkan f6, diagonal dari gajah g5 sampai d8 terbuka. Diagonal ini akan menentukan di akhir.",
        "31": "Menteri dikorbankan di b8 sambil skak! Inilah langkah paling terkenal di partai ini. Hitam harus memakan dengan kuda, dan saat kuda meninggalkan d7, lajur d terbuka.",
        "32": "Hitam memakan dengan kuda. Kini tidak ada buah Hitam yang menjaga d8.",
        "33": "Benteng ke d8, skakmat! Gajah g5 mendukung d8, dan raja Hitam terkurung oleh buahnya sendiri. Putih memberi menteri, benteng, dan gajah, lalu menutup hanya dengan satu benteng dan satu gajah. Berkembang cepat, amankan raja, dan serang selagi raja lawan masih di tengah: partai terkenal ini memuat semua gagasan penting itu."
      } },
    "reti1910": { "t": "Skakmat Réti", "w": "Richard Réti", "b": "Savielly Tartakower", "ev": "Partai santai (bukan turnamen)", "d": "1910", "pl": "Austria (Wina)", "lead": "Dua calon grandmaster, partai santai di Wina, sebelas langkah. Putih mengorbankan menteri dan menutup dengan skak ganda: dua buah memberi skak sekaligus. Pola skakmat ini dinamai menurut nama Putih: Skakmat Réti.",
      c: {
        "0": "Wina, 1910. Putih dimainkan Richard Réti yang berusia dua puluh tahun; Hitam oleh Savielly Tartakower. Keduanya kelak menjadi pemain terbaik dunia dan dikenal membawa gagasan baru ke dunia catur. Ini bukan partai turnamen, melainkan partai santai dengan taruhan kecil. Singkat, tetapi jelas menunjukkan mengapa raja harus cepat diamankan.",
        "1": "Putih memajukan pion raja dua petak. Menguasai tengah memudahkan buah di belakang untuk keluar. Jalan gajah dan menteri pun terbuka.",
        "2": "Hitam bermain c6. Bukannya langsung ke tengah, Hitam bersiap untuk d5 dan menyerang pion e4. Pembukaan kokoh ini disebut Pertahanan Caro-Kann.",
        "3": "Putih juga menaruh pion lain di d4. Dua pion berdampingan di tengah: Putih punya banyak ruang. Hitam akan berusaha memecahnya.",
        "4": "Sesuai rencana, d5. Pion menantang e4: \"Aku bisa memakanmu.\" Putih harus memilih: menjaga, memajukan, atau menukar.",
        "5": "Putih mengeluarkan kuda untuk menjaga e4. Mengembangkan buah sekaligus bertahan, tanpa membuang waktu.",
        "6": "Hitam memakan pion e4. Dengan menukar pion tengah, pusat Putih menjadi lebih kecil.",
        "7": "Putih memakan kembali dengan kuda, yang kini berdiri di tengah papan. Kuda di tengah menjangkau banyak petak dan sangat kuat.",
        "8": "Hitam mengeluarkan kuda berhadapan dengan kuda e4. Di sini biasanya dimainkan gajah ke f5, tetapi Hitam mengajak tukar kuda.",
        "9": "Menteri keluar lebih awal ke d3 untuk menjaga kuda e4. Biasanya menteri tidak dikeluarkan secepat ini, tetapi Putih punya rencana. Ingat, menteri ini berdiri di lajur d, di depan raja Hitam.",
        "10": "Hitam bermain e5 dan menawarkan pion untuk membuka jalan bagi gajah dan menteri. Langkah aktif yang memulai pertempuran di tengah.",
        "11": "Putih memakan pion e5. Hadiah diterima, tetapi menteri Hitam jadi lebih leluasa.",
        "12": "Skak! Menteri Hitam di a5 membidik raja e1 secara diagonal. Sekaligus ia berniat merebut kembali pion e5: dua tugas dalam satu langkah. Putih harus menutup.",
        "13": "Putih menutup skak dengan gajah di d2. Menteri bisa memakan gajah, tetapi menteri Putih menjaganya dengan baik.",
        "14": "Hitam merebut kembali pion, materi kembali seimbang. Dan menteri ini melihat lurus di lajur e ke kuda e4 dan raja di belakangnya. Jika kuda bergerak, raja terkena skak, jadi kuda terkunci. Tampaknya Hitam akan segera memenanginya.",
        "15": "Putih melakukan rokade panjang. Raja meninggalkan lajur e, dan kuda bebas lagi. Sekaligus sebuah benteng tiba di d1: benteng d1, menteri d3, dan petak d8 di samping raja Hitam berada di satu garis. Inilah jebakan Putih.",
        "16": "Hitam memakan kuda e4 dan tampaknya menang satu buah. Tetapi raja Hitam masih di e8 dan belum rokade. Buah Putih berbaris di lajur d, sementara raja Hitam tanpa pelindung. Langkah yang membuat kalah ini adalah titik baliknya.",
        "17": "Menteri ke d8, skak! Putih memberikan buah terkuatnya begitu saja. Satu-satunya buah Hitam yang bisa memakannya adalah raja. Dengan membiarkannya dimakan, Putih menarik raja ke petak berbahaya d8.",
        "18": "Hitam harus memakan dengan raja; tidak ada cara lain menghindari skak. Raja berada di d8, dengan benteng d1 menunggu di belakang.",
        "19": "Gajah pindah dari d2 ke g5 sambil skak, dan sekaligus membuka jalan benteng d1, yang juga memberi skak di lajur d. Dua buah memberi skak bersamaan: skak ganda. Tidak bisa dihentikan dengan memakan satu buah atau menutup; raja harus lari.",
        "20": "Raja lari ke c7. Jika ke e8, benteng datang ke d8 dan skakmat. Ke mana pun raja pergi, Putih sudah menyiapkan pukulan terakhir.",
        "21": "Gajah ke d8: skakmat secara diagonal terhadap raja di c7! Gajah dijaga benteng d1, jadi raja tidak bisa memakannya. Petak seperti b8, c8, b7, dan c6 terisi buah Hitam sendiri, dan benteng mengawasi d6 dan d7. Hanya dalam sebelas langkah, Putih mengorbankan menteri dan menang dengan dua buah kecil. Partai ini mengajarkan betapa berbahayanya mengejar materi sebelum rokade. Beberapa catatan menyebut Hitam menyerah satu langkah sebelumnya."
      } },
    "immortal": { "t": "Partai Abadi", "w": "Adolf Anderssen", "b": "Lionel Kieseritzky", "ev": "Partai tidak resmi saat jeda turnamen London 1851", "d": "1851", "pl": "Britania Raya (London)", "lead": "London, saat turnamen catur internasional pertama: sebuah partai yang dimainkan di waktu jeda. Putih mengorbankan gajah, kedua benteng, lalu akhirnya menteri, dan men-skakmat dengan tiga buah kecil yang tersisa. Konon Hitam menyerah sebelum akhir, dan beberapa langkah terakhir adalah penyelesaian yang ditunjukkan Putih.",
      c: {
        "0": "London, 1851. Saat jeda turnamen, Anderssen dari Jerman (Putih) dan Kieseritzky, bintang dari Paris (Hitam), bermain santai.",
        "1": "Putih memajukan pion raja dua petak.",
        "2": "Hitam melakukan hal yang sama.",
        "3": "f4! Putih menawarkan pion: inilah Gambit Raja. Tujuannya menarik pion Hitam di e5 keluar dari tengah.",
        "4": "Hitam mengambil pion itu.",
        "5": "Gajah keluar dan membidik f7, di samping raja Hitam.",
        "6": "Skak! Tanpa pion f Putih, diagonal dari h4 ke e1 terbuka.",
        "7": "Raja menyingkir. Sekarang Putih tidak bisa rokade lagi.",
        "8": "Hitam juga menawarkan pion, untuk memancing gajah ke b5.",
        "9": "Putih memakannya.",
        "10": "Kuda keluar dan menyerang pion e4.",
        "11": "Putih mengeluarkan kuda dan mengusir menteri dari h4.",
        "12": "Menteri mundur ke h6.",
        "13": "d3 menjaga e4 dan membuka jalan gajah c1.",
        "14": "Kuda ke h5. Rencananya melompat ke g3 sambil skak dan menyerang benteng h1.",
        "15": "Kuda Putih ke h4, siap melompat ke f5 untuk mengganggu menteri Hitam.",
        "16": "Menteri Hitam ke g5 dan menyerang kuda h4.",
        "17": "Kuda ke f5, petak bagus yang dijaga pion e4. Ia juga membidik pion g7.",
        "18": "c6 mencoba mengusir gajah di b5.",
        "19": "Putih tidak menyelamatkan gajah: g4 mengejar kuda di h5.",
        "20": "Kuda kembali ke f6.",
        "21": "Benteng ke g1, menjaga pion g4. Putih membiarkan gajah b5 dimakan. Berani sekali!",
        "22": "Hitam memakan gajah dan unggul satu buah.",
        "23": "Pion h mulai mengejar menteri Hitam.",
        "24": "Menteri ke g6.",
        "25": "h5 mengejar menteri lagi.",
        "26": "Menteri hanya bisa kembali ke g5. Petaknya makin sedikit.",
        "27": "Menteri Putih ke f3. Jika gajah lalu memakan di f4, menteri Hitam bisa terkurung.",
        "28": "Hitam memulangkan kuda ke g8 agar menteri bisa kabur ke f6.",
        "29": "Gajah memakan pion f4 dan menyerang menteri.",
        "30": "Menteri kabur ke f6.",
        "31": "Kuda keluar, berniat melompat ke d5 dan menyerang menteri.",
        "32": "Gajah keluar dan membidik benteng g1.",
        "33": "Kuda ke d5, menyerang menteri di f6 dan petak c7. Putih tidak peduli kehilangan benteng g1.",
        "34": "Menteri memakan pion b2 dan menyerang benteng a1.",
        "35": "Gajah ke d6! Putih membiarkan kedua benteng dimakan. Sebagai gantinya, buah-buahnya membuat jaring di sekitar raja Hitam.",
        "36": "Hitam memakan benteng g1.",
        "37": "e5! Pion ini menutup diagonal menteri b2 ke g7. Menteri Hitam tidak bisa lagi kembali membantu rajanya.",
        "38": "Hitam juga memakan benteng lainnya sambil skak.",
        "39": "Raja ke e2. Putih hanya punya menteri, dua kuda, dan satu gajah.",
        "40": "Kuda ke a6 untuk menjaga c7. Konon Hitam menyerah sekitar sini; sisanya penyelesaian yang ditunjukkan Putih.",
        "41": "Kuda memakan di g7 sambil skak.",
        "42": "Raja lari ke d8.",
        "43": "Menteri dikorbankan di f6 sambil skak! Buah besar terakhir pun pergi.",
        "44": "Hitam harus memakan dengan kuda.",
        "45": "Gajah ke e7, skakmat! Kuda d5 menguasai e7 dan c7, kuda g7 menguasai e8. Putih menang hanya dengan satu gajah dan dua kuda."
      } },
    "mimiaka": { "t": "Permainan Telinga Memerah", "w": "Hon’inbō Shūsaku", "b": "Inoue Gennan Inseki", "ev": "Permainan di Osaka (dimainkan tiga hari)", "d": "1846", "pl": "Jepang (Osaka)", "lead": "Shūsaku yang berusia 17 tahun (4-dan) melawan Gennan (8-dan), salah satu pemain terkuat saat itu. Konon, saat langkah ke-127, telinga Gennan memerah — dari situlah namanya. Belum ada komi: Hitam menang 2 poin.",
      c: {
        "0": "Osaka, 1846. Shūsaku memegang Hitam, Gennan Putih. Sehari sebelumnya mereka mulai bermain dengan voor dua batu, tetapi dihentikan; kali ini Shūsaku bermain Hitam tanpa voor.",
        "1": "Hitam 1 di titik 3-4 kanan atas (R16), titik rendah yang mudah mengamankan sudut.",
        "2": "Putih 2 mengambil titik 3-4 kiri atas (D17). Mula-mula sudut-sudut kosong dibagi.",
        "5": "Dengan 1, 3, dan 5, Hitam mengambil tiga sudut, semuanya di titik 3-4. Ini pembukaan kesukaan Shūsaku yang kemudian banyak dipelajari.",
        "6": "Putih 6 di C14 sisi kiri. Alih-alih mendekati sudut Hitam, Putih mengambil sisi — pilihan yang agak jarang.",
        "7": "Hitam 7 (E4) menutup sudut kiri bawah dengan batu kedua. “Penutupan” ini membuat sudut sangat kokoh.",
        "8": "Putih 8 (R5) mendekati sudut Hitam di Q3. Pertarungan besar di kanan bawah akan dimulai.",
        "10": "Putih 10 (O4) adalah taisha: menutupi batu Hitam secara diagonal dari jauh. Variasinya sangat banyak, dan ini langkah kesukaan Gennan.",
        "11": "Dengan 11 (Q5), Hitam masuk ke jalur yang sulit. Gennan sangat paham taisha, jadi Hitam harus berhati-hati.",
        "24": "Di kanan bawah batu-batu saling terjalin; masing-masing ingin memotong lawan. Setelah Putih 24 (N4), batu Hitam sulit keluar.",
        "25": "Hitam 25 (N3). Kajian kemudian menyebut ada langkah yang lebih baik di sini. Bahkan bagi seorang master, ini posisi sulit.",
        "28": "Dengan 28 (M3) dan 30 (L2), Putih langsung menyerang kelemahan Hitam. Batu Hitam bisa terkurung di ruang sempit di bawah.",
        "31": "Hitam 31 (M4) penting. Ia menyiapkan ko yang akan datang — perebutan saling makan — dengan membuat ancaman yang harus dijawab Putih.",
        "36": "Putih 36 (N2). Sebelum memulai ko, Putih bermain di sini dulu. Waktunya tepat.",
        "40": "Putih 40 (R1) memakan satu batu dan ko dimulai. Pihak yang batunya dimakan tidak boleh langsung membalas; ia harus membuat ancaman di tempat lain dulu.",
        "41": "Hitam 41 (O5) adalah ancaman ko. Sedikit rugi, tetapi tidak ada pilihan lebih baik di sini.",
        "53": "Hitam 53 (R10) adalah ide cerdik yang jarang terpikirkan. Ia mengganggu bentuk Putih di sisi kanan.",
        "60": "Putih 60 (S3) langkah besar. Berkat itu, 62 (M1) juga bisa dimainkan dengan inisiatif.",
        "63": "Setelah Hitam 63 (O1), pertarungan panjang di kanan bawah mereda. Putih punya wilayah di bawah, Hitam punya dinding tebal di kanan. Sejauh ini Putih tampak lebih baik.",
        "67": "Hitam 67 (L17). Bersandar pada dinding di kanan, Hitam membangun kerangka besar di atas.",
        "72": "Putih 72 (P13) langkah yang luar biasa. Diletakkan tepat di atas dinding Hitam, ia menghentikan kerangka Hitam membesar.",
        "74": "Dari sini sampai sekitar langkah 100, Gennan tidak sekali pun lengah. Ia menghindari serangan dan menjaga batunya tetap tersambung.",
        "83": "Hitam 83 (H3) masuk ke daerah Putih di bawah untuk memperkecilnya.",
        "96": "Sejak Putih 96 (R14) terjadi pertarungan halus di sekitar sudut kanan atas Hitam. Putih kembali menemukan bentuk yang baik.",
        "107": "Hitam 107 (P10) memakan satu batu Putih. Kelompok Hitam di kanan kini aman.",
        "118": "Putih 118 (M19) memakan satu batu, dan kelompok Putih di atas juga hidup. Kerangka Hitam di atas jadi lebih kecil dari harapan.",
        "126": "Putih 126 (J5). Putih tebal di bawah dan menjangkau ke tengah. Konon kebanyakan pemain profesional yang menonton mengira Putih unggul.",
        "127": "Inilah langkah terkenal “telinga memerah”, Hitam 127 (K11). Konon satu batu di tengah ini bekerja ke empat arah sekaligus: memperluas daerah Hitam di atas, melemahkan ketebalan Putih di bawah, membantu kelompok Hitam di kanan, dan menghalangi Putih meluas ke kiri.",
        "128": "Saat itu seorang dokter yang menonton melihat telinga Gennan memerah. Ia tidak paham go, tetapi konon menganggapnya tanda gelisah dan menebak Hitam akan menang.",
        "131": "Hitam 131 (D10). Hitam juga masuk ke sisi kiri Putih dan memangkas wilayah Putih di seluruh papan.",
        "147": "Hitam 147 (K10). Batu langkah 127 mulai berguna: Hitam maju di antara kelompok-kelompok Putih di tengah.",
        "160": "Putih 160 (H8). Putih menjaga batu di tengah sambil mengincar kelompok Hitam di kiri bawah. Permainan masih ketat.",
        "167": "Hitam 167 (C2) tepat. Batu Hitam di sudut kiri bawah kini aman, dan ancaman Putih hilang.",
        "175": "Hitam 175 (G4) memakan satu batu Putih. Wilayah Putih di bawah tidak sebesar kelihatannya.",
        "199": "Hitam 199 (K7). Pertarungan di tengah mereda, lalu masuk ke tahap akhir: menetapkan batas, di mana setiap poin berarti.",
        "212": "Dengan 212 (D19) dan 216 (F19), Putih memakan batu Hitam di tepi atas. Di tahap akhir tidak ada yang mengalah.",
        "228": "Putih 228 (N12) menciptakan ko di tengah. Selama lebih dari 80 langkah, kedua pihak bergantian memakan di M13 dan N13.",
        "236": "Putih 236 (T8), dimainkan saat ko, memakan satu batu. Sebagian analis menilai mengakhiri ko di sini akan membuat selisihnya lebih tipis.",
        "275": "Hitam 275 (T14) memakan dua batu Putih. Selama ko, kedua pihak untung di sini dan rugi di sana di seluruh papan.",
        "299": "Hitam 299 (J16) memakan empat batu Putih sekaligus. Hitam menjaga bagian atas dengan kokoh.",
        "311": "Hitam 311 (M13) menutup ko. Pertarungan ko yang panjang akhirnya selesai.",
        "325": "Permainan selesai setelah 325 langkah, dan hitungan menunjukkan Hitam unggul 2 poin. Meski tanpa komi, kemenangan anak 17 tahun atas pemain sekelas Gennan menggemparkan, dan nama Shūsaku pun terkenal."
      } },
    "evergreen": { "t": "Partai Hijau Abadi", "w": "Adolf Anderssen", "b": "Jean Dufresne", "ev": "Partai santai (bukan turnamen)", "d": "1852", "pl": "Jerman (kemungkinan Berlin)", "lead": "Anderssen, pemenang Partai Abadi, memainkan mahakarya lain ini setahun kemudian. Tepat ketika Hitam mengancam skakmat, Putih dengan tenang memindahkan satu benteng, lalu mengorbankan menteri dan menutup dengan skak ganda. Disebut \"hijau abadi\" (Evergreen) karena tak pernah pudar.",
      c: {
        "0": "Partai yang dimuat di majalah pada 1852. Putih adalah Anderssen, Hitam temannya, Dufresne. Diduga dimainkan di Berlin, tetapi tidak ada catatan yang memastikannya.",
        "1": "Putih memajukan pion raja dua petak.",
        "2": "Hitam melakukan hal yang sama.",
        "3": "Kuda menyerang pion e5.",
        "4": "Hitam menjaga e5 dengan kuda.",
        "5": "Gajah keluar dan membidik f7.",
        "6": "Hitam juga mengeluarkan gajah.",
        "7": "b4! Tawaran pion yang disebut Gambit Evans. Selagi Hitam memakannya, Putih membangun pusat.",
        "8": "Hitam memakan pion.",
        "9": "c3 mengejar gajah dan bersiap untuk d4.",
        "10": "Gajah mundur ke a5.",
        "11": "d4 merebut pusat.",
        "12": "Hitam memakan pion.",
        "13": "Putih tidak memakan kembali, tetapi rokade. Keamanan raja dan buah yang aktif lebih penting daripada pion.",
        "14": "Pion Hitam maju sampai d3, jauh di dalam wilayah Putih.",
        "15": "Menteri ke b3. Bersama gajah c4, ia membidik f7.",
        "16": "Hitam menjaga f7 dengan menteri.",
        "17": "e5 mengejar menteri.",
        "18": "Menteri ke g6.",
        "19": "Benteng ke e1, masuk lajur e untuk mendukung pion e5.",
        "20": "Hitam mengeluarkan kuda untuk bersiap rokade.",
        "21": "Gajah ke a3, membidik kuda e7 secara diagonal. Jika kuda itu bergerak, gajah menjangkau f8, sehingga Hitam sulit rokade pendek.",
        "22": "Hitam menawarkan pion untuk menarik buah Putih.",
        "23": "Menteri memakannya.",
        "24": "Benteng ke b8, mengejar menteri di lajur b.",
        "25": "Menteri ke a4.",
        "26": "Gajah mundur ke b6.",
        "27": "Kuda keluar. Hampir semua buah Putih sudah bermain.",
        "28": "Hitam mengeluarkan gajah yang lain.",
        "29": "Kuda ke e4, mengincar f6.",
        "30": "Menteri Hitam ke f5 dan menyerang kuda e4.",
        "31": "Gajah memakan pion d3 dan menjaga kuda e4.",
        "32": "Menteri ke h5, membidik kuda di f3.",
        "33": "Kuda dikorbankan di f6 sambil skak!",
        "34": "Hitam memakan dengan pion.",
        "35": "Putih memakan kembali dengan pion dan menyerang kuda e7. Di lajur e, benteng e1 juga mengawasi e7.",
        "36": "Benteng ke g8, membidik g2. Jika menteri h5 memakan di f3, skakmat sudah dekat.",
        "37": "Langkah benteng yang tenang ke d1! Raja Putih dalam bahaya, tetapi Putih tidak bertahan dan malah membidik d7. Langkah inilah yang membuat partai ini \"hijau abadi\".",
        "38": "Hitam memakan kuda f3. Memakan di g2 berikutnya akan menjadi skakmat.",
        "39": "Tetapi Putih jalan lebih dulu. Benteng memakan kuda e7 sambil skak!",
        "40": "Hitam memakan kembali dengan kuda dari c6. Kini diagonal dari a4 ke d7 terbuka.",
        "41": "Menteri dikorbankan di d7 sambil skak!",
        "42": "Hitam harus memakan dengan raja.",
        "43": "Gajah ke f5 sambil skak dan membuka lajur d untuk benteng d1: skak ganda.",
        "44": "Raja ke e8. Jika ke c6, gajah akan skakmat di d7.",
        "45": "Gajah ke d7, skak.",
        "46": "Raja ke f8.",
        "47": "Gajah dari a3 memakan kuda e7: skakmat! Gajah d7 menguasai e8, dan pion f6 menguasai e7 dan g7."
      } },
    "lasker1912": { "t": "Perburuan Raja", "w": "Edward Lasker", "b": "George Alan Thomas", "ev": "Partai cepat dan santai di City of London Chess Club", "d": "1912", "pl": "Britania Raya (London)", "lead": "Partai cepat dan santai di sebuah klub di London. Putih mengorbankan menteri dan mengejar raja Hitam melintasi seluruh papan, dari g8 ke g1. Urutan langkah pembukaan sedikit berbeda di tiap catatan, tetapi posisi setelah langkah ke-10 tetap sama.",
      c: {
        "0": "Oktober 1912, City of London Chess Club. Putih adalah Edward Lasker, insinyur muda yang baru datang dari Jerman; Hitam adalah George Alan Thomas, kelak juara Inggris. Ini partai cepat dan santai. Partai ini terkenal sebagai \"perburuan raja\": raja Hitam dikejar dari g8 sampai g1 di ujung papan yang lain. Lasker kemudian pindah ke Amerika dan dikenal lewat buku-buku caturnya.",
        "1": "Putih memulai dengan d4, pion menteri. Ia menguasai e5 dan c5 serta membuka jalan gajah c1.",
        "2": "Hitam bermain e6: posisi kokoh dulu, sambil menyiapkan f5 atau d5.",
        "3": "Kuda ke f3. Ia menguasai e5 dan membantu menjaga sisi raja: petak paling alami.",
        "4": "Hitam bermain f5 dan menguasai e4, mirip Pertahanan Belanda. Tetapi menggerakkan pion di depan raja membuat raja sedikit lebih lemah.",
        "5": "Kuda yang lain ke c3, bersiap untuk e4 menyerang pion f5.",
        "6": "Hitam mengeluarkan kuda ke f6: makin menguasai e4 dan bersiap rokade.",
        "7": "Gajah ke g5, membidik kuda f6. Kuda itu pembela penting raja Hitam, jadi Putih ingin menyingkirkannya lebih awal.",
        "8": "Hitam menaruh gajah di e7 untuk menjaga kuda dan makin dekat ke rokade.",
        "9": "Putih menukar gajah dengan kuda. Kuda yang melindungi raja Hitam hilang.",
        "10": "Hitam memakan kembali dengan gajah. Kini gajah f6 mengambil alih tugas menjaga sisi raja.",
        "11": "e4! Putih menyerang pion f5 dan merebut ruang di tengah. Jalur terbuka, buah Putih lebih leluasa.",
        "12": "Hitam memakan pion e4. Kalau tidak, Putih akan bermain e5 dan mendorong mundur buah Hitam.",
        "13": "Kuda memakan kembali dan berdiri di tengah, mengawasi gajah f6 serta petak g5 dan d6.",
        "14": "Hitam bermain b6 untuk membawa gajah ke b7 dan membidik kuda e4 lewat diagonal panjang.",
        "15": "Kuda ke e5, petak tengah yang kuat yang juga mengawasi g4 dan f7. Kedua kuda Putih kini dekat sisi raja Hitam.",
        "16": "Hitam rokade. Raja di g8. Tetapi tanpa pion f, banyak celah di sekitar raja.",
        "17": "Gajah ke d3. Untuk sementara terhalang kudanya sendiri di e4, tetapi di baliknya ada pion h7. Begitu kuda e4 bergerak, gajah ini langsung membidik h7.",
        "18": "Gajah Hitam ke b7 dan membidik kuda e4 lewat diagonal panjang, membatasi buah Putih.",
        "19": "Menteri ke h5, membidik pion h7 yang hanya dijaga raja Hitam. Menteri, gajah, dan kuda Putih semuanya mengarah ke raja Hitam.",
        "20": "Hitam menaruh menteri di e7. Ia menjaga gajah f6 dan bersiap ke c5, tetapi Hitam tidak melihat rencana Putih. Seharusnya h6 atau memakan kuda e5. Inilah titik baliknya.",
        "21": "Menteri dikorbankan di h7 sambil skak! Putih memberikan buah terkuatnya begitu saja. Lasker sudah melihat seluruh jalan untuk mengejar raja sampai skakmat.",
        "22": "Hitam harus memakan dengan raja, yang kini berada di h7.",
        "23": "Kuda memakan gajah f6 sambil skak. Sekaligus e4 kosong, dan gajah d3 juga memberi skak kepada raja di h7: skak ganda. Tidak bisa ditutup, raja harus lari.",
        "24": "Raja ke h6. Jika ke h8, kuda yang lain melompat ke g6 dan skakmat. Raja terdorong makin ke depan.",
        "25": "Kuda lainnya melompat dari e5 ke g4 sambil skak, menyerang raja di h6 dan mendorongnya lebih jauh.",
        "26": "Raja ke g5: meninggalkan wilayahnya dan berjalan ke sisi Putih.",
        "27": "Skak dengan pion h! Bahkan pion ikut berburu. Raja harus terus maju.",
        "28": "Raja ke f4. Ia sudah melewati tengah papan dan masuk ke wilayah Putih.",
        "29": "Skak lagi dengan pion g. Dua pion menutup jalan pulang raja.",
        "30": "Raja ke f3, tepat di tengah buah-buah Putih.",
        "31": "Gajah mundur dari d3 ke e2 sambil skak. Raja didorong makin dalam.",
        "32": "Raja ke g2. Raja Putih di e1 sudah tidak jauh.",
        "33": "Benteng ke h2, skak. Akhirnya benteng ikut bermain.",
        "34": "Raja akhirnya tiba di g1. Dari g8 ia berjalan sampai baris pertama di ujung papan yang lain.",
        "35": "Raja Putih melangkah dari e1 ke d2. Ini membuka jalan benteng a1, yang memberi skak kepada raja di g1 di baris pertama: skakmat! Rokade panjang juga skakmat, tetapi Lasker menggerakkan raja. Dalam partai cepat, setelah mengorbankan menteri, Putih mengejar raja selama empat belas langkah sampai sudut terdalam wilayahnya sendiri. Partai yang sangat langka."
      } },
    "toketsu": { "t": "Permainan Muntah Darah", "w": "Akaboshi Intetsu", "b": "Hon’inbō Jōwa", "ev": "Dimainkan di kediaman Tuan Matsudaira dari Suō (empat hari)", "d": "1835", "pl": "Jepang (Edo)", "lead": "Permainan yang lahir dari perebutan jabatan Meijin Godokoro, posisi tertinggi dalam go Jepang. Inoue Gennan Inseki mengirim muridnya, Akaboshi Intetsu, melawan Meijin Jōwa. Setelah empat hari bertarung, Intetsu kalah dan konon batuk darah di depan papan.",
      c: {
        "0": "1835. Hitam: Akaboshi Intetsu (7-dan); Putih: Meijin Hon’inbō Jōwa. Gennan mengirim murid terbaiknya agar bisa berkata: Meijin yang kalah dari 7-dan tidak layak bergelar itu.",
        "1": "Hitam 1 di titik 3-4 kiri bawah (C4). Intetsu memulai dengan tenang.",
        "4": "Setelah empat langkah, tiap sudut berisi satu batu: Putih di kanan bawah dan kiri atas, Hitam di kiri bawah dan kanan atas.",
        "6": "Putih 6 (E3) sudah mendekati sudut kiri bawah Hitam. Jōwa aktif sejak awal.",
        "10": "Putih 10 (P4) menutup sudut kanan bawah dengan batu kedua.",
        "12": "Putih 12 (D6) menekan sudut kiri bawah Hitam dari atas. Pertarungan terbesar permainan ini dimulai di sini.",
        "13": "Hitam 13 (E4) menempel langsung pada batu Putih. Hitam menerima tantangan.",
        "20": "Putih 20 (C3) menyusup ke bawah sudut Hitam: menggerogoti wilayah sudut sambil berusaha menghidupkan batunya.",
        "28": "Putih 28 (C9) melebar jauh di sisi kiri. Sering dianggap berlebihan — langkah garang khas Jōwa.",
        "33": "Hitam 33 (C2). Konon ini variasi baru yang diam-diam dipelajari keluarga Inoue. Ia menyerang batu Putih yang mengambang di tengah sambil menelan batu Putih di sisi kiri.",
        "36": "Putih 36 (F3). Putih mencoba mengurung Hitam dari luar di kiri bawah sambil menyambung batunya.",
        "43": "Hitam 43 (E9). Batu Putih di kiri kesulitan. Sampai di sini Intetsu bermain bagus dan dianggap unggul.",
        "45": "Hitam 45 (D11) memanjang ke atas di sisi kiri, menjaga batu Putih tetap terpisah sambil memperkuat diri.",
        "50": "Putih 50 (C16). Putih meninggalkan kiri bawah sejenak dan beralih ke sudut kiri atas.",
        "53": "Hitam 53 (G17). Hitam masuk ke sisi atas agar Putih tidak bisa memperluas kiri atas.",
        "58": "Putih 58 (C14) melebar dari sudut kiri atas di sepanjang sisi dan mendekati batu Hitam di kiri.",
        "60": "Putih 60 (G4) memakan dua batu Hitam. Kelompok Putih di kiri bawah akhirnya sedikit lega.",
        "62": "Putih 62 (J17). Di atas pun keduanya berhadapan. Ada batu lemah di seluruh papan — posisi yang sulit.",
        "66": "Putih 66 (B14). Di sekitar sudut kiri atas, Putih menstabilkan batunya.",
        "68": "Putih 68 (B11). Beberapa langkah Putih berikutnya, bersama langkah 80, terkenal sebagai langkah gemilang Jōwa. Begitu hebatnya hingga orang bilang hantu yang menunjukkannya.",
        "70": "Putih 70 (E12). Bukannya langsung menjawab Hitam di kiri, Putih lebih dulu mengambil titik kunci lain. Kemungkinan tersembunyi yang tersisa membuatnya bisa.",
        "72": "Putih 72 (R13). Putih beralih ke sisi kanan agar daerah Hitam di kanan atas tidak membesar.",
        "76": "Putih 76 (O14). Putih menghubungkan sisi kanan dengan tengah dan bersiap memisahkan batu Hitam.",
        "80": "Putih 80 (Q10) membentuk “segitiga kosong”, bentuk yang biasanya dianggap buruk. Namun langkah inilah yang menjadi pijakan untuk membelah Hitam menjadi dua dan menyerangnya. Contoh klasik langkah jelek tapi hebat.",
        "83": "Hitam 83 (R3) masuk ke sudut kanan bawah Putih. Di sana terjadi pertarungan sengit saling makan.",
        "91": "Hitam 91 (Q4) memakan satu batu Putih. Sudut kanan bawah penting bagi Hitam.",
        "98": "Putih 98 (M4). Putih membungkus batu Hitam di bawah dan tidak membiarkannya hidup dengan mudah.",
        "106": "Putih 106 (S5) memakan satu batu Hitam. Putih mempertahankan sudut kanan bawah, dan batu Hitam harus lari ke luar.",
        "113": "Hitam 113 (K6). Batu Hitam di bawah mencari hidup dengan keluar ke tengah.",
        "120": "Putih 120 (N9) menghadang batu Hitam yang lari. Di tengah, yang penting siapa yang lebih dulu melemah.",
        "128": "Putih 128 (L11) juga menekan batu Hitam di tengah dari atas. Hitam masih belum bisa tenang.",
        "138": "Putih 138 (K8) memakan satu batu dan ko dimulai di tengah. Sekitar 30 langkah, keduanya bergantian memakan di K8 dan L8.",
        "152": "Putih 152 (E11) adalah ancaman ko. Selama ko, Putih terus menemukan langkah di mana-mana yang harus dijawab Hitam.",
        "170": "Putih 170 (P15). Ko di tengah sudah reda; Putih beralih ke kanan atas, mengincar kelompok besar Hitam yang belum sepenuhnya hidup.",
        "178": "Putih 178 (J14) melompat ke tengah daerah atas untuk memisahkan batu Hitam kiri dan kanan. Serangan pemisah yang disiapkan sejak langkah 80 kini dimulai sungguh-sungguh.",
        "193": "Hitam 193 (J11) memakan satu batu Putih. Hitam berjuang keras untuk menyambung dan hidup.",
        "201": "Hitam 201 (R14) memakan satu batu dan ko baru dimulai di sisi kanan, saling makan di R14 dan R15.",
        "206": "Putih 206 (M13). Bahkan saat ko, Putih perlahan mempersempit ruang batu Hitam di tengah.",
        "222": "Putih 222 (L14) memakan satu batu. Batu Hitam di atas tetap terbelah dua, dan menyelamatkan keduanya makin sulit.",
        "230": "Putih 230 (C13) juga menyerang titik lemah Hitam di sisi kiri. Batu-batu Putih kini tersambung kokoh di seluruh papan.",
        "237": "Dengan 237 (F12) dan 239 (E13), Hitam membalas memakan batu di kiri atas. Meski begitu, selisih keseluruhan tidak mengecil.",
        "246": "Setelah Putih 246 (L8), Intetsu menyerah. Konon saat batu-batu dibereskan, ia batuk darah di atas papan. Ia mungkin sudah lama sakit, dan meninggal tak lama kemudian. Bagi Jōwa, ini disebut kemenangan terbesar dalam hidupnya."
      } },
    "deepblue1997": { "t": "Kemenangan Deep Blue", "w": "Deep Blue (komputer IBM)", "b": "Garry Kasparov", "ev": "Partai ke-6 pertandingan ulang melawan Deep Blue dari IBM (pertandingan enam partai)", "d": "1997", "pl": "Amerika Serikat (New York)", "lead": "Juara dunia Kasparov melawan Deep Blue, komputer catur buatan IBM, dalam pertandingan enam partai. Skor imbang setelah lima partai, dan partai terakhir selesai hanya dalam 19 langkah. Untuk pertama kalinya sebuah komputer mengalahkan juara dunia dalam pertandingan penuh beberapa partai.",
      c: {
        "0": "New York, 11 Mei 1997. Setahun sebelumnya Kasparov memenangi pertandingan mereka. Kali ini skornya 2½–2½ setelah lima partai. Deep Blue memegang Putih.",
        "1": "Putih memajukan pion raja dua petak.",
        "2": "Kasparov bermain c6: Pertahanan Caro-Kann.",
        "3": "Putih membawa pion lain ke tengah.",
        "4": "Hitam bermain d5, menyerang e4.",
        "5": "Kuda menjaga e4.",
        "6": "Hitam memakan pion e4.",
        "7": "Kuda memakan kembali.",
        "8": "Hitam menaruh kuda di d7, bersiap membawa kuda lain ke f6.",
        "9": "Kuda melompat ke g5: rencana tajam yang membidik f7 dan e6.",
        "10": "Hitam mengeluarkan kuda ke f6.",
        "11": "Gajah ke d3, mengawasi sisi raja Hitam.",
        "12": "Hitam memperkuat pertahanan dengan e6.",
        "13": "Kuda yang lain keluar ke f3.",
        "14": "Hitam bermain h6 untuk mengusir kuda g5. Tetapi di posisi ini pengorbanan kuda untuk Putih sudah dikenal. Banyak yang bilang ini pilihan yang tidak biasa bagi Kasparov.",
        "15": "Kuda dikorbankan di e6! Konon Deep Blue memainkan langkah ini dari langkah pembukaan yang sudah disimpannya.",
        "16": "Hitam tidak langsung memakan, tetapi menaruh menteri di e7. Di lajur e, ia membidik kuda e6 dan raja Putih di belakangnya.",
        "17": "Putih rokade dan menyelamatkan raja.",
        "18": "Hitam memakan kuda dan unggul materi.",
        "19": "Gajah ke g6, skak. Tanpa pion f7, diagonal sampai ke raja.",
        "20": "Raja ke d8. Hitam tidak bisa rokade lagi, dan raja tertahan dekat tengah.",
        "21": "Gajah yang lain keluar dan membidik petak di sekitar raja Hitam.",
        "22": "Hitam bermain b5, membuat ruang di sisi menteri untuk raja dan gajah.",
        "23": "a4 menyerang pion b5.",
        "24": "Hitam menaruh gajah di b7.",
        "25": "Benteng ke e1. Di lajur e, ia membidik pion e6 dan di baliknya menteri e7.",
        "26": "Kuda Hitam ke d5 dan menyerang gajah f4.",
        "27": "Gajah mundur ke g3.",
        "28": "Raja Hitam ke c8, sedikit lebih aman.",
        "29": "Putih memakan pion b5.",
        "30": "Hitam memakan kembali.",
        "31": "Menteri ke d3, mengawasi pion b5 dan petak f5.",
        "32": "Hitam menjaga b5 dengan gajah.",
        "33": "Gajah ke f5! Bisa dimakan gratis.",
        "34": "Hitam memakan dengan pion. Tetapi kini pion di lajur e hilang.",
        "35": "Benteng memakan menteri e7. Putih sudah memberi kuda, gajah, dan benteng, tetapi mendapat menteri.",
        "36": "Hitam memakan benteng dengan gajah.",
        "37": "c4! Pion menyerang b5 dan d5 sekaligus, dan pertahanan Hitam mulai runtuh. Kasparov menyerah di sini, mungkin merasa rajanya terlalu terbuka untuk menahan serangan. Sebuah komputer telah memenangi pertandingan melawan juara dunia."
      } },
    "seigen1933": { "t": "Permainan 3-3, Titik Bintang, dan Tengen", "w": "Go Seigen", "b": "Hon’inbō Shūsai", "ev": "Permainan peringatan dengan sang Meijin (lebih dari tiga bulan)", "d": "1933–1934", "pl": "Jepang (Tokyo)", "lead": "Go Seigen yang berusia 19 tahun (5-dan) melawan Meijin Hon’inbō Shūsai. Dengan Hitam ia membuka di titik 3-3, lalu titik bintang, lalu tepat di tengah (tengen) — melanggar semua kebiasaan saat itu dan mengejutkan dunia go. Dengan banyak jeda, permainan berlangsung lebih dari tiga bulan; Putih menang 2 poin.",
      c: {
        "0": "1933. Tahun itu Go Seigen dan sahabatnya Kitani Minoru sedang menyebarkan gaya pembukaan baru, “Shinfuseki”. Semua ingin melihat bagaimana ia memakainya melawan sang Meijin.",
        "1": "Hitam 1 di titik 3-3 kanan atas (R17). Sekali langkah sudut aman, tetapi pengaruh ke luarnya kecil; saat itu tak ada yang menganggapnya langkah pembuka.",
        "3": "Hitam 3 di titik bintang kiri bawah (D4). Berbeda dengan 3-3, titik bintang mengutamakan perluasan ke luar.",
        "5": "Hitam 5 langsung ke tengah papan — tengen (K10). Bukan sudut, bukan sisi, melainkan tengah. Di depan sang Meijin, Go Seigen memamerkan gagasan barunya terang-terangan.",
        "6": "3-3, bintang, tengen: tiap batu Hitam punya tugas berbeda — wilayah sudut, jangkauan ke luar, dan kekuatan di tengah. Dengan 6 (Q16), Putih bermain tepat di sebelah batu 3-3 Hitam.",
        "9": "Hitam 9 (P18). Hitam memantapkan sudut kanan atas dengan ringkas dan aman — gaya mengutamakan wilayah, khas titik 3-3.",
        "11": "Hitam 11 (K4) ke tengah sisi bawah, tepat di bawah tengen. Bersama batu itu, Hitam mengincar daerah besar di bawah.",
        "12": "Putih 12 (M3) langsung masuk ke sisi bawah agar Hitam tak bisa membangun kerangka besar. Sang Meijin tenang dan membongkar rencana Hitam satu per satu.",
        "13": "Hitam 13 (D10), kini di tengah sisi kiri. Batu-batu Hitam berada tinggi dan bersama membentuk kerangka luas.",
        "14": "Putih 14 (E16) menutup sudut kiri atas dengan batu kedua. Sang Meijin tidak terpengaruh gaya baru dan dengan tenang mengamankan sudut.",
        "21": "Hitam 21 (G10) menghubungkan tengen dengan batu di sisi kiri, dan pengaruh Hitam menyebar di tengah.",
        "28": "Putih 28 (D3) menyusup di bawah batu bintang Hitam kiri bawah dan mengambil sudut. Hitam merelakannya demi kekuatan di luar.",
        "30": "Putih 30 (Q12) melebar di sisi kanan sekaligus menutup bagian luar sudut 3-3 Hitam, melemahkan jangkauannya.",
        "37": "Hitam 37 (P15) memakan satu batu Putih. Di kanan atas keduanya bertabrakan dalam pertarungan ketat.",
        "40": "Putih 40 (O10) keluar dari sisi kanan ke arah tengah, mendekati pengaruh Hitam di sekitar tengen.",
        "44": "Putih 44 (H17) mengambil titik di sisi atas untuk menahan Hitam meluas ke atas.",
        "45": "Hitam 45 (R7) mulai mengusik posisi Putih di kanan bawah. Menyusul pertarungan panjang dari sisi kanan hingga sudut itu.",
        "59": "Hitam 59 (R4) juga masuk ke sudut kanan bawah dan memperkecil wilayah Putih.",
        "70": "Putih 70 (N6) mendorong dari sisi bawah ke tengah untuk memisahkan batu Hitam kanan bawah dari yang di tengah.",
        "79": "Hitam 79 (L9) memperkuat tengah di sekitar batu tengen. Sejauh ini permainan tampak cukup seimbang.",
        "80": "Putih 80 (C6) bergerak dari sudut kiri bawah ke sisi kiri, mengincar batu Hitam di sana.",
        "98": "Putih 98 (A11) memakan dua batu Hitam. Putih hidup rapi di tepi kiri, dan sisi kiri Hitam lebih kecil dari rencana.",
        "101": "Hitam 101 (S14) kembali ke kanan atas untuk mengecilkan posisi Putih di sisi kanan.",
        "105": "Hitam 105 (K17) mengambil tengah sisi atas dan mulai menyerang batu Putih di sana.",
        "117": "Hitam 117 (F17) juga masuk ke sekitar sudut kiri atas Putih, dan seluruh sisi atas menjadi medan tempur.",
        "124": "Putih 124 (K15) membawa batu atasnya ke tengah sambil memotong di antara batu Hitam.",
        "135": "Hitam 135 (E9) memakan dua batu Putih. Hitam merebut kembali sedikit di sisi kiri.",
        "138": "Putih 138 (N18) mengamankan wilayah di sisi atas. Di seluruh papan, posisinya sangat ketat.",
        "153": "Hitam 153 (K14). Batu Hitam di tengah membentuk jalan tebal yang menghubungkan atas dan bawah. Kuncinya: bagaimana Putih bisa membobol ketebalan itu.",
        "159": "Hitam 159 (F4) bertahan kokoh di kiri bawah. Langkah Putih berikutnya adalah langkah paling terkenal di permainan ini.",
        "160": "Putih 160 (H8) melompat ke celah ketebalan Hitam — langkah tajam dengan beberapa tujuan sekaligus, dari sini Putih mulai menembus tengah Hitam. Beredar desas-desus bahwa langkah ini ditemukan muridnya, bukan Shūsai, tetapi tak pernah terbukti.",
        "161": "Hitam 161 (J8) langsung menjawab, tetapi Putih punya lebih dari satu sasaran.",
        "162": "Putih 162 (K12) beralih ke bagian atas tengah dan mengancam sambungan batu Hitam.",
        "172": "Putih 172 (F13) menghubungkan batu dari tengah ke kiri atas. Sedikit demi sedikit, ketebalan Hitam di tengah tak lagi menjadi wilayah.",
        "178": "Putih 178 (N9) juga masuk ke daerah Hitam di kanan tengah.",
        "187": "Dengan 187 (M6) dan 189 (L7), Hitam membalas dengan memakan batu Putih. Meski begitu, Putih sudah lebih dulu menempati titik-titik penting.",
        "198": "Putih 198 (E12) memakan satu batu. Batu Putih di kiri atas juga tersambung, dan Putih sedikit unggul secara keseluruhan.",
        "203": "Hitam 203 (B3). Mulai sini tahap akhir: batas-batas di tepi ditetapkan poin demi poin.",
        "224": "Putih 224 (T10) memakan satu batu. Bahkan di tepi kanan, Putih tidak memberi satu poin pun.",
        "233": "Hitam 233 (L13) memakan dua batu Putih. Hitam terus mengejar sampai akhir.",
        "252": "Permainan selesai setelah 252 langkah: Putih menang 2 poin. Tanpa komi, Hitam punya sedikit keuntungan jalan duluan, tetapi sang Meijin tetap teguh sampai akhir. Meski begitu, 3-3, titik bintang, dan tengen Go Seigen menggemparkan dan menandai era baru pembukaan."
      } },
    "century1956": { "t": "Partai Abad Ini", "w": "Donald Byrne", "b": "Bobby Fischer", "ev": "Turnamen Trofi Rosenwald ketiga (Memorial Rosenwald)", "d": "1956", "pl": "Amerika Serikat (New York)", "lead": "Bobby Fischer yang berusia tiga belas tahun mengalahkan Donald Byrne, salah satu master terkuat Amerika. Pada langkah ke-17 Fischer membiarkan menterinya dimakan begitu saja, lalu merebut kembali buah demi buah, dan akhirnya buah-buah kecilnya memburu raja Putih. Fischer kelak menjadi juara dunia.",
      c: {
        "0": "New York, 17 Oktober 1956, partai turnamen. Hitam dimainkan Fischer yang berusia tiga belas tahun; Putih oleh Byrne, salah satu pemain terbaik Amerika.",
        "1": "Putih memulai dengan kuda.",
        "4": "Fischer bermain g6 untuk menaruh gajah di diagonal panjang.",
        "8": "Hitam rokade: raja aman lebih dulu.",
        "10": "Hitam bermain d5. Perebutan pusat dimulai.",
        "15": "Dengan e4, Putih punya dua pion berdampingan di tengah.",
        "17": "Benteng ke d1, mendukung pion d4. Putih masih belum rokade.",
        "18": "Kuda ke b6 dan mengejar menteri di c4.",
        "20": "Gajah ke g4, menekan kuda di f3.",
        "21": "Gajah Putih ke g5. Raja Putih masih di tengah.",
        "22": "Kuda ke a4! Melompat ke petak yang bisa dimakan. Idenya: jika kuda c3 pergi, pion e4 kehilangan penjaganya.",
        "23": "Putih tidak memakan kuda dan memindahkan menteri ke a3.",
        "26": "Kuda Hitam memakan pion e4. Pusat Putih runtuh.",
        "27": "Gajah Putih memakan pion e7 dan sekaligus menyerang menteri Hitam dan benteng f8.",
        "28": "Menteri ke b6! Hitam membiarkan benteng f8. Fischer mengandalkan raja Putih yang masih di tengah.",
        "29": "Putih tidak memakan benteng, tetapi mengeluarkan gajah.",
        "30": "Kuda memakan pion c3 dan menyerang benteng d1.",
        "31": "Gajah ke c5, menyerang menteri Hitam di b6.",
        "32": "Skak dari benteng di lajur e!",
        "33": "Raja ke f1. Sekarang Putih tidak bisa rokade lagi.",
        "34": "Gajah ke e6! Langkah paling terkenal di partai ini: Hitam membiarkan menterinya dimakan gratis. Sebagai gantinya, Hitam punya rencana merebut kembali buah demi buah.",
        "35": "Putih memakan menteri Hitam.",
        "36": "Gajah ke c4, skak. Serangan balik Hitam dimulai.",
        "38": "Kuda memberi skak dari e2.",
        "40": "Saat raja kembali ke f1, kuda bergerak dan membuka skak dari gajah c4. Sambil lewat, kuda menyambar pion d4.",
        "44": "Kuda kembali ke c3, skak terbuka lagi, kali ini menyerang benteng d1. Memberi skak berulang-ulang sambil mengambil buah disebut \"kincir angin\".",
        "46": "Hitam merebut kembali gajah. Kuda c3 masih menyerang benteng d1.",
        "50": "Kuda memakan benteng d1. Kini Hitam sudah merebut kembali lebih dari menteri dan jelas unggul.",
        "52": "Benteng juga memakan pion a2.",
        "56": "Hitam menukar benteng. Makin sedikit buah tersisa, makin untung pihak yang punya lebih banyak.",
        "57": "Menteri Putih memberi skak.",
        "58": "Hitam menutup dengan gajah.",
        "64": "b5. Pion Hitam mulai berjalan.",
        "68": "Raja ke g7 dan membebaskan gajah f8.",
        "70": "Kini buah-buah Hitam memburu raja Putih. Skak dengan gajah.",
        "72": "Kuda memberi skak di g3.",
        "74": "Skak dengan gajah yang lain.",
        "76": "Gajah ke b3, skak.",
        "78": "Kuda memberi skak di e2.",
        "80": "Kuda memberi skak di c3. Raja dikejar ke sana kemari.",
        "82": "Benteng ke c2: skakmat! Benteng, dua gajah, dan kuda bekerja sama. Seorang anak berusia tiga belas tahun menunjukkan bagaimana banyak buah bisa bermain sebagai satu tim."
      } },
    "oshiro1849": { "t": "Permainan Kastel Pertama Shūsaku", "w": "Hon’inbō Shūsaku", "b": "Yasui Sanchi IX", "ev": "Permainan Kastel (permainan tahunan di Kastel Edo)", "d": "1849", "pl": "Jepang (Edo)", "lead": "Permainan Kastel adalah ajang tahunan tempat para pemain dari rumah go resmi bermain di kastel sang shogun. Shūsaku yang berusia 20 tahun tampil pertama kali tahun itu dan menang dengan Hitam 11 poin — awal rekor sempurna 19 kemenangan dari 19 Permainan Kastel.",
      c: {
        "0": "1849. Setahun sebelumnya Shūsaku ditetapkan sebagai pewaris rumah Hon’inbō, dan kini ia memainkan Permainan Kastel pertamanya. Konon permainan ini sering dimainkan lebih dulu di tempat lain, lalu hanya diulang di kastel.",
        "1": "Hitam 1 di titik 3-4 kanan atas (R16). Seperti biasa, Shūsaku memulai dengan 3-4 yang tenang.",
        "4": "Putih 4 (C15) mendekati batu Hitam D17 di kiri atas. Pertarungan dimulai lebih awal di sana.",
        "5": "Hitam 5 (C11) menjepit batu Putih yang mendekat dari bawah, agar Putih tak mudah mapan di sisi kiri.",
        "12": "Putih 12 (C17). Putih mengambil sudut kiri atas, Hitam mendapat batu yang menghadap ke luar — pertukaran yang adil.",
        "13": "Hitam 13 (J17) memanfaatkan batu luar dan melebar di sisi atas.",
        "15": "Hitam 15 (C5) mengambil sudut terakhir yang kosong di kiri bawah. Keempat sudut kini terisi.",
        "16": "Putih 16 (E4) segera mendekati batu Hitam itu, dan pertarungan juga terjadi di kiri bawah.",
        "19": "Hitam 19 (D2) mengamankan sudut kiri bawah dengan kokoh — pilihan mantap khas Shūsaku.",
        "23": "Hitam 23 (E5) keluar di antara batu Putih dan memperkuat kelompoknya di kiri bawah.",
        "29": "Hitam 29 (F11) memperkuat batu Hitam di kiri sambil menatap ke tengah.",
        "30": "Putih 30 (H4) melebar di bawah, menekan kelompok Hitam di kiri sambil membangun daerahnya sendiri.",
        "31": "Hitam 31 (O3) mendekati sudut kanan bawah Putih.",
        "33": "Hitam 33 (R3) menempel pada batu sudut Putih. Dari sini Hitam membangun di luar, sementara Putih merayap di garis ketiga tepi.",
        "43": "Hitam 43 (Q8). Kini dinding Hitam yang tebal membentang di sisi kanan. Putih mendapat wilayah sudut dan tepi; Hitam mendapat kekuatan luar.",
        "44": "Putih 44 (L17) masuk di antara batu Hitam di sisi atas agar daerah Hitam tidak terlalu besar.",
        "50": "Putih 50 (R18) menyusup ke bawah sudut kanan atas Hitam, mengincar wilayah sudut.",
        "51": "Hitam 51 (P13). Dengan dinding di belakang, Hitam membentuk daerah besar dari sisi kanan ke tengah.",
        "52": "Putih 52 (D10) masuk di antara batu Hitam di sisi kiri. Di sana batu-batu saling membelit.",
        "63": "Hitam 63 (B10) bermain di tepi kiri agar batu Putih tak bisa membangun pangkalan di sana.",
        "65": "Hitam 65 (G3) juga masuk ke daerah Putih di bawah dan memperkecil wilayahnya.",
        "73": "Hitam 73 (K17) memperkuat batu atasnya dan menekan batu Putih langkah 44.",
        "76": "Putih 76 (P11) melompat masuk ke daerah Hitam di sisi kanan. Hidup-matinya batu ini sangat menentukan skor.",
        "77": "Hitam 77 (Q11) menjawab dari sisi dindingnya dan mendorong Putih ke tengah — bertahan dengan tenang sekaligus menyerang, khas Shūsaku.",
        "80": "Putih 80 (N10) lari ke tengah, mencoba lolos dari kejaran Hitam.",
        "85": "Hitam 85 (N12) terus menyerang sambil memperluas wilayahnya di atas dan kanan. Untung lewat serangan — permainan cakap.",
        "91": "Hitam 91 (J7) bermain di atas batu Putih bawah, menutup daerah Putih dari arah tengah juga.",
        "100": "Putih 100 (S17) mencoba sesuatu di sudut kanan atas untuk mengurangi wilayah sudut Hitam.",
        "119": "Hitam 119 (R17) mempertahankan sudut kanan atas dengan kokoh dan menahan usaha Putih.",
        "122": "Putih 122 (G6) memutar di luar batu Hitam kiri bawah, mencoba memotongnya dari Hitam di tengah.",
        "131": "Hitam 131 (M5) menancapkan baji ke daerah Putih di tengah sisi bawah.",
        "140": "Putih 140 (B4) mencoba sesuatu di sudut kiri bawah Hitam. Pertarungan saling makan yang ketat dimulai di tepi kiri.",
        "156": "Putih 156 (A8) memakan dua batu Hitam. Pertarungan di tepi kiri mereda setelah keduanya sama-sama mendapat sedikit.",
        "158": "Putih 158 (L10). Putih masih punya batu di tengah dan mencoba mengurangi wilayah tengah Hitam.",
        "162": "Putih 162 (O12) memakan satu batu Hitam. Meski begitu, daerah Hitam di kanan tetap besar.",
        "172": "Putih 172 (K18). Mulai sini tahap akhir, diawali batas di sisi atas.",
        "186": "Putih 186 (T16) memangkas wilayah Hitam di tepi kanan atas. Di tahap akhir, keduanya memainkan titik terbesar lebih dulu.",
        "205": "Hitam 205 (Q18) menutup bagian kanan sisi atas dan memastikan wilayahnya di sana.",
        "223": "Hitam 223 (P10) menetapkan batas antara wilayah Hitam di kanan dan batu Putih yang lolos ke tengah.",
        "233": "Hitam 233 (Q9) memakan satu batu Putih. Wilayah Hitam di kanan kini hampir sepenuhnya aman.",
        "239": "Hitam 239 (A6) memakan satu batu dan ko muncul di tepi kiri. Perebutan poin demi poin berlanjut sampai akhir.",
        "260": "Putih 260 (T6) memakan satu batu dan membuat ko lagi di tepi kanan bawah. Hitam membalas di 263 (T5).",
        "267": "Permainan selesai setelah 267 langkah: Hitam menang 11 poin. Tanpa petualangan — Shūsaku menyerang dan membiarkan wilayahnya tumbuh wajar, kemenangan khas dirinya. Inilah yang pertama dari 19 kemenangan beruntunnya di Permainan Kastel."
      } },
    "shilin": { "t": "Partai dari Shilin Guangji", "w": "Merah (nama tidak tercatat)", "b": "Hitam (nama tidak tercatat)", "ev": "Ensiklopedia sehari-hari Shilin Guangji: “partai yang dimenangkan setelah memberi langkah pertama, meriam sisi yang sama”", "d": "Abad ke-13", "pl": "Tiongkok (Song–Yuan)", "lead": "Catatan ini berasal dari Shilin Guangji, ensiklopedia kehidupan sehari-hari yang disusun Chen Yuanjing pada akhir Dinasti Song hingga awal Yuan. Catatan ini disebut sebagai salah satu catatan partai xiangqi lengkap tertua yang masih ada. Ini adalah partai contoh ketika pihak yang lebih kuat memberi langkah pertama, dan hanya dalam sembilan langkah kuda hitam menjebak kereta merah.",
      c: {
        "0": "Catatan ini berumur lebih dari 700 tahun, dari masa antara Dinasti Song dan Yuan. Catatan ini ada di bab permainan ensiklopedia Shilin Guangji dan disebut sebagai salah satu partai xiangqi lengkap tertua yang masih kita miliki. Nama para pemainnya tidak tercatat. Judulnya mengatakan pemain kuat “memberikan langkah pertama” kepada yang lebih lemah, jadi ini pelajaran yang menunjukkan bagaimana Merah, yang melangkah lebih dulu, kalah. Merah di bawah dan mulai lebih dulu.",
        "1": "Merah memindahkan meriam kanan ke lajur tengah. Ini disebut Meriam Tengah, langsung membidik jenderal hitam, dan sampai sekarang masih salah satu pembukaan terkuat. Ternyata pembukaan ini sudah dimainkan 700 tahun lalu.",
        "2": "Hitam juga memindahkan meriam ke tengah, sehingga dua meriam saling berhadapan. Jika kedua pihak menggerakkan meriam di sisi yang sama, namanya “meriam searah”. Duel meriam sudah populer selama berabad-abad.",
        "3": "Merah mengeluarkan kuda untuk menjaga prajurit tengah. Prajurit itu sedang dibidik meriam hitam dan perlu penjaga. Kuda itu juga bersiap untuk maju.",
        "4": "Hitam melakukan hal yang sama dan menjaga prajurit tengahnya dengan kuda. Kedua pihak membangun pijakan yang kuat dulu.",
        "5": "Merah menggeser kereta kanan satu langkah ke samping, ke lajur terbuka. Kereta adalah bidak terkuat, jadi sebaiknya cepat dipakai.",
        "6": "Hitam mengeluarkan kuda yang lain dan membiarkan kereta tetap di rumah dulu. Rencananya memajukan bidak lebih dulu. Tetapi kereta yang keluar terlambat bisa sulit dipakai untuk menyerang nanti.",
        "7": "Kereta merah langsung menyeberangi sungai dan masuk ke daerah hitam. Ia ingin mengancam bidak hitam, tetapi bidak merah lainnya masih di rumah, jadi serangan ini agak terburu-buru. Mengeluarkan kuda atau kereta kiri lebih dulu juga mungkin.",
        "8": "Hitam memajukan prajurit di lajur 3 satu langkah. Ini membuka jalan bagi kuda agar bisa melompat maju nanti. Hitam seolah-olah mengundang kereta merah datang.",
        "9": "Kereta merah memakan seorang prajurit dan sekarang membidik kuda hitam di belakangnya. Mendapat satu bidak dan mengancam bidak lain terlihat hebat. Tetapi kereta itu maju terlalu jauh tanpa teman di sekitarnya. Kereta yang sendirian di daerah lawan mudah dikejar.",
        "10": "Kuda hitam melompat maju. Ia lari dari kereta sekaligus mendekati daerah merah: dua tugas dalam satu langkah. Kuda ini akan menjadi bintang partai ini.",
        "11": "Merah menarik kereta satu langkah untuk menyerang kuda dari samping. Kereta bisa memakan dari jauh, jadi kuda tidak bisa beristirahat. Namun langkah ini tetap tidak membantu bidak merah lainnya keluar.",
        "12": "Kuda hitam maju lagi dan menyeberangi sungai ke daerah merah. Setiap kali lari dari kereta, ia semakin dekat dengan jenderal merah.",
        "13": "Merah memajukan seorang prajurit untuk membuka jalan bagi kudanya sendiri. Idenya mengeluarkan kuda itu dan menukarnya dengan kuda hitam. Tetapi ini memberi Hitam waktu untuk maju lebih jauh.",
        "14": "Hitam menaikkan gajah dan menyerang kereta merah. Mengusir kereta lawan dengan bidak bertahan sangat efisien. Merah harus memindahkan kereta lagi, dan Hitam mendapat satu tempo lagi.",
        "15": "Kereta merah bergeser ke samping dan memakan prajurit lagi. Merah unggul dua prajurit, tetapi inilah langkah yang membuat kalah. Kereta kini jauh dari jenderalnya dan tidak bisa kembali untuk bertahan. Merah perlu berjaga dari kuda, misalnya dengan membawa kereta pulang.",
        "16": "Kuda hitam masuk lebih dalam dan menyerang kereta merah. Dan masih ada lagi: jika melompat sekali lagi, ia akan menskak jenderal merah dan sekaligus menyerang kereta di sudut merah. Satu kuda membuat dua ancaman sekaligus.",
        "17": "Merah mengejar kuda dengan kereta. Tetapi kuda itu sudah tidak bisa dihentikan. Di sekitar jenderal merah tidak ada lagi yang bisa membantu.",
        "18": "Kuda melompat masuk dengan skak! Ia juga menyerang kereta di sudut merah, jadi saat jenderal menghindar, kereta akan hilang. Hanya sembilan langkah, tetapi partai ini mengajarkan apa yang terjadi pada kereta yang maju sendirian, dan mengapa bidak harus berjuang bersama. 700 tahun lalu, para pemain sudah memikirkan hal yang sama di papan yang sama."
      } },
    "qima13": { "t": "Korban kuda tiga belas langkah (Juzhongmi)", "w": "Merah (nama tidak tercatat)", "b": "Hitam (nama tidak tercatat)", "ev": "Juzhongmi, jilid 1, partai 1", "d": "1632 (terbit)", "pl": "Tiongkok (Ming)", "lead": "Ini adalah partai paling pertama dalam Juzhongmi (“Rahasia di Dalam Jeruk”), buku xiangqi yang diterbitkan Zhu Jinzhen dari Dinasti Ming pada 1632. Merah membiarkan Hitam memakan kuda secara gratis, lalu menyerbu selagi Hitam sibuk, dan menskakmat dalam tiga belas langkah. Dengan nama “korban kuda tiga belas langkah”, partai ini masih disukai hampir 400 tahun kemudian.",
      c: {
        "0": "Ini partai 1 dari Juzhongmi, buku yang dicetak pada 1632 menjelang akhir Dinasti Ming. Bersama Buku Bunga Plum yang terbit kemudian, buku ini disebut salah satu dari dua karya klasik besar xiangqi. Ini bukan pertandingan sungguhan melainkan contoh untuk mengajarkan rencana, jadi tidak ada nama pemain. Merah di bawah dan mulai lebih dulu, dan semuanya selesai hanya dalam tiga belas langkah.",
        "1": "Merah memindahkan meriam kanan ke tengah. Inilah Meriam Tengah yang menatap langsung jenderal hitam. Juzhongmi terkenal karena meneliti cara menyerang dengan pembukaan ini.",
        "2": "Hitam juga memindahkan meriam di sisi yang sama ke tengah. Ini “meriam searah”, yang beradu langsung. Masing-masing membidik prajurit tengah lawan.",
        "3": "Merah mengeluarkan kuda untuk menjaga prajurit tengah. Kuda itu melindungi prajurit yang dibidik meriam hitam, sekaligus mulai bekerja.",
        "4": "Hitam juga menjaga prajurit tengah dengan kuda. Sampai di sini bentuk kedua pihak sama.",
        "5": "Merah memajukan kereta kanan hanya satu langkah. Sekarang pada langkah berikutnya kereta bisa berlari ke samping. Kereta yang bergerak ke samping seperti ini disebut “kereta mendatar”, dan bisa cepat pindah ke sayap mana pun.",
        "6": "Hitam menggeser kereta satu langkah ke samping agar bisa maju lurus. Ini “kereta lurus”. Kereta mendatar melawan kereta lurus: dua cara berbeda memakai kereta saling berhadapan.",
        "7": "Kereta mendatar merah berpindah ke lajur di kiri. Lajur itu berada tepat di samping penasihat hitam, tempat pertahanan lemah. Merah bersiap menerobos dari sini.",
        "8": "Kereta lurus hitam menyeberangi sungai dan masuk jauh ke daerah merah. Hitam ingin membalas dengan serangannya sendiri. Tetapi ini langkah yang terburu-buru menyerang sebelum bertahan.",
        "9": "Kereta merah masuk jauh ke dalam daerah hitam. Ia berdiri di “mata” gajah, titik yang harus dilewati gajah, sehingga gajah hitam tidak bisa bergerak. Tepat di samping penasihat, kini ia sangat dekat dengan jenderal.",
        "10": "Hitam mengeluarkan kuda lainnya ke tepi. Salah satu tujuannya mencegah kereta merah menyelinap dari samping.",
        "11": "Inilah korban kuda! Merah menaikkan kereta yang lain satu langkah. Akibatnya kuda di sudut kiri tidak punya penjaga, dan meriam hitam bisa memakannya gratis. Tetapi sebagai gantinya Merah mendapat waktu untuk segera memasukkan kedua kereta ke serangan.",
        "12": "Meriam hitam memakan kuda merah. Kelihatannya Hitam untung satu bidak. Tetapi meriam itu sekarang jauh dari rumah dan tidak bisa membantu bertahan. Konon di sini lebih baik menaikkan penasihat untuk memperkuat pertahanan daripada memakan kuda.",
        "13": "Meriam merah maju. Dengan memakai meriam tengah hitam sebagai “layar” untuk dilompati, ia membidik kuda hitam di belakangnya. Meriam adalah bidak unik yang memakan dengan melompati tepat satu bidak.",
        "14": "Hitam menarik kudanya untuk kabur. Tetapi kuda itu adalah bidak penting yang menjaga prajurit tengah. Dengan kabur, terbukalah lubang di tengah. Hitam punya cara bertahan lain, tetapi inilah pilihan terburuk.",
        "15": "Meriam merah memakan prajurit tengah — skak! Tanpa kuda hitam, bagian tengah terbuka lebar. Dari sini serangan merah melaju kencang.",
        "16": "Hitam menaikkan penasihat untuk menutup bagian depan jenderal. Ini satu-satunya cara yang baik untuk menahan skak.",
        "17": "Kereta merah kedua tiba di lajur yang sama. Dua kereta berjajar di satu lajur sangat kuat. Rencananya menembus sampai ke bagian terdalam daerah hitam.",
        "18": "Jenderal hitam menyingkir ke samping. Kalau tidak, ia akan langsung dibidik dua kereta merah di lajur yang sama.",
        "19": "Kereta merah yang di depan memakan penasihat hitam — skak! Kereta ini akan segera dimakan penasihat yang lain, tetapi itu bagian dari rencana. Merah mengorbankan kereta untuk menghancurkan penjaga jenderal hitam. Langkah yang sangat berani!",
        "20": "Hitam memakan kereta dengan penasihat. Dari jumlah bidak, Hitam jauh unggul. Tetapi rumah sang jenderal semakin kosong.",
        "21": "Kereta merah terakhir pindah ke lajur jenderal — skak lagi. Jenderal hitam hampir tidak punya bidak lagi untuk melindunginya.",
        "22": "Hitam menaruh meriam di depan jenderal untuk menutup skak. Menaruh bidak di antara seperti ini disebut menghalangi.",
        "23": "Kereta merah memakan meriam itu — skak lagi. Kereta terus memakan bidak hitam sambil menyudutkan jenderal.",
        "24": "Jenderal hitam hanya bisa kembali ke tengah. Semua titik lain dikuasai bidak merah.",
        "25": "Akhirnya meriam merah berdiri di tengah: dua meriam di satu lajur — skak. Meriam depan menjadi layar dan meriam belakang menghantam jenderal: skakmat “meriam ganda”. Jenderal hitam tidak punya tempat lari, dan Merah menang. Hanya dengan mengorbankan satu kuda, Merah menang dalam tiga belas langkah. Selama 400 tahun partai ini mengajarkan bahwa waktu dan keaktifan bidak bisa lebih penting daripada jumlah bidak."
      } }
  },
  "hi": {
    ui: {"lead":"महान बाज़ियाँ, एक-एक चाल करके। Musowl हर चाल समझाएगा, और आप बोर्ड पर मशहूर बाज़ियों को देखते चलिए।","all":"सभी","k_chess":"शतरंज","k_shogi":"शोगी","k_go":"गो","k_xiangqi":"शियांगची","side_r":"लाल","res_r":"लाल जीता","back":"महान बाज़ियों पर लौटें","start":"शुरुआत","prev":"एक चाल पीछे","next":"एक चाल आगे","end":"अंत","play":"अपने-आप चलाएँ","pause":"रोकें","moves":"चालें","move":"चाल {n}","startpos":"शुरुआती स्थिति","nextnote":"अगली टिप्पणी (चाल {n})","quiet":"इस चाल पर कोई टिप्पणी नहीं है।","guide":"Musowl","keys":"← → से एक-एक चाल","result":"नतीजा","r_event":"बाज़ी","r_date":"वर्ष","r_place":"स्थान","side_w":"सफ़ेद","side_b":"काला","side_s":"सेंते","side_g":"गोते","side_B":"काला","side_W":"सफ़ेद","res_w":"सफ़ेद जीता","res_b":"काला जीता","res_d":"ड्रॉ","res_s":"सेंते जीता","res_g":"गोते जीता","credit":"चालें हर बाज़ी का सार्वजनिक रिकॉर्ड हैं। टिप्पणियाँ संग्रहालय के Musowl ने लिखी हैं।"},
    "opera": { "t": "ओपेरा वाली बाज़ी", "w": "पॉल मॉर्फी", "b": "ब्रंसविक के ड्यूक कार्ल द्वितीय और काउंट इसुआर", "ev": "पेरिस ओपेरा के एक बॉक्स में खेली गई (दोनों साथी आपस में सलाह करके खेले)", "d": "1858", "pl": "फ़्रांस (पेरिस)", "lead": "ओपेरा के एक शो के दौरान युवा अमेरिकी चैंपियन ने दो रईसों के ख़िलाफ़ 17 चालों में यह बाज़ी खेली। मोहरों को जल्दी बाहर निकालो, बिना झिझक क़ुर्बान करो, और आख़िर में बहुत कम मोहरों से जीत लो। शतरंज की किताबों में इससे ज़्यादा कोई बाज़ी नहीं छपती।",
      c: {
        "0": "पेरिस, 1858। 21 साल के अमेरिकी पॉल मॉर्फी यूरोप के मज़बूत खिलाड़ियों को एक-एक करके हरा रहे थे। उस शाम ओपेरा के एक बॉक्स में ब्रंसविक के ड्यूक और काउंट इज़ुआर ने मिलकर काले मोहरे लिए और हर चाल पर सलाह करते हुए उन्हें चुनौती दी। कहा जाता है कि मॉर्फी मंच भी देखना चाहते थे, इसलिए बाज़ी जल्दी ख़त्म करना चाहते थे। इन 17 चालों में शतरंज की बुनियादी बातें भरी हैं: मोहरे जल्दी निकालो और राजा को सुरक्षित करो।",
        "1": "सफ़ेद राजा का प्यादा दो ख़ाने बढ़ाता है। यह बीच के d5 और e5 पर नज़र रखता है और ऊँट व वज़ीर का रास्ता खोलता है।",
        "2": "काला भी e5 चलता है। प्यादे बीच में आमने-सामने हैं, और सफ़ेद प्यादा आगे नहीं बढ़ सकता।",
        "3": "घोड़ा f3 पर आकर e5 के प्यादे पर हमला करता है। अच्छी चाल: मोहरा भी निकला और विरोधी को बचाव की सोचनी पड़ी।",
        "4": "काला d6 से e5 बचाता है। इसे फ़िलिडोर डिफ़ेंस कहते हैं। मज़बूत है, पर f8 के ऊँट का रास्ता थोड़ा तंग हो जाता है।",
        "5": "सफ़ेद d4 चलता है: बीच में एक और प्यादा, e5 के ख़िलाफ़। काले को लेना या बचाना तय करना है।",
        "6": "काला ऊँट g4 पर जाता है। वह f3 के घोड़े पर दबाव डालता है, जो d1 के सफ़ेद वज़ीर की सीध में है। घोड़ा हटा तो वज़ीर जाएगा, इसलिए घोड़ा e5 लेने नहीं जा सकता।",
        "7": "सफ़ेद प्यादे से e5 लेता है। अगर काला तुरंत d6 के प्यादे से वापस ले, तो सफ़ेद वज़ीर बदल लेगा और फिर घोड़ा e5 का प्यादा ले लेगा। इसलिए काला पहले f3 का घोड़ा हटाना चाहता है।",
        "8": "काला ऊँट से घोड़ा लेता है। अब e5 आराम से वापस लिया जा सकता है। पर अभी-अभी निकले ऊँट को घोड़े से बदलने पर काला मोहरे निकालने में पिछड़ जाता है।",
        "9": "सफ़ेद वज़ीर से वापस लेता है। सफ़ेद वज़ीर अभी से बीच के पास काम कर रहा है, जबकि काले ने लगभग कोई मोहरा नहीं निकाला।",
        "10": "काला प्यादे से वापस लेता है, मोहरे बराबर। पर बाहर निकले मोहरों में सफ़ेद आगे है।",
        "11": "ऊँट c4 पर। f3 के वज़ीर के साथ मिलकर f7 पर निशाना। f7 को सिर्फ़ राजा बचाता है, यह कमज़ोर ख़ाना है: इसे लेना मात होगी।",
        "12": "काला घोड़ा f6 पर लाकर f लाइन बंद करता है। इसके बिना वज़ीर f7 लेकर मात कर देता। मोहरा निकालते हुए बचाव करना सही जवाब है।",
        "13": "वज़ीर मुड़कर b3 पर जाता है और एक साथ f7 और b7 पर हमला करता है। दो ख़तरों वाली चाल ताक़तवर होती है, क्योंकि विरोधी दोनों को नहीं बचा सकता।",
        "14": "काला वज़ीर को e7 पर लाकर f7 बचाता है और b7 छोड़ देता है। पर अब वज़ीर f8 के ऊँट का रास्ता रोक रहा है।",
        "15": "मॉर्फी b7 का प्यादा नहीं लेते; घोड़ा निकालते हैं। लेने पर वज़ीर बहुत दूर चला जाता। प्यादे के बजाय तेज़ी से मोहरे निकालना मॉर्फी की पहचान है।",
        "16": "काला c6 चलता है: d5 और b5 पर क़ाबू, और वज़ीर के लिए b6 का रास्ता खुला।",
        "17": "ऊँट g5 पर जाकर f6 के घोड़े को बाँध देता है। घोड़ा हटा तो पीछे e7 का वज़ीर चला जाएगा। काले मोहरों का हिलना मुश्किल होता जा रहा है।",
        "18": "काला c4 के ऊँट को भगाने के लिए b5 चलता है। वज़ीर की तरफ़ जगह मिलती है, पर सफ़ेद मोहरों के घुसने के लिए दरार भी खुल जाती है।",
        "19": "घोड़ा क़ुर्बान करके b5 लिया! ऊँट पीछे हटाने के बजाय मॉर्फी हमला जारी रखते हैं। काला राजा अब भी बीच में है, यह काले के लिए बहुत ख़तरनाक है।",
        "20": "काला घोड़ा लेता है और एक घोड़ा आगे हो जाता है। पर उसका राजा अब भी e8 पर है, और सफ़ेद मोहरे आते जा रहे हैं।",
        "21": "ऊँट b5 पर, शह! काला राजा अब भी बीच में फँसा है। सफ़ेद के पास घोड़े के बदले दो प्यादे हैं और वह सीधे राजा की ओर बढ़ता है।",
        "22": "काला d7 पर घोड़ा रखकर शह रोकता है। पर यह घोड़ा बँधा हुआ है: हिला तो काले राजा पर शह। अब सफ़ेद d7 पर निशाना लगाएगा।",
        "23": "सफ़ेद वज़ीर की तरफ़ कैसलिंग करता है। राजा सुरक्षित, और साथ ही हाथी d1 पर आकर d7 को देखता है। एक चाल से बचाव भी और हमला भी: शानदार।",
        "24": "काला d7 बचाने के लिए हाथी d8 पर लाता है। वह अब भी कैसलिंग नहीं कर सकता, और h8 का हाथी व f8 का ऊँट कुछ नहीं कर रहे।",
        "25": "हाथी क़ुर्बान करके d7 लिया! सफ़ेद एक हाथी देकर काले के एक बचाव करने वाले मोहरे को हटाता है।",
        "26": "काला हाथी से वापस लेता है। अब d7 का यह हाथी भी बँधा है: हिला तो b5 का ऊँट काले राजा को शह देगा।",
        "27": "दूसरा हाथी d1 पर आकर फिर d7 पर हमला करता है। अब d7 पर हमला करने वाले सफ़ेद मोहरे बचाने वाले काले मोहरों से ज़्यादा हैं।",
        "28": "काला वज़ीर e6 पर जाता है, b3 के वज़ीर को हटाने के लिए वज़ीरों की अदला-बदली की पेशकश करता है और d7 की मदद चाहता है। पर अब देर हो चुकी है।",
        "29": "ऊँट d7 लेकर शह देता है। सफ़ेद काले के बचाव वाले मोहरों को एक-एक करके हटा रहा है।",
        "30": "काला घोड़े से वापस लेता है। f6 का घोड़ा हटने से g5 के ऊँट से d8 तक की तिरछी लाइन खुल गई। यही लाइन आख़िर में काम आएगी।",
        "31": "वज़ीर b8 पर शह देकर क़ुर्बान! यह बाज़ी की सबसे मशहूर चाल है। काले को घोड़े से लेना ही पड़ता है, और घोड़ा d7 छोड़ते ही d लाइन खुल जाती है।",
        "32": "काला घोड़े से लेता है। अब d8 को बचाने वाला कोई काला मोहरा नहीं बचा।",
        "33": "हाथी d8 पर, शह और मात! g5 का ऊँट d8 को सहारा देता है, और काला राजा अपने ही मोहरों से घिरा है, भाग नहीं सकता। सफ़ेद ने वज़ीर, हाथी और ऊँट दिए और आख़िर में सिर्फ़ एक हाथी और एक ऊँट से जीत ली। जल्दी मोहरे निकालो, राजा को सुरक्षित करो, और जब विरोधी राजा बीच में हो तभी हमला करो: यह मशहूर बाज़ी इन सब ज़रूरी बातों को एक साथ दिखाती है।"
      } },
    "reti1910": { "t": "रेटी की मात", "w": "रिचर्ड रेटी", "b": "सावियेली टार्टाकोवर", "ev": "एक दोस्ताना बाज़ी (टूर्नामेंट नहीं)", "d": "1910", "pl": "ऑस्ट्रिया (वियना)", "lead": "आगे चलकर महान खिलाड़ी बनने वाले दो लोग, वियना में एक दोस्ताना बाज़ी, 11 चालें। सफ़ेद अपना वज़ीर दे देता है और दोहरी शह से बाज़ी ख़त्म करता है: दो मोहरे एक साथ शह देते हैं। मात के इस रूप का नाम सफ़ेद के नाम पर है: रेटी की मात।",
      c: {
        "0": "वियना, 1910। सफ़ेद से 20 साल के रिचर्ड रेटी, काले से सावियेली टार्टाकोवर। दोनों आगे चलकर दुनिया के सबसे अच्छे खिलाड़ियों में गिने गए और शतरंज में नए विचार लाने के लिए जाने जाते हैं। यह टूर्नामेंट की नहीं, बल्कि छोटी-सी शर्त पर खेली गई दोस्ताना बाज़ी थी। छोटी है, पर साफ़ दिखाती है कि राजा को जल्दी सुरक्षित करना क्यों ज़रूरी है।",
        "1": "सफ़ेद राजा का प्यादा दो ख़ाने बढ़ाता है। बीच पर क़ब्ज़ा करने से पीछे के मोहरे आसानी से निकलते हैं। ऊँट और वज़ीर का रास्ता भी खुल गया।",
        "2": "काला c6 चलता है। तुरंत बीच में जाने के बजाय वह d5 से e4 के प्यादे पर हमले की तैयारी करता है। इस मज़बूत शुरुआत को कैरो-कान डिफ़ेंस कहते हैं।",
        "3": "सफ़ेद दूसरा प्यादा भी d4 पर रखता है। बीच में दो प्यादे साथ-साथ: सफ़ेद के पास बहुत जगह है। काला इन्हें तोड़ने की कोशिश करेगा।",
        "4": "योजना के मुताबिक़ d5. प्यादा e4 को चुनौती देता है: \"मैं तुम्हें ले सकता हूँ।\" सफ़ेद को तय करना है कि बचाए, आगे बढ़ाए या बदले।",
        "5": "सफ़ेद e4 बचाने के लिए घोड़ा निकालता है। मोहरा भी निकला और बचाव भी हुआ, समय बर्बाद नहीं।",
        "6": "काला e4 का प्यादा ले लेता है। बीच के प्यादे बदलकर वह सफ़ेद के बीच को छोटा करता है।",
        "7": "सफ़ेद घोड़े से वापस लेता है, और घोड़ा बोर्ड के बीच में आ जाता है। बीच का घोड़ा कई ख़ानों तक पहुँचता है और बहुत ताक़तवर होता है।",
        "8": "काला e4 के घोड़े के सामने घोड़ा निकालता है। यहाँ अक्सर ऊँट f5 पर चलते हैं, पर काला घोड़ों की अदला-बदली का न्योता देता है।",
        "9": "वज़ीर जल्दी d3 पर आकर e4 के घोड़े को बचाता है। आम तौर पर वज़ीर इतनी जल्दी नहीं निकालते, पर सफ़ेद के पास योजना है। याद रखना, यह वज़ीर d लाइन पर काले राजा के सामने खड़ा है।",
        "10": "काला e5 चलता है और ऊँट व वज़ीर के लिए रास्ता खोलने को एक प्यादा देता है। बीच में लड़ाई छेड़ने वाली सक्रिय चाल।",
        "11": "सफ़ेद e5 का प्यादा लेता है। तोहफ़ा ले लिया, पर इससे काले वज़ीर को ज़्यादा आज़ादी मिल गई।",
        "12": "शह! a5 का काला वज़ीर तिरछे e1 के राजा पर निशाना लगाता है। साथ ही वह e5 का प्यादा वापस लेना चाहता है: एक चाल में दो काम। सफ़ेद को बीच में कुछ रखना होगा।",
        "13": "सफ़ेद d2 पर ऊँट रखकर शह रोकता है। वज़ीर ऊँट ले सकता था, पर सफ़ेद वज़ीर उसे अच्छी तरह बचा रहा है।",
        "14": "काले ने प्यादा वापस ले लिया, मोहरे फिर बराबर। और यह वज़ीर e लाइन पर सीधे e4 के घोड़े और उसके पीछे के राजा को देख रहा है। घोड़ा हटा तो राजा पर शह आएगी, इसलिए घोड़ा बँधा हुआ है। लगता है काला उसे जल्द जीत लेगा।",
        "15": "सफ़ेद वज़ीर की तरफ़ कैसलिंग करता है। राजा e लाइन से हटता है, और घोड़ा फिर आज़ाद। साथ ही हाथी d1 पर आता है: d1 का हाथी, d3 का वज़ीर और काले राजा के पास का d8 एक लाइन में हैं। यही सफ़ेद का जाल है।",
        "16": "काला e4 का घोड़ा ले लेता है और लगता है एक मोहरा जीत गया। पर काला राजा अब भी e8 पर है और उसने कैसलिंग नहीं की। सफ़ेद मोहरे d लाइन पर जमे हैं और काला राजा बिना सुरक्षा के है। बाज़ी हराने वाली यही चाल निर्णायक मोड़ है।",
        "17": "वज़ीर d8 पर, शह! सफ़ेद अपना सबसे ताक़तवर मोहरा मुफ़्त में देता है। उसे लेने वाला अकेला काला मोहरा राजा है। लेने देकर सफ़ेद राजा को ख़तरनाक d8 ख़ाने पर खींच लाता है।",
        "18": "काले को राजा से लेना ही पड़ता है; शह से बचने का कोई और रास्ता नहीं। राजा d8 पर है, और पीछे d1 का हाथी इंतज़ार कर रहा है।",
        "19": "ऊँट d2 से g5 पर शह देते हुए जाता है और साथ ही d1 के हाथी का रास्ता खोलता है, जो d लाइन पर शह देता है। दो मोहरों की एक साथ शह: दोहरी शह। इसे न एक मोहरा लेकर रोका जा सकता है न बीच में कुछ रखकर; राजा को भागना ही होगा।",
        "20": "राजा c7 पर भागता है। e8 पर जाता तो हाथी d8 पर आकर मात कर देता। राजा कहीं भी जाए, सफ़ेद का आख़िरी वार तैयार है।",
        "21": "ऊँट d8 पर: c7 के राजा को तिरछी लाइन से शह और मात! ऊँट को d1 का हाथी बचा रहा है, इसलिए राजा उसे नहीं ले सकता। b8, c8, b7 और c6 जैसे ख़ाने काले के अपने मोहरों से भरे हैं, और हाथी d6 व d7 पर नज़र रखता है। सिर्फ़ 11 चालों में सफ़ेद ने वज़ीर देकर दो छोटे मोहरों से जीत ली। यह बाज़ी सिखाती है कि कैसलिंग से पहले मोहरे बटोरना कितना ख़तरनाक है। कुछ रिकॉर्ड कहते हैं कि काले ने एक चाल पहले हार मान ली थी।"
      } },
    "immortal": { "t": "अमर बाज़ी", "w": "एडॉल्फ़ एंडरसन", "b": "लियोनेल कीज़ेरित्स्की", "ev": "लंदन 1851 टूर्नामेंट के बीच ख़ाली समय में खेली गई अनौपचारिक बाज़ी", "d": "1851", "pl": "यूनाइटेड किंगडम (लंदन)", "lead": "लंदन में दुनिया के पहले अंतरराष्ट्रीय शतरंज टूर्नामेंट के दौरान, एक ब्रेक में खेली गई बाज़ी। सफ़ेद एक ऊँट, दोनों हाथी और आख़िर में वज़ीर भी दे देता है, और बचे हुए तीन छोटे मोहरों से मात करता है। कहा जाता है कि काले ने अंत से पहले हार मान ली थी, और आख़िरी कुछ चालें सफ़ेद ने दिखाई थीं।",
      c: {
        "0": "लंदन, 1851। टूर्नामेंट के ब्रेक में जर्मनी के एंडरसन (सफ़ेद) और पेरिस के मशहूर खिलाड़ी कीज़ेरित्स्की (काला) ने दोस्ताना बाज़ी खेली।",
        "1": "सफ़ेद राजा के आगे का प्यादा दो ख़ाने बढ़ाता है।",
        "2": "काला भी वैसा ही करता है।",
        "3": "f4! सफ़ेद एक प्यादा देने की पेशकश करता है: इसे किंग्स गैम्बिट कहते हैं। मक़सद है काले के e5 प्यादे को बीच से हटाना।",
        "4": "काला प्यादा ले लेता है।",
        "5": "ऊँट बाहर आता है और काले राजा के पास f7 पर नज़र रखता है।",
        "6": "शह! सफ़ेद का f प्यादा हटने से h4 से e1 तक तिरछा रास्ता खुला था।",
        "7": "राजा एक तरफ़ हटता है। अब सफ़ेद कभी कैसलिंग नहीं कर सकता।",
        "8": "काला भी एक प्यादा देता है, ताकि ऊँट को b5 पर खींच सके।",
        "9": "सफ़ेद ले लेता है।",
        "10": "घोड़ा निकलकर e4 के प्यादे पर हमला करता है।",
        "11": "सफ़ेद भी घोड़ा निकालता है और h4 के वज़ीर को भगाता है।",
        "12": "वज़ीर h6 पर लौटता है।",
        "13": "d3 से e4 सुरक्षित होता है और c1 के ऊँट का रास्ता खुलता है।",
        "14": "घोड़ा h5 पर। योजना है g3 पर कूदकर शह देना और h1 के हाथी पर हमला करना।",
        "15": "सफ़ेद घोड़ा h4 पर, ताकि f5 पर कूदकर काले वज़ीर को परेशान कर सके।",
        "16": "काला वज़ीर g5 पर जाकर h4 के घोड़े पर हमला करता है।",
        "17": "घोड़ा f5 पर, जिसे e4 का प्यादा बचा रहा है। वह g7 के प्यादे को भी देख रहा है।",
        "18": "c6 से b5 के ऊँट को भगाने की कोशिश।",
        "19": "सफ़ेद ऊँट को नहीं बचाता; g4 से h5 के घोड़े को भगाता है।",
        "20": "घोड़ा f6 पर लौटता है।",
        "21": "हाथी g1 पर, g4 के प्यादे को बचाता है। b5 का ऊँट चला जाए तो भी ठीक। बड़ी हिम्मत वाली चाल!",
        "22": "काला ऊँट ले लेता है और एक मोहरा आगे हो जाता है।",
        "23": "h प्यादा काले वज़ीर का पीछा करने लगता है।",
        "24": "वज़ीर g6 पर।",
        "25": "h5 फिर वज़ीर को भगाता है।",
        "26": "वज़ीर सिर्फ़ g5 पर लौट सकता है। उसके ख़ाने कम होते जा रहे हैं।",
        "27": "सफ़ेद वज़ीर f3 पर। अगर फिर ऊँट f4 पर ले, तो काला वज़ीर फँस सकता है।",
        "28": "काला घोड़े को g8 पर वापस ले जाता है ताकि वज़ीर f6 पर भाग सके।",
        "29": "ऊँट f4 का प्यादा लेकर वज़ीर पर हमला करता है।",
        "30": "वज़ीर f6 पर भागता है।",
        "31": "घोड़ा निकलता है; d5 पर कूदकर वज़ीर पर हमला करने की सोच है।",
        "32": "ऊँट निकलकर g1 के हाथी पर निशाना लगाता है।",
        "33": "घोड़ा d5 पर, f6 के वज़ीर और c7 ख़ाने पर हमला। g1 का हाथी जाए तो जाए।",
        "34": "वज़ीर b2 का प्यादा लेकर a1 के हाथी पर हमला करता है।",
        "35": "ऊँट d6 पर! सफ़ेद दोनों हाथी जाने देता है। बदले में उसके मोहरे काले राजा के चारों ओर जाल बुनते हैं।",
        "36": "काला g1 का हाथी ले लेता है।",
        "37": "e5! यह प्यादा b2 के वज़ीर से g7 तक का तिरछा रास्ता बंद कर देता है। काला वज़ीर अब राजा की मदद को नहीं आ सकता।",
        "38": "काला शह देते हुए दूसरा हाथी भी ले लेता है।",
        "39": "राजा e2 पर। सफ़ेद के पास बस वज़ीर, दो घोड़े और एक ऊँट बचे हैं।",
        "40": "घोड़ा a6 पर जाकर c7 को बचाता है। कहा जाता है कि काले ने लगभग यहीं हार मान ली, और आगे की चालें सफ़ेद ने दिखाईं।",
        "41": "घोड़ा g7 पर लेकर शह देता है।",
        "42": "राजा d8 पर भागता है।",
        "43": "वज़ीर f6 पर शह देकर क़ुर्बान! आख़िरी बड़ा मोहरा भी गया।",
        "44": "काले को घोड़े से लेना ही पड़ता है।",
        "45": "ऊँट e7 पर, शह और मात! d5 का घोड़ा e7 और c7 को, g7 का घोड़ा e8 को रोकता है। सफ़ेद सिर्फ़ एक ऊँट और दो घोड़ों से जीतता है।"
      } },
    "mimiaka": { "t": "लाल कानों वाली बाज़ी", "w": "होन्इनबो शूसाकु", "b": "इनोए गेनान इनसेकी", "ev": "ओसाका में खेली गई बाज़ी (तीन दिन में)", "d": "1846", "pl": "जापान (ओसाका)", "lead": "17 साल के शूसाकु (4-दान) ने उस समय के सबसे मज़बूत खिलाड़ियों में से एक गेनान (8-दान) से मुक़ाबला किया। कहा जाता है कि 127वीं चाल देखकर गेनान के कान लाल हो गए थे। तब कोमी नहीं था: काला 2 अंक से जीता।",
      c: {
        "0": "ओसाका, 1846। शूसाकु काले से और गेनान सफ़ेद से। एक दिन पहले दो पत्थरों की छूट वाली बाज़ी शुरू हुई थी, पर बीच में रुक गई; इस बार शूसाकु बिना छूट के काले से खेलता है।",
        "1": "काले की 1 ऊपर दाएँ 3-4 बिंदु (R16) पर। यहाँ से कोना आसानी से पक्का होता है।",
        "2": "सफ़ेद की 2 ऊपर बाएँ 3-4 बिंदु (D17) पर। पहले खाली कोने बाँटे जाते हैं।",
        "5": "1, 3 और 5 से काले ने तीनों कोने 3-4 बिंदुओं पर लिए। यह शूसाकु की पसंदीदा शुरुआत थी, जिसे बाद में बहुत पढ़ा गया।",
        "6": "सफ़ेद की 6 बाईं ओर C14 पर। काले के कोने के पास जाने के बजाय किनारे पर जमता है — थोड़ा असामान्य।",
        "7": "काले की 7 (E4) से नीचे बायाँ कोना दूसरे पत्थर से बंद हो गया। यह “घेराबंदी” कोने को बहुत मज़बूत बनाती है।",
        "8": "सफ़ेद की 8 (R5) काले के Q3 वाले कोने के पास आती है। नीचे दाईं ओर बड़ी लड़ाई शुरू होने वाली है।",
        "10": "सफ़ेद की 10 (O4) “ताइशा” कहलाती है: यह काले पत्थर को दूर से तिरछा ढकती है। इसके बहुत सारे रूप हैं, और यह गेनान की पसंदीदा चाल थी।",
        "11": "11 (Q5) से काला एक कठिन रास्ते पर जाता है। गेनान ताइशा को बहुत अच्छी तरह जानता था, इसलिए सावधानी ज़रूरी है।",
        "24": "नीचे दाईं ओर पत्थर उलझ गए हैं; दोनों एक-दूसरे को काटना चाहते हैं। सफ़ेद 24 (N4) के बाद काले पत्थरों का बाहर निकलना कठिन है।",
        "25": "काले की 25 (N3)। बाद के अध्ययन कहते हैं कि यहाँ बेहतर चाल थी। किसी उस्ताद के लिए भी यह कठिन जगह थी।",
        "28": "28 (M3) और 30 (L2) से सफ़ेद तुरंत कमज़ोरी पर वार करता है। काले पत्थर नीचे छोटी जगह में बंद हो सकते हैं।",
        "31": "काले की 31 (M4) अहम है। यह आने वाले “को” (बार-बार पकड़ने-छुड़ाने की लड़ाई) की तैयारी है: ऐसी धमकियाँ बनाती है जिनका सफ़ेद को जवाब देना पड़ेगा।",
        "36": "सफ़ेद की 36 (N2)। “को” शुरू करने से पहले सफ़ेद पहले यहाँ खेलता है। सही समय।",
        "40": "सफ़ेद की 40 (R1) एक पत्थर पकड़ती है और “को” शुरू होता है। जिसका पत्थर गया, वह तुरंत वापस नहीं पकड़ सकता; पहले कहीं और धमकी देता है।",
        "41": "काले की 41 (O5) “को” की धमकी है। थोड़ा नुकसान है, पर यहाँ इससे बेहतर कुछ नहीं।",
        "53": "काले की 53 (R10) एक अनोखा विचार है जो कम लोग सोच पाते। यह दाईं ओर सफ़ेद की बनावट पर चोट करती है।",
        "60": "सफ़ेद की 60 (S3) बड़ी चाल है। इससे सफ़ेद 62 (M1) भी पहल रखते हुए खेल पाता है।",
        "63": "काले की 63 (O1) के बाद नीचे दाईं ओर की लंबी लड़ाई थमती है। सफ़ेद के पास नीचे इलाक़ा है, काले के पास दाईं ओर मोटी दीवार। अभी तक सफ़ेद बेहतर लगता है।",
        "67": "काले की 67 (L17)। दाईं दीवार के सहारे काला ऊपर बड़ा ढाँचा बनाता है।",
        "72": "सफ़ेद की 72 (P13) शानदार चाल है। काली दीवार के ठीक ऊपर रखा पत्थर काले ढाँचे को बढ़ने से रोकता है।",
        "74": "यहाँ से लगभग 100वीं चाल तक गेनान एक भी ढीली चाल नहीं चलता। वह हमलों से बचता है और अपने पत्थर जोड़े रखता है।",
        "83": "काले की 83 (H3) नीचे सफ़ेद के इलाक़े में घुसकर उसे छोटा करने की कोशिश है।",
        "96": "सफ़ेद 96 (R14) से ऊपर दाएँ काले कोने के आसपास बारीक लड़ाई चलती है। सफ़ेद यहाँ भी अच्छी बनावट पाता है।",
        "107": "काले की 107 (P10) सफ़ेद का एक पत्थर पकड़ती है। दाईं ओर का काला समूह अब सुरक्षित है।",
        "118": "सफ़ेद की 118 (M19) एक पत्थर पकड़ती है और ऊपर का सफ़ेद समूह भी जी जाता है। ऊपर काले का ढाँचा उम्मीद से छोटा रह जाता है।",
        "126": "सफ़ेद की 126 (J5)। नीचे सफ़ेद मज़बूत है और बीच की ओर बढ़ रहा है। कहा जाता है कि देख रहे ज़्यादातर पेशेवर सफ़ेद को आगे मानते थे।",
        "127": "यही है मशहूर “लाल कानों वाली चाल”, काले की 127 (K11)। कहा जाता है कि बीच का यह एक पत्थर चारों दिशाओं में एक साथ काम करता है: ऊपर काले का इलाक़ा बढ़ाता है, नीचे सफ़ेद की मज़बूती घटाता है, दाईं ओर काले समूह की मदद करता है और सफ़ेद को बाईं ओर फैलने से रोकता है।",
        "128": "उसी समय बाज़ी देख रहे एक डॉक्टर ने देखा कि गेनान के कान लाल हो गए हैं। वह गो ज़्यादा नहीं जानता था, पर कहा जाता है कि उसने इसे घबराहट का संकेत मानकर काले की जीत का अंदाज़ा लगाया।",
        "131": "काले की 131 (D10)। अब काला बाईं ओर सफ़ेद के इलाक़े में भी घुसता है और पूरे बोर्ड पर सफ़ेद का इलाक़ा घटाता है।",
        "147": "काले की 147 (K10)। 127वीं चाल का पत्थर काम आने लगता है: काला बीच में सफ़ेद समूहों के बीच से आगे बढ़ता है।",
        "160": "सफ़ेद की 160 (H8)। सफ़ेद बीच के पत्थर बचाते हुए नीचे बाएँ काले समूह पर नज़र रखता है। मुक़ाबला अब भी क़रीबी है।",
        "167": "काले की 167 (C2) सटीक है। नीचे बाएँ कोने के काले पत्थर सुरक्षित हो गए, सफ़ेद की धमकी ख़त्म।",
        "175": "काले की 175 (G4) सफ़ेद का एक पत्थर पकड़ती है। नीचे सफ़ेद का इलाक़ा उतना बड़ा नहीं जितना लगता था।",
        "199": "काले की 199 (K7)। बीच की लड़ाई थमती है और अंतिम चरण शुरू होता है: सीमाएँ तय करना, जहाँ हर अंक मायने रखता है।",
        "212": "212 (D19) और 216 (F19) से सफ़ेद ऊपरी किनारे पर काले पत्थर पकड़ता है। अंत में कोई पीछे नहीं हटता।",
        "228": "सफ़ेद की 228 (N12) बीच में “को” बनाती है। 80 से ज़्यादा चालों तक M13 और N13 पर बारी-बारी पकड़ना चलता है।",
        "236": "सफ़ेद की 236 (T8), “को” के दौरान, एक पत्थर पकड़ती है। कुछ विश्लेषकों के अनुसार यहाँ “को” ख़त्म करने से अंतर और कम होता।",
        "275": "काले की 275 (T14) सफ़ेद के दो पत्थर पकड़ती है। “को” के दौरान दोनों बोर्ड पर कहीं फ़ायदा, कहीं नुकसान उठाते हैं।",
        "299": "काले की 299 (J16) एक साथ सफ़ेद के चार पत्थर पकड़ती है। ऊपर का हिस्सा काला मज़बूती से रखता है।",
        "311": "काले की 311 (M13) “को” को बंद करती है। लंबी लड़ाई आख़िर ख़त्म होती है।",
        "325": "325 चालों पर बाज़ी ख़त्म होती है और गिनती में काला 2 अंक आगे है। कोमी न होने पर भी 17 साल के लड़के का गेनान जैसे खिलाड़ी को हराना सनसनी बना, और शूसाकु का नाम मशहूर हो गया।"
      } },
    "evergreen": { "t": "सदाबहार बाज़ी", "w": "एडॉल्फ़ एंडरसन", "b": "ज़ाँ ड्यूफ़्रेन", "ev": "एक दोस्ताना बाज़ी (टूर्नामेंट नहीं)", "d": "1852", "pl": "जर्मनी (शायद बर्लिन)", "lead": "\"अमर बाज़ी\" वाले एंडरसन ने एक साल बाद यह दूसरी शानदार बाज़ी खेली। ठीक जब काला मात की धमकी देता है, सफ़ेद शांति से एक हाथी चलता है, फिर वज़ीर देकर दोहरी शह से बाज़ी ख़त्म करता है। यह कभी फीकी नहीं पड़ती, इसलिए इसे \"सदाबहार\" कहते हैं।",
      c: {
        "0": "1852 में एक पत्रिका में छपी बाज़ी। सफ़ेद एंडरसन, काला उनके दोस्त ड्यूफ़्रेन। माना जाता है कि यह बर्लिन में खेली गई, पर पक्का रिकॉर्ड नहीं है।",
        "1": "सफ़ेद राजा का प्यादा दो ख़ाने बढ़ाता है।",
        "2": "काला भी वैसा ही करता है।",
        "3": "घोड़ा e5 के प्यादे पर हमला करता है।",
        "4": "काला घोड़े से e5 बचाता है।",
        "5": "ऊँट निकलकर f7 को देखता है।",
        "6": "काला भी ऊँट निकालता है।",
        "7": "b4! प्यादा देने की यह पेशकश इवांस गैम्बिट कहलाती है। काला प्यादा ले, इतने में सफ़ेद बीच को मज़बूत करता है।",
        "8": "काला प्यादा ले लेता है।",
        "9": "c3 ऊँट को भगाता है और d4 की तैयारी करता है।",
        "10": "ऊँट a5 पर लौटता है।",
        "11": "d4 बीच पर क़ब्ज़ा करता है।",
        "12": "काला प्यादा ले लेता है।",
        "13": "सफ़ेद वापस नहीं लेता, कैसलिंग करता है। प्यादों से पहले राजा की सुरक्षा और मोहरों की सक्रियता।",
        "14": "काला प्यादा d3 तक बढ़ जाता है, सफ़ेद के इलाक़े में गहरे।",
        "15": "वज़ीर b3 पर। c4 के ऊँट के साथ f7 पर निशाना।",
        "16": "काला वज़ीर से f7 बचाता है।",
        "17": "e5 वज़ीर को भगाता है।",
        "18": "वज़ीर g6 पर।",
        "19": "हाथी e1 पर, e लाइन में आकर e5 के प्यादे को सहारा देता है।",
        "20": "काला कैसलिंग की तैयारी में घोड़ा निकालता है।",
        "21": "ऊँट a3 पर, तिरछी लाइन से e7 के घोड़े को देखता है। यह घोड़ा हटा तो ऊँट f8 तक पहुँचेगा, इसलिए काले के लिए राजा की तरफ़ कैसलिंग मुश्किल हो गई।",
        "22": "काला सफ़ेद के मोहरों को भटकाने के लिए एक प्यादा देता है।",
        "23": "वज़ीर ले लेता है।",
        "24": "हाथी b8 पर, b लाइन में वज़ीर का पीछा।",
        "25": "वज़ीर a4 पर।",
        "26": "ऊँट b6 पर लौटता है।",
        "27": "घोड़ा निकलता है। सफ़ेद के लगभग सारे मोहरे खेल में हैं।",
        "28": "काला दूसरा ऊँट निकालता है।",
        "29": "घोड़ा e4 पर, नज़र f6 पर।",
        "30": "काला वज़ीर f5 पर जाकर e4 के घोड़े पर हमला करता है।",
        "31": "ऊँट d3 का प्यादा लेता है और e4 के घोड़े को बचाता है।",
        "32": "वज़ीर h5 पर, f3 के घोड़े पर निशाना।",
        "33": "घोड़ा f6 पर शह देकर क़ुर्बान!",
        "34": "काला प्यादे से लेता है।",
        "35": "सफ़ेद प्यादे से वापस लेता है और e7 के घोड़े पर हमला करता है। e लाइन पर e1 का हाथी भी e7 को देख रहा है।",
        "36": "हाथी g8 पर, g2 पर निशाना। अगर h5 का वज़ीर f3 पर ले ले, तो मात बहुत क़रीब है।",
        "37": "हाथी चुपचाप d1 पर! सफ़ेद का राजा ख़तरे में है, पर बचाव के बजाय सफ़ेद d7 पर निशाना लगाता है। इसी चाल ने बाज़ी को \"सदाबहार\" बनाया।",
        "38": "काला f3 का घोड़ा लेता है। अगली चाल g2 पर लेना मात होगा।",
        "39": "पर पहले सफ़ेद की बारी है। हाथी e7 का घोड़ा लेकर शह देता है!",
        "40": "काला c6 के घोड़े से वापस लेता है। अब a4 से d7 तक का तिरछा रास्ता खुल गया।",
        "41": "वज़ीर d7 पर शह देकर क़ुर्बान!",
        "42": "काले को राजा से लेना ही पड़ता है।",
        "43": "ऊँट शह देते हुए f5 पर जाता है और d1 के हाथी के लिए d लाइन खोल देता है: दोहरी शह।",
        "44": "राजा e8 पर। c6 पर जाता तो ऊँट d7 पर मात कर देता।",
        "45": "ऊँट d7 पर, शह।",
        "46": "राजा f8 पर।",
        "47": "a3 का ऊँट e7 का घोड़ा लेता है: शह और मात! d7 का ऊँट e8 को, और f6 का प्यादा e7 और g7 को रोकता है।"
      } },
    "lasker1912": { "t": "राजा का शिकार", "w": "एडवर्ड लास्कर", "b": "जॉर्ज एलन थॉमस", "ev": "सिटी ऑफ़ लंदन चेस क्लब में तेज़ और दोस्ताना बाज़ी", "d": "1912", "pl": "यूनाइटेड किंगडम (लंदन)", "lead": "लंदन के एक क्लब में तेज़ और दोस्ताना बाज़ी। सफ़ेद वज़ीर देकर काले राजा को पूरे बोर्ड के पार, g8 से g1 तक खदेड़ता है। अलग-अलग रिकॉर्ड में शुरुआती चालों का क्रम थोड़ा अलग है, पर 10वीं चाल के बाद की स्थिति एक जैसी है।",
      c: {
        "0": "अक्टूबर 1912, सिटी ऑफ़ लंदन चेस क्लब। सफ़ेद से जर्मनी से अभी-अभी आए युवा इंजीनियर एडवर्ड लास्कर, काले से जॉर्ज एलन थॉमस, जो आगे चलकर ब्रिटेन के चैंपियन बने। यह तेज़ और दोस्ताना बाज़ी थी। यह \"राजा का शिकार\" के नाम से मशहूर है: काले राजा को g8 से बोर्ड के दूसरे छोर पर g1 तक खदेड़ा जाता है। लास्कर बाद में अमेरिका गए और अपनी शतरंज की किताबों से जाने गए।",
        "1": "सफ़ेद वज़ीर के प्यादे d4 से शुरू करता है। यह e5 और c5 पर क़ाबू रखता है और c1 के ऊँट का रास्ता खोलता है।",
        "2": "काला e6 चलता है: पहले मज़बूत ढाँचा, फिर f5 या d5 की तैयारी।",
        "3": "घोड़ा f3 पर। यह e5 पर क़ाबू रखता है और राजा की तरफ़ के बचाव में मदद करता है: सबसे स्वाभाविक ख़ाना।",
        "4": "काला f5 चलकर e4 पर क़ाबू करता है, डच डिफ़ेंस जैसा। पर राजा के आगे का प्यादा हिलाने से राजा थोड़ा कमज़ोर होता है।",
        "5": "दूसरा घोड़ा c3 पर आता है, ताकि e4 चलकर f5 के प्यादे से टकरा सके।",
        "6": "काला भी घोड़ा f6 पर निकालता है: e4 पर और क़ाबू, साथ ही कैसलिंग की तैयारी।",
        "7": "ऊँट g5 पर, f6 के घोड़े पर निशाना। यह घोड़ा काले राजा का अहम रक्षक है, इसलिए सफ़ेद उसे जल्दी हटाना चाहता है।",
        "8": "काला ऊँट को e7 पर रखकर घोड़े को बचाता है और कैसलिंग के क़रीब पहुँचता है।",
        "9": "सफ़ेद ऊँट को घोड़े से बदल लेता है। काले राजा को बचाने वाला घोड़ा चला गया।",
        "10": "काला ऊँट से वापस लेता है। अब f6 का ऊँट राजा की तरफ़ की रखवाली सँभालता है।",
        "11": "e4! सफ़ेद f5 के प्यादे से टकराता है और बीच में जगह बनाता है। रास्ते खुलते हैं और सफ़ेद मोहरे आसानी से चलते हैं।",
        "12": "काला e4 का प्यादा ले लेता है। न लेता तो सफ़ेद e5 चलकर काले मोहरों को पीछे धकेल देता।",
        "13": "घोड़ा वापस लेकर बीच में बैठता है, f6 के ऊँट और g5, d6 ख़ानों को देखता है।",
        "14": "काला b6 चलता है ताकि ऊँट b7 पर आकर लंबी तिरछी लाइन से e4 के घोड़े पर निशाना लगा सके।",
        "15": "घोड़ा e5 पर, बीच का मज़बूत ख़ाना, जहाँ से g4 और f7 भी दिखते हैं। दोनों सफ़ेद घोड़े अब काले राजा की तरफ़ के पास हैं।",
        "16": "काला कैसलिंग करता है। राजा g8 पर है। पर f प्यादा न होने से राजा के आसपास कई ख़ाली जगहें हैं।",
        "17": "ऊँट d3 पर। अभी e4 का अपना घोड़ा रास्ते में है, पर उसके पीछे h7 का प्यादा है। जैसे ही e4 का घोड़ा हटेगा, यह ऊँट सीधे h7 पर निशाना लगाएगा।",
        "18": "काला ऊँट b7 पर जाकर लंबी तिरछी लाइन से e4 के घोड़े को देखता है और सफ़ेद मोहरों को बाँधता है।",
        "19": "वज़ीर h5 पर, h7 के प्यादे पर निशाना, जिसे सिर्फ़ काला राजा बचा रहा है। सफ़ेद वज़ीर, ऊँट और घोड़े सब काले राजा की ओर हैं।",
        "20": "काला वज़ीर को e7 पर रखता है। यह f6 के ऊँट को बचाता है और c5 जाने की तैयारी करता है, पर काला सफ़ेद की योजना नहीं देखता। h6 या e5 का घोड़ा लेना ज़रूरी था। यही निर्णायक मोड़ है।",
        "21": "वज़ीर h7 पर शह देकर क़ुर्बान! सफ़ेद अपना सबसे ताक़तवर मोहरा मुफ़्त में देता है। लास्कर ने राजा को मात तक खदेड़ने का पूरा रास्ता देख लिया था।",
        "22": "काले को राजा से लेना ही पड़ता है; राजा h7 पर आ गया।",
        "23": "घोड़ा f6 का ऊँट लेकर शह देता है। साथ ही e4 ख़ाली हुआ, और d3 का ऊँट भी h7 के राजा को शह देता है: दोहरी शह। बीच में कुछ नहीं रखा जा सकता, राजा को भागना होगा।",
        "24": "राजा h6 पर। h8 पर जाता तो दूसरा घोड़ा g6 पर कूदकर मात कर देता। राजा आगे-आगे धकेला जा रहा है।",
        "25": "दूसरा घोड़ा e5 से g4 पर शह देते हुए कूदता है, h6 के राजा पर हमला कर उसे और आगे धकेलता है।",
        "26": "राजा g5 पर: अपना इलाक़ा छोड़कर सफ़ेद की तरफ़ बढ़ रहा है।",
        "27": "h प्यादे से शह! प्यादे भी शिकार में शामिल हैं। राजा को आगे बढ़ते रहना होगा।",
        "28": "राजा f4 पर। वह बोर्ड का बीच पार कर सफ़ेद के इलाक़े में घुस रहा है।",
        "29": "फिर शह, इस बार g प्यादे से। दो प्यादे राजा का लौटने का रास्ता बंद कर रहे हैं।",
        "30": "राजा f3 पर, सफ़ेद मोहरों के बीचोंबीच।",
        "31": "ऊँट d3 से e2 पर लौटकर शह देता है। राजा और गहराई में धकेला जाता है।",
        "32": "राजा g2 पर। e1 का सफ़ेद राजा अब दूर नहीं।",
        "33": "हाथी h2 पर, शह। आख़िरकार हाथी भी खेल में आया।",
        "34": "राजा आख़िर g1 पर पहुँचता है। g8 से चलकर वह बोर्ड के दूसरे छोर की पहली पंक्ति तक आ गया।",
        "35": "सफ़ेद राजा e1 से d2 पर जाता है। इससे a1 के हाथी का रास्ता खुलता है, जो पहली पंक्ति पर g1 के राजा को शह देता है: शह और मात! वज़ीर की तरफ़ कैसलिंग से भी मात होती, पर लास्कर ने राजा चला। एक तेज़ बाज़ी में वज़ीर देने के बाद सफ़ेद ने 14 चालों तक राजा को अपने ही इलाक़े के सबसे गहरे कोने तक खदेड़ा। बहुत ही दुर्लभ बाज़ी।"
      } },
    "toketsu": { "t": "ख़ून उगलने वाली बाज़ी", "w": "अकाबोशी इनतेत्सु", "b": "होन्इनबो जोवा", "ev": "सुओ के सामंत मात्सुदाइरा की हवेली में (चार दिन)", "d": "1835", "pl": "जापान (एदो)", "lead": "जापानी गो के सबसे ऊँचे पद “मेइजिन गोदोकोरो” की होड़ से जन्मी बाज़ी। इनोए गेनान इनसेकी ने अपने शिष्य अकाबोशी इनतेत्सु को मेइजिन जोवा के सामने उतारा। चार दिन की कड़ी लड़ाई के बाद इनतेत्सु हार गया, और कहा जाता है कि उसने बोर्ड के सामने ख़ून उगला।",
      c: {
        "0": "1835। काला: अकाबोशी इनतेत्सु (7-दान); सफ़ेद: मेइजिन होन्इनबो जोवा। गेनान ने अपना सबसे अच्छा शिष्य भेजा, ताकि कह सके कि 7-दान से हारने वाला मेइजिन पद के लायक़ नहीं।",
        "1": "काले की 1 नीचे बाएँ 3-4 बिंदु (C4) पर। इनतेत्सु शांति से शुरू करता है।",
        "4": "चार चालों के बाद हर कोने में एक पत्थर है: सफ़ेद नीचे दाएँ और ऊपर बाएँ, काला नीचे बाएँ और ऊपर दाएँ।",
        "6": "सफ़ेद की 6 (E3) अभी से नीचे बाएँ काले कोने के पास आती है। जोवा शुरू से सक्रिय है।",
        "10": "सफ़ेद की 10 (P4) नीचे दाएँ कोने को दूसरे पत्थर से बंद करती है।",
        "12": "सफ़ेद की 12 (D6) नीचे बाएँ काले कोने को ऊपर से दबाती है। बाज़ी की सबसे बड़ी लड़ाई यहीं से शुरू होती है।",
        "13": "काले की 13 (E4) सफ़ेद पत्थर से सीधे सटती है। काला लड़ाई स्वीकार करता है।",
        "20": "सफ़ेद की 20 (C3) काले कोने के नीचे घुसती है: कोने का इलाक़ा कम करते हुए अपने पत्थरों को ज़िंदा रखने की कोशिश।",
        "28": "सफ़ेद की 28 (C9) बाईं ओर बहुत दूर तक फैलती है। अक्सर इसे ज़रूरत से ज़्यादा फैलाव कहा जाता है — जोवा की तीखी शैली।",
        "33": "काले की 33 (C2)। कहा जाता है कि यह इनोए घराने का गुप्त रूप से तैयार किया गया नया रास्ता था। यह बीच के कमज़ोर सफ़ेद पत्थरों पर हमला करते हुए बाईं ओर के सफ़ेद पत्थरों को भी निगलना चाहता है।",
        "36": "सफ़ेद की 36 (F3)। सफ़ेद नीचे बाएँ काले को बाहर से घेरते हुए अपने पत्थर जोड़ना चाहता है।",
        "43": "काले की 43 (E9)। बाईं ओर के सफ़ेद पत्थर मुश्किल में हैं। अब तक इनतेत्सु ने अच्छा खेला है और आगे माना जाता है।",
        "45": "काले की 45 (D11) बाईं ओर ऊपर बढ़ती है, सफ़ेद पत्थरों को अलग रखते हुए ख़ुद को मज़बूत करती है।",
        "50": "सफ़ेद की 50 (C16)। सफ़ेद फ़िलहाल नीचे बायाँ छोड़कर ऊपर बाएँ कोने की ओर जाता है।",
        "53": "काले की 53 (G17)। काला ऊपरी किनारे में घुसता है ताकि सफ़ेद ऊपर बायाँ कोना न बढ़ा सके।",
        "58": "सफ़ेद की 58 (C14) ऊपर बाएँ कोने से किनारे के साथ फैलती है और बाईं ओर के काले पत्थरों के पास आती है।",
        "60": "सफ़ेद की 60 (G4) काले के दो पत्थर पकड़ती है। नीचे बाएँ सफ़ेद समूह को आख़िर थोड़ी साँस मिलती है।",
        "62": "सफ़ेद की 62 (J17)। ऊपर भी दोनों आमने-सामने हैं। पूरे बोर्ड पर कमज़ोर पत्थर हैं — कठिन स्थिति।",
        "66": "सफ़ेद की 66 (B14)। ऊपर बाएँ कोने के पास सफ़ेद अपने पत्थर स्थिर करता है।",
        "68": "सफ़ेद की 68 (B11)। इसके बाद की कुछ सफ़ेद चालें और 80वीं चाल “जोवा की अद्भुत चालें” के रूप में मशहूर हुईं। वे इतनी शानदार थीं कि लोग कहते थे भूतों ने उसे बताई थीं।",
        "70": "सफ़ेद की 70 (E12)। बाईं ओर काले का सीधे जवाब देने के बजाय सफ़ेद पहले दूसरा अहम बिंदु लेता है। छिपी संभावनाएँ इसे मुमकिन बनाती हैं।",
        "72": "सफ़ेद की 72 (R13)। सफ़ेद दाईं ओर जाता है ताकि ऊपर दाएँ काले का इलाक़ा न बढ़े।",
        "76": "सफ़ेद की 76 (O14)। सफ़ेद दाईं ओर को बीच से जोड़ता है और काले पत्थरों को बाँटने की तैयारी करता है।",
        "80": "सफ़ेद की 80 (Q10) “ख़ाली त्रिकोण” बनाती है, जिसे आम तौर पर बुरी बनावट माना जाता है। फिर भी यही चाल काले को दो हिस्सों में बाँटकर हमला करने का आधार बनी। “दिखने में बुरी, पर बेहतरीन चाल” की यह मशहूर मिसाल है।",
        "83": "काले की 83 (R3) नीचे दाएँ सफ़ेद कोने में घुसती है। वहाँ पकड़ने-छुड़ाने की तेज़ लड़ाई होती है।",
        "91": "काले की 91 (Q4) सफ़ेद का एक पत्थर पकड़ती है। नीचे दायाँ कोना काले के लिए अहम है।",
        "98": "सफ़ेद की 98 (M4)। सफ़ेद नीचे काले पत्थरों को बाहर से घेरता है और उन्हें आसानी से जीने नहीं देता।",
        "106": "सफ़ेद की 106 (S5) काले का एक पत्थर पकड़ती है। नीचे दायाँ कोना सफ़ेद के पास रहता है, और काले पत्थरों को बाहर भागना पड़ता है।",
        "113": "काले की 113 (K6)। नीचे के काले पत्थर बीच की ओर निकलकर जीने का रास्ता खोजते हैं।",
        "120": "सफ़ेद की 120 (N9) भागते काले पत्थरों का रास्ता रोकती है। बीच में मुक़ाबला है कि किसके पत्थर पहले कमज़ोर होते हैं।",
        "128": "सफ़ेद की 128 (L11) बीच के काले पत्थरों को ऊपर से भी दबाती है। काला अब भी चैन से नहीं बैठ सकता।",
        "138": "सफ़ेद की 138 (K8) एक पत्थर पकड़ती है और बीच में “को” शुरू होता है। लगभग 30 चालों तक K8 और L8 पर बारी-बारी पकड़ना चलता है।",
        "152": "सफ़ेद की 152 (E11) “को” की धमकी है। “को” के दौरान सफ़ेद हर जगह ऐसी चालें ढूँढता है जिनका काले को जवाब देना पड़ता है।",
        "170": "सफ़ेद की 170 (P15)। बीच का “को” थम गया; सफ़ेद ऊपर दाएँ जाता है और एक बड़े काले समूह को निशाना बनाता है जो अभी पूरी तरह ज़िंदा नहीं।",
        "178": "सफ़ेद की 178 (J14) ऊपर के बीच में कूदकर काले पत्थरों को बाएँ-दाएँ बाँटती है। 80वीं चाल से तैयार हो रहा बाँटने वाला हमला अब पूरी ताक़त से शुरू होता है।",
        "193": "काले की 193 (J11) सफ़ेद का एक पत्थर पकड़ती है। काला जुड़ने और जीने के लिए जी-जान से लड़ता है।",
        "201": "काले की 201 (R14) एक पत्थर पकड़ती है और दाईं ओर नया “को” शुरू होता है, R14 और R15 पर।",
        "206": "सफ़ेद की 206 (M13)। “को” के दौरान भी सफ़ेद धीरे-धीरे बीच के काले पत्थरों पर शिकंजा कसता है।",
        "222": "सफ़ेद की 222 (L14) एक पत्थर पकड़ती है। ऊपर के काले पत्थर अब भी दो हिस्सों में बँटे हैं, दोनों को बचाना कठिन हो रहा है।",
        "230": "सफ़ेद की 230 (C13) बाईं ओर भी काले की कमज़ोरी पर वार करती है। अब सफ़ेद पत्थर पूरे बोर्ड पर मज़बूती से जुड़े हैं।",
        "237": "237 (F12) और 239 (E13) से काला ऊपर बाएँ पत्थर वापस पकड़ता है। फिर भी कुल अंतर कम नहीं होता।",
        "246": "सफ़ेद 246 (L8) के बाद इनतेत्सु ने हार मान ली। कहा जाता है कि पत्थर समेटते समय उसने बोर्ड पर ख़ून उगला। शायद वह पहले से बीमार था, और कुछ ही समय बाद उसकी मृत्यु हो गई। जोवा के लिए यह जीवन की सबसे बड़ी जीत कही जाती है।"
      } },
    "deepblue1997": { "t": "डीप ब्लू की जीत", "w": "डीप ब्लू (IBM का कंप्यूटर)", "b": "गैरी कास्परोव", "ev": "IBM के डीप ब्लू से दोबारा मुक़ाबले (छह बाज़ियों का मैच) की छठी बाज़ी", "d": "1997", "pl": "अमेरिका (न्यूयॉर्क)", "lead": "विश्व चैंपियन कास्परोव और IBM के बनाए शतरंज कंप्यूटर डीप ब्लू के बीच छह बाज़ियों का मैच। पाँच बाज़ियों के बाद स्कोर बराबर था, और आख़िरी बाज़ी सिर्फ़ 19 चालों में ख़त्म हो गई। पहली बार किसी कंप्यूटर ने कई बाज़ियों के पूरे मैच में विश्व चैंपियन को हराया।",
      c: {
        "0": "न्यूयॉर्क, 11 मई 1997। पिछले साल का मैच कास्परोव ने जीता था। इस बार पाँच बाज़ियों के बाद स्कोर 2½–2½ है। डीप ब्लू सफ़ेद से खेल रहा है।",
        "1": "सफ़ेद राजा का प्यादा दो ख़ाने बढ़ाता है।",
        "2": "कास्परोव c6 चलते हैं: कैरो-कान डिफ़ेंस।",
        "3": "सफ़ेद दूसरा प्यादा भी बीच में लाता है।",
        "4": "काला d5 से e4 पर टकराता है।",
        "5": "घोड़ा e4 को बचाता है।",
        "6": "काला e4 का प्यादा ले लेता है।",
        "7": "घोड़ा वापस लेता है।",
        "8": "काला घोड़े को d7 पर रखता है, ताकि बाद में दूसरा घोड़ा f6 पर आ सके।",
        "9": "घोड़ा g5 पर कूदता है: f7 और e6 पर निशाना लगाने वाली तेज़ योजना।",
        "10": "काला घोड़ा f6 पर निकालता है।",
        "11": "ऊँट d3 पर, काले राजा की तरफ़ नज़र।",
        "12": "काला e6 से बचाव मज़बूत करता है।",
        "13": "दूसरा घोड़ा भी f3 पर निकलता है।",
        "14": "काला g5 के घोड़े को भगाने के लिए h6 चलता है। पर इस स्थिति में सफ़ेद का घोड़ा क़ुर्बान करना पहले से जाना जाता था। कहते हैं कि यह कास्परोव के लिए अजीब चुनाव था।",
        "15": "घोड़ा e6 पर क़ुर्बान! कहा जाता है कि डीप ब्लू ने यह चाल पहले से याद की हुई शुरुआती चालों में से चली।",
        "16": "काला तुरंत नहीं लेता, वज़ीर को e7 पर लाता है। e लाइन पर वह e6 के घोड़े और उसके पीछे सफ़ेद राजा को देखता है।",
        "17": "सफ़ेद कैसलिंग करके राजा को बचा लेता है।",
        "18": "काला घोड़ा ले लेता है और मोहरों में आगे हो जाता है।",
        "19": "ऊँट g6 पर, शह। f7 का प्यादा न होने से तिरछी लाइन राजा तक खुली है।",
        "20": "राजा d8 पर। काला अब कैसलिंग नहीं कर सकता और राजा बीच के पास फँसा है।",
        "21": "दूसरा ऊँट भी निकलकर काले राजा के आसपास के ख़ानों को देखता है।",
        "22": "काला b5 चलता है, वज़ीर की तरफ़ राजा और ऊँट के लिए जगह बनाने को।",
        "23": "a4 से b5 के प्यादे पर हमला।",
        "24": "काला ऊँट को b7 पर लाता है।",
        "25": "हाथी e1 पर। e लाइन पर e6 के प्यादे को, और उसके पीछे e7 के वज़ीर को देखता है।",
        "26": "काला घोड़ा d5 पर जाकर f4 के ऊँट पर हमला करता है।",
        "27": "ऊँट g3 पर लौटता है।",
        "28": "काला राजा c8 पर, थोड़ा सुरक्षित।",
        "29": "सफ़ेद b5 का प्यादा लेता है।",
        "30": "काला वापस लेता है।",
        "31": "वज़ीर d3 पर, b5 के प्यादे और f5 ख़ाने पर नज़र।",
        "32": "काला ऊँट से b5 बचाता है।",
        "33": "ऊँट f5 पर! इसे मुफ़्त में लिया जा सकता है।",
        "34": "काला प्यादे से लेता है। पर इससे e लाइन का प्यादा हट गया।",
        "35": "हाथी e7 का वज़ीर ले लेता है। सफ़ेद ने घोड़ा, ऊँट और हाथी दिए, पर वज़ीर जीत लिया।",
        "36": "काला ऊँट से हाथी वापस लेता है।",
        "37": "c4! प्यादा एक साथ b5 और d5 पर टकराता है, और काले का बचाव टूटने लगता है। कास्परोव ने यहीं हार मान ली, शायद यह सोचकर कि उनका राजा हमला रोकने के लिए बहुत खुला है। एक कंप्यूटर ने विश्व चैंपियन के ख़िलाफ़ मैच जीत लिया था।"
      } },
    "seigen1933": { "t": "3-3, स्टार पॉइंट और तेनगेन वाली बाज़ी", "w": "गो सेइगेन", "b": "होन्इनबो शूसाई", "ev": "मेइजिन के साथ यादगार बाज़ी (तीन महीने से ज़्यादा)", "d": "1933–1934", "pl": "जापान (टोक्यो)", "lead": "19 साल के गो सेइगेन (5-दान) ने मेइजिन होन्इनबो शूसाई से बाज़ी खेली। काले से उसने पहले 3-3 बिंदु, फिर स्टार पॉइंट, फिर ठीक बीच (तेनगेन) पर खेला — उस समय के सारे नियम तोड़कर सबको चौंका दिया। कई बार रुकते हुए बाज़ी तीन महीने से ज़्यादा चली; सफ़ेद 2 अंक से जीता।",
      c: {
        "0": "1933। उस साल गो सेइगेन और उसके दोस्त कितानी मिनोरु “शिनफ़ुसेकी” नाम की नई शुरुआत फैला रहे थे। सब देखना चाहते थे कि वह इसे मेइजिन के ख़िलाफ़ कैसे इस्तेमाल करेगा।",
        "1": "काले की 1 ऊपर दाएँ 3-3 बिंदु (R17) पर। एक ही चाल में कोना पक्का, पर बाहर की ओर असर कम; उस समय इसे पहली चाल नहीं माना जाता था।",
        "3": "काले की 3 नीचे बाएँ स्टार पॉइंट (D4) पर। 3-3 के उलट, यह बाहर फैलने को महत्व देती है।",
        "5": "काले की 5 ठीक बोर्ड के बीच — तेनगेन (K10)। न कोना, न किनारा, सीधे बीच। मेइजिन के सामने गो सेइगेन ने अपने नए विचार खुलकर दिखाए।",
        "6": "3-3, स्टार, तेनगेन: तीनों काले पत्थरों का अलग काम है — कोने का इलाक़ा, बाहर तक पहुँच और बीच की ताक़त। 6 (Q16) से सफ़ेद काले 3-3 के ठीक बगल में खेलता है।",
        "9": "काले की 9 (P18)। काला ऊपर दाएँ कोने को छोटा और सुरक्षित बसा लेता है — 3-3 वाली “पहले इलाक़ा” शैली।",
        "11": "काले की 11 (K4) तेनगेन के ठीक नीचे, निचले किनारे के बीच। उस पत्थर के साथ मिलकर काला नीचे बड़ा इलाक़ा चाहता है।",
        "12": "सफ़ेद की 12 (M3) सीधे निचले किनारे में घुसती है ताकि काला बड़ा ढाँचा न बना सके। मेइजिन शांत रहकर काले की योजनाएँ एक-एक कर तोड़ता है।",
        "13": "काले की 13 (D10), अब बाएँ किनारे के बीच। काले पत्थर ऊँचे खड़े हैं और मिलकर बड़ा ढाँचा बनाते हैं।",
        "14": "सफ़ेद की 14 (E16) ऊपर बाएँ कोने को दूसरे पत्थर से बंद करती है। मेइजिन नई शैली से विचलित नहीं होता और शांति से कोना पक्का करता है।",
        "21": "काले की 21 (G10) तेनगेन को बाएँ किनारे के पत्थर से जोड़ती है, और काले का असर बीच में फैलता है।",
        "28": "सफ़ेद की 28 (D3) नीचे बाएँ काले स्टार पत्थर के नीचे घुसकर कोना ले लेती है। काला बाहर की ताक़त के बदले कोना छोड़ देता है।",
        "30": "सफ़ेद की 30 (Q12) दाईं ओर फैलती है और काले 3-3 कोने के ऊपर ढक्कन भी लगाती है, जिससे उसकी पहुँच घटती है।",
        "37": "काले की 37 (P15) सफ़ेद का एक पत्थर पकड़ती है। ऊपर दाएँ दोनों में क़रीबी टक्कर है।",
        "40": "सफ़ेद की 40 (O10) दाईं ओर से बीच की ओर क़दम बढ़ाकर तेनगेन के आसपास काले असर के पास आती है।",
        "44": "सफ़ेद की 44 (H17) ऊपरी किनारे पर बैठकर काले को ऊपर फैलने से रोकती है।",
        "45": "काले की 45 (R7) नीचे दाएँ सफ़ेद की जगह पर काम शुरू करती है। दाएँ किनारे से उस कोने तक लंबी लड़ाई चलती है।",
        "59": "काले की 59 (R4) नीचे दाएँ कोने में भी घुसकर सफ़ेद का इलाक़ा घटाती है।",
        "70": "सफ़ेद की 70 (N6) नीचे से बीच की ओर बढ़कर काले के नीचे-दाएँ और बीच वाले पत्थरों को अलग करना चाहती है।",
        "79": "काले की 79 (L9) तेनगेन के आसपास बीच को मज़बूत करती है। अब तक बाज़ी काफ़ी बराबर लगती है।",
        "80": "सफ़ेद की 80 (C6) नीचे बाएँ कोने से बाएँ किनारे पर ऊपर बढ़कर वहाँ के काले पत्थरों को निशाना बनाती है।",
        "98": "सफ़ेद की 98 (A11) काले के दो पत्थर पकड़ती है। सफ़ेद बाएँ किनारे पर साफ़-सुथरे ढंग से जीता है, और काले का बायाँ हिस्सा योजना से छोटा रह जाता है।",
        "101": "काले की 101 (S14) ऊपर दाएँ लौटकर दाईं ओर सफ़ेद की जगह छोटी करती है।",
        "105": "काले की 105 (K17) ऊपरी किनारे का बीच लेकर वहाँ के सफ़ेद पत्थरों पर हमला शुरू करती है।",
        "117": "काले की 117 (F17) ऊपर बाएँ सफ़ेद कोने के आसपास भी घुसती है, और पूरा ऊपरी किनारा युद्धभूमि बन जाता है।",
        "124": "सफ़ेद की 124 (K15) ऊपर के पत्थरों को बीच की ओर ले जाते हुए काले पत्थरों के बीच से काटती है।",
        "135": "काले की 135 (E9) सफ़ेद के दो पत्थर पकड़ती है। बाईं ओर काला कुछ वापस पाता है।",
        "138": "सफ़ेद की 138 (N18) ऊपरी किनारे पर इलाक़ा पक्का करती है। पूरे बोर्ड पर स्थिति बहुत क़रीबी है।",
        "153": "काले की 153 (K14)। बीच के काले पत्थर ऊपर और नीचे को जोड़ने वाला मोटा रास्ता बनाते हैं। असली सवाल है कि सफ़ेद इस मज़बूती को कैसे तोड़ेगा।",
        "159": "काले की 159 (F4) नीचे बाएँ मज़बूती से बचाव करती है। सफ़ेद की अगली चाल इस बाज़ी की सबसे मशहूर चाल है।",
        "160": "सफ़ेद की 160 (H8) काले की मज़बूती की दरार में कूदती है — एक साथ कई निशानों वाली तीखी चाल, जिससे सफ़ेद काले के बीच में घुसना शुरू करता है। अफ़वाह फैली कि यह चाल शूसाई ने नहीं, उसके एक शिष्य ने ढूँढी थी, पर यह कभी साबित नहीं हुआ।",
        "161": "काले की 161 (J8) तुरंत जवाब देती है, पर सफ़ेद के निशाने एक से ज़्यादा हैं।",
        "162": "सफ़ेद की 162 (K12) बीच के ऊपरी हिस्से में जाकर काले पत्थरों के जोड़ों को धमकाती है।",
        "172": "सफ़ेद की 172 (F13) बीच के पत्थरों को ऊपर बाएँ से जोड़ती है। धीरे-धीरे काले की बीच वाली मज़बूती इलाक़े में नहीं बदल पाती।",
        "178": "सफ़ेद की 178 (N9) बीच के दाईं ओर भी काले इलाक़े में घुसती है।",
        "187": "187 (M6) और 189 (L7) से काला सफ़ेद पत्थर पकड़कर जवाब देता है। फिर भी सफ़ेद अहम बिंदुओं पर पहले पहुँच चुका था।",
        "198": "सफ़ेद की 198 (E12) एक पत्थर पकड़ती है। ऊपर बाएँ के सफ़ेद पत्थर भी जुड़ गए, और कुल मिलाकर सफ़ेद थोड़ा आगे है।",
        "203": "काले की 203 (B3)। यहाँ से अंतिम चरण: किनारों की सीमाएँ एक-एक अंक करके तय होती हैं।",
        "224": "सफ़ेद की 224 (T10) एक पत्थर पकड़ती है। दाएँ किनारे पर भी सफ़ेद एक अंक नहीं छोड़ता।",
        "233": "काले की 233 (L13) सफ़ेद के दो पत्थर पकड़ती है। काला आख़िर तक पीछा करता है।",
        "252": "252 चालों पर बाज़ी ख़त्म: सफ़ेद 2 अंक से जीता। कोमी न होने से पहले चलने वाले काले को थोड़ा फ़ायदा था, पर मेइजिन आख़िर तक डटा रहा। फिर भी गो सेइगेन के 3-3, स्टार और तेनगेन ने सनसनी मचा दी और शुरुआत के नए दौर का ऐलान किया।"
      } },
    "century1956": { "t": "सदी की बाज़ी", "w": "डोनाल्ड बर्न", "b": "बॉबी फ़िशर", "ev": "तीसरा रोज़ेनवाल्ड ट्रॉफ़ी टूर्नामेंट (रोज़ेनवाल्ड मेमोरियल)", "d": "1956", "pl": "अमेरिका (न्यूयॉर्क)", "lead": "13 साल के बॉबी फ़िशर ने अमेरिका के सबसे मज़बूत मास्टरों में से एक डोनाल्ड बर्न को हराया। 17वीं चाल में फ़िशर अपना वज़ीर मुफ़्त में ले लेने देते हैं, फिर एक-एक करके मोहरे वापस जीतते हैं, और आख़िर में उनके छोटे मोहरे सफ़ेद राजा को घेर लेते हैं। फ़िशर आगे चलकर विश्व चैंपियन बने।",
      c: {
        "0": "न्यूयॉर्क, 17 अक्टूबर 1956, एक टूर्नामेंट बाज़ी। काले से 13 साल के फ़िशर, सफ़ेद से अमेरिका के टॉप खिलाड़ियों में से एक बर्न।",
        "1": "सफ़ेद घोड़े से शुरू करता है।",
        "4": "फ़िशर g6 चलते हैं, ताकि ऊँट लंबी तिरछी लाइन पर आ सके।",
        "8": "काला कैसलिंग करता है: पहले राजा सुरक्षित।",
        "10": "काला d5 चलता है। बीच की लड़ाई शुरू।",
        "15": "e4 से सफ़ेद के बीच में दो प्यादे साथ-साथ हैं।",
        "17": "हाथी d1 पर, d4 के प्यादे को सहारा। सफ़ेद ने अब तक कैसलिंग नहीं की।",
        "18": "घोड़ा b6 पर जाकर c4 के वज़ीर को भगाता है।",
        "20": "ऊँट g4 पर, f3 के घोड़े पर दबाव।",
        "21": "सफ़ेद ऊँट g5 पर। सफ़ेद राजा अब भी बीच में है।",
        "22": "घोड़ा a4 पर! ऐसे ख़ाने पर कूदता है जहाँ उसे लिया जा सकता है। सोच यह है: c3 का घोड़ा हटे तो e4 का प्यादा बिना बचाव के रह जाए।",
        "23": "सफ़ेद घोड़ा नहीं लेता, वज़ीर को a3 पर ले जाता है।",
        "26": "काला घोड़ा e4 का प्यादा लेता है। सफ़ेद का बीच टूटने लगा।",
        "27": "सफ़ेद ऊँट e7 का प्यादा लेकर एक साथ काले वज़ीर और f8 के हाथी पर हमला करता है।",
        "28": "वज़ीर b6 पर! काला f8 का हाथी जाने देता है। फ़िशर इस बात पर भरोसा कर रहे हैं कि सफ़ेद राजा अब भी बीच में है।",
        "29": "सफ़ेद हाथी नहीं लेता, ऊँट निकालता है।",
        "30": "घोड़ा c3 का प्यादा लेकर d1 के हाथी पर हमला करता है।",
        "31": "ऊँट c5 पर, b6 के काले वज़ीर पर हमला।",
        "32": "e लाइन पर हाथी की शह!",
        "33": "राजा f1 पर। अब सफ़ेद कभी कैसलिंग नहीं कर सकता।",
        "34": "ऊँट e6 पर! बाज़ी की सबसे मशहूर चाल: काला अपना वज़ीर मुफ़्त में दे देता है। बदले में उसकी योजना है एक-एक करके मोहरे वापस जीतने की।",
        "35": "सफ़ेद काले वज़ीर को ले लेता है।",
        "36": "ऊँट c4 पर, शह। काले का जवाबी हमला शुरू।",
        "38": "घोड़ा e2 से शह देता है।",
        "40": "राजा f1 पर लौटे तो घोड़ा हटकर c4 के ऊँट की शह खोल देता है। रास्ते में घोड़ा d4 का प्यादा भी ले लेता है।",
        "44": "घोड़ा c3 पर लौटता है, फिर खुली शह, और अब d1 के हाथी पर हमला। बार-बार शह देते हुए मोहरे बटोरने को \"पनचक्की\" कहते हैं।",
        "46": "काला ऊँट वापस लेता है। c3 का घोड़ा अब भी d1 के हाथी पर हमला कर रहा है।",
        "50": "घोड़ा d1 का हाथी लेता है। अब काला दिए गए वज़ीर से ज़्यादा वापस जीत चुका है और साफ़ आगे है।",
        "52": "हाथी a2 का प्यादा भी ले लेता है।",
        "56": "काला हाथी बदल लेता है। मोहरे जितने कम, जिसके पास ज़्यादा हों उसका उतना फ़ायदा।",
        "57": "सफ़ेद वज़ीर शह देता है।",
        "58": "काला बीच में ऊँट रखता है।",
        "64": "b5. काला प्यादा आगे बढ़ना शुरू करता है।",
        "68": "राजा g7 पर जाकर f8 के ऊँट को आज़ाद करता है।",
        "70": "अब काले मोहरे सफ़ेद राजा का शिकार करते हैं। ऊँट से शह।",
        "72": "घोड़ा g3 पर शह देता है।",
        "74": "दूसरे ऊँट से शह।",
        "76": "ऊँट b3 पर, शह।",
        "78": "घोड़ा e2 पर शह देता है।",
        "80": "घोड़ा c3 पर शह देता है। राजा इधर-उधर भगाया जा रहा है।",
        "82": "हाथी c2 पर: शह और मात! हाथी, दो ऊँट और घोड़ा मिलकर काम करते हैं। 13 साल के एक लड़के ने दिखाया कि कई मोहरे एक टीम की तरह कैसे खेल सकते हैं।"
      } },
    "oshiro1849": { "t": "शूसाकु की पहली क़िले वाली बाज़ी", "w": "होन्इनबो शूसाकु", "b": "यासुई सान्ची (नौवें)", "ev": "क़िले की बाज़ी (एदो क़िले में हर साल होने वाला मुक़ाबला)", "d": "1849", "pl": "जापान (एदो)", "lead": "क़िले की बाज़ियाँ हर साल का बड़ा मौक़ा थीं, जब गो के सरकारी घरानों के खिलाड़ी शोगुन के क़िले में खेलते थे। 20 साल के शूसाकु ने उस साल पहली बार भाग लिया और काले से 11 अंक से जीता — यहीं से 19 में 19 जीत का बेदाग़ रिकॉर्ड शुरू हुआ।",
      c: {
        "0": "1849। एक साल पहले शूसाकु को होन्इनबो घराने का उत्तराधिकारी चुना गया था, और अब वह अपनी पहली क़िले वाली बाज़ी खेलता है। कहा जाता है कि ये बाज़ियाँ अक्सर पहले कहीं और खेल ली जाती थीं और क़िले में बस दोहराई जाती थीं।",
        "1": "काले की 1 ऊपर दाएँ 3-4 बिंदु (R16) पर। हमेशा की तरह शूसाकु शांत 3-4 से शुरू करता है।",
        "4": "सफ़ेद की 4 (C15) ऊपर बाएँ काले D17 के पास आती है। वहाँ जल्दी ही लड़ाई शुरू होती है।",
        "5": "काले की 5 (C11) पास आए सफ़ेद पत्थर को नीचे से चिमटी में लेती है, ताकि सफ़ेद बाईं ओर आसानी से न जमे।",
        "12": "सफ़ेद की 12 (C17)। ऊपर बायाँ कोना सफ़ेद का, और काले को बाहर की ओर देखते पत्थर मिले — दोनों के लिए ठीक सौदा।",
        "13": "काले की 13 (J17) बाहर वाले पत्थरों का फ़ायदा उठाकर ऊपर फैलती है।",
        "15": "काले की 15 (C5) आख़िरी ख़ाली कोना, नीचे बायाँ, लेती है। अब चारों कोने भर गए।",
        "16": "सफ़ेद की 16 (E4) तुरंत उस काले पत्थर के पास आती है, और नीचे बाएँ भी लड़ाई होती है।",
        "19": "काले की 19 (D2) नीचे बाएँ कोने को मज़बूती से पक्का करती है — शूसाकु जैसी ठोस चाल।",
        "23": "काले की 23 (E5) सफ़ेद पत्थरों के बीच से निकलकर नीचे बाएँ समूह को मज़बूत करती है।",
        "29": "काले की 29 (F11) बाईं ओर के काले पत्थरों को मज़बूत करते हुए बीच की ओर भी देखती है।",
        "30": "सफ़ेद की 30 (H4) नीचे फैलती है, बाएँ काले समूह पर दबाव डालते हुए अपना इलाक़ा बनाती है।",
        "31": "काले की 31 (O3) नीचे दाएँ सफ़ेद कोने के पास आती है।",
        "33": "काले की 33 (R3) सफ़ेद कोने के पत्थर से सटती है। यहाँ से काला बाहर की ओर बनाता है और सफ़ेद किनारे की तीसरी रेखा पर रेंगता है।",
        "43": "काले की 43 (Q8)। दाईं ओर ऊपर से नीचे तक मोटी काली दीवार बन गई। सफ़ेद को कोने और किनारे का इलाक़ा मिला, काले को बाहर की ताक़त।",
        "44": "सफ़ेद की 44 (L17) ऊपर काले पत्थरों के बीच घुसती है ताकि काले का इलाक़ा बहुत बड़ा न हो।",
        "50": "सफ़ेद की 50 (R18) ऊपर दाएँ काले कोने के नीचे घुसकर कोने के इलाक़े पर नज़र डालती है।",
        "51": "काले की 51 (P13)। दीवार के सहारे काला दाईं ओर से बीच तक बड़ा इलाक़ा घेरता है।",
        "52": "सफ़ेद की 52 (D10) बाईं ओर काले पत्थरों के बीच कूदती है। वहाँ पत्थर उलझ जाते हैं।",
        "63": "काले की 63 (B10) बाएँ किनारे पर खेलती है ताकि सफ़ेद पत्थर वहाँ आधार न बना सकें।",
        "65": "काले की 65 (G3) नीचे सफ़ेद के इलाक़े में भी घुसकर उसे छोटा करती है।",
        "73": "काले की 73 (K17) ऊपर के काले पत्थरों को मज़बूत करके 44वीं चाल वाले सफ़ेद पत्थर पर दबाव डालती है।",
        "76": "सफ़ेद की 76 (P11) दाईं ओर काले इलाक़े में कूदती है। यह पत्थर जिएगा या मरेगा, इससे अंक बहुत बदलेंगे।",
        "77": "काले की 77 (Q11) अपनी दीवार की ओर से जवाब देकर सफ़ेद को बीच की ओर धकेलती है — शांत बचाव जो हमला भी है, शूसाकु जैसा।",
        "80": "सफ़ेद की 80 (N10) काले के पीछा करने से बचने के लिए बीच की ओर भागती है।",
        "85": "काले की 85 (N12) हमला जारी रखते हुए ऊपर और दाईं ओर अपना इलाक़ा बढ़ाती है। हमले से फ़ायदा — कुशल खेल।",
        "91": "काले की 91 (J7) नीचे के सफ़ेद पत्थरों के ऊपर खेलकर बीच की ओर से भी सफ़ेद इलाक़े को ढकती है।",
        "100": "सफ़ेद की 100 (S17) ऊपर दाएँ कोने में काले का इलाक़ा घटाने की कोशिश करती है।",
        "119": "काले की 119 (R17) ऊपर दाएँ कोने का मज़बूती से बचाव करके सफ़ेद की कोशिश नाकाम करती है।",
        "122": "सफ़ेद की 122 (G6) नीचे बाएँ काले पत्थरों के बाहर घूमकर उन्हें बीच के काले से काटना चाहती है।",
        "131": "काले की 131 (M5) निचले किनारे के बीच सफ़ेद इलाक़े में फाँस गाड़ती है।",
        "140": "सफ़ेद की 140 (B4) नीचे बाएँ काले कोने में कोशिश करती है। बाएँ किनारे पर पकड़ने की क़रीबी लड़ाई शुरू होती है।",
        "156": "सफ़ेद की 156 (A8) काले के दो पत्थर पकड़ती है। दोनों के थोड़ा-थोड़ा पाने के बाद बाएँ किनारे की लड़ाई थमती है।",
        "158": "सफ़ेद की 158 (L10)। बीच में अब भी सफ़ेद पत्थर हैं, और वह काले का बीच वाला इलाक़ा घटाना चाहता है।",
        "162": "सफ़ेद की 162 (O12) काले का एक पत्थर पकड़ती है। फिर भी दाईं ओर काले का इलाक़ा बड़ा बना रहता है।",
        "172": "सफ़ेद की 172 (K18)। यहाँ से अंतिम चरण, शुरुआत ऊपरी किनारे की सीमा से।",
        "186": "सफ़ेद की 186 (T16) ऊपर दाएँ किनारे पर काले का इलाक़ा कतरती है। अंत में दोनों पहले सबसे बड़े बिंदु खेलते हैं।",
        "205": "काले की 205 (Q18) ऊपरी किनारे का दायाँ हिस्सा बंद करके वहाँ का इलाक़ा पक्का करती है।",
        "223": "काले की 223 (P10) दाईं ओर काले इलाक़े और बीच में भागे सफ़ेद पत्थरों के बीच सीमा तय करती है।",
        "233": "काले की 233 (Q9) सफ़ेद का एक पत्थर पकड़ती है। दाईं ओर काले का इलाक़ा अब लगभग पूरा सुरक्षित है।",
        "239": "काले की 239 (A6) एक पत्थर पकड़ती है और बाएँ किनारे पर “को” बनता है। एक-एक अंक की लड़ाई आख़िर तक चलती है।",
        "260": "सफ़ेद की 260 (T6) एक पत्थर पकड़कर नीचे दाएँ किनारे पर एक और “को” बनाती है। काला 263 (T5) से वापस पकड़ता है।",
        "267": "267 चालों पर बाज़ी ख़त्म: काला 11 अंक से जीता। कोई जोखिम नहीं — शूसाकु ने हमला करते हुए अपना इलाक़ा स्वाभाविक रूप से बढ़ाया, बिल्कुल उसकी शैली की जीत। यह क़िले की बाज़ियों में उसकी लगातार 19 जीतों में पहली थी।"
      } },
    "shilin": { "t": "शिलिन ग्वांगजी की बाज़ी", "w": "लाल (नाम दर्ज नहीं)", "b": "काला (नाम दर्ज नहीं)", "ev": "रोज़मर्रा का विश्वकोश शिलिन ग्वांगजी: “पहली चाल देकर, एक ही ओर की तोपों से जीती बाज़ी”", "d": "13वीं सदी", "pl": "चीन (सोंग–युआन)", "lead": "यह रिकॉर्ड शिलिन ग्वांगजी से है, जो रोज़मर्रा के जीवन का एक विश्वकोश है और जिसे चेन युआनजिंग ने सोंग राजवंश के अंत और युआन की शुरुआत के आसपास तैयार किया था। इसे शियांगची की सबसे पुरानी बची हुई पूरी बाज़ियों में से एक माना जाता है। यह एक नमूना बाज़ी है जिसमें मज़बूत खिलाड़ी दूसरे को पहली चाल देता है, और सिर्फ़ नौ चालों में काला घोड़ा लाल रथ को फँसा लेता है।",
      c: {
        "0": "यह रिकॉर्ड 700 साल से भी पुराना है, सोंग और युआन राजवंशों के बीच के समय का। यह शिलिन ग्वांगजी विश्वकोश के खेलों वाले हिस्से में है, और इसे हमारे पास बची शियांगची की सबसे पुरानी पूरी बाज़ियों में से एक माना जाता है। खिलाड़ियों के नाम दर्ज नहीं हैं। शीर्षक कहता है कि मज़बूत खिलाड़ी ने कमज़ोर को “पहली चाल दी”, इसलिए यह एक पाठ है जो दिखाता है कि पहले चलने वाला लाल कैसे हारता है। लाल नीचे है और पहले चलता है।",
        "1": "लाल दाईं तोप को बीच वाली पंक्ति में लाता है। इसे “बीच की तोप” कहते हैं; यह सीधे काले जनरल पर निशाना साधती है और आज भी सबसे मज़बूत शुरुआतों में से एक है। इससे पता चलता है कि यह शुरुआत 700 साल पहले भी खेली जाती थी।",
        "2": "काला भी एक तोप बीच में लाता है, और दोनों तोपें आमने-सामने आ जाती हैं। जब दोनों एक ही ओर की तोप चलाते हैं, तो इसे “एक ही दिशा की तोपें” कहते हैं। तोप बनाम तोप की लड़ाई सदियों से पसंद की जाती है।",
        "3": "लाल बीच वाले सिपाही की रक्षा के लिए एक घोड़ा निकालता है। उस सिपाही पर काली तोप का निशाना है, इसलिए उसे रक्षक चाहिए। साथ ही घोड़ा आगे बढ़ने की तैयारी भी करता है।",
        "4": "काला भी यही करता है और अपने बीच वाले सिपाही की रक्षा घोड़े से करता है। दोनों पहले अपनी नींव मज़बूत कर रहे हैं।",
        "5": "लाल दाएँ रथ को एक कदम बगल में, खुली पंक्ति पर ले जाता है। रथ बोर्ड का सबसे ताक़तवर मोहरा है, इसलिए उसे जल्दी काम में लगाना अच्छा है।",
        "6": "काला दूसरा घोड़ा निकालता है और रथों को अभी घर पर ही रखता है। योजना पहले मोहरों को आगे लाने की है। लेकिन देर से निकला रथ बाद में हमले में काम लाना मुश्किल हो सकता है।",
        "7": "लाल रथ एक ही बार में नदी पार करके काले के इलाक़े में घुस जाता है। वह काले मोहरों को धमकाना चाहता है, पर बाकी लाल मोहरे अभी घर पर हैं, इसलिए यह हमला थोड़ा जल्दबाज़ी वाला है। पहले बायाँ घोड़ा या रथ निकालना भी संभव था।",
        "8": "काला कॉलम 3 के सिपाही को एक कदम आगे बढ़ाता है। इससे घोड़े का रास्ता खुलता है ताकि वह बाद में आगे कूद सके। काला लगभग लाल रथ को आने का न्योता दे रहा है।",
        "9": "लाल रथ एक सिपाही को मारता है और अब उसके पीछे वाले काले घोड़े पर निशाना साधता है। एक मोहरा जीतना और दूसरे को धमकाना बढ़िया लगता है। लेकिन रथ बहुत आगे निकल गया है और उसके पास कोई साथी नहीं है। दुश्मन के इलाक़े में अकेला रथ आसानी से खदेड़ा जाता है।",
        "10": "काला घोड़ा आगे कूदता है। वह रथ से बचता है और साथ ही लाल के इलाक़े के पास पहुँचता है — एक चाल में दो काम। यही घोड़ा इस बाज़ी का हीरो बनेगा।",
        "11": "लाल रथ को एक कदम पीछे करके घोड़े पर बगल से हमला करता है। रथ दूर से भी मार सकता है, इसलिए घोड़ा आराम नहीं कर सकता। फिर भी यह चाल किसी दूसरे लाल मोहरे को आगे नहीं लाती।",
        "12": "काला घोड़ा और आगे बढ़कर नदी पार करके लाल के इलाक़े में पहुँच जाता है। हर बार रथ से बचते हुए वह लाल जनरल के और पास आ जाता है।",
        "13": "लाल अपने घोड़े का रास्ता खोलने के लिए एक सिपाही आगे बढ़ाता है। विचार यह है कि घोड़े को निकालकर काले घोड़े से बदल लिया जाए। लेकिन इससे काले को और आगे जाने का समय मिल जाता है।",
        "14": "काला हाथी को ऊपर लाकर लाल रथ पर हमला करता है। बचाव वाले मोहरे से दुश्मन के रथ को भगाना बहुत किफ़ायती है। लाल को फिर रथ हटाना पड़ता है, और काला एक और चाल कमा लेता है।",
        "15": "लाल रथ बगल में खिसककर एक और सिपाही मारता है। लाल अब दो सिपाही आगे है, लेकिन यही हारने वाली चाल है। रथ अब अपने जनरल से बहुत दूर है और बचाव के लिए लौट नहीं सकता। लाल को घोड़े से बचाव करना था, जैसे रथ को घर वापस लाना।",
        "16": "काला घोड़ा और गहराई में घुसकर लाल रथ पर हमला करता है। और भी है: अगर वह एक बार और कूदे, तो लाल जनरल को शह देगा और उसी समय कोने वाले रथ पर भी हमला करेगा। एक ही घोड़े ने एक साथ दो ख़तरे बना दिए।",
        "17": "लाल रथ से घोड़े का पीछा करता है। लेकिन अब उसे रोका नहीं जा सकता। लाल जनरल के आसपास मदद करने वाला कोई नहीं बचा।",
        "18": "घोड़ा कूदकर शह देता है! वह कोने वाले लाल रथ पर भी हमला कर रहा है, इसलिए जनरल के हटते ही रथ चला जाएगा। सिर्फ़ नौ चालें, लेकिन यह बाज़ी सिखाती है कि अकेले आगे भागने वाले रथ का क्या होता है, और मोहरों को मिलकर क्यों लड़ना चाहिए। 700 साल पहले के खिलाड़ी भी उसी बोर्ड पर यही बातें सोच रहे थे।"
      } },
    "qima13": { "t": "तेरह चालों में घोड़े की कुर्बानी (जुझोंगमी)", "w": "लाल (नाम दर्ज नहीं)", "b": "काला (नाम दर्ज नहीं)", "ev": "जुझोंगमी, खंड 1, बाज़ी 1", "d": "1632 (प्रकाशन)", "pl": "चीन (मिंग)", "lead": "यह जुझोंगमी (“संतरे के अंदर का रहस्य”) की सबसे पहली बाज़ी है, जो मिंग राजवंश के झू जिनझेन ने 1632 में प्रकाशित की थी। लाल काले को एक घोड़ा मुफ़्त में लेने देता है, उसी बीच हमला करता है और तेरह चालों में मात दे देता है। “तेरह चालों में घोड़े की कुर्बानी” नाम से यह लगभग 400 साल बाद भी पसंद की जाती है।",
      c: {
        "0": "यह जुझोंगमी की बाज़ी 1 है, जो 1632 में, मिंग राजवंश के आख़िरी दौर में छपी किताब है। बाद में आई “बेर के फूल की पुस्तिका” के साथ इसे शियांगची की दो महान क्लासिक किताबों में गिना जाता है। यह असली मुक़ाबला नहीं, बल्कि एक योजना सिखाने के लिए लिखी नमूना बाज़ी है, इसलिए खिलाड़ियों के नाम नहीं हैं। लाल नीचे है और पहले चलता है, और सब कुछ सिर्फ़ तेरह चालों में ख़त्म हो जाता है।",
        "1": "लाल दाईं तोप को बीच में लाता है। यह “बीच की तोप” है, जो सीधे काले जनरल को घूरती है। जुझोंगमी इस शुरुआत से हमला करने के तरीक़ों के अध्ययन के लिए प्रसिद्ध है।",
        "2": "काला भी उसी ओर की तोप बीच में लाता है। ये “एक ही दिशा की तोपें” हैं, जो आमने-सामने टकराती हैं। दोनों एक-दूसरे के बीच वाले सिपाही पर निशाना साधे हैं।",
        "3": "लाल बीच वाले सिपाही की रक्षा के लिए घोड़ा निकालता है। वह काली तोप के निशाने वाले सिपाही को बचाता है, और घोड़ा भी काम शुरू कर देता है।",
        "4": "काला भी बीच वाले सिपाही की रक्षा घोड़े से करता है। अब तक दोनों की बनावट एक जैसी है।",
        "5": "लाल दाएँ रथ को सिर्फ़ एक कदम आगे बढ़ाता है। अब अगली चाल में रथ बगल में दौड़ सकता है। ऐसे बगल में चलने वाले रथ को “आड़ा रथ” कहते हैं; यह जल्दी से किसी भी ओर जा सकता है।",
        "6": "काला रथ को एक कदम बगल में करता है ताकि वह सीधा ऊपर चढ़ सके। यह “सीधा रथ” है। आड़ा रथ बनाम सीधा रथ — रथ को इस्तेमाल करने के दो अलग तरीक़े आमने-सामने।",
        "7": "लाल का आड़ा रथ बाईं ओर की एक पंक्ति पर पहुँच जाता है। यह पंक्ति काले सलाहकार के ठीक बगल से जाती है, जहाँ बचाव कमज़ोर है। लाल यहीं से घुसने की तैयारी कर रहा है।",
        "8": "काले का सीधा रथ नदी पार करके लाल के इलाक़े में गहरे घुस जाता है। काला अपने हमले से जवाब देना चाहता है। लेकिन यह चाल बचाव से पहले हमला करने की जल्दबाज़ी है।",
        "9": "लाल रथ काले के इलाक़े में बहुत अंदर तक घुस जाता है। वह हाथी की “आँख” पर खड़ा है, यानी वह बिंदु जिससे हाथी को गुज़रना पड़ता है, इसलिए काला हाथी हिल नहीं सकता। सलाहकार के ठीक बगल में, अब वह जनरल के बहुत पास है।",
        "10": "काला दूसरा घोड़ा किनारे की ओर निकालता है। इसका एक मक़सद लाल रथ को बगल से घुसने से रोकना भी है।",
        "11": "यही है घोड़े की कुर्बानी! लाल दूसरे रथ को एक कदम ऊपर उठाता है। इससे बाएँ कोने के घोड़े का कोई रक्षक नहीं रहता, और काली तोप उसे मुफ़्त में ले सकती है। लेकिन एक घोड़े के बदले लाल को दोनों रथों को जल्दी हमले में लाने का समय मिल जाता है।",
        "12": "काली तोप लाल घोड़े को मार लेती है। लगता है काले ने एक मोहरा जीत लिया। लेकिन यह तोप अब घर से दूर है और बचाव में मदद नहीं कर सकती। कहा जाता है कि यहाँ मारने के बजाय सलाहकार को ऊपर लाकर बचाव मज़बूत करना बेहतर था।",
        "13": "लाल तोप आगे बढ़ती है। बीच की काली तोप को कूदने के लिए “ओट” बनाकर वह उसके पीछे वाले काले घोड़े पर निशाना साधती है। तोप एक अनोखा मोहरा है जो ठीक एक मोहरे के ऊपर से कूदकर मारता है।",
        "14": "काला घोड़े को पीछे हटाकर बचाता है। लेकिन यही घोड़ा बीच वाले सिपाही की रक्षा कर रहा था। भागने से बीच में छेद हो जाता है। काले के पास दूसरे बचाव भी थे, पर यह सबसे बुरा चुनाव था।",
        "15": "लाल तोप बीच वाले सिपाही को मारती है — शह! काला घोड़ा हटने से बीच पूरी तरह खुला था। यहाँ से लाल का हमला तेज़ी से आगे बढ़ता है।",
        "16": "काला जनरल के सामने को ढकने के लिए एक सलाहकार ऊपर लाता है। शह रोकने का यही एक अच्छा तरीक़ा है।",
        "17": "दूसरा लाल रथ भी उसी पंक्ति पर आ जाता है। एक पंक्ति पर एक के पीछे एक खड़े दो रथ बेहद ताक़तवर होते हैं। योजना है काले के इलाक़े की सबसे गहराई तक घुसना।",
        "18": "काला जनरल बगल में हट जाता है। वरना उसी पंक्ति पर खड़े दोनों लाल रथ उसे सीधे घूरते।",
        "19": "आगे वाला लाल रथ काले सलाहकार को मारता है — शह! दूसरा सलाहकार उसे तुरंत मार लेगा, पर यह योजना का हिस्सा है। लाल काले जनरल के पहरेदारों को तोड़ने के लिए एक रथ कुर्बान करता है। कितनी साहसी चाल!",
        "20": "काला सलाहकार से रथ को मार लेता है। मोहरों में काला बहुत आगे है। लेकिन जनरल का घर और भी ख़ाली हो गया।",
        "21": "आख़िरी लाल रथ जनरल की पंक्ति पर आता है — फिर शह। काले जनरल के पास बचाने वाला लगभग कोई मोहरा नहीं बचा।",
        "22": "काला शह रोकने के लिए जनरल के सामने एक तोप रखता है। बीच में ऐसे मोहरा रखने को “बीच में आना” कहते हैं।",
        "23": "लाल रथ उस तोप को मारता है — फिर शह। रथ काले मोहरों को मारते हुए जनरल को घेरता जाता है।",
        "24": "काला जनरल सिर्फ़ बीच में लौट सकता है। बाकी सब बिंदु लाल मोहरों के क़ब्ज़े में हैं।",
        "25": "आख़िर में लाल तोप बीच में आती है: एक पंक्ति पर दो तोपें — शह। आगे वाली तोप ओट बनती है और पीछे वाली जनरल पर वार करती है: यह “दोहरी तोप” की मात है। काले जनरल के पास कहीं जाने की जगह नहीं, और लाल जीतता है। सिर्फ़ एक घोड़ा देकर लाल तेरह चालों में जीत गया। 400 साल से यह बाज़ी सिखा रही है कि समय और सक्रिय मोहरे, मोहरों की गिनती से ज़्यादा मायने रख सकते हैं।"
      } }
  },
  "ar": {
    ui: {"lead":"مباريات عظيمة، نقلةً بعد نقلة. تابع على الرقعة مباريات مشهورة بينما يشرح Musowl كل نقلة.","all":"الكل","k_chess":"الشطرنج","k_shogi":"الشوغي","k_go":"الغو","k_xiangqi":"شيانغتشي","side_r":"الأحمر","res_r":"فوز الأحمر","back":"العودة إلى المباريات العظيمة","start":"البداية","prev":"نقلة إلى الوراء","next":"نقلة إلى الأمام","end":"النهاية","play":"تشغيل تلقائي","pause":"إيقاف","moves":"النقلات","move":"النقلة {n}","startpos":"وضع البداية","nextnote":"الشرح التالي (النقلة {n})","quiet":"لا يوجد شرح لهذه النقلة.","guide":"Musowl","keys":"← → للتنقل نقلةً نقلة","result":"النتيجة","r_event":"المباراة","r_date":"السنة","r_place":"المكان","side_w":"الأبيض","side_b":"الأسود","side_s":"سينتي","side_g":"غوتي","side_B":"الأسود","side_W":"الأبيض","res_w":"فوز الأبيض","res_b":"فوز الأسود","res_d":"تعادل","res_s":"فوز سينتي","res_g":"فوز غوتي","credit":"النقلات هي السجل المعروف لكل مباراة. الشروح من كتابة Musowl في المتحف."},
    "opera": { "t": "مباراة الأوبرا", "w": "بول مورفي", "b": "دوق برونزفيك كارل الثاني والكونت إيزوار", "ev": "لُعبت في مقصورة بدار أوبرا باريس (الحليفان يتشاوران معًا)", "d": "1858", "pl": "فرنسا (باريس)", "lead": "البطل الأمريكي الشاب في مواجهة نبيلَين، أثناء عرض في الأوبرا: سبع عشرة نقلة. أخرِج القطع بسرعة، وضحِّ بها دون تردد، وأنهِ المباراة بقطع قليلة جدًا. لا توجد مباراة تظهر في كتب الشطرنج أكثر منها.",
      c: {
        "0": "باريس، 1858. كان الأمريكي بول مورفي، ابن الحادية والعشرين، يهزم أقوى لاعبي أوروبا واحدًا تلو الآخر. في تلك الليلة، في مقصورة بدار الأوبرا، أخذ دوق برونزويك والكونت إيزوار القطع السوداء معًا وتحدّياه، يتشاوران في كل نقلة. ويُقال إن مورفي أراد أن ينهي المباراة بسرعة ليشاهد العرض. هذه النقلات السبع عشرة مليئة بالأساسيات: أخرِج القطع بسرعة وضع الملك في أمان.",
        "1": "يتقدّم الأبيض ببيدق الملك مربعين. ينظر إلى d5 وe5 في الوسط ويفتح الطريق للفيل والوزير.",
        "2": "يلعب الأسود e5 أيضًا. يتواجه البيدقان في الوسط، ولا يستطيع البيدق الأبيض التقدّم أكثر.",
        "3": "يخرج الحصان إلى f3 ويهاجم بيدق e5. نقلة جيدة: تطوّر قطعة وتجعل الخصم يفكّر في الدفاع.",
        "4": "يحمي الأسود e5 بـ d6. يُسمّى هذا دفاع فيليدور. إنه متين، لكنه يضيّق قليلًا طريق فيل f8.",
        "5": "يلعب الأبيض d4: بيدق آخر إلى الوسط في مواجهة e5. على الأسود أن يختار بين الأخذ والحماية.",
        "6": "الفيل الأسود إلى g4. يضغط على حصان f3 الواقع على خط واحد مع الوزير الأبيض في d1. إذا تحرّك الحصان ضاع الوزير، فلا يستطيع الحصان الذهاب إلى e5.",
        "7": "يأخذ الأبيض في e5 بالبيدق. لو استردّ الأسود فورًا ببيدق d6 لبادل الأبيض الوزيرين ثم أخذ الحصان بيدق e5. لذلك يريد الأسود أولًا التخلّص من حصان f3.",
        "8": "يأخذ الأسود الحصان بالفيل. صار بإمكانه الآن استرداد e5 بأمان. لكن مبادلة الفيل الذي خرج للتو بالحصان تجعل الأسود متأخرًا في التطوير.",
        "9": "يستردّ الأبيض بالوزير الذي يعمل بالفعل قرب الوسط، بينما لم يُخرج الأسود تقريبًا أي قطعة.",
        "10": "يستردّ الأسود ببيدق والعتاد متعادل. لكن الأبيض متقدّم في عدد القطع المطوَّرة.",
        "11": "الفيل إلى c4. مع وزير f3 يصوّب نحو f7. لا يحمي f7 إلا الملك، فهو مربع ضعيف: أخذه يعني كش مات.",
        "12": "يضع الأسود الحصان في f6 ويسدّ العمود f. لولا ذلك لأخذ الوزير f7 بكش مات. الدفاع مع التطوير هو الردّ الصحيح.",
        "13": "ينعطف الوزير إلى b3 ويهاجم f7 وb7 معًا. النقلة ذات التهديدين قوية لأن الخصم لا يستطيع صدّهما معًا.",
        "14": "يضع الأسود الوزير في e7 ليحمي f7 ويترك b7. لكن الوزير الآن يسدّ طريق فيل f8.",
        "15": "لا يأخذ مورفي بيدق b7، بل يُخرج حصانًا. لو أخذه لابتعد الوزير كثيرًا. تفضيل التطوير السريع على بيدق هو أسلوب مورفي تمامًا.",
        "16": "يلعب الأسود c6: يسيطر على d5 وb5 ويفتح طريقًا للوزير نحو b6.",
        "17": "الفيل إلى g5 يثبّت حصان f6. إذا تحرّك الحصان يمكن أخذ الوزير في e7 خلفه. صار تحريك قطع الأسود أصعب فأصعب.",
        "18": "يلعب الأسود b5 ليطرد فيل c4. يكسب مساحة في جناح الوزير، لكنه يفتح ثغرة لدخول قطع الأبيض.",
        "19": "يُضحّى بالحصان ليأخذ في b5! بدل سحب الفيل، يواصل مورفي الهجوم. والملك الأسود ما زال في الوسط، وهذا خطير جدًا على الأسود.",
        "20": "يأخذ الأسود الحصان ويتقدّم بحصان. لكن ملكه ما زال في e8، وقطع الأبيض تواصل التجمّع.",
        "21": "الفيل إلى b5، كش! الملك الأسود ما زال عالقًا في الوسط. للأبيض بيدقان مقابل الحصان، ويتّجه مباشرة نحو الملك.",
        "22": "يسدّ الأسود بالحصان في d7. لكن هذا الحصان مثبّت: إذا تحرّك صار الملك الأسود في كش. الآن سيصوّب الأبيض نحو d7.",
        "23": "يبيّت الأبيض في جهة الوزير. صار الملك آمنًا، وفي الوقت نفسه وصل الرخ إلى d1 ليصوّب نحو d7. نقلة واحدة تدافع وتهاجم: رائعة.",
        "24": "يضع الأسود الرخ في d8 ليحمي d7. ما زال لا يستطيع التبييت، والرخ في h8 والفيل في f8 لا يفعلان شيئًا.",
        "25": "يُضحّى بالرخ ليأخذ في d7! يعطي الأبيض رخًا ليزيل أحد مدافعي الأسود.",
        "26": "يستردّ الأسود بالرخ. الآن هذا الرخ في d7 مثبّت أيضًا: إذا تحرّك أعطى فيل b5 كشًّا للملك الأسود.",
        "27": "يصل الرخ الآخر إلى d1 ويهاجم d7 من جديد. صار عدد القطع البيضاء المهاجِمة لـ d7 أكثر من القطع السوداء المدافِعة.",
        "28": "الوزير الأسود إلى e6، يعرض مبادلة الوزيرين ليُبعد وزير b3 ويريد مساعدة d7. لكن الأوان قد فات.",
        "29": "يأخذ الفيل في d7 مع كش. يزيل الأبيض مدافعي الأسود واحدًا تلو الآخر.",
        "30": "يستردّ الأسود بالحصان. بعد مغادرة الحصان f6 انفتح القطر من فيل g5 إلى d8. وسيكون لهذا القطر دور في النهاية.",
        "31": "يُضحّى بالوزير في b8 مع كش! إنها أشهر نقلة في المباراة. لا بد أن يأخذ الأسود بالحصان، وعندما يغادر الحصان d7 ينفتح العمود d.",
        "32": "يأخذ الأسود بالحصان. الآن لا توجد قطعة سوداء تحمي d8.",
        "33": "الرخ إلى d8، كش مات! فيل g5 يدعم d8، والملك الأسود محاصر بقطعه نفسها فلا مهرب. أعطى الأبيض الوزير والرخ والفيل وأنهى برخ وفيل فقط. طوِّر بسرعة، أمِّن ملكك، وهاجم ما دام ملك الخصم في الوسط: تجمع هذه المباراة الشهيرة كل هذه الأفكار المهمة."
      } },
    "reti1910": { "t": "كش مات ريتي", "w": "ريتشارد ريتي", "b": "سافيلي تارتاكوفر", "ev": "مباراة ودية (ليست في بطولة)", "d": "1910", "pl": "النمسا (فيينا)", "lead": "لاعبان سيصبحان من كبار الأساتذة، في مباراة ودية في فيينا، إحدى عشرة نقلة. يضحّي الأبيض بالوزير وينهي المباراة بكش مزدوج: قطعتان تكشّان في الوقت نفسه. ويُسمّى هذا الشكل من الكش مات باسم الأبيض: كش مات ريتي.",
      c: {
        "0": "فيينا، 1910. الأبيض ريتشارد ريتي ابن العشرين، والأسود سافيلي تارتاكوفر. أصبح كلاهما من أفضل لاعبي العالم، ويُعرفان بإدخال أفكار جديدة إلى الشطرنج. لم تكن مباراة في بطولة، بل مباراة ودية على رهان صغير. إنها قصيرة، لكنها تُظهر بوضوح لماذا يجب تأمين الملك مبكرًا.",
        "1": "يتقدّم الأبيض ببيدق الملك مربعين. السيطرة على الوسط تسهّل خروج القطع الخلفية. وانفتح الطريق للفيل والوزير.",
        "2": "يلعب الأسود c6. بدل الذهاب إلى الوسط فورًا، يستعد لـ d5 لمهاجمة بيدق e4. يُسمّى هذا الافتتاح المتين دفاع كارو-كان.",
        "3": "يضع الأبيض البيدق الآخر في d4 أيضًا. بيدقان متجاوران في الوسط: للأبيض مساحة كبيرة. سيحاول الأسود تفكيكهما.",
        "4": "كما خُطّط، d5. البيدق يتحدّى e4: \"أستطيع أخذك\". على الأبيض أن يقرّر: الحماية أو التقدّم أو المبادلة.",
        "5": "يُخرج الأبيض حصانًا ليحمي e4. يطوّر قطعة ويدافع في الوقت نفسه دون إضاعة وقت.",
        "6": "يأخذ الأسود بيدق e4. بمبادلة بيادق الوسط يصغر وسط الأبيض.",
        "7": "يستردّ الأبيض بالحصان، فيقف في وسط الرقعة. الحصان في الوسط يصل إلى مربعات كثيرة وهو قوي جدًا.",
        "8": "يُخرج الأسود حصانًا في مواجهة حصان e4. يُلعب هنا غالبًا الفيل إلى f5، لكن الأسود يدعو إلى مبادلة الحصانين.",
        "9": "يخرج الوزير مبكرًا إلى d3 ليحمي حصان e4. عادةً لا يُخرَج الوزير بهذه السرعة، لكن للأبيض خطة. تذكّر أن هذا الوزير يقف على العمود d أمام الملك الأسود.",
        "10": "يلعب الأسود e5 ويعرض بيدقًا ليفتح الطريق للفيل والوزير. نقلة نشطة تُشعل القتال في الوسط.",
        "11": "يأخذ الأبيض بيدق e5. قبل الهدية، لكن الوزير الأسود صار أكثر حرية.",
        "12": "كش! الوزير الأسود في a5 يصوّب قطريًا نحو الملك في e1. وفي الوقت نفسه يريد استرداد بيدق e5: مهمتان في نقلة واحدة. على الأبيض أن يسدّ.",
        "13": "يسدّ الأبيض الكش بالفيل في d2. يمكن للوزير أخذ الفيل، لكن الوزير الأبيض يحميه جيدًا.",
        "14": "استردّ الأسود البيدق وعاد التعادل في العتاد. وهذا الوزير ينظر على العمود e إلى حصان e4 والملك خلفه. إذا تحرّك الحصان صار الملك في كش، فالحصان مقيّد. يبدو أن الأسود سيربحه قريبًا.",
        "15": "يبيّت الأبيض في جهة الوزير. يغادر الملك العمود e فيتحرّر الحصان. وفي الوقت نفسه يصل رخ إلى d1: الرخ في d1 والوزير في d3 والمربع d8 بجانب الملك الأسود صارت على خط واحد. هذا هو فخّ الأبيض.",
        "16": "يأخذ الأسود حصان e4 ويبدو أنه ربح قطعة. لكن الملك الأسود ما زال في e8 ولم يبيّت. قطع الأبيض مصطفّة على العمود d، والملك الأسود بلا حماية. هذه النقلة الخاسرة هي نقطة التحوّل.",
        "17": "الوزير إلى d8، كش! يقدّم الأبيض أقوى قطعه مجانًا. القطعة السوداء الوحيدة التي تستطيع أخذه هي الملك. بتركه يُؤخذ، يجرّ الأبيض الملك إلى المربع الخطِر d8.",
        "18": "لا بد أن يأخذ الأسود بالملك؛ لا طريقة أخرى لصدّ الكش. صار الملك في d8، ورخ d1 ينتظر خلفه.",
        "19": "يتحرّك الفيل من d2 إلى g5 بكش، وفي الوقت نفسه يفتح الطريق لرخ d1 الذي يكشّ أيضًا على العمود d. قطعتان تكشّان معًا: كش مزدوج. لا يمكن صدّه بأخذ قطعة ولا بالسدّ، فعلى الملك أن يهرب.",
        "20": "يهرب الملك إلى c7. لو ذهب إلى e8 لجاء الرخ إلى d8 وأعطى كش مات. أينما ذهب الملك، فالضربة الأخيرة جاهزة لدى الأبيض.",
        "21": "الفيل إلى d8: كش مات على القطر للملك في c7! الفيل يحميه رخ d1، فلا يستطيع الملك أخذه. مربعات مثل b8 وc8 وb7 وc6 مشغولة بقطع الأسود نفسه، والرخ يراقب d6 وd7. في إحدى عشرة نقلة فقط ضحّى الأبيض بالوزير وفاز بقطعتين صغيرتين. تعلّمنا هذه المباراة مدى خطورة السعي وراء العتاد قبل التبييت. وتقول بعض السجلات إن الأسود استسلم قبل ذلك بنقلة."
      } },
    "immortal": { "t": "المباراة الخالدة", "w": "أدولف أندرسن", "b": "ليونيل كيزيريتسكي", "ev": "مباراة غير رسمية في استراحة بطولة لندن 1851", "d": "1851", "pl": "المملكة المتحدة (لندن)", "lead": "لندن، أثناء أول بطولة شطرنج دولية: مباراة لُعبت في استراحة. يضحّي الأبيض بفيل ورخّين ثم بالوزير، ويعطي كش مات بالقطع الصغيرة الثلاث الباقية. ويُقال إن الأسود استسلم قبل النهاية، وإن النقلات الأخيرة هي الختام الذي عرضه الأبيض.",
      c: {
        "0": "لندن، 1851. في استراحة البطولة، لعب الألماني أندرسن (الأبيض) وكيزيريتسكي نجم باريس (الأسود) مباراة ودية.",
        "1": "يتقدّم الأبيض ببيدق الملك مربعين.",
        "2": "يفعل الأسود الشيء نفسه.",
        "3": "f4! يعرض الأبيض بيدقًا: إنه غامبيت الملك. الفكرة إبعاد بيدق الأسود في e5 عن الوسط.",
        "4": "يأخذ الأسود البيدق.",
        "5": "يخرج الفيل ويصوّب نحو f7 بجانب الملك الأسود.",
        "6": "كش! بعد غياب بيدق f الأبيض صار القطر من h4 إلى e1 مفتوحًا.",
        "7": "يتنحّى الملك جانبًا. لن يستطيع الأبيض التبييت بعد الآن.",
        "8": "يعرض الأسود بيدقًا أيضًا ليجذب الفيل إلى b5.",
        "9": "يأخذه الأبيض.",
        "10": "يخرج حصان ويهاجم بيدق e4.",
        "11": "يُخرج الأبيض حصانًا ويطرد الوزير من h4.",
        "12": "يتراجع الوزير إلى h6.",
        "13": "d3 يحمي e4 ويفتح الطريق لفيل c1.",
        "14": "الحصان إلى h5. الخطة القفز إلى g3 بكش ومهاجمة رخ h1.",
        "15": "الحصان الأبيض إلى h4، مستعدًا للقفز إلى f5 وإزعاج الوزير الأسود.",
        "16": "الوزير الأسود إلى g5 ويهاجم حصان h4.",
        "17": "الحصان إلى f5، مربع جيد يحميه بيدق e4. ويصوّب أيضًا نحو بيدق g7.",
        "18": "c6 يحاول طرد فيل b5.",
        "19": "لا ينقذ الأبيض الفيل: g4 يطارد حصان h5.",
        "20": "يعود الحصان إلى f6.",
        "21": "الرخ إلى g1 يحمي بيدق g4. ويترك الأبيض فيل b5 يذهب. يا لها من جرأة!",
        "22": "يأخذ الأسود الفيل ويتقدّم بقطعة كاملة.",
        "23": "يبدأ بيدق h بمطاردة الوزير الأسود.",
        "24": "الوزير إلى g6.",
        "25": "h5 يطارد الوزير مجددًا.",
        "26": "لا يستطيع الوزير إلا العودة إلى g5. مربعاته تقلّ شيئًا فشيئًا.",
        "27": "الوزير الأبيض إلى f3. إذا أخذ الفيل بعد ذلك في f4 فقد يُحاصَر الوزير الأسود.",
        "28": "يُعيد الأسود الحصان إلى g8 كي يهرب الوزير إلى f6.",
        "29": "يأخذ الفيل بيدق f4 ويهاجم الوزير.",
        "30": "يهرب الوزير إلى f6.",
        "31": "يخرج حصان، ينوي القفز إلى d5 لمهاجمة الوزير.",
        "32": "يخرج الفيل ويصوّب نحو رخ g1.",
        "33": "الحصان إلى d5 يهاجم الوزير في f6 والمربع c7. لا يبالي الأبيض بخسارة رخ g1.",
        "34": "يأخذ الوزير بيدق b2 ويهاجم رخ a1.",
        "35": "الفيل إلى d6! يترك الأبيض الرخّين معًا. وفي المقابل تنسج قطعه شبكة حول الملك الأسود.",
        "36": "يأخذ الأسود رخ g1.",
        "37": "e5! يسدّ هذا البيدق قطر الوزير من b2 إلى g7. لم يعد الوزير الأسود قادرًا على مساعدة ملكه.",
        "38": "يأخذ الأسود الرخ الآخر أيضًا مع كش.",
        "39": "الملك إلى e2. لم يبقَ للأبيض إلا الوزير وحصانان وفيل.",
        "40": "الحصان إلى a6 ليحمي c7. يُقال إن الأسود استسلم هنا تقريبًا، وإن ما يلي هو الختام الذي عرضه الأبيض.",
        "41": "يأخذ الحصان في g7 مع كش.",
        "42": "يهرب الملك إلى d8.",
        "43": "يُضحّى بالوزير في f6 مع كش! تذهب آخر قطعة كبيرة أيضًا.",
        "44": "لا بد أن يأخذ الأسود بالحصان.",
        "45": "الفيل إلى e7، كش مات! حصان d5 يسيطر على e7 وc7، وحصان g7 يسيطر على e8. يفوز الأبيض بفيل واحد وحصانين فقط."
      } },
    "mimiaka": { "t": "مباراة الأذنين المحمرّتين", "w": "هونينبو شوساكو", "b": "إينوي غينان إنسيكي", "ev": "مباراة في أوساكا (على ثلاثة أيام)", "d": "1846", "pl": "اليابان (أوساكا)", "lead": "واجه شوساكو، وهو في السابعة عشرة (4 دان)، غينان (8 دان)، أحد أقوى لاعبي عصره. يُروى أن أذني غينان احمرّتا عند النقلة 127، ومن هنا جاء الاسم. لم يكن هناك كومي آنذاك: فاز الأسود بنقطتين.",
      c: {
        "0": "أوساكا، 1846. شوساكو بالأسود وغينان بالأبيض. في اليوم السابق بدآ مباراة بحجرين مسبقين لكنها توقفت؛ وهذه المرة يلعب شوساكو بالأسود دون أفضلية.",
        "1": "الأسود 1 على نقطة 3-4 في الزاوية العليا اليمنى (R16)، وهي نقطة منخفضة تحمي الزاوية بسهولة.",
        "2": "الأبيض 2 على نقطة 3-4 في الزاوية العليا اليسرى (D17). يبدأ اللاعبان بتقاسم الزوايا الفارغة.",
        "5": "بالنقلات 1 و3 و5 أخذ الأسود ثلاث زوايا كلها على نقاط 3-4. كانت هذه افتتاحية شوساكو المفضلة، ودرسها اللاعبون بعده كثيرًا.",
        "6": "الأبيض 6 في C14 على الجهة اليسرى. بدل الاقتراب من زاوية الأسود يتمركز على الجانب، وهو اختيار غير مألوف قليلًا.",
        "7": "الأسود 7 (E4) يغلق الزاوية السفلى اليسرى بحجر ثانٍ. هذا «الإغلاق» يجعل الزاوية متينة جدًا.",
        "8": "الأبيض 8 (R5) يقترب من زاوية الأسود في Q3. معركة كبيرة على وشك أن تبدأ في الأسفل يمينًا.",
        "10": "الأبيض 10 (O4) هو «تايشا»: يغطي حجر الأسود قطريًا من بعيد. له تفرعات كثيرة جدًا، وكان المفضّل لدى غينان.",
        "11": "بالنقلة 11 (Q5) يدخل الأسود مسارًا صعبًا. كان غينان يعرف التايشا جيدًا، فعلى الأسود أن يتقدم بحذر.",
        "24": "في الأسفل يمينًا تشابكت الأحجار، وكل طرف يحاول قطع الآخر. بعد الأبيض 24 (N4) صار خروج أحجار الأسود صعبًا.",
        "25": "الأسود 25 (N3). تشير الدراسات اللاحقة إلى أن نقلة أفضل كانت ممكنة هنا. كان موقفًا صعبًا حتى على المحترف.",
        "28": "بالنقلتين 28 (M3) و30 (L2) يضرب الأبيض نقطة الضعف فورًا. قد تُحبس أحجار الأسود في مساحة ضيقة في الأسفل.",
        "31": "الأسود 31 (M4) نقلة مهمة. يستعد بها للـ«كو» القادم، أي معركة الأسر وإعادة الأسر، فيصنع تهديدات يجب على الأبيض الرد عليها.",
        "36": "الأبيض 36 (N2). قبل أن يبدأ الكو، يلعب الأبيض هنا أولًا. توقيت جيد.",
        "40": "الأبيض 40 (R1) يأسر حجرًا فيبدأ الكو. لا يجوز للطرف الذي خسر الحجر أن يستردّه فورًا، فيلعب أولًا تهديدًا في مكان آخر.",
        "41": "الأسود 41 (O5) تهديد كو. يكلّف قليلًا، لكن لا خيار أفضل هنا.",
        "53": "الأسود 53 (R10) فكرة بارعة قلّما يجدها أحد. تستهدف شكل الأبيض على الجانب الأيمن.",
        "60": "الأبيض 60 (S3) نقلة كبيرة، وتتيح له أيضًا لعب 62 (M1) مع الاحتفاظ بالمبادرة.",
        "63": "بعد الأسود 63 (O1) تهدأ المعركة الطويلة في الأسفل يمينًا. للأبيض أرض في الأسفل، وللأسود جدار سميك على اليمين. حتى الآن يبدو الأبيض أفضل.",
        "67": "الأسود 67 (L17). مستندًا إلى جداره على اليمين، يبني الأسود إطارًا كبيرًا في الأعلى.",
        "72": "الأبيض 72 (P13) نقلة رائعة. وُضع فوق جدار الأسود مباشرة، فيمنع إطار الأسود من التوسع.",
        "74": "من هنا حتى النقلة 100 تقريبًا لا يتهاون غينان أبدًا. يتفادى هجمات الأسود ويُبقي أحجاره متصلة.",
        "83": "الأسود 83 (H3) يدخل منطقة الأبيض في الأسفل ليقلّصها.",
        "96": "منذ الأبيض 96 (R14) تدور معركة دقيقة حول زاوية الأسود العليا اليمنى. ويجد الأبيض شكلًا جيدًا هنا أيضًا.",
        "107": "الأسود 107 (P10) يأسر حجرًا أبيض. مجموعة الأسود على اليمين صارت آمنة.",
        "118": "الأبيض 118 (M19) يأسر حجرًا، وتعيش مجموعته في الأعلى أيضًا. يبقى إطار الأسود في الأعلى أصغر مما كان مأمولًا.",
        "126": "الأبيض 126 (J5). الأبيض سميك في الأسفل ويمتد نحو الوسط. يُقال إن معظم المحترفين الحاضرين ظنّوا أن الأبيض متقدم.",
        "127": "هذه هي نقلة «الأذنين المحمرّتين» الشهيرة، الأسود 127 (K11). يُقال إن هذا الحجر في الوسط يعمل في أربعة اتجاهات معًا: يوسّع منطقة الأسود في الأعلى، ويُضعف سُمك الأبيض في الأسفل، ويساعد مجموعة الأسود على اليمين، ويمنع الأبيض من التمدد يسارًا.",
        "128": "في تلك اللحظة لاحظ طبيب كان يشاهد المباراة أن أذني غينان احمرّتا. لم يكن يعرف الكثير عن الغو، لكنه يُروى أنه رأى في ذلك علامة اضطراب وتوقّع فوز الأسود.",
        "131": "الأسود 131 (D10). يدخل الأسود الآن الجانب الأيسر للأبيض أيضًا، ويقلّص أرض الأبيض في كل اللوحة.",
        "147": "الأسود 147 (K10). يبدأ حجر النقلة 127 في إثبات قيمته، إذ يتقدم الأسود بين مجموعات الأبيض في الوسط.",
        "160": "الأبيض 160 (H8). يحمي الأبيض أحجاره في الوسط وعينه على مجموعة الأسود في الأسفل يسارًا. ما زالت المباراة متقاربة.",
        "167": "الأسود 167 (C2) نقلة دقيقة. صارت أحجار الأسود في الزاوية السفلى اليسرى آمنة، وزال تهديد الأبيض.",
        "175": "الأسود 175 (G4) يأسر حجرًا أبيض. أرض الأبيض في الأسفل ليست كبيرة كما بدت أولًا.",
        "199": "الأسود 199 (K7). تهدأ معركة الوسط وتدخل المباراة مرحلة النهاية: تثبيت الحدود، حيث تهم كل نقطة.",
        "212": "بالنقلتين 212 (D19) و216 (F19) يأسر الأبيض أحجارًا سوداء على الحافة العليا. في النهاية لا يتنازل أحد عن شيء.",
        "228": "الأبيض 228 (N12) يصنع كو في الوسط. لأكثر من 80 نقلة يتناوب الطرفان الأسر في M13 وN13.",
        "236": "الأبيض 236 (T8)، أثناء الكو، يأسر حجرًا. يرى بعض المحللين أن إنهاء الكو هنا كان سيجعل الفارق أصغر.",
        "275": "الأسود 275 (T14) يأسر حجرين أبيضين. أثناء الكو يكسب كل طرف هنا ويخسر هناك في أنحاء اللوحة.",
        "299": "الأسود 299 (J16) يأسر أربعة أحجار بيضاء دفعة واحدة. ويحكم الأسود قبضته على الأعلى.",
        "311": "الأسود 311 (M13) يغلق الكو. وتنتهي أخيرًا معركة الكو الطويلة.",
        "325": "تنتهي المباراة بعد 325 نقلة، ويُظهر العدّ تقدّم الأسود بنقطتين. ورغم غياب الكومي، أحدث فوز فتى في السابعة عشرة على لاعب بمستوى غينان ضجة كبيرة، وذاع اسم شوساكو."
      } },
    "evergreen": { "t": "المباراة دائمة الخضرة", "w": "أدولف أندرسن", "b": "جان دوفرين", "ev": "مباراة ودية (ليست في بطولة)", "d": "1852", "pl": "ألمانيا (على الأرجح برلين)", "lead": "أندرسن، صاحب المباراة الخالدة، لعب هذه التحفة الأخرى بعد عام. في اللحظة التي يهدّد فيها الأسود بالكش مات، يحرّك الأبيض رخًا بهدوء، ثم يضحّي بالوزير وينهي بكش مزدوج. تُسمّى \"دائمة الخضرة\" لأنها لا تذبل أبدًا.",
      c: {
        "0": "مباراة نُشرت في مجلة عام 1852. الأبيض أندرسن، والأسود صديقه دوفرين. يُعتقد أنها لُعبت في برلين، لكن لا يوجد سجل يؤكد ذلك.",
        "1": "يتقدّم الأبيض ببيدق الملك مربعين.",
        "2": "يفعل الأسود الشيء نفسه.",
        "3": "الحصان يهاجم بيدق e5.",
        "4": "يحمي الأسود e5 بحصان.",
        "5": "يخرج الفيل ويصوّب نحو f7.",
        "6": "يُخرج الأسود فيلًا أيضًا.",
        "7": "b4! عرض بيدق يُسمّى غامبيت إيفانز. بينما يأخذه الأسود، يقوّي الأبيض الوسط.",
        "8": "يأخذ الأسود البيدق.",
        "9": "c3 يطارد الفيل ويستعد لـ d4.",
        "10": "يتراجع الفيل إلى a5.",
        "11": "d4 يحتل الوسط.",
        "12": "يأخذ الأسود البيدق.",
        "13": "لا يستردّ الأبيض، بل يبيّت. سلامة الملك ونشاط القطع قبل البيادق.",
        "14": "يتقدّم البيدق الأسود حتى d3، في عمق معسكر الأبيض.",
        "15": "الوزير إلى b3. مع فيل c4 يصوّب نحو f7.",
        "16": "يحمي الأسود f7 بالوزير.",
        "17": "e5 يطارد الوزير.",
        "18": "الوزير إلى g6.",
        "19": "الرخ إلى e1، على العمود e ليدعم بيدق e5.",
        "20": "يُخرج الأسود حصانًا استعدادًا للتبييت.",
        "21": "الفيل إلى a3 يصوّب قطريًا نحو حصان e7. إذا تحرّك هذا الحصان وصل الفيل إلى f8، فصار التبييت القصير صعبًا على الأسود.",
        "22": "يعرض الأسود بيدقًا ليُبعد قطع الأبيض.",
        "23": "يأخذه الوزير.",
        "24": "الرخ إلى b8 يطارد الوزير على العمود b.",
        "25": "الوزير إلى a4.",
        "26": "يتراجع الفيل إلى b6.",
        "27": "يخرج حصان. صارت كل قطع الأبيض تقريبًا في اللعب.",
        "28": "يُخرج الأسود الفيل الآخر.",
        "29": "الحصان إلى e4، وعينه على f6.",
        "30": "الوزير الأسود إلى f5 ويهاجم حصان e4.",
        "31": "يأخذ الفيل بيدق d3 ويحمي حصان e4.",
        "32": "الوزير إلى h5 يصوّب نحو حصان f3.",
        "33": "يُضحّى بالحصان في f6 مع كش!",
        "34": "يأخذ الأسود ببيدق.",
        "35": "يستردّ الأبيض ببيدق ويهاجم حصان e7. وعلى العمود e يراقب رخ e1 المربع e7 أيضًا.",
        "36": "الرخ إلى g8 يصوّب نحو g2. إذا أخذ وزير h5 في f3 صار الكش مات قريبًا.",
        "37": "نقلة رخ هادئة إلى d1! ملك الأبيض في خطر، لكن بدل الدفاع يصوّب الأبيض نحو d7. هذه النقلة هي ما جعل المباراة \"دائمة الخضرة\".",
        "38": "يأخذ الأسود حصان f3. الأخذ في g2 بعدها سيكون كش مات.",
        "39": "لكن الدور للأبيض أولًا. يأخذ الرخ حصان e7 مع كش!",
        "40": "يستردّ الأسود بالحصان من c6. صار القطر من a4 إلى d7 مفتوحًا.",
        "41": "يُضحّى بالوزير في d7 مع كش!",
        "42": "لا بد أن يأخذ الأسود بالملك.",
        "43": "يتحرّك الفيل إلى f5 بكش ويفتح العمود d لرخ d1: كش مزدوج.",
        "44": "الملك إلى e8. لو ذهب إلى c6 لأعطى الفيل كش مات في d7.",
        "45": "الفيل إلى d7، كش.",
        "46": "الملك إلى f8.",
        "47": "فيل a3 يأخذ حصان e7: كش مات! فيل d7 يسيطر على e8، وبيدق f6 يسيطر على e7 وg7."
      } },
    "lasker1912": { "t": "صيد الملك", "w": "إدوارد لاسكر", "b": "جورج آلان توماس", "ev": "مباراة سريعة ودية في نادي مدينة لندن للشطرنج", "d": "1912", "pl": "المملكة المتحدة (لندن)", "lead": "مباراة سريعة وودية في نادٍ بلندن. يضحّي الأبيض بالوزير ويطارد الملك الأسود عبر الرقعة كلها، من g8 إلى g1. تختلف ترتيبات نقلات الافتتاح قليلًا بين السجلات، لكن الوضع بعد النقلة العاشرة هو نفسه.",
      c: {
        "0": "أكتوبر 1912، نادي مدينة لندن للشطرنج. الأبيض إدوارد لاسكر، مهندس شاب وصل لتوّه من ألمانيا، والأسود جورج آلان توماس الذي صار لاحقًا بطل بريطانيا. كانت مباراة سريعة وودية. وهي مشهورة باسم \"صيد الملك\": يُطارَد الملك الأسود من g8 حتى g1 في الطرف الآخر من الرقعة. انتقل لاسكر لاحقًا إلى أمريكا واشتهر بكتبه في الشطرنج.",
        "1": "يبدأ الأبيض بـ d4، بيدق الوزير. يسيطر على e5 وc5 ويفتح الطريق لفيل c1.",
        "2": "يلعب الأسود e6: وضع متين أولًا، مع التحضير لـ f5 أو d5.",
        "3": "الحصان إلى f3. يسيطر على e5 ويساعد في حماية جناح الملك: أكثر المربعات طبيعية.",
        "4": "يلعب الأسود f5 ويسيطر على e4، كما في الدفاع الهولندي. لكن تحريك بيدق أمام الملك يُضعفه قليلًا.",
        "5": "الحصان الآخر إلى c3، استعدادًا لـ e4 لضرب بيدق f5.",
        "6": "يُخرج الأسود حصانًا إلى f6: يزيد سيطرته على e4 ويستعد للتبييت.",
        "7": "الفيل إلى g5 يصوّب نحو حصان f6. هذا الحصان مدافع مهم عن الملك الأسود، لذا يريد الأبيض إزالته مبكرًا.",
        "8": "يضع الأسود الفيل في e7 ليحمي الحصان ويقترب من التبييت.",
        "9": "يبادل الأبيض الفيل بالحصان. اختفى الحصان الذي كان يحمي الملك الأسود.",
        "10": "يستردّ الأسود بالفيل. الآن يتولّى فيل f6 حماية جناح الملك.",
        "11": "e4! يضرب الأبيض بيدق f5 ويكسب مساحة في الوسط. تنفتح الخطوط وتتحرّك قطع الأبيض بحرية أكبر.",
        "12": "يأخذ الأسود بيدق e4. وإلا لعب الأبيض e5 ودفع قطع الأسود إلى الخلف.",
        "13": "يستردّ الحصان ويستقر في الوسط، ينظر إلى فيل f6 والمربعين g5 وd6.",
        "14": "يلعب الأسود b6 ليضع الفيل في b7 ويصوّب على القطر الطويل نحو حصان e4.",
        "15": "الحصان إلى e5، مربع قوي في الوسط يرى أيضًا g4 وf7. صار الحصانان الأبيضان قريبين من جناح ملك الأسود.",
        "16": "يبيّت الأسود. الملك في g8. لكن بغياب بيدق f توجد ثغرات كثيرة حول الملك.",
        "17": "الفيل إلى d3. حصانه في e4 يعترضه الآن، لكن خلفه بيدق h7. ما إن يتحرّك حصان e4 حتى يصوّب هذا الفيل مباشرة نحو h7.",
        "18": "الفيل الأسود إلى b7 يصوّب على القطر الطويل نحو حصان e4 ويقيّد قطع الأبيض.",
        "19": "الوزير إلى h5 يصوّب نحو بيدق h7 الذي لا يحميه إلا الملك الأسود. وزير الأبيض وفيله وحصاناه كلها موجّهة نحو الملك الأسود.",
        "20": "يضع الأسود الوزير في e7. يحمي فيل f6 ويستعد للذهاب إلى c5، لكنه لا يرى فكرة الأبيض. كان لا بد من h6 أو أخذ حصان e5. هذه نقطة التحوّل.",
        "21": "يُضحّى بالوزير في h7 مع كش! يقدّم الأبيض أقوى قطعه مجانًا. كان لاسكر يرى الطريق كله لمطاردة الملك حتى الكش مات.",
        "22": "لا بد أن يأخذ الأسود بالملك، فيصير الملك في h7.",
        "23": "يأخذ الحصان فيل f6 مع كش. وفي الوقت نفسه يخلو e4، فيكشّ فيل d3 أيضًا الملك في h7: كش مزدوج. لا يمكن سدّه، فعلى الملك أن يهرب.",
        "24": "الملك إلى h6. لو ذهب إلى h8 لقفز الحصان الآخر إلى g6 بكش مات. يُدفع الملك إلى الأمام أكثر فأكثر.",
        "25": "يقفز الحصان الآخر من e5 إلى g4 بكش، يهاجم الملك في h6 ويدفعه أبعد.",
        "26": "الملك إلى g5: يترك معسكره ويمشي نحو جهة الأبيض.",
        "27": "كش ببيدق h! حتى البيادق تشارك في الصيد. على الملك أن يواصل التقدّم.",
        "28": "الملك إلى f4. عبر منتصف الرقعة ويدخل معسكر الأبيض.",
        "29": "كش مرة أخرى ببيدق g. بيدقان يسدّان طريق العودة على الملك.",
        "30": "الملك إلى f3، في وسط قطع الأبيض تمامًا.",
        "31": "يتراجع الفيل من d3 إلى e2 بكش. يُدفع الملك إلى عمق أكبر.",
        "32": "الملك إلى g2. لم يعد الملك الأبيض في e1 بعيدًا.",
        "33": "الرخ إلى h2، كش. أخيرًا يدخل الرخ اللعب.",
        "34": "يصل الملك أخيرًا إلى g1. انطلق من g8 وبلغ الصف الأول في الطرف الآخر من الرقعة.",
        "35": "يتحرّك الملك الأبيض من e1 إلى d2. ينفتح بذلك طريق رخ a1 الذي يكشّ الملك في g1 على الصف الأول: كش مات! كان التبييت الطويل سيعطي كش مات أيضًا، لكن لاسكر حرّك الملك. في مباراة سريعة، وبعد التضحية بالوزير، طارد الأبيض الملك أربع عشرة نقلة حتى أعمق زاوية في معسكره. مباراة نادرة جدًا."
      } },
    "toketsu": { "t": "مباراة الدم", "w": "أكابوشي إنتيتسو", "b": "هونينبو جووا", "ev": "لُعبت في دار السيد ماتسودايرا حاكم سوو (على أربعة أيام)", "d": "1835", "pl": "اليابان (إيدو)", "lead": "مباراة وُلدت من الصراع على منصب «ميجين غودوكورو»، أعلى منصب في الغو الياباني. أرسل إينوي غينان إنسيكي تلميذه أكابوشي إنتيتسو لمواجهة الميجين جووا. بعد أربعة أيام من القتال خسر إنتيتسو، ويُروى أنه سعل دمًا أمام اللوحة.",
      c: {
        "0": "1835. الأسود: أكابوشي إنتيتسو (7 دان)، والأبيض: الميجين هونينبو جووا. أرسل غينان أفضل تلاميذه ليقول إن ميجين يخسر أمام لاعب 7 دان لا يستحق اللقب.",
        "1": "الأسود 1 على نقطة 3-4 في الأسفل يسارًا (C4). يبدأ إنتيتسو بهدوء.",
        "4": "بعد أربع نقلات في كل زاوية حجر: الأبيض في الأسفل يمينًا والأعلى يسارًا، والأسود في الأسفل يسارًا والأعلى يمينًا.",
        "6": "الأبيض 6 (E3) يقترب مبكرًا من زاوية الأسود السفلى اليسرى. جووا نشِط منذ البداية.",
        "10": "الأبيض 10 (P4) يغلق الزاوية السفلى اليمنى بحجر ثانٍ.",
        "12": "الأبيض 12 (D6) يضغط من الأعلى على زاوية الأسود السفلى اليسرى. هنا تبدأ أكبر معارك المباراة.",
        "13": "الأسود 13 (E4) يلتصق مباشرة بحجر أبيض. يقبل الأسود القتال.",
        "20": "الأبيض 20 (C3) يتسلل تحت زاوية الأسود: يقتطع من أرض الزاوية ويحاول في الوقت نفسه إحياء أحجاره.",
        "28": "الأبيض 28 (C9) يمتد بعيدًا على الجانب الأيسر. كثيرًا ما يُعدّ تمددًا مبالغًا فيه، نقلة عنيفة على طريقة جووا.",
        "33": "الأسود 33 (C2). يُروى أنها تفرّعة جديدة درستها مدرسة إينوي سرًّا. تهاجم أحجار الأبيض العائمة في الوسط وتبتلع في الوقت نفسه أحجاره على الجانب الأيسر.",
        "36": "الأبيض 36 (F3). يحاول الأبيض حصر الأسود من الخارج في الأسفل يسارًا مع وصل أحجاره.",
        "43": "الأسود 43 (E9). أحجار الأبيض على اليسار في ورطة. حتى الآن لعب إنتيتسو جيدًا ويُعتقد أنه تقدّم.",
        "45": "الأسود 45 (D11) يمتد صعودًا على الجانب الأيسر، فيُبقي أحجار الأبيض منفصلة ويقوّي أحجاره.",
        "50": "الأبيض 50 (C16). يترك الأبيض الأسفل يسارًا مؤقتًا ويتجه إلى الزاوية العليا اليسرى.",
        "53": "الأسود 53 (G17). يدخل الأسود الجانب العلوي كي لا يوسّع الأبيض الزاوية العليا اليسرى.",
        "58": "الأبيض 58 (C14) يمتد من الزاوية العليا اليسرى على طول الجانب ويقترب من أحجار الأسود على اليسار.",
        "60": "الأبيض 60 (G4) يأسر حجرين أسودين. تتنفس مجموعة الأبيض في الأسفل يسارًا قليلًا أخيرًا.",
        "62": "الأبيض 62 (J17). يتواجه الطرفان في الأعلى أيضًا. هناك أحجار ضعيفة في كل مكان: موقف صعب.",
        "66": "الأبيض 66 (B14). حول الزاوية العليا اليسرى يعمل الأبيض على تثبيت أحجاره.",
        "68": "الأبيض 68 (B11). اشتهرت نقلات الأبيض التالية، مع النقلة 80، بأنها نقلات جووا العبقرية. كانت مدهشة لدرجة أن الناس قالوا إن الأشباح هي التي أرتها له.",
        "70": "الأبيض 70 (E12). بدل الرد على الأسود مباشرة في اليسار، يلعب الأبيض أولًا نقطة مفتاحية أخرى. الإمكانيات الخفية المتبقية تسمح بذلك.",
        "72": "الأبيض 72 (R13). يتجه الأبيض إلى الجانب الأيمن كي لا تكبر منطقة الأسود في الأعلى يمينًا.",
        "76": "الأبيض 76 (O14). يربط الأبيض الجانب الأيمن بالوسط ويستعد لتقسيم أحجار الأسود.",
        "80": "الأبيض 80 (Q10) يصنع «مثلثًا فارغًا»، وهو شكل يُعدّ سيئًا عادة. لكن هذه النقلة صارت قاعدة لشطر الأسود نصفين ومهاجمته. وهي المثال الكلاسيكي على نقلة قبيحة المظهر لكنها ممتازة.",
        "83": "الأسود 83 (R3) يدخل زاوية الأبيض السفلى اليمنى، فتندلع هناك معركة شرسة من الأسر وإعادة الأسر.",
        "91": "الأسود 91 (Q4) يأسر حجرًا أبيض. الزاوية السفلى اليمنى مهمة جدًا للأسود.",
        "98": "الأبيض 98 (M4). يطوّق الأبيض أحجار الأسود في الأسفل ولا يدعها تعيش بسهولة.",
        "106": "الأبيض 106 (S5) يأسر حجرًا أسود. يحتفظ الأبيض بالزاوية السفلى اليمنى، وعلى أحجار الأسود الهرب إلى الخارج.",
        "113": "الأسود 113 (K6). تبحث أحجار الأسود في الأسفل عن الحياة بالخروج نحو الوسط.",
        "120": "الأبيض 120 (N9) يسدّ طريق أحجار الأسود الهاربة. في الوسط صار السؤال: أيّ الأحجار تضعف أولًا؟",
        "128": "الأبيض 128 (L11) يضغط أحجار الأسود في الوسط من الأعلى أيضًا. لا يستطيع الأسود الاطمئنان بعد.",
        "138": "الأبيض 138 (K8) يأسر حجرًا فيبدأ كو في الوسط. لنحو 30 نقلة يتناوب الطرفان الأسر في K8 وL8.",
        "152": "الأبيض 152 (E11) تهديد كو. أثناء الكو يجد الأبيض في كل مكان نقلات يجب على الأسود الرد عليها.",
        "170": "الأبيض 170 (P15). هدأ كو الوسط، فيتجه الأبيض إلى الأعلى يمينًا مستهدفًا مجموعة سوداء كبيرة لم تعش تمامًا بعد.",
        "178": "الأبيض 178 (J14) يقفز إلى وسط المنطقة العليا ليفصل أحجار الأسود يمينًا ويسارًا. الهجوم الفاصل الذي حُضّر منذ النقلة 80 يبدأ الآن بجدية.",
        "193": "الأسود 193 (J11) يأسر حجرًا أبيض. يقاتل الأسود بشدة ليتصل ويعيش.",
        "201": "الأسود 201 (R14) يأسر حجرًا فيبدأ كو جديد على الجانب الأيمن، بأسرٍ متبادل في R14 وR15.",
        "206": "الأبيض 206 (M13). حتى أثناء الكو يشدّ الأبيض الخناق تدريجيًا على أحجار الأسود في الوسط.",
        "222": "الأبيض 222 (L14) يأسر حجرًا. تبقى أحجار الأسود في الأعلى منقسمة، وإنقاذ القسمين معًا يزداد صعوبة.",
        "230": "الأبيض 230 (C13) يضرب نقطة ضعف الأسود على الجانب الأيسر أيضًا. أحجار الأبيض صارت متصلة بقوة في أنحاء اللوحة.",
        "237": "بالنقلتين 237 (F12) و239 (E13) يستردّ الأسود أحجارًا في الأعلى يسارًا. ومع ذلك لا يتقلص الفارق الكلي.",
        "246": "بعد الأبيض 246 (L8) استسلم إنتيتسو. يُروى أنه سعل دمًا على اللوحة أثناء جمع الأحجار. ربما كان مريضًا منذ مدة، وتوفي بعد ذلك بقليل. وتُعدّ هذه المباراة أعظم انتصار في حياة جووا."
      } },
    "deepblue1997": { "t": "انتصار ديب بلو", "w": "ديب بلو (حاسوب IBM)", "b": "غاري كاسباروف", "ev": "المباراة السادسة من مواجهة الثأر مع ديب بلو من IBM (لقاء من ست مباريات)", "d": "1997", "pl": "الولايات المتحدة (نيويورك)", "lead": "بطل العالم كاسباروف في مواجهة ديب بلو، حاسوب شطرنج صنعته IBM، في لقاء من ست مباريات. كانت النتيجة متعادلة بعد خمس مباريات، وانتهت الأخيرة في 19 نقلة فقط. كانت أول مرة يهزم فيها حاسوب بطل العالم في لقاء كامل من عدة مباريات.",
      c: {
        "0": "نيويورك، 11 مايو 1997. فاز كاسباروف بلقائهما في العام السابق. هذه المرة النتيجة 2½–2½ بعد خمس مباريات. ديب بلو بالأبيض.",
        "1": "يتقدّم الأبيض ببيدق الملك مربعين.",
        "2": "يلعب كاسباروف c6: دفاع كارو-كان.",
        "3": "يضع الأبيض البيدق الآخر في الوسط.",
        "4": "يلعب الأسود d5 ضد e4.",
        "5": "الحصان يحمي e4.",
        "6": "يأخذ الأسود بيدق e4.",
        "7": "يستردّ الحصان.",
        "8": "يضع الأسود حصانًا في d7 ليُخرج الحصان الآخر إلى f6 بعد ذلك.",
        "9": "يقفز الحصان إلى g5: خطة حادّة تصوّب نحو f7 وe6.",
        "10": "يُخرج الأسود الحصان إلى f6.",
        "11": "الفيل إلى d3 ينظر إلى جناح ملك الأسود.",
        "12": "يقوّي الأسود الدفاع بـ e6.",
        "13": "يخرج الحصان الآخر إلى f3.",
        "14": "يلعب الأسود h6 لطرد حصان g5. لكن في هذا الوضع كانت التضحية بالحصان للأبيض معروفة من قبل. ويُقال إنه كان اختيارًا غريبًا من كاسباروف.",
        "15": "يُضحّى بالحصان في e6! يُقال إن ديب بلو لعب هذه النقلة من نقلات الافتتاح المخزّنة لديه مسبقًا.",
        "16": "لا يأخذ الأسود فورًا، بل يضع الوزير في e7. على العمود e يصوّب نحو حصان e6 والملك الأبيض خلفه.",
        "17": "يبيّت الأبيض ويضع ملكه في أمان.",
        "18": "يأخذ الأسود الحصان ويتقدّم في العتاد.",
        "19": "الفيل إلى g6، كش. بغياب بيدق f7 يصل القطر إلى الملك.",
        "20": "الملك إلى d8. لم يعد الأسود قادرًا على التبييت، وبقي الملك قرب الوسط.",
        "21": "يخرج الفيل الآخر ويصوّب نحو المربعات حول الملك الأسود.",
        "22": "يلعب الأسود b5 ليفسح مكانًا في جناح الوزير للملك والفيل.",
        "23": "a4 يضرب بيدق b5.",
        "24": "يضع الأسود الفيل في b7.",
        "25": "الرخ إلى e1. على العمود e ينظر إلى بيدق e6، وخلفه إلى الوزير في e7.",
        "26": "الحصان الأسود إلى d5 ويهاجم فيل f4.",
        "27": "يتراجع الفيل إلى g3.",
        "28": "الملك الأسود إلى c8، أكثر أمانًا قليلًا.",
        "29": "يأخذ الأبيض بيدق b5.",
        "30": "يستردّ الأسود.",
        "31": "الوزير إلى d3 ينظر إلى بيدق b5 والمربع f5.",
        "32": "يحمي الأسود b5 بالفيل.",
        "33": "الفيل إلى f5! يمكن أخذه مجانًا.",
        "34": "يأخذ الأسود ببيدق. لكن بذلك يختفي بيدق العمود e.",
        "35": "يأخذ الرخ الوزير في e7. أعطى الأبيض حصانًا وفيلًا ورخًا، لكنه كسب الوزير.",
        "36": "يستردّ الأسود الرخ بالفيل.",
        "37": "c4! يضرب البيدق b5 وd5 معًا، ويبدأ دفاع الأسود بالانهيار. استسلم كاسباروف هنا، ربما لأنه رأى ملكه مكشوفًا أكثر من أن يوقف الهجوم. لقد فاز حاسوب بلقاء ضد بطل العالم."
      } },
    "seigen1933": { "t": "مباراة 3-3 ونقطة النجم والتنغن", "w": "غو سيغن", "b": "هونينبو شوساي", "ev": "مباراة تذكارية مع الميجين (أكثر من ثلاثة أشهر)", "d": "1933–1934", "pl": "اليابان (طوكيو)", "lead": "لعب غو سيغن، وهو في التاسعة عشرة (5 دان)، ضد الميجين هونينبو شوساي. بالأسود افتتح على نقطة 3-3، ثم على نقطة نجم، ثم في المركز تمامًا (تنغن)، محطّمًا أعراف زمانه ومُدهشًا عالم الغو. مع توقفات كثيرة استمرت المباراة أكثر من ثلاثة أشهر، وفاز الأبيض بنقطتين.",
      c: {
        "0": "1933. في ذلك العام كان غو سيغن وصديقه كيتاني مينورو ينشران أسلوب افتتاح جديدًا يُسمّى «شين فوسيكي». أراد الجميع أن يروا كيف سيستعمله أمام الميجين.",
        "1": "الأسود 1 على نقطة 3-3 في الأعلى يمينًا (R17). يضمن الزاوية بنقلة واحدة، لكن تأثيره نحو الخارج ضعيف، ولم يكن أحد آنذاك يراه نقلة افتتاح.",
        "3": "الأسود 3 على نقطة النجم في الأسفل يسارًا (D4). على عكس 3-3، يهتم بالتوسع نحو الخارج.",
        "5": "الأسود 5 يذهب إلى مركز اللوحة تمامًا: التنغن (K10). لا زاوية ولا جانب، بل الوسط. أمام الميجين عرض غو سيغن أفكاره الجديدة صراحة.",
        "6": "3-3 والنجم والتنغن: لكل حجر أسود دور مختلف: أرض الزاوية، والامتداد نحو الخارج، وقوة الوسط. بالنقلة 6 (Q16) يلعب الأبيض بجوار حجر 3-3 الأسود مباشرة.",
        "9": "الأسود 9 (P18). يستقر الأسود في الزاوية العليا اليمنى بشكل مضغوط وآمن، أسلوب يقدّم الأرض أولًا كما يليق بنقطة 3-3.",
        "11": "الأسود 11 (K4) في منتصف الجانب السفلي تحت التنغن مباشرة. بالتعاون معه يطمح الأسود إلى منطقة كبيرة في الأسفل.",
        "12": "الأبيض 12 (M3) يدخل فورًا الجانب السفلي كي لا يبني الأسود إطارًا كبيرًا. يحافظ الميجين على هدوئه ويفكك خطط الأسود واحدة تلو الأخرى.",
        "13": "الأسود 13 (D10)، هذه المرة في منتصف الجانب الأيسر. أحجار الأسود عالية وتشكّل معًا إطارًا واسعًا.",
        "14": "الأبيض 14 (E16) يغلق الزاوية العليا اليسرى بحجر ثانٍ. لا يرتبك الميجين أمام الأسلوب الجديد ويؤمّن الزاوية بهدوء.",
        "21": "الأسود 21 (G10) يربط التنغن بحجر الجانب الأيسر، فينتشر نفوذ الأسود في الوسط.",
        "28": "الأبيض 28 (D3) يتسلل تحت حجر النجم الأسود في الأسفل يسارًا ويأخذ الزاوية. يتنازل الأسود عنها مقابل قوة في الخارج.",
        "30": "الأبيض 30 (Q12) يمتد على الجانب الأيمن ويضع غطاءً فوق زاوية 3-3 السوداء، فيُضعف امتدادها.",
        "37": "الأسود 37 (P15) يأسر حجرًا أبيض. في الأعلى يمينًا يتصادم الطرفان في معركة متقاربة.",
        "40": "الأبيض 40 (O10) يخرج من الجانب الأيمن نحو الوسط ويقترب من نفوذ الأسود حول التنغن.",
        "44": "الأبيض 44 (H17) يحتل نقطة على الجانب العلوي ليوقف امتداد الأسود نحو الأعلى.",
        "45": "الأسود 45 (R7) يبدأ العمل على موقع الأبيض في الأسفل يمينًا. تتبعه معركة طويلة من الجانب الأيمن نزولًا إلى تلك الزاوية.",
        "59": "الأسود 59 (R4) يدخل الزاوية السفلى اليمنى أيضًا ويقلّص أرض الأبيض.",
        "70": "الأبيض 70 (N6) يتقدم من الجانب السفلي نحو الوسط ليفصل أحجار الأسود في الأسفل يمينًا عن أحجار الوسط.",
        "79": "الأسود 79 (L9) يقوّي الوسط حول حجر التنغن. حتى الآن تبدو المباراة متوازنة إلى حد كبير.",
        "80": "الأبيض 80 (C6) يصعد من الزاوية السفلى اليسرى على الجانب الأيسر مستهدفًا أحجار الأسود هناك.",
        "98": "الأبيض 98 (A11) يأسر حجرين أسودين. يعيش الأبيض بإتقان على الحافة اليسرى، ويصبح جانب الأسود الأيسر أصغر مما خُطّط له.",
        "101": "الأسود 101 (S14) يعود إلى الأعلى يمينًا ليقلّص موقع الأبيض على الجانب الأيمن.",
        "105": "الأسود 105 (K17) يحتل منتصف الجانب العلوي ويبدأ مهاجمة أحجار الأبيض هناك.",
        "117": "الأسود 117 (F17) يدخل أيضًا محيط زاوية الأبيض العليا اليسرى، فيتحول الجانب العلوي كله إلى ساحة قتال.",
        "124": "الأبيض 124 (K15) يقود أحجاره العليا نحو الوسط ويقطع بين أحجار الأسود في طريقه.",
        "135": "الأسود 135 (E9) يأسر حجرين أبيضين. يستعيد الأسود شيئًا على الجانب الأيسر.",
        "138": "الأبيض 138 (N18) يثبّت أرضًا على الجانب العلوي. على اللوحة كلها الوضع متقارب جدًا.",
        "153": "الأسود 153 (K14). تشكّل أحجار الأسود في الوسط طريقًا سميكًا يصل الأعلى بالأسفل. والسؤال الحاسم: كيف سيخترق الأبيض هذا السُّمك؟",
        "159": "الأسود 159 (F4) يدافع بثبات في الأسفل يسارًا. نقلة الأبيض التالية هي الأشهر في المباراة.",
        "160": "الأبيض 160 (H8) يقفز إلى ثغرة في سُمك الأسود: نقلة حادة بأهداف متعددة، ومنها يبدأ الأبيض اختراق وسط الأسود. انتشرت إشاعة بأن تلميذًا، لا شوساي، هو من وجدها، لكن ذلك لم يثبت قط.",
        "161": "الأسود 161 (J8) يردّ فورًا، لكن للأبيض أكثر من هدف.",
        "162": "الأبيض 162 (K12) ينتقل إلى الجزء العلوي من الوسط ويهدد روابط أحجار الأسود.",
        "172": "الأبيض 172 (F13) يصل أحجار الوسط بالأعلى يسارًا. شيئًا فشيئًا يتوقف سُمك الأسود في الوسط عن التحول إلى أرض.",
        "178": "الأبيض 178 (N9) يدخل منطقة الأسود يمين الوسط أيضًا.",
        "187": "بالنقلتين 187 (M6) و189 (L7) يردّ الأسود بأسر أحجار بيضاء. ومع ذلك كان الأبيض قد سبق إلى النقاط المهمة.",
        "198": "الأبيض 198 (E12) يأسر حجرًا. وتتصل أحجار الأبيض في الأعلى يسارًا أيضًا، فيتقدم الأبيض قليلًا إجمالًا.",
        "203": "الأسود 203 (B3). من هنا تبدأ النهاية: تُثبَّت الحدود على الحواف نقطة نقطة.",
        "224": "الأبيض 224 (T10) يأسر حجرًا. حتى على الحافة اليمنى لا يتنازل الأبيض عن نقطة واحدة.",
        "233": "الأسود 233 (L13) يأسر حجرين أبيضين. يواصل الأسود المطاردة حتى النهاية.",
        "252": "تنتهي المباراة بعد 252 نقلة: فاز الأبيض بنقطتين. بلا كومي كان للأسود أفضلية صغيرة بالبدء أولًا، لكن الميجين ثبت حتى النهاية. ومع ذلك أحدثت افتتاحية غو سيغن (3-3 والنجم والتنغن) ضجة كبيرة وبشّرت بعصر جديد في الافتتاحيات."
      } },
    "century1956": { "t": "مباراة القرن", "w": "دونالد بيرن", "b": "بوبي فيشر", "ev": "بطولة كأس روزنوالد الثالثة (بطولة روزنوالد التذكارية)", "d": "1956", "pl": "الولايات المتحدة (نيويورك)", "lead": "بوبي فيشر، ابن الثالثة عشرة، يهزم دونالد بيرن، أحد أقوى أساتذة أمريكا. في النقلة 17 يترك فيشر وزيره يُؤخذ مجانًا، ثم يستعيد القطع واحدة تلو الأخرى، وفي النهاية تطارد قطعه الصغيرة الملك الأبيض. وأصبح فيشر لاحقًا بطلًا للعالم.",
      c: {
        "0": "نيويورك، 17 أكتوبر 1956، مباراة في بطولة. يلعب بالأسود فيشر ابن الثالثة عشرة، وبالأبيض بيرن، أحد أفضل اللاعبين الأمريكيين.",
        "1": "يبدأ الأبيض بحصان.",
        "4": "يلعب فيشر g6 ليضع الفيل على القطر الطويل.",
        "8": "يبيّت الأسود: الملك في أمان أولًا.",
        "10": "يلعب الأسود d5. يبدأ الصراع على الوسط.",
        "15": "بـ e4 صار للأبيض بيدقان متجاوران في الوسط.",
        "17": "الرخ إلى d1 يدعم بيدق d4. لم يبيّت الأبيض بعد.",
        "18": "يذهب الحصان إلى b6 ويطارد الوزير في c4.",
        "20": "الفيل إلى g4 يضغط على حصان f3.",
        "21": "الفيل الأبيض إلى g5. ما زال الملك الأبيض في الوسط.",
        "22": "الحصان إلى a4! يقفز إلى مربع يمكن أخذه فيه. الفكرة: إذا ابتعد حصان c3 فقد بيدق e4 حاميه.",
        "23": "لا يأخذ الأبيض الحصان، وينقل الوزير إلى a3.",
        "26": "يأخذ الحصان الأسود بيدق e4. وسط الأبيض ينهار.",
        "27": "يأخذ الفيل الأبيض بيدق e7 ويهاجم في الوقت نفسه الوزير الأسود ورخ f8.",
        "28": "الوزير إلى b6! يترك الأسود رخ f8. يعتمد فيشر على أن الملك الأبيض ما زال في الوسط.",
        "29": "لا يأخذ الأبيض الرخ، بل يُخرج الفيل.",
        "30": "يأخذ الحصان بيدق c3 ويهاجم رخ d1.",
        "31": "الفيل إلى c5 يهاجم الوزير الأسود في b6.",
        "32": "كش من الرخ على العمود e!",
        "33": "الملك إلى f1. الآن لن يستطيع الأبيض التبييت أبدًا.",
        "34": "الفيل إلى e6! أشهر نقلة في المباراة: يترك الأسود وزيره يُؤخذ مجانًا. وفي المقابل لديه خطة لاستعادة القطع واحدة تلو الأخرى.",
        "35": "يأخذ الأبيض الوزير الأسود.",
        "36": "الفيل إلى c4، كش. يبدأ الهجوم المضاد للأسود.",
        "38": "يكشّ الحصان من e2.",
        "40": "حين يعود الملك إلى f1 يتحرّك الحصان فيكشف كشًّا من فيل c4. وفي طريقه يلتقط الحصان بيدق d4.",
        "44": "يعود الحصان إلى c3، كش مكشوف آخر، ويهاجم الآن رخ d1. إعطاء الكش مرة بعد مرة مع جمع القطع يُسمّى \"الطاحونة\".",
        "46": "يستردّ الأسود الفيل. وما زال حصان c3 يهاجم رخ d1.",
        "50": "يأخذ الحصان رخ d1. الآن استعاد الأسود أكثر من الوزير وصار متقدّمًا بوضوح.",
        "52": "يأخذ الرخ بيدق a2 أيضًا.",
        "56": "يبادل الأسود الرخاخ. كلما قلّت القطع كان ذلك أفضل لمن يملك أكثر.",
        "57": "الوزير الأبيض يكشّ.",
        "58": "يسدّ الأسود بالفيل.",
        "64": "b5. يبدأ البيدق الأسود بالتقدّم.",
        "68": "يذهب الملك إلى g7 ويحرّر فيل f8.",
        "70": "الآن تطارد القطع السوداء الملك الأبيض. كش بفيل.",
        "72": "يكشّ الحصان في g3.",
        "74": "كش بالفيل الآخر.",
        "76": "الفيل إلى b3، كش.",
        "78": "يكشّ الحصان في e2.",
        "80": "يكشّ الحصان في c3. يُطارَد الملك هنا وهناك.",
        "82": "الرخ إلى c2: كش مات! الرخ والفيلان والحصان يعملون معًا. أظهر فتى في الثالثة عشرة كيف تلعب قطع كثيرة كفريق واحد."
      } },
    "oshiro1849": { "t": "أول مباراة قلعة لشوساكو", "w": "هونينبو شوساكو", "b": "ياسوي سانتشي التاسع", "ev": "مباراة القلعة (المباراة السنوية في قلعة إيدو)", "d": "1849", "pl": "اليابان (إيدو)", "lead": "كانت مباريات القلعة المناسبة السنوية الكبرى التي يلعب فيها لاعبو بيوت الغو الرسمية في قلعة الشوغون. شارك شوساكو، وهو في العشرين، لأول مرة في ذلك العام وفاز بالأسود بفارق 11 نقطة، فبدأ سجلًا مثاليًا من 19 فوزًا في 19 مباراة قلعة.",
      c: {
        "0": "1849. في العام السابق اختير شوساكو وريثًا لبيت هونينبو، وها هو يلعب أول مباراة قلعة له. يُقال إن هذه المباريات كانت تُلعب غالبًا مسبقًا في مكان آخر ثم يُعاد رصّها في القلعة فقط.",
        "1": "الأسود 1 على نقطة 3-4 في الأعلى يمينًا (R16). كعادته يبدأ شوساكو بنقطة 3-4 هادئة.",
        "4": "الأبيض 4 (C15) يقترب من حجر الأسود في D17 في الأعلى يسارًا. تبدأ هناك معركة مبكرة.",
        "5": "الأسود 5 (C11) يضغط على الحجر الأبيض المقترب من الأسفل بكماشة، كي لا يستقر الأبيض بسهولة على اليسار.",
        "12": "الأبيض 12 (C17). يأخذ الأبيض الزاوية العليا اليسرى، ويحصل الأسود على أحجار متجهة نحو الخارج: مقايضة عادلة.",
        "13": "الأسود 13 (J17) يستفيد من الأحجار الخارجية ويمتد على الجانب العلوي.",
        "15": "الأسود 15 (C5) يأخذ آخر زاوية فارغة في الأسفل يسارًا. صارت الزوايا الأربع كلها مشغولة.",
        "16": "الأبيض 16 (E4) يقترب فورًا من ذلك الحجر الأسود، فتبدأ معركة في الأسفل يسارًا أيضًا.",
        "19": "الأسود 19 (D2) يؤمّن الزاوية السفلى اليسرى بثبات: اختيار متين على طريقة شوساكو.",
        "23": "الأسود 23 (E5) يخرج بين أحجار الأبيض ويقوّي مجموعته في الأسفل يسارًا.",
        "29": "الأسود 29 (F11) يقوّي أحجاره على اليسار ويتطلع في الوقت نفسه إلى الوسط.",
        "30": "الأبيض 30 (H4) يمتد في الأسفل، يضغط على مجموعة الأسود اليسرى ويبني منطقته.",
        "31": "الأسود 31 (O3) يقترب من زاوية الأبيض السفلى اليمنى.",
        "33": "الأسود 33 (R3) يلتصق بحجر الأبيض في الزاوية. من هنا يبني الأسود في الخارج، بينما يزحف الأبيض على الخط الثالث عند الحافة.",
        "43": "الأسود 43 (Q8). يمتد الآن جدار أسود سميك على الجانب الأيمن. أخذ الأبيض أرض الزاوية والحافة، وكسب الأسود قوة خارجية.",
        "44": "الأبيض 44 (L17) يدخل بين أحجار الأسود على الجانب العلوي كي لا تكبر منطقة الأسود كثيرًا.",
        "50": "الأبيض 50 (R18) يتسلل تحت زاوية الأسود العليا اليمنى مستهدفًا أرض الزاوية.",
        "51": "الأسود 51 (P13). مستندًا إلى الجدار، يرسم الأسود منطقة كبيرة من الجانب الأيمن نحو الوسط.",
        "52": "الأبيض 52 (D10) يقتحم بين أحجار الأسود على الجانب الأيسر، فتتشابك الأحجار هناك.",
        "63": "الأسود 63 (B10) يلعب على الحافة اليسرى كي لا تجد أحجار الأبيض قاعدة هناك.",
        "65": "الأسود 65 (G3) يدخل أيضًا منطقة الأبيض في الأسفل ويقلّص أرضه.",
        "73": "الأسود 73 (K17) يقوّي أحجاره العليا ويضغط على حجر الأبيض من النقلة 44.",
        "76": "الأبيض 76 (P11) يقفز داخل منطقة الأسود على الجانب الأيمن. حياة هذا الحجر أو موته ستغيّر النتيجة كثيرًا.",
        "77": "الأسود 77 (Q11) يرد من جهة جداره ويدفع الأبيض نحو الوسط: دفاع هادئ يهاجم أيضًا، على طريقة شوساكو.",
        "80": "الأبيض 80 (N10) يهرب نحو الوسط محاولًا الإفلات من مطاردة الأسود.",
        "85": "الأسود 85 (N12) يواصل الهجوم مع توسيع أرضه في الأعلى واليمين. الكسب عبر الهجوم: لعب بارع.",
        "91": "الأسود 91 (J7) يلعب فوق أحجار الأبيض السفلية ويغطي منطقة الأبيض من جهة الوسط أيضًا.",
        "100": "الأبيض 100 (S17) يحاول شيئًا في الزاوية العليا اليمنى ليقلّص أرض الأسود.",
        "119": "الأسود 119 (R17) يدافع بثبات عن الزاوية العليا اليمنى ويصدّ محاولة الأبيض.",
        "122": "الأبيض 122 (G6) يلتف حول أحجار الأسود في الأسفل يسارًا من الخارج محاولًا قطعها عن وسط الأسود.",
        "131": "الأسود 131 (M5) يدقّ إسفينًا في منطقة الأبيض وسط الجانب السفلي.",
        "140": "الأبيض 140 (B4) يحاول شيئًا في زاوية الأسود السفلى اليسرى، فتبدأ معركة أسر متقاربة على الحافة اليسرى.",
        "156": "الأبيض 156 (A8) يأسر حجرين أسودين. تهدأ معركة الحافة اليسرى بعد أن أخذ كل طرف قليلًا.",
        "158": "الأبيض 158 (L10). ما زالت للأبيض أحجار في الوسط، ويحاول تقليص أرض الأسود هناك.",
        "162": "الأبيض 162 (O12) يأسر حجرًا أسود. ومع ذلك تبقى منطقة الأسود على اليمين كبيرة.",
        "172": "الأبيض 172 (K18). من هنا تبدأ النهاية، بدءًا بالحدود على الجانب العلوي.",
        "186": "الأبيض 186 (T16) يقتطع من أرض الأسود عند الحافة العليا اليمنى. في النهاية يلعب الطرفان أكبر النقاط أولًا.",
        "205": "الأسود 205 (Q18) يغلق الجزء الأيمن من الجانب العلوي ويثبّت أرضه هناك.",
        "223": "الأسود 223 (P10) يثبّت الحدود بين أرض الأسود على اليمين وأحجار الأبيض التي فرّت إلى الوسط.",
        "233": "الأسود 233 (Q9) يأسر حجرًا أبيض. صارت أرض الأسود على اليمين آمنة تقريبًا بالكامل.",
        "239": "الأسود 239 (A6) يأسر حجرًا فيظهر كو على الحافة اليسرى. يستمر الصراع على كل نقطة حتى النهاية.",
        "260": "الأبيض 260 (T6) يأسر حجرًا ويصنع كو آخر عند الحافة السفلى اليمنى. يستردّ الأسود بالنقلة 263 (T5).",
        "267": "تنتهي المباراة بعد 267 نقلة: فاز الأسود بفارق 11 نقطة. بلا مغامرات: هاجم شوساكو وترك أرضه تنمو بشكل طبيعي، فوز يشبهه تمامًا. وكانت الأولى من 19 انتصارًا متتاليًا في مباريات القلعة."
      } },
    "shilin": { "t": "مباراة «شيلين غوانغجي»", "w": "الأحمر (لم يُحفظ اسمه)", "b": "الأسود (لم يُحفظ اسمه)", "ev": "موسوعة الحياة اليومية «شيلين غوانغجي»: «مباراة فاز فيها من أعطى النقلة الأولى، بمدفعين من الجهة نفسها»", "d": "القرن الثالث عشر", "pl": "الصين (سونغ–يوان)", "lead": "هذا السجل مأخوذ من «شيلين غوانغجي»، وهي موسوعة للحياة اليومية جمعها تشن يوانجينغ في أواخر عهد سلالة سونغ وبدايات يوان. ويُقال إنه من أقدم سجلات الشيانغتشي الكاملة الباقية. إنها مباراة نموذجية يترك فيها اللاعب الأقوى النقلة الأولى لخصمه، وفي تسع نقلات فقط يحاصر الحصانُ الأسود العربةَ الحمراء.",
      c: {
        "0": "يزيد عمر هذا السجل على 700 عام، وهو من الزمن الواقع بين سلالتي سونغ ويوان. يرد في باب الألعاب من موسوعة «شيلين غوانغجي»، ويُقال إنه من أقدم مباريات الشيانغتشي الكاملة التي بقيت لنا. لم تُحفظ أسماء اللاعبين. يقول العنوان إن اللاعب الأقوى «أعطى النقلة الأولى» للأضعف، فهي درس يبيّن كيف يخسر الأحمر الذي يبدأ. الأحمر في الأسفل ويبدأ اللعب.",
        "1": "ينقل الأحمر المدفع الأيمن إلى العمود الأوسط. هذا هو «المدفع المركزي» الذي يصوّب مباشرة على الجنرال الأسود، وما زال من أقوى الافتتاحيات حتى اليوم. ونرى أنه كان يُلعب قبل 700 عام.",
        "2": "يردّ الأسود بمدفع إلى الوسط أيضًا، فيتواجه المدفعان. عندما يحرّك الطرفان المدفع من الجهة نفسها يُسمّى ذلك «مدفعين في اتجاه واحد». ومعركة المدفع ضد المدفع محبوبة منذ قرون.",
        "3": "يُخرج الأحمر حصانًا ليحمي الجندي الأوسط. هذا الجندي مهدَّد من المدفع الأسود ويحتاج إلى حارس. والحصان يستعد أيضًا للتقدّم.",
        "4": "يفعل الأسود الشيء نفسه ويحمي جنديه الأوسط بحصان. يبني الطرفان أولًا قاعدة متينة.",
        "5": "ينقل الأحمر العربة اليمنى خطوة إلى الجانب نحو عمود مفتوح. العربة أقوى قطعة على الرقعة، لذلك من الجيد تشغيلها مبكرًا.",
        "6": "يُخرج الأسود الحصان الآخر ويترك العربتين في البيت الآن. الخطة هي تقديم القطع أولًا. لكن العربة التي تخرج متأخرة قد يصعب استخدامها في الهجوم لاحقًا.",
        "7": "تعبر العربة الحمراء النهر دفعة واحدة وتدخل معسكر الأسود. تريد تهديد القطع السوداء، لكن بقية القطع الحمراء ما زالت في البيت، فالهجوم متسرّع قليلًا. كان يمكن أيضًا إخراج الحصان أو العربة اليسرى أولًا.",
        "8": "يقدّم الأسود جندي العمود 3 خطوة واحدة. بهذا يفتح طريقًا للحصان ليقفز إلى الأمام لاحقًا. يكاد الأسود يدعو العربة الحمراء إلى القدوم.",
        "9": "تأخذ العربة الحمراء جنديًا وتصوّب الآن على الحصان الأسود خلفه. كسب قطعة وتهديد أخرى يبدو رائعًا. لكن العربة تقدّمت بعيدًا جدًا ولا صديق حولها. والعربة الوحيدة في معسكر العدو يسهل مطاردتها.",
        "10": "يقفز الحصان الأسود إلى الأمام. يهرب من العربة ويقترب من معسكر الأحمر في الوقت نفسه: مهمتان بنقلة واحدة. سيكون هذا الحصان بطل المباراة.",
        "11": "يعيد الأحمر العربة خطوة إلى الوراء ليهاجم الحصان من الجانب. العربة تأخذ من بعيد، فلا يستطيع الحصان أن يرتاح. ومع ذلك لا تساعد هذه النقلة على إخراج قطع حمراء أخرى.",
        "12": "يتقدّم الحصان الأسود أكثر ويعبر النهر إلى معسكر الأحمر. وفي كل مرة يهرب فيها من العربة يقترب أكثر من الجنرال الأحمر.",
        "13": "يقدّم الأحمر جنديًا ليفتح الطريق لحصانه. الفكرة إخراجه ومبادلته بالحصان الأسود. لكن هذا يمنح الأسود وقتًا ليتقدّم أكثر.",
        "14": "يرفع الأسود فيلًا ويهاجم العربة الحمراء. طرد عربة الخصم بقطعة دفاعية أمر فعّال جدًا. على الأحمر أن يحرّك العربة مرة أخرى، ويكسب الأسود نقلة إضافية.",
        "15": "تنزلق العربة الحمراء جانبًا وتأخذ جنديًا آخر. صار الأحمر متقدّمًا بجنديين، لكن هذه هي النقلة الخاسرة. فالعربة الآن بعيدة عن جنرالها ولا تستطيع العودة للدفاع. كان على الأحمر أن يحتاط من الحصان، كأن يعيد العربة إلى البيت.",
        "16": "يتوغّل الحصان الأسود أعمق ويهاجم العربة الحمراء. وهناك المزيد: إذا قفز مرة أخرى فسيكشّ الجنرال الأحمر ويهاجم في الوقت نفسه العربة في زاوية الأحمر. حصان واحد صنع تهديدين معًا.",
        "17": "يطارد الأحمر الحصان بالعربة. لكن لم يعد من الممكن إيقافه. لم يبقَ حول الجنرال الأحمر أحد يساعد.",
        "18": "يقفز الحصان مع كِش! وهو يهاجم أيضًا العربة في زاوية الأحمر، فإذا تنحّى الجنرال ضاعت العربة. تسع نقلات فقط، لكن المباراة تعلّمنا ماذا يحدث لعربة تندفع وحدها، ولماذا يجب أن تقاتل القطع معًا. قبل 700 عام كان اللاعبون يفكّرون في الأشياء نفسها على الرقعة نفسها."
      } },
    "qima13": { "t": "التضحية بالحصان في ثلاث عشرة نقلة («جوتشونغمي»)", "w": "الأحمر (لم يُحفظ اسمه)", "b": "الأسود (لم يُحفظ اسمه)", "ev": "«جوتشونغمي»، الجزء الأول، المباراة الأولى", "d": "1632 (سنة النشر)", "pl": "الصين (مينغ)", "lead": "هذه أول مباراة في كتاب «جوتشونغمي» («السرّ في داخل اليوسفية»)، وهو كتاب شيانغتشي نشره تشو جينتشن من عهد سلالة مينغ سنة 1632. يترك الأحمر للأسود أن يأخذ حصانًا مجانًا، ويندفع في الهجوم أثناء ذلك، ويُميت في ثلاث عشرة نقلة. وما زالت محبوبة بعد نحو 400 عام باسم «التضحية بالحصان في ثلاث عشرة نقلة».",
      c: {
        "0": "هذه المباراة الأولى في كتاب «جوتشونغمي» الذي طُبع سنة 1632 قرب نهاية سلالة مينغ. ويُعدّ مع «كتيّب زهر البرقوق» اللاحق أحد الكتابين الكلاسيكيين الكبيرين في الشيانغتشي. ليست مباراة حقيقية بل نموذج كُتب لتعليم خطة، لذلك لا توجد أسماء لاعبين. الأحمر في الأسفل ويبدأ، وينتهي كل شيء في ثلاث عشرة نقلة فقط.",
        "1": "ينقل الأحمر المدفع الأيمن إلى الوسط. هذا هو «المدفع المركزي» الذي يحدّق مباشرة في الجنرال الأسود. واشتهر كتاب «جوتشونغمي» بدراسة طرق الهجوم بهذه الافتتاحية.",
        "2": "ينقل الأسود أيضًا المدفع من الجهة نفسها إلى الوسط. هذان «مدفعان في اتجاه واحد» يتصادمان وجهًا لوجه. كل طرف يصوّب على الجندي الأوسط للآخر.",
        "3": "يُخرج الأحمر حصانًا ليحمي الجندي الأوسط. يحمي الجندي الذي يصوّب عليه المدفع الأسود، ويبدأ الحصان العمل.",
        "4": "يحمي الأسود أيضًا الجندي الأوسط بحصان. حتى الآن الشكلان متماثلان.",
        "5": "يقدّم الأحمر العربة اليمنى خطوة واحدة فقط. الآن تستطيع في النقلة التالية أن تجري جانبًا. العربة التي تتحرك جانبيًا هكذا تُسمّى «العربة الأفقية»، وتستطيع الانتقال بسرعة إلى أي جناح.",
        "6": "يحرّك الأسود العربة خطوة إلى الجانب لتتمكن من الصعود مستقيمة. هذه «عربة مستقيمة». العربة الأفقية ضد العربة المستقيمة: طريقتان مختلفتان لاستخدام العربة وجهًا لوجه.",
        "7": "تنتقل العربة الأفقية الحمراء إلى عمود على اليسار. هذا العمود يمرّ بجوار المستشار الأسود مباشرة، حيث الدفاع ضعيف. يستعد الأحمر للاقتحام من هنا.",
        "8": "تعبر العربة المستقيمة السوداء النهر وتتوغّل في معسكر الأحمر. يريد الأسود أن يردّ بهجوم من عنده. لكنها نقلة تستعجل الهجوم قبل الدفاع.",
        "9": "تندفع العربة الحمراء إلى عمق معسكر الأسود. تقف على «عين» الفيل، وهي النقطة التي يجب أن يمرّ بها الفيل، فلا يستطيع الفيل الأسود التحرك. وبجوار المستشار صارت قريبة جدًا من الجنرال.",
        "10": "يُخرج الأسود الحصان الآخر نحو الحافة. ومن أهدافه منع العربة الحمراء من التسلّل من الجانب.",
        "11": "ها هي التضحية بالحصان! يرفع الأحمر العربة الأخرى خطوة واحدة. يترك هذا الحصانَ في الزاوية اليسرى بلا حارس، فيستطيع المدفع الأسود أخذه مجانًا. لكن الأحمر يكسب مقابل حصان واحد الوقتَ لإدخال العربتين في الهجوم بسرعة.",
        "12": "يأخذ المدفع الأسود الحصان الأحمر. يبدو أن الأسود كسب قطعة. لكن هذا المدفع صار بعيدًا عن بيته ولا يستطيع المساعدة في الدفاع. ويُقال إن الأفضل هنا كان رفع مستشار لتقوية الدفاع بدل الأخذ.",
        "13": "يتقدّم المدفع الأحمر. مستخدمًا المدفع الأسود في الوسط «حاجزًا» يقفز فوقه، يصوّب الآن على الحصان الأسود خلفه. المدفع قطعة عجيبة تأخذ بالقفز فوق قطعة واحدة بالضبط.",
        "14": "يتراجع الأسود بالحصان ليهرب. لكن هذا الحصان كان القطعة المهمة التي تحمي الجندي الأوسط. وبهروبه انفتحت ثغرة في الوسط. كان لدى الأسود دفاعات أخرى، لكن هذا كان أسوأ اختيار.",
        "15": "يأخذ المدفع الأحمر الجندي الأوسط — كِش! بعد ذهاب الحصان الأسود صار الوسط مفتوحًا تمامًا. ومن هنا ينطلق هجوم الأحمر بسرعة.",
        "16": "يرفع الأسود مستشارًا ليسدّ ما أمام الجنرال. هذه هي الطريقة الجيدة الوحيدة لصدّ الكِش.",
        "17": "تصل العربة الحمراء الثانية إلى العمود نفسه. عربتان مصطفّتان في عمود واحد قوة هائلة. الخطة هي اقتحام عمق معسكر الأسود.",
        "18": "يتنحّى الجنرال الأسود جانبًا. وإلا لحدّقت فيه العربتان الحمراوان من العمود نفسه.",
        "19": "تأخذ العربة الحمراء الأمامية المستشار الأسود — كِش! سيأخذها المستشار الآخر فورًا، لكن هذا جزء من الخطة. يضحّي الأحمر بعربة ليحطّم حرس الجنرال الأسود. يا لها من نقلة جريئة!",
        "20": "يأخذ الأسود العربة بالمستشار. في عدد القطع صار الأسود متقدّمًا كثيرًا. لكن بيت الجنرال صار أكثر فراغًا.",
        "21": "تنتقل آخر عربة حمراء إلى عمود الجنرال — كِش مرة أخرى. لم يبقَ للجنرال الأسود تقريبًا أي قطعة تحميه.",
        "22": "يضع الأسود مدفعًا أمام الجنرال ليسدّ الكِش. وضع قطعة في الوسط هكذا يُسمّى الاعتراض.",
        "23": "تأخذ العربة الحمراء ذلك المدفع — كِش مجددًا. تواصل العربة أخذ القطع السوداء وهي تحاصر الجنرال.",
        "24": "لا يستطيع الجنرال الأسود إلا العودة إلى الوسط. كل النقاط الأخرى تحت سيطرة القطع الحمراء.",
        "25": "أخيرًا يقف المدفع الأحمر في الوسط: مدفعان في عمود واحد — كِش. المدفع الأمامي هو الحاجز والخلفي يضرب الجنرال: إنه مات «المدفع المزدوج». لا مكان يذهب إليه الجنرال الأسود، ويفوز الأحمر. بالتخلّي عن حصان واحد فقط فاز الأحمر في ثلاث عشرة نقلة. منذ 400 عام وهذه المباراة تعلّمنا أن الوقت ونشاط القطع قد يكونان أهم من عددها."
      } }
  }
};
